-- ==============================================================================
-- SCHEMA CYBERPHONE PRO - SQL SETUP (IDEMPOTENT & SECURE)
-- ==============================================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Enumerações (Tipos)
DO $$ BEGIN
    CREATE TYPE user_type AS ENUM ('STANDARD', 'CREATOR');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE post_type AS ENUM ('TEXT', 'IMAGE', 'LIVE', 'REEL');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE product_type AS ENUM ('PHYSICAL', 'DIGITAL_COURSE', 'DIGITAL_EBOOK', 'DIGITAL_OTHER');
EXCEPTION WHEN duplicate_object THEN null; END $$;

DO $$ BEGIN
    CREATE TYPE order_status AS ENUM ('WAITLIST', 'SHIPPING', 'DELIVERED');
EXCEPTION WHEN duplicate_object THEN null; END $$;

-- 4. Tabela de Perfis
CREATE TABLE IF NOT EXISTS profiles (
    id UUID REFERENCES auth.users(id) ON DELETE CASCADE PRIMARY KEY,
    email TEXT UNIQUE,
    first_name TEXT,
    last_name TEXT,
    user_type TEXT DEFAULT 'STANDARD', 
    phone TEXT UNIQUE,
    document_id TEXT UNIQUE,
    birth_date BIGINT,
    profile_picture TEXT,
    balance FLOAT DEFAULT 0,
    credentials TEXT,
    bio TEXT,
    is_admin BOOLEAN DEFAULT FALSE,
    is_verified BOOLEAN DEFAULT FALSE,
    is_suspended BOOLEAN DEFAULT FALSE,
    is_premium BOOLEAN DEFAULT FALSE,
    premium_expiry BIGINT,
    followers TEXT[] DEFAULT '{}',
    followed_users TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Tabela de Lojas
CREATE TABLE IF NOT EXISTS stores (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    professor_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    name TEXT,
    description TEXT,
    brand_color TEXT DEFAULT '#2563eb',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. Tabela de Produtos
CREATE TABLE IF NOT EXISTS products (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    store_id UUID REFERENCES stores(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    price FLOAT NOT NULL,
    image_urls TEXT[],
    affiliate_commission_rate FLOAT DEFAULT 0, 
    type TEXT DEFAULT 'DIGITAL_COURSE', 
    average_rating FLOAT DEFAULT 5.0,
    rating_count INT DEFAULT 0,
    digital_content_url TEXT,
    is_dropshipping BOOLEAN DEFAULT FALSE,
    external_provider_id TEXT,
    original_price FLOAT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 7. Tabela de Posts
CREATE TABLE IF NOT EXISTS posts (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    type TEXT DEFAULT 'TEXT', 
    content TEXT,
    image_url TEXT,
    timestamp BIGINT, 
    likes TEXT[] DEFAULT '{}',
    shares TEXT[] DEFAULT '{}',
    saves TEXT[] DEFAULT '{}',
    is_pinned BOOLEAN DEFAULT FALSE,
    is_boosted BOOLEAN DEFAULT FALSE,
    boost_expires BIGINT,
    live_data JSONB, 
    reel_data JSONB, 
    font_family TEXT,
    text_color TEXT,
    background_color TEXT,
    font_size TEXT,
    indicated_user_ids TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 8. Tabela de Comentários
CREATE TABLE IF NOT EXISTS comments (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    post_id UUID REFERENCES posts(id) ON DELETE CASCADE,
    user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    text TEXT NOT NULL,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 9. Tabela de Vendas
CREATE TABLE IF NOT EXISTS sales (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    product_id UUID REFERENCES products(id) ON DELETE SET NULL,
    buyer_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
    affiliate_user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
    store_id UUID REFERENCES stores(id) ON DELETE SET NULL,
    commission_earned FLOAT DEFAULT 0,
    sale_amount FLOAT NOT NULL,
    status TEXT DEFAULT 'WAITLIST', 
    shipping_address JSONB, 
    is_rated BOOLEAN DEFAULT FALSE,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 10. Tabela de Anúncios
CREATE TABLE IF NOT EXISTS ads (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    professor_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    title TEXT,
    description TEXT,
    target_audience TEXT,
    budget FLOAT DEFAULT 0,
    is_active BOOLEAN DEFAULT TRUE,
    image_url TEXT,
    link_url TEXT,
    cta_text TEXT,
    min_age INT,
    max_age INT,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 11. Tabela de Eventos
CREATE TABLE IF NOT EXISTS events (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    creator_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    title TEXT,
    description TEXT,
    date_time BIGINT,
    end_date_time BIGINT,
    type TEXT DEFAULT 'ONLINE',
    location TEXT,
    image_url TEXT,
    is_public BOOLEAN DEFAULT TRUE,
    attendees TEXT[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 12. Tabela de Notificações
CREATE TABLE IF NOT EXISTS notifications (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    recipient_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    actor_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    type TEXT, 
    post_id UUID REFERENCES posts(id) ON DELETE CASCADE,
    sale_id UUID REFERENCES sales(id) ON DELETE CASCADE,
    is_read BOOLEAN DEFAULT FALSE,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 13. Tabelas de Chat
CREATE TABLE IF NOT EXISTS conversations (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    participants TEXT[], 
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS messages (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    conversation_id UUID REFERENCES conversations(id) ON DELETE CASCADE,
    sender_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    receiver_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    text TEXT,
    image_url TEXT,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 14. Logs e Reportes
CREATE TABLE IF NOT EXISTS reports (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    reporter_id UUID REFERENCES profiles(id),
    target_id TEXT,
    target_type TEXT,
    reason TEXT,
    details TEXT,
    status TEXT DEFAULT 'OPEN',
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS logs (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    admin_id UUID REFERENCES profiles(id),
    action TEXT,
    target_id TEXT,
    details TEXT,
    timestamp BIGINT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 15. Audio Tracks
CREATE TABLE IF NOT EXISTS audio_tracks (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    title TEXT,
    artist TEXT,
    url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 16. Stories
CREATE TABLE IF NOT EXISTS stories (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    image_url TEXT,
    text TEXT,
    background_color TEXT,
    text_color TEXT,
    font_family TEXT,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==============================================================================
-- STORAGE CONFIGURATION
-- ==============================================================================

INSERT INTO storage.buckets (id, name, public) 
VALUES ('cyber-files', 'cyber-files', true)
ON CONFLICT (id) DO NOTHING;

-- Políticas de Storage (Remover antigas antes de criar para evitar erro)
DROP POLICY IF EXISTS "Public Access" ON storage.objects;
CREATE POLICY "Public Access" ON storage.objects FOR SELECT USING (bucket_id = 'cyber-files');

DROP POLICY IF EXISTS "Authenticated Upload" ON storage.objects;
CREATE POLICY "Authenticated Upload" ON storage.objects FOR INSERT WITH CHECK (
  bucket_id = 'cyber-files' AND auth.role() = 'authenticated'
);

DROP POLICY IF EXISTS "Owner Update" ON storage.objects;
CREATE POLICY "Owner Update" ON storage.objects FOR UPDATE USING (bucket_id = 'cyber-files' AND auth.uid() = owner);

DROP POLICY IF EXISTS "Owner Delete" ON storage.objects;
CREATE POLICY "Owner Delete" ON storage.objects FOR DELETE USING (bucket_id = 'cyber-files' AND auth.uid() = owner);

-- ==============================================================================
-- LOGICA ADMIN E TRIGGERS
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
  is_super_admin BOOLEAN;
  default_pic TEXT;
BEGIN
  is_super_admin := (new.email = 'alfaajmc@gmail.com');
  default_pic := 'data:image/svg+xml,%3Csvg xmlns=''http://www.w3.org/2000/svg'' viewBox=''0 0 24 24'' fill=''%23cbd5e1''%3E%3Cpath fill-rule=''evenodd'' d=''M7.5 6a4.5 4.5 0 119 0 4.5 4.5 0 01-9 0zM3.751 20.105a8.25 8.25 0 0116.498 0 .75.75 0 01-.437.695A18.683 18.683 0 0112 22.5c-2.786 0-5.433-.608-7.812-1.7a.75.75 0 01-.437-.695z'' clip-rule=''evenodd'' /%3E%3C/svg%3E';

  INSERT INTO public.profiles (id, email, first_name, last_name, user_type, profile_picture, document_id, phone, bio, credentials, birth_date, is_admin, is_verified, is_premium, balance)
  VALUES (
    new.id,
    new.email,
    COALESCE(new.raw_user_meta_data->>'firstName', 'Novo'),
    COALESCE(new.raw_user_meta_data->>'lastName', 'Usuário'),
    CASE WHEN is_super_admin THEN 'CREATOR' ELSE COALESCE(new.raw_user_meta_data->>'userType', 'STANDARD') END,
    COALESCE(new.raw_user_meta_data->>'profilePicture', default_pic),
    COALESCE(new.raw_user_meta_data->>'documentId', ''),
    COALESCE(new.raw_user_meta_data->>'phone', ''),
    CASE WHEN is_super_admin THEN 'CEO & Root Admin - Conta Mestra' ELSE COALESCE(new.raw_user_meta_data->>'bio', '') END,
    CASE WHEN is_super_admin THEN 'Super Admin' ELSE COALESCE(new.raw_user_meta_data->>'credentials', '') END,
    COALESCE((new.raw_user_meta_data->>'birthDate')::BIGINT, 0),
    is_super_admin,
    is_super_admin,
    is_super_admin,
    CASE WHEN is_super_admin THEN 1000000 ELSE 0 END
  )
  ON CONFLICT (id) DO NOTHING; -- Evita erro se o perfil já foi criado manualmente

  IF (new.raw_user_meta_data->>'userType' = 'CREATOR' OR is_super_admin) THEN
    INSERT INTO public.stores (professor_id, name, description, brand_color)
    VALUES (new.id, 'Loja de ' || COALESCE(new.raw_user_meta_data->>'firstName', 'Admin'), 'Bem-vindo à minha loja!', '#2563eb')
    ON CONFLICT DO NOTHING; -- Stores não tem unique constraint simples além do ID, mas evita insert duplo lógico
  END IF;

  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

-- Atualiza usuário mestre se já existir (Idempotente)
UPDATE public.profiles SET is_admin = TRUE, is_verified = TRUE, is_premium = TRUE, user_type = 'CREATOR', balance = 1000000, credentials = 'Super Admin Root' WHERE email = 'alfaajmc@gmail.com';

-- ==============================================================================
-- ROW LEVEL SECURITY (RLS) - POLÍTICAS SEGURAS E REUTILIZÁVEIS
-- ==============================================================================

-- 1. Profiles
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Profiles View" ON profiles;
CREATE POLICY "Profiles View" ON profiles FOR SELECT USING (true);

DROP POLICY IF EXISTS "Profiles Update" ON profiles;
CREATE POLICY "Profiles Update" ON profiles FOR UPDATE USING (auth.uid() = id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

DROP POLICY IF EXISTS "Profiles Delete" ON profiles;
CREATE POLICY "Profiles Delete" ON profiles FOR DELETE USING (auth.uid() = id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 2. Posts
ALTER TABLE posts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Posts View" ON posts;
CREATE POLICY "Posts View" ON posts FOR SELECT USING (true);

DROP POLICY IF EXISTS "Posts Insert" ON posts;
CREATE POLICY "Posts Insert" ON posts FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Posts Update" ON posts;
CREATE POLICY "Posts Update" ON posts FOR UPDATE USING (auth.uid() = user_id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

DROP POLICY IF EXISTS "Posts Delete" ON posts;
CREATE POLICY "Posts Delete" ON posts FOR DELETE USING (auth.uid() = user_id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 3. Stores
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Stores View" ON stores;
CREATE POLICY "Stores View" ON stores FOR SELECT USING (true);

DROP POLICY IF EXISTS "Stores Insert" ON stores;
CREATE POLICY "Stores Insert" ON stores FOR INSERT WITH CHECK (auth.uid() = professor_id);

DROP POLICY IF EXISTS "Stores Update" ON stores;
CREATE POLICY "Stores Update" ON stores FOR UPDATE USING (auth.uid() = professor_id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 4. Products
ALTER TABLE products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Products View" ON products;
CREATE POLICY "Products View" ON products FOR SELECT USING (true);

DROP POLICY IF EXISTS "Products Manage" ON products;
CREATE POLICY "Products Manage" ON products FOR ALL USING (
  EXISTS (SELECT 1 FROM stores WHERE stores.id = products.store_id AND stores.professor_id = auth.uid()) OR (SELECT is_admin FROM profiles WHERE id = auth.uid())
);

-- 5. Sales
ALTER TABLE sales ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Sales View" ON sales;
CREATE POLICY "Sales View" ON sales FOR SELECT USING (
  auth.uid() = buyer_id OR 
  auth.uid() = affiliate_user_id OR 
  EXISTS (SELECT 1 FROM stores WHERE stores.id = sales.store_id AND stores.professor_id = auth.uid()) OR
  (SELECT is_admin FROM profiles WHERE id = auth.uid())
);

DROP POLICY IF EXISTS "Sales Insert" ON sales;
CREATE POLICY "Sales Insert" ON sales FOR INSERT WITH CHECK (auth.uid() = buyer_id);

DROP POLICY IF EXISTS "Sales Update" ON sales;
CREATE POLICY "Sales Update" ON sales FOR UPDATE USING (
  EXISTS (SELECT 1 FROM stores WHERE stores.id = sales.store_id AND stores.professor_id = auth.uid()) OR
  (SELECT is_admin FROM profiles WHERE id = auth.uid())
);

-- 6. Ads
ALTER TABLE ads ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Ads View" ON ads;
CREATE POLICY "Ads View" ON ads FOR SELECT USING (true);

DROP POLICY IF EXISTS "Ads Manage" ON ads;
CREATE POLICY "Ads Manage" ON ads FOR ALL USING (auth.uid() = professor_id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 7. Comments
ALTER TABLE comments ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Comments View" ON comments;
CREATE POLICY "Comments View" ON comments FOR SELECT USING (true);

DROP POLICY IF EXISTS "Comments Insert" ON comments;
CREATE POLICY "Comments Insert" ON comments FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Comments Delete" ON comments;
CREATE POLICY "Comments Delete" ON comments FOR DELETE USING (auth.uid() = user_id OR (SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 8. Notifications
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Notif View" ON notifications;
CREATE POLICY "Notif View" ON notifications FOR SELECT USING (auth.uid() = recipient_id);

DROP POLICY IF EXISTS "Notif Insert" ON notifications;
CREATE POLICY "Notif Insert" ON notifications FOR INSERT WITH CHECK (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Notif Update" ON notifications;
CREATE POLICY "Notif Update" ON notifications FOR UPDATE USING (auth.uid() = recipient_id);

-- 9. Chat (Mensagens e Conversas)
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Conv View" ON conversations;
CREATE POLICY "Conv View" ON conversations FOR SELECT USING (auth.uid()::text = ANY(participants));

DROP POLICY IF EXISTS "Conv Insert" ON conversations;
CREATE POLICY "Conv Insert" ON conversations FOR INSERT WITH CHECK (auth.uid()::text = ANY(participants));

ALTER TABLE messages ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Msg View" ON messages;
CREATE POLICY "Msg View" ON messages FOR SELECT USING (auth.uid() = sender_id OR auth.uid() = receiver_id);

DROP POLICY IF EXISTS "Msg Insert" ON messages;
CREATE POLICY "Msg Insert" ON messages FOR INSERT WITH CHECK (auth.uid() = sender_id);

-- 10. Reports & Logs (Admin Only for View)
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Reports Insert" ON reports;
CREATE POLICY "Reports Insert" ON reports FOR INSERT WITH CHECK (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Reports View" ON reports;
CREATE POLICY "Reports View" ON reports FOR SELECT USING ((SELECT is_admin FROM profiles WHERE id = auth.uid()));

DROP POLICY IF EXISTS "Reports Update" ON reports;
CREATE POLICY "Reports Update" ON reports FOR UPDATE USING ((SELECT is_admin FROM profiles WHERE id = auth.uid()));

ALTER TABLE logs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Logs View" ON logs;
CREATE POLICY "Logs View" ON logs FOR SELECT USING ((SELECT is_admin FROM profiles WHERE id = auth.uid()));

DROP POLICY IF EXISTS "Logs Insert" ON logs;
CREATE POLICY "Logs Insert" ON logs FOR INSERT WITH CHECK ((SELECT is_admin FROM profiles WHERE id = auth.uid()));

-- 11. Events
ALTER TABLE events ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Events View" ON events;
CREATE POLICY "Events View" ON events FOR SELECT USING (true);

DROP POLICY IF EXISTS "Events Insert" ON events;
CREATE POLICY "Events Insert" ON events FOR INSERT WITH CHECK (auth.uid() = creator_id);

DROP POLICY IF EXISTS "Events Update" ON events;
CREATE POLICY "Events Update" ON events FOR UPDATE USING (auth.uid() = creator_id);

-- 12. Stories
ALTER TABLE stories ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Stories View" ON stories;
CREATE POLICY "Stories View" ON stories FOR SELECT USING (true);

DROP POLICY IF EXISTS "Stories Manage" ON stories;
CREATE POLICY "Stories Manage" ON stories FOR ALL USING (auth.uid() = user_id);

