-- Função segura para dar like (bypassa RLS de update)
CREATE OR REPLACE FUNCTION toggle_like(post_uuid UUID, user_uuid UUID)
RETURNS VOID AS $$
DECLARE
  likes_arr TEXT[];
  user_text TEXT := user_uuid::TEXT;
BEGIN
  SELECT likes INTO likes_arr FROM posts WHERE id = post_uuid;

  IF likes_arr IS NULL THEN
    likes_arr := '{}';
  END IF;

  IF likes_arr @> ARRAY[user_text] THEN
    -- Remove like
    UPDATE posts SET likes = array_remove(likes, user_text) WHERE id = post_uuid;
  ELSE
    -- Add like
    UPDATE posts SET likes = array_append(likes, user_text) WHERE id = post_uuid;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

