// Função atualizada para usar RPC (Remote Procedure Call)
// Isso contorna a limitação da RLS que impede update direto na tabela posts por terceiros.
export const updatePostLikes = async (postId: string, userId: string) => {
  const { error } = await supabase.rpc('toggle_like', { 
    post_uuid: postId, 
    user_uuid: userId 
  });

  if (!error) {
    // Notificar apenas se foi um like (verificação otimista)
    const { data: post } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
    if (post && post.likes && post.likes.includes(userId)) {
        createNotification({
            type: NotificationType.LIKE,
            recipientId: post.user_id,
            actorId: userId,
            postId: postId,
            timestamp: Date.now()
        });
    }
  } else {
    console.error("Erro ao atualizar like:", error);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (post) {
    let saves = post.saves || [];
    if (saves.includes(userId)) saves = saves.filter((id: string) => id !== userId);
    else saves.push(userId);
    await supabase.from('posts').update({ saves }).eq('id', postId);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('shares').eq('id', postId).single();
  if (post) {
    let shares = post.shares || [];
    if (!shares.includes(userId)) {
      shares.push(userId);
      await supabase.from('posts').update({ shares }).eq('id', postId);
    }
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  // Garantir que o ID é um UUID válido para o banco de dados
  const commentId = crypto.randomUUID();

  const { error } = await supabase.from('comments').insert({
    id: commentId,
    post_id: postId,
    user_id: comment.userId,
    text: comment.text,
    timestamp: comment.timestamp
  });

  if(!error) {
      const { data: post } = await supabase.from('posts').select('user_id').eq('id', postId).single();
      if(post) {
          createNotification({
              type: NotificationType.COMMENT,
              recipientId: post.user_id,
              actorId: comment.userId,
              postId: postId,
              timestamp: Date.now()
          });
      }
  } else {
      console.error("Erro ao comentar:", error);
  }
};

