export const indicatePostToUser = async (pId: string, from: string, to: string) => {
  const { data: post } = await supabase.from('posts').select('indicated_user_ids').eq('id', pId).single();
  if (post) {
    const indicated = post.indicated_user_ids || [];
    if (!indicated.includes(to)) {
      indicated.push(to);
      await supabase.from('posts').update({ indicated_user_ids: indicated }).eq('id', pId);
      createNotification({
          type: NotificationType.INDICATION,
          recipientId: to,
          actorId: from,
          postId: pId,
          timestamp: Date.now()
      });
      return true;
    }
  }
  return false;
};

