export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}`;
  const { data, error } = await supabase.storage.from('cyber-files').upload(fileName, file);

  if (error) throw new Error(error.message);

  const { data: publicUrl } = supabase.storage.from('cyber-files').getPublicUrl(fileName);
  return publicUrl.publicUrl;
};

