const mapProfileToUser = (profile: any): User => ({
  id: profile.id,
  email: profile.email || '',
  firstName: profile.first_name || '',
  lastName: profile.last_name || '',
  userType: (profile.user_type as UserType) || UserType.STANDARD,
  phone: profile.phone || '',
  documentId: profile.document_id || '',
  birthDate: profile.birth_date || 0,
  profilePicture: profile.profile_picture || DEFAULT_PROFILE_PIC,
  balance: profile.balance || 0,
  credentials: profile.credentials,
  bio: profile.bio,
  storeId: undefined, // Será preenchido se encontrar a loja
  isAdmin: profile.is_admin || false,
  isVerified: profile.is_verified || false,
  isSuspended: profile.is_suspended || false,
  isPremium: profile.is_premium || false,
  premiumExpiry: profile.premium_expiry,
  followers: profile.followers || [],
  followedUsers: profile.followed_users || [],
  verificationFileUrl: undefined
});

const mapPostToDomain = (p: any): Post => ({
  id: p.id,
  userId: p.user_id,
  authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Usuário Desconhecido',
  authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: p.type,
  content: p.content,
  imageUrl: p.image_url,
  timestamp: p.timestamp,
  likes: p.likes || [],
  shares: p.shares || [],
  saves: p.saves || [],
  isPinned: p.is_pinned,
  isBoosted: p.is_boosted,
  boostExpires: p.boost_expires,
  liveStream: p.live_data,
  reel: p.reel_data,
  fontFamily: p.font_family,
  textColor: p.text_color,
  backgroundColor: p.background_color,
  fontSize: p.font_size,
  indicatedUserIds: p.indicated_user_ids || [],
  comments: p.comments ? p.comments.map((c: any) => ({
    id: c.id,
    userId: c.user_id,
    userName: c.profiles ? `${c.profiles.first_name} ${c.profiles.last_name}` : 'Anônimo',
    profilePic: c.profiles?.profile_picture,
    text: c.text,
    timestamp: c.timestamp
  })) : []
});

const mapStoreToDomain = (s: any): Store => ({
  id: s.id,
  professorId: s.professor_id,
  name: s.name,
  description: s.description,
  brandColor: s.brand_color,
  productIds: []
});

const mapProductToDomain = (p: any): Product => ({
  id: p.id,
  storeId: p.store_id,
  name: p.name,
  description: p.description,
  price: p.price,
  imageUrls: p.image_urls || [],
  affiliateCommissionRate: p.affiliate_commission_rate,
  type: p.type,
  averageRating: p.average_rating,
  ratingCount: p.rating_count,
  digitalContentUrl: p.digital_content_url,
  isDropshipping: p.is_dropshipping,
  externalProviderId: p.external_provider_id,
  originalPrice: p.original_price,
  ratings: []
});

const mapSaleToDomain = (s: any): AffiliateSale => ({
  id: s.id,
  productId: s.product_id,
  buyerId: s.buyer_id,
  affiliateUserId: s.affiliate_user_id,
  storeId: s.store_id,
  commissionEarned: s.commission_earned,
  saleAmount: s.sale_amount,
