export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`
      *,
      profiles (first_name, last_name, profile_picture),
      comments (
        id, user_id, text, timestamp,
        profiles (first_name, last_name, profile_picture)
      )
    `)
    .order('timestamp', { ascending: false });

  if (error) {
    console.error("Erro ao buscar posts:", error);
    return [];
  }
  return data.map(mapPostToDomain);
};

export const addPost = async (post: Post) => {
  const { error } = await supabase.from('posts').insert({
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    timestamp: post.timestamp,
    is_pinned: post.isPinned,
    live_data: post.liveStream,
    reel_data: post.reel,
    font_family: post.fontFamily,
    text_color: post.textColor,
    background_color: post.backgroundColor,
    font_size: post.fontSize
  });

  if (error) throw new Error(error.message);

  const user = await findUserById(post.userId);
  if (user && user.followers) {
      user.followers.forEach(fid => {
          createNotification({
              type: NotificationType.NEW_POST,
              recipientId: fid,
              actorId: post.userId,
              postId: post.id,
              timestamp: Date.now()
          });
      });
  }
};

export const updatePost = async (post: Post) => {
  await supabase.from('posts').update({
    content: post.content,
    likes: post.likes,
    shares: post.shares,
    saves: post.saves,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires,
    indicated_user_ids: post.indicatedUserIds
  }).eq('id', post.id);
};

export const deletePost = async (postId: string) => {
  await supabase.from('posts').delete().eq('id', postId);
};

export const adminDeletePost = deletePost;

// Função atualizada para usar RPC (Remote Procedure Call)
// Isso contorna a limitação da RLS que impede update direto na tabela posts por terceiros.
export const updatePostLikes = async (postId: string, userId: string) => {
  const { error } = await supabase.rpc('toggle_like', { 
    post_uuid: postId, 
    user_uuid: userId 
  });

  if (!error) {
    // Notificar apenas se foi um like (verificação otimista)
    const { data: post } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
    if (post && post.likes && post.likes.includes(userId)) {
        createNotification({
            type: NotificationType.LIKE,
            recipientId: post.user_id,
            actorId: userId,
            postId: postId,
            timestamp: Date.now()
        });
    }
  } else {
    console.error("Erro ao atualizar like:", error);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (post) {
    let saves = post.saves || [];
    if (saves.includes(userId)) saves = saves.filter((id: string) => id !== userId);
    else saves.push(userId);
    await supabase.from('posts').update({ saves }).eq('id', postId);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('shares').eq('id', postId).single();
  if (post) {
    let shares = post.shares || [];
    if (!shares.includes(userId)) {
      shares.push(userId);
      await supabase.from('posts').update({ shares }).eq('id', postId);
    }
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  // Garantir que o ID é um UUID válido para o banco de dados
  const commentId = crypto.randomUUID();

  const { error } = await supabase.from('comments').insert({
    id: commentId,
    post_id: postId,
    user_id: comment.userId,
    text: comment.text,
    timestamp: comment.timestamp
  });

  if(!error) {
      const { data: post } = await supabase.from('posts').select('user_id').eq('id', postId).single();
      if(post) {
          createNotification({
              type: NotificationType.COMMENT,
              recipientId: post.user_id,
              actorId: comment.userId,
              postId: postId,
              timestamp: Date.now()
          });
      }
  } else {
      console.error("Erro ao comentar:", error);
  }
};

export const pinPost = async (postId: string, userId: string) => {
  await supabase.from('posts').update({ is_pinned: false }).eq('user_id', userId);
  await supabase.from('posts').update({ is_pinned: true }).eq('id', postId);
  return true;
};

export const unpinPost = async (postId: string, userId: string) => {
  await supabase.from('posts').update({ is_pinned: false }).eq('id', postId);
  return true;
};

export const indicatePostToUser = async (pId: string, from: string, to: string) => {
  const { data: post } = await supabase.from('posts').select('indicated_user_ids').eq('id', pId).single();
  if (post) {
    const indicated = post.indicated_user_ids || [];
    if (!indicated.includes(to)) {
      indicated.push(to);
      await supabase.from('posts').update({ indicated_user_ids: indicated }).eq('id', pId);
      createNotification({
          type: NotificationType.INDICATION,
          recipientId: to,
          actorId: from,
          postId: pId,
          timestamp: Date.now()
      });
      return true;
    }
  }
  return false;
};

export const boostPost = async (pId: string, uId: string, budget: number, days: number) => {
  const success = await updateUserBalance(uId, -budget);
  if (success) {
    await supabase.from('posts').update({
        is_boosted: true,
        boost_expires: Date.now() + (days * 86400000)
    }).eq('id', pId);
    return true;
  }
  return false;
};

