export const getChats = async (): Promise<ChatConversation[]> => {
  const { data } = await supabase.from('conversations').select(`
    id, participants,
    messages (id, sender_id, receiver_id, text, image_url, timestamp)
  `);

  return data?.map((c: any) => ({
      id: c.id,
      participants: c.participants,
      messages: c.messages.map((m: any) => ({
          id: m.id,
          senderId: m.sender_id,
          receiverId: m.receiver_id,
          text: m.text,
          imageUrl: m.image_url,
          timestamp: m.timestamp
      })).sort((a: Message, b: Message) => a.timestamp - b.timestamp)
  })) || [];
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const allChats = await getChats();
  const existing = allChats.find(c => c.participants.includes(u1) && c.participants.includes(u2));

  if (existing) return existing;

  const newId = generateUUID();
  const { error } = await supabase.from('conversations').insert({
      id: newId,
      participants: [u1, u2]
  });

  if(error) throw new Error(error.message);

  return { id: newId, participants: [u1, u2], messages: [] };
};

export const sendMessage = async (chatId: string, msg: Message) => {
  await supabase.from('messages').insert({
      id: msg.id,
      conversation_id: chatId,
      sender_id: msg.senderId,
      receiver_id: msg.receiverId,
      text: msg.text,
      image_url: msg.imageUrl,
      timestamp: msg.timestamp
  });

  createNotification({
      type: NotificationType.MESSAGE,
      recipientId: msg.receiverId,
      actorId: msg.senderId,
      timestamp: Date.now()
  });
};

