export const getStories = async (): Promise<Story[]> => {
  const { data } = await supabase.from('stories').select('*, profiles(first_name, last_name, profile_picture)');
  const storiesMap: Record<string, Story> = {};

  data?.forEach((s: any) => {
      if(!storiesMap[s.user_id]) {
          storiesMap[s.user_id] = {
              userId: s.user_id,
              userName: `${s.profiles.first_name} ${s.profiles.last_name}`,
              userProfilePic: s.profiles.profile_picture,
              items: []
          };
      }
      storiesMap[s.user_id].items.push({
          id: s.id,
          imageUrl: s.image_url,
          text: s.text,
          backgroundColor: s.background_color,
          textColor: s.text_color,
          fontFamily: s.font_family,
          timestamp: new Date(s.created_at).getTime()
      });
  });

  return Object.values(storiesMap);
};

