// Nova função de verificação de documentos robusta
export const verifyProfessionalDocument = async (base64File: string): Promise<{ isValid: boolean; reason: string; professionDetected?: string }> => {
  try {
    const ai = await getGeminiClient();

    // 1. Extração Dinâmica do MIME Type e dos Dados
    // Formato esperado: data:application/pdf;base64,JVBERi... ou data:image/png;base64,iVBOR...
    const matches = base64File.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+);base64,(.+)$/);

    let mimeType = 'application/pdf'; // Fallback padrão
    let cleanBase64 = base64File;

    if (matches && matches.length === 3) {
      mimeType = matches[1];
      cleanBase64 = matches[2];
    } else {
      // Tenta limpar caso venha com prefixo mas o regex falhe ou venha sem prefixo
      if (base64File.includes(',')) {
         const parts = base64File.split(',');
         cleanBase64 = parts[1];
         // Tenta adivinhar pelo header se possível, ou mantém PDF
         if (parts[0].includes('image')) mimeType = 'image/jpeg';
      }
    }

    console.log(`Auditoria IA iniciada. Tipo detectado: ${mimeType}`);

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', // Modelo Multimodal superior para análise de documentos/texto
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: cleanBase64
            }
          },
          {
            text: `Aja como um auditor de conformidade rigoroso (Compliance Officer). 
            Analise a imagem ou documento PDF anexo.

            Sua missão é validar se este é um documento de identificação profissional ou acadêmico LEGÍTIMO (Ex: Diploma, Certificado, Carteira da OAB, CRM, CREA, Identidade Funcional, etc).

            Critérios de Aprovação:
            1. O documento deve ser legível.
            2. Deve conter nome de uma pessoa.
            3. Deve parecer um documento oficial (selos, assinaturas, logotipos de instituições).
            4. NÃO aprove selfies, fotos de paisagens, recibos aleatórios ou documentos em branco.

            Responda APENAS com o JSON abaixo:`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isValid: { type: Type.BOOLEAN, description: "True apenas se for um documento profissional/acadêmico válido e legível." },
            reason: { type: Type.STRING, description: "Explicação curta e direta do motivo da aprovação ou rejeição (em português)." },
            professionDetected: { type: Type.STRING, description: "A profissão ou título identificado no documento (Ex: Médico, Engenheiro, Advogado). Se não identificar, deixe em branco." }
          },
          required: ["isValid", "reason"]
        }
      }
    });

    if (!response.text) {
      throw new Error("Sem resposta da IA");
    }

    const result = JSON.parse(response.text);

    return {
      isValid: result.isValid || false,
      reason: result.reason || "Não foi possível analisar o documento.",
      professionDetected: result.professionDetected
    };

  } catch (error: any) {
    console.error("Erro na verificação de documento com IA:", error);

    // Tratamento de erros específicos
    let msg = "Erro técnico na análise inteligente.";
    if (error.message?.includes('400')) msg = "O formato do arquivo não é suportado ou está corrompido.";
    if (error.message?.includes('500')) msg = "O serviço de auditoria está instável. Tente novamente.";

    return { isValid: false, reason: msg };
  }
};

