  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<string | null>(null);
  const [verificationFileName, setVerificationFileName] = useState<string | null>(null);

  const profilePicInputRef = useRef<HTMLInputElement>(null);
  const docInputRef = useRef<HTMLInputElement>(null);

  const filteredCountries = useMemo(() => {
    return COUNTRIES.filter(c => 
      c.name.toLowerCase().includes(countrySearch.toLowerCase()) || 
      c.ddi.includes(countrySearch)
    );
  }, [countrySearch]);

  const inputClasses = "w-full p-3.5 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (selectedCountry.ddi === '+55') {
      if (value.length > 11) value = value.slice(0, 11);
      if (value.length > 10) {
        value = value.replace(/^(\d{2})(\d{5})(\d{4}).*/, '($1) $2-$3');
      } else if (value.length > 6) {
        value = value.replace(/^(\d{2})(\d{4})(\d{0,4}).*/, '($1) $2-$3');
      } else if (value.length > 2) {
        value = value.replace(/^(\d{2})(\d{0,5}).*/, '($1) $2');
      } else if (value.length > 0) {
        value = value.replace(/^(\d*)/, '($1');
      }
    } else {
      if (value.length > 14) value = value.slice(0, 14);
    }
    setPhone(value);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf' && !file.type.startsWith('image/')) {
        setError('Formato inválido. Envie PDF, JPG ou PNG.');
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        setError('O arquivo é muito grande. Máximo 5MB.');
        return;
      }

      setVerificationFileName(file.name);
      const reader = new FileReader();
      reader.onloadend = () => {
        setVerificationFile(reader.result as string);
        setError('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !phone || !documentId || !birthDate || !password) {
      setError('Preencha todos os campos obrigatórios.');
      return;
    }

    if (userType === UserType.CREATOR && !verificationFile) {
      setError('Para conta profissional, o envio do documento é obrigatório.');
      return;
    }

    setLoading(true);
    setLoadingMessage('Criando conta...');

    try {
      if (userType === UserType.CREATOR && verificationFile) {
        setLoadingMessage('A IA está auditando seu documento...');
        const analysis = await verifyProfessionalDocument(verificationFile);

        if (!analysis.isValid) {
          throw new Error(`Documento Recusado: ${analysis.reason}`);
        }

        if (analysis.professionDetected && !credentials) {
           setCredentials(analysis.professionDetected);
        }
      }

      const fullPhone = `${selectedCountry.ddi} ${phone}`;
      const newUser = await registerUser({
        userType, firstName, lastName, email, phone: fullPhone, documentId,
        birthDate: new Date(birthDate).getTime(), password, profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined, verificationFileUrl: verificationFile || undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Erro desconhecido no cadastro.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email || !password) {
      setError('Email e senha obrigatórios.');
      return;
    }
    setLoading(true);
    setLoadingMessage('Entrando...');
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais inválidas.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  // 1. Solicita o reset COM VERIFICAÇÃO DE CADASTRO
  const handleRecoveryRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!email) {
      setError('Digite seu e-mail para recuperar.');
      return;
    }
    setLoading(true);
    setLoadingMessage('Verificando cadastro...');
    try {
      // Tenta recuperar. Se o e-mail não existir, o serviço lança um erro.
      await recoverPassword(email); 
      setRecoveryStep('sent');
    } catch (err: any) {
      // Verifica se o erro é de "não encontrado"
      if (err.message && (err.message.includes('não encontrado') || err.message.includes('not found'))) {
        setLoadingMessage('E-mail não cadastrado. Redirecionando para Cadastro...');
        // Pequeno delay para o usuário ler a mensagem
        await new Promise(resolve => setTimeout(resolve, 2000));

        // Troca para o modo de Registro
        setIsRecovery(false);
        setIsRegister(true);
        // Limpa o erro para não aparecer no formulário de cadastro
        setError('');
        // O estado 'email' já está preenchido, então o campo no cadastro já virá com o valor.
      } else {
        setError(err.message || 'Erro ao enviar recuperação.');
      }
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  // 2. Processa o reset (nova senha)
  const handlePasswordReset = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!newPassword || !confirmNewPassword) {
      setError('Preencha os campos de senha.');
      return;
    }
    if (newPassword.length < 6) {
      setError('A senha deve ter pelo menos 6 caracteres.');
      return;
    }
    if (newPassword !== confirmNewPassword) {
      setError('As senhas não coincidem.');
      return;
    }

    setLoading(true);
    setLoadingMessage('Atualizando credenciais...');
    try {
      await resetUserPassword(email, newPassword);
      setRecoveryStep('success');
    } catch (err: any) {
      setError('Não foi possível redefinir a senha.');
    } finally {
      setLoading(false);
      setLoadingMessage('');
    }
  };

  const resetRecoveryState = () => {
    setIsRecovery(false);
    setRecoveryStep('request');
    setError('');
    // Não limpa o e-mail caso venha do fluxo de login
    setNewPassword('');
    setConfirmNewPassword('');
  };

  const openRecovery = () => {
    setRecoveryStep('request');
    setError('');
    setNewPassword('');
    setConfirmNewPassword('');
    setIsRecovery(true);
  };

  if (isRecovery) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
        <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10">

           {recoveryStep === 'request' && (
             <>
               <button onClick={resetRecoveryState} className="mb-6 flex items-center text-gray-400 hover:text-blue-600 font-bold text-xs uppercase tracking-widest gap-2 transition-colors">
                  <ArrowLeftIcon className="h-4 w-4" /> Voltar
               </button>

               <div className="mb-8 flex flex-col items-center">
                  <div className="bg-blue-50 dark:bg-blue-900/10 p-4 rounded-full mb-4">
                     <ShieldCheckIcon className="h-10 w-10 text-blue-600" />
                  </div>
                  <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Recuperar Acesso</h2>
                  <p className="text-center text-gray-400 text-xs font-medium mt-2">Informe seu e-mail. Se não tiver conta, vamos te cadastrar.</p>
               </div>

               {error && <div className="bg-red-50 dark:bg-red-900/20 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest">{error}</div>}

               <form onSubmit={handleRecoveryRequest} className="space-y-6">
                  <div className="relative">
                     <EnvelopeIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                     <input type="email" placeholder="Seu e-mail cadastrado" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses + " pl-12"} />
                  </div>
                  <button 
                    type="submit" 
                    disabled={loading} 
                    className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-blue-600 text-white disabled:opacity-50"
                  >
                    {loading ? (
                      <>
                        <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                        <span>{loadingMessage || 'Verificando...'}</span>
                      </>
                    ) : 'Verificar E-mail'}
                  </button>
               </form>
             </>
           )}

           {recoveryStep === 'sent' && (
             <div className="text-center animate-fade-in">
               <div className="bg-green-50 dark:bg-green-900/10 p-6 rounded-full w-24 h-24 mx-auto mb-6 flex items-center justify-center">
                  <PaperAirplaneIcon className="h-10 w-10 text-green-600 -rotate-45 ml-1 mt-1" />
               </div>
               <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter mb-4">E-mail Enviado!</h2>
               <p className="text-gray-500 font-medium text-sm mb-8">
                 Enviamos um link seguro para <strong>{email}</strong>. Acesse sua caixa de entrada para criar uma nova senha.
               </p>

               <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-2xl border border-dashed border-gray-200 dark:border-white/10">
                 <p className="text-[10px] font-black uppercase text-gray-400 mb-3">Simulação de Desenvolvimento</p>
                 <button 
                   onClick={() => setRecoveryStep('reset')}
                   className="w-full py-3 bg-gray-200 dark:bg-white/10 text-gray-700 dark:text-white rounded-xl font-bold text-xs hover:bg-gray-300 dark:hover:bg-white/20 transition-all"
                 >
                   [Dev] Simular Clique no Link
                 </button>
               </div>

               <button onClick={resetRecoveryState} className="mt-8 text-[10px] font-black uppercase text-blue-600 hover:underline tracking-widest">
                 Voltar ao início
               </button>
             </div>
           )}

           {recoveryStep === 'reset' && (
             <div className="animate-fade-in">
               <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter text-center mb-2">Nova Senha</h2>
               <p className="text-center text-gray-400 text-xs font-medium mb-8">Crie uma senha forte para proteger sua conta.</p>

               {error && <div className="bg-red-50 dark:bg-red-900/20 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest">{error}</div>}

               <form onSubmit={handlePasswordReset} className="space-y-6">
                  <div className="relative">
                     <LockClosedIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                     <input 
                       type="password" 
                       placeholder="Nova Senha" 
                       value={newPassword} 
                       onChange={e => setNewPassword(e.target.value)} 
                       className={inputClasses + " pl-12"} 
                     />
                  </div>
                  <div className="relative">
                     <LockClosedIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                     <input 
                       type="password" 
                       placeholder="Confirmar Nova Senha" 
                       value={confirmNewPassword} 
                       onChange={e => setConfirmNewPassword(e.target.value)} 
                       className={inputClasses + " pl-12"} 
                     />
                  </div>
                  <button 
                    type="submit" 
                    disabled={loading} 
                    className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-blue-600 text-white disabled:opacity-50"
                  >
                    {loading ? 'Atualizando...' : 'Redefinir Senha'}
                  </button>
               </form>
             </div>
           )}

           {recoveryStep === 'success' && (
             <div className="text-center animate-fade-in">
               <div className="bg-green-100 dark:bg-green-900/20 p-6 rounded-full w-24 h-24 mx-auto mb-6 flex items-center justify-center">
                  <CheckCircleIcon className="h-12 w-12 text-green-600" />
               </div>
               <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter mb-4">Senha Atualizada!</h2>
               <p className="text-gray-500 font-medium text-sm mb-8">
                 Sua senha foi alterada com sucesso. Você já pode acessar sua conta com as novas credenciais.
               </p>
               <button 
                 onClick={resetRecoveryState}
                 className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all bg-blue-600 text-white hover:bg-blue-700"
               >
                 Voltar para Login
               </button>
             </div>
           )}

        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4 font-sans">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10 relative overflow-visible">

        <div className="mb-6 flex flex-col items-center">
          <Logo size="lg" className="mb-1" />
          <p className="text-center text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em] opacity-80">
            {isRegister ? 'Ecossistema Digital' : 'Bem-vindo ao CyBerPhone'}
          </p>
        </div>

        {error && (
          <div className="bg-red-50 dark:bg-red-900/20 border border-red-100 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 text-center uppercase tracking-widest leading-tight flex items-center justify-center gap-2">
            <ExclamationTriangleIcon className="h-5 w-5 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {isRegister && (
          <div className="flex bg-gray-50 dark:bg-white/5 p-1 rounded-2xl mb-6">
            <button type="button" onClick={() => setUserType(UserType.STANDARD)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.STANDARD ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400'}`}>Normal</button>
            <button type="button" onClick={() => setUserType(UserType.CREATOR)} className={`flex-1 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${userType === UserType.CREATOR ? 'bg-purple-600 text-white shadow-lg' : 'text-gray-400'}`}>Profissional</button>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="flex flex-col items-center mb-4">
              <div onClick={() => profilePicInputRef.current?.click()} className="relative group cursor-pointer">
                <div className="w-20 h-20 rounded-[1.8rem] overflow-hidden border-4 border-gray-50 dark:border-white/10 shadow-xl transition-all group-hover:scale-105 group-hover:border-blue-500">
                  <img src={profilePicBase64} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <CameraIcon className="h-6 w-6 text-white" />
                  </div>
                </div>
                <div className="absolute -bottom-1 -right-1 bg-blue-600 text-white p-1.5 rounded-lg shadow-lg border-2 border-white dark:border-darkcard">
                  <PlusIcon className="h-2.5 w-2.5 stroke-[4]" />
                </div>
                <input type="file" ref={profilePicInputRef} onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => setProfilePicBase64(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} accept="image/*" className="hidden" />
              </div>
              <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest mt-2">Identidade Visual</p>
            </div>
          )}

          {isRegister && (
            <>
              <div className="grid grid-cols-2 gap-2.5">
                <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
                <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Data de Nascimento</label>
                <div className="relative">
                  <CalendarDaysIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className={inputClasses + " pl-10"} />
                </div>
              </div>
            </>
          )}

          <input type="email" placeholder="E-mail de acesso" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4">
               <div className="relative">
                  <div className="flex bg-gray-50 dark:bg-white/5 rounded-2xl border-2 border-transparent focus-within:border-blue-500 transition-all shadow-inner overflow-visible">
                     <button 
                       type="button" 
                       onClick={() => setShowCountryPicker(!showCountryPicker)}
                       className="flex items-center gap-2 px-4 border-r border-gray-200 dark:border-white/10 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors shrink-0"
                     >
                        <span className="text-xl">{selectedCountry.flag}</span>
                        <span className="text-xs font-black dark:text-white">{selectedCountry.ddi}</span>
                        <ChevronDownIcon className={`h-3 w-3 text-gray-400 transition-transform ${showCountryPicker ? 'rotate-180' : ''}`} />
                     </button>
                     <input type="tel" placeholder="Telefone" value={phone} onChange={handlePhoneChange} className="w-full p-3.5 bg-transparent dark:text-white outline-none font-bold text-sm" />
                  </div>
                  {showCountryPicker && (
                    <div className="absolute top-full left-0 mt-2 w-72 bg-white dark:bg-[#1a1e26] rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-gray-100 dark:border-white/10 z-[100] flex flex-col overflow-hidden animate-fade-in">
                       <div className="p-3 border-b dark:border-white/10 bg-gray-50 dark:bg-white/5">
                          <div className="relative">
                             <MagnifyingGlassIcon className="h-4 w-4 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                             <input 
                               type="text" 
                               autoFocus
                               placeholder="Buscar país ou DDI..." 
                               value={countrySearch}
                               onChange={e => setCountrySearch(e.target.value)}
                               className="w-full pl-9 pr-4 py-2 bg-white dark:bg-[#0d1117] rounded-xl outline-none font-bold text-[10px] dark:text-white"
                             />
                          </div>
                       </div>
                       <div className="max-h-64 overflow-y-auto custom-scrollbar">
                          {filteredCountries.map((c) => (
                            <button 
                              key={c.code} 
                              type="button" 
                              onClick={() => { setSelectedCountry(c); setShowCountryPicker(false); setPhone(''); setCountrySearch(''); }} 
                              className={`w-full flex items-center justify-between p-4 hover:bg-blue-50 dark:hover:bg-white/5 transition-colors text-left ${selectedCountry.code === c.code ? 'bg-blue-50/50 dark:bg-blue-600/10' : ''}`}
                            >
                               <div className="flex items-center gap-3">
                                  <span className="text-xl">{c.flag}</span>
                                  <span className="text-[10px] font-black uppercase dark:text-white truncate max-w-[120px]">{c.name}</span>
                               </div>
                               <span className="text-[10px] font-bold text-blue-600">{c.ddi}</span>
                            </button>
                          ))}
                          {filteredCountries.length === 0 && (
                            <div className="p-8 text-center text-[10px] font-black text-gray-400 uppercase">Nenhum país encontrado</div>
                          )}
                       </div>
                    </div>
                  )}
               </div>
               <input type="text" placeholder="Documento ID (CPF/BI)" value={documentId} onChange={e => setDocumentId(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          {isRegister && (
            <div className="space-y-4 animate-fade-in pt-1">
              {userType === UserType.CREATOR && (
                <>
                  <input type="text" placeholder="Área de Atuação / Cargo" value={credentials} onChange={e => setCredentials(e.target.value)} className={inputClasses} />

                  <div className="space-y-2">
                    <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3 flex items-center gap-1">
                       Comprovação de Habilitação <ShieldCheckIcon className="h-3 w-3 text-blue-500" />
                    </label>
                    <div 
                      onClick={() => docInputRef.current?.click()}
                      className={`w-full p-4 bg-gray-50 dark:bg-white/5 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${verificationFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                    >
                      {verificationFile ? (
                        <div className="flex items-center gap-3 w-full">
                           <DocumentCheckIcon className="h-6 w-6 text-green-600" />
                           <div className="flex-1 min-w-0">
                              <p className="text-[10px] font-black text-green-700 truncate">{verificationFileName}</p>
                              <p className="text-[8px] font-bold text-green-600/60 uppercase">Arquivo pronto para Auditoria IA</p>
                           </div>
                           <button 
                             type="button" 
                             onClick={(e) => { e.stopPropagation(); setVerificationFile(null); setVerificationFileName(null); }}
                             className="p-1.5 bg-white dark:bg-darkcard rounded-lg shadow-sm text-red-500 hover:bg-red-50"
                           >
                             <XMarkIcon className="h-4 w-4" />
                           </button>
                        </div>
                      ) : (
                        <>
                          <DocumentArrowUpIcon className="h-6 w-6 text-gray-400" />
                          <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest text-center">
                             Upload PDF ou Imagem<br/>do Documento Oficial
                          </span>
                        </>
                      )}
                      <input 
                        type="file" 
                        ref={docInputRef} 
                        onChange={handleFileChange} 
                        accept=".pdf,image/*" 
                        className="hidden" 
                      />
                    </div>
                  </div>
                </>
              )}
              <div className="space-y-1">
                <label className="text-[8px] font-black text-gray-400 uppercase tracking-widest ml-3">Sobre você</label>
                <textarea placeholder="Resumo do perfil..." value={bio} onChange={e => setBio(e.target.value)} className={inputClasses + " h-20 resize-none font-medium text-xs"} />
              </div>
            </div>
          )}

          <button 
            type="submit" 
            disabled={loading} 
            className="w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 bg-blue-600 text-white mt-4 disabled:opacity-50 disabled:bg-gray-400"
          >
            {loading ? (
              <>
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                <span>{loadingMessage || 'Processando...'}</span>
              </>
            ) : isRegister ? 'Confirmar Registro' : 'Acessar Rede'}
          </button>
        </form>

        {!isRegister && (
          <div className="mt-4 text-center">
             <button onClick={openRecovery} className="text-[9px] font-black text-gray-400 hover:text-blue-600 uppercase tracking-widest transition-colors">
               Esqueceu a senha?
             </button>
          </div>
        )}

        <button onClick={() => { setIsRegister(!isRegister); setError(''); }} className="w-full mt-6 text-[8px] font-black uppercase tracking-[0.3em] text-gray-400 hover:text-blue-600 transition-colors">
          {isRegister ? 'Já possui acesso? Entrar' : 'Novo integrante? Obter acesso'}
        </button>
      </div>
    </div>
  );
};

