// ==============================================================================
// AUTH & USERS
// ==============================================================================

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(CURRENT_USER_KEY, userId);
  else localStorage.removeItem(CURRENT_USER_KEY);
};

export const getCurrentUserId = (): string | null => {
  return localStorage.getItem(CURRENT_USER_KEY);
};

export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Usuário não encontrado.");

  const profile = await findUserById(data.user.id);
  if (!profile) throw new Error("Perfil de usuário incompleto.");

  return profile;
};

export const registerUser = async (userData: any): Promise<User> => {
  const { data, error } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
    options: {
      data: {
        firstName: userData.firstName,
        lastName: userData.lastName,
        userType: userData.userType,
        documentId: userData.documentId,
        phone: userData.phone,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture,
        credentials: userData.credentials,
        bio: userData.bio
      }
    }
  });

  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Erro ao criar conta.");

  await new Promise(r => setTimeout(r, 1500));

  const newUser = await findUserById(data.user.id);
  if (!newUser) throw new Error("Falha na criação do perfil. Tente logar.");

  return newUser;
};

export const recoverPassword = async (email: string): Promise<void> => {
  const { error } = await supabase.auth.resetPasswordForEmail(email, {
    redirectTo: window.location.origin + '/reset-password',
  });
  if (error) throw new Error(error.message);
};

export const resetUserPassword = async (email: string, newPass: string): Promise<void> => {
  const { error } = await supabase.auth.updateUser({ password: newPass });
  if (error) throw new Error(error.message);
};

export const updateUserPassword = async (password: string): Promise<void> => {
  const { error } = await supabase.auth.updateUser({ password });
  if (error) throw new Error(error.message);
};

export const getUsers = async (): Promise<User[]> => {
  const { data } = await supabase.from('profiles').select('*');
  return data?.map(mapProfileToUser) || [];
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
  if (error || !data) return undefined;

  const user = mapProfileToUser(data);
  if (user.userType === UserType.CREATOR) {
    const { data: storeData } = await supabase.from('stores').select('id').eq('professor_id', userId).single();
    if (storeData) user.storeId = storeData.id;
  }
  return user;
};

export const updateUser = async (updatedUser: User) => {
  const { error } = await supabase.from('profiles').update({
    first_name: updatedUser.firstName,
    last_name: updatedUser.lastName,
    bio: updatedUser.bio,
    credentials: updatedUser.credentials,
    profile_picture: updatedUser.profilePicture,
    phone: updatedUser.phone,
  }).eq('id', updatedUser.id);

  if (error) throw new Error(error.message);
};

export const deleteUser = async (userId: string) => {
  await supabase.from('profiles').delete().eq('id', userId);
};

export const adminUpdateUser = async (user: User) => {
  await supabase.from('profiles').update({
    is_verified: user.isVerified,
    is_suspended: user.isSuspended,
    balance: user.balance
  }).eq('id', user.id);
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const { data: user } = await supabase.from('profiles').select('balance').eq('id', userId).single();
  if (user) {
    const newBalance = (user.balance || 0) + amount;
    await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId);
    return true;
  }
  return false;
};

export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const { data: currentUser } = await supabase.from('profiles').select('followed_users').eq('id', currentUserId).single();
  const { data: targetUser } = await supabase.from('profiles').select('followers').eq('id', userIdToFollow).single();

  if (!currentUser || !targetUser) return;

  let newFollowed = currentUser.followed_users || [];
  let newFollowers = targetUser.followers || [];

  if (newFollowed.includes(userIdToFollow)) {
    newFollowed = newFollowed.filter((id: string) => id !== userIdToFollow);
    newFollowers = newFollowers.filter((id: string) => id !== currentUserId);
  } else {
    newFollowed.push(userIdToFollow);
    newFollowers.push(currentUserId);
    createNotification({
        type: NotificationType.NEW_FOLLOWER,
        recipientId: userIdToFollow,
        actorId: currentUserId,
        timestamp: Date.now()
    });
  }

  await supabase.from('profiles').update({ followed_users: newFollowed }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: newFollowers }).eq('id', userIdToFollow);
};

