export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`
      *,
      profiles (first_name, last_name, profile_picture),
      comments (
        id, user_id, text, timestamp,
        profiles (first_name, last_name, profile_picture)
      )
    `)
    .order('timestamp', { ascending: false });

  if (error) {
    console.error("Erro ao buscar posts:", error);
    return [];
  }
  return data.map(mapPostToDomain);
};

export const addPost = async (post: Post) => {
  const { error } = await supabase.from('posts').insert({
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    timestamp: post.timestamp,
    is_pinned: post.isPinned,
    live_data: post.liveStream,
    reel_data: post.reel,
    font_family: post.fontFamily,
    text_color: post.textColor,
    background_color: post.backgroundColor,
    font_size: post.fontSize
  });

  if (error) throw new Error(error.message);

  const user = await findUserById(post.userId);
  if (user && user.followers) {
      user.followers.forEach(fid => {
          createNotification({
              type: NotificationType.NEW_POST,
              recipientId: fid,
              actorId: post.userId,
              postId: post.id,
              timestamp: Date.now()
          });
      });
  }
};

export const updatePost = async (post: Post) => {
  await supabase.from('posts').update({
    content: post.content,
    likes: post.likes,
    shares: post.shares,
    saves: post.saves,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires,
    indicated_user_ids: post.indicatedUserIds
  }).eq('id', post.id);
};

export const deletePost = async (postId: string) => {
  await supabase.from('posts').delete().eq('id', postId);
