// Função atualizada para usar RPC (Remote Procedure Call)
// Isso contorna a limitação da RLS que impede update direto na tabela posts por terceiros.
export const updatePostLikes = async (postId: string, userId: string) => {
  const { error } = await supabase.rpc('toggle_like', { 
    post_uuid: postId, 
    user_uuid: userId 
  });

  if (!error) {
    // Notificar apenas se foi um like (verificação otimista)
    const { data: post } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
    if (post && post.likes && post.likes.includes(userId)) {
        createNotification({
            type: NotificationType.LIKE,
            recipientId: post.user_id,
            actorId: userId,
            postId: postId,
            timestamp: Date.now()
        });
    }
  } else {
    console.error("Erro ao atualizar like:", error);
  }
};

