export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  try {
      for (const item of cartItems) {
        const product = await findProductById(item.productId);
        if (!product) continue;
        const store = await findStoreById(product.storeId);
        if (!store) continue;

        const itemTotal = product.price * item.quantity;
        const commissionEarned = affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0;

        const netRevenue = itemTotal - commissionEarned;
        await updateUserBalance(store.professorId, netRevenue);

        if (affiliateUserId && commissionEarned > 0) {
            await updateUserBalance(affiliateUserId, commissionEarned);
            createNotification({
                type: NotificationType.AFFILIATE_SALE,
                recipientId: affiliateUserId,
                actorId: buyerId,
                timestamp: Date.now()
            });
        }

        await supabase.from('sales').insert({
            id: generateUUID(),
            product_id: item.productId,
            buyer_id: buyerId,
            affiliate_user_id: affiliateUserId,
            store_id: product.storeId,
            commission_earned: commissionEarned,
            sale_amount: itemTotal,
            status: OrderStatus.WAITLIST,
            shipping_address: shippingAddress,
            timestamp: Date.now()
        });
      }
      clearCart();
      return true;
  } catch (e) {
      console.error(e);
      return false;
  }
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
  const { data: sale } = await supabase.from('sales').select('*').eq('id', saleId).single();
  if (!sale || sale.is_rated) return false;

  await supabase.from('sales').update({ is_rated: true }).eq('id', saleId);

  const { data: product } = await supabase.from('products').select('*').eq('id', sale.product_id).single();
  if(product) {
      const newCount = (product.rating_count || 0) + 1;
      const currentTotal = (product.average_rating || 5) * (product.rating_count || 0);
      const newAvg = (currentTotal + rating) / newCount;
      await supabase.from('products').update({ average_rating: newAvg, rating_count: newCount }).eq('id', sale.product_id);
  }
  return true;
};

