interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const [author, setAuthor] = useState<User | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const user = await findUserById(post.userId);
      setAuthor(user || null);
    };
    fetchAuthor();
  }, [post.userId]);

  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!post.imageUrl) return;

    try {
      const response = await fetch(post.imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cyberphone-midia-${post.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      window.open(post.imageUrl, '_blank');
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Aula de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {}
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleSendComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    const newComment: Comment = {
      id: generateUUID(),
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    };

    addPostComment(post.id, newComment);

    setCommentText('');
    onUpdate();

    setTimeout(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTo({
          top: scrollRef.current.scrollHeight,
          behavior: 'smooth'
        });
      }
    }, 100);
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const isGradient = hasBg && post.backgroundColor?.includes('gradient');

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/90 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-md">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[3rem] bg-white dark:bg-[#0a0c10] flex flex-col tablet:flex-row overflow-hidden relative shadow-2xl">

        {/* Mobile Header */}
        <div className="flex items-center justify-between px-4 md:hidden z-[101] bg-black/40 backdrop-blur-xl border-b border-white/10 h-16 shrink-0">
           <button onClick={onClose} className="p-2 text-white">
             <ArrowLeftIcon className="h-6 w-6" />
           </button>
           <span className="font-black text-[10px] uppercase text-white tracking-[0.3em]">Detalhes da Aula</span>
           <div className="w-10"></div>
        </div>

        {/* Desktop Close Button */}
        <button 
          onClick={onClose} 
          className="hidden md:flex absolute top-6 left-6 z-[101] p-4 bg-black/50 hover:bg-black/80 text-white rounded-full transition-all backdrop-blur-lg shadow-2xl border border-white/10 active:scale-90"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        {/* Image Container */}
        <div className={`w-full tablet:flex-1 bg-black flex items-center justify-center relative overflow-hidden shrink-0 ${!post.imageUrl ? 'hidden tablet:flex' : 'h-[50vh] tablet:h-full'}`}>
          {post.imageUrl && (
            <img 
              src={post.imageUrl} 
              className="w-full h-full object-contain" 
              alt="Mídia"
            />
          )}

          <div className="absolute bottom-6 right-6 flex flex-col gap-4 md:hidden">
             <button onClick={handleDownload} className="p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl bg-black/40 text-white active:scale-90 transition-all">
                <ArrowDownTrayIcon className="h-6 w-6" />
             </button>
             <button onClick={handleLike} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasLiked ? 'bg-blue-600 text-white' : 'bg-black/40 text-white'}`}>
                {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
             </button>
             <button onClick={handleSave} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasSaved ? 'bg-yellow-500 text-white' : 'bg-black/40 text-white'}`}>
                {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
             </button>
          </div>
        </div>

        {/* Content & Comments Sidebar */}
        <div className="flex-1 tablet:w-[480px] flex flex-col h-full bg-white dark:bg-[#0a0c10] border-l border-gray-100 dark:border-white/10 relative overflow-hidden">

          <div className="p-6 border-b border-gray-50 dark:border-white/10 flex items-center justify-between shrink-0 hidden tablet:flex bg-gray-50/50 dark:bg-white/[0.02]">
             <div className="flex items-center gap-4 cursor-pointer group" onClick={() => { onClose(); onNavigate('profile', { userId: post.userId }); }}>
                <div className="relative">
                   <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1.2rem] object-cover border-2 border-white dark:border-white/10 shadow-lg" />
                   {author.userType === UserType.CREATOR && <div className="absolute -bottom-1 -right-1 bg-blue-600 p-0.5 rounded-lg border border-white dark:border-[#0a0c10]"><CheckBadgeIcon className="h-3 w-3 text-white" /></div>}
                </div>
                <div>
                   <h4 className="font-black text-sm dark:text-white group-hover:text-blue-600 transition-colors uppercase tracking-tight">{author.firstName} {author.lastName}</h4>
                   <p className="text-gray-400 text-[9px] font-black uppercase tracking-widest mt-0.5">Professor CyBer</p>
                </div>
             </div>
             {!isOwner && (
               <button 
                 onClick={handleFollow}
                 className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 ${isFollowing ? 'bg-gray-100 dark:bg-white/5 text-gray-500' : 'bg-blue-600 text-white shadow-xl shadow-blue-500/20'}`}
               >
                 {isFollowing ? 'Seguindo' : 'Seguir'}
               </button>
             )}
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8">
             {!post.imageUrl && (
                <div className="tablet:hidden flex items-center justify-between mb-4 border-b border-gray-100 dark:border-white/5 pb-4">
                  <div className="flex items-center gap-4">
                     <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover" />
                     <div className="flex flex-col">
                        <span className="font-black text-sm dark:text-white uppercase tracking-tight">{author.firstName} {author.lastName}</span>
                        <span className="text-gray-400 text-[9px] font-black uppercase tracking-widest">Professor CyBer</span>
                     </div>
                  </div>
               </div>
             )}

             <div 
               className={`p-8 md:p-12 rounded-[2.5rem] shadow-inner flex flex-col items-center justify-center text-center animate-fade-in ${post.fontFamily || 'font-sans'}`}
               style={{ 
                 background: hasBg ? post.backgroundColor : 'transparent',
                 backgroundImage: isGradient ? post.backgroundColor : undefined,
                 backgroundColor: hasBg && !isGradient ? post.backgroundColor : undefined,
                 color: post.textColor || 'inherit',
                 fontSize: post.fontSize ? `calc(${post.fontSize} * 1.2)` : '1.1rem',
                 minHeight: hasBg ? '300px' : 'auto',
                 border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
