  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
      post.likes.push(userId);
      createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId: post.id, timestamp: Date.now() });
    }
    updatePost(post);
  }
};

export const updatePost = (updatedPost: Post) => {
  let posts = getPosts();
  posts = posts.map(post => post.id === updatedPost.id ? updatedPost : post);
  savePosts(posts);
};

export const updatePostSaves = (postId: string, userId: string) => {
  const posts = getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
    else post.saves.push(userId);
    updatePost(post);
  }
};

export const updatePostShares = (postId: string, userId: string) => {
  const post = getPosts().find(p => p.id === postId);
  if (post && !post.shares.includes(userId)) {
    post.shares.push(userId);
    updatePost(post);
  }
};

export const addPostComment = (postId: string, comment: Comment) => {
  const post = getPosts().find(p => p.id === postId);
  if (post) {
    post.comments.push(comment);
    createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() });
    updatePost(post);
  }
};

export const toggleFollowUser = (currentUserId: string, userIdToFollow: string) => {
  let allUsers = getUsers();
  const current = allUsers.find(u => u.id === currentUserId);
  const target = allUsers.find(u => u.id === userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    saveUsers(allUsers);
  }
};

export const getOrCreateConversation = (u1: string, u2: string): ChatConversation => {
  const chats = getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { id: `chat-${Date.now()}`, participants: [u1, u2], messages: [] };
    saveChats([...chats, chat]);
  }
  return chat;
};

export const sendMessage = (chatId: string, msg: any) => {
  const chats = getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(msg);
    saveChats(chats);
  }
};

export const getStories = (): Story[] => {
  const storiesJson = localStorage.getItem(STORIES_KEY);
  return storiesJson ? JSON.parse(storiesJson) : [];
};
export const addStory = (uId: string, item: any) => {
  const stories = getStories();
  const user = findUserById(uId);
  if (!user) return;
  let userStory = stories.find(s => s.userId === uId);
  if (!userStory) {
    userStory = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(userStory);
  }
  userStory.items.push({ ...item, id: `item-${Date.now()}`, timestamp: Date.now() });
  localStorage.setItem(STORIES_KEY, JSON.stringify(stories));
};

export const getEvents = (): CyberEvent[] => {
  const eventsJson = localStorage.getItem(EVENTS_KEY);
  return eventsJson ? JSON.parse(eventsJson) : [];
};
export const createEvent = (evt: CyberEvent) => {
  const evts = getEvents();
  localStorage.setItem(EVENTS_KEY, JSON.stringify([evt, ...evts]));
};
export const toggleJoinEvent = (eId: string, uId: string) => {
  const evts = getEvents();
  const evt = evts.find(e => e.id === eId);
  if (evt) {
    if (evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
    else evt.attendees.push(uId);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(evts));
  }
};

export const indicatePostToUser = (pId: string, from: string, to: string) => {
  const post = getPosts().find(p => p.id === pId);
  if (post) {
    if (!post.indicatedUserIds) post.indicatedUserIds = [];
    if (post.indicatedUserIds.includes(to)) return false;
    post.indicatedUserIds.push(to);
    updatePost(post);
    createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: post.id, timestamp: Date.now() });
    return true;
  }
  return false;
};

export const getGlobalSettings = () => ({ platformTax: 0.1, upgradeCost: 29.9, minWithdrawal: 50, maintenanceMode: false });

export const boostPost = (pId: string, uId: string, budget: number, days: number) => {
  const post = getPosts().find(p => p.id === pId);
  if (post && updateUserBalance(uId, -budget)) {
    post.isBoosted = true;
    post.boostExpires = Date.now() + (days * 86400000);
    updatePost(post);
    return true;
  }
  return false;
};

export const saveAffiliateLink = (uId: string, pId: string, link: string) => {
  const links = JSON.parse(localStorage.getItem('cyber_affiliate_links') || '[]');
  links.push({ uId, pId, link, timestamp: Date.now() });
  localStorage.setItem('cyber_affiliate_links', JSON.stringify(links));
};

