  SwatchIcon,
  LanguageIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
  onCancel?: () => void;
}

const BACKGROUND_OPTIONS = [
  { id: 'transparent', value: 'transparent', label: 'Padrão' },
  { id: 'gradient-1', value: 'linear-gradient(135deg, #FF9A9E 0%, #FECFEF 100%)', label: 'Suave' },
  { id: 'solid-dark', value: '#1a1a1a', label: 'Dark' },
  { id: 'solid-blue', value: '#2563eb', label: 'Blue' }
];

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);

  const [liveTitle, setLiveTitle] = useState('');
  const [isLivePaid, setIsLivePaid] = useState(false);
  const [livePrice, setLivePrice] = useState('5.00');
  const [showRecordReel, setShowRecordReel] = useState(false);

  const [fontFamily, setFontFamily] = useState('font-sans');
  const [textColor, setTextColor] = useState('#000000');
  const [backgroundColor, setBackgroundColor] = useState('transparent');

  const [loading, setLoading] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;
  const isProfessional = currentUser.userType === UserType.CREATOR;

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImageUrl(URL.createObjectURL(file));
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file)); 
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      let finalImageUrl = imageUrl;
      let finalReelUrl = reelUrl;

      // 1. Processar Uploads se necessário
      if (postType === PostType.IMAGE && imageFile) {
        finalImageUrl = await uploadFile(imageFile, 'posts');
      }

      if (postType === PostType.REEL && reelFile) {
        finalReelUrl = await uploadFile(reelFile, 'reels');
      }

      // 2. Criar objeto do Post
      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        type: postType,
        timestamp: Date.now(),
        content: content,
        imageUrl: postType === PostType.IMAGE ? finalImageUrl : undefined,
        fontFamily: postType === PostType.TEXT ? fontFamily : undefined,
        textColor: postType === PostType.TEXT ? textColor : undefined,
        backgroundColor: postType === PostType.TEXT ? backgroundColor : undefined,
        reel: postType === PostType.REEL ? { videoUrl: finalReelUrl, description: content } : undefined,
        liveStream: postType === PostType.LIVE ? { title: liveTitle, description: content, isPaid: isLivePaid, price: parseFloat(livePrice) } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: []
      };

      if (isEditing) await updatePost(postData);
      else await addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setReelUrl('');
        setImageFile(null);
        setReelFile(null);
      }
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar postagem. Verifique sua conexão.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-4 shadow-sm">
         <div className="flex items-center gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-3 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-sm">
              O que você está pensando, {currentUser.firstName}?
            </button>
         </div>
         <div className="flex gap-6 px-2 border-t border-gray-50 dark:border-white/5 pt-4">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 text-[10px] font-black uppercase tracking-widest"><PhotoIcon className="h-5 w-5 text-blue-500" /> Imagem</button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex items-center gap-2 text-gray-500 text-[10px] font-black uppercase tracking-widest"><FilmIcon className="h-5 w-5 text-purple-500" /> Reel</button>
         </div>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-8 md:p-10 border dark:border-white/5 animate-fade-in relative">
      <div className="flex items-center justify-between mb-8">
        <h3 className="font-black text-gray-900 dark:text-white uppercase text-xs tracking-[0.2em]">Criar Conteúdo</h3>
        <button onClick={() => setIsExpanded(false)} className="p-2 bg-gray-100 dark:bg-white/10 rounded-xl"><XMarkIcon className="h-6 w-6 text-gray-400" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex gap-2 p-1 bg-gray-100 dark:bg-white/5 rounded-2xl w-fit">
           {[PostType.TEXT, PostType.IMAGE, PostType.REEL].map(t => (
             <button key={t} type="button" onClick={() => setPostType(t)} className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${postType === t ? 'bg-white dark:bg-white/10 text-blue-600' : 'text-gray-400'}`}>{t}</button>
           ))}
        </div>

        {postType === PostType.TEXT && (
          <textarea 
            value={content} 
            onChange={e => setContent(e.target.value)} 
            className="w-full p-8 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-bold text-xl min-h-[200px]" 
            placeholder="No que está pensando?" 
            style={{ backgroundColor, color: textColor }}
          />
        )}

        {postType === PostType.IMAGE && (
          <div className="space-y-4">
            <textarea value={content} onChange={e => setContent(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none" placeholder="Legenda da imagem..." />
            <div onClick={() => imageInputRef.current?.click()} className="w-full h-64 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-all overflow-hidden bg-gray-50 dark:bg-white/5">
              {imageUrl ? <img src={imageUrl} className="w-full h-full object-cover" /> : <PhotoIcon className="h-12 w-12 text-gray-300" />}
              <input type="file" ref={imageInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
            </div>
          </div>
        )}

        {postType === PostType.REEL && (
          <div className="space-y-4">
            <textarea value={content} onChange={e => setContent(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none" placeholder="Descrição do Reel..." />
            <div onClick={() => videoInputRef.current?.click()} className="w-full h-64 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-purple-500 transition-all bg-gray-50 dark:bg-white/5">
              {reelUrl ? <video src={reelUrl} className="h-full" /> : <FilmIcon className="h-12 w-12 text-gray-300" />}
              <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
            </div>
          </div>
        )}

        <button type="submit" disabled={loading} className="w-full py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-xs shadow-xl disabled:opacity-50 active:scale-95 transition-all">
          {loading ? 'Publicando...' : 'Publicar Agora'}
        </button>
      </form>
    </div>
  );
};

