// Fix and Refactor: Correct Story grouping logic to prevent "Cannot read properties of undefined (reading '0')"
export const getStories = async (): Promise<Story[]> => {
  const { data, error } = await supabase
    .from('stories')
    .select(`
      *,
      profiles (first_name, last_name, profile_picture)
    `);

  if (error || !data) return [];

  const grouped: Record<string, Story> = {};

  data.forEach(item => {
    const userId = item.user_id;
    if (!grouped[userId]) {
      grouped[userId] = {
        userId: userId,
        userName: item.profiles ? `${item.profiles.first_name} ${item.profiles.last_name}` : 'Usuário',
        userProfilePic: item.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
        items: []
      };
    }
    grouped[userId].items.push({
      id: item.id,
      imageUrl: item.image_url,
      text: item.text,
      backgroundColor: item.background_color,
      textColor: item.text_color,
      fontFamily: item.font_family,
      timestamp: item.created_at ? new Date(item.created_at).getTime() : Date.now()
    });
  });

  return Object.values(grouped);
};

