export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const mapPostToDomain = (p: any): Post => ({
  id: p.id,
  userId: p.user_id,
  authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Usuário',
  authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: p.type as any,
  content: p.content,
  imageUrl: p.image_url,
  timestamp: p.timestamp,
  likes: p.likes || [],
  shares: p.shares || [],
  saves: p.saves || [],
  isPinned: p.is_pinned,
  isBoosted: p.is_boosted,
  boostExpires: p.boost_expires,
  liveStream: p.live_data,
  reel: p.reel_data,
  fontFamily: p.font_family,
  textColor: p.text_color,
  backgroundColor: p.background_color,
  fontSize: p.font_size,
  indicatedUserIds: p.indicated_user_ids || [],
  comments: [] 
});

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileExt = file instanceof File ? file.name.split('.').pop() : 'webm';
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

  const { error } = await supabase.storage
    .from('cyber-files')
    .upload(fileName, file, {
      cacheControl: '3600',
      upsert: true
    });

  if (error) throw error;
  const { data: { publicUrl } } = supabase.storage.from('cyber-files').getPublicUrl(fileName);
  return publicUrl;
};

