export const getChats = async (): Promise<ChatConversation[]> => {
  const { data } = await supabase.from('conversations').select('*');
  if (!data) return [];
  const mapped = await Promise.all(data.map(async (conv) => {
    const { data: msgs } = await supabase.from('messages').select('*').eq('conversation_id', conv.id).order('timestamp', { ascending: true });
    return {
      id: conv.id,
      participants: conv.participants,
      messages: (msgs || []).map(m => ({
        id: m.id,
        senderId: m.sender_id,
        receiverId: m.receiver_id,
        timestamp: m.timestamp,
        text: m.text,
        imageUrl: m.image_url
      }))
    };
  }));
  return mapped;
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    const id = generateUUID();
    await supabase.from('conversations').insert({ id, participants: [u1, u2] });
    return { id, participants: [u1, u2], messages: [] };
  }
  return chat;
};

