      const prod = await findProductById(item.productId);
      if (!prod) continue;
      await supabase.from('sales').insert({
          id: generateUUID(),
          product_id: item.productId,
          buyer_id: buyerId,
          affiliate_user_id: affiliateId,
          store_id: prod.storeId,
          commission_earned: prod.price * prod.affiliateCommissionRate,
          sale_amount: prod.price * item.quantity,
          status: 'WAITLIST',
          shipping_address: shipping,
          timestamp: Date.now()
      });
  }
  return true;
};

