-- 7. Função de Like (Toggle)
DROP FUNCTION IF EXISTS toggle_like(UUID, TEXT);
CREATE OR REPLACE FUNCTION toggle_like(post_uuid UUID, user_uuid TEXT)
RETURNS VOID AS $$
DECLARE
    current_likes TEXT[];
    author_id UUID;
BEGIN
    SELECT COALESCE(likes, '{}'), user_id INTO current_likes, author_id FROM posts WHERE id = post_uuid FOR UPDATE;
    IF current_likes @> ARRAY[user_uuid] THEN
        UPDATE posts SET likes = array_remove(likes, user_uuid) WHERE id = post_uuid;
    ELSE
        UPDATE posts SET likes = array_append(current_likes, user_uuid) WHERE id = post_uuid;
        IF author_id::text != user_uuid THEN
            INSERT INTO notifications (recipient_id, actor_id, type, post_id, timestamp)
            VALUES (author_id, user_uuid::uuid, 'LIKE', post_uuid, extract(epoch from now()) * 1000);
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

