export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileExt = file instanceof File ? file.name.split('.').pop() : 'webm';
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

  const { error } = await supabase.storage
    .from('cyber-files')
    .upload(fileName, file, {
      cacheControl: '3600',
      upsert: true
    });

  if (error) throw error;
  const { data: { publicUrl } } = supabase.storage.from('cyber-files').getPublicUrl(fileName);
  return publicUrl;
};

export const addPost = async (post: Post) => {
  const { error } = await supabase.from('posts').insert({
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    timestamp: post.timestamp,
    is_pinned: post.isPinned || false,
    live_data: post.liveStream || null,
    reel_data: post.reel || null,
    font_family: post.fontFamily,
    text_color: post.textColor,
    background_color: post.backgroundColor,
    font_size: post.fontSize
  });
  if (error) throw error;
};

export const updatePost = async (post: Post) => {
  const { error } = await supabase.from('posts').update({
    content: post.content,
    image_url: post.imageUrl,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires,
    indicated_user_ids: post.indicatedUserIds,
    reel_data: post.reel,
    live_data: post.liveStream
  }).eq('id', post.id);
  if (error) throw error;
};

export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`*, profiles (first_name, last_name, profile_picture)`)
    .order('timestamp', { ascending: false });

  if (error || !data) return [];
  return data.map(mapPostToDomain);
};

