export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!userId) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
  if (error || !data) return undefined;
  return {
    id: data.id,
    email: data.email,
    firstName: data.first_name,
    lastName: data.last_name,
    userType: data.user_type as any,
    phone: data.phone,
    documentId: data.document_id,
    birthDate: data.birth_date,
    profilePicture: data.profile_picture,
    balance: data.balance,
    credentials: data.credentials,
    bio: data.bio,
    isAdmin: data.is_admin,
    isVerified: data.is_verified,
    followedUsers: data.followed_users || [],
    followers: data.followers || []
  };
};

export const updatePostLikes = async (postId: string, userId: string) => {
  if (!postId || !userId) return;
  const { error } = await supabase.rpc('toggle_like', { 
    post_uuid: postId, 
    user_uuid: userId 
  });
  if (error) throw error;
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (post) {
    let saves = post.saves || [];
    if (saves.includes(userId)) saves = saves.filter((id: string) => id !== userId);
    else saves.push(userId);
    await supabase.from('posts').update({ saves }).eq('id', postId);
  }
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data: post } = await supabase.from('posts').select('shares').eq('id', postId).single();
  if (post) {
    let shares = post.shares || [];
    if (!shares.includes(userId)) {
      shares.push(userId);
      await supabase.from('posts').update({ shares }).eq('id', postId);
    }
  }
};

