export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileExt = file instanceof File ? file.name.split('.').pop() : 'webm';
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;
  const { error } = await supabase.storage.from('cyber-files').upload(fileName, file);
  if (error) throw error;
  const { data: { publicUrl } } = supabase.storage.from('cyber-files').getPublicUrl(fileName);
  return publicUrl;
};

