export const verifyProfessionalDocument = async (base64File: string): Promise<{ isValid: boolean; reason: string; professionDetected?: string }> => {
  if (!apiKey) return { isValid: true, reason: "Bypass por falta de chave de API" };

  try {
    const matches = base64File.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+);base64,(.+)$/);
    let mimeType = 'application/pdf';
    let cleanBase64 = base64File;

    if (matches && matches.length === 3) {
      mimeType = matches[1];
      cleanBase64 = matches[2];
    } else if (base64File.includes(',')) {
      const parts = base64File.split(',');
      cleanBase64 = parts[1];
      if (parts[0].includes('image')) mimeType = 'image/jpeg';
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: cleanBase64 } },
          { text: `Aja como um auditor de conformidade rigoroso. Valide se este é um documento de identificação profissional ou acadêmico legítimo. Responda APENAS JSON.` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isValid: { type: Type.BOOLEAN },
            reason: { type: Type.STRING },
            professionDetected: { type: Type.STRING }
          },
          required: ["isValid", "reason"]
        }
      }
    });

    return JSON.parse(response.text || '{"isValid":false, "reason":"Erro na análise"}');
  } catch (error) {
    console.error("Erro na auditoria Gemini:", error);
    return { isValid: false, reason: "Falha na análise inteligente do documento." };
  }
};

const CACHE_NAME = 'cyberphone-cache-v1';
const urlsToCache = [
  '/',
  '/index.html'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(urlsToCache))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.filter(name => name !== CACHE_NAME).map(name => caches.delete(name))
      );
    }).then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.open(CACHE_NAME).then(async (cache) => {
      const cachedResponse = await cache.match(event.request);

      // Adicionado 'credentials' para evitar erro 401 em links de preview da Vercel
      const fetchPromise = fetch(event.request, { 
        credentials: event.request.mode === 'navigate' ? 'include' : 'same-origin' 
      }).then(networkResponse => {
        if (networkResponse.ok) {
          cache.put(event.request, networkResponse.clone());
        }
        return networkResponse;
      }).catch(() => cachedResponse);

      return cachedResponse || fetchPromise;
    })
  );
});

