export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
    const { data: current } = await supabase.from('profiles').select('followed_users').eq('id', currentUserId).single();
    const { data: target } = await supabase.from('profiles').select('followers').eq('id', userIdToFollow).single();
    if (!current || !target) return;
    let followed = current.followed_users || [];
    let followers = target.followers || [];
    if (followed.includes(userIdToFollow)) {
        followed = followed.filter((id: string) => id !== userIdToFollow);
        followers = followers.filter((id: string) => id !== currentUserId);
    } else {
        followed.push(userIdToFollow);
        followers.push(currentUserId);
    }
    await supabase.from('profiles').update({ followed_users: followed }).eq('id', currentUserId);
    await supabase.from('profiles').update({ followers: followers }).eq('id', userIdToFollow);
};

