import { supabase } from './supabaseClient';
import { 
  User, Post, ChatConversation, AdCampaign, UserType, Store, Product, 
  AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, 
  Notification, NotificationType, CartItem, ProductRating, OrderStatus, 
  CyberEvent, Story, ContentReport, SystemLog, Transaction, GlobalSettings, 
  TransactionType, Message
} from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

const CURRENT_USER_KEY = 'cyberphone_current_user_id';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

const mapPostToDomain = (p: any): Post => ({
  id: p.id,
  userId: p.user_id,
  authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Membro CyBer',
  authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
  type: p.type as any,
  content: p.content,
  imageUrl: p.image_url,
  timestamp: p.timestamp,
  likes: Array.isArray(p.likes) ? p.likes : [],
  shares: Array.isArray(p.shares) ? p.shares : [],
  saves: Array.isArray(p.saves) ? p.saves : [],
  isPinned: p.is_pinned,
  isBoosted: p.is_boosted,
  boostExpires: p.boost_expires,
  liveStream: p.live_data,
  reel: p.reel_data,
  fontFamily: p.font_family,
  textColor: p.text_color,
  backgroundColor: p.background_color,
  fontSize: p.font_size,
  indicatedUserIds: p.indicated_user_ids || [],
  comments: Array.isArray(p.comments) ? p.comments : [] 
});

export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`*, profiles (first_name, last_name, profile_picture)`)
    .order('timestamp', { ascending: false });

  if (error || !data) return [];
  return data.map(mapPostToDomain);
};

export const updatePostLikes = async (postId: string, userId: string) => {
  if (!postId || !userId) return;
  const { error } = await supabase.rpc('toggle_like', { 
    post_uuid: postId, 
    user_uuid: userId 
  });
  if (error) {
    console.error("Erro ao curtir:", error);
    throw error;
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  // Busca comentários atuais para anexar o novo (Supabase não tem array_append em update direto facilmente para JSONB)
  const { data: post, error: fetchError } = await supabase
    .from('posts')
    .select('comments')
    .eq('id', postId)
    .single();

  if (fetchError) throw fetchError;

  const currentComments = Array.isArray(post.comments) ? post.comments : [];
  const updatedComments = [...currentComments, comment];

  const { error: updateError } = await supabase
    .from('posts')
    .update({ comments: updatedComments })
    .eq('id', postId);

  if (updateError) throw updateError;
};

