export const getStories = async (): Promise<Story[]> => {
    const { data } = await supabase.from('stories').select('*, profiles(first_name, last_name, profile_picture)');
    if (!data) return [];
    const grouped: Record<string, Story> = {};
    data.forEach(item => {
        if (!grouped[item.user_id]) {
            grouped[item.user_id] = {
                userId: item.user_id,
                userName: `${item.profiles.first_name} ${item.profiles.last_name}`,
                userProfilePic: item.profiles.profile_picture || DEFAULT_PROFILE_PIC,
                items: []
            };
        }
        grouped[item.user_id].items.push({
            id: item.id,
            imageUrl: item.image_url,
            text: item.text,
            timestamp: new Date(item.created_at).getTime()
        });
    });
    return Object.values(grouped);
};
