const CURRENT_USER_KEY = 'cyberphone_current_user_id';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

export const getChats = async (): Promise<ChatConversation[]> => {
  const { data, error } = await supabase.from('chats').select('*');
  if (error) return [];
  return (data || []).map(c => ({
    id: c.id,
    type: c.type as ChatType,
    participants: c.participants || [],
    messages: c.messages || [],
    groupName: c.group_name,
    groupImage: c.group_image,
    adminId: c.admin_id
  }));
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { 
      id: generateUUID(), 
      type: ChatType.PRIVATE, 
      participants: [u1, u2], 
      messages: [] 
    };
    await supabase.from('chats').insert({
      id: chat.id,
      type: chat.type,
      participants: chat.participants,
      messages: []
    });
  }
  return chat;
};

export const createGroup = async (name: string, members: string[], adminId: string): Promise<ChatConversation> => {
  const chat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.GROUP,
    groupName: name,
    participants: [...new Set([...members, adminId])],
    messages: [],
    adminId,
    groupImage: `https://picsum.photos/200/200?random=${Math.random()}`
  };
  await supabase.from('chats').insert({
    id: chat.id,
    type: chat.type,
    group_name: chat.groupName,
    participants: chat.participants,
    admin_id: chat.adminId,
    group_image: chat.groupImage,
    messages: []
  });
  return chat;
};

export const sendMessage = async (chatId: string, msg: Message) => {
  const { data: chat } = await supabase.from('chats').select('messages').eq('id', chatId).single();
  if (chat) {
    const messages = [...(chat.messages || []), msg];
    await supabase.from('chats').update({ messages }).eq('id', chatId);
  }
};

