export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`*, profiles (first_name, last_name, profile_picture)`)
    .order('timestamp', { ascending: false });

  if (error || !data) return [];
  return data.map(p => ({
    id: p.id,
    userId: p.user_id,
    authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Membro CyBer',
    authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
    type: p.type as any,
    content: p.content,
    imageUrl: p.image_url,
    timestamp: p.timestamp,
    likes: p.likes || [],
    shares: p.shares || [],
    saves: p.saves || [],
    isPinned: p.is_pinned,
    isBoosted: p.is_boosted,
    boostExpires: p.boost_expires,
    liveStream: p.live_data,
    reel: p.reel_data,
    comments: p.comments || []
  }));
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!userId) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
  if (error || !data) return undefined;
  return {
    id: data.id,
    email: data.email,
    firstName: data.first_name,
    lastName: data.last_name,
    userType: data.user_type as any,
    phone: data.phone,
    documentId: data.document_id,
    birthDate: data.birth_date,
    profilePicture: data.profile_picture,
    balance: data.balance,
    credentials: data.credentials,
    bio: data.bio,
    isAdmin: data.is_admin,
    isVerified: data.is_verified,
    isSuspended: data.is_suspended,
    followedUsers: data.followed_users || [],
    followers: data.followers || []
  };
};

export const getCurrentUserId = (): string | null => localStorage.getItem(CURRENT_USER_KEY);
export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(CURRENT_USER_KEY, userId);
  else localStorage.removeItem(CURRENT_USER_KEY);
};

export const updateUserBalance = async (id: string, amount: number) => {
    const { data } = await supabase.from('profiles').select('balance').eq('id', id).single();
    if (data) {
        await supabase.from('profiles').update({ balance: (data.balance || 0) + amount }).eq('id', id);
    }
};

export const getAds = async (): Promise<AdCampaign[]> => {
    const { data } = await supabase.from('ads').select('*').eq('is_active', true);
    return (data || []).map(a => ({
        id: a.id,
        professorId: a.professor_id,
        title: a.title,
        description: a.description,
        targetAudience: a.target_audience,
        budget: a.budget,
        isActive: a.is_active,
        imageUrl: a.image_url,
        linkUrl: a.link_url,
        ctaText: a.cta_text,
        timestamp: a.timestamp
    }));
};

export const getUsers = async (): Promise<User[]> => {
    const { data } = await supabase.from('profiles').select('*');
    return (data || []).map(d => ({
        id: d.id,
        email: d.email,
        firstName: d.first_name,
        lastName: d.last_name,
        userType: d.user_type as any,
        profilePicture: d.profile_picture,
        followers: d.followers || [],
        followedUsers: d.followed_users || [],
        credentials: d.credentials,
        balance: d.balance,
        bio: d.bio,
        isAdmin: d.is_admin,
        isVerified: d.is_verified,
        isSuspended: d.is_suspended
    } as any));
};

