import React, { useState, useEffect, useRef } from 'react';
import { User } from '../types';
import { 
  XMarkIcon, 
  MicrophoneIcon, 
  VideoCameraIcon, 
  PhoneIcon,
  SpeakerWaveIcon,
  VideoCameraSlashIcon,
  MicrophoneSlashIcon
} from '@heroicons/react/24/solid';

interface CallModalProps {
  partner: User;
  type: 'voice' | 'video';
  onClose: () => void;
}

const CallModal: React.FC<CallModalProps> = ({ partner, type, onClose }) => {
  const [status, setStatus] = useState<'calling' | 'connected'>('calling');
  const [timer, setTimer] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(type === 'voice');
  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const startMedia = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: type === 'video' 
        });
        streamRef.current = stream;
        if (localVideoRef.current) {
          localVideoRef.current.srcObject = stream;
        }

        // Simular conexão após 2 segundos
        setTimeout(() => setStatus('connected'), 2500);
      } catch (err) {
        console.error("Erro ao acessar mídia:", err);
      }
    };

    startMedia();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [type]);

  useEffect(() => {
    let interval: any;
    if (status === 'connected') {
      interval = setInterval(() => setTimer(t => t + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-black flex flex-col items-center justify-center animate-fade-in text-white overflow-hidden">
      {/* Background dinâmico */}
      <div className="absolute inset-0 opacity-40">
        <img src={partner.profilePicture} className="w-full h-full object-cover blur-3xl scale-110" />
      </div>

      {/* Área de Vídeo */}
      {type === 'video' && status === 'connected' && (
        <div className="absolute inset-0 z-0">
           <video 
             ref={localVideoRef} 
             autoPlay 
             playsInline 
             muted 
             className={`w-full h-full object-cover transition-opacity duration-1000 ${isCameraOff ? 'opacity-0' : 'opacity-100'}`} 
           />
           {/* Miniatura local (Self) */}
           <div className="absolute bottom-32 right-6 w-32 h-48 bg-gray-900 rounded-3xl border-2 border-white/20 overflow-hidden shadow-2xl">
              <video autoPlay playsInline muted className="w-full h-full object-cover mirror" />
           </div>
        </div>
      )}

      {/* Info do Parceiro */}
      <div className="relative z-10 flex flex-col items-center mb-20 text-center px-6">
         <div className={`w-32 h-32 md:w-48 md:h-48 rounded-full overflow-hidden border-4 border-blue-500 shadow-[0_0_50px_rgba(37,99,235,0.4)] mb-8 transition-all duration-500 ${status === 'connected' && type === 'video' ? 'scale-50 translate-y-[-50px] opacity-0' : 'scale-100'}`}>
            <img src={partner.profilePicture} className="w-full h-full object-cover" />
         </div>
         <h2 className="text-3xl font-black tracking-tighter uppercase mb-2">{partner.firstName} {partner.lastName}</h2>
         <p className="text-blue-400 font-black uppercase tracking-[0.2em] text-xs">
            {status === 'calling' ? 'Chamando...' : formatTime(timer)}
         </p>
      </div>

      {/* Controles Flutuantes */}
      <div className="absolute bottom-12 left-0 right-0 z-20 flex items-center justify-center gap-6 md:gap-10">
         <button 
           onClick={() => setIsMuted(!isMuted)}
           className={`p-5 rounded-full transition-all active:scale-90 ${isMuted ? 'bg-white text-black' : 'bg-white/10 text-white hover:bg-white/20 backdrop-blur-xl'}`}
         >
            {isMuted ? <MicrophoneSlashIcon className="h-7 w-7" /> : <MicrophoneIcon className="h-7 w-7" />}
         </button>

         <button 
           onClick={onClose}
           className="p-7 bg-red-600 rounded-full shadow-2xl shadow-red-900/50 hover:bg-red-700 active:scale-90 transition-all group"
         >
            <PhoneIcon className="h-9 w-9 rotate-[135deg] text-white" />
         </button>

         {type === 'video' && (
           <button 
             onClick={() => setIsCameraOff(!isCameraOff)}
             className={`p-5 rounded-full transition-all active:scale-90 ${isCameraOff ? 'bg-white text-black' : 'bg-white/10 text-white hover:bg-white/20 backdrop-blur-xl'}`}
           >
              {isCameraOff ? <VideoCameraSlashIcon className="h-7 w-7" /> : <VideoCameraIcon className="h-7 w-7" />}
           </button>
         )}

         <button className="p-5 bg-white/10 rounded-full text-white hover:bg-white/20 backdrop-blur-xl transition-all">
            <SpeakerWaveIcon className="h-7 w-7" />
         </button>
      </div>

      <style>{`
        .mirror { transform: scaleX(-1); }
      `}</style>
    </div>
  );
};

