  getChats,
  findUserById,
  getOrCreateConversation,
  createGroup,
  sendMessage,
  generateUUID,
  getUsers
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  UsersIcon
} from '@heroicons/react/24/solid';
