                <div className="ml-4 text-left overflow-hidden flex-1">
                   <p className="font-black text-sm truncate uppercase tracking-tight">{isGroup ? chat.groupName : `Conversa Privada`}</p>
                   <p className={`text-[11px] truncate mt-0.5 ${selectedChat?.id === chat.id ? 'text-blue-100' : 'text-gray-400 font-bold'}`}>
                      {lastMsg ? lastMsg.text || '📷 Imagem' : 'Nenhuma mensagem'}
                   </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Área Principal de Chat */}
      <div className={`flex-1 flex flex-col h-full relative ${!selectedChat ? 'hidden md:flex' : 'flex'}`}>
        {selectedChat ? (
          <>
            <div className="h-16 md:h-20 flex items-center justify-between px-6 bg-white dark:bg-[#12161f] border-b dark:border-white/5 z-30">
               <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-gray-400"><ArrowLeftIcon className="h-6 w-6"/></button>
                  <div className="flex items-center gap-3">
                     <img src={selectedChat.type === ChatType.GROUP ? selectedChat.groupImage : DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-2xl object-cover border shadow-sm" />
                     <div>
                        <h3 className="text-sm md:text-base font-black dark:text-white uppercase tracking-tight leading-none">{selectedChat.type === ChatType.GROUP ? selectedChat.groupName : 'Mestre Privado'}</h3>
                        <p className="text-[10px] text-green-500 font-black uppercase mt-1">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Online agora'}</p>
                     </div>
                  </div>
               </div>
               <div className="flex items-center gap-2">
                  <button onClick={() => startCall('voice')} className="p-3 bg-gray-50 dark:bg-white/5 text-blue-600 rounded-2xl hover:bg-blue-600 hover:text-white transition-all"><PhoneIcon className="h-5 w-5"/></button>
                  <button onClick={() => startCall('video')} className="p-3 bg-gray-50 dark:bg-white/5 text-blue-600 rounded-2xl hover:bg-blue-600 hover:text-white transition-all"><VideoCameraIcon className="h-5 w-5"/></button>
