               </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-10 opacity-30">
             <ChatBubbleLeftRightIcon className="h-32 w-32 text-gray-400 mb-6" />
             <h3 className="text-2xl font-black uppercase tracking-tighter">Selecione uma conversa</h3>
