      </div>

      {/* Modal Criação de Grupo */}
      {isCreatingGroup && (
        <div className="fixed inset-0 z-[1000] bg-black/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsCreatingGroup(false)}>
           <div className="bg-white dark:bg-[#12161f] w-full max-w-md rounded-[3rem] p-8 shadow-2xl relative border dark:border-white/10" onClick={e => e.stopPropagation()}>
