export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const chats = await getChats();
  let chat = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(u1) && c.participants.includes(u2));
  if (!chat) {
    chat = { 
      id: generateUUID(), 
      type: ChatType.PRIVATE, 
      participants: [u1, u2], 
      messages: [] 
    };
    await supabase.from('chats').insert({
      id: chat.id,
      type: chat.type,
      participants: chat.participants,
      messages: []
    });
  }
  return chat;
};

