export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  for (const item of cartItems) {
    const product = await findProductById(item.productId);
    if (!product) continue;
    const store = await findStoreById(product.storeId);
    if (!store) continue;

    const total = product.price * item.quantity;
    const commission = affiliateUserId ? total * product.affiliateCommissionRate : 0;

    await supabase.from('sales').insert({
      id: generateUUID(),
      product_id: item.productId,
      buyer_id: buyerId,
      affiliate_user_id: affiliateUserId || '',
      store_id: product.storeId,
      commission_earned: commission,
      sale_amount: total,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      is_rated: false,
      shipping_address: shippingAddress,
      digital_content_url: product.digitalContentUrl
    });

    const ownerNet = total - commission;
    await updateUserBalance(store.professorId, ownerNet);
    if (affiliateUserId) await updateUserBalance(affiliateUserId, commission);
  }
  clearCart();
  return true;
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
  const sales = await getAffiliateSales();
  const sale = sales.find(s => s.id === saleId);
  if (!sale || sale.isRated) return;

  const product = await findProductById(sale.productId);
  if (!product) return;

  const newRating: ProductRating = {
    id: generateUUID(),
    saleId,
    userId: sale.buyerId,
    rating,
    comment,
    timestamp: Date.now()
  };

  const updatedRatings = [...product.ratings, newRating];
  const avg = updatedRatings.reduce((sum, r) => sum + r.rating, 0) / updatedRatings.length;

  await supabase.from('products').update({
    ratings: updatedRatings,
    rating_count: updatedRatings.length,
    average_rating: avg
  }).eq('id', product.id);

  await supabase.from('sales').update({ is_rated: true }).eq('id', saleId);
};

