export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if (existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(i => i.productId !== productId);
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  const cart = getCart();
  const item = cart.find(i => i.productId === productId);
  if (item) {
    item.quantity = quantity;
    if (item.quantity <= 0) removeFromCart(productId);
    else localStorage.setItem(CART_KEY, JSON.stringify(cart));
  }
};

export const clearCart = () => localStorage.removeItem(CART_KEY);

