export const verifyProfessionalDocument = async (base64File: string): Promise<{ isValid: boolean; reason: string; professionDetected?: string }> => {
  try {
    const matches = base64File.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9-.+]+);base64,(.+)$/);
    let mimeType = 'application/pdf';
    let cleanBase64 = base64File;

    if (matches && matches.length === 3) {
      mimeType = matches[1];
      cleanBase64 = matches[2];
    } else if (base64File.includes(',')) {
      const parts = base64File.split(',');
      cleanBase64 = parts[1];
      if (parts[0].includes('image')) mimeType = 'image/jpeg';
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType, data: cleanBase64 } },
          { text: `Aja como um auditor de conformidade rigoroso. Valide se este é um documento de identificação profissional ou acadêmico legítimo. Responda APENAS JSON.` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isValid: { type: Type.BOOLEAN },
            reason: { type: Type.STRING },
            professionDetected: { type: Type.STRING }
          },
          required: ["isValid", "reason"]
        }
      }
    });

    // Extraindo o texto gerado através da propriedade .text
    return JSON.parse(response.text || '{"isValid":false, "reason":"Erro na análise"}');
  } catch (error) {
    console.error("Erro na auditoria Gemini:", error);
    return { isValid: false, reason: "Falha na análise inteligente do documento." };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { User } from '../types';
import { 
  XMarkIcon, 
  MicrophoneIcon, 
  VideoCameraIcon, 
  PhoneIcon,
  SpeakerWaveIcon,
  VideoCameraSlashIcon,
  MicrophoneSlashIcon,
  ArrowPathIcon
} from '@heroicons/react/24/solid';

interface CallModalProps {
  partner: User;
  type: 'voice' | 'video';
  onClose: () => void;
}

const CallModal: React.FC<CallModalProps> = ({ partner, type, onClose }) => {
  const [status, setStatus] = useState<'calling' | 'connected'>('calling');
  const [timer, setTimer] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(type === 'voice');
  const [volumeLevel, setVolumeLevel] = useState(0);

  const localVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const startMedia = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: type === 'video' 
        });

        streamRef.current = stream;

        if (localVideoRef.current && type === 'video') {
          localVideoRef.current.srcObject = stream;
        }

        // Setup Audio Analysis for Voice Visualizer
        if (stream.getAudioTracks().length > 0) {
          setupAudioAnalyser(stream);
        }

        // Simulate connection delay
        const ringingTimeout = setTimeout(() => setStatus('connected'), 3000);
        return () => clearTimeout(ringingTimeout);
      } catch (err) {
        console.error("Erro ao acessar mídia:", err);
        alert("Não foi possível acessar a câmera ou microfone.");
        onClose();
      }
    };

    startMedia();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, [type]);

  const setupAudioAnalyser = (stream: MediaStream) => {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const source = audioContext.createMediaStreamSource(stream);
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    audioContextRef.current = audioContext;
    analyserRef.current = analyser;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const updateVolume = () => {
      if (!analyserRef.current) return;
      analyserRef.current.getByteFrequencyData(dataArray);

      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += dataArray[i];
      }
      const average = sum / bufferLength;
      setVolumeLevel(average); // Escala de 0 a 255 aproximadamente

      animationFrameRef.current = requestAnimationFrame(updateVolume);
    };

    updateVolume();
  };

  useEffect(() => {
    let interval: any;
    if (status === 'connected') {
      interval = setInterval(() => setTimer(t => t + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-black flex flex-col items-center justify-center animate-fade-in text-white overflow-hidden">

      {/* Background Dinâmico com Blur Profundo */}
      <div className="absolute inset-0 opacity-40">
        <img 
          src={partner.profilePicture} 
          className="w-full h-full object-cover blur-[100px] scale-150 transition-transform duration-[10s] animate-slow-zoom" 
        />
      </div>

      {/* Camada de Vídeo (Somente se for chamada de vídeo) */}
      {type === 'video' && (
        <div className="absolute inset-0 z-0">
           <video 
             ref={localVideoRef} 
             autoPlay 
             playsInline 
             muted 
             className={`w-full h-full object-cover transition-opacity duration-1000 ${isCameraOff ? 'opacity-0' : 'opacity-100'}`} 
           />

           {/* Miniatura local (Self View) */}
           <div className="absolute bottom-32 right-6 w-32 h-48 bg-gray-900 rounded-3xl border-2 border-white/20 overflow-hidden shadow-2xl z-50">
              <video autoPlay playsInline muted className="w-full h-full object-cover mirror" />
           </div>
        </div>
      )}

      {/* UI Central (Foco no Usuário) */}
      <div className="relative z-10 flex flex-col items-center mb-20 text-center px-6">

         {/* Efeito de Ondas Sonoras (Visualizer) */}
         <div className="relative mb-8">
            <div 
              className="absolute inset-0 rounded-full bg-blue-500/20 animate-ping"
              style={{ 
                transform: `scale(${1 + (volumeLevel / 200)})`,
                opacity: volumeLevel > 10 ? 0.4 : 0 
              }}
            ></div>
            <div 
              className="absolute inset-0 rounded-full bg-blue-400/10"
              style={{ 
                transform: `scale(${1.2 + (volumeLevel / 150)})`,
                transition: 'transform 0.1s ease-out'
              }}
            ></div>

            <div className={`relative w-32 h-32 md:w-48 md:h-48 rounded-full overflow-hidden border-4 ${status === 'connected' ? 'border-green-500' : 'border-blue-500'} shadow-[0_0_60px_rgba(37,99,235,0.3)] transition-all duration-700 ${status === 'connected' && type === 'video' ? 'scale-0 opacity-0' : 'scale-100'}`}>
               <img src={partner.profilePicture} className="w-full h-full object-cover" />
            </div>
         </div>

         <div className={`transition-all duration-700 ${status === 'connected' && type === 'video' ? 'translate-y-[-100px] opacity-0' : 'translate-y-0 opacity-100'}`}>
            <h2 className="text-3xl md:text-5xl font-black tracking-tighter uppercase mb-2 drop-shadow-2xl">
              {partner.firstName} {partner.lastName}
            </h2>
            <div className="flex items-center justify-center gap-3">
               <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-green-500 animate-pulse' : 'bg-blue-500 animate-bounce'}`}></span>
               <p className="text-blue-400 font-black uppercase tracking-[0.3em] text-xs">
                  {status === 'calling' ? 'Ringing...' : formatTime(timer)}
               </p>
            </div>
         </div>
      </div>

      {/* Controles Estilo Telegram (Bottom Bar) */}
      <div className="absolute bottom-12 left-0 right-0 z-30 flex items-center justify-center gap-4 md:gap-8 px-4">

         <div className="flex bg-white/10 backdrop-blur-2xl rounded-[3rem] p-2 border border-white/10 shadow-2xl items-center gap-2">

            <button 
              onClick={() => setIsMuted(!isMuted)}
              className={`p-5 rounded-full transition-all active:scale-90 ${isMuted ? 'bg-red-500 text-white shadow-lg' : 'bg-white/5 text-white hover:bg-white/20'}`}
              title="Mudar Microfone"
            >
               {isMuted ? <MicrophoneSlashIcon className="h-6 w-6" /> : <MicrophoneIcon className="h-6 w-6" />}
            </button>

            {type === 'video' && (
              <button 
                onClick={() => setIsCameraOff(!isCameraOff)}
                className={`p-5 rounded-full transition-all active:scale-90 ${isCameraOff ? 'bg-red-500 text-white' : 'bg-white/5 text-white hover:bg-white/20'}`}
                title="Mudar Câmera"
              >
                 {isCameraOff ? <VideoCameraSlashIcon className="h-6 w-6" /> : <VideoCameraIcon className="h-6 w-6" />}
              </button>
            )}

            <button className="p-5 bg-white/5 rounded-full text-white hover:bg-white/20 transition-all hidden md:block">
               <SpeakerWaveIcon className="h-6 w-6" />
            </button>

            <button className="p-5 bg-white/5 rounded-full text-white hover:bg-white/20 transition-all">
               <ArrowPathIcon className="h-6 w-6" />
            </button>

            {/* Botão de Desligar (Separado para ênfase) */}
            <button 
              onClick={onClose}
              className="p-6 bg-red-600 rounded-full shadow-2xl shadow-red-900/50 hover:bg-red-700 active:scale-95 transition-all group ml-2"
            >
               <PhoneIcon className="h-8 w-8 rotate-[135deg] text-white" />
            </button>
         </div>

      </div>

      <style>{`
        .mirror { transform: scaleX(-1); }
        @keyframes slow-zoom {
          0% { transform: scale(1.5) rotate(0deg); }
          50% { transform: scale(1.7) rotate(5deg); }
          100% { transform: scale(1.5) rotate(0deg); }
        }
        .animate-slow-zoom {
          animation: slow-zoom 20s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

