import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType } from '../types';
import {
  getChats,
  findUserById,
  getOrCreateConversation,
  createGroup,
  sendMessage,
  generateUUID,
  getUsers
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  UsersIcon,
  EllipsisVerticalIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';

interface ChatPageProps {
  currentUser: User;
}

const ChatPage: React.FC<ChatPageProps> = ({ currentUser }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [groupName, setGroupName] = useState('');
  const [selectedMembers, setSelectedMembers] = useState<string[]>([]);
  const [availableUsers, setAvailableUsers] = useState<User[]>([]);
  const [activeCall, setActiveCall] = useState<{partner: User, type: 'voice' | 'video'} | null>(null);
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = useCallback(async () => {
    const allChats = await getChats();
    const userChats = allChats.filter(c => c.participants.includes(currentUser.id));
    setConversations(userChats);

    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
    }

    const users = await getUsers();
    setAvailableUsers(users.filter(u => u.id !== currentUser.id));
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 4000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length]);

  const handleStartGroup = async () => {
    if (!groupName || selectedMembers.length === 0) return;
    const newGroup = await createGroup(groupName, selectedMembers, currentUser.id);
    setSelectedChat(newGroup);
    setIsCreatingGroup(false);
    setGroupName('');
    setSelectedMembers([]);
    loadData();
  };

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    const msg: Message = {
      id: generateUUID(),
      senderId: currentUser.id,
      timestamp: Date.now(),
      text: newMessage.trim() || undefined,
      imageUrl: attachedImage || undefined,
      groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
      receiverId: selectedChat.type === ChatType.PRIVATE ? selectedChat.participants.find(p => p !== currentUser.id) : undefined
    };

    await sendMessage(selectedChat.id, msg);
    setNewMessage('');
    setAttachedImage(null);
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat || selectedChat.type === ChatType.GROUP) return;
    const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
    const partner = await findUserById(partnerId!);
    if (partner) setActiveCall({ partner, type });
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab === 'ALL') return true;
    return c.type === filterTab;
  });

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in font-sans">

      {/* Sidebar Style Telegram */}
      <div className={`w-full md:w-80 lg:w-[380px] flex flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 shrink-0 z-40 transition-all ${selectedChat ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-5 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <button className="p-2 text-gray-400 hover:text-blue-500"><Bars3BottomLeftIcon className="h-6 w-6"/></button>
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">CyBer Chat</h2>
              </div>
              <button onClick={() => setIsCreatingGroup(true)} className="p-2.5 bg-blue-600 text-white rounded-2xl shadow-lg hover:bg-blue-700 transition-all"><PlusIcon className="h-5 w-5"/></button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input placeholder="Buscar conversas..." className="w-full pl-11 pr-4 py-3 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-2 focus:ring-blue-500"/>
           </div>

           <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-5 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-2 space-y-1">
          {filteredConversations.map(chat => {
            const isGroup = chat.type === ChatType.GROUP;
            const partnerId = chat.participants.find(p => p !== currentUser.id);
            const lastMsg = chat.messages[chat.messages.length - 1];

            return (
              <button
                key={chat.id}
                onClick={() => setSelectedChat(chat)}
                className={`w-full flex items-center p-4 rounded-3xl transition-all group ${selectedChat?.id === chat.id ? 'bg-blue-600 text-white shadow-xl translate-x-1' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
              >
                <div className="relative shrink-0">
                   <img src={isGroup ? chat.groupImage : `https://ui-avatars.com/api/?name=${partnerId}&background=random`} className="w-14 h-14 rounded-2xl object-cover border-2 border-white/10" />
                   {isGroup && <div className="absolute -bottom-1 -right-1 bg-blue-600 p-1 rounded-lg border-2 border-white shadow-md"><UserGroupIcon className="h-3 w-3 text-white"/></div>}
                </div>
                <div className="ml-4 text-left overflow-hidden flex-1">
                   <p className="font-black text-sm truncate uppercase tracking-tight">{isGroup ? chat.groupName : `Chat Privado`}</p>
                   <p className={`text-[11px] truncate mt-0.5 ${selectedChat?.id === chat.id ? 'text-blue-100' : 'text-gray-400 font-bold'}`}>
                      {lastMsg ? lastMsg.text || '📷 Imagem' : 'Nenhuma mensagem'}
                   </p>
                </div>
                {lastMsg && (
                  <div className="ml-2 text-[8px] font-black text-gray-400 uppercase opacity-60">
                    {new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes()}
                  </div>
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Área Principal de Chat */}
      <div className={`flex-1 flex flex-col h-full relative ${!selectedChat ? 'hidden md:flex' : 'flex'}`}>
        {selectedChat ? (
          <>
            <div className="h-16 md:h-20 flex items-center justify-between px-6 bg-white dark:bg-[#12161f] border-b dark:border-white/5 z-30">
               <div className="flex items-center gap-4">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-gray-400"><ArrowLeftIcon className="h-6 w-6"/></button>
                  <div className="flex items-center gap-3">
                     <img src={selectedChat.type === ChatType.GROUP ? selectedChat.groupImage : DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-12 md:h-12 rounded-2xl object-cover border shadow-sm" />
                     <div>
                        <h3 className="text-sm md:text-base font-black dark:text-white uppercase tracking-tight leading-none">{selectedChat.type === ChatType.GROUP ? selectedChat.groupName : 'Professor'}</h3>
                        <p className="text-[10px] text-green-500 font-black uppercase mt-1">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Disponível'}</p>
                     </div>
                  </div>
               </div>

               {/* Botões de Chamada de Voz e Vídeo */}
               <div className="flex items-center gap-2">
                  <button 
                    onClick={() => startCall('voice')} 
                    className="p-3 bg-blue-50 dark:bg-blue-600/10 text-blue-600 rounded-2xl hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-90"
                    title="Chamada de Voz"
                  >
                    <PhoneIcon className="h-5 w-5"/>
                  </button>
                  <button 
                    onClick={() => startCall('video')} 
                    className="p-3 bg-blue-50 dark:bg-blue-600/10 text-blue-600 rounded-2xl hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-90"
                    title="Chamada de Vídeo"
                  >
                    <VideoCameraIcon className="h-5 w-5"/>
                  </button>
                  <button className="p-3 text-gray-400"><EllipsisVerticalIcon className="h-6 w-6"/></button>
               </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-4 custom-scrollbar bg-[url('https://www.transparenttextures.com/patterns/chat-bubbles.png')] dark:bg-none">
               {selectedChat.messages.map(msg => {
                 const isMine = msg.senderId === currentUser.id;
                 return (
                   <div key={msg.id} className={`flex w-full ${isMine ? 'justify-end' : 'justify-start'} animate-scale-in`}>
                      <div className={`max-w-[80%] p-4 rounded-3xl shadow-sm ${isMine ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white dark:bg-[#1a1c23] dark:text-white rounded-bl-none border dark:border-white/5'}`}>
                         {msg.imageUrl && <img src={msg.imageUrl} className="w-full h-auto rounded-2xl mb-2 shadow-lg" />}
                         <p className="text-sm font-bold leading-relaxed">{msg.text}</p>
                         <div className={`flex items-center gap-2 mt-2 text-[8px] font-black uppercase opacity-50 ${isMine ? 'justify-end' : ''}`}>
                            {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                            {isMine && <CheckBadgeIcon className="h-3 w-3" />}
                         </div>
                      </div>
                   </div>
                 );
               })}
               <div ref={messagesEndRef} />
            </div>

            <div className="p-4 md:p-6 bg-white dark:bg-[#12161f] border-t dark:border-white/5">
               <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-center gap-3">
                  <button type="button" onClick={() => fileInputRef.current?.click()} className="p-4 text-gray-400 hover:text-blue-500 transition-all"><PhotoIcon className="h-7 w-7"/></button>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => {
                     const file = e.target.files?.[0];
                     if (file) {
                        const r = new FileReader();
                        r.onloadend = () => setAttachedImage(r.result as string);
                        r.readAsDataURL(file);
                     }
                  }} />
                  <input 
                    value={newMessage} 
                    onChange={e => setNewMessage(e.target.value)}
                    placeholder="Escreva sua mensagem..." 
                    className="flex-1 bg-gray-50 dark:bg-white/5 dark:text-white p-4 rounded-2xl outline-none font-bold text-sm focus:ring-2 focus:ring-blue-600 transition-all"
                  />
                  <button type="submit" disabled={!newMessage.trim() && !attachedImage} className="p-4 bg-blue-600 text-white rounded-2xl shadow-xl active:scale-90 disabled:opacity-50 transition-all"><PaperAirplaneIcon className="h-6 w-6 -rotate-45"/></button>
               </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-10 opacity-30">
             <div className="w-40 h-40 bg-gray-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-8 animate-pulse">
                <ChatBubbleLeftRightIcon className="h-20 w-20 text-gray-400" />
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter">Sua Central de Mensagens</h3>
             <p className="text-sm font-bold uppercase tracking-widest mt-2 max-w-xs">Inicie conversas privadas ou participe de grupos com mestres e alunos.</p>
          </div>
        )}
      </div>

      {/* Modais omitidos para brevidade, mas devem existir no arquivo original */}
      {isCreatingGroup && (
        <div className="fixed inset-0 z-[1000] bg-black/80 backdrop-blur-md flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsCreatingGroup(false)}>
           <div className="bg-white dark:bg-[#12161f] w-full max-w-md rounded-[3rem] p-8 shadow-2xl relative border dark:border-white/10" onClick={e => e.stopPropagation()}>
              <h3 className="text-2xl font-black dark:text-white uppercase tracking-tighter mb-8 text-center">Novo Grupo</h3>
              <input value={groupName} onChange={e => setGroupName(e.target.value)} placeholder="Nome do Grupo" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl mb-6 font-bold dark:text-white outline-none focus:ring-2 focus:ring-blue-600" />

              <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4 ml-1">Membros Disponíveis</p>
              <div className="max-h-60 overflow-y-auto space-y-2 custom-scrollbar mb-8 pr-2">
                 {availableUsers.map(user => (
                    <label key={user.id} className="flex items-center justify-between p-3 bg-gray-50 dark:bg-white/5 rounded-2xl cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/10 transition-colors">
                       <div className="flex items-center gap-3">
                          <img src={user.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover" />
                          <span className="font-black text-xs dark:text-white truncate max-w-[150px]">{user.firstName} {user.lastName}</span>
                       </div>
                       <input 
                         type="checkbox" 
                         checked={selectedMembers.includes(user.id)} 
                         onChange={() => {
                           if (selectedMembers.includes(user.id)) setSelectedMembers(selectedMembers.filter(id => id !== user.id));
                           else setSelectedMembers([...selectedMembers, user.id]);
                         }}
                         className="w-5 h-5 accent-blue-600 rounded-lg" 
                       />
                    </label>
                 ))}
              </div>

              <div className="flex gap-3">
                 <button onClick={() => setIsCreatingGroup(false)} className="flex-1 py-4 font-black text-xs uppercase text-gray-400">Cancelar</button>
                 <button onClick={handleStartGroup} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all">Criar Grupo</button>
              </div>
           </div>
        </div>
      )}

      {/* Modal de Chamada */}
      {activeCall && <CallModal partner={activeCall.partner} type={activeCall.type} onClose={() => setActiveCall(null)} />}
    </div>
  );
};

