    console.log('SW registrado para Push:', registration);

    // Chave VAPID pública (exemplo para o protótipo)
    const publicVapidKey = 'BEl62vp9IHZisOV0QXZf8azm2vVvF-W66XlE16-96WqL_K5f3tF7_p03-B5_6-6WqL_K5f3tF7_p03';

