import { verifyProfessionalDocument } from '../services/geminiService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { COUNTRIES } from '../data/countries';
import { 
  DocumentArrowUpIcon, 
  CalendarDaysIcon, 
  CameraIcon, 
  PlusIcon, 
  ChevronDownIcon, 
  MagnifyingGlassIcon,
  DocumentCheckIcon,
  XMarkIcon,
  ShieldCheckIcon,
  ArrowLeftIcon,
  EnvelopeIcon,
  ExclamationTriangleIcon,
  LockClosedIcon,
  CheckCircleIcon,
  PaperAirplaneIcon
} from '@heroicons/react/24/outline';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

type RecoveryStep = 'request' | 'sent' | 'reset' | 'success';

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [isRecovery, setIsRecovery] = useState(false);
  const [recoveryStep, setRecoveryStep] = useState<RecoveryStep>('request');

  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);
  const [loading, setLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [error, setError] = useState('');

  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES.find(c => c.code === 'BR') || COUNTRIES[0]);
  const [showCountryPicker, setShowCountryPicker] = useState(false);
  const [countrySearch, setCountrySearch] = useState('');

  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');

  const [newPassword, setNewPassword] = useState('');
  const [confirmNewPassword, setConfirmNewPassword] = useState('');

  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');
  const [profilePicBase64, setProfilePicBase64] = useState<string>(DEFAULT_PROFILE_PIC);
  const [verificationFile, setVerificationFile] = useState<string | null>(null);
  const [verificationFileName, setVerificationFileName] = useState<string | null>(null);

  const profilePicInputRef = useRef<HTMLInputElement>(null);
  const docInputRef = useRef<HTMLInputElement>(null);

  const validateEmailFormat = (email: string) => {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  };

  const filteredCountries = useMemo(() => {
    return COUNTRIES.filter(c => 
      c.name.toLowerCase().includes(countrySearch.toLowerCase()) || 
      c.ddi.includes(countrySearch)
    );
  }, [countrySearch]);

  const inputClasses = "w-full p-3.5 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl border-2 border-transparent focus:border-blue-500 focus:bg-white dark:focus:bg-darkcard outline-none font-bold text-sm transition-all shadow-inner placeholder-gray-400";

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let value = e.target.value.replace(/\D/g, '');
    if (selectedCountry.ddi === '+55') {
      if (value.length > 11) value = value.slice(0, 11);
      if (value.length > 10) {
        value = value.replace(/^(\d{2})(\d{5})(\d{4}).*/, '($1) $2-$3');
      } else if (value.length > 6) {
        value = value.replace(/^(\d{2})(\d{4})(\d{0,4}).*/, '($1) $2-$3');
      } else if (value.length > 2) {
        value = value.replace(/^(\d{2})(\d{0,5}).*/, '($1) $2');
      } else if (value.length > 0) {
        value = value.replace(/^(\d*)/, '($1');
      }
    } else {
      if (value.length > 14) value = value.slice(0, 14);
    }
    setPhone(value);
  };

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !password) {
      setError('Campos básicos obrigatórios pendentes.');
      return;
    }

    if (!validateEmailFormat(email)) {
      setError('Formato de e-mail inválido (exemplo: usuario@email.com).');
      return;
    }

    setLoading(true);
    setLoadingMessage('Auditando dados...');

    try {
      if (userType === UserType.CREATOR && verificationFile) {
        setLoadingMessage('A IA está validando seus documentos...');
        const analysis = await verifyProfessionalDocument(verificationFile);
        if (!analysis.isValid) throw new Error(`Documento Recusado: ${analysis.reason}`);
        if (analysis.professionDetected && !credentials) setCredentials(analysis.professionDetected);
      }

      const fullPhone = `${selectedCountry.ddi} ${phone}`;
      const newUser = await registerUser({
        userType, firstName, lastName, email, phone: fullPhone, documentId,
        birthDate: new Date(birthDate).getTime(), password, profilePicture: profilePicBase64,
        credentials: userType === UserType.CREATOR ? credentials : undefined,
        bio: bio || undefined, verificationFileUrl: verificationFile || undefined
      });
      saveCurrentUser(newUser.id);
      onLoginSuccess(newUser);
    } catch (err: any) {
      setError(err.message || 'Falha no processamento.');
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!validateEmailFormat(email)) {
      setError('Insira um e-mail válido para acessar.');
      return;
    }

    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError('Credenciais não reconhecidas no sistema.');
    } finally {
      setLoading(false);
    }
  };

  const handleRecoveryRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!validateEmailFormat(email)) {
      setError('E-mail inválido para recuperação.');
      return;
    }

    setLoading(true);
    try {
      await recoverPassword(email);
      setRecoveryStep('sent');
    } catch (err: any) {
      setError('E-mail não localizado em nossa base.');
    } finally {
      setLoading(false);
    }
  };

  if (isRecovery) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4">
        <div className="bg-white dark:bg-darkcard p-8 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10">
           {recoveryStep === 'request' && (
             <>
               <button onClick={() => setIsRecovery(false)} className="mb-6 flex items-center text-gray-400 hover:text-blue-600 font-bold text-xs uppercase gap-2 transition-colors">
                  <ArrowLeftIcon className="h-4 w-4" /> Voltar
               </button>
               <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter mb-6">Recuperar Acesso</h2>
               {error && <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 uppercase text-center">{error}</div>}
               <form onSubmit={handleRecoveryRequest} className="space-y-6">
                  <input type="email" placeholder="Seu e-mail cadastrado" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />
                  <button type="submit" disabled={loading} className="w-full py-4 rounded-2xl font-black text-xs uppercase bg-blue-600 text-white shadow-xl">
                    {loading ? 'Consultando...' : 'Enviar Link de Recuperação'}
                  </button>
               </form>
             </>
           )}
           {recoveryStep === 'sent' && (
             <div className="text-center">
               <PaperAirplaneIcon className="h-12 w-12 text-blue-600 mx-auto mb-6" />
               <h2 className="text-xl font-black mb-4">Link Enviado!</h2>
               <p className="text-gray-500 text-sm mb-8">Verifique sua caixa de entrada em <strong>{email}</strong>.</p>
               <button onClick={() => setIsRecovery(false)} className="text-blue-600 font-black uppercase text-xs">Voltar ao Login</button>
             </div>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 p-4">
      <div className="bg-white dark:bg-darkcard p-8 md:p-10 rounded-[2.5rem] shadow-2xl w-full max-w-md animate-fade-in border border-white/10">
        <div className="mb-8 flex flex-col items-center">
          <Logo size="lg" className="mb-1" />
          <p className="text-gray-400 font-bold uppercase text-[8px] tracking-[0.25em]">Ecossistema Educacional CyBerPhone</p>
        </div>

        {error && (
          <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[10px] font-black mb-6 flex items-center justify-center gap-2 border border-red-100">
            <ExclamationTriangleIcon className="h-4 w-4" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={isRegister ? handleRegister : handleLogin} className="space-y-4">
          {isRegister && (
            <div className="grid grid-cols-2 gap-3">
              <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClasses} />
              <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClasses} />
            </div>
          )}

          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClasses} />
          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClasses} />

          <button type="submit" disabled={loading} className="w-full py-4 rounded-2xl font-black text-xs uppercase bg-blue-600 text-white shadow-xl active:scale-95 transition-all">
            {loading ? 'Aguarde...' : isRegister ? 'Criar Conta Agora' : 'Entrar na Rede'}
          </button>
        </form>

        <div className="mt-6 flex flex-col items-center gap-4">
          {!isRegister && (
            <button onClick={() => setIsRecovery(true)} className="text-[10px] font-black text-gray-400 hover:text-blue-600 uppercase">Esqueceu a senha?</button>
          )}
          <button onClick={() => setIsRegister(!isRegister)} className="text-[9px] font-black text-blue-600 uppercase tracking-widest border-b border-blue-600 pb-1">
            {isRegister ? 'Já possui acesso? Entrar' : 'Não tem conta? Cadastrar-se'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem, GlobalSettings } from '../types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    getGlobalSettings
} from '../services/storageService';
import Header from './Header';
import Footer from './Footer';
import AuthPage from './AuthPage';
import FeedPage from './FeedPage';
import ProfilePage from './ProfilePage';
import ChatPage from './ChatPage';
import AdCampaignPage from './AdCampaignPage';
import LiveStreamViewer from './LiveStreamViewer';
import { StorePage } from './StorePage';
import StoreManagerPage from './StoreManagerPage';
import CreatePost from './CreatePost';
import ReelsPage from './ReelsPage';
import SearchResultsPage from './SearchResultsPage';
import NotificationsPage from './NotificationsPage';
import CartModal from './CartModal';
import WalletModal from './WalletModal';
import SettingsPage from './SettingsPage';
import AdminDashboard from './AdminDashboard';
import EventsPage from './EventsPage';
import PurchasesPage from './PurchasesPage';
import AffiliatesPage from './AffiliatesPage';
import { ExclamationTriangleIcon } from '@heroicons/react/24/solid';
import { requestNotificationPermission } from '../services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'create-post' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates';

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');
                    requestNotificationPermission();
                } else {
                    setCurrentPage('auth');
                }
            } else {
                setCurrentPage('auth');
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, [currentPage]);

    useEffect(() => {
        refreshCurrentUser();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-blue-600 mb-4"></div>
                <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Iniciando Ecossistema...</p>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-12 w-12 text-red-500 mb-4" />
                <h2 className="text-xl font-black uppercase mb-2">Ops! Ocorreu um erro</h2>
                <p className="text-gray-500 text-sm mb-6">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black uppercase text-xs">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''}`}>
                    <div className="max-w-7xl mx-auto">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

