                   <div className="relative">
                      <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                      <input 
                        type="text" 
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        placeholder="Buscar aluno por nome..."
                        className="w-full pl-12 pr-6 py-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white border border-gray-100 dark:border-white/5"
                      />
