                           >
                              <div className="flex items-center gap-4">
                                 <img src={follower.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover shadow-sm" />
                                 <div>
                                    <p className="font-black text-xs dark:text-white uppercase truncate max-w-[150px]">{follower.firstName} {follower.lastName}</p>
                                    <p className="text-[8px] font-bold text-gray-400 uppercase">{follower.credentials || 'Aluno CyBer'}</p>
                                 </div>
                              </div>
                              <div className={`w-6 h-6 rounded-lg flex items-center justify-center border-2 transition-all ${selectedMembers.includes(follower.id) ? 'bg-blue-600 border-blue-600 text-white' : 'border-gray-200'}`}>
                                 {selectedMembers.includes(follower.id) && <CheckIcon className="h-4 w-4" />}
                              </div>
                           </div>
                        ))
                      )}
                   </div>
                </div>
             </div>

             <div className="pt-6 border-t border-gray-100 dark:border-white/5">
                <button 
                  onClick={handleCreate}
                  disabled={loading || !groupName.trim() || selectedMembers.length === 0}
                  className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${
                    loading || !groupName.trim() || selectedMembers.length === 0 
                     ? 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none' 
                     : 'bg-blue-600 text-white hover:bg-blue-700'
                  }`}
                >
                   {loading ? (
                     <div className="w-5 h-5 border-2 border-white border-t-transparent animate-spin rounded-full" />
                   ) : (
                     <><SparklesIcon className="h-5 w-5 text-yellow-400" /> Ativar Comunidade</>
                   )}
                </button>
             </div>
          </div>
       </div>
    </div>
  );
};

