import React, { useState, useEffect, useMemo } from 'react';
import { User, ChatConversation, ChatType } from '../types';
// Fix: DEFAULT_PROFILE_PIC is not exported from storageService, importing from constants
import { getUsers, createGroup, findUserById } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  ArrowLeftIcon, 
  UserGroupIcon, 
  MagnifyingGlassIcon, 
  CheckIcon, 
  XMarkIcon,
  SparklesIcon,
  CameraIcon
} from '@heroicons/react/24/solid';

interface CreateGroupPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
}

const CreateGroupPage: React.FC<CreateGroupPageProps> = ({ currentUser, onNavigate }) => {
  const [groupName, setGroupName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedMembers, setSelectedMembers] = useState<string[]>([]);
  const [followers, setFollowers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const loadFollowers = async () => {
      // No contexto desta rede social, professores costumam criar grupos com seus alunos (seguidores)
      // Carregamos todos os usuários e filtramos aqueles que seguem o professor
      const allUsers = await getUsers();
      const myFollowers = allUsers.filter(u => u.followedUsers?.includes(currentUser.id));
      setFollowers(myFollowers);
    };
    loadFollowers();
  }, [currentUser.id]);

  const filteredFollowers = useMemo(() => {
    return followers.filter(f => 
      `${f.firstName} ${f.lastName}`.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [followers, searchTerm]);

  const toggleMember = (id: string) => {
    if (selectedMembers.includes(id)) {
      setSelectedMembers(selectedMembers.filter(m => m !== id));
    } else {
      setSelectedMembers([...selectedMembers, id]);
    }
  };

  const handleCreate = async () => {
    if (!groupName.trim() || selectedMembers.length === 0) {
      alert("Defina um nome para o grupo e selecione ao menos um membro.");
      return;
    }

    setLoading(true);
    try {
      const newGroup = await createGroup(groupName.trim(), selectedMembers, currentUser.id);
      onNavigate('chat');
    } catch (error) {
      alert("Erro ao criar grupo.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mx-auto px-4 pt-24 pb-32 max-w-2xl animate-fade-in">
       <button 
         onClick={() => onNavigate('profile')}
         className="flex items-center gap-2 text-gray-500 hover:text-blue-600 font-black text-[10px] uppercase tracking-widest mb-8 transition-colors"
       >
          <ArrowLeftIcon className="h-4 w-4" /> Voltar ao Perfil
       </button>

       <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
          <div className="p-8 md:p-12 space-y-10">
             <div className="text-center">
                <div className="relative inline-block mb-6">
                   <div className="w-24 h-24 md:w-32 md:h-32 bg-blue-50 dark:bg-blue-900/10 rounded-[2.5rem] md:rounded-[3.5rem] flex items-center justify-center border-4 border-white dark:border-darkcard shadow-xl">
                      <UserGroupIcon className="h-12 w-12 md:h-16 md:w-16 text-blue-600" />
                   </div>
                   <button className="absolute bottom-1 right-1 bg-white dark:bg-darkcard p-2 rounded-xl shadow-lg border border-gray-100 dark:border-white/10 text-gray-400 hover:text-blue-600">
                      <CameraIcon className="h-4 w-4" />
                   </button>
                </div>
                <h2 className="text-2xl md:text-4xl font-black dark:text-white uppercase tracking-tighter">Nova Comunidade</h2>
                <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest mt-2">Organize seus alunos em grupos exclusivos</p>
             </div>

             <div className="space-y-6">
                <div className="space-y-2">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-4">Nome do Grupo</label>
                   <input 
                     type="text" 
                     value={groupName}
                     onChange={e => setGroupName(e.target.value)}
                     placeholder="Ex: Mentoria Elite 2024"
                     className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-3xl outline-none font-black text-lg dark:text-white border-2 border-transparent focus:border-blue-600 transition-all shadow-inner"
                   />
                </div>

                <div className="space-y-4">
                   <div className="flex items-center justify-between px-4">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Selecionar Membros</label>
                      <span className="text-[10px] font-black text-blue-600 uppercase">{selectedMembers.length} Selecionados</span>
                   </div>

                   <div className="relative">
                      <MagnifyingGlassIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                      <input 
                        type="text" 
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        placeholder="Buscar aluno por nome..."
                        className="w-full pl-12 pr-6 py-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white border border-gray-100 dark:border-white/5"
                      />
                   </div>

                   <div className="max-h-64 overflow-y-auto custom-scrollbar space-y-2 pr-2">
                      {filteredFollowers.length === 0 ? (
                        <div className="p-10 text-center text-gray-400 uppercase font-black text-[9px] border-2 border-dashed border-gray-50 dark:border-white/5 rounded-2xl">
                           Nenhum aluno encontrado
                        </div>
                      ) : (
                        filteredFollowers.map(follower => (
                           <div 
                             key={follower.id}
                             onClick={() => toggleMember(follower.id)}
                             className={`flex items-center justify-between p-4 rounded-2xl cursor-pointer transition-all border ${
                               selectedMembers.includes(follower.id) 
                                ? 'bg-blue-50 dark:bg-blue-600/10 border-blue-200 dark:border-blue-500/30' 
                                : 'bg-white dark:bg-darkcard border-gray-50 dark:border-white/5 hover:bg-gray-50 dark:hover:bg-white/5'
                             }`}
                           >
                              <div className="flex items-center gap-4">
                                 <img src={follower.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover shadow-sm" />
                                 <div>
                                    <p className="font-black text-xs dark:text-white uppercase truncate max-w-[150px]">{follower.firstName} {follower.lastName}</p>
                                    <p className="text-[8px] font-bold text-gray-400 uppercase">{follower.credentials || 'Aluno CyBer'}</p>
                                 </div>
                              </div>
                              <div className={`w-6 h-6 rounded-lg flex items-center justify-center border-2 transition-all ${selectedMembers.includes(follower.id) ? 'bg-blue-600 border-blue-600 text-white' : 'border-gray-200'}`}>
                                 {selectedMembers.includes(follower.id) && <CheckIcon className="h-4 w-4" />}
                              </div>
                           </div>
                        ))
                      )}
                   </div>
                </div>
             </div>

             <div className="pt-6 border-t border-gray-100 dark:border-white/5">
                <button 
                  onClick={handleCreate}
                  disabled={loading || !groupName.trim() || selectedMembers.length === 0}
                  className={`w-full py-5 rounded-[2rem] font-black text-sm uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 ${
                    loading || !groupName.trim() || selectedMembers.length === 0 
                     ? 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none' 
                     : 'bg-blue-600 text-white hover:bg-blue-700'
                  }`}
                >
                   {loading ? (
                     <div className="w-5 h-5 border-2 border-white border-t-transparent animate-spin rounded-full" />
                   ) : (
                     <><SparklesIcon className="h-5 w-5 text-yellow-400" /> Ativar Comunidade</>
                   )}
                </button>
             </div>
          </div>
       </div>
    </div>
  );
};

