export const updatePostLikes = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
  if (data) {
    let likes = data.likes || [];
    if (likes.includes(userId)) likes = likes.filter((id: string) => id !== userId);
    else {
      likes.push(userId);
      await createNotification({ type: NotificationType.LIKE, recipientId: data.user_id, actorId: userId, postId, timestamp: Date.now() });
    }
    await supabase.from('posts').update({ likes }).eq('id', postId);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (data) {
    let saves = data.saves || [];
    if (saves.includes(userId)) saves = saves.filter((id: string) => id !== userId);
    else saves.push(userId);
    await supabase.from('posts').update({ saves }).eq('id', postId);
  }
};

export const deletePost = async (postId: string) => {
  await supabase.from('posts').delete().eq('id', postId);
};

export const pinPost = async (postId: string, userId: string) => {
  await supabase.from('posts').update({ is_pinned: false }).eq('user_id', userId);
  await supabase.from('posts').update({ is_pinned: true }).eq('id', postId);
};

export const unpinPost = async (postId: string, userId: string) => {
  await supabase.from('posts').update({ is_pinned: false }).eq('id', postId);
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('shares').eq('id', postId).single();
  if (data) {
    const shares = data.shares || [];
    if (!shares.includes(userId)) {
      shares.push(userId);
      await supabase.from('posts').update({ shares }).eq('id', postId);
    }
  }
};

export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const curr = await findUserById(currentUserId);
  const target = await findUserById(userIdToFollow);
  if (!curr || !target) return;

  let followed = curr.followedUsers || [];
  let followers = target.followers || [];

  if (followed.includes(userIdToFollow)) {
    followed = followed.filter(id => id !== userIdToFollow);
    followers = followers.filter(id => id !== currentUserId);
  } else {
    followed.push(userIdToFollow);
    followers.push(currentUserId);
    await createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
  }

  await supabase.from('profiles').update({ followed_users: followed }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: followers }).eq('id', userIdToFollow);
};

export const updateUserBalance = async (id: string, amount: number) => {
    const { data } = await supabase.from('profiles').select('balance').eq('id', id).single();
    if (data) {
        const newBalance = (data.balance || 0) + amount;
        await supabase.from('profiles').update({ balance: newBalance }).eq('id', id);

        await supabase.from('transactions').insert({
          id: generateUUID(),
          user_id: id,
          amount: Math.abs(amount),
          type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
          description: amount > 0 ? 'Depósito de fundos' : 'Saque/Compra de fundos',
          timestamp: Date.now(),
          status: 'COMPLETED'
        });
    }
};

export const updatePostSharesInternal = async (postId: string, userId: string) => {
  await updatePostShares(postId, userId);
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const { data } = await supabase.from('posts').select('comments, user_id').eq('id', postId).single();
  if (data) {
    const comments = [...(data.comments || []), comment];
    await supabase.from('posts').update({ comments }).eq('id', postId);
    await createNotification({ type: NotificationType.COMMENT, recipientId: data.user_id, actorId: comment.userId, postId, timestamp: Date.now() });
  }
};

export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2)}.jpg`;
  const { data, error } = await supabase.storage.from('cyberphone').upload(fileName, file);
  if (error) {
    return URL.createObjectURL(file);
  }
  const { data: { publicUrl } } = supabase.storage.from('cyberphone').getPublicUrl(fileName);
  return publicUrl;
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Post, AdCampaign, PostType, Story, CyberEvent, ChatConversation } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents, getChats, joinGroup } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import GroupDiscoveryCard from './GroupDiscoveryCard';
import { PlusIcon, ArrowPathIcon, RocketLaunchIcon, ChevronUpIcon, FireIcon, SparklesIcon, CalendarIcon, UserGroupIcon, StarIcon, ArrowTrendingUpIcon } from '@heroicons/react/24/outline';
import { TrophyIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<(Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[]>([]);
  const [visibleItems, setVisibleItems] = useState<(Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [stories, setStories] = useState<Story[]>([]);
  const [upcomingEvents, setUpcomingEvents] = useState<CyberEvent[]>([]);
  const [sidebarAds, setSidebarAds] = useState<AdCampaign[]>([]);

  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async (isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    const [allPosts, allAds, allUsers, allEvents, allStories, allChats] = await Promise.all([
      getPosts(),
      getAds(),
      getUsers(),
      getEvents(),
      getStories(),
      getChats()
    ]);

    const sortedPosts = allPosts.sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;
        const aBoosted = a.isBoosted && a.boostExpires && a.boostExpires > Date.now();
        const bBoosted = b.isBoosted && b.boostExpires && b.boostExpires > Date.now();
        if (aBoosted && !bBoosted) return -1;
        if (!aBoosted && bBoosted) return 1;
        return b.timestamp - a.timestamp;
    });

    const activeAds = allAds.filter(a => a.isActive).sort((a, b) => (b.budget || 0) - (a.budget || 0));
    const publicGroups = allChats.filter(c => c.type === 'GROUP' && c.isPublic && !c.participants.includes(currentUser.id)).slice(0, 3);

    setUpcomingEvents(allEvents.filter(e => e.dateTime > Date.now()).slice(0, 3));
    setSidebarAds(activeAds.slice(0, 2));
    setStories(allStories);

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);
    setSuggestedUsers(suggestions);

    let combined: (Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[] = [];
    let adPointer = 0;
    let groupPointer = 0;

    sortedPosts.forEach((post, idx) => {
        combined.push(post);
        if (idx === 0 && suggestions.length > 0) combined.push({ type: 'SUGGESTIONS' });
        if ((idx + 1) % 4 === 0 && adPointer < activeAds.length) {
            combined.push(activeAds[adPointer]);
            adPointer++;
        }
        if ((idx + 1) % 7 === 0 && groupPointer < publicGroups.length) {
            combined.push(publicGroups[groupPointer]);
            groupPointer++;
        }
    });

    setAllItems(combined);
    setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
    setDisplayLimit(ITEMS_PER_PAGE);
    setLoading(false);
  }, [currentUser]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  useEffect(() => {
    const handleScroll = () => setShowScrollTop(window.scrollY > 1000);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleJoin = async (groupId: string) => {
    await joinGroup(groupId, currentUser.id);
    loadData(true);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);
  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-8 relative">
      <div className="fixed bottom-24 right-6 z-[60] flex flex-col gap-3">
        {showScrollTop && (
          <button onClick={scrollToTop} className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all">
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button onClick={() => onNavigate('ads')} className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all">
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      <div className="flex gap-4 overflow-x-auto pb-6 pt-2 no-scrollbar mb-4">
         <div onClick={() => setIsCreatingStory(true)} className="flex-shrink-0 w-20 h-32 bg-white dark:bg-darkcard rounded-2xl shadow-md border border-dashed border-blue-300 dark:border-blue-900/50 flex flex-col items-center justify-center cursor-pointer group hover:border-blue-500 transition-all">
            <div className="bg-blue-50 dark:bg-white/5 p-2 rounded-full mb-2 group-hover:bg-blue-600 group-hover:text-white transition-colors">
               <PlusIcon className="h-5 w-5 text-blue-600 group-hover:text-white" />
            </div>
            <span className="text-[9px] font-black uppercase text-gray-400 group-hover:text-blue-600">Criar</span>
         </div>

         {stories.map((story, i) => (
            <div key={i} onClick={() => setSelectedStoryIndex(i)} className="flex-shrink-0 w-20 h-32 rounded-2xl overflow-hidden relative cursor-pointer group shadow-lg border-2 border-transparent hover:border-blue-500 transition-all">
               <img src={story.items[0]?.imageUrl || story.userProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
               <div className="absolute bottom-2 left-2 right-2 text-center">
                  <p className="text-[8px] font-black text-white uppercase truncate">{story.userName.split(' ')[0]}</p>
               </div>
               <div className="absolute top-2 left-2 w-6 h-6 rounded-full border-2 border-blue-600 overflow-hidden">
                  <img src={story.userProfilePic} className="w-full h-full object-cover" />
               </div>
            </div>
         ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Sincronizando Feed...</p>
              </div>
            ) : (
              <>
                {visibleItems.map((item: any, idx) => {
                  if (item.authorName) { // Is Post
                    return <PostCard key={item.id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
                  }
                  if (item.professorId) { // Is Ad
                    return <AdCard key={item.id} ad={item as AdCampaign} rank={idx} />;
                  }
                  if (item.type === 'GROUP') { // Is Group Discovery
                    return <GroupDiscoveryCard key={item.id} group={item} onJoin={() => handleJoin(item.id)} />;
                  }
                  if (item.type === 'SUGGESTIONS') {
                    return (
                      <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden animate-fade-in">
                         <SparklesIcon className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10" />
                         <div className="flex items-center justify-between mb-8">
                            <div>
                               <h4 className="font-black text-2xl tracking-tighter flex items-center gap-3"><FireIcon className="h-8 w-8 text-yellow-400" /> Networking</h4>
                               <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Sugestões de Conexão CyBer</p>
                            </div>
                            <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><ArrowPathIcon className="h-6 w-6"/></button>
                         </div>
                         <div className="flex gap-5 overflow-x-auto pb-4 no-scrollbar">
                            {suggestedUsers.map(u => (
                              <div key={u.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] min-w-[180px] flex flex-col items-center text-center border border-white/10 group">
                                 <img src={u.profilePicture} className="w-20 h-20 rounded-2xl object-cover mb-3 border-2 border-white/20 shadow-xl group-hover:scale-110 transition-transform" />
                                 <p className="font-black text-sm truncate w-full">{u.firstName} {u.lastName}</p>
                                 <p className="text-[8px] font-black text-blue-200 uppercase mb-4 tracking-tighter">{u.credentials || 'Especialista'}</p>
                                 <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-800 py-2.5 rounded-xl font-black text-[9px] uppercase shadow-lg active:scale-95 transition-all">Seguir</button>
                              </div>
                            ))}
                         </div>
                      </div>
                    );
                  }
                  return null;
                })}

                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Buscando mais conteúdos...</p>
                    </>
                  )}
                  {isAtEnd && (
                    <div className="flex flex-col items-center gap-3 opacity-60 py-10">
                       <CheckCircleIcon className="h-10 w-10 text-green-500" />
                       <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Você chegou ao fim do seu feed!</p>
                       <button onClick={scrollToTop} className="text-blue-600 text-[9px] font-black uppercase underline tracking-widest mt-2">Voltar para o topo</button>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </main>

        <aside className="hidden lg:block lg:col-span-4 space-y-6">
           <div className="sticky top-24 space-y-6">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden group">
                 <RocketLaunchIcon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-4 flex items-center gap-2">
                    <TrophyIcon className="h-6 w-6 text-yellow-400" /> Meta Profissional
                 </h3>
                 <div className="mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2">
                       <span>Progresso</span>
