import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType, ChatConversation } from '../types';
import { addPost, updatePost, uploadFile, generateUUID, getChats } from '../services/storageService';
import { 
  VideoCameraIcon, 
  PhotoIcon, 
  XMarkIcon, 
  PlusIcon,
  ChevronDownIcon,
  UserGroupIcon,
  GlobeAmericasIcon,
  FilmIcon
} from '@heroicons/react/24/solid';

interface CreatePostProps {
  currentUser: User;
  onPostCreated: () => void;
  refreshUser: () => void;
  postId?: string;
  onCancel?: () => void;
}

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);

  const [selectedGroup, setSelectedGroup] = useState<{id?: string, name: string}>({ name: 'Feed Geral' });
  const [myGroups, setMyGroups] = useState<ChatConversation[]>([]);
  const [showGroupSelector, setShowGroupSelector] = useState(false);

  const [loading, setLoading] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;

  useEffect(() => {
    const loadMyGroups = async () => {
       const allChats = await getChats();
       const groups = allChats.filter(c => c.type === 'GROUP' && c.participants.includes(currentUser.id));
       setMyGroups(groups);
    };
    loadMyGroups();
  }, [currentUser.id]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImageUrl(URL.createObjectURL(file));
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file)); 
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      let finalImageUrl = imageUrl;
      let finalReelUrl = reelUrl;

      if (postType === PostType.IMAGE && imageFile) {
        finalImageUrl = await uploadFile(imageFile, 'posts');
      }

      if (postType === PostType.REEL && reelFile) {
        finalReelUrl = await uploadFile(reelFile, 'reels');
      }

      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        type: postType,
        timestamp: Date.now(),
        content: content,
        imageUrl: postType === PostType.IMAGE ? finalImageUrl : undefined,
        groupId: selectedGroup.id,
        groupName: selectedGroup.id ? selectedGroup.name : undefined,
        reel: postType === PostType.REEL ? { videoUrl: finalReelUrl, description: content } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: []
      };

      if (isEditing) await updatePost(postData);
      else await addPost(postData);

      onPostCreated();
      if (!isEditing) {
        setIsExpanded(false);
        setContent('');
        setImageUrl('');
        setReelUrl('');
        setImageFile(null);
        setReelFile(null);
        setSelectedGroup({ name: 'Feed Geral' });
      }
    } catch (err) {
      console.error(err);
      alert('Erro ao salvar postagem.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-4 shadow-sm">
         <div className="flex items-center gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-3 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-sm">
              O que você está pensando, {currentUser.firstName}?
            </button>
         </div>
         <div className="flex gap-6 px-2 border-t border-gray-50 dark:border-white/5 pt-4">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); }} className="flex items-center gap-2 text-gray-500 text-[10px] font-black uppercase tracking-widest"><PhotoIcon className="h-5 w-5 text-blue-500" /> Imagem</button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex items-center gap-2 text-gray-500 text-[10px] font-black uppercase tracking-widest"><FilmIcon className="h-5 w-5 text-purple-500" /> Reel</button>
         </div>
      </div>
    );
  }

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-8 md:p-10 border dark:border-white/5 animate-fade-in relative">
      <div className="flex items-center justify-between mb-8">
        <div className="flex flex-col">
           <h3 className="font-black text-gray-900 dark:text-white uppercase text-xs tracking-[0.2em]">Criar Conteúdo</h3>
           {/* Selector de Destino */}
           <div className="relative mt-2">
              <button 
                type="button"
                onClick={() => setShowGroupSelector(!showGroupSelector)}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 dark:bg-blue-900/20 text-blue-600 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all hover:bg-blue-100"
              >
                 {selectedGroup.id ? <UserGroupIcon className="h-3 w-3" /> : <GlobeAmericasIcon className="h-3 w-3" />}
                 {selectedGroup.name}
                 <ChevronDownIcon className={`h-3 w-3 transition-transform ${showGroupSelector ? 'rotate-180' : ''}`} />
              </button>

              {showGroupSelector && (
                <div className="absolute top-full left-0 mt-2 w-56 bg-white dark:bg-[#1a1c23] border border-gray-100 dark:border-white/10 rounded-2xl shadow-2xl z-[110] p-2 animate-fade-in">
                   <button 
                    onClick={() => { setSelectedGroup({ name: 'Feed Geral' }); setShowGroupSelector(false); }}
                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                   >
                      <GlobeAmericasIcon className="h-4 w-4 text-gray-400" />
                      <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">Feed Geral</span>
                   </button>
                   {myGroups.map(group => (
                     <button 
                      key={group.id}
                      onClick={() => { setSelectedGroup({ id: group.id, name: group.groupName! }); setShowGroupSelector(false); }}
                      className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                     >
                        <UserGroupIcon className="h-4 w-4 text-blue-600" />
                        <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{group.groupName}</span>
                     </button>
                   ))}
                </div>
              )}
           </div>
        </div>
        <button onClick={() => setIsExpanded(false)} className="p-2 bg-gray-100 dark:bg-white/10 rounded-xl"><XMarkIcon className="h-6 w-6 text-gray-400" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Lógica de formulário mantida */}
        <textarea 
          value={content} 
          onChange={e => setContent(e.target.value)} 
          className="w-full p-8 bg-gray-50 dark:bg-white/5 rounded-[2rem] outline-none font-bold text-xl min-h-[200px]" 
          placeholder={selectedGroup.id ? `Mensagem para os membros de ${selectedGroup.name}...` : "No que está pensando?"} 
        />

        {postType === PostType.IMAGE && (
          <div onClick={() => imageInputRef.current?.click()} className="w-full h-64 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-all overflow-hidden bg-gray-50 dark:bg-white/5">
            {imageUrl ? <img src={imageUrl} className="w-full h-full object-cover" /> : <PhotoIcon className="h-12 w-12 text-gray-300" />}
            <input type="file" ref={imageInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
          </div>
        )}

        <button type="submit" disabled={loading} className="w-full py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase text-xs shadow-xl disabled:opacity-50 active:scale-95 transition-all">
          {loading ? 'Publicando...' : 'Publicar Agora'}
        </button>
      </form>
    </div>
  );
};

export default CreatePost;

import React, { useState, useEffect, useMemo } from 'react';
import { Notification, User, Post, NotificationType } from '../types';
import { getNotificationsForUser, findUserById, getPosts, toggleFollowUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { HeartIcon, ChatBubbleOvalLeftIcon, UserPlusIcon, CurrencyDollarIcon, StarIcon, EnvelopeIcon, RocketLaunchIcon, ShareIcon, UserGroupIcon } from '@heroicons/react/24/solid';

interface NotificationsPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const timeAgo = (timestamp: number): string => {
  const now = new Date();
  const secondsPast = (now.getTime() - timestamp) / 1000;

  if (secondsPast < 60) return `${Math.round(secondsPast)}s atrás`;
  if (secondsPast < 3600) return `${Math.round(secondsPast / 60)}m atrás`;
  if (secondsPast <= 86400) return `${Math.round(secondsPast / 3600)}h atrás`;
  const days = Math.round(secondsPast / 86400);
  if (days <= 7) return `${days}d atrás`;
  return new Date(timestamp).toLocaleDateString();
};

const NotificationItem: React.FC<{ notification: Notification; onNavigate: Function; refreshUser: Function; currentUser: User; allPosts: Post[] }> = ({ notification, onNavigate, refreshUser, currentUser, allPosts }) => {
  const [actor, setActor] = useState<User | null>(null);

  useEffect(() => {
    const fetchActor = async () => {
      const user = await findUserById(notification.actorId);
      setActor(user || null);
    };
    fetchActor();
  }, [notification.actorId]);

  const post = notification.postId ? allPosts.find(p => p.id === notification.postId) : null;
  const isFollowingActor = actor && currentUser.followedUsers.includes(actor.id);

  if (!actor) return null;

  const handleFollowToggle = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, actor.id);
    refreshUser();
  };

  const handleNavigation = () => {
    if (notification.type === NotificationType.MESSAGE) {
      onNavigate('chat');
    } else if (notification.postId && post) {
      onNavigate('feed'); 
    } else if (notification.type === NotificationType.NEW_FOLLOWER) {
      onNavigate('profile', { userId: actor.id });
    }
  };

  const renderIcon = () => {
    switch (notification.type) {
      case NotificationType.LIKE: return <HeartIcon className="h-6 w-6 text-white bg-red-500 rounded-full p-1" />;
      case NotificationType.COMMENT: return <ChatBubbleOvalLeftIcon className="h-6 w-6 text-white bg-blue-500 rounded-full p-1" />;
      case NotificationType.NEW_FOLLOWER: return <UserPlusIcon className="h-6 w-6 text-white bg-green-500 rounded-full p-1" />;
      case NotificationType.GROUP_POST: return <UserGroupIcon className="h-6 w-6 text-white bg-blue-600 rounded-full p-1" />;
      case NotificationType.INDICATION: return <ShareIcon className="h-6 w-6 text-white bg-blue-600 rounded-full p-1" />;
      default: return <StarIcon className="h-6 w-6 text-white bg-purple-500 rounded-full p-1" />;
    }
  };

  const renderMessage = () => {
    const actorName = <strong className="font-semibold">{`${actor.firstName} ${actor.lastName}`}</strong>;
    switch (notification.type) {
      case NotificationType.LIKE: return <>{actorName} curtiu sua publicação.</>;
      case NotificationType.COMMENT: return <>{actorName} comentou em sua publicação.</>;
      case NotificationType.NEW_FOLLOWER: return <>{actorName} começou a seguir você.</>;
      case NotificationType.GROUP_POST: return <>{actorName} publicou um novo conteúdo no grupo <strong className="text-blue-600">{notification.groupName}</strong>.</>;
      case NotificationType.INDICATION: return <>{actorName} indicou uma aula para você.</>;
      default: return 'Nova notificação.';
    }
  };

  return (
    <div onClick={handleNavigation} className="flex items-center p-3 space-x-4 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-white/5 transition-colors duration-200">
      <div className="relative">
        <img src={actor.profilePicture || DEFAULT_PROFILE_PIC} alt={actor.firstName} className="w-12 h-12 rounded-full object-cover" />
        <div className="absolute -bottom-1 -right-1">{renderIcon()}</div>
      </div>
      <div className="flex-1">
        <p className="text-sm text-gray-800 dark:text-gray-200">{renderMessage()}</p>
        <span className="text-xs text-gray-500">{timeAgo(notification.timestamp)}</span>
      </div>
      {post && post.imageUrl && (
        <img src={post.imageUrl} alt="Post thumbnail" className="w-12 h-12 object-cover rounded-md" />
      )}
    </div>
  );
};

const NotificationsPage: React.FC<NotificationsPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [allPosts, setAllPosts] = useState<Post[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
        setLoading(true);
        const userNotifications = await getNotificationsForUser(currentUser.id);
        setNotifications(userNotifications);
        const posts = await getPosts();
        setAllPosts(posts); 
        setLoading(false);
    };
    fetchData();
  }, [currentUser.id]);

  const groupedNotifications = useMemo(() => {
    const groups: { [key: string]: Notification[] } = {
      "Recentes": [],
      "Mais Antigas": [],
    };
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

    notifications.forEach(n => {
      if (n.timestamp >= today) groups["Recentes"].push(n);
      else groups["Mais Antigas"].push(n);
    });

    return groups;
  }, [notifications]);

  if (loading) {
    return <div className="p-8 text-center dark:text-gray-400">Carregando notificações...</div>;
  }

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 md:pb-8">
