  const { data } = await supabase.from('posts').select('comments, user_id').eq('id', postId).single();
  if (data) {
    const comments = [...(data.comments || []), comment];
    await supabase.from('posts').update({ comments }).eq('id', postId);
    await createNotification({ type: NotificationType.COMMENT, recipientId: data.user_id, actorId: comment.userId, postId, timestamp: Date.now() });
