export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const { data } = await supabase.from('chats')
    .select('*')
    .eq('type', ChatType.PRIVATE)
    .contains('participants', [u1, u2])
    .maybeSingle();

  if (data) {
    return {
      id: data.id,
      type: data.type as ChatType,
      participants: data.participants,
      messages: data.messages || [],
      theme: 'blue'
    };
  }

  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.PRIVATE,
    participants: [u1, u2],
    messages: [],
    theme: 'blue'
  };

  await supabase.from('chats').insert({
    id: newChat.id,
    type: newChat.type,
    participants: newChat.participants,
    messages: [],
    theme: 'blue'
  });

  return newChat;
};

