export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const curr = await findUserById(currentUserId);
  const target = await findUserById(userIdToFollow);
  if (!curr || !target) return;

  let followed = curr.followedUsers || [];
  let followers = target.followers || [];

  if (followed.includes(userIdToFollow)) {
    followed = followed.filter(id => id !== userIdToFollow);
    followers = followers.filter(id => id !== currentUserId);
  } else {
    followed.push(userIdToFollow);
    followers.push(currentUserId);
    await createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
  }

  await supabase.from('profiles').update({ followed_users: followed }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: followers }).eq('id', userIdToFollow);
};

export const updateUserBalance = async (id: string, amount: number) => {
    const { data } = await supabase.from('profiles').select('balance').eq('id', id).single();
    if (data) {
        const newBalance = (data.balance || 0) + amount;
        await supabase.from('profiles').update({ balance: newBalance }).eq('id', id);

        await supabase.from('transactions').insert({
          id: generateUUID(),
          user_id: id,
          amount: Math.abs(amount),
          type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
          description: amount > 0 ? 'Depósito de fundos' : 'Saque/Compra de fundos',
          timestamp: Date.now(),
          status: 'COMPLETED'
        });
        return true;
    }
    return false;
};

