export const addPost = async (post: Post) => {
  await supabase.from('posts').insert({
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    group_id: post.groupId,
    group_name: post.groupName,
    timestamp: post.timestamp,
    likes: post.likes,
    comments: post.comments,
    shares: post.shares,
    saves: post.saves,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires,
    live_data: post.liveStream,
    reel_data: post.reel,
    background_color: post.backgroundColor,
    text_color: post.textColor,
    font_family: post.fontFamily,
    font_size: post.fontSize
  });

  if (post.groupId) {
    const chat = await findChatById(post.groupId);
    if (chat) {
      const participants = chat.participants.filter(p => p !== post.userId);
      for (const pId of participants) {
        await createNotification({
          type: NotificationType.GROUP_POST,
          recipientId: pId,
          actorId: post.userId,
          postId: post.id,
          timestamp: Date.now(),
          groupName: post.groupName
        });
      }
    }
  }
};

