export const getChats = async (): Promise<ChatConversation[]> => {
  const { data, error } = await supabase.from('chats').select('*');
  if (error) return [];
  return (data || []).map(c => ({
    id: c.id,
    type: c.type as ChatType,
    participants: c.participants || [],
    messages: c.messages || [],
    groupName: c.group_name,
    groupImage: c.group_image,
    adminId: c.admin_id,
    isPublic: c.is_public || false,
    description: c.description,
    theme: c.theme as GroupTheme || 'blue'
  }));
};

export const findChatById = async (id: string): Promise<ChatConversation | undefined> => {
  const { data } = await supabase.from('chats').select('*').eq('id', id).maybeSingle();
  if (!data) return undefined;
  return {
    id: data.id,
    type: data.type as ChatType,
    participants: data.participants || [],
    messages: data.messages || [],
    groupName: data.group_name,
    groupImage: data.group_image,
    adminId: data.admin_id,
    isPublic: data.is_public,
    description: data.description,
    theme: data.theme as GroupTheme || 'blue'
  };
};

export const getOrCreateConversation = async (u1: string, u2: string): Promise<ChatConversation> => {
  const { data } = await supabase.from('chats')
    .select('*')
    .eq('type', ChatType.PRIVATE)
    .contains('participants', [u1, u2])
    .maybeSingle();

  if (data) {
    return {
      id: data.id,
      type: data.type as ChatType,
      participants: data.participants,
      messages: data.messages || [],
      theme: 'blue'
    };
  }

  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.PRIVATE,
    participants: [u1, u2],
    messages: [],
    theme: 'blue'
  };

  await supabase.from('chats').insert({
    id: newChat.id,
    type: newChat.type,
    participants: newChat.participants,
    messages: [],
    theme: 'blue'
  });

  return newChat;
};

export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme: GroupTheme = 'blue'): Promise<ChatConversation> => {
  const chat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.GROUP,
    groupName: name,
    participants: [...new Set([...members, adminId])],
    messages: [],
    adminId,
    isPublic: true, 
    description,
    groupImage: `https://picsum.photos/200/200?random=${Math.random()}`,
    theme
  };
  await supabase.from('chats').insert({
    id: chat.id,
    type: chat.type,
    group_name: chat.groupName,
    participants: chat.participants,
    admin_id: chat.adminId,
    group_image: chat.groupImage,
    is_public: chat.isPublic,
    description: chat.description,
    messages: [],
    theme: chat.theme
  });
  return chat;
};

export const updateGroupTheme = async (groupId: string, theme: GroupTheme) => {
  await supabase.from('chats').update({ theme }).eq('id', groupId);
};

export const joinGroup = async (groupId: string, userId: string) => {
  const chat = await findChatById(groupId);
  if (chat && !chat.participants.includes(userId)) {
    const updatedParticipants = [...chat.participants, userId];
    await supabase.from('chats').update({ participants: updatedParticipants }).eq('id', groupId);
  }
};

export const sendMessage = async (chatId: string, msg: Message) => {
  const chat = await findChatById(chatId);
  if (chat) {
    const updatedMessages = [...chat.messages, msg];
    await supabase.from('chats').update({ messages: updatedMessages }).eq('id', chatId);
  }
};

