export const addStory = async (uId: string, item: any) => {
  const user = await findUserById(uId);
  if (!user) return;

  const { data: existing } = await supabase.from('stories').select('*').eq('user_id', uId).maybeSingle();

  const newItem = {
    ...item,
    id: generateUUID(),
    timestamp: Date.now()
  };

  if (existing) {
    const updatedItems = [...(existing.items || []), newItem];
    await supabase.from('stories').update({ items: updatedItems }).eq('user_id', uId);
  } else {
    await supabase.from('stories').insert({
      user_id: uId,
      user_name: user.firstName,
      user_profile_pic: user.profilePicture,
      items: [newItem]
    });
  }
};

