    userId: p.user_id,
    authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Membro CyBer',
    authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
