export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  for (const item of cartItems) {
    const product = await findProductById(item.productId);
    if (!product) continue;
    const store = await findStoreById(product.storeId);
    if (!store) continue;

    const itemTotal = product.price * item.quantity;
    const commissionEarned = affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0;

    const newSale = {
      id: generateUUID(),
      product_id: item.productId,
      buyer_id: buyerId,
      affiliate_user_id: affiliateUserId || '',
      store_id: product.storeId,
      commission_earned: commissionEarned,
      sale_amount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      is_rated: false,
      shipping_address: shippingAddress,
      digital_content_url: product.digitalContentUrl
    };

    await supabase.from('affiliate_sales').insert(newSale);
    await updateUserBalance(store.professorId, itemTotal - commissionEarned);
    if (affiliateUserId) {
        await updateUserBalance(affiliateUserId, commissionEarned);
        await createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, timestamp: Date.now(), saleId: newSale.id });
    }
  }
  localStorage.setItem(CART_KEY, JSON.stringify([]));
  return true;
};

export const updateSaleStatus = async (saleId: string, status: OrderStatus) => {
  await supabase.from('affiliate_sales').update({ status }).eq('id', saleId);
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
  const { data: sale } = await supabase.from('affiliate_sales').select('*').eq('id', saleId).single();
  if (!sale || sale.is_rated) return;
  const product = await findProductById(sale.product_id);
  if (!product) return;
  const updatedRatings = [...(product.ratings || []), { id: generateUUID(), saleId, userId: sale.buyer_id, rating, comment, timestamp: Date.now() }];
  await supabase.from('products').update({ ratings: updatedRatings, rating_count: updatedRatings.length, average_rating: updatedRatings.reduce((sum, r) => sum + r.rating, 0) / updatedRatings.length }).eq('id', product.id);
  await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);
};

