import EventsPage from './EventsPage';
import PurchasesPage from './PurchasesPage';
import AffiliatesPage from './AffiliatesPage';
import CreateGroupPage from './CreateGroupPage';
import { ExclamationTriangleIcon } from '@heroicons/react/24/solid';
import { requestNotificationPermission } from '../services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates' | 'create-group';

const THEME_MAP: Record<GroupTheme, { primary: string, hover: string, light: string }> = {
  blue: { primary: '#2563eb', hover: '#1d4ed8', light: '#eff6ff' },
  green: { primary: '#10b981', hover: '#059669', light: '#ecfdf5' },
  black: { primary: '#18181b', hover: '#09090b', light: '#27272a' },
  orange: { primary: '#f97316', hover: '#ea580c', light: '#fff7ed' }
};

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [appTheme, setAppTheme] = useState<GroupTheme>(() => getAppTheme());
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    const changeAppTheme = useCallback((newTheme: GroupTheme) => {
        setAppTheme(newTheme);
        saveAppTheme(newTheme);
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');
                    requestNotificationPermission();
                } else {
                    setCurrentPage('auth');
                }
            } else {
                setCurrentPage('auth');
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, [currentPage]);

    useEffect(() => {
        refreshCurrentUser();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-brand mb-4"></div>
                <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Iniciando Ecossistema...</p>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-12 w-12 text-red-500 mb-4" />
                <h2 className="text-xl font-black uppercase mb-2">Ops! Ocorreu um erro</h2>
                <p className="text-gray-500 text-sm mb-6">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-brand text-white px-8 py-3 rounded-xl font-black uppercase text-xs">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={changeAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''}`}>
                    <div className="max-w-7xl mx-auto">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();

    const revealObserver = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        setIsVisible(true);
        if (cardRef.current) revealObserver.unobserve(cardRef.current);
      }
    }, { threshold: 0.1 });

    if (cardRef.current) revealObserver.observe(cardRef.current);
    return () => revealObserver.disconnect();
  }, [post.userId]);

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const hasLiked = post.likes?.includes(currentUser.id) || false;
  const hasSaved = post.saves?.includes(currentUser.id) || false;
  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();
    await updatePostLikes(post.id, currentUser.id);
    onPostUpdatedOrDeleted();
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        ref={cardRef}
        onClick={() => {
          if (post.type === PostType.LIVE) onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else setShowDetailModal(true);
        }}
        className={`bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group transform transition-all duration-[800ms] ${
          isVisible ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-12 scale-[0.98]'
        } hover:shadow-2xl hover:-translate-y-1`}
      >
        <div className="p-5 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-4 md:gap-5">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1.5 -right-1.5 bg-brand rounded-xl p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-4 w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-base md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-4 w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-4 w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1.5 text-[9px] font-black text-brand uppercase tracking-widest mt-0.5">
                     <UserGroupIcon className="h-3 w-3" /> {post.groupName}
                  </div>
                )}
              </div>
              <p className="text-[9px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-3 text-brand">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all"
          >
            <EllipsisHorizontalIcon className="h-7 w-7" />
          </button>
        </div>

        <div className={`px-5 md:px-8 ${hasBg ? 'pb-8' : 'pb-5 md:pb-8'}`}>
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[2.5rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-8 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-6 left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3.5 w-3.5" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-8 flex flex-col items-center text-center">
                   <h3 className="text-2xl md:text-4xl font-black mb-8 tracking-tighter uppercase">{post.liveStream.title}</h3>
                   <button className="bg-brand text-white px-10 py-5 rounded-[2.2rem] font-black text-[11px] md:text-sm uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-4">
                      <PlayIcon className="h-6 w-6" /> Entrar Agora
                   </button>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`rounded-[2.5rem] md:rounded-[4rem] mb-2 transition-all duration-700 flex items-center justify-center text-center ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    background: hasBg ? post.backgroundColor : 'transparent', 
                    color: post.textColor || 'inherit', 
                    fontSize: post.fontSize ? post.fontSize : '1.2rem', 
                    minHeight: hasBg ? '400px' : 'auto', 
                    padding: hasBg ? '3rem' : '0.5rem',
                  }}
                >
                  <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-2xl text-2xl md:text-3xl' : 'text-left w-full text-base md:text-lg'}`}>
                    {post.content}
                  </p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl mt-4">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-6 md:px-12 py-5 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-2 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${hasLiked ? 'text-brand bg-brand/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {hasLiked ? <HeartIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <HeartIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{post.likes?.length || 0}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ChatIconOutline className="h-6 w-6 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-4 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-6 w-6 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdatedOrDeleted(); }} className={`p-4 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${hasSaved ? 'text-brand bg-brand/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {hasSaved ? <BookmarkIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal isAuthor={isAuthor} isPinned={!!post.isPinned} onClose={() => setShowActionsModal(false)} onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} onReport={() => { createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); setShowActionsModal(false); }} />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}
      {showDeleteModal && <DeleteConfirmModal onClose={() => setShowDeleteModal(false)} onConfirm={() => { onPostUpdatedOrDeleted(); setShowDeleteModal(false); }} />}
      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

export default PostCard;

import React from 'react';

interface LogoProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  showText?: boolean;
  variant?: 'default' | 'white' | 'dark';
  onClick?: () => void;
}

const Logo: React.FC<LogoProps> = ({ 
  className = "", 
  size = 'md', 
  showText = true,
  variant = 'default',
  onClick
}) => {
  const sizes = {
    sm: 'h-4',
    md: 'h-6',
    lg: 'h-8',
    xl: 'h-10 md:h-12'
  };

  const textSizes = {
    sm: 'text-sm',
    md: 'text-lg',
    lg: 'text-xl',
    xl: 'text-2xl md:text-3xl'
  };

  const getTextColor = () => {
    if (variant === 'white') return 'text-white';
    if (variant === 'dark') return 'text-gray-900';
    return 'text-gray-900 dark:text-white';
  };

  return (
    <div 
      className={`flex items-center gap-2.5 ${className} ${onClick ? 'cursor-pointer' : ''}`}
      onClick={onClick}
    >
      <div className={`${sizes[size]} aspect-square relative`}>
        <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg" className="w-full h-full drop-shadow-lg">
          <defs>
            <linearGradient id="cyber-grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="var(--brand-color)" />
              <stop offset="100%" stopColor="var(--brand-hover)" />
            </linearGradient>
            <filter id="glow">
              <feGaussianBlur stdDeviation="2" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>

          <path 
            d="M80 25C72.5 15.5 61.5 10 49.5 10C27.6853 10 10 27.6853 10 49.5C10 71.3147 27.6853 89 49.5 89C61.5 89 72.5 83.5 80 74" 
            stroke="url(#cyber-grad)" 
            strokeWidth="12" 
            strokeLinecap="round"
          />

          <rect x="40" y="35" width="12" height="30" rx="6" fill="url(#cyber-grad)" filter="url(#glow)" />
          <path d="M52 35C60 35 66 41 66 49C66 57 60 63 52 63H40V35H52Z" fill="url(#cyber-grad)" opacity="0.8" />
          <circle cx="55" cy="50" r="8" stroke="white" strokeWidth="3" opacity="0.5" />
        </svg>
      </div>

      {showText && (
        <h1 className={`${textSizes[size]} font-black tracking-tighter transition-colors`}>
          <span className="text-brand">CyBer</span>
          <span className={getTextColor()}>Phone</span>
        </h1>
      )}
    </div>
  );
};

export default Logo;

import { supabase } from './supabaseClient';
import { 
  User, Post, ChatConversation, AdCampaign, UserType, Store, Product, 
  AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, 
  Notification, NotificationType, CartItem, ProductRating, OrderStatus, 
  CyberEvent, Story, ContentReport, SystemLog, Transaction, GlobalSettings, 
  TransactionType, Message, ChatType, GroupTheme
} from '../types';
import { DEFAULT_PROFILE_PIC, DEFAULT_AUDIO_TRACKS } from '../data/constants';

const CURRENT_USER_KEY = 'cyberphone_current_user_id';
const CART_KEY = 'cyberphone_cart';
const APP_THEME_KEY = 'cyberphone_app_theme';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

