  return data.map(p => ({
    id: p.id,
    userId: p.user_id,
    authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Membro CyBer',
    authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
    type: p.type as any,
    content: p.content,
    imageUrl: p.image_url,
    groupId: p.group_id,
    groupName: p.group_name,
    timestamp: p.timestamp,
    likes: p.likes || [],
    shares: p.shares || [],
    saves: p.saves || [],
    isPinned: p.is_pinned,
    isBoosted: p.is_boosted,
    boostExpires: p.boost_expires,
    liveStream: p.live_data,
    reel: p.reel_data,
    backgroundColor: p.background_color,
    textColor: p.text_color,
    fontFamily: p.font_family,
    fontSize: p.font_size,
    indicatedUserIds: p.indicated_user_ids || []
  }));
};

export const addPost = async (post: Post) => {
  await supabase.from('posts').insert({
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    group_id: post.groupId,
    group_name: post.groupName,
    timestamp: post.timestamp,
    likes: post.likes,
    comments: post.comments,
    shares: post.shares,
    saves: post.saves,
    is_pinned: post.isPinned,
    is_boosted: post.isBoosted,
    boost_expires: post.boostExpires,
    live_data: post.liveStream,
    reel_data: post.reel,
    background_color: post.backgroundColor,
    text_color: post.textColor,
    font_family: post.fontFamily,
    font_size: post.fontSize
  });

  if (post.groupId) {
    const chat = await findChatById(post.groupId);
    if (chat) {
      const participants = chat.participants.filter(p => p !== post.userId);
      for (const pId of participants) {
        await createNotification({
          type: NotificationType.GROUP_POST,
          recipientId: pId,
          actorId: post.userId,
          postId: post.id,
          timestamp: Date.now(),
          groupName: post.groupName
        });
      }
    }
  }
};

