export const createNotification = async (n: any) => {
  if (n.recipientId === n.actorId) return;
  await supabase.from('notifications').insert({
    id: generateUUID(),
    recipient_id: n.recipientId,
    actor_id: n.actorId,
    type: n.type,
    timestamp: n.timestamp,
    post_id: n.postId,
    sale_id: n.saleId,
    is_read: false,
    group_name: n.groupName
