const CURRENT_USER_KEY = 'cyberphone_current_user_id';
const CART_KEY = 'cyberphone_cart';
const APP_THEME_KEY = 'cyberphone_app_theme';

export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- TEMA GLOBAL DO SISTEMA ---
export const saveAppTheme = (theme: GroupTheme) => {
  localStorage.setItem(APP_THEME_KEY, theme);
};

export const getAppTheme = (): GroupTheme => {
  return (localStorage.getItem(APP_THEME_KEY) as GroupTheme) || 'blue';
};

// --- AUTHENTICATION ---
export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.from('profiles').select('*').eq('email', email).maybeSingle();
  if (error || !data) throw new Error('Credenciais inválidas.');
  return {
    id: data.id,
    email: data.email,
    firstName: data.first_name,
    lastName: data.last_name,
    userType: data.user_type as any,
    phone: data.phone,
    documentId: data.document_id,
    birthDate: data.birth_date,
    profilePicture: data.profile_picture,
    balance: data.balance,
    credentials: data.credentials,
    bio: data.bio,
    isAdmin: data.is_admin,
    isVerified: data.is_verified,
    isSuspended: data.is_suspended,
    followedUsers: data.followed_users || [],
    followers: data.followers || [],
    storeId: data.store_id
  } as any;
};

export const registerUser = async (userData: any): Promise<User> => {
  const id = generateUUID();
  const newUser: User = {
    id,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials,
    bio: userData.bio,
    verificationFileUrl: userData.verificationFileUrl
  };

  const { error } = await supabase.from('profiles').insert({
    id: newUser.id,
    email: newUser.email,
    first_name: newUser.firstName,
    last_name: newUser.lastName,
    user_type: newUser.userType,
    phone: newUser.phone,
    document_id: newUser.documentId,
    birth_date: newUser.birthDate,
    profile_picture: newUser.profilePicture,
    credentials: newUser.credentials,
    bio: newUser.bio,
    balance: 0,
    is_admin: false,
    is_verified: false,
    is_suspended: false,
    followed_users: [],
    followers: []
  });

  if (error) throw error;

  if (newUser.userType === UserType.CREATOR) {
    const storeId = generateUUID();
    await supabase.from('stores').insert({
      id: storeId,
      professor_id: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      product_ids: []
    });
    newUser.storeId = storeId;
    await supabase.from('profiles').update({ store_id: storeId }).eq('id', newUser.id);
  }

  return newUser;
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (!userId) return undefined;
  const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
  if (error || !data) return undefined;
  return {
    id: data.id,
    email: data.email,
    firstName: data.first_name,
    lastName: data.last_name,
    userType: data.user_type as any,
    phone: data.phone,
    documentId: data.document_id,
    birthDate: data.birth_date,
    profilePicture: data.profile_picture,
    balance: data.balance,
    credentials: data.credentials,
    bio: data.bio,
    isAdmin: data.is_admin,
    isVerified: data.is_verified,
    isSuspended: data.is_suspended,
    followedUsers: data.followed_users || [],
    followers: data.followers || [],
    storeId: data.store_id
  } as any;
};

export const updateUser = async (user: User) => {
  await supabase.from('profiles').update({
    first_name: user.firstName,
    last_name: user.lastName,
    email: user.email,
    phone: user.phone,
    credentials: user.credentials,
    bio: user.bio,
    profile_picture: user.profilePicture,
    birth_date: user.birthDate,
    balance: user.balance,
    is_admin: user.isAdmin,
    is_verified: user.isVerified,
    is_suspended: user.isSuspended,
    followed_users: user.followedUsers,
    followers: user.followers,
    store_id: user.storeId
  }).eq('id', user.id);
};

export const updateUserBalance = async (id: string, amount: number) => {
    const { data } = await supabase.from('profiles').select('balance').eq('id', id).single();
    if (data) {
        const newBalance = (data.balance || 0) + amount;
        await supabase.from('profiles').update({ balance: newBalance }).eq('id', id);
        return true;
    }
    return false;
};

export const getPosts = async (): Promise<Post[]> => {
  const { data, error } = await supabase
    .from('posts')
    .select(`*, profiles (first_name, last_name, profile_picture)`)
    .order('is_pinned', { ascending: false })
    .order('timestamp', { ascending: false });

  if (error || !data) return [];
  return data.map(p => ({
    id: p.id,
    userId: p.user_id,
    authorName: p.profiles ? `${p.profiles.first_name} ${p.profiles.last_name}` : 'Membro CyBer',
    authorProfilePic: p.profiles?.profile_picture || DEFAULT_PROFILE_PIC,
    type: p.type as any,
    content: p.content,
    imageUrl: p.image_url,
    groupId: p.group_id,
    groupName: p.group_name,
    timestamp: p.timestamp,
    likes: p.likes || [],
    shares: p.shares || [],
    saves: p.saves || [],
    isPinned: p.is_pinned,
    isBoosted: p.is_boosted,
    boostExpires: p.boost_expires,
    liveStream: p.live_data,
    reel: p.reel_data,
    backgroundColor: p.background_color,
    textColor: p.text_color,
    fontFamily: p.font_family,
    fontSize: p.font_size,
    indicatedUserIds: p.indicated_user_ids || []
  }));
};

