// Fix: Exporting addProductRating
export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const { data: sale } = await supabase.from('affiliate_sales').select('*').eq('id', saleId).single();
    if (!sale || sale.is_rated) return false;

    const { data: product } = await supabase.from('products').select('*').eq('id', sale.product_id).single();
    if (!product) return false;

    const newRating = { id: generateUUID(), saleId, userId: sale.buyer_id, rating, comment, timestamp: Date.now() };
    const ratings = [...(product.ratings || []), newRating];
    const ratingCount = ratings.length;
    const averageRating = ratings.reduce((sum: number, r: any) => sum + r.rating, 0) / ratingCount;

    await supabase.from('products').update({ ratings, rating_count: ratingCount, average_rating: averageRating }).eq('id', product.id);
    await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);
    return true;
};

