import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem, GlobalSettings, GroupTheme } from '../types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    getGlobalSettings,
    getAppTheme,
    saveAppTheme
} from '../services/storageService';
import Header from './Header';
import Footer from './Footer';
import AuthPage from './AuthPage';
import FeedPage from './FeedPage';
import ProfilePage from './ProfilePage';
import ChatPage from './ChatPage';
import AdCampaignPage from './AdCampaignPage';
import LiveStreamViewer from './LiveStreamViewer';
import { StorePage } from './StorePage';
import StoreManagerPage from './StoreManagerPage';
import ReelsPage from './ReelsPage';
import SearchResultsPage from './SearchResultsPage';
import NotificationsPage from './NotificationsPage';
import CartModal from './CartModal';
import WalletModal from './WalletModal';
import SettingsPage from './SettingsPage';
import AdminDashboard from './AdminDashboard';
import EventsPage from './EventsPage';
import PurchasesPage from './PurchasesPage';
import AffiliatesPage from './AffiliatesPage';
import CreateGroupPage from './CreateGroupPage';
import { ExclamationTriangleIcon } from '@heroicons/react/24/solid';
import { requestNotificationPermission } from '../services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates' | 'create-group';

const THEME_MAP: Record<GroupTheme, { primary: string, hover: string, light: string }> = {
  blue: { primary: '#2563eb', hover: '#1d4ed8', light: '#eff6ff' },
  green: { primary: '#10b981', hover: '#059669', light: '#ecfdf5' },
  black: { primary: '#18181b', hover: '#09090b', light: '#27272a' },
  orange: { primary: '#f97316', hover: '#ea580c', light: '#fff7ed' }
};

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [appTheme, setAppTheme] = useState<GroupTheme>(() => getAppTheme());
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    const changeAppTheme = useCallback((newTheme: GroupTheme) => {
        setAppTheme(newTheme);
        saveAppTheme(newTheme);
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');
                    requestNotificationPermission();
                } else {
                    setCurrentPage('auth');
                }
            } else {
                setCurrentPage('auth');
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, [currentPage]);

    useEffect(() => {
        refreshCurrentUser();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-brand mb-6 shadow-[0_0_15px_rgba(37,99,235,0.3)]"></div>
                <div className="flex flex-col items-center gap-2">
                   <h1 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">CyBerPhone <span className="text-brand">Pro</span></h1>
                   <p className="text-[9px] font-bold uppercase text-gray-400 tracking-[0.3em] animate-pulse">Carregando Ecossistema v1.3.1</p>
                </div>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-16 w-16 text-red-500 mb-6" />
                <h2 className="text-2xl font-black uppercase mb-2 text-gray-900 dark:text-white">Erro de Inicialização</h2>
                <p className="text-gray-500 text-sm mb-8 font-medium">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-brand text-white px-10 py-4 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={changeAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''}`}>
                    <div className="max-w-7xl mx-auto">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { User } from '../types';
import { 
  XMarkIcon, 
  MicrophoneIcon, 
  VideoCameraIcon, 
  PhoneIcon,
  SpeakerWaveIcon,
  VideoCameraSlashIcon,
  ArrowPathIcon
} from '@heroicons/react/24/solid';
import { MicrophoneSlashIcon } from '@heroicons/react/24/outline';

interface CallModalProps {
  partner: User;
  type: 'voice' | 'video';
  onClose: () => void;
}

const CallModal: React.FC<CallModalProps> = ({ partner, type, onClose }) => {
  const [status, setStatus] = useState<'calling' | 'connected'>('calling');
  const [timer, setTimer] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(type === 'voice');
  const [volumeLevel, setVolumeLevel] = useState(0);

  const miniVideoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const animationFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const startMedia = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: type === 'video' 
        });

        streamRef.current = stream;

        if (miniVideoRef.current && type === 'video') {
          miniVideoRef.current.srcObject = stream;
        }

        // Setup Audio Analysis for Voice Visualizer
        if (stream.getAudioTracks().length > 0) {
          setupAudioAnalyser(stream);
        }

        // Simulate connection delay
        const ringingTimeout = setTimeout(() => setStatus('connected'), 3000);
        return () => clearTimeout(ringingTimeout);
      } catch (err) {
        console.error("Erro ao acessar mídia:", err);
        alert("Não foi possível acessar a câmera ou microfone.");
        onClose();
      }
    };

    startMedia();

    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, [type]);

  const setupAudioAnalyser = (stream: MediaStream) => {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const source = audioContext.createMediaStreamSource(stream);
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    audioContextRef.current = audioContext;
    analyserRef.current = analyser;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    const updateVolume = () => {
      if (!analyserRef.current) return;
      analyserRef.current.getByteFrequencyData(dataArray);

      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += dataArray[i];
      }
      const average = sum / bufferLength;
      setVolumeLevel(average); 

      animationFrameRef.current = requestAnimationFrame(updateVolume);
    };

    updateVolume();
  };

  useEffect(() => {
    let interval: any;
    if (status === 'connected') {
      interval = setInterval(() => setTimer(t => t + 1), 1000);
    }
    return () => clearInterval(interval);
  }, [status]);

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed inset-0 z-[10000] bg-[#0a0c10] flex flex-col items-center justify-center animate-fade-in text-white overflow-hidden font-sans">

      {/* BACKGROUND / REMOTE VIDEO AREA */}
      <div className="absolute inset-0 z-0">
        {status === 'connected' && type === 'video' ? (
          <div className="w-full h-full relative overflow-hidden bg-black">
             {/* Simulated Remote Video (using profile pic with blur/motion) */}
             <img 
               src={partner.profilePicture} 
               className="w-full h-full object-cover blur-[50px] scale-150 opacity-40 animate-slow-zoom" 
               alt="Background"
             />
             <div className="absolute inset-0 flex items-center justify-center">
                <img 
                  src={partner.profilePicture} 
                  className="w-48 h-48 md:w-64 md:h-64 rounded-[4rem] object-cover border-4 border-white/10 shadow-2xl animate-pulse" 
                  alt={partner.firstName}
                />
                <div className="absolute bottom-1/4 bg-blue-600/90 backdrop-blur-md px-6 py-2 rounded-full font-black text-xs uppercase tracking-widest shadow-xl border border-white/10">
                   Vídeo de {partner.firstName}
                </div>
             </div>
          </div>
        ) : (
          <div className="w-full h-full relative overflow-hidden">
             <img 
               src={partner.profilePicture} 
               className="w-full h-full object-cover blur-[80px] scale-150 opacity-30 transition-transform duration-[10s] animate-slow-zoom" 
               alt="Calling Background"
             />
          </div>
        )}
      </div>

      {/* MINI LOCAL VIEW (Self View) */}
      {type === 'video' && (
        <div className={`absolute top-10 right-6 w-32 h-44 md:w-40 md:h-56 bg-gray-900 rounded-[2rem] border-2 border-white/20 overflow-hidden shadow-2xl z-50 transition-all duration-700 ${isCameraOff ? 'scale-0' : 'scale-100'}`}>
           <video ref={miniVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
           <div className="absolute bottom-3 left-1/2 -translate-x-1/2 bg-black/40 backdrop-blur-md px-3 py-1 rounded-full text-[8px] font-black uppercase border border-white/10">
              Você
           </div>
        </div>
      )}

      {/* UI CENTRAL - CALLING INFO */}
      <div className="relative z-10 flex flex-col items-center mb-20 text-center px-6">

         {/* Voice Waves (Visualizer) */}
         <div className={`relative mb-8 transition-all duration-700 ${status === 'connected' && type === 'video' ? 'scale-0 opacity-0 h-0' : 'scale-100 opacity-100'}`}>
            <div 
              className="absolute inset-0 rounded-full bg-blue-500/20 animate-ping"
              style={{ 
                transform: `scale(${1 + (volumeLevel / 150)})`,
                opacity: volumeLevel > 5 ? 0.4 : 0 
              }}
            ></div>
            <div 
              className="absolute inset-0 rounded-full bg-blue-400/10"
              style={{ 
                transform: `scale(${1.2 + (volumeLevel / 120)})`,
                transition: 'transform 0.1s ease-out'
              }}
            ></div>

            <div className={`relative w-32 h-32 md:w-48 md:h-48 rounded-[3rem] md:rounded-[4rem] overflow-hidden border-4 ${status === 'connected' ? 'border-green-500' : 'border-blue-500'} shadow-[0_0_80px_rgba(37,99,235,0.4)] transition-all duration-700`}>
               <img src={partner.profilePicture} className="w-full h-full object-cover" alt={partner.firstName} />
            </div>
         </div>

         <div className={`transition-all duration-700 ${status === 'connected' && type === 'video' ? 'fixed top-12 left-10 text-left' : 'translate-y-0 text-center'}`}>
            <h2 className={`font-black tracking-tighter uppercase mb-2 drop-shadow-2xl transition-all ${status === 'connected' && type === 'video' ? 'text-2xl md:text-4xl' : 'text-3xl md:text-5xl'}`}>
              {partner.firstName} {partner.lastName}
            </h2>
            <div className={`flex items-center gap-3 ${status === 'connected' && type === 'video' ? 'justify-start' : 'justify-center'}`}>
               <span className={`w-2.5 h-2.5 rounded-full ${status === 'connected' ? 'bg-green-500 animate-pulse' : 'bg-blue-500 animate-bounce'}`}></span>
               <p className="text-blue-400 font-black uppercase tracking-[0.3em] text-[10px] md:text-xs">
                  {status === 'calling' ? 'Conectando...' : formatTime(timer)}
               </p>
            </div>
         </div>
      </div>

      {/* CALL CONTROLS */}
      <div className="absolute bottom-12 left-0 right-0 z-[100] flex items-center justify-center gap-4 md:gap-8 px-4">

         <div className="flex bg-white/10 backdrop-blur-2xl rounded-[3.5rem] p-3 border border-white/10 shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] items-center gap-3">

            <button 
              onClick={() => setIsMuted(!isMuted)}
              className={`p-5 md:p-6 rounded-full transition-all active:scale-90 ${isMuted ? 'bg-red-500 text-white shadow-lg' : 'bg-white/5 text-white hover:bg-white/20'}`}
              title="Microfone"
            >
               {isMuted ? <MicrophoneSlashIcon className="h-6 w-6 md:h-7 md:w-7" /> : <MicrophoneIcon className="h-6 w-6 md:h-7 md:w-7" />}
            </button>

            {type === 'video' && (
              <button 
                onClick={() => setIsCameraOff(!isCameraOff)}
                className={`p-5 md:p-6 rounded-full transition-all active:scale-90 ${isCameraOff ? 'bg-red-500 text-white' : 'bg-white/5 text-white hover:bg-white/20'}`}
                title="Câmera"
              >
                 {isCameraOff ? <VideoCameraSlashIcon className="h-6 w-6 md:h-7 md:w-7" /> : <VideoCameraIcon className="h-6 w-6 md:h-7 md:w-7" />}
              </button>
            )}

            <button className="p-5 md:p-6 bg-white/5 rounded-full text-white hover:bg-white/20 transition-all hidden sm:block">
               <SpeakerWaveIcon className="h-6 w-6 md:h-7 md:w-7" />
            </button>

            <button className="p-5 md:p-6 bg-white/5 rounded-full text-white hover:bg-white/20 transition-all">
               <ArrowPathIcon className="h-6 w-6 md:h-7 md:w-7" />
            </button>

            <button 
              onClick={onClose}
              className="p-6 md:p-7 bg-red-600 rounded-full shadow-[0_15px_30px_rgba(220,38,38,0.4)] hover:bg-red-700 active:scale-95 transition-all group ml-2"
              title="Desligar"
            >
               <PhoneIcon className="h-8 w-8 md:h-9 md:w-9 rotate-[135deg] text-white" />
            </button>
         </div>

      </div>

      <style>{`
        .mirror { transform: scaleX(-1); }
        @keyframes slow-zoom {
          0% { transform: scale(1.5) rotate(0deg); }
          50% { transform: scale(1.7) rotate(3deg); }
          100% { transform: scale(1.5) rotate(0deg); }
        }
        .animate-slow-zoom {
          animation: slow-zoom 25s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default CallModal;

