import React, { useState, useEffect, useCallback } from 'react';
import { Story } from '../types';
import { XMarkIcon, ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/solid';

interface StoryViewerModalProps {
  stories: Story[];
  initialIndex: number;
  onClose: () => void;
}

const STORY_DURATION = 5000;

const StoryViewerModal: React.FC<StoryViewerModalProps> = ({ stories, initialIndex, onClose }) => {
  const [currentUserIdx, setCurrentUserIdx] = useState(initialIndex);
  const [currentItemIdx, setCurrentItemIdx] = useState(0);
  const [progress, setProgress] = useState(0);

  const currentStory = stories[currentUserIdx];
  const currentItem = currentStory?.items?.[currentItemIdx];

  const handleNext = useCallback(() => {
    if (!currentStory || !currentStory.items) { onClose(); return; }

    if (currentItemIdx < currentStory.items.length - 1) {
      setCurrentItemIdx(prev => prev + 1);
      setProgress(0);
    } else if (currentUserIdx < stories.length - 1) {
      setCurrentUserIdx(prev => prev + 1);
      setCurrentItemIdx(0);
      setProgress(0);
    } else {
      onClose();
    }
  }, [currentItemIdx, currentUserIdx, currentStory, stories.length, onClose]);

  const handlePrev = useCallback(() => {
    if (currentItemIdx > 0) {
      setCurrentItemIdx(prev => prev - 1);
      setProgress(0);
    } else if (currentUserIdx > 0) {
      const prevStory = stories[currentUserIdx - 1];
      setCurrentUserIdx(prev => prev - 1);
      setCurrentItemIdx(prevStory?.items?.length ? prevStory.items.length - 1 : 0);
      setProgress(0);
    }
  }, [currentItemIdx, currentUserIdx, stories]);

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          handleNext();
          return 0;
        }
        return prev + (100 / (STORY_DURATION / 100));
      });
    }, 100);

    return () => clearInterval(timer);
  }, [handleNext]);

  if (!currentStory || !currentItem) return null;

  return (
    <div className="fixed inset-0 z-[1000] bg-black/95 flex items-center justify-center animate-fade-in">
      <div className="relative w-full max-w-lg h-full md:h-[90vh] md:rounded-[2rem] overflow-hidden bg-black flex flex-col">

        {/* Progress Bars */}
        <div className="absolute top-4 left-4 right-4 flex gap-1.5 z-20">
          {currentStory.items?.map((_, idx) => (
            <div key={idx} className="h-1 flex-1 bg-white/20 rounded-full overflow-hidden">
               <div 
                 className="h-full bg-white transition-all duration-100 ease-linear"
                 style={{ 
                   width: idx === currentItemIdx ? `${progress}%` : idx < currentItemIdx ? '100%' : '0%' 
                 }}
               />
            </div>
          ))}
        </div>

        {/* Header */}
        <div className="absolute top-8 left-6 right-6 flex items-center justify-between z-20">
           <div className="flex items-center gap-3">
              <img src={currentStory.userProfilePic} className="w-10 h-10 rounded-full border-2 border-white object-cover shadow-md" />
              <span className="font-black text-white text-sm shadow-sm drop-shadow-md">{currentStory.userName}</span>
           </div>
           <button onClick={onClose} className="p-2 text-white/70 hover:text-white">
              <XMarkIcon className="h-7 w-7" />
           </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex items-center justify-center overflow-hidden bg-[#111]">
           {currentItem.imageUrl ? (
              <img src={currentItem.imageUrl} className="w-full h-full object-contain" alt="Story" />
           ) : (
              <div className={`w-full h-full flex flex-col items-center justify-center text-center p-12 transition-colors duration-500 ${currentItem.backgroundColor || 'bg-blue-600'}`}>
                 <p className={`font-black leading-tight break-words max-w-full ${currentItem.textColor || 'text-white'} ${currentItem.fontFamily || 'font-sans'} ${currentItem.text && currentItem.text.length > 60 ? 'text-2xl' : 'text-4xl md:text-5xl'}`}>
                   {currentItem.text}
                 </p>
              </div>
           )}
        </div>

        {/* Controls Overlay */}
        <div className="absolute inset-0 z-10 flex">
           <div className="w-1/3 h-full cursor-pointer" onClick={handlePrev}></div>
           <div className="w-2/3 h-full cursor-pointer" onClick={handleNext}></div>
        </div>

        {/* Nav Buttons (Desktop) */}
        <button 
          onClick={handlePrev} 
          className="hidden md:flex absolute -left-16 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white z-50"
        >
           <ChevronLeftIcon className="h-8 w-8" />
        </button>
        <button 
          onClick={handleNext} 
          className="hidden md:flex absolute -right-16 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white z-50"
        >
           <ChevronRightIcon className="h-8 w-8" />
        </button>
      </div>
    </div>
  );
};

export default StoryViewerModal;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Post, AdCampaign, PostType, Story, CyberEvent, ChatConversation } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents, getChats, joinGroup } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import GroupDiscoveryCard from './GroupDiscoveryCard';
import { PlusIcon, ArrowPathIcon, RocketLaunchIcon, ChevronUpIcon, FireIcon, SparklesIcon, CalendarIcon, UserGroupIcon, StarIcon, ArrowTrendingUpIcon } from '@heroicons/react/24/outline';
import { TrophyIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<(Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[]>([]);
  const [visibleItems, setVisibleItems] = useState<(Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [stories, setStories] = useState<Story[]>([]);
  const [upcomingEvents, setUpcomingEvents] = useState<CyberEvent[]>([]);
  const [sidebarAds, setSidebarAds] = useState<AdCampaign[]>([]);

  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async (isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    const [allPosts, allAds, allUsers, allEvents, allStories, allChats] = await Promise.all([
      getPosts(),
      getAds(),
      getUsers(),
      getEvents(),
      getStories(),
      getChats()
    ]);

    const sortedPosts = allPosts.sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;
        const aBoosted = a.isBoosted && a.boostExpires && a.boostExpires > Date.now();
        const bBoosted = b.isBoosted && b.boostExpires && b.boostExpires > Date.now();
        if (aBoosted && !bBoosted) return -1;
        if (!aBoosted && bBoosted) return 1;
        return b.timestamp - a.timestamp;
    });

    const activeAds = allAds.filter(a => a.isActive).sort((a, b) => (b.budget || 0) - (a.budget || 0));
    const publicGroups = allChats.filter(c => c.type === 'GROUP' && c.isPublic && !c.participants.includes(currentUser.id)).slice(0, 3);

    setUpcomingEvents(allEvents.filter(e => e.dateTime > Date.now()).slice(0, 3));
    setSidebarAds(activeAds.slice(0, 2));
    setStories(allStories);

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);
    setSuggestedUsers(suggestions);

    let combined: (Post | AdCampaign | ChatConversation | { type: 'SUGGESTIONS' })[] = [];
    let adPointer = 0;
    let groupPointer = 0;

    sortedPosts.forEach((post, idx) => {
        combined.push(post);
        if (idx === 0 && suggestions.length > 0) combined.push({ type: 'SUGGESTIONS' });
        if ((idx + 1) % 4 === 0 && adPointer < activeAds.length) {
            combined.push(activeAds[adPointer]);
            adPointer++;
        }
        if ((idx + 1) % 7 === 0 && groupPointer < publicGroups.length) {
            combined.push(publicGroups[groupPointer]);
            groupPointer++;
        }
    });

    setAllItems(combined);
    setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
    setDisplayLimit(ITEMS_PER_PAGE);
    setLoading(false);
  }, [currentUser]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  useEffect(() => {
    const handleScroll = () => setShowScrollTop(window.scrollY > 1000);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleJoin = async (groupId: string) => {
    await joinGroup(groupId, currentUser.id);
    loadData(true);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);
  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-8 relative">
      <div className="fixed bottom-24 right-6 z-[60] flex flex-col gap-3">
        {showScrollTop && (
          <button onClick={scrollToTop} className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all">
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button onClick={() => onNavigate('ads')} className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all">
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      <div className="flex gap-4 overflow-x-auto pb-6 pt-2 no-scrollbar mb-4">
         <div onClick={() => setIsCreatingStory(true)} className="flex-shrink-0 w-20 h-32 bg-white dark:bg-darkcard rounded-2xl shadow-md border border-dashed border-blue-300 dark:border-blue-900/50 flex flex-col items-center justify-center cursor-pointer group hover:border-blue-500 transition-all">
            <div className="bg-blue-50 dark:bg-white/5 p-2 rounded-full mb-2 group-hover:bg-blue-600 group-hover:text-white transition-colors">
               <PlusIcon className="h-5 w-5 text-blue-600 group-hover:text-white" />
            </div>
            <span className="text-[9px] font-black uppercase text-gray-400 group-hover:text-blue-600">Criar</span>
         </div>

         {stories.map((story, i) => (
            <div key={i} onClick={() => setSelectedStoryIndex(i)} className="flex-shrink-0 w-20 h-32 rounded-2xl overflow-hidden relative cursor-pointer group shadow-lg border-2 border-transparent hover:border-blue-500 transition-all">
               <img src={story.items?.[0]?.imageUrl || story.userProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
               <div className="absolute bottom-2 left-2 right-2 text-center">
                  <p className="text-[8px] font-black text-white uppercase truncate">{(story.userName || 'Membro').split(' ')[0]}</p>
               </div>
               <div className="absolute top-2 left-2 w-6 h-6 rounded-full border-2 border-blue-600 overflow-hidden">
                  <img src={story.userProfilePic} className="w-full h-full object-cover" />
               </div>
            </div>
         ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Sincronizando Feed...</p>
              </div>
            ) : (
              <>
                {visibleItems.map((item: any, idx) => {
                  if (item.authorName) { // Is Post
                    return <PostCard key={item.id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
                  }
                  if (item.professorId) { // Is Ad
                    return <AdCard key={item.id} ad={item as AdCampaign} rank={idx} />;
                  }
                  if (item.type === 'GROUP') { // Is Group Discovery
                    return <GroupDiscoveryCard key={item.id} group={item} onJoin={() => handleJoin(item.id)} />;
                  }
                  if (item.type === 'SUGGESTIONS') {
                    return (
                      <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden animate-fade-in">
                         <SparklesIcon className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10" />
                         <div className="flex items-center justify-between mb-8">
                            <div>
                               <h4 className="font-black text-2xl tracking-tighter flex items-center gap-3"><FireIcon className="h-8 w-8 text-yellow-400" /> Networking</h4>
                               <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Sugestões de Conexão CyBer</p>
                            </div>
                            <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><ArrowPathIcon className="h-6 w-6"/></button>
                         </div>
                         <div className="flex gap-5 overflow-x-auto pb-4 no-scrollbar">
                            {suggestedUsers.map(u => (
                              <div key={u.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] min-w-[180px] flex flex-col items-center text-center border border-white/10 group">
                                 <img src={u.profilePicture} className="w-20 h-20 rounded-2xl object-cover mb-3 border-2 border-white/20 shadow-xl group-hover:scale-110 transition-transform" />
                                 <p className="font-black text-sm truncate w-full">{u.firstName} {u.lastName}</p>
                                 <p className="text-[8px] font-black text-blue-200 uppercase mb-4 tracking-tighter">{u.credentials || 'Especialista'}</p>
                                 <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-800 py-2.5 rounded-xl font-black text-[9px] uppercase shadow-lg active:scale-95 transition-all">Seguir</button>
                              </div>
                            ))}
                         </div>
                      </div>
                    );
                  }
                  return null;
                })}

                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Buscando mais conteúdos...</p>
                    </>
                  )}
                  {isAtEnd && (
                    <div className="flex flex-col items-center gap-3 opacity-60 py-10">
                       <CheckCircleIcon className="h-10 w-10 text-green-500" />
                       <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.3em]">Você chegou ao fim do seu feed!</p>
                       <button onClick={scrollToTop} className="text-blue-600 text-[9px] font-black uppercase underline tracking-widest mt-2">Voltar para o topo</button>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </main>

        <aside className="hidden lg:block lg:col-span-4 space-y-6">
           <div className="sticky top-24 space-y-6">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden group">
                 <RocketLaunchIcon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-4 flex items-center gap-2">
                    <TrophyIcon className="h-6 w-6 text-yellow-400" /> Meta Profissional
                 </h3>
                 <div className="mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2">
                       <span>Progresso</span>
                       <span>{followerCount} / 2.000</span>
                    </div>
                    <div className="w-full h-2.5 bg-white/20 rounded-full overflow-hidden border border-white/10">
                       <div className="h-full bg-white shadow-[0_0_10px_white] transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
                    </div>
                 </div>
                 <button onClick={() => onNavigate('ads')} className="w-full bg-white text-blue-700 py-4 rounded-2xl font-black text-[11px] uppercase shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
                    <RocketLaunchIcon className="h-5 w-5" /> Impulsionar Perfil
                 </button>
              </div>
           </div>
        </aside>
      </div>

      {isCreatingStory && <CreateStoryModal currentUser={currentUser} onClose={() => setIsCreatingStory(false)} onStoryCreated={() => { setIsCreatingStory(false); loadData(true); }} />}

      {selectedStoryIndex !== null && (
        <StoryViewerModal 
          stories={stories} 
          initialIndex={selectedStoryIndex} 
          onClose={() => setSelectedStoryIndex(null)} 
        />
      )}
    </div>
  );
};

export default FeedPage;

import React, { useState, useEffect } from 'react';
import { User, CyberEvent, UserType } from '../types';
import { getEvents, createEvent, toggleJoinEvent, findUserById, generateUUID } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  CalendarIcon, 
  MapPinIcon, 
  VideoCameraIcon, 
  UserGroupIcon, 
  PlusIcon, 
  XMarkIcon, 
  GlobeAltIcon, 
  SparklesIcon, 
  PhotoIcon,
  ClockIcon,
  GlobeAmericasIcon,
  LockClosedIcon,
  EyeIcon,
  InformationCircleIcon
} from '@heroicons/react/24/outline';
import { CheckBadgeIcon, CameraIcon } from '@heroicons/react/24/solid';

interface EventsPageProps {
  currentUser: User;
}

const EventsPage: React.FC<EventsPageProps> = ({ currentUser }) => {
  const [events, setEvents] = useState<CyberEvent[]>([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [filter, setFilter] = useState<'ALL' | 'MY_EVENTS'>('ALL');
  const [creatorsMap, setCreatorsMap] = useState<Record<string, User>>({});

  // Event Form States
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [startDate, setStartDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endDate, setEndDate] = useState('');
  const [endTime, setEndTime] = useState('');
  const [location, setLocation] = useState('');
  const [type, setType] = useState<'ONLINE' | 'PRESENTIAL'>('ONLINE');
  const [isPublic, setIsPublic] = useState(true);
  const [imageUrl, setImageUrl] = useState('');

  const fetchEvents = async () => {
    const allEvents = await getEvents();
    setEvents(allEvents.sort((a, b) => a.dateTime - b.dateTime));

    // Fetch creators for events
    const creatorsToFetch = Array.from(new Set(allEvents.map(e => e.creatorId))) as string[];
    const newCreatorsMap: Record<string, User> = { ...creatorsMap };

    for (const id of creatorsToFetch) {
      if (!newCreatorsMap[id]) {
        const u = await findUserById(id);
        if (u) newCreatorsMap[id] = u;
      }
    }
    setCreatorsMap(newCreatorsMap);
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  const handleCreateEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !startDate || !startTime) return;

    const newEvent: CyberEvent = {
      id: generateUUID(),
      creatorId: currentUser.id,
      creatorName: `${currentUser.firstName} ${currentUser.lastName}`,
      title,
      description,
      dateTime: new Date(`${startDate}T${startTime}`).getTime(),
      endDateTime: endDate && endTime ? new Date(`${endDate}T${endTime}`).getTime() : undefined,
      location,
      type,
      isPublic,
      attendees: [currentUser.id],
      imageUrl: imageUrl || `https://picsum.photos/800/400?random=${Date.now()}`
    };
    await createEvent(newEvent);
    await fetchEvents();
    setShowCreateModal(false);
    resetForm();
  };

  const resetForm = () => {
    setTitle(''); setDescription(''); setStartDate(''); setStartTime(''); 
    setEndDate(''); setEndTime(''); setLocation(''); setType('ONLINE');
    setIsPublic(true); setImageUrl('');
  };

  const handleJoin = async (eventId: string) => {
    await toggleJoinEvent(eventId, currentUser.id);
    await fetchEvents();
  };

  const filteredEvents = filter === 'ALL' 
    ? events 
    : events.filter(e => e.attendees.includes(currentUser.id));

  return (
    <div className="container mx-auto px-2 py-4 md:p-8 animate-fade-in max-w-7xl">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-10 px-2">
        <div className="space-y-1">
           <h2 className="text-3xl md:text-6xl font-black text-gray-900 dark:text-white tracking-tighter">Eventos</h2>
           <p className="text-gray-500 font-bold uppercase tracking-widest text-[10px] md:text-xs">Descubra novas experiências educacionais na CyBerPhone</p>
        </div>

        <div className="flex gap-3">
           <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-2xl">
              <button 
                onClick={() => setFilter('ALL')}
                className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase transition-all ${filter === 'ALL' ? 'bg-white dark:bg-darkcard text-blue-600 shadow-md' : 'text-gray-500'}`}
              >
                Explorar
              </button>
              <button 
                onClick={() => setFilter('MY_EVENTS')}
                className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase transition-all ${filter === 'MY_EVENTS' ? 'bg-white dark:bg-darkcard text-blue-600 shadow-md' : 'text-gray-500'}`}
              >
                Meus Eventos
              </button>
           </div>

           {currentUser.userType === UserType.CREATOR && (
             <button 
               onClick={() => setShowCreateModal(true)}
               className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-2xl font-black text-[10px] flex items-center gap-2 shadow-xl active:scale-95 transition-all uppercase tracking-widest"
             >
               <PlusIcon className="h-4 w-4 stroke-[4]" /> Criar Evento
             </button>
           )}
        </div>
      </header>

      {filteredEvents.length === 0 ? (
        <div className="bg-white dark:bg-darkcard rounded-[3rem] p-20 text-center border-2 border-dashed border-gray-100 dark:border-white/5 mx-2">
           <div className="bg-gray-50 dark:bg-white/5 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
              <CalendarIcon className="h-10 w-10 text-gray-300" />
           </div>
           <h3 className="text-2xl font-black text-gray-900 dark:text-white mb-2">Nenhum encontro agendado</h3>
           <p className="text-gray-500 font-medium">Fique atento às notificações dos seus professores favoritos.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 px-2">
           {filteredEvents.map(evt => {
             const isJoined = evt.attendees.includes(currentUser.id);
             const isCreator = evt.creatorId === currentUser.id;
             const creator = creatorsMap[evt.creatorId];

             return (
               <div key={evt.id} className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-sm group hover:shadow-2xl transition-all duration-500 hover:-translate-y-1">
                  <div className="relative h-48 overflow-hidden">
                     <img src={evt.imageUrl} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt={evt.title} />
