               className={`p-8 md:p-12 rounded-[2.5rem] shadow-inner flex flex-col items-center justify-center text-center animate-fade-in ${post.fontFamily || 'font-sans'}`}
               style={{ 
                 background: hasBg ? post.backgroundColor : 'transparent',
                 backgroundImage: isGradient ? post.backgroundColor : undefined,
                 backgroundColor: hasBg && !isGradient ? post.backgroundColor : undefined,
                 color: post.textColor || 'inherit',
                 fontSize: post.fontSize ? `calc(${post.fontSize} * 1.2)` : '1.1rem',
                 minHeight: hasBg ? '300px' : 'auto',
                 border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
                 fontFamily: post.fontFamily?.replace('font-', '')
               }}
             >
                <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-xs' : 'text-left w-full'}`}>{post.content}</p>
                <div className={`text-[8px] font-black uppercase tracking-[0.2em] pt-8 mt-4 border-t w-full opacity-30 ${hasBg ? 'border-white/10' : 'border-gray-100'}`}>
                   Publicado em {new Date(post.timestamp).toLocaleDateString()}
                </div>
             </div>

             <div className="hidden md:flex items-center justify-between py-6 border-b border-gray-50 dark:border-white/5 text-gray-400">
                <div className="flex items-center gap-4">
                   <button onClick={handleLike} className={`flex items-center gap-2 group transition-all active:scale-75 ${hasLiked ? 'text-blue-600' : 'hover:text-blue-600'}`}>
                      <div className={`p-3 rounded-2xl transition-colors ${hasLiked ? 'bg-blue-50 dark:bg-blue-600/10' : 'group-hover:bg-gray-50'}`}>
                       {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
                      </div>
                      <span className="text-xs font-black">{post.likes?.length || 0}</span>
