type StyleTab = 'bg' | 'text' | 'font';

const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');

  // Customizações de Texto
  const [selectedBg, setSelectedBg] = useState(BG_OPTIONS[0]);
  const [selectedTextColor, setSelectedTextColor] = useState(TEXT_COLORS[0]);
  const [selectedFont, setSelectedFont] = useState(FONT_OPTIONS[0]);

  const [showStyleTools, setShowStyleTools] = useState(false);
  const [activeStyleTab, setActiveStyleTab] = useState<StyleTab>('bg');

  // Mídia
  const [imageUrl, setImageUrl] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);
  const [showRecordModal, setShowRecordModal] = useState(false);

  // Configs
  const [selectedGroup, setSelectedGroup] = useState<{id?: string, name: string}>({ name: 'Feed Geral' });
  const [myGroups, setMyGroups] = useState<ChatConversation[]>([]);
  const [showGroupSelector, setShowGroupSelector] = useState(false);
  const [loading, setLoading] = useState(false);

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;

  // Ajustar cor do texto automaticamente quando muda o fundo se for transparente/branco/preto
  useEffect(() => {
    if (selectedBg.id === 'transparent' || selectedBg.id === 'white') {
        setSelectedTextColor(TEXT_COLORS.find(c => c.id === 'text-gray-900')!);
    } else {
        setSelectedTextColor(TEXT_COLORS.find(c => c.id === 'text-white')!);
    }
  }, [selectedBg.id]);

  useEffect(() => {
    const loadMyGroups = async () => {
       const allChats = await getChats();
       const groups = allChats.filter(c => c.type === 'GROUP' && c.participants.includes(currentUser.id));
       setMyGroups(groups);
    };
    loadMyGroups();
  }, [currentUser.id]);

  const resetForm = () => {
    setIsExpanded(false);
    setPostType(PostType.TEXT);
    setContent('');
    setImageUrl('');
    setReelUrl('');
    setImageFile(null);
    setReelFile(null);
    setSelectedBg(BG_OPTIONS[0]);
    setSelectedTextColor(TEXT_COLORS[0]);
    setSelectedFont(FONT_OPTIONS[0]);
    setShowStyleTools(false);
    setSelectedGroup({ name: 'Feed Geral' });
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImageUrl(URL.createObjectURL(file));
      setPostType(PostType.IMAGE);
      setShowStyleTools(false);
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file));
      setPostType(PostType.REEL);
    }
  };

  const handleRecordedReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setReelFile(videoBlob);
    setReelUrl(URL.createObjectURL(videoBlob));
    setPostType(PostType.REEL);
    setShowRecordModal(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() && !imageFile && !reelFile) return;

    setLoading(true);

    try {
      let finalImageUrl = imageUrl;
      let finalReelUrl = reelUrl;

      if (postType === PostType.IMAGE && imageFile) {
        finalImageUrl = await uploadFile(imageFile, 'posts');
      }

      if (postType === PostType.REEL && reelFile) {
        finalReelUrl = await uploadFile(reelFile, 'reels');
      }

      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        type: postType,
        timestamp: Date.now(),
        content: content,
        imageUrl: postType === PostType.IMAGE ? finalImageUrl : undefined,
        groupId: selectedGroup.id,
        groupName: selectedGroup.id ? selectedGroup.name : undefined,
        backgroundColor: selectedBg.class,
        textColor: selectedTextColor.class,
        fontFamily: selectedFont.class,
        reel: postType === PostType.REEL ? { videoUrl: finalReelUrl, description: content } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: []
      };

      if (isEditing) await updatePost(postData);
      else await addPost(postData);

      onPostCreated();
      if (!isEditing) resetForm();
      if (onCancel) onCancel();

    } catch (err) {
      console.error(err);
      alert('Erro ao salvar postagem.');
    } finally {
      setLoading(false);
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-4 shadow-sm animate-fade-in">
         <div className="flex items-center gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-sm hover:bg-gray-100 dark:hover:bg-white/10 transition-all">
              No que você está pensando?
            </button>
         </div>
         <div className="flex gap-4 px-2 border-t border-gray-50 dark:border-white/5 pt-4">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <PhotoIcon className="h-5 w-5 text-green-500" /> Foto
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <FilmIcon className="h-5 w-5 text-purple-500" /> Reel
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.TEXT); setShowStyleTools(true); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <SwatchIcon className="h-5 w-5 text-blue-500" /> Cor
            </button>
         </div>
      </div>
    );
  }

  const isBgSelected = selectedBg.id !== 'transparent';

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-6 md:p-8 border dark:border-white/5 animate-fade-in relative overflow-visible">
      {/* Header do Modal */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
           <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover" />
           <div className="flex flex-col">
              <h3 className="font-black text-gray-900 dark:text-white text-sm">{currentUser.firstName} {currentUser.lastName}</h3>

              {/* Selector de Destino */}
              <div className="relative">
                 <button 
                   type="button"
                   onClick={() => setShowGroupSelector(!showGroupSelector)}
                   className="flex items-center gap-1.5 bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded-lg text-[9px] font-bold text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/20 transition-all"
                 >
                    {selectedGroup.id ? <UserGroupIcon className="h-3 w-3" /> : <GlobeAmericasIcon className="h-3 w-3" />}
                    <span className="max-w-[100px] truncate">{selectedGroup.name}</span>
                    <ChevronDownIcon className="h-3 w-3" />
                 </button>

                 {showGroupSelector && (
                   <div className="absolute top-full left-0 mt-2 w-56 bg-white dark:bg-[#1a1c23] border border-gray-100 dark:border-white/10 rounded-2xl shadow-2xl z-[150] p-2 animate-fade-in">
                      <button 
                       onClick={() => { setSelectedGroup({ name: 'Feed Geral' }); setShowGroupSelector(false); }}
                       className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                      >
                         <GlobeAmericasIcon className="h-4 w-4 text-gray-400" />
                         <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">Feed Geral</span>
                      </button>
                      {myGroups.map(group => (
                        <button 
                         key={group.id}
                         onClick={() => { setSelectedGroup({ id: group.id, name: group.groupName! }); setShowGroupSelector(false); }}
                         className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                        >
                           <UserGroupIcon className="h-4 w-4 text-blue-600" />
                           <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{group.groupName}</span>
                        </button>
                      ))}
                   </div>
                 )}
              </div>
           </div>
        </div>
        <button onClick={resetForm} className="p-2 bg-gray-100 dark:bg-white/10 rounded-full hover:bg-gray-200 dark:hover:bg-white/20 transition-all"><XMarkIcon className="h-5 w-5 text-gray-500" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* TEXT AREA COM ESTILOS */}
        {postType === PostType.TEXT && (
          <div className={`relative transition-all duration-500 rounded-[2rem] overflow-hidden flex items-center justify-center ${isBgSelected ? `${selectedBg.class} min-h-[300px]` : 'bg-gray-50 dark:bg-white/5 min-h-[150px]'}`}>
             <textarea 
               value={content} 
               onChange={e => { setContent(e.target.value); }} 
               className={`w-full p-6 bg-transparent outline-none resize-none text-center placeholder:opacity-50 ${isBgSelected ? `${selectedTextColor.class} ${selectedFont.class} text-2xl md:text-3xl leading-tight py-20` : 'text-gray-900 dark:text-white text-lg font-medium'}`}
               placeholder={selectedGroup.id ? `Olá ${selectedGroup.name}...` : "No que você está pensando?"}
               style={{ height: '100%' }}
             />

             {isBgSelected && (
               <button 
                 type="button" 
                 onClick={() => { setSelectedBg(BG_OPTIONS[0]); setSelectedTextColor(TEXT_COLORS[0]); setShowStyleTools(false); }}
                 className="absolute top-4 right-4 bg-black/20 hover:bg-black/40 text-white p-2 rounded-full backdrop-blur-md transition-all"
               >
                 <XMarkIcon className="h-4 w-4" />
               </button>
             )}
          </div>
        )}

        {/* FERRAMENTAS DE ESTILO DE TEXTO */}
        {postType === PostType.TEXT && showStyleTools && (
           <div className="space-y-4 animate-slide-down bg-gray-50 dark:bg-white/5 p-4 rounded-3xl border border-gray-100 dark:border-white/5">
              <div className="flex gap-2 mb-2 border-b border-gray-200 dark:border-white/10 pb-2 overflow-x-auto no-scrollbar">
                 <button type="button" onClick={() => setActiveStyleTab('bg')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'bg' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fundo</button>
                 <button type="button" onClick={() => setActiveStyleTab('text')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'text' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Cor Texto</button>
                 <button type="button" onClick={() => setActiveStyleTab('font')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'font' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fonte</button>
              </div>

              {activeStyleTab === 'bg' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {BG_OPTIONS.map(bg => (
                       <button
                         key={bg.id}
                         type="button"
                         onClick={() => setSelectedBg(bg)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all ${bg.id === 'transparent' ? 'bg-white border-dashed border-gray-400' : bg.class} ${selectedBg.id === bg.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-transparent'}`}
                         title={bg.label}
                       >
                         {bg.id === 'transparent' && <span className="text-[8px] font-black text-gray-400">NONE</span>}
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'text' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {TEXT_COLORS.map(color => (
                       <button
                         key={color.id}
                         type="button"
                         onClick={() => setSelectedTextColor(color)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all flex items-center justify-center bg-gray-800 ${selectedTextColor.id === color.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-gray-600'}`}
                         title={color.label}
                       >
                         <div className={`w-6 h-6 rounded-full ${color.class.replace('text-', 'bg-')}`}></div>
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'font' && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                    {FONT_OPTIONS.map(font => (
                       <button
                         key={font.id}
                         type="button"
                         onClick={() => setSelectedFont(font)}
                         className={`px-4 py-2 rounded-xl text-sm border transition-all whitespace-nowrap ${font.class} ${selectedFont.id === font.id ? 'bg-white dark:bg-white/10 border-blue-600 text-blue-600 shadow-md' : 'border-transparent text-gray-500 hover:bg-white/50'}`}
                       >
                          {font.label}
                       </button>
                    ))}
                </div>
              )}
           </div>
        )}

        {/* UPLOAD DE IMAGEM */}
        {postType === PostType.IMAGE && (
          <div className="relative">
             <div onClick={() => imageInputRef.current?.click()} className="w-full h-80 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-all overflow-hidden bg-gray-50 dark:bg-white/5 group">
               {imageUrl ? (
                 <>
                   <img src={imageUrl} className="w-full h-full object-cover" />
                   <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <span className="text-white font-black text-xs uppercase bg-black/50 px-4 py-2 rounded-xl backdrop-blur-md">Trocar Imagem</span>
                   </div>
                 </>
               ) : (
                 <>
                   <PhotoIcon className="h-12 w-12 text-gray-300 group-hover:text-blue-500 transition-colors" />
                   <p className="text-gray-400 font-black text-xs uppercase mt-2">Clique para carregar</p>
                 </>
               )}
               <input type="file" ref={imageInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
             </div>

             <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full mt-4 p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Adicione uma legenda..." 
               rows={2}
             />
          </div>
        )}

        {/* REELS AREA */}
        {postType === PostType.REEL && (
           <div className="space-y-4">
              {!reelUrl ? (
                 <div className="grid grid-cols-2 gap-4 h-64">
                    <button 
                      type="button"
                      onClick={() => setShowRecordModal(true)}
                      className="bg-gray-900 text-white rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-800 transition-all group border-2 border-gray-800 hover:border-blue-500"
                    >
                       <div className="p-4 bg-red-600 rounded-full group-hover:scale-110 transition-transform shadow-lg shadow-red-900/50">
                          <CameraIcon className="h-8 w-8 text-white" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Gravar Agora</span>
                    </button>

                    <button 
                      type="button"
                      onClick={() => videoInputRef.current?.click()}
                      className="bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-300 rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-100 dark:hover:bg-white/10 transition-all border-2 border-dashed border-gray-200 dark:border-white/10 hover:border-blue-500"
                    >
                       <div className="p-4 bg-white dark:bg-white/10 rounded-full group-hover:scale-110 transition-transform">
                          <VideoCameraIcon className="h-8 w-8 text-blue-500" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Upload Vídeo</span>
                       <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
                    </button>
                 </div>
              ) : (
                 <div className="relative rounded-[2rem] overflow-hidden bg-black aspect-[9/16] max-h-[500px] mx-auto w-full max-w-xs shadow-2xl">
                    <video src={reelUrl} controls className="w-full h-full object-cover" />
                    <button 
                      type="button" 
                      onClick={() => { setReelUrl(''); setReelFile(null); }}
                      className="absolute top-4 right-4 bg-black/60 text-white p-2 rounded-full hover:bg-red-600 transition-colors backdrop-blur-md"
                    >
                       <XMarkIcon className="h-5 w-5" />
                    </button>
                 </div>
              )}

              <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Descreva seu Reel..." 
               rows={2}
             />
           </div>
        )}

        {/* BARRA DE FERRAMENTAS INFERIOR */}
        <div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-white/5">
           <div className="flex gap-2">
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.TEXT); setShowStyleTools(!showStyleTools); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.TEXT && showStyleTools ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Estilo de Texto"
              >
                 <FontIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.IMAGE ? 'bg-green-100 dark:bg-green-900/30 text-green-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Adicionar Foto"
              >
                 <PhotoIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => setPostType(PostType.REEL)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.REEL ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Reel"
              >
                 <FilmIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-yellow-500 transition-all hidden sm:block"
              >
                 <FaceSmileIcon className="h-6 w-6" />
              </button>
           </div>

           <button 
             type="submit" 
             disabled={loading || (!content && !imageFile && !reelFile)} 
             className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all flex items-center gap-2"
           >
             {loading ? 'Enviando...' : <><PaperAirplaneIcon className="h-4 w-4 -rotate-45" /> Publicar</>}
           </button>
        </div>
      </form>

      {showRecordModal && (
        <RecordReelModal 
          onClose={() => setShowRecordModal(false)} 
          onSave={handleRecordedReel} 
        />
      )}
    </div>
  );
};

export default CreatePost;

