      setIsMobileSearchOpen(false);
    }
  };

  return (
    <>
      <header className="bg-white/90 dark:bg-darkbg/90 backdrop-blur-md shadow-sm px-4 md:px-6 py-2 md:py-4 flex justify-between items-center fixed top-0 left-0 w-full z-[100] border-b border-gray-100 dark:border-white/5 h-[64px] md:h-[72px]">
        <div className="flex items-center gap-2">
          {currentUser && (
            <button 
              onClick={onToggleMenu}
              className="md:hidden p-2 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5 rounded-xl transition-all active:scale-90"
              aria-label="Menu"
            >
              <Bars3Icon className="h-7 w-7" />
            </button>
          )}
          <div className="cursor-pointer" onClick={() => onNavigate('feed')}>
            <Logo size="md" />
          </div>
        </div>

        {currentUser && (
          <form onSubmit={handleSearchSubmit} className="hidden lg:flex flex-1 max-w-md mx-8 relative group">
            <div className="relative w-full text-gray-400 focus-within:text-brand transition-colors">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MagnifyingGlassIcon className="h-4 w-4" />
              </div>
              <input
                type="text"
                className="block w-full pl-9 pr-4 py-2 border border-gray-100 dark:border-white/10 rounded-xl bg-gray-50 dark:bg-white/5 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-brand text-sm transition-all shadow-inner dark:text-white"
                placeholder="Buscar na rede..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </form>
        )}

        {currentUser ? (
          <div className="flex items-center gap-2 md:gap-4 flex-shrink-0">
            <button onClick={() => setIsMobileSearchOpen(true)} className="lg:hidden p-2 text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 rounded-xl">
              <MagnifyingGlassIcon className="h-6 w-6" />
            </button>
            <button onClick={onOpenCart} className="p-2 rounded-xl text-gray-600 dark:text-gray-400 relative transition-colors hover:bg-gray-100 dark:hover:bg-white/5">
              <ShoppingCartIcon className="h-6 w-6" />
              {cartItemCount > 0 && (
                <span className="absolute top-1 right-1 bg-brand text-white text-[8px] font-black rounded-full h-4 w-4 flex items-center justify-center border-2 border-white dark:border-darkbg">
                  {cartItemCount}
                </span>
              )}
            </button>
            <button onClick={() => onNavigate('notifications')} className="p-2 rounded-xl text-gray-600 dark:text-gray-400 relative transition-colors hover:bg-gray-100 dark:hover:bg-white/5">
              <BellIcon className="h-6 w-6" />
              {unreadNotificationsCount > 0 && (
                <span className="absolute top-1 right-1 bg-red-600 text-white text-[8px] font-black rounded-full h-4 w-4 flex items-center justify-center border-2 border-white dark:border-darkbg animate-pulse">
                  {unreadNotificationsCount > 9 ? '9+' : unreadNotificationsCount}
                </span>
              )}
            </button>
            <img
              src={currentUser.profilePicture || DEFAULT_PROFILE_PIC}
              alt="Profile"
              className="w-8 h-8 md:w-10 md:h-10 rounded-xl object-cover cursor-pointer border-2 border-transparent hover:border-brand transition-all shadow-sm"
              onClick={() => onNavigate('profile')}
            />
          </div>
        ) : (
          <button onClick={() => onNavigate('auth')} className="bg-brand hover:bg-brandHover text-white px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">Entrar</button>
        )}
      </header>

      {isMobileSearchOpen && (
        <div className="fixed inset-0 z-[110] bg-white dark:bg-darkbg animate-fade-in lg:hidden">
          <div className="flex items-center p-4 border-b border-gray-100 dark:border-white/5">
            <button onClick={() => setIsMobileSearchOpen(false)} className="p-2 text-gray-500 dark:text-gray-400 mr-2">
              <ArrowLeftIcon className="h-7 w-7" />
            </button>
            <form onSubmit={handleSearchSubmit} className="flex-1">
              <input autoFocus type="text" placeholder="Buscar na CyBerPhone..." className="w-full bg-transparent text-lg font-bold outline-none dark:text-white" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
            </form>
          </div>
        </div>
      )}
    </>
  );
};

export default Header;

import React, { useState } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import Logo from './Logo';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      if (isRegister) {
        const user = await registerUser({ firstName, lastName, email, password, userType: UserType.STANDARD });
        onLoginSuccess(user);
      } else {
        const user = await loginUser(email, password);
        onLoginSuccess(user);
      }
    } catch (err: any) {
      setError(err.message || 'Falha na autenticação.');
    } finally {
      setLoading(false);
    }
  };

  const inputClass = "w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-brand dark:text-white font-bold transition-all shadow-inner";

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-[#0a0c10] p-4">
      <div className="bg-white dark:bg-darkcard p-8 md:p-12 rounded-[3rem] shadow-2xl w-full max-w-md border border-gray-100 dark:border-white/5 animate-fade-in">
        <div className="mb-10 flex flex-col items-center">
          <Logo size="xl" />
          <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.3em] mt-4">Rede Social Educacional</p>
        </div>

        {error && <div className="mb-6 p-4 bg-red-50 text-red-600 rounded-2xl text-xs font-black uppercase text-center border border-red-100">{error}</div>}

        <form onSubmit={handleAuth} className="space-y-4">
          {isRegister && (
            <div className="grid grid-cols-2 gap-3">
              <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClass} required />
              <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className={inputClass} required />
            </div>
          )}
          <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className={inputClass} required />
          <input type="password" placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className={inputClass} required />

          <button 
            type="submit" 
            disabled={loading}
            className="w-full py-5 bg-brand hover:bg-brandHover text-white rounded-3xl font-black uppercase text-sm shadow-xl shadow-brand/20 active:scale-95 transition-all disabled:opacity-50"
          >
            {loading ? 'Aguarde...' : isRegister ? 'Criar Conta' : 'Entrar na Rede'}
          </button>
        </form>

        <button 
          onClick={() => setIsRegister(!isRegister)} 
          className="w-full mt-8 text-center text-gray-400 hover:text-brand font-black uppercase text-[10px] tracking-widest transition-colors"
        >
          {isRegister ? 'Já tenho uma conta' : 'Não tenho cadastro'}
        </button>
      </div>
    </div>
  );
};

export default AuthPage;

import React, { useState, useEffect, useCallback } from 'react';
import { User, CartItem, GlobalSettings, GroupTheme } from './types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    getGlobalSettings,
    getAppTheme,
    saveAppTheme
} from './services/storageService';
import Header from './components/Header';
import Footer from './components/Footer';
import AuthPage from './components/AuthPage';
import FeedPage from './components/FeedPage';
import ProfilePage from './components/ProfilePage';
import ChatPage from './components/ChatPage';
import AdCampaignPage from './components/AdCampaignPage';
import LiveStreamViewer from './components/LiveStreamViewer';
import { StorePage } from './components/StorePage';
import StoreManagerPage from './components/StoreManagerPage';
import ReelsPage from './components/ReelsPage';
import SearchResultsPage from './components/SearchResultsPage';
import NotificationsPage from './components/NotificationsPage';
import CartModal from './components/CartModal';
import WalletModal from './components/WalletModal';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import EventsPage from './components/EventsPage';
import PurchasesPage from './components/PurchasesPage';
import AffiliatesPage from './components/AffiliatesPage';
import CreateGroupPage from './components/CreateGroupPage';
import { ExclamationTriangleIcon } from '@heroicons/react/24/solid';
import { requestNotificationPermission } from './services/notificationService';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates' | 'create-group';

const THEME_MAP: Record<GroupTheme, { primary: string, hover: string, light: string }> = {
  blue: { primary: '#2563eb', hover: '#1d4ed8', light: '#eff6ff' },
  green: { primary: '#10b981', hover: '#059669', light: '#ecfdf5' },
  black: { primary: '#18181b', hover: '#09090b', light: '#27272a' },
  orange: { primary: '#f97316', hover: '#ea580c', light: '#fff7ed' }
};

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [appTheme, setAppTheme] = useState<GroupTheme>(() => getAppTheme());
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    const changeAppTheme = useCallback((newTheme: GroupTheme) => {
        setAppTheme(newTheme);
        saveAppTheme(newTheme);
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    requestNotificationPermission().catch(() => {});
                } else {
                    setCurrentUser(null);
                }
            } else {
                setCurrentUser(null);
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        refreshCurrentUser();
    }, [refreshCurrentUser]);

    useEffect(() => {
        if (currentUser && currentPage === 'auth') {
            setCurrentPage('feed');
        } else if (!currentUser && !isLoading && currentPage !== 'auth') {
            setCurrentPage('auth');
        }
    }, [currentUser, currentPage, isLoading]);

    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && event.state.page) {
                setCurrentPage(event.state.page);
                setPageParams(event.state.params || {});
            } else if (!currentUser) {
                setCurrentPage('auth');
            } else {
                setCurrentPage('feed');
            }
        };

        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, [currentUser]);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
        window.history.pushState({ page: 'feed' }, '', '#feed');
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
        window.history.pushState({ page: 'auth' }, '', '#auth');
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }

        window.history.pushState({ page, params }, '', `#${page}`);

        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-brand mb-6 shadow-[0_0_15px_rgba(37,99,235,0.3)]"></div>
                <div className="flex flex-col items-center gap-2">
                   <h1 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">CyBerPhone <span className="text-brand">Pro</span></h1>
                   <p className="text-[9px] font-bold uppercase text-gray-400 tracking-[0.3em] animate-pulse">Carregando Ecossistema v1.3.1</p>
                </div>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-16 w-16 text-red-500 mb-6" />
                <h2 className="text-2xl font-black uppercase mb-2 text-gray-900 dark:text-white">Erro de Inicialização</h2>
                <p className="text-gray-500 text-sm mb-8 font-medium">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-brand text-white px-10 py-4 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={changeAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[72px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''}`}>
                    <div className="max-w-7xl mx-auto">{renderPage()}</div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport,
  updatePostShares
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Optimistic UI states
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);
  const [localSaves, setLocalSaves] = useState<string[]>(post.saves || []);
  const [isSaved, setIsSaved] = useState(post.saves?.includes(currentUser.id) || false);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
    setLocalSaves(post.saves || []);
    setIsSaved(post.saves?.includes(currentUser.id) || false);
  }, [post.likes, post.saves, currentUser.id]);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevIsLiked);
    if (prevIsLiked) {
      setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostLikes(post.id, currentUser.id);
      // We don't strictly need to reload everything if the optimistic update worked, 
      // but we do it to sync eventually
      // onPostUpdatedOrDeleted(); 
    } catch (error) {
      // Revert if failed
      setIsLiked(prevIsLiked);
      setLocalLikes(prevLikes);
      console.error("Falha ao curtir post", error);
    }
  };

  const handleSave = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsSaved = isSaved;
    const prevSaves = [...localSaves];

    setIsSaved(!prevIsSaved);
    if (prevIsSaved) {
      setLocalSaves(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalSaves(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostSaves(post.id, currentUser.id);
    } catch (error) {
      setIsSaved(prevIsSaved);
      setLocalSaves(prevSaves);
    }
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE) onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else setShowDetailModal(true);
        }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group transform transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 animate-fade-in"
      >
        <div className="p-5 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-4 md:gap-5">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1.5 -right-1.5 bg-brand rounded-xl p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-4 w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-base md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-4 w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-4 w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1.5 text-[9px] font-black text-brand uppercase tracking-widest mt-0.5">
                     <UserGroupIcon className="h-3 w-3" /> {post.groupName}
                  </div>
                )}
              </div>
              <p className="text-[9px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-3 text-brand">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all"
          >
            <EllipsisHorizontalIcon className="h-7 w-7" />
          </button>
        </div>

        <div className={`px-5 md:px-8 ${hasBg ? 'pb-8' : 'pb-5 md:pb-8'}`}>
          {post.type === PostType.LIVE && post.liveStream ? (
