export const addPostComment = async (postId: string, comment: Comment) => {
  const { data } = await supabase.from('posts').select('comments, user_id').eq('id', postId).single();
  if (data) {
    const comments = [...(data.comments || []), comment];
    await supabase.from('posts').update({ comments }).eq('id', postId);
    createNotification({ type: NotificationType.COMMENT, recipientId: data.user_id, actorId: comment.userId, postId, timestamp: Date.now() });
  }
};

export const indicatePostToUser = async (postId: string, fromId: string, toId: string) => {
  const { data } = await supabase.from('posts').select('indicated_user_ids').eq('id', postId).single();
  if (data) {
    let list = data.indicated_user_ids || [];
    if (list.includes(toId)) return false;
    list.push(toId);
    await supabase.from('posts').update({ indicated_user_ids: list }).eq('id', postId);
    createNotification({ type: NotificationType.INDICATION, recipientId: toId, actorId: fromId, postId, timestamp: Date.now() });
    return true;
  }
  return false;
};

export const boostPost = async (postId: string, userId: string, budget: number, days: number) => {
  const success = await updateUserBalance(userId, -budget);
  if (success) {
    const expires = Date.now() + (days * 86400000);
    await supabase.from('posts').update({ is_boosted: true, boost_expires: expires }).eq('id', postId);
    return true;
  }
  return false;
};

