export const toggleJoinEvent = async (eventId: string, userId: string) => {
    const { data } = await supabase.from('events').select('attendees').eq('id', eventId).single();
    if (data) {
        let list = data.attendees || [];
        if (list.includes(userId)) list = list.filter((id: string) => id !== userId);
        else list.push(userId);
