export const registerUser = async (userData: any): Promise<User> => {
  const id = generateUUID();
  const newUser: User = {
    id,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials,
    bio: userData.bio,
    verificationFileUrl: userData.verificationFileUrl
  };

  const { error } = await supabase.from('profiles').insert({
    id: newUser.id,
    email: newUser.email,
    first_name: newUser.firstName,
    last_name: newUser.lastName,
    user_type: newUser.userType,
    phone: newUser.phone,
    document_id: newUser.documentId,
    birth_date: newUser.birthDate,
    profile_picture: newUser.profilePicture,
    credentials: newUser.credentials,
    bio: newUser.bio,
    balance: 0,
    is_admin: false,
    is_verified: false,
    is_suspended: false,
    followed_users: [],
    followers: []
  });

  if (error) throw error;

  if (newUser.userType === UserType.CREATOR) {
    const storeId = generateUUID();
    await supabase.from('stores').insert({
      id: storeId,
      professor_id: newUser.id,
      name: `Loja de ${newUser.firstName}`,
      description: 'Bem-vindo à minha loja!',
      product_ids: []
    });
    newUser.storeId = storeId;
    await supabase.from('profiles').update({ store_id: storeId }).eq('id', newUser.id);
  }

  return newUser;
};

