    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    // Referência para controlar qual foi a última notificação vista pelo sistema de polling
    const lastNotificationIdRef = useRef<string | null>(null);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    const changeAppTheme = useCallback((newTheme: GroupTheme) => {
        setAppTheme(newTheme);
        saveAppTheme(newTheme);
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    // --- SISTEMA DE POLLING PARA NOTIFICAÇÕES (Simula Push) ---
    useEffect(() => {
        if (!currentUser) return;

        // Intervalo de verificação (ex: a cada 5 segundos)
        const pollInterval = setInterval(async () => {
            try {
                const notifications = await getNotificationsForUser(currentUser.id);
                // Ordena por mais recente
                const sorted = notifications.sort((a, b) => b.timestamp - a.timestamp);

                if (sorted.length > 0) {
                    const latest = sorted[0];
                    setUnreadNotificationsCount(sorted.filter(n => !n.isRead).length);

                    // Se encontrou uma notificação mais recente que a última verificada e ela não foi lida
                    if (lastNotificationIdRef.current && latest.id !== lastNotificationIdRef.current && !latest.isRead) {
                        const actor = await findUserById(latest.actorId);
                        if (actor) {
                            const content = getNotificationContent(latest.type, actor.firstName, latest.groupName);
                            showNotification(content.title, { 
                                body: content.body,
                                icon: actor.profilePicture,
                                url: window.location.origin
                            });
                        }
                    }
                    lastNotificationIdRef.current = latest.id;
                }
            } catch (err) {
                // Silently fail on poll error
            }
        }, 5000);

        return () => clearInterval(pollInterval);
    }, [currentUser]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    const notifications = await getNotificationsForUser(user.id);
                    const sorted = notifications.sort((a, b) => b.timestamp - a.timestamp);
                    if (sorted.length > 0) lastNotificationIdRef.current = sorted[0].id;

                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');

                    // Solicita permissão para notificações ao carregar usuário
                    requestNotificationPermission();
                } else {
                    setCurrentPage('auth');
                }
            } else {
                setCurrentPage('auth');
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, [currentPage]);

    useEffect(() => {
        refreshCurrentUser();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
        requestNotificationPermission();
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
        lastNotificationIdRef.current = null;
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-brand mb-6 shadow-[0_0_15px_rgba(37,99,235,0.3)]"></div>
                <div className="flex flex-col items-center gap-2">
                   <h1 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">CyBerPhone <span className="text-brand">Pro</span></h1>
                   <p className="text-[9px] font-bold uppercase text-gray-400 tracking-[0.3em] animate-pulse">Carregando Ecossistema v1.3.1</p>
                </div>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-16 w-16 text-red-500 mb-6" />
                <h2 className="text-2xl font-black uppercase mb-2 text-gray-900 dark:text-white">Erro de Inicialização</h2>
                <p className="text-gray-500 text-sm mb-8 font-medium">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-brand text-white px-10 py-4 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={changeAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1 relative">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[80px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''} overflow-x-hidden`}>
                    <div className="max-w-7xl mx-auto min-h-[calc(100vh-140px)] animate-fade-in">
                        {renderPage()}
                    </div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Post, AdCampaign, PostType, Story, CyberEvent, ChatConversation } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents, getChats, joinGroup } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import GroupDiscoveryCard from './GroupDiscoveryCard';
import { PlusIcon, ArrowPathIcon, RocketLaunchIcon, ChevronUpIcon, FireIcon, SparklesIcon, CalendarIcon, UserGroupIcon, StarIcon, ArrowTrendingUpIcon, PlayIcon, FilmIcon } from '@heroicons/react/24/outline';
import { TrophyIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

type FeedItem = 
  | Post 
  | AdCampaign 
  | ChatConversation 
  | { type: 'SUGGESTIONS' } 
  | { type: 'REELS_SHELF'; items: Post[] } 
  | { type: 'GROUPS_SHELF'; items: ChatConversation[] };

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<FeedItem[]>([]);
  const [visibleItems, setVisibleItems] = useState<FeedItem[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [stories, setStories] = useState<Story[]>([]);
  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async (isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    const [allPosts, allAds, allUsers, allStories, allChats] = await Promise.all([
      getPosts(),
      getAds(),
      getUsers(),
      getStories(),
      getChats()
    ]);

    // Filtrar Posts Normais e Reels
    const normalPosts = allPosts.filter(p => p.type !== PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);
    const reelsPosts = allPosts.filter(p => p.type === PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);

    const activeAds = allAds.filter(a => a.isActive).sort((a, b) => (b.budget || 0) - (a.budget || 0));

    // Filtrar Grupos Públicos que o usuário NÃO participa
    const publicGroups = allChats.filter(c => 
      c.type === 'GROUP' && 
      c.isPublic && 
      !c.participants.includes(currentUser.id)
    );

    setStories(allStories);

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);
    setSuggestedUsers(suggestions);

    let combined: FeedItem[] = [];
    let adPointer = 0;

    // Estratégia de Mixagem do Feed

    // 1. Bloco inicial de posts
    const firstBatch = normalPosts.slice(0, 3);
    combined.push(...firstBatch);

    // 2. Prateleira de Reels (se houver)
    if (reelsPosts.length > 0) {
      combined.push({ type: 'REELS_SHELF', items: reelsPosts.slice(0, 10) });
    }

    // 3. Bloco de Sugestões de Usuários
    if (suggestions.length > 0) {
      combined.push({ type: 'SUGGESTIONS' });
    }

    // 4. Prateleira de Grupos (se houver)
    if (publicGroups.length > 0) {
      combined.push({ type: 'GROUPS_SHELF', items: publicGroups.slice(0, 5) });
    }

    // 5. Restante dos posts com Ads intercalados
    const remainingPosts = normalPosts.slice(3);
    remainingPosts.forEach((post, idx) => {
        combined.push(post);
        // Inserir Ad a cada 5 posts
        if ((idx + 1) % 5 === 0 && adPointer < activeAds.length) {
            combined.push(activeAds[adPointer]);
            adPointer++;
        }
    });

    setAllItems(combined);
    setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
    setDisplayLimit(ITEMS_PER_PAGE);
    setLoading(false);
  }, [currentUser]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  useEffect(() => {
    const handleScroll = () => setShowScrollTop(window.scrollY > 1000);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleJoin = async (groupId: string) => {
    await joinGroup(groupId, currentUser.id);
    loadData(true);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);
  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  return (
    <div className="w-full max-w-[1400px] mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-8 relative">
      <div className="fixed bottom-24 right-6 z-[100] flex flex-col gap-3">
        {showScrollTop && (
          <button onClick={scrollToTop} className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all">
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button 
          onClick={() => onNavigate('ads')} 
          className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all flex items-center justify-center"
          title="Criar Anúncio"
        >
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      {/* STORIES BAR */}
      <div className="flex gap-4 overflow-x-auto pb-6 pt-2 no-scrollbar mb-4">
         <div onClick={() => setIsCreatingStory(true)} className="flex-shrink-0 w-20 h-32 bg-white dark:bg-darkcard rounded-2xl shadow-md border border-dashed border-blue-300 dark:border-blue-900/50 flex flex-col items-center justify-center cursor-pointer group hover:border-blue-500 transition-all">
            <div className="bg-blue-50 dark:bg-white/5 p-2 rounded-full mb-2 group-hover:bg-blue-600 group-hover:text-white transition-colors">
               <PlusIcon className="h-5 w-5 text-blue-600 group-hover:text-white" />
            </div>
            <span className="text-[9px] font-black uppercase text-gray-400 group-hover:text-blue-600">Criar</span>
         </div>

         {stories.map((story, i) => (
            <div key={i} onClick={() => setSelectedStoryIndex(i)} className="flex-shrink-0 w-20 h-32 rounded-2xl overflow-hidden relative cursor-pointer group shadow-lg border-2 border-transparent hover:border-blue-500 transition-all">
               <img src={story.items?.[0]?.imageUrl || story.userProfilePic} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
               <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
               <div className="absolute bottom-2 left-2 right-2 text-center">
                  <p className="text-[8px] font-black text-white uppercase truncate">{(story.userName || 'Membro').split(' ')[0]}</p>
               </div>
               <div className="absolute top-2 left-2 w-6 h-6 rounded-full border-2 border-blue-600 overflow-hidden">
                  <img src={story.userProfilePic} className="w-full h-full object-cover" />
               </div>
            </div>
         ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Sincronizando Feed...</p>
              </div>
            ) : (
              <>
                {visibleItems.map((item: any, idx) => {
                  // RENDERIZAÇÃO DE POST NORMAL
                  if (item.authorName) { 
                    return <PostCard key={item.id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
                  }

                  // RENDERIZAÇÃO DE ADS
                  if (item.professorId) { 
                    return <AdCard key={item.id} ad={item as AdCampaign} rank={idx} />;
                  }

                  // RENDERIZAÇÃO DE SUGESTÕES DE USUÁRIOS
                  if (item.type === 'SUGGESTIONS') {
                    return (
                      <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden animate-fade-in my-6">
                         <SparklesIcon className="absolute -right-10 -bottom-10 w-72 h-72 opacity-10" />
                         <div className="flex items-center justify-between mb-8">
                            <div>
                               <h4 className="font-black text-2xl tracking-tighter flex items-center gap-3"><FireIcon className="h-8 w-8 text-yellow-400" /> Networking</h4>
                               <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Sugestões de Conexão CyBer</p>
                            </div>
                            <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all"><ArrowPathIcon className="h-6 w-6"/></button>
                         </div>
                         <div className="flex gap-5 overflow-x-auto pb-4 no-scrollbar">
                            {suggestedUsers.map(u => (
                              <div key={u.id} className="bg-white/10 backdrop-blur-xl p-6 rounded-[2.5rem] min-w-[180px] flex flex-col items-center text-center border border-white/10 group">
                                 <img src={u.profilePicture} className="w-20 h-20 rounded-2xl object-cover mb-3 border-2 border-white/20 shadow-xl group-hover:scale-110 transition-transform" />
                                 <p className="font-black text-sm truncate w-full">{u.firstName} {u.lastName}</p>
                                 <p className="text-[8px] font-black text-blue-200 uppercase mb-4 tracking-tighter">{u.credentials || 'Especialista'}</p>
                                 <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-800 py-2.5 rounded-xl font-black text-[9px] uppercase shadow-lg active:scale-95 transition-all">Seguir</button>
                              </div>
                            ))}
                         </div>
                      </div>
                    );
                  }

                  // RENDERIZAÇÃO DA PRATELEIRA DE REELS
                  if (item.type === 'REELS_SHELF') {
                    return (
                      <div key="reels-shelf" className="my-6">
                        <div className="flex items-center gap-2 mb-4 px-2">
                           <FilmIcon className="h-6 w-6 text-purple-600" />
                           <h3 className="font-black text-lg dark:text-white uppercase tracking-tighter">Reels em Alta</h3>
                        </div>
                        <div className="flex gap-4 overflow-x-auto pb-6 no-scrollbar snap-x">
                           {item.items.map((reel: Post) => (
                             <div 
                               key={reel.id} 
                               onClick={() => onNavigate('reels-page', { startPostId: reel.id })}
                               className="relative min-w-[160px] h-[280px] rounded-[1.5rem] overflow-hidden cursor-pointer group shadow-lg snap-start border border-gray-100 dark:border-white/5"
                             >
                                <video src={reel.reel?.videoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" muted />
                                <div className="absolute inset-0 bg-black/20 group-hover:bg-black/40 transition-colors flex items-center justify-center">
                                   <div className="bg-white/20 backdrop-blur-md p-3 rounded-full">
                                      <PlayIcon className="h-6 w-6 text-white fill-white" />
                                   </div>
                                </div>
                                <div className="absolute bottom-0 left-0 w-full p-3 bg-gradient-to-t from-black/90 to-transparent">
                                   <p className="text-white text-[10px] font-bold line-clamp-2 leading-tight">{reel.reel?.description}</p>
                                   <p className="text-white/60 text-[8px] font-black uppercase mt-1">@{reel.authorName}</p>
                                </div>
                             </div>
                           ))}
                        </div>
                      </div>
                    );
                  }

                  // RENDERIZAÇÃO DA PRATELEIRA DE GRUPOS
                  if (item.type === 'GROUPS_SHELF') {
                    return (
                      <div key="groups-shelf" className="my-6 bg-gray-50 dark:bg-white/5 p-6 rounded-[2.5rem] border border-gray-100 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-4">
                           <UserGroupIcon className="h-6 w-6 text-blue-600" />
                           <h3 className="font-black text-lg dark:text-white uppercase tracking-tighter">Comunidades</h3>
                        </div>
                        <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar snap-x">
                           {item.items.map((group: ChatConversation) => (
                             <div key={group.id} className="min-w-[260px] snap-start">
                                <GroupDiscoveryCard group={group} onJoin={() => handleJoin(group.id)} />
                             </div>
                           ))}
                        </div>
                      </div>
                    );
                  }

                  return null;
                })}

                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Buscando mais conteúdos...</p>
