export const sendMessage = async (chatId: string, msg: Message) => {
    const { data } = await supabase.from('chats').select('messages, participants, type, group_name').eq('id', chatId).single();
    if (data) {
        const messages = [...(data.messages || []), msg];
        await supabase.from('chats').update({ messages }).eq('id', chatId);

        // Criar notificação para os destinatários
        const recipients = (data.participants || []).filter((id: string) => id !== msg.senderId);

        for (const recipientId of recipients) {
          createNotification({
            type: data.type === 'GROUP' ? NotificationType.GROUP_POST : NotificationType.MESSAGE,
            recipientId: recipientId,
            actorId: msg.senderId,
            timestamp: Date.now(),
            groupName: data.type === 'GROUP' ? data.group_name : undefined
          });
        }
    }
};

