// --- FOLLOW & NOTIFICATIONS ---
export const toggleFollowUser = async (currentUserId: string, targetUserId: string) => {
    const { data: current } = await supabase.from('profiles').select('followed_users').eq('id', currentUserId).single();
    const { data: target } = await supabase.from('profiles').select('followers').eq('id', targetUserId).single();
    if (current && target) {
        let followed = current.followed_users || [];
        let followers = target.followers || [];
        if (followed.includes(targetUserId)) {
            followed = followed.filter((id: string) => id !== targetUserId);
            followers = followers.filter((id: string) => id !== currentUserId);
        } else {
            followed.push(targetUserId);
            followers.push(currentUserId);
            createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetUserId, actorId: currentUserId, timestamp: Date.now() });
        }
        await supabase.from('profiles').update({ followed_users: followed }).eq('id', currentUserId);
        await supabase.from('profiles').update({ followers: followers }).eq('id', targetUserId);
    }
};

export const createNotification = async (notificationData: Omit<Notification, 'id' | 'isRead'>) => {
  if (notificationData.recipientId === notificationData.actorId) return;
  await supabase.from('notifications').insert({
    id: generateUUID(),
    recipient_id: notificationData.recipientId,
    actor_id: notificationData.actorId,
    type: notificationData.type,
    timestamp: notificationData.timestamp,
    post_id: notificationData.postId,
    sale_id: notificationData.saleId,
    is_read: false,
    group_name: notificationData.groupName
  });
};

