// --- CART ---
export const updateCartItemQuantity = (productId: string, quantity: number) => {
  const cartJson = localStorage.getItem(CART_KEY);
  let cart: CartItem[] = cartJson ? JSON.parse(cartJson) : [];
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) item.quantity = quantity;
  }
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const removeFromCart = (productId: string) => {
  const cartJson = localStorage.getItem(CART_KEY);
  let cart: CartItem[] = cartJson ? JSON.parse(cartJson) : [];
  cart = cart.filter(item => item.productId !== productId);
  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
    for (const item of cartItems) {
        const prod = await findProductById(item.productId);
        if (!prod) continue;
        const store = await findStoreById(prod.storeId);
        if (!store) continue;
        const total = prod.price * item.quantity;

        let finalAffiliateId = affiliateUserId;
        if (affiliateUserId === buyerId) {
            finalAffiliateId = null;
        }

        const commission = finalAffiliateId ? total * prod.affiliateCommissionRate : 0;
        const net = total - commission;

        const owner = await findUserById(store.professorId);
        if (owner) await updateUserBalance(owner.id, net);

        if (finalAffiliateId) {
            await updateUserBalance(finalAffiliateId, commission);
            createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: finalAffiliateId, actorId: buyerId, saleId: '', timestamp: Date.now() });
        }

        await supabase.from('affiliate_sales').insert({
            id: generateUUID(),
            product_id: item.productId,
            buyer_id: buyerId,
            affiliate_user_id: finalAffiliateId || '',
            store_id: prod.storeId,
            commission_earned: commission,
            sale_amount: total,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            is_rated: false,
            shipping_address: shippingAddress,
            digital_content_url: prod.digitalContentUrl,
            is_dropshipping: prod.isDropshipping || false,
            supplier_cost: prod.originalPrice || 0,
            supplier_order_id: null,
            tracking_code: null
        });
    }
    localStorage.setItem(CART_KEY, JSON.stringify([]));
    return true;
};

