export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2)}.jpg`;
  const { error } = await supabase.storage.from('cyberphone').upload(fileName, file);
  if (error) {
      console.warn("Upload falhou, usando blob local:", error);
      return URL.createObjectURL(file);
  }
  const { data: { publicUrl } } = supabase.storage.from('cyberphone').getPublicUrl(fileName);
  return publicUrl;
};

