export const sendMessage = async (chatId: string, msg: Message) => {
    const { data } = await supabase.from('chats').select('messages, participants, type, group_name').eq('id', chatId).single();
    if (data) {
        const messages = [...(data.messages || []), msg];
        await supabase.from('chats').update({ messages }).eq('id', chatId);

        // Criar notificação para os destinatários
        const recipients = (data.participants || []).filter((id: string) => id !== msg.senderId);

        for (const recipientId of recipients) {
          createNotification({
            type: data.type === 'GROUP' ? NotificationType.GROUP_POST : NotificationType.MESSAGE,
            recipientId: recipientId,
            actorId: msg.senderId,
            timestamp: Date.now(),
            groupName: data.type === 'GROUP' ? data.group_name : undefined
          });
        }
    }
};

export const updateGroupTheme = async (chatId: string, theme: GroupTheme) => {
    await supabase.from('chats').update({ theme }).eq('id', chatId);
};

export const joinGroup = async (groupId: string, userId: string) => {
    const { data } = await supabase.from('chats').select('participants').eq('id', groupId).single();
    if (data) {
        let parts = data.participants || [];
        if (!parts.includes(userId)) {
            parts.push(userId);
            await supabase.from('chats').update({ participants: parts }).eq('id', groupId);
        }
    }
};

export const createGroup = async (name: string, participants: string[], adminId: string, description: string, theme: GroupTheme) => {
    const id = generateUUID();
    const { error } = await supabase.from('chats').insert({
        id,
        type: ChatType.GROUP,
        group_name: name,
        participants: [...participants, adminId],
        admin_id: adminId,
        description,
        theme,
        messages: [],
        is_public: true
    });
    if (error) throw error;
    return id;
};

// --- STORIES ---
export const getStories = async (): Promise<Story[]> => {
  const { data } = await supabase.from('stories').select('*');
  if (!data) return [];

  // Lógica para filtrar stories com mais de 24 horas
  const now = Date.now();
  const storyLifetime = 24 * 60 * 60 * 1000; 

  const validStories = data.map((story: any) => {
    const activeItems = (story.items || []).filter((item: StoryItem) => {
      return (now - item.timestamp) < storyLifetime;
    });

    if (activeItems.length === 0) return null;

    return {
      userId: story.user_id,
      userName: story.user_name,
      userProfilePic: story.user_profile_pic,
      items: activeItems
    };
  }).filter(Boolean);

  return validStories as Story[];
};

export const addStory = async (userId: string, item: any) => {
    const { data: user } = await supabase.from('profiles').select('first_name, profile_picture').eq('id', userId).single();
    if (!user) throw new Error("Usuário não encontrado para criar story.");

    const { data: existing } = await supabase.from('stories').select('*').eq('user_id', userId).maybeSingle();

    const storyItem: StoryItem = { ...item, id: generateUUID(), timestamp: Date.now() };

    if (existing) {
        const items = [...(existing.items || []), storyItem];
        const { error } = await supabase.from('stories').update({ items }).eq('user_id', userId);
        if (error) throw error;
    } else {
        const { error } = await supabase.from('stories').insert({
            user_id: userId,
            user_name: user.first_name,
            user_profile_pic: user.profile_picture || DEFAULT_PROFILE_PIC,
            items: [storyItem]
        });
        if (error) throw error;
    }
};

