import { GoogleGenAI, Type } from '@google/genai';

// Obtém a chave diretamente. O Vite substituirá process.env.API_KEY pelo valor do .env.
const getApiKey = () => {
  // Tenta acessar a variável injetada
  const key = process.env.API_KEY;

  if (key && key.length > 0) return key;

  // Fallback para window.process se definido (polyfill)
  if (typeof window !== 'undefined' && (window as any).process?.env?.API_KEY) {
    return (window as any).process.env.API_KEY;
  }

  return '';
};

const getAiClient = () => {
  const apiKey = getApiKey();
  if (!apiKey) {
    console.warn("API Key do Gemini não encontrada ou vazia.");
  }
  return new GoogleGenAI({ apiKey });
};

