  { id: 'purple', class: 'bg-purple-600', label: 'Roxo' },
  { id: 'fuchsia', class: 'bg-fuchsia-600', label: 'Fúcsia' },
  { id: 'pink', class: 'bg-pink-500', label: 'Rosa' },
  { id: 'rose', class: 'bg-rose-500', label: 'Rose' },
  // Gradientes
  { id: 'grad-sunset', class: 'bg-gradient-to-br from-orange-500 to-pink-600', label: 'Pôr do Sol' },
  { id: 'grad-ocean', class: 'bg-gradient-to-br from-blue-400 to-emerald-400', label: 'Oceano' },
  { id: 'grad-berry', class: 'bg-gradient-to-br from-purple-600 to-red-500', label: 'Berry' },
  { id: 'grad-dark', class: 'bg-gradient-to-br from-slate-900 to-slate-700', label: 'Dark' },
