    const { data: target } = await supabase.from('profiles').select('followers').eq('id', targetUserId).single();
    if (current && target) {
        let followed = current.followed_users || [];
        let followers = target.followers || [];
        if (followed.includes(targetUserId)) {
            followed = followed.filter((id: string) => id !== targetUserId);
            followers = followers.filter((id: string) => id !== currentUserId);
        } else {
            followed.push(targetUserId);
            followers.push(currentUserId);
