export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    const success = await updateUserBalance(userId, -cost);
    if (success) {
        await supabase.from('affiliate_sales').update({ 
            status: OrderStatus.PROCESSING_SUPPLIER,
            supplier_cost: cost
        }).eq('id', saleId);
        return true;
