const CreatePost: React.FC<CreatePostProps> = ({ currentUser, onPostCreated, refreshUser, postId, onCancel }) => {
  const [isExpanded, setIsExpanded] = useState(!!postId);
  const [postType, setPostType] = useState<PostType>(PostType.TEXT);
  const [content, setContent] = useState('');

  // Customizações de Texto
  const [selectedBg, setSelectedBg] = useState(BG_OPTIONS[0]);
  const [selectedTextColor, setSelectedTextColor] = useState(TEXT_COLORS[0]);
  const [selectedFont, setSelectedFont] = useState(FONT_OPTIONS[0]);

  const [showStyleTools, setShowStyleTools] = useState(false);
  const [activeStyleTab, setActiveStyleTab] = useState<StyleTab>('bg');

  // Mídia
  const [imageUrl, setImageUrl] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);

  // Reel Data
  const [reelUrl, setReelUrl] = useState('');
  const [reelFile, setReelFile] = useState<File | Blob | null>(null);
  const [reelMeta, setReelMeta] = useState<{audioTrackId?: string, aiPrompt?: string, filter?: string}>({});

  const [showRecordModal, setShowRecordModal] = useState(false);

  // Configs
  const [selectedGroup, setSelectedGroup] = useState<{id?: string, name: string}>({ name: 'Feed Geral' });
  const [myGroups, setMyGroups] = useState<ChatConversation[]>([]);
  const [showGroupSelector, setShowGroupSelector] = useState(false);
  const [loading, setLoading] = useState(false);
  const [statusText, setStatusText] = useState('Publicar');

  const imageInputRef = useRef<HTMLInputElement>(null);
  const videoInputRef = useRef<HTMLInputElement>(null);

  const isEditing = !!postId;

  // Ajustar cor do texto automaticamente quando muda o fundo
  useEffect(() => {
    if (!selectedBg) return;
    if (selectedBg.id === 'transparent' || selectedBg.id === 'white') {
        const color = TEXT_COLORS.find(c => c.id === 'text-gray-900');
        if (color) setSelectedTextColor(color);
    } else {
        const color = TEXT_COLORS.find(c => c.id === 'text-white');
        if (color) setSelectedTextColor(color);
    }
  }, [selectedBg]);

  useEffect(() => {
    const loadMyGroups = async () => {
       const allChats = await getChats();
       const groups = allChats.filter(c => c.type === 'GROUP' && c.participants.includes(currentUser.id));
       setMyGroups(groups);
    };
    loadMyGroups();
  }, [currentUser.id]);

  const resetForm = () => {
    setIsExpanded(false);
    setPostType(PostType.TEXT);
    setContent('');
    setImageUrl('');
    setReelUrl('');
    setImageFile(null);
    setReelFile(null);
    setReelMeta({});
    setSelectedBg(BG_OPTIONS[0]);
    setSelectedTextColor(TEXT_COLORS[0]);
    setSelectedFont(FONT_OPTIONS[0]);
    setShowStyleTools(false);
    setSelectedGroup({ name: 'Feed Geral' });
    setStatusText('Publicar');
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setImageUrl(URL.createObjectURL(file));
      setPostType(PostType.IMAGE);
      setShowStyleTools(false);
      setReelFile(null); // Limpa reel se houver
    }
  };

  const handleVideoFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setReelFile(file);
      setReelUrl(URL.createObjectURL(file));
      setPostType(PostType.REEL);
      setImageFile(null); // Limpa imagem se houver
    }
  };

  const handleRecordedReel = (videoBlob: Blob, audioTrackId?: string, aiPrompt?: string, filter?: string) => {
    setReelFile(videoBlob);
    setReelUrl(URL.createObjectURL(videoBlob));
    setReelMeta({ audioTrackId, aiPrompt, filter });
    setPostType(PostType.REEL);
    setImageFile(null);
    setShowRecordModal(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() && !imageFile && !reelFile) return;

    setLoading(true);

    try {
      let finalImageUrl = imageUrl;
      let finalReelUrl = reelUrl;

      // 1. Upload de Imagem (se houver)
      if (postType === PostType.IMAGE && imageFile) {
        setStatusText('Enviando Imagem...');
        finalImageUrl = await uploadFile(imageFile, 'posts');
      }

      // 2. Upload de Reel (se houver)
      if (postType === PostType.REEL && reelFile) {
        setStatusText('Enviando Vídeo...');
        finalReelUrl = await uploadFile(reelFile, 'reels');
      }

      setStatusText('Finalizando...');

      const postData: Post = {
        id: isEditing ? postId! : generateUUID(),
        userId: currentUser.id,
        authorName: `${currentUser.firstName} ${currentUser.lastName}`,
        type: postType,
        timestamp: Date.now(),
        content: content,
        imageUrl: postType === PostType.IMAGE ? finalImageUrl : undefined,
        groupId: selectedGroup.id,
        groupName: selectedGroup.id ? selectedGroup.name : undefined,
        backgroundColor: selectedBg.class,
        textColor: selectedTextColor.class,
        fontFamily: selectedFont.class,
        // Garante que o objeto reel só é criado se for tipo REEL
        reel: postType === PostType.REEL ? { 
            videoUrl: finalReelUrl, 
            description: content,
            audioTrackId: reelMeta.audioTrackId,
            aiEffectPrompt: reelMeta.aiPrompt,
            filter: reelMeta.filter
        } : undefined,
        likes: [],
        comments: [],
        shares: [],
        saves: [],
        indicatedUserIds: []
      };

      if (isEditing) await updatePost(postData);
      else await addPost(postData);

      onPostCreated();
      if (!isEditing) resetForm();
      if (onCancel) onCancel();

    } catch (err: any) {
      console.error(err);
      alert('Erro ao salvar postagem: ' + (err.message || 'Verifique sua conexão.'));
    } finally {
      setLoading(false);
      setStatusText('Publicar');
    }
  };

  if (!isExpanded && !isEditing) {
    return (
      <div className="bg-white dark:bg-darkcard rounded-[2.5rem] p-6 border border-gray-100 dark:border-white/10 flex flex-col gap-4 shadow-sm animate-fade-in">
         <div className="flex items-center gap-4">
            <img src={currentUser.profilePicture} className="w-12 h-12 rounded-2xl object-cover shadow-sm" />
            <button onClick={() => setIsExpanded(true)} className="flex-1 text-left px-6 py-4 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 font-bold text-sm hover:bg-gray-100 dark:hover:bg-white/10 transition-all">
              No que você está pensando?
            </button>
         </div>
         <div className="flex gap-4 px-2 border-t border-gray-50 dark:border-white/5 pt-4">
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <PhotoIcon className="h-5 w-5 text-green-500" /> Foto
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.REEL); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <FilmIcon className="h-5 w-5 text-purple-500" /> Reel
            </button>
            <button onClick={() => { setIsExpanded(true); setPostType(PostType.TEXT); setShowStyleTools(true); }} className="flex-1 flex items-center justify-center gap-2 py-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 text-gray-500 text-[10px] font-black uppercase tracking-widest transition-all">
               <SwatchIcon className="h-5 w-5 text-blue-500" /> Cor
            </button>
         </div>
      </div>
    );
  }

  const isBgSelected = selectedBg.id !== 'transparent';

  return (
    <div className="bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl p-6 md:p-8 border dark:border-white/5 animate-fade-in relative overflow-visible">
      {/* Header do Modal */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
           <img src={currentUser.profilePicture} className="w-10 h-10 rounded-xl object-cover" />
           <div className="flex flex-col">
              <h3 className="font-black text-gray-900 dark:text-white text-sm">{currentUser.firstName} {currentUser.lastName}</h3>

              {/* Selector de Destino */}
              <div className="relative">
                 <button 
                   type="button"
                   onClick={() => setShowGroupSelector(!showGroupSelector)}
                   className="flex items-center gap-1.5 bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded-lg text-[9px] font-bold text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/20 transition-all"
                 >
                    {selectedGroup.id ? <UserGroupIcon className="h-3 w-3" /> : <GlobeAmericasIcon className="h-3 w-3" />}
                    <span className="max-w-[100px] truncate">{selectedGroup.name}</span>
                    <ChevronDownIcon className="h-3 w-3" />
                 </button>

                 {showGroupSelector && (
                   <div className="absolute top-full left-0 mt-2 w-56 bg-white dark:bg-[#1a1c23] border border-gray-100 dark:border-white/10 rounded-2xl shadow-2xl z-[150] p-2 animate-fade-in">
                      <button 
                       onClick={() => { setSelectedGroup({ name: 'Feed Geral' }); setShowGroupSelector(false); }}
                       className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                      >
                         <GlobeAmericasIcon className="h-4 w-4 text-gray-400" />
                         <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">Feed Geral</span>
                      </button>
                      {myGroups.map(group => (
                        <button 
                         key={group.id}
                         onClick={() => { setSelectedGroup({ id: group.id, name: group.groupName! }); setShowGroupSelector(false); }}
                         className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                        >
                           <UserGroupIcon className="h-4 w-4 text-blue-600" />
                           <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{group.groupName}</span>
                        </button>
                      ))}
                   </div>
                 )}
              </div>
           </div>
        </div>
        <button onClick={resetForm} className="p-2 bg-gray-100 dark:bg-white/10 rounded-full hover:bg-gray-200 dark:hover:bg-white/20 transition-all"><XMarkIcon className="h-5 w-5 text-gray-500" /></button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* TEXT AREA COM ESTILOS */}
        {postType === PostType.TEXT && (
          <div className={`relative transition-all duration-500 rounded-[2rem] overflow-hidden flex items-center justify-center ${isBgSelected ? `${selectedBg.class} min-h-[300px]` : 'bg-gray-50 dark:bg-white/5 min-h-[150px]'}`}>
             <textarea 
               value={content} 
               onChange={e => { setContent(e.target.value); }} 
               className={`w-full p-6 bg-transparent outline-none resize-none text-center placeholder:opacity-50 ${isBgSelected ? `${selectedTextColor.class} ${selectedFont.class} text-2xl md:text-3xl leading-tight py-20` : 'text-gray-900 dark:text-white text-lg font-medium'}`}
               placeholder={selectedGroup.id ? `Olá ${selectedGroup.name}...` : "No que você está pensando?"}
               style={{ height: '100%' }}
             />

             {isBgSelected && (
               <button 
                 type="button" 
                 onClick={() => { setSelectedBg(BG_OPTIONS[0]); setSelectedTextColor(TEXT_COLORS[0]); setShowStyleTools(false); }}
                 className="absolute top-4 right-4 bg-black/20 hover:bg-black/40 text-white p-2 rounded-full backdrop-blur-md transition-all"
               >
                 <XMarkIcon className="h-4 w-4" />
               </button>
             )}
          </div>
        )}

        {/* FERRAMENTAS DE ESTILO DE TEXTO */}
        {postType === PostType.TEXT && showStyleTools && (
           <div className="space-y-4 animate-slide-down bg-gray-50 dark:bg-white/5 p-4 rounded-3xl border border-gray-100 dark:border-white/5">
              <div className="flex gap-2 mb-2 border-b border-gray-200 dark:border-white/10 pb-2 overflow-x-auto no-scrollbar">
                 <button type="button" onClick={() => setActiveStyleTab('bg')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'bg' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fundo</button>
                 <button type="button" onClick={() => setActiveStyleTab('text')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'text' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Cor Texto</button>
                 <button type="button" onClick={() => setActiveStyleTab('font')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${activeStyleTab === 'font' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-200 dark:hover:bg-white/10'}`}>Fonte</button>
              </div>

              {activeStyleTab === 'bg' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {BG_OPTIONS.map(bg => (
                       <button
                         key={bg.id}
                         type="button"
                         onClick={() => setSelectedBg(bg)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all ${bg.id === 'transparent' ? 'bg-white border-dashed border-gray-400' : bg.class} ${selectedBg.id === bg.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-transparent'}`}
                         title={bg.label}
                       >
                         {bg.id === 'transparent' && <span className="text-[8px] font-black text-gray-400">NONE</span>}
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'text' && (
                <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar">
                    {TEXT_COLORS.map(color => (
                       <button
                         key={color.id}
                         type="button"
                         onClick={() => setSelectedTextColor(color)}
                         className={`w-10 h-10 rounded-full border-2 flex-shrink-0 transition-all flex items-center justify-center bg-gray-800 ${selectedTextColor.id === color.id ? 'border-blue-600 scale-110 shadow-lg' : 'border-gray-600'}`}
                         title={color.label}
                       >
                         <div className={`w-6 h-6 rounded-full ${color.class.replace('text-', 'bg-')}`}></div>
                       </button>
                    ))}
                </div>
              )}

              {activeStyleTab === 'font' && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar">
                    {FONT_OPTIONS.map(font => (
                       <button
                         key={font.id}
                         type="button"
                         onClick={() => setSelectedFont(font)}
                         className={`px-4 py-2 rounded-xl text-sm border transition-all whitespace-nowrap ${font.class} ${selectedFont.id === font.id ? 'bg-white dark:bg-white/10 border-blue-600 text-blue-600 shadow-md' : 'border-transparent text-gray-500 hover:bg-white/50'}`}
                       >
                          {font.label}
                       </button>
                    ))}
                </div>
              )}
           </div>
        )}

        {/* UPLOAD DE IMAGEM */}
        {postType === PostType.IMAGE && (
          <div className="relative">
             <div onClick={() => imageInputRef.current?.click()} className="w-full h-80 border-4 border-dashed rounded-[2rem] flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 transition-all overflow-hidden bg-gray-50 dark:bg-white/5 group">
               {imageUrl ? (
                 <>
                   <img src={imageUrl} className="w-full h-full object-cover" />
                   <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <span className="text-white font-black text-xs uppercase bg-black/50 px-4 py-2 rounded-xl backdrop-blur-md">Trocar Imagem</span>
                   </div>
                 </>
               ) : (
                 <>
                   <PhotoIcon className="h-12 w-12 text-gray-300 group-hover:text-blue-500 transition-colors" />
                   <p className="text-gray-400 font-black text-xs uppercase mt-2">Clique para carregar</p>
                 </>
               )}
               <input type="file" ref={imageInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
             </div>

             <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full mt-4 p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Adicione uma legenda..." 
               rows={2}
             />
          </div>
        )}

        {/* REELS AREA */}
        {postType === PostType.REEL && (
           <div className="space-y-4">
              {!reelUrl ? (
                 <div className="grid grid-cols-2 gap-4 h-64">
                    <button 
                      type="button"
                      onClick={() => setShowRecordModal(true)}
                      className="bg-gray-900 text-white rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-800 transition-all group border-2 border-gray-800 hover:border-blue-500"
                    >
                       <div className="p-4 bg-red-600 rounded-full group-hover:scale-110 transition-transform shadow-lg shadow-red-900/50">
                          <CameraIcon className="h-8 w-8 text-white" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Gravar Agora</span>
                    </button>

                    <button 
                      type="button"
                      onClick={() => videoInputRef.current?.click()}
                      className="bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-300 rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-100 dark:hover:bg-white/10 transition-all border-2 border-dashed border-gray-200 dark:border-white/10 hover:border-blue-500"
                    >
                       <div className="p-4 bg-white dark:bg-white/10 rounded-full group-hover:scale-110 transition-transform">
                          <VideoCameraIcon className="h-8 w-8 text-blue-500" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Upload Vídeo</span>
                       <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
                    </button>
                 </div>
              ) : (
                 <div className="relative rounded-[2rem] overflow-hidden bg-black aspect-[9/16] max-h-[500px] mx-auto w-full max-w-xs shadow-2xl">
                    <video src={reelUrl} controls className="w-full h-full object-cover" />
                    <button 
                      type="button" 
                      onClick={() => { setReelUrl(''); setReelFile(null); setReelMeta({}); }}
                      className="absolute top-4 right-4 bg-black/60 text-white p-2 rounded-full hover:bg-red-600 transition-colors backdrop-blur-md"
                    >
                       <XMarkIcon className="h-5 w-5" />
                    </button>
                 </div>
              )}

              <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Descreva seu Reel..." 
               rows={2}
             />
           </div>
        )}

        {/* BARRA DE FERRAMENTAS INFERIOR */}
        <div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-white/5">
           <div className="flex gap-2">
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.TEXT); setShowStyleTools(!showStyleTools); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.TEXT && showStyleTools ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Estilo de Texto"
              >
                 <FontIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.IMAGE ? 'bg-green-100 dark:bg-green-900/30 text-green-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Adicionar Foto"
              >
                 <PhotoIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => setPostType(PostType.REEL)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.REEL ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Reel"
              >
                 <FilmIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-yellow-500 transition-all hidden sm:block"
              >
                 <FaceSmileIcon className="h-6 w-6" />
              </button>
           </div>

           <button 
             type="submit" 
             disabled={loading || (!content && !imageFile && !reelFile)} 
             className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all flex items-center gap-2 min-w-[140px] justify-center"
           >
             {loading ? <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> {statusText}</> : <><PaperAirplaneIcon className="h-4 w-4 -rotate-45" /> Publicar</>}
           </button>
        </div>
      </form>

      {showRecordModal && (
        <RecordReelModal 
          onClose={() => setShowRecordModal(false)} 
          onSave={handleRecordedReel} 
        />
      )}
    </div>
  );
};

export default CreatePost;

import React, { useState, useEffect } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport,
  updatePostShares,
  deletePost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Optimistic UI states
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);
  const [localSaves, setLocalSaves] = useState<string[]>(post.saves || []);
  const [isSaved, setIsSaved] = useState(post.saves?.includes(currentUser.id) || false);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
    setLocalSaves(post.saves || []);
    setIsSaved(post.saves?.includes(currentUser.id) || false);
  }, [post.likes, post.saves, currentUser.id]);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevIsLiked);
    if (prevIsLiked) {
      setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostLikes(post.id, currentUser.id);
    } catch (error) {
      setIsLiked(prevIsLiked);
      setLocalLikes(prevLikes);
      console.error("Falha ao curtir post", error);
    }
  };

  const handleSave = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsSaved = isSaved;
    const prevSaves = [...localSaves];

    setIsSaved(!prevIsSaved);
    if (prevIsSaved) {
      setLocalSaves(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalSaves(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostSaves(post.id, currentUser.id);
    } catch (error) {
      setIsSaved(prevIsSaved);
      setLocalSaves(prevSaves);
    }
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE) onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else setShowDetailModal(true);
        }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group transform transition-all duration-300 hover:shadow-2xl hover:-translate-y-1 animate-fade-in"
      >
        <div className="p-5 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-4 md:gap-5">
            <div className="relative cursor-pointer" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1.5 -right-1.5 bg-brand rounded-xl p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-4 w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="flex flex-col">
                <div className="flex items-center gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-base md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-4 w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-4 w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1.5 text-[9px] font-black text-brand uppercase tracking-widest mt-0.5">
                     <UserGroupIcon className="h-3 w-3" /> {post.groupName}
                  </div>
                )}
              </div>
              <p className="text-[9px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-3 text-brand">⚡ Patrocinado</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all"
          >
            <EllipsisHorizontalIcon className="h-7 w-7" />
          </button>
        </div>

        <div className={`px-5 md:px-8 ${hasBg ? 'pb-8' : 'pb-5 md:pb-8'}`}>
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[2.5rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-8 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-6 left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3.5 w-3.5" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-8 flex flex-col items-center text-center">
                   <h3 className="text-2xl md:text-4xl font-black mb-8 tracking-tighter uppercase">{post.liveStream.title}</h3>
                   <button className="bg-brand text-white px-10 py-5 rounded-[2.2rem] font-black text-[11px] md:text-sm uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-4">
                      <PlayIcon className="h-6 w-6" /> Entrar Agora
                   </button>
                </div>
             </div>
          ) : post.type === PostType.REEL && post.reel ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-[9/16] max-h-[600px] flex items-center justify-center group">
                <video 
                  src={post.reel.videoUrl} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" 
                  muted 
                  loop 
                  playsInline
                  onMouseOver={(e) => e.currentTarget.play()}
                  onMouseOut={(e) => e.currentTarget.pause()}
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                   <div className="bg-white/20 backdrop-blur-md p-4 rounded-full border border-white/10 group-hover:scale-110 transition-transform">
                      <PlayIcon className="h-10 w-10 text-white fill-white" />
                   </div>
                </div>
                <div className="absolute bottom-0 left-0 w-full p-6 bg-gradient-to-t from-black/80 to-transparent pointer-events-none">
                   <p className="text-white text-sm font-medium line-clamp-2">{post.reel.description}</p>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`rounded-[2.5rem] md:rounded-[4rem] mb-2 transition-all duration-700 flex items-center justify-center text-center 
                    ${hasBg ? `${post.backgroundColor} ${post.textColor || 'text-white'}` : 'text-left w-full'} 
                    ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    minHeight: hasBg ? '400px' : 'auto', 
                    padding: hasBg ? '3rem' : '0.5rem',
                  }}
                >
                  <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-2xl text-2xl md:text-3xl' : 'text-base md:text-lg text-gray-900 dark:text-white'}`}>
                    {post.content}
                  </p>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl mt-4">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-6 md:px-12 py-5 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-2 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${isLiked ? 'text-brand bg-brand/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {isLiked ? <HeartIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <HeartIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{localLikes.length}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-3 px-5 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ChatIconOutline className="h-6 w-6 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-4 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-6 w-6 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-4 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${isSaved ? 'text-brand bg-brand/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {isSaved ? <BookmarkIconSolid className="h-6 w-6 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-6 w-6 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor} 
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)} 
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} 
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} 
          onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} 
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} 
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} 
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} 
          onReport={() => { 
            if(window.confirm("Deseja realmente denunciar esta publicação?")) {
              createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); 
              alert("Denúncia enviada com sucesso. Nossa equipe irá analisar.");
              setShowActionsModal(false); 
            }
          }} 
        />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)} 
          onConfirm={async () => { 
            await deletePost(post.id); 
            onPostUpdatedOrDeleted(); 
            setShowDeleteModal(false); 
          }} 
        />
      )}

      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

