// --- STORIES ---
export const getStories = async (): Promise<Story[]> => {
  const { data } = await supabase.from('stories').select('*');
  if (!data) return [];

  const now = Date.now();
  const storyLifetime = 24 * 60 * 60 * 1000; 

  const validStories = data.map((story: any) => {
    const activeItems = (story.items || []).filter((item: StoryItem) => {
      return (now - item.timestamp) < storyLifetime;
    });

    if (activeItems.length === 0) return null;

    return {
      userId: story.user_id,
      userName: story.user_name,
      userProfilePic: story.user_profile_pic,
      items: activeItems
    };
  }).filter(Boolean);

  return validStories as Story[];
};

export const addStory = async (userId: string, item: any) => {
    const { data: user } = await supabase.from('profiles').select('first_name, profile_picture').eq('id', userId).single();
    if (!user) throw new Error("Usuário não encontrado para criar story.");

    const { data: existing } = await supabase.from('stories').select('*').eq('user_id', userId).maybeSingle();

    const storyItem: StoryItem = { ...item, id: generateUUID(), timestamp: Date.now() };

    if (existing) {
        const items = [...(existing.items || []), storyItem];
        const { error } = await supabase.from('stories').update({ items }).eq('user_id', userId);
        if (error) throw error;
    } else {
        const { error } = await supabase.from('stories').insert({
            user_id: userId,
            user_name: user.first_name,
            user_profile_pic: user.profile_picture || DEFAULT_PROFILE_PIC,
            items: [storyItem]
        });
        if (error) throw error;
    }
};

