  localStorage.setItem(CART_KEY, JSON.stringify(cart));
};

export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existingItem = cart.find(item => item.productId === productId && item.selectedColor === selectedColor);
  if (existingItem) {
    existingItem.quantity += quantity;
  } else {
    cart.push({ productId, quantity, selectedColor });
  }
  saveCart(cart);
};

export const updateCartItemQuantity = (productId: string, quantity: number) => {
  let cart = getCart();
  if (quantity <= 0) {
    cart = cart.filter(item => item.productId !== productId);
  } else {
    const item = cart.find(item => item.productId === productId);
    if (item) {
      item.quantity = quantity;
    }
  }
  saveCart(cart);
};

export const removeFromCart = (productId: string) => {
  const cart = getCart().filter(item => item.productId !== productId);
  saveCart(cart);
};

export const clearCart = () => {
  saveCart([]);
};

export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
    for (const item of cartItems) {
        const product = await findProductById(item.productId);
        if (!product) continue;

        const store = await findStoreById(product.storeId);
        if (!store) continue;

        const total = product.price * item.quantity;
        let commission = 0;

        if (affiliateUserId) {
            commission = total * product.affiliateCommissionRate;
            await updateUserBalance(affiliateUserId, commission);
            await createNotification({ 
                type: NotificationType.AFFILIATE_SALE, 
                recipientId: affiliateUserId, 
                actorId: buyerId, 
                timestamp: Date.now(),
                saleId: 'pending' // Placeholder
            });
        }

        const sellerRevenue = total - commission;
        await updateUserBalance(store.professorId, sellerRevenue);

        await supabase.from('affiliate_sales').insert({
            id: generateUUID(),
            product_id: item.productId,
            buyer_id: buyerId,
            affiliate_user_id: affiliateUserId || null,
            store_id: product.storeId,
            commission_earned: commission,
            sale_amount: total,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            is_rated: false,
            shipping_address: shippingAddress,
            digital_content_url: product.digitalContentUrl,
            is_dropshipping: product.isDropshipping,
            supplier_cost: product.isDropshipping ? (product.originalPrice || 0) * item.quantity : 0
        });
    }
    clearCart();
    return true;
};

