// --- FILE UPLOAD ---
export const uploadFile = async (file: File | Blob, folder: string): Promise<string> => {
  let ext = 'jpg';
  if (file instanceof File) {
      const parts = file.name.split('.');
      if (parts.length > 1) ext = parts.pop() || 'jpg';
  } else if (file.type) {
      if (file.type.includes('video')) ext = 'webm';
      else if (file.type.includes('png')) ext = 'png';
  }

  const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
  const bucketName = 'cyberphone';

  // Tentativa inicial de upload
  let { error } = await supabase.storage.from(bucketName).upload(fileName, file);

  // Tratamento de erro "Bucket not found"
  if (error && (error.message.includes('Bucket not found') || error.message.includes('The resource was not found'))) {
      console.warn("Bucket não encontrado. Tentando criar bucket 'cyberphone'...");
      const { error: createError } = await supabase.storage.createBucket(bucketName, {
          public: true,
          fileSizeLimit: 52428800, // 50MB
          allowedMimeTypes: ['image/*', 'video/*']
      });

      if (!createError) {
          // Retry upload após criação
          const { error: retryError } = await supabase.storage.from(bucketName).upload(fileName, file);
          error = retryError;
      } else {
          console.error("Falha ao criar bucket:", createError);
          // Se não conseguir criar (permissão), tenta usar bucket 'public' se existir (fallback)
          // Em último caso, lançar erro instruindo o usuário
      }
  }

  if (error) {
      console.error("Erro no upload para Supabase:", error);
      throw new Error(`Falha no upload de arquivo: ${error.message}. Se o erro for 'Bucket not found', execute o SQL de configuração.`);
  }

  const { data: { publicUrl } } = supabase.storage.from(bucketName).getPublicUrl(fileName);
  return publicUrl;
};

