export const addPost = async (post: Post) => {
  console.log("Tentando inserir post para UserID:", post.userId);

  const { data: userCheck } = await supabase.from('profiles').select('id').eq('id', post.userId).single();
  if (!userCheck) {
      throw new Error("Erro de sessão: Usuário não encontrado no banco de dados. Faça login novamente.");
  }

  // Mapeamento para colunas snake_case
  const payload: any = {
    id: post.id,
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    group_id: post.groupId,
    group_name: post.groupName,
    timestamp: post.timestamp,
    likes: post.likes || [],
    comments: post.comments || [],
    shares: post.shares || [],
    saves: post.saves || [],
    is_pinned: post.isPinned || false,
    is_boosted: post.isBoosted || false,
    boost_expires: post.boostExpires,
    live_data: post.liveStream,
    reel_data: post.reel,
    background_color: post.backgroundColor,
    text_color: post.textColor,
    font_family: post.fontFamily,
    font_size: post.fontSize,
    indicated_user_ids: post.indicatedUserIds || []
  };

  const { error } = await supabase.from('posts').insert(payload);

  if (error) {
      console.error("FATAL: Erro ao adicionar post no Supabase:", error);
      // Tentativa de recuperação: Se o erro for de coluna 'comments' (schema desatualizado), tenta inserir sem ela
      if (error.message && (error.message.includes('comments') || error.message.includes('column'))) {
          console.warn("Schema desatualizado detectado. Tentando inserir sem coluna 'comments'...");
          const { comments, ...safePayload } = payload;
          const { error: retryError } = await supabase.from('posts').insert(safePayload);
          if (retryError) throw new Error("Erro ao salvar post (Retry falhou): " + retryError.message);
          return;
      }
      throw new Error("Erro ao salvar post: " + error.message);
  }
};

