export const getStories = async (): Promise<Story[]> => {
  const { data } = await supabase.from('stories').select('*');
  if (!data) return [];

  const now = Date.now();
  const storyLifetime = 24 * 60 * 60 * 1000; 

  const validStories = data.map((story: any) => {
    const activeItems = (story.items || []).filter((item: StoryItem) => {
      return (now - item.timestamp) < storyLifetime;
    });

    if (activeItems.length === 0) return null;

    return {
      userId: story.user_id,
      userName: story.user_name,
      userProfilePic: story.user_profile_pic,
      items: activeItems
    };
  }).filter(Boolean);

  return validStories as Story[];
};

export const addStory = async (userId: string, item: any) => {
    const { data: user, error: userError } = await supabase.from('profiles').select('first_name, profile_picture').eq('id', userId).single();

    if (userError || !user) {
        console.error("Erro ao buscar usuário para story:", userError);
        throw new Error("Usuário não encontrado para criar story.");
    }

    const { data: existing, error: fetchError } = await supabase.from('stories').select('*').eq('user_id', userId).maybeSingle();

    if (fetchError) {
        console.error("Erro ao verificar stories existentes:", fetchError);
        throw new Error("Erro de conexão ao acessar stories.");
    }

    const storyItem: StoryItem = { ...item, id: generateUUID(), timestamp: Date.now() };

    if (existing) {
        // Garante que items seja um array, mesmo que o banco retorne null ou algo estranho
        const currentItems = Array.isArray(existing.items) ? existing.items : [];
        const items = [...currentItems, storyItem];

        const { error } = await supabase.from('stories').update({ 
            items,
            updated_at: new Date().toISOString() // Atualiza timestamp para ordenação se necessário
        }).eq('user_id', userId);

        if (error) {
            console.error("Erro ao atualizar story:", error);
            throw new Error("Falha ao salvar story no banco de dados.");
        }
    } else {
        const { error } = await supabase.from('stories').insert({
            user_id: userId,
            user_name: user.first_name || 'Usuário',
            user_profile_pic: user.profile_picture || DEFAULT_PROFILE_PIC,
            items: [storyItem]
        });

        if (error) {
            console.error("Erro ao criar novo registro de story:", error);
            throw new Error("Falha ao criar primeiro story.");
        }
    }
};

