export const getUsers = (): User[] => {
  return JSON.parse(localStorage.getItem(USERS_KEY) || '[]');
};
export const saveUsers = (users: User[]) => localStorage.setItem(USERS_KEY, JSON.stringify(users));

export const findUserById = (userId: string): User | undefined => getUsers().find(u => u.id === userId);

export const loginUser = async (email: string, password: string): Promise<User> => {
  const user = getUsers().find(u => u.email === email);
  if (user) return user;
  throw new Error('Credenciais inválidas.');
};

export const registerUser = async (userData: any): Promise<User> => {
  const users = getUsers();
  if (users.some(u => u.email === userData.email)) throw new Error('Email já cadastrado.');
  const newUser: User = {
    id: `user-${Date.now()}`,
    userType: userData.userType,
    firstName: userData.firstName,
    lastName: userData.lastName,
    email: userData.email,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate || Date.now(),
    followedUsers: [],
    followers: [],
    balance: 0,
    profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
    credentials: userData.credentials,
    bio: userData.bio,
    verificationFileUrl: userData.verificationFileUrl
  };
  if (newUser.userType === UserType.CREATOR) {
    const stores = getStores();
    const storeId = `store-${Date.now()}`;
    newUser.storeId = storeId;
    saveStores([...stores, { id: storeId, professorId: newUser.id, name: `Loja de ${newUser.firstName}`, description: 'Bem-vindo!', productIds: [] }]);
  }
  saveUsers([...users, newUser]);
  return newUser;
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(CURRENT_USER_KEY, userId);
  else localStorage.removeItem(CURRENT_USER_KEY);
};
export const getCurrentUserId = (): string | null => localStorage.getItem(CURRENT_USER_KEY);

export const updateUser = async (updatedUser: User) => {
  const users = getUsers().map(u => u.id === updatedUser.id ? updatedUser : u);
  saveUsers(users);
};

export const deleteUser = async (userId: string) => {
  const users = getUsers().filter(u => u.id !== userId);
  saveUsers(users);
};

export const updateUserPassword = async (password: string) => { return true; }; // Mock

export const toggleFollowUser = (currentUserId: string, userIdToFollow: string) => {
  let users = getUsers();
  const current = users.find(u => u.id === currentUserId);
  const target = users.find(u => u.id === userIdToFollow);
  if (current && target) {
    if (current.followedUsers.includes(userIdToFollow)) {
      current.followedUsers = current.followedUsers.filter(id => id !== userIdToFollow);
      target.followers = target.followers.filter(id => id !== currentUserId);
    } else {
      current.followedUsers.push(userIdToFollow);
      target.followers.push(currentUserId);
      createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: userIdToFollow, actorId: currentUserId, timestamp: Date.now() });
    }
    saveUsers(users);
  }
};

export const updateUserBalance = (userId: string, amount: number) => {
  let users = getUsers();
  const user = users.find(u => u.id === userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    saveUsers(users);
    // Log transaction
    const tx: Transaction = {
        id: generateUUID(),
        userId,
        type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
        amount: Math.abs(amount),
        description: amount > 0 ? 'Depósito/Venda' : 'Saque/Compra',
        timestamp: Date.now(),
        status: 'COMPLETED'
    };
    const txs = getTransactions();
    localStorage.setItem(TRANSACTIONS_KEY, JSON.stringify([tx, ...txs]));
    return true;
  }
  return false;
};

// Posts
export const getPosts = (): Post[] => JSON.parse(localStorage.getItem(POSTS_KEY) || '[]');
export const savePosts = (posts: Post[]) => localStorage.setItem(POSTS_KEY, JSON.stringify(posts));

export const addPost = async (post: Post) => {
  const posts = getPosts();
  savePosts([post, ...posts]);
  if(post.groupId) {
      // Notify group members?
      const chat = getChats().find(c => c.id === post.groupId);
      if(chat) {
          chat.participants.forEach(pId => {
              if(pId !== post.userId) {
                  createNotification({ type: NotificationType.GROUP_POST, recipientId: pId, actorId: post.userId, groupName: chat.groupName, timestamp: Date.now(), postId: post.id });
              }
          });
      }
  } else {
      // Notify followers
      const user = findUserById(post.userId);
      if(user) {
          user.followers.forEach(fId => {
              createNotification({ type: NotificationType.NEW_POST, recipientId: fId, actorId: post.userId, postId: post.id, timestamp: Date.now() });
          });
      }
  }
};

export const updatePost = async (post: Post) => {
  const posts = getPosts().map(p => p.id === post.id ? post : p);
  savePosts(posts);
};

export const deletePost = (postId: string) => {
