        if(pId !== msg.senderId) {
            createNotification({ type: NotificationType.MESSAGE, recipientId: pId, actorId: msg.senderId, groupName: chat.type === ChatType.GROUP ? chat.groupName : undefined, timestamp: Date.now() });
        }
    });
  }
