// Sales
export const getAffiliateSales = (): AffiliateSale[] => JSON.parse(localStorage.getItem(AFFILIATE_SALES_KEY) || '[]');
export const saveAffiliateSales = (sales: AffiliateSale[]) => localStorage.setItem(AFFILIATE_SALES_KEY, JSON.stringify(sales));
export const getSalesByAffiliateId = (id: string) => getAffiliateSales().filter(s => s.affiliateUserId === id);
export const getSalesByStoreId = (id: string) => getAffiliateSales().filter(s => s.storeId === id);
export const getPurchasesByBuyerId = (id: string) => getAffiliateSales().filter(s => s.buyerId === id);

export const processProductPurchase = async (items: CartItem[], buyerId: string, affiliateId: string | null, address?: ShippingAddress) => {
    const products = getProducts();
    const sales = getAffiliateSales();
    let total = 0;

    for(const item of items) {
        const prod = products.find(p => p.id === item.productId);
        if(!prod) continue;
        const amount = prod.price * item.quantity;
        total += amount;

        let commission = 0;
        if(affiliateId && affiliateId !== prod.storeId) {
            commission = amount * prod.affiliateCommissionRate;
            updateUserBalance(affiliateId, commission);
            createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateId, actorId: buyerId, timestamp: Date.now() });
        }

        const store = findStoreById(prod.storeId);
        if(store) {
            updateUserBalance(store.professorId, amount - commission); // Store owner gets rest
        }

        sales.push({
            id: generateUUID(),
            productId: prod.id,
            buyerId,
            affiliateUserId: affiliateId || '',
            storeId: prod.storeId,
            commissionEarned: commission,
            saleAmount: amount,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            isRated: false,
            shippingAddress: address,
            digitalContentUrl: prod.digitalContentUrl,
            isDropshipping: prod.isDropshipping,
            supplierCost: prod.originalPrice // Estimativa
        });
    }
    saveAffiliateSales(sales);
    saveCart([]);
    return true;
};

export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    if(updateUserBalance(userId, -cost)) {
        updateSaleStatus(saleId, OrderStatus.PROCESSING_SUPPLIER);
        return true;
    }
    return false;
};

export const updateSaleStatus = async (saleId: string, status: OrderStatus) => {
    const sales = getAffiliateSales();
    const sale = sales.find(s => s.id === saleId);
    if(sale) {
        sale.status = status;
        saveAffiliateSales(sales);
    }
};

export const updateSaleTracking = async (saleId: string, code: string, supplierId?: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(s => s.id === saleId);
    if(sale) {
        sale.trackingCode = code;
        sale.supplierOrderId = supplierId;
        saveAffiliateSales(sales);
    }
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const sales = getAffiliateSales();
    const sale = sales.find(s => s.id === saleId);
    if(sale && !sale.isRated) {
        sale.isRated = true;
        saveAffiliateSales(sales);
        const products = getProducts();
        const product = products.find(p => p.id === sale.productId);
        if(product) {
            product.ratings.push({ id: generateUUID(), saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() });
            product.ratingCount = product.ratings.length;
            product.averageRating = product.ratings.reduce((acc, r) => acc + r.rating, 0) / product.ratingCount;
            saveProducts(products);
        }
    }
};

// Cart
export const getCart = (): CartItem[] => JSON.parse(localStorage.getItem(CART_KEY) || '[]');
export const saveCart = (cart: CartItem[]) => localStorage.setItem(CART_KEY, JSON.stringify(cart));
export const addToCart = (productId: string, quantity: number, selectedColor?: string) => {
    const cart = getCart();
    const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
    if(existing) existing.quantity += quantity;
    else cart.push({ productId, quantity, selectedColor });
    saveCart(cart);
};
export const updateCartItemQuantity = (pId: string, q: number) => {
    let cart = getCart();
    if(q <= 0) cart = cart.filter(i => i.productId !== pId);
    else {
        const item = cart.find(i => i.productId === pId);
        if(item) item.quantity = q;
    }
    saveCart(cart);
};
export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));

// Ads
export const getAds = (): AdCampaign[] => JSON.parse(localStorage.getItem(ADS_KEY) || '[]');
export const saveAds = (ads: AdCampaign[]) => localStorage.setItem(ADS_KEY, JSON.stringify(ads));

// Notifications
export const getNotifications = (): Notification[] => JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || '[]');
export const createNotification = (n: any) => {
    const list = getNotifications();
    list.unshift({ ...n, id: generateUUID(), isRead: false });
    localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(list));
};
export const getNotificationsForUser = (userId: string) => getNotifications().filter(n => n.recipientId === userId);
export const markNotificationsAsRead = (userId: string) => {
    const list = getNotifications();
    list.forEach(n => { if(n.recipientId === userId) n.isRead = true; });
    localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(list));
};

// Misc
export const getEvents = (): CyberEvent[] => JSON.parse(localStorage.getItem(EVENTS_KEY) || '[]');
export const createEvent = async (evt: CyberEvent) => {
    const evts = getEvents();
    evts.push(evt);
    localStorage.setItem(EVENTS_KEY, JSON.stringify(evts));
};
export const toggleJoinEvent = async (eId: string, uId: string) => {
    const evts = getEvents();
    const e = evts.find(ev => ev.id === eId);
    if(e) {
        if(e.attendees.includes(uId)) e.attendees = e.attendees.filter(id => id !== uId);
        else e.attendees.push(uId);
        localStorage.setItem(EVENTS_KEY, JSON.stringify(evts));
    }
};

export const getStories = (): Story[] => JSON.parse(localStorage.getItem(STORIES_KEY) || '[]');
export const addStory = async (uId: string, item: any) => {
    const stories = getStories();
    let story = stories.find(s => s.userId === uId);
    if(!story) {
        const user = findUserById(uId);
        story = { userId: uId, userName: user?.firstName || 'User', userProfilePic: user?.profilePicture || '', items: [] };
        stories.push(story);
    }
    story.items.push({ ...item, id: generateUUID(), timestamp: Date.now() });
    localStorage.setItem(STORIES_KEY, JSON.stringify(stories));
};

export const getAudioTracks = async (): Promise<AudioTrack[]> => JSON.parse(localStorage.getItem(AUDIO_TRACKS_KEY) || '[]');
export const findAudioTrackById = async (id: string) => (await getAudioTracks()).find(t => t.id === id);

export const uploadFile = async (file: File, folder: string): Promise<string> => {
    return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result as string);
        reader.readAsDataURL(file);
    });
};

export const saveAffiliateLink = async (uId: string, pId: string, link: string) => {
    const links = await getAffiliateLinks(uId); // Actually this gets enriched ones, we need raw
    const rawLinks = JSON.parse(localStorage.getItem(LINKS_KEY) || '[]');
    rawLinks.push({ id: generateUUID(), uId, pId, link, timestamp: Date.now() });
    localStorage.setItem(LINKS_KEY, JSON.stringify(rawLinks));
};

export const getAffiliateLinks = async (userId: string) => {
    const rawLinks = JSON.parse(localStorage.getItem(LINKS_KEY) || '[]');
    const products = getProducts();
    return rawLinks.filter((l: any) => l.uId === userId).map((l: any) => {
        const p = products.find(prod => prod.id === l.pId);
        return {
            id: l.id,
            link: l.link,
            productName: p?.name || 'Unknown',
            productImage: p?.imageUrls[0] || '',
            commissionRate: p?.affiliateCommissionRate || 0,
            timestamp: l.timestamp
        };
    });
};

