interface ProfilePageProps {
  currentUser: User;
  onNavigate: (page: string, params?: any) => void;
  refreshUser: () => void;
  userId?: string;
  onOpenWallet: (mode: 'deposit' | 'withdraw') => void;
}

const ProfilePage: React.FC<ProfilePageProps> = ({ currentUser, onNavigate, refreshUser, userId, onOpenWallet }) => {
  const profileId = userId || currentUser.id;
  const [profile, setProfile] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'posts' | 'about' | 'store' | 'ads'>('posts');
  const [userPosts, setUserPosts] = useState<Post[]>([]);
  const [userAds, setUserAds] = useState<AdCampaign[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      const u = await findUserById(profileId);
      if (u) {
        setProfile(u);
      }

      const allPosts = await getPosts();
      setUserPosts(allPosts.filter(p => p.userId === profileId).sort((a, b) => b.timestamp - a.timestamp));

      const allAds = await getAds();
      setUserAds(allAds.filter(a => a.professorId === profileId));
    };
    fetchData();
  }, [profileId, currentUser.balance, currentUser.followedUsers]);

  if (!profile) return <div className="pt-32 text-center font-black uppercase text-gray-400">Usuário não encontrado</div>;

