import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Post, User, UserType, Comment } from '../types';
import { findUserById, addPostComment, updatePostLikes, updatePostSaves, updatePostShares, toggleFollowUser, generateUUID, getPosts } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  XMarkIcon, 
  ChatBubbleOvalLeftIcon,
  HeartIcon as HeartIconOutline,
  BookmarkIcon as BookmarkIconOutline,
  ShareIcon,
  EllipsisHorizontalIcon,
  ArrowLeftIcon,
  PaperAirplaneIcon,
  ArrowDownTrayIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  CheckBadgeIcon
} from '@heroicons/react/24/solid';

interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const [author, setAuthor] = useState<User | null>(null);
  const [comments, setComments] = useState<Comment[]>(post.comments || []);
  const [loadingComments, setLoadingComments] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const commentsEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const user = await findUserById(post.userId);
      setAuthor(user || null);
    };
    fetchAuthor();
  }, [post.userId]);

  // Função para buscar comentários atualizados
  const fetchComments = async () => {
    // setLoadingComments(true); // Opcional: evitar flicker
    const allPosts = await getPosts();
    const currentPost = allPosts.find(p => p.id === post.id);
    if (currentPost) {
      setComments(currentPost.comments || []);
    }
    setLoadingComments(false);
  };

  useEffect(() => {
    fetchComments();
  }, [post.id]);

  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!post.imageUrl) return;

    try {
      const response = await fetch(post.imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cyberphone-midia-${post.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      window.open(post.imageUrl, '_blank');
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Publicação de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {}
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleSendComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    const newComment: Comment = {
      id: generateUUID(),
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    };

    // Aguarda a persistência no banco
    await addPostComment(post.id, newComment);

    setCommentText('');

    // Atualiza a lista localmente e notifica o pai
    await fetchComments();
    onUpdate();

    setTimeout(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTo({
          top: scrollRef.current.scrollHeight,
          behavior: 'smooth'
        });
      }
    }, 100);
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/90 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-md">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[3rem] bg-white dark:bg-[#0a0c10] flex flex-col md:flex-row overflow-hidden relative shadow-2xl">

        {/* Mobile Header */}
        <div className="flex items-center justify-between px-4 md:hidden z-[101] bg-black/40 backdrop-blur-xl border-b border-white/10 h-16 shrink-0">
           <button onClick={onClose} className="p-2 text-white">
             <ArrowLeftIcon className="h-6 w-6" />
           </button>
           <span className="font-black text-[10px] uppercase text-white tracking-[0.3em]">Detalhes</span>
           <div className="w-10"></div>
        </div>

        {/* Desktop Close Button */}
        <button 
          onClick={onClose} 
          className="hidden md:flex absolute top-6 left-6 z-[101] p-4 bg-black/50 hover:bg-black/80 text-white rounded-full transition-all backdrop-blur-lg shadow-2xl border border-white/10 active:scale-90"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        {/* Image Container */}
        <div className={`w-full md:flex-1 bg-black flex items-center justify-center relative overflow-hidden shrink-0 ${!post.imageUrl ? 'hidden md:flex' : 'h-[50vh] md:h-full'}`}>
          {post.imageUrl && (
            <img 
              src={post.imageUrl} 
              className="w-full h-full object-contain" 
              alt="Mídia"
            />
          )}

          <div className="absolute bottom-6 right-6 flex flex-col gap-4 md:hidden">
             <button onClick={handleDownload} className="p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl bg-black/40 text-white active:scale-90 transition-all">
                <ArrowDownTrayIcon className="h-6 w-6" />
             </button>
             <button onClick={handleLike} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasLiked ? 'bg-blue-600 text-white' : 'bg-black/40 text-white'}`}>
                {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
             </button>
             <button onClick={handleSave} className={`p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl transition-all ${hasSaved ? 'bg-yellow-500 text-white' : 'bg-black/40 text-white'}`}>
                {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
             </button>
          </div>
        </div>

        {/* Content & Comments Sidebar */}
        <div className="flex-1 md:w-[480px] flex flex-col h-full bg-white dark:bg-[#0a0c10] border-l border-gray-100 dark:border-white/10 relative overflow-hidden">

          <div className="p-6 border-b border-gray-50 dark:border-white/10 flex items-center justify-between shrink-0 hidden md:flex bg-gray-50/50 dark:bg-white/[0.02]">
             <div className="flex items-center gap-4 cursor-pointer group" onClick={() => { onClose(); onNavigate('profile', { userId: post.userId }); }}>
                <div className="relative">
                   <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-[1.2rem] object-cover border-2 border-white dark:border-white/10 shadow-lg" />
                   {author.userType === UserType.CREATOR && <div className="absolute -bottom-1 -right-1 bg-blue-600 p-0.5 rounded-lg border border-white dark:border-[#0a0c10]"><CheckBadgeIcon className="h-3 w-3 text-white" /></div>}
                </div>
                <div>
                   <h4 className="font-black text-sm dark:text-white group-hover:text-blue-600 transition-colors uppercase tracking-tight">{author.firstName} {author.lastName}</h4>
                   <p className="text-gray-400 text-[9px] font-black uppercase tracking-widest mt-0.5">{author.userType === UserType.CREATOR ? 'Profissional Verificado' : 'Membro da Comunidade'}</p>
                </div>
             </div>
             {!isOwner && (
               <button 
                 onClick={handleFollow}
                 className={`px-6 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all active:scale-95 ${isFollowing ? 'bg-gray-100 dark:bg-white/5 text-gray-500' : 'bg-blue-600 text-white shadow-xl shadow-blue-500/20'}`}
               >
                 {isFollowing ? 'Seguindo' : 'Seguir'}
               </button>
             )}
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto custom-scrollbar p-6 space-y-8">
             {!post.imageUrl && (
                <div className="md:hidden flex items-center justify-between mb-4 border-b border-gray-100 dark:border-white/5 pb-4">
                  <div className="flex items-center gap-4">
                     <img src={author.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover" />
                     <div className="flex flex-col">
                        <span className="font-black text-sm dark:text-white uppercase tracking-tight">{author.firstName} {author.lastName}</span>
                        <span className="text-gray-400 text-[9px] font-black uppercase tracking-widest">{author.userType === UserType.CREATOR ? 'Profissional' : 'Membro'}</span>
                     </div>
                  </div>
               </div>
             )}

             <div 
               className={`p-8 md:p-12 rounded-[2.5rem] shadow-inner flex flex-col items-center justify-center text-center animate-fade-in 
                 ${post.fontFamily || 'font-sans'}
                 ${hasBg ? `${post.backgroundColor} ${post.textColor || 'text-white'}` : 'text-left w-full text-gray-900 dark:text-white'}
               `}
               style={{ 
                 fontSize: post.fontSize ? `calc(${post.fontSize} * 1.2)` : '1.1rem',
                 minHeight: hasBg ? '350px' : 'auto',
                 border: hasBg ? 'none' : '1px solid rgba(0,0,0,0.03)',
               }}
             >
                <p className={`font-black leading-snug whitespace-pre-wrap ${hasBg ? 'max-w-md text-2xl md:text-3xl' : 'text-left w-full'}`}>{post.content}</p>
                <div className={`text-[8px] font-black uppercase tracking-[0.2em] pt-8 mt-4 border-t w-full opacity-30 ${hasBg ? 'border-white/20' : 'border-gray-100'}`}>
                   Publicado em {new Date(post.timestamp).toLocaleDateString()}
                </div>
             </div>

             <div className="hidden md:flex items-center justify-between py-6 border-b border-gray-50 dark:border-white/5 text-gray-400">
                <div className="flex items-center gap-4">
                   <button onClick={handleLike} className={`flex items-center gap-2 group transition-all active:scale-75 ${hasLiked ? 'text-blue-600' : 'hover:text-blue-600'}`}>
                      <div className={`p-3 rounded-2xl transition-colors ${hasLiked ? 'bg-blue-50 dark:bg-blue-600/10' : 'group-hover:bg-gray-50'}`}>
                       {hasLiked ? <HeartIconSolid className="h-6 w-6" /> : <HeartIconOutline className="h-6 w-6" />}
                      </div>
                      <span className="text-xs font-black">{post.likes?.length || 0}</span>
                   </button>
                   <div className="flex items-center gap-2 group text-gray-400">
                      <div className="p-3 rounded-2xl bg-gray-50 dark:bg-white/5">
                       <ChatBubbleOvalLeftIcon className="h-6 w-6" />
                      </div>
                      <span className="text-xs font-black">{comments.length}</span>
                   </div>
                </div>
                <div className="flex items-center gap-2">
                   <button onClick={handleDownload} className="p-3 rounded-2xl hover:bg-gray-50 text-gray-400 transition-all active:scale-90" title="Baixar Mídia">
                      <ArrowDownTrayIcon className="h-6 w-6" />
                   </button>
                   <button onClick={handleSave} className={`p-3 rounded-2xl transition-all active:scale-90 ${hasSaved ? 'text-yellow-500 bg-yellow-50 dark:bg-yellow-500/10' : 'hover:bg-gray-50 text-gray-300'}`}>
                      {hasSaved ? <BookmarkIconSolid className="h-6 w-6" /> : <BookmarkIconOutline className="h-6 w-6" />}
                   </button>
                   <button onClick={handleShare} className="p-3 rounded-2xl hover:bg-gray-50 text-gray-300 transition-all active:scale-90">
                      <ShareIcon className="h-6 w-6" />
                   </button>
                </div>
             </div>

             <div className="space-y-6 pt-4 pb-10">
                <div className="flex items-center justify-between mb-4">
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Comentários</p>
                </div>

                {comments.length === 0 ? (
                  <div className="py-12 text-center opacity-20">
                     <ChatBubbleOvalLeftIcon className="h-10 w-10 mx-auto mb-2" />
                     <p className="text-[10px] font-black uppercase tracking-widest">Seja o primeiro a comentar</p>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {comments.map((c) => (
                      <div key={c.id} className="flex gap-4 animate-fade-in group">
                         <img src={c.profilePic || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover shrink-0 border-2 border-white dark:border-white/5 shadow-sm" />
                         <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                               <span className="font-black text-[11px] dark:text-white uppercase tracking-tighter truncate">{c.userName}</span>
                               <span className="text-gray-400 text-[8px] font-black uppercase">· {new Date(c.timestamp).getHours()}h</span>
                            </div>
                            <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-white/10 shadow-sm">
                               <p className="text-sm dark:text-gray-200 font-medium leading-relaxed">{c.text}</p>
                            </div>
                         </div>
                      </div>
                    ))}
                    <div ref={commentsEndRef} />
                  </div>
                )}
             </div>
          </div>

          <div className="p-6 bg-white dark:bg-[#0a0c10] border-t border-gray-100 dark:border-white/10 z-[105] shadow-[0_-10px_30px_rgba(0,0,0,0.05)] shrink-0">
             <form onSubmit={handleSendComment} className="max-w-4xl mx-auto flex items-end gap-3 bg-gray-50 dark:bg-white/5 p-3 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-inner group focus-within:border-blue-500/50 transition-all">
                <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-xl object-cover hidden sm:block border-2 border-white shadow-sm" />
                <div className="flex-1 flex items-center gap-3">
                   <textarea 
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                    placeholder="Adicionar um comentário..."
                    className="w-full bg-transparent dark:text-white outline-none resize-none text-sm placeholder-gray-400 py-3 font-bold custom-scrollbar max-h-24"
                    rows={1}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${target.scrollHeight}px`;
                    }}
                   />
                   <button 
                     type="submit" 
                     disabled={!commentText.trim()}
                     className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 text-white p-3.5 rounded-2xl shadow-xl shadow-blue-500/20 active:scale-90 transition-all shrink-0"
                   >
                     <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                   </button>
                </div>
             </form>
             <div className="h-2 md:hidden"></div>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

