                            <p className={`text-xs font-black uppercase ${docFile ? 'text-green-600' : 'text-gray-500'}`}>
                                {docFile ? docFile.name : 'Upload Habilitação (PDF)'}
                            </p>
                            <p className="text-[9px] text-gray-400 font-bold mt-1">Comprovante Profissional</p>
                        </div>
