export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) throw new Error(error.message);
  if (!data.user) throw new Error("Usuário não encontrado.");

  const user = await findUserById(data.user.id);
  if (!user) throw new Error("Perfil de usuário não encontrado.");
  return user;
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Criar Auth User
  const { data: authData, error: authError } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
  });

  if (authError) throw new Error(authError.message);
  if (!authData.user) throw new Error("Erro ao criar conta.");

  const userId = authData.user.id;

  // 2. Criar Store se for Creator
  let storeId = null;
  if (userData.userType === UserType.CREATOR) {
    const { data: storeData, error: storeError } = await supabase.from('stores').insert({
      professor_id: userId,
      name: `Loja de ${userData.firstName}`,
      description: 'Bem-vindo à minha loja!',
      product_ids: []
    }).selectSingle();

    if (!storeError && storeData) storeId = storeData.id;
  }

  // 3. Criar Profile
  const profilePayload = {
    id: userId,
    email: userData.email,
    first_name: userData.firstName,
    last_name: userData.lastName,
    user_type: userData.userType,
    phone: userData.phone,
    document_id: userData.documentId,
    birth_date: userData.birthDate,
    profile_picture: userData.profilePicture,
    credentials: userData.credentials,
    bio: userData.bio,
    verification_file_url: userData.verificationFileUrl,
    store_id: storeId
  };

  const { error: profileError } = await supabase.from('profiles').insert(profilePayload);

  if (profileError) {
    // Rollback manual (opcional, deletar auth user)
    console.error("Erro ao criar perfil:", profileError);
    throw new Error("Erro ao salvar dados do perfil.");
  }

  return mapUser(profilePayload);
};

