export const boostPost = async (pId: string, uId: string, budget: number, days: number) => {
  const balanceUpdated = await updateUserBalance(uId, -budget);
  if (balanceUpdated) {
    await supabase.from('posts').update({
        is_boosted: true,
        boost_expires: Date.now() + (days * 86400000)
    }).eq('id', pId);
    return true;
  }
  return false;
};

export const indicatePostToUser = async (pId: string, from: string, to: string) => {
  const { data } = await supabase.from('posts').select('indicated_user_ids').eq('id', pId).single();
  if (!data) return false;

  const indicated = data.indicated_user_ids || [];
  if (indicated.includes(to)) return false;

  indicated.push(to);
  await supabase.from('posts').update({ indicated_user_ids: indicated }).eq('id', pId);
  await createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: pId, timestamp: Date.now() });
  return true;
};

