export const getCart = (): CartItem[] => JSON.parse(localStorage.getItem('cyberphone_cart') || '[]');
export const saveCart = (cart: CartItem[]) => localStorage.setItem('cyberphone_cart', JSON.stringify(cart));
export const addToCart = (productId: string, quantity: number, selectedColor?: string) => {
    const cart = getCart();
    const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
    if(existing) existing.quantity += quantity;
    else cart.push({ productId, quantity, selectedColor });
    saveCart(cart);
};
export const updateCartItemQuantity = (pId: string, q: number) => {
    let cart = getCart();
    if(q <= 0) cart = cart.filter(i => i.productId !== pId);
    else {
        const item = cart.find(i => i.productId === pId);
        if(item) item.quantity = q;
    }
    saveCart(cart);
};
export const removeFromCart = (pId: string) => saveCart(getCart().filter(i => i.productId !== pId));

