export const generateUUID = () => crypto.randomUUID();

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- AUTH & USERS ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });

  if (error) {
    if (error.message.includes("Email not confirmed")) {
      throw new Error("Email não confirmado. Por favor, verifique sua caixa de entrada e spam.");
    }
    if (error.message.includes("security purposes")) {
      throw new Error("Muitas tentativas de login. Aguarde 60 segundos.");
    }
    if (error.message.includes("Invalid login credentials")) {
      throw new Error("Email ou senha incorretos.");
    }
    throw new Error(error.message);
  }

  if (!data.user) throw new Error("Usuário não encontrado.");

  const user = await findUserById(data.user.id);
  if (!user) {
    // Caso de borda: Usuário autenticou mas não tem perfil (ex: erro no cadastro anterior)
    // Poderíamos tentar recriar o perfil aqui, mas por segurança lançamos erro.
    throw new Error("Perfil de usuário incompleto. Contate o suporte.");
  }
  return user;
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Criar Auth User
  const { data: authData, error: authError } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
    options: {
      data: {
        first_name: userData.firstName,
        last_name: userData.lastName,
      }
    }
  });

  if (authError) {
    if (authError.message.includes("security purposes")) {
      throw new Error("Muitas tentativas. Aguarde 60 segundos antes de tentar novamente.");
    }
    throw new Error(authError.message);
  }

  if (!authData.user) throw new Error("Erro ao iniciar criação de conta.");

  // VERIFICAÇÃO DE E-MAIL
  // Se a sessão for nula, o Supabase exige confirmação de email.
  // Não podemos inserir no 'profiles' se as políticas RLS exigirem autenticação e não tivermos sessão.
  if (authData.user && !authData.session) {
    // Tentamos inserir o perfil mesmo assim (caso o RLS permita inserts públicos para configurar o perfil inicial)
    // Se falhar, avisamos o usuário para confirmar o email.

    const userId = authData.user.id;
    const profilePayload = {
        id: userId,
        email: userData.email,
        first_name: userData.firstName,
        last_name: userData.lastName,
        user_type: userData.userType,
        phone: userData.phone,
        document_id: userData.documentId,
        birth_date: userData.birthDate,
        profile_picture: userData.profilePicture,
        credentials: userData.credentials,
        bio: userData.bio,
        verification_file_url: userData.verificationFileUrl,
        store_id: null
    };

    const { error: profileError } = await supabase.from('profiles').insert(profilePayload);

    if (profileError) {
        console.warn("Perfil pendente de criação (RLS ou Erro):", profileError);
        // Não lançamos erro fatal do banco, mas sim uma instrução ao usuário
        // O perfil será criado/acessado após o login confirmado se o backend tiver trigger, 
        // ou o usuário terá que contatar suporte se o RLS for estrito.
        // No nosso caso, assumimos que o fluxo de confirmação é prioritário.
        throw new Error("Cadastro iniciado! Verifique seu e-mail para confirmar a conta antes de entrar.");
    }

    // Se o perfil foi criado mas não temos sessão, também pedimos confirmação
    throw new Error("Cadastro realizado com sucesso! Verifique seu e-mail para ativar a conta.");
  }

  const userId = authData.user.id;

  // 2. Criar Store se for Creator (Apenas se tivermos sessão ativa)
  let storeId = null;
  if (userData.userType === UserType.CREATOR) {
    const { data: storeData, error: storeError } = await supabase.from('stores').insert({
      professor_id: userId,
      name: `Loja de ${userData.firstName}`,
      description: 'Bem-vindo à minha loja!',
      product_ids: []
    }).selectSingle();

    if (!storeError && storeData) storeId = storeData.id;
  }

  // 3. Criar Profile (Com Sessão Ativa)
  const profilePayload = {
    id: userId,
    email: userData.email,
    first_name: userData.firstName,
    last_name: userData.lastName,
    user_type: userData.userType,
    phone: userData.phone,
    document_id: userData.documentId,
    birth_date: userData.birthDate,
    profile_picture: userData.profilePicture,
    credentials: userData.credentials,
    bio: userData.bio,
    verification_file_url: userData.verificationFileUrl,
    store_id: storeId
  };

  const { error: profileError } = await supabase.from('profiles').insert(profilePayload);

  if (profileError) {
    // Se der erro aqui, pode ser duplicação ou RLS. 
    console.error("Erro ao criar perfil:", profileError);
    // Tenta recuperar se já existir (idempotência)
    const existing = await findUserById(userId);
    if (existing) return existing;

    throw new Error("Erro ao salvar dados do perfil. Tente fazer login.");
  }

  return mapUser(profilePayload);
};

