    await supabase.from('chats').update({ messages: newMessages }).eq('id', chatId);

    // Notifications
    data.participants.forEach((pId: string) => {
        if (pId !== msg.senderId) {
            createNotification({ 
                type: NotificationType.MESSAGE, 
                recipientId: pId, 
                actorId: msg.senderId, 
                groupName: data.type === ChatType.GROUP ? data.group_name : undefined, 
                timestamp: Date.now() 
            });
        }
    });
  }
};

