const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// --- AUTH & USERS ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });

  if (error) {
    if (error.message.includes("Email not confirmed")) {
      throw new Error("Email não confirmado. Por favor, verifique sua caixa de entrada e spam.");
    }
    if (error.message.includes("security purposes")) {
      throw new Error("Muitas tentativas de login. Aguarde 60 segundos.");
    }
    if (error.message.includes("Invalid login credentials")) {
      throw new Error("Email ou senha incorretos.");
    }
    // Se for erro de fetch na autenticação, não podemos fazer muito, pois não temos sessão.
    throw new Error(error.message);
  }

  if (!data.user) throw new Error("Usuário não encontrado.");

  let user;
  try {
      user = await findUserById(data.user.id);
  } catch (e) {
      console.warn("Erro ao buscar usuário (possível falha de rede):", e);
  }

  // AUTO-RECUPERAÇÃO DE PERFIL
  if (!user) {
    console.warn("Perfil ausente. Tentando criar automaticamente baseado no Auth...");

    const meta = data.user.user_metadata || {};
    const firstName = meta.first_name || 'Membro';
    const lastName = meta.last_name || 'Novo';

    const recoveryProfile = {
        id: data.user.id,
        email: data.user.email || email,
        first_name: firstName,
        last_name: lastName,
        user_type: UserType.STANDARD,
        phone: '', // Info perdida se não estiver no metadata
        document_id: '',
        birth_date: Date.now(), 
        profile_picture: DEFAULT_PROFILE_PIC,
        balance: 0,
        credentials: '',
        bio: 'Perfil recuperado.',
        followers: [],
        followed_users: []
    };

    // Usando upsert para garantir que se o perfil existir (mas findUserById falhou por latência), ele atualiza
    const { error: recoveryError } = await supabase.from('profiles').upsert(recoveryProfile);

    if (recoveryError) {
        console.error("Falha fatal na recuperação:", recoveryError);

        // FALLBACK CRÍTICO: Se falhar por rede (Failed to fetch), permitimos o login com o perfil local
        // Isso permite que o app funcione em modo 'semi-offline' ou quando o backend está instável
        if (recoveryError.message && (recoveryError.message.includes("Failed to fetch") || recoveryError.message.includes("Network request failed") || recoveryError.message.includes("TypeError"))) {
            console.warn("Ativando modo de fallback para perfil devido a erro de rede.");
            return mapUser(recoveryProfile);
        }

        // Tenta buscar novamente caso o upsert tenha corrigido algo invisível ou se foi um erro transitório
        user = await findUserById(data.user.id);
        if (user) return user;

        throw new Error("Perfil incompleto. Não foi possível restaurar automaticamente: " + recoveryError.message);
    }

    // Mapear o objeto recém-criado para o formato User
    user = mapUser(recoveryProfile);
  }

  return user;
};

export const registerUser = async (userData: any): Promise<User> => {
  // 1. Criar Auth User
  const { data: authData, error: authError } = await supabase.auth.signUp({
    email: userData.email,
    password: userData.password,
    options: {
      data: {
        first_name: userData.firstName,
        last_name: userData.lastName,
      }
    }
  });

  if (authError) {
    if (authError.message.includes("security purposes")) {
      throw new Error("Muitas tentativas. Aguarde 60 segundos antes de tentar novamente.");
    }
    if (authError.message.includes("Database error saving new user")) {
        // Erro comum do Supabase quando triggers falham ou há conflito interno
        throw new Error("Erro no servidor ao criar usuário. Se você já tem uma conta, tente fazer login.");
    }
    throw new Error(authError.message);
  }

  if (!authData.user) throw new Error("Erro ao iniciar criação de conta.");

  const userId = authData.user.id;

  // 2. Criar Store se for Creator (Apenas se tivermos sessão ativa para respeitar RLS padrão, mas tentamos preparar o ID)
  let storeId = null;
  if (userData.userType === UserType.CREATOR) {
    // Se não tiver sessão, a criação da loja pode falhar se RLS estiver ativo.
    // Ignoramos o erro aqui para não bloquear o cadastro principal. A loja pode ser criada depois.
    try {
        const { data: storeData } = await supabase.from('stores').insert({
        professor_id: userId,
        name: `Loja de ${userData.firstName}`,
        description: 'Bem-vindo à minha loja!',
        product_ids: []
        }).selectSingle();

        if (storeData) storeId = storeData.id;
    } catch (e) {
        console.warn("Não foi possível criar loja (provavelmente RLS ou rede):", e);
    }
  }

  // 3. Criar Profile
  const profilePayload = {
    id: userId,
    email: userData.email,
    first_name: userData.firstName,
    last_name: userData.lastName,
    user_type: userData.userType,
    phone: userData.phone,
    document_id: userData.documentId,
    birth_date: userData.birthDate,
    profile_picture: userData.profilePicture,
    credentials: userData.credentials,
    bio: userData.bio,
    verification_file_url: userData.verificationFileUrl,
    store_id: storeId
  };

  // Usamos UPSERT em vez de INSERT. Isso corrige erros onde o usuário já existe parcialmente
  const { error: profileError } = await supabase.from('profiles').upsert(profilePayload);

  // VERIFICAÇÃO DE E-MAIL
  if (authData.user && !authData.session) {
    if (profileError) {
        console.warn("Perfil pendente (Sem sessão):", profileError);
    }
    throw new Error("Cadastro realizado! Verifique seu e-mail para ativar a conta.");
  }

  if (profileError) {
    console.error("Erro ao salvar perfil:", profileError);

    // FALLBACK CRÍTICO DE REDE
    if (profileError.message && (profileError.message.includes("Failed to fetch") || profileError.message.includes("Network request failed") || profileError.message.includes("TypeError"))) {
        console.warn("Ativando modo de fallback para cadastro devido a erro de rede.");
        return mapUser(profilePayload);
    }

    // Tenta recuperar se já existir (idempotência)
    const existing = await findUserById(userId);
    if (existing) return existing;

    throw new Error("Erro ao salvar dados do perfil (" + profileError.message + "). Tente fazer login.");
  }

  return mapUser(profilePayload);
};

