export const updatePostLikes = async (postId: string, userId: string) => {
  // Usando função RPC para array operations se possível, ou read-modify-write
  const { data } = await supabase.from('posts').select('likes, user_id').eq('id', postId).single();
  if (!data) return;

  let likes = data.likes || [];
  if (likes.includes(userId)) {
    likes = likes.filter((id: string) => id !== userId);
  } else {
    likes.push(userId);
    if (data.user_id !== userId) {
        createNotification({ type: NotificationType.LIKE, recipientId: data.user_id, actorId: userId, postId, timestamp: Date.now() });
    }
  }
  await supabase.from('posts').update({ likes }).eq('id', postId);
};

export const updatePostSaves = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('saves').eq('id', postId).single();
  if (!data) return;
  let saves = data.saves || [];
  if (saves.includes(userId)) saves = saves.filter((id: string) => id !== userId);
  else saves.push(userId);
  await supabase.from('posts').update({ saves }).eq('id', postId);
};

export const updatePostShares = async (postId: string, userId: string) => {
  const { data } = await supabase.from('posts').select('shares').eq('id', postId).single();
