export const processProductPurchase = async (items: CartItem[], buyerId: string, affiliateId: string | null, address?: ShippingAddress) => {
    // Process logic needs to happen here for balance updates and inserts
    const products = await getProducts();

    for(const item of items) {
        const prod = products.find(p => p.id === item.productId);
        if(!prod) continue;
        const amount = prod.price * item.quantity;

        let commission = 0;
        if(affiliateId && affiliateId !== prod.storeId) {
            commission = amount * prod.affiliateCommissionRate;
            await updateUserBalance(affiliateId, commission);
            await createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateId, actorId: buyerId, timestamp: Date.now() });
        }

        const store = await findStoreById(prod.storeId);
        if(store) {
            await updateUserBalance(store.professorId, amount - commission);
        }

        await supabase.from('affiliate_sales').insert({
            product_id: prod.id,
            buyer_id: buyerId,
            affiliate_user_id: affiliateId || '',
            store_id: prod.storeId,
            commission_earned: commission,
            sale_amount: amount,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            shipping_address: address,
            digital_content_url: prod.digitalContentUrl,
            is_dropshipping: prod.isDropshipping,
            supplier_cost: prod.originalPrice
        });
    }
    saveCart([]);
    return true;
};

