export const findUserById = async (userId: string): Promise<User | undefined> => {
  try {
    const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();

    if (error) {
        // Verifica se é erro de rede
        if (error.message && (error.message.includes("Failed to fetch") || error.message.includes("Network request failed") || error.message.includes("TypeError"))) {
            console.warn("Rede indisponível. Tentando cache local para usuário:", userId);
            const cached = getCachedUserProfile(userId);
            if (cached) return cached;
            // Se não tem cache, não retornamos undefined para evitar logout em cascata, 
            // mas sem dados não há muito o que fazer. Deixamos o chamador lidar ou retornamos undefined.
        }
        // Se o usuário não existir (ex: deletado), retorna undefined
        return undefined;
    }

    if (!data) return undefined;

    const user = mapUser(data);
    cacheUserProfile(user); // Cache bem sucedido
    return user;
  } catch (e: any) {
      console.warn("Exceção em findUserById:", e);
      const cached = getCachedUserProfile(userId);
      if (cached) return cached;
      return undefined;
  }
};

