export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    // Fetch sale, check if rated, update sale, update product ratings
    await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);
    // Note: This logic requires a more complex query to fetch the product and append rating
    // For now in Supabase, we would ideally have a separate 'ratings' table.
    // Simplifying: we update the product's JSONB column
    const { data: sale } = await supabase.from('affiliate_sales').select('product_id, buyer_id').eq('id', saleId).single();
    if(sale) {
        const { data: prod } = await supabase.from('products').select('ratings').eq('id', sale.product_id).single();
        if(prod) {
            const newRating = { id: generateUUID(), saleId, userId: sale.buyer_id, rating, comment, timestamp: Date.now() };
            const ratings = [...(prod.ratings || []), newRating];
            const avg = ratings.reduce((a:any, b:any) => a + b.rating, 0) / ratings.length;
            await supabase.from('products').update({ ratings, average_rating: avg, rating_count: ratings.length }).eq('id', sale.product_id);
        }
    }
};

