export const uploadFile = async (file: File, folder: string): Promise<string> => {
  const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
  const filePath = `${folder}/${fileName}`;

  try {
    const { data, error } = await supabase.storage.from('cyberphone').upload(filePath, file);

    if (error) {
        console.error("Erro no Storage Supabase:", error);
        throw new Error(error.message);
    }

    const { data: urlData } = supabase.storage.from('cyberphone').getPublicUrl(filePath);
    return urlData.publicUrl;
  } catch (e: any) {
    console.error("Exceção no upload:", e);

    // Tratamento específico para erros críticos de rede ou configuração
    if (folder === 'profiles') {
        // Se for upload de perfil e falhar, usamos uma imagem padrão para não bloquear o cadastro
    }

    // Fallback para Base64 para garantir funcionalidade em caso de falha de storage (ex: "Failed to fetch")
    // Isso permite que a demo funcione 100% mesmo sem o bucket configurado ou com CORS/Network issues.
    if (file.type.startsWith('image/') || file.type.startsWith('application/pdf')) {
        console.warn("Usando fallback Base64 devido a falha no upload.");
        return await fileToBase64(file);
    }

    throw new Error("Falha no upload: " + (e.message || "Erro de conexão"));
  }
};

