  const { data } = await supabase.from('chats').select('messages, participants, type, group_name').eq('id', chatId).single();
  if (data) {
    const newMessages = [...(data.messages || []), msg];
    await supabase.from('chats').update({ messages: newMessages }).eq('id', chatId);

    data.participants.forEach((pId: string) => {
        if (pId !== msg.senderId) {
            createNotification({ 
                type: NotificationType.MESSAGE, 
                recipientId: pId, 
                actorId: msg.senderId, 
                groupName: data.type === ChatType.GROUP ? data.group_name : undefined, 
                timestamp: Date.now() 
            });
        }
    });
  }
};

