export const findUserById = async (userId: string): Promise<User | undefined> => {
  try {
    const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();

    // Se houver erro (incluindo "Row not found" PGRST116 ou "Failed to fetch"), 
    // tentamos o cache local como fonte da verdade.
    if (error) {
        const cached = getCachedUserProfile(userId);
        if (cached) {
            // Se achou no cache, retorna o cache e ignora o erro do banco por enquanto
            return cached;
        }
        // Se não tem cache e deu erro de rede, logamos warning
        if (error.message && (error.message.includes("Failed to fetch") || error.message.includes("Network"))) {
             console.warn("Rede indisponível e sem cache para usuário:", userId);
        }
        return undefined;
    }

    if (!data) return undefined;

    const user = mapUser(data);
    cacheUserProfile(user); 
    return user;
  } catch (e: any) {
      // Em caso de exceção grave, tenta o cache
      const cached = getCachedUserProfile(userId);
      if (cached) return cached;
      return undefined;
  }
};

