export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  const currentUser = await findUserById(currentUserId);
  const targetUser = await findUserById(userIdToFollow);

  if (!currentUser || !targetUser) return;

  let newFollowing = [...currentUser.followedUsers];
  let newFollowers = [...targetUser.followers];

  if (newFollowing.includes(userIdToFollow)) {
    newFollowing = newFollowing.filter(id => id !== userIdToFollow);
    newFollowers = newFollowers.filter(id => id !== currentUserId);
  } else {
    newFollowing.push(userIdToFollow);
    newFollowers.push(currentUserId);
    await createNotification({ 
      type: NotificationType.NEW_FOLLOWER, 
      recipientId: userIdToFollow, 
      actorId: currentUserId, 
      timestamp: Date.now() 
    });
  }

  await supabase.from('profiles').update({ followed_users: newFollowing }).eq('id', currentUserId);
  await supabase.from('profiles').update({ followers: newFollowers }).eq('id', userIdToFollow);
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    const newBalance = (user.balance || 0) + amount;

    // Atualiza cache local
    cacheUserProfile({ ...user, balance: newBalance });

    await supabase.from('profiles').update({ balance: newBalance }).eq('id', userId);

    await supabase.from('transactions').insert({
      user_id: userId,
      type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
      amount: Math.abs(amount),
      description: amount > 0 ? 'Depósito/Venda' : 'Saque/Compra',
      timestamp: Date.now(),
      status: 'COMPLETED'
    });

    return true;
  }
  return false;
};

