export const addPost = async (post: Post) => {
  const payload = {
    user_id: post.userId,
    type: post.type,
    content: post.content,
    image_url: post.imageUrl,
    timestamp: post.timestamp,
    group_id: post.groupId,
    group_name: post.groupName,
    background_color: post.backgroundColor,
    text_color: post.textColor,
    font_family: post.fontFamily,
    reel_data: post.reel ? post.reel : null,
    live_data: post.liveStream ? post.liveStream : null,
    likes: [],
    comments: [],
    shares: [],
    saves: []
  };

  try {
    const { data, error } = await supabase.from('posts').insert(payload).select().single();

    if (data && !error) {
        if (post.groupId) {
            // Group notification logic
        } else {
            const user = await findUserById(post.userId);
            if (user && user.followers) {
                user.followers.forEach(followerId => {
                    createNotification({ type: NotificationType.NEW_POST, recipientId: followerId, actorId: post.userId, postId: data.id, timestamp: Date.now() });
                });
            }
        }
    }
  } catch (e) {
    console.warn("Erro ao publicar post (possivelmente offline):", e);
  }
};

export const updatePost = async (post: Post) => {
  const payload = {
    content: post.content,
    is_pinned: post.isPinned,
