export const processProductPurchase = async (items: CartItem[], buyerId: string, affiliateId: string | null, address?: ShippingAddress) => {
    const products = await getProducts();

    for(const item of items) {
        const prod = products.find(p => p.id === item.productId);
        if(!prod) continue;
        const amount = prod.price * item.quantity;

        let commission = 0;
        if(affiliateId && affiliateId !== prod.storeId) {
            commission = amount * prod.affiliateCommissionRate;
            await updateUserBalance(affiliateId, commission);
            await createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateId, actorId: buyerId, timestamp: Date.now() });
        }

        const store = await findStoreById(prod.storeId);
        if(store) {
            await updateUserBalance(store.professorId, amount - commission);
        }

        await supabase.from('affiliate_sales').insert({
            product_id: prod.id,
            buyer_id: buyerId,
            affiliate_user_id: affiliateId || '',
            store_id: prod.storeId,
            commission_earned: commission,
            sale_amount: amount,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            shipping_address: address,
            digital_content_url: prod.digitalContentUrl,
            is_dropshipping: prod.isDropshipping,
            supplier_cost: prod.originalPrice
        });
    }
    saveCart([]);
    return true;
};

export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    if(await updateUserBalance(userId, -cost)) {
        await updateSaleStatus(saleId, OrderStatus.PROCESSING_SUPPLIER);
        return true;
    }
    return false;
};

export const updateSaleStatus = async (saleId: string, status: OrderStatus) => {
    await supabase.from('affiliate_sales').update({ status }).eq('id', saleId);
};

export const updateSaleTracking = async (saleId: string, code: string, supplierId?: string) => {
    await supabase.from('affiliate_sales').update({ tracking_code: code, supplier_order_id: supplierId }).eq('id', saleId);
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);

    const { data: sale } = await supabase.from('affiliate_sales').select('product_id, buyer_id').eq('id', saleId).single();
    if(sale) {
        const { data: prod } = await supabase.from('products').select('ratings').eq('id', sale.product_id).single();
        if(prod) {
            const newRating = { id: generateUUID(), saleId, userId: sale.buyer_id, rating, comment, timestamp: Date.now() };
            const ratings = [...(prod.ratings || []), newRating];
            const avg = ratings.reduce((a:any, b:any) => a + b.rating, 0) / ratings.length;
            await supabase.from('products').update({ ratings, average_rating: avg, rating_count: ratings.length }).eq('id', sale.product_id);
        }
    }
};

