import { 
  User, Post, ChatConversation, AdCampaign, UserType, Store, Product, 
  AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, 
  Notification, NotificationType, CartItem, ProductRating, OrderStatus, 
  CyberEvent, Story, ContentReport, SystemLog, Transaction, GlobalSettings, 
  TransactionType, Message, ChatType, GroupTheme
} from '../types';
import { supabase } from './supabaseClient';
import { 
  DEFAULT_PROFILE_PIC, 
  DEFAULT_USERS, 
  DEFAULT_POSTS, 
  DEFAULT_ADS, 
  DEFAULT_STORES, 
  DEFAULT_PRODUCTS, 
  DEFAULT_AUDIO_TRACKS 
} from '../data/constants';

// --- CONSTANTES DE LOCAL STORAGE (FALLBACK) ---
const KEYS = {
  USERS: 'cyber_data_users',
  POSTS: 'cyber_data_posts',
  CHATS: 'cyber_data_chats',
  ADS: 'cyber_data_ads',
  STORES: 'cyber_data_stores',
  PRODUCTS: 'cyber_data_products',
  SALES: 'cyber_data_sales',
  NOTIFICATIONS: 'cyber_data_notifications',
  CURRENT_USER: 'cyber_current_user_id',
  EVENTS: 'cyber_data_events',
  STORIES: 'cyber_data_stories',
  CART: 'cyberphone_cart'
};

// --- HELPER FUNCTIONS ---

export const generateUUID = () => crypto.randomUUID();

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// Generic Local Storage Helpers
const getLocalList = <T>(key: string, defaultData: T[] = []): T[] => {
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultData;
  } catch { return defaultData; }
};

const saveLocalList = <T>(key: string, data: T[]) => {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) { console.warn("Quota LocalStorage excedida"); }
};

// --- MAPPERS (Banco -> App) ---
const mapUser = (row: any): User => ({
  id: row.id,
  userType: row.user_type as UserType,
  firstName: row.first_name,
  lastName: row.last_name,
  email: row.email,
  phone: row.phone || '',
  documentId: row.document_id || '',
  birthDate: Number(row.birth_date),
  profilePicture: row.profile_picture || DEFAULT_PROFILE_PIC,
  balance: row.balance || 0,
  credentials: row.credentials,
  bio: row.bio,
  verificationFileUrl: row.verification_file_url,
  isAdmin: row.is_admin || false,
  isVerified: row.is_verified || false,
  isSuspended: row.is_suspended || false,
  isPremium: row.is_premium || false,
  premiumExpiry: Number(row.premium_expiry),
  followers: row.followers || [],
  followedUsers: row.followed_users || [],
  storeId: row.store_id
});

// --- AUTH & USERS ---

export const loginUser = async (email: string, password: string): Promise<User> => {
  // 1. Tenta Supabase Auth
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });

  if (!error && data.user) {
    // Sucesso no Auth, busca perfil
    const user = await findUserById(data.user.id);
    if (user) return user;
  }

  // 2. Fallback: Verifica usuários locais (Modo Offline/Demo)
  const localUsers = getLocalList<User>(KEYS.USERS, DEFAULT_USERS as any);
  const localUser = localUsers.find(u => u.email === email);

  if (localUser) {
    console.warn("Login realizado via LocalStorage (Modo Offline)");
    return localUser;
  }

  throw new Error(error?.message || "Usuário não encontrado.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const userId = generateUUID();
  let storeId = null;

  // Cria loja se for criador
  if (userData.userType === UserType.CREATOR) {
    storeId = generateUUID();
    const newStore: Store = {
      id: storeId,
      professorId: userId,
      name: `Loja de ${userData.firstName}`,
      description: 'Bem-vindo à minha loja!',
      productIds: [],
      brandColor: '#2563eb'
    };
    // Salva loja localmente
    const stores = getLocalList<Store>(KEYS.STORES, DEFAULT_STORES);
    saveLocalList(KEYS.STORES, [...stores, newStore]);

    // Tenta salvar loja no Supabase (silencioso se falhar)
    supabase.from('stores').insert({
        id: storeId,
        professor_id: userId,
        name: newStore.name,
        description: newStore.description,
        brand_color: newStore.brandColor
    }).then(() => {});
  }

  const newUser: User = {
    id: userId,
    email: userData.email,
    firstName: userData.firstName,
    lastName: userData.lastName,
    userType: userData.userType,
    phone: userData.phone,
    documentId: userData.documentId,
    birthDate: userData.birthDate,
    profilePicture: userData.profilePicture,
    credentials: userData.credentials,
    bio: userData.bio,
    verificationFileUrl: userData.verificationFileUrl,
    storeId: storeId || undefined,
    balance: 0,
    followers: [],
    followedUsers: [],
    isAdmin: false,
    isVerified: false,
    isSuspended: false,
    isPremium: false
  };

  // 1. Salva no LocalStorage IMEDIATAMENTE (Garante que "findUserById" funcione)
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS as any);
  saveLocalList(KEYS.USERS, [...users, newUser]);

  // 2. Tenta criar no Supabase Auth e Tabela Profiles
  try {
    const { data: authData, error: authError } = await supabase.auth.signUp({
      email: userData.email,
      password: userData.password,
      options: { data: { first_name: userData.firstName, last_name: userData.lastName } }
    });

    if (!authError && authData.user) {
      // Atualiza ID para bater com o Auth real se conseguiu criar
      const realId = authData.user.id;
      newUser.id = realId;
      if(storeId) {
          // Atualiza ID do dono da loja se necessário
          const stores = getLocalList<Store>(KEYS.STORES);
          const st = stores.find(s => s.id === storeId);
          if(st) { st.professorId = realId; saveLocalList(KEYS.STORES, stores); }
      }

      await supabase.from('profiles').upsert({
        id: realId,
        email: newUser.email,
        first_name: newUser.firstName,
        last_name: newUser.lastName,
        user_type: newUser.userType,
        phone: newUser.phone,
        document_id: newUser.documentId,
        birth_date: newUser.birthDate,
        profile_picture: newUser.profilePicture,
        credentials: newUser.credentials,
        bio: newUser.bio,
        store_id: storeId
      });
    }
  } catch (e) {
    console.warn("Cadastro offline realizado. Sincronização pendente.");
  }

  return newUser;
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(KEYS.CURRENT_USER, userId);
  else {
    localStorage.removeItem(KEYS.CURRENT_USER);
    supabase.auth.signOut().catch(() => {});
  }
};

export const getCurrentUserId = (): string | null => {
  return localStorage.getItem(KEYS.CURRENT_USER);
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  // 1. Tenta Cache Local primeiro (Performance + Offline)
  const localUsers = getLocalList<User>(KEYS.USERS, DEFAULT_USERS as any);
  const localUser = localUsers.find(u => u.id === userId);

  if (localUser) return localUser;

  // 2. Tenta Supabase
  try {
    const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
    if (data && !error) {
      const mapped = mapUser(data);
      // Atualiza cache
      saveLocalList(KEYS.USERS, [...localUsers, mapped]);
      return mapped;
    }
  } catch (e) {
    console.warn("Erro ao buscar usuário online, usando fallback.");
  }

  return undefined;
};

export const getUsers = async (): Promise<User[]> => {
  try {
    const { data } = await supabase.from('profiles').select('*');
    if (data) return data.map(mapUser);
  } catch (e) {}
  return getLocalList<User>(KEYS.USERS, DEFAULT_USERS as any);
};

export const updateUser = async (updatedUser: User) => {
  // Atualiza Local
  const users = getLocalList<User>(KEYS.USERS);
  const newUsers = users.map(u => u.id === updatedUser.id ? updatedUser : u);
  saveLocalList(KEYS.USERS, newUsers);

  // Tenta Online
  try {
    await supabase.from('profiles').update({
      first_name: updatedUser.firstName,
      last_name: updatedUser.lastName,
      bio: updatedUser.bio,
      profile_picture: updatedUser.profilePicture,
      balance: updatedUser.balance,
      followed_users: updatedUser.followedUsers,
      followers: updatedUser.followers
    }).eq('id', updatedUser.id);
  } catch(e) {}
};

export const updateUserPassword = async (password: string) => {
  try {
    const { error } = await supabase.auth.updateUser({ password });
    if (error) throw error;
  } catch (e) {
    console.warn("Erro ao atualizar senha no Supabase:", e);
    throw e;
  }
};

export const toggleFollowUser = async (currentUserId: string, userIdToFollow: string) => {
  let currentUser = await findUserById(currentUserId);
  let targetUser = await findUserById(userIdToFollow);

  if (!currentUser || !targetUser) return;

  // Lógica Local
  if (currentUser.followedUsers.includes(userIdToFollow)) {
    currentUser.followedUsers = currentUser.followedUsers.filter(id => id !== userIdToFollow);
    targetUser.followers = targetUser.followers.filter(id => id !== currentUserId);
  } else {
    currentUser.followedUsers.push(userIdToFollow);
    targetUser.followers.push(currentUserId);
    createNotification({ 
      type: NotificationType.NEW_FOLLOWER, 
      recipientId: userIdToFollow, 
      actorId: currentUserId, 
      timestamp: Date.now() 
    });
  }

  await updateUser(currentUser);
  await updateUser(targetUser);
};

export const updateUserBalance = async (userId: string, amount: number) => {
  const user = await findUserById(userId);
  if (user) {
    user.balance = (user.balance || 0) + amount;
    await updateUser(user);

    // Log Transação
    const tx: Transaction = {
        id: generateUUID(),
        userId,
        type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
        amount: Math.abs(amount),
        description: amount > 0 ? 'Crédito' : 'Débito',
        timestamp: Date.now(),
        status: 'COMPLETED'
    };
    const txs = getLocalList<Transaction>('cyber_transactions');
    saveLocalList('cyber_transactions', [tx, ...txs]);

    return true;
  }
  return false;
};

// --- POSTS ---

export const getPosts = async (): Promise<Post[]> => {
  try {
    const { data, error } = await supabase.from('posts').select('*, profiles(first_name, last_name, profile_picture)').order('timestamp', { ascending: false });
    if (!error && data) {
        return data.map((row: any) => ({
            id: row.id,
            userId: row.user_id,
            authorName: row.profiles ? `${row.profiles.first_name} ${row.profiles.last_name}` : 'Usuário',
            authorProfilePic: row.profiles ? row.profiles.profile_picture : DEFAULT_PROFILE_PIC,
            type: row.type,
            content: row.content,
            imageUrl: row.image_url,
            timestamp: Number(row.timestamp),
            likes: row.likes || [],
            comments: row.comments || [],
            shares: row.shares || [],
            saves: row.saves || [],
            isPinned: row.is_pinned,
            isBoosted: row.is_boosted,
            boostExpires: Number(row.boost_expires),
            liveStream: row.live_data,
            reel: row.reel_data,
            fontFamily: row.font_family,
            textColor: row.text_color,
            backgroundColor: row.background_color,
            fontSize: row.font_size,
            groupId: row.group_id,
            groupName: row.group_name,
            indicatedUserIds: row.indicated_user_ids || []
        }));
    }
  } catch (e) {}
  return getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
};

export const addPost = async (post: Post) => {
  // Salva Local
  const posts = getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
  saveLocalList(KEYS.POSTS, [post, ...posts]);

  // Notifica seguidores (Local)
  const user = await findUserById(post.userId);
  if (user && user.followers) {
      user.followers.forEach(fid => {
          createNotification({ type: NotificationType.NEW_POST, recipientId: fid, actorId: post.userId, postId: post.id, timestamp: Date.now() });
      });
  }

  // Tenta Salvar Online
  try {
    await supabase.from('posts').insert({
        id: post.id,
        user_id: post.userId,
        type: post.type,
        content: post.content,
        image_url: post.imageUrl,
        timestamp: post.timestamp,
        group_id: post.groupId,
        group_name: post.groupName,
        background_color: post.backgroundColor,
        text_color: post.textColor,
        font_family: post.fontFamily,
        reel_data: post.reel,
        live_data: post.liveStream,
        likes: post.likes,
        comments: post.comments
    });
  } catch(e) {}
};

export const updatePost = async (post: Post) => {
  const posts = getLocalList<Post>(KEYS.POSTS);
  const newPosts = posts.map(p => p.id === post.id ? post : p);
  saveLocalList(KEYS.POSTS, newPosts);

  try {
    await supabase.from('posts').update({
        content: post.content,
        likes: post.likes,
        comments: post.comments,
        saves: post.saves,
        is_pinned: post.isPinned,
        is_boosted: post.isBoosted,
        indicated_user_ids: post.indicatedUserIds
    }).eq('id', post.id);
  } catch(e) {}
};

export const deletePost = async (postId: string) => {
  const posts = getLocalList<Post>(KEYS.POSTS).filter(p => p.id !== postId);
  saveLocalList(KEYS.POSTS, posts);
  try { await supabase.from('posts').delete().eq('id', postId); } catch(e) {}
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = getLocalList<Post>(KEYS.POSTS);
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else {
        post.likes.push(userId);
        if(post.userId !== userId) {
            createNotification({ type: NotificationType.LIKE, recipientId: post.userId, actorId: userId, postId, timestamp: Date.now() });
        }
    }
    await updatePost(post);
  }
};

export const updatePostSaves = async (postId: string, userId: string) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    const post = posts.find(p => p.id === postId);
    if(post) {
        if(post.saves.includes(userId)) post.saves = post.saves.filter(id => id !== userId);
        else post.saves.push(userId);
        await updatePost(post);
    }
};

export const updatePostShares = async (postId: string, userId: string) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    const post = posts.find(p => p.id === postId);
    if(post && !post.shares.includes(userId)) {
        post.shares.push(userId);
        await updatePost(post);
    }
};

export const addPostComment = async (postId: string, comment: Comment) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    const post = posts.find(p => p.id === postId);
    if(post) {
        post.comments.push(comment);
        if(post.userId !== comment.userId) {
            createNotification({ type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId, timestamp: Date.now() });
        }
        await updatePost(post);
    }
};

export const pinPost = async (postId: string, userId: string) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    posts.forEach(p => {
        if(p.userId === userId) p.isPinned = (p.id === postId);
    });
    saveLocalList(KEYS.POSTS, posts);
    // Sync online
    try {
        await supabase.from('posts').update({ is_pinned: false }).eq('user_id', userId);
        await supabase.from('posts').update({ is_pinned: true }).eq('id', postId);
    } catch(e) {}
    return true;
};

export const unpinPost = async (postId: string, userId: string) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    const post = posts.find(p => p.id === postId);
    if(post) {
        post.isPinned = false;
        saveLocalList(KEYS.POSTS, posts);
        try { await supabase.from('posts').update({ is_pinned: false }).eq('id', postId); } catch(e) {}
    }
    return true;
};

export const boostPost = async (pId: string, uId: string, budget: number, days: number) => {
    const success = await updateUserBalance(uId, -budget);
    if(success) {
        const posts = getLocalList<Post>(KEYS.POSTS);
        const post = posts.find(p => p.id === pId);
        if(post) {
            post.isBoosted = true;
            post.boostExpires = Date.now() + (days * 86400000);
            await updatePost(post);
            return true;
        }
    }
    return false;
};

export const indicatePostToUser = async (pId: string, from: string, to: string) => {
    const posts = getLocalList<Post>(KEYS.POSTS);
    const post = posts.find(p => p.id === pId);
    if(post) {
        if(!post.indicatedUserIds) post.indicatedUserIds = [];
        if(post.indicatedUserIds.includes(to)) return false;
        post.indicatedUserIds.push(to);
        await updatePost(post);
        createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: pId, timestamp: Date.now() });
        return true;
    }
    return false;
};

