export const getChats = async (): Promise<ChatConversation[]> => {
    try {
        const { data } = await supabase.from('chats').select('*');
        if(data) {
            return data.map((row: any) => ({
                id: row.id,
                type: row.type,
                participants: row.participants,
                messages: row.messages || [],
                groupName: row.group_name,
                groupImage: row.group_image,
                adminId: row.admin_id,
                isPublic: row.is_public,
                description: row.description,
                theme: row.theme
            }));
        }
    } catch(e) {}
    return getLocalList<ChatConversation>(KEYS.CHATS);
};

export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme?: string) => {
    const newChat: ChatConversation = {
        id: generateUUID(),
        type: ChatType.GROUP,
        participants: [...members, adminId],
        messages: [],
        groupName: name,
        adminId,
        description,
        theme: theme as GroupTheme,
        isPublic: false
    };

    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
