            type: newChat.type,
            participants: newChat.participants,
            group_name: newChat.groupName,
            admin_id: newChat.adminId,
            description: newChat.description,
            theme: newChat.theme,
            messages: []
        });
    } catch(e) {}

    return newChat;
};

