export const uploadFile = async (file: File, folder: string): Promise<string> => {
  try {
    const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.]/g, '')}`;
    const filePath = `${folder}/${fileName}`;
    const { error } = await supabase.storage.from('cyberphone').upload(filePath, file);
    if (error) throw error;
    const { data } = supabase.storage.from('cyberphone').getPublicUrl(filePath);
    return data.publicUrl;
  } catch (e) {
    // FALLBACK OFFLINE: Converte para Base64 se upload falhar
    console.warn("Upload falhou, usando Base64 local.");
    return await fileToBase64(file);
