export const processProductPurchase = async (items: CartItem[], buyerId: string, affiliateId: string | null, address?: ShippingAddress) => {
    const allProducts = await getProducts();
    const newSales: AffiliateSale[] = [];

    for(const item of items) {
        const prod = allProducts.find(p => p.id === item.productId);
        if(!prod) continue;

        const amount = prod.price * item.quantity;
        let commission = 0;

        // Pagar Comissão
        if(affiliateId && affiliateId !== prod.storeId) {
            commission = amount * prod.affiliateCommissionRate;
            await updateUserBalance(affiliateId, commission);
            createNotification({ type: NotificationType.AFFILIATE_SALE, recipientId: affiliateId, actorId: buyerId, timestamp: Date.now() });
        }

        // Pagar Dono da Loja
        const store = await findStoreById(prod.storeId);
        if(store) {
            await updateUserBalance(store.professorId, amount - commission);
        }

        const sale: AffiliateSale = {
            id: generateUUID(),
            productId: prod.id,
            buyerId: buyerId,
            affiliateUserId: affiliateId || '',
            storeId: prod.storeId,
            commissionEarned: commission,
            saleAmount: amount,
            timestamp: Date.now(),
            status: OrderStatus.WAITLIST,
            shippingAddress: address,
            isDropshipping: prod.isDropshipping,
            supplierCost: prod.originalPrice,
            digitalContentUrl: prod.digitalContentUrl
        };
        newSales.push(sale);

        // Sync BD
        try {
            await supabase.from('affiliate_sales').insert({
                id: sale.id,
                product_id: sale.productId,
                buyer_id: sale.buyerId,
                affiliate_user_id: sale.affiliateUserId,
                store_id: sale.storeId,
                commission_earned: sale.commissionEarned,
                sale_amount: sale.saleAmount,
                timestamp: sale.timestamp,
                status: sale.status,
                shipping_address: sale.shippingAddress,
                is_dropshipping: sale.isDropshipping,
                supplier_cost: sale.supplierCost
            });
        } catch(e) {}
    }

    const currentSales = getLocalList<AffiliateSale>(KEYS.SALES);
    saveLocalList(KEYS.SALES, [...currentSales, ...newSales]);
    saveCart([]); // Limpa carrinho
    return true;
};

