    const user = await findUserById(uId);
    if(!story && user) {
        story = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
        stories.push(story);
    }
    if(story) {
        const newItem = { ...item, id: generateUUID(), timestamp: Date.now() };
        story.items.push(newItem);
        saveLocalList(KEYS.STORIES, stories);

        // Sync BD (Upsert)
        try {
            await supabase.from('stories').upsert({
                user_id: uId,
                user_name: story.userName,
                user_profile_pic: story.userProfilePic,
                items: story.items
            }, { onConflict: 'user_id' });
        } catch(e) {}
    }
