            platform_tax: s.platformTax,
            upgrade_cost: s.upgradeCost,
            min_withdrawal: s.minWithdrawal,
            maintenance_mode: s.maintenanceMode
        }).eq('id', 1).then(() => {});
    } catch(e) {}
};

export const getPlatformRevenue = async () => 15000;

export const getTransactions = async (): Promise<Transaction[]> => {
    try {
        const { data } = await supabase.from('transactions').select('*');
        if(data) return data.map((row: any) => ({
            id: row.id,
            userId: row.user_id,
            type: row.type,
            amount: row.amount,
            description: row.description,
            timestamp: Number(row.timestamp),
            status: row.status
        }));
    } catch(e) {}
    return getLocalList<Transaction>(KEYS.TRANSACTIONS);
};

export const getSystemLogs = async (): Promise<SystemLog[]> => {
    try {
        const { data } = await supabase.from('system_logs').select('*');
        if(data) return data.map((row: any) => ({
            id: row.id,
            adminId: row.admin_id,
            action: row.action,
            targetId: row.target_id,
            details: row.details,
            timestamp: Number(row.timestamp)
        }));
    } catch(e) {}
    return [];
};

export const getReports = async (): Promise<ContentReport[]> => {
    try {
        const { data } = await supabase.from('reports').select('*');
        if(data) return data.map((row: any) => ({
            id: row.id,
            reporterId: row.reporter_id,
            targetId: row.target_id,
            targetType: row.target_type,
            reason: row.reason,
            details: row.details,
            status: row.status,
            timestamp: Number(row.timestamp)
        }));
    } catch(e) {}
    return [];
};

export const createReport = async (r: any) => {
    try {
        await supabase.from('reports').insert({
            reporter_id: r.reporterId,
            target_id: r.targetId,
            target_type: r.targetType,
            reason: r.reason,
            details: r.details,
            status: 'OPEN',
            timestamp: Date.now()
        });
    } catch(e) {}
};

export const adminProcessReport = async (rId: string, status: 'RESOLVED' | 'DISMISSED', adminId: string) => {
    try {
        await supabase.from('reports').update({ status }).eq('id', rId);
        await supabase.from('system_logs').insert({
            admin_id: adminId,
            action: 'REPORT_PROCESSED',
            target_id: rId,
            details: `Status alterado para ${status}`,
            timestamp: Date.now()
        });
    } catch(e) {}
};

export const adminUpdateUser = async (u: User) => updateUser(u);
export const adminDeletePost = async (id: string) => deletePost(id);
export const deleteUser = async (id: string) => {
    const users = getLocalList<User>(KEYS.USERS).filter(u => u.id !== id);
    saveLocalList(KEYS.USERS, users);
    try { await supabase.from('profiles').delete().eq('id', id); } catch(e) {}
};

export const getAppTheme = (): GroupTheme => (localStorage.getItem('cyberphone_app_theme') as GroupTheme) || 'blue';
export const saveAppTheme = (t: GroupTheme) => localStorage.setItem('cyberphone_app_theme', t);

import React, { useState, useRef } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, getStores, saveStores, generateUUID } from '../services/storageService';
import { 
  ShieldCheckIcon, 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  CommandLineIcon,
  BuildingStorefrontIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance'>('main');
  const [isOnWaitlist, setIsOnWaitlist] = useState(false);

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      await updateUser(updatedUser);
      refreshUser();
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  // --- FUNÇÕES DE DEBUG/DEMO ---
  const toggleAdminRole = async () => {
    await updateUser({ ...currentUser, isAdmin: !currentUser.isAdmin });
    refreshUser();
    alert(`Modo Admin ${!currentUser.isAdmin ? 'ATIVADO' : 'DESATIVADO'}. Verifique o rodapé.`);
  };

  const toggleCreatorRole = async () => {
    const newType = currentUser.userType === UserType.STANDARD ? UserType.CREATOR : UserType.STANDARD;
    let updates: Partial<User> = { userType: newType };

    // Se virar criador e não tiver loja, cria uma automaticamente
    if (newType === UserType.CREATOR) {
        const stores = await getStores();
        const existingStore = stores.find(s => s.professorId === currentUser.id);

        if (!existingStore) {
            const newStoreId = generateUUID();
            await saveStores([...stores, {
                id: newStoreId,
                professorId: currentUser.id,
                name: `Loja de ${currentUser.firstName}`,
                description: 'Minha loja oficial no CyBerPhone.',
                productIds: []
            }]);
            updates.storeId = newStoreId;
        } else {
            updates.storeId = existingStore.id;
        }
        updates.credentials = currentUser.credentials || 'Criador de Conteúdo';
    }

    await updateUser({ ...currentUser, ...updates });
    refreshUser();
    alert(`Conta alterada para ${newType === UserType.CREATOR ? 'PROFISSIONAL (Com Loja)' : 'PADRÃO'}.`);
  };

  const handleDeletePress = async () => {
    if (window.confirm('TEM CERTEZA? Esta ação excluirá permanentemente sua conta da rede social e não poderá ser desfeita.')) {
      await deleteUser(currentUser.id);
      onDeleteAccount();
    }
  };

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-4xl font-black dark:text-white tracking-tighter">Dados de Inscrição</h2>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-500/30 rounded-2xl flex items-center gap-3 animate-fade-in">
             <CheckIcon className="h-5 w-5 text-green-600" />
             <p className="text-xs font-black text-green-700 dark:text-green-400 uppercase tracking-widest">Perfil atualizado!</p>
          </div>
        )}

        <form onSubmit={handleSaveProfile} className="space-y-8">
           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Identidade Visual</p>
              <div className="flex flex-col items-center gap-6">
                 <div 
                   onClick={() => fileInputRef.current?.click()} 
                   className="relative group cursor-pointer"
                 >
                    <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-white dark:border-darkcard shadow-2xl transition-transform group-hover:scale-105 relative">
                       <img src={profilePicture || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" alt="Profile" />
                       {isUploading && (
                         <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                           <div className="w-8 h-8 border-4 border-white border-t-transparent animate-spin rounded-full"></div>
                         </div>
                       )}
                       <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                          <CameraIcon className="h-10 w-10 text-white" />
                       </div>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-brand text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                       <PaintBrushIcon className="h-4 w-4" />
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileChange} 
                    />
                 </div>
                 <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Clique na foto para alterar</p>
              </div>
           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Dados Pessoais</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nome</label>
                    <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Sobrenome</label>
                    <input type="text" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Cargo ou Especialidade</label>
                      <input type="text" value={credentials} onChange={e => setCredentials(e.target.value)} placeholder="Ex: Professor" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-brand font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className={`bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border transition-all ${currentUser.isAdmin ? 'border-green-500/20 shadow-green-500/10' : 'border-gray-200 dark:border-white/10 opacity-90'}`}>
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                    {currentUser.isAdmin ? (
                        <><LockOpenIcon className="h-3 w-3 text-green-500" /> Acesso Administrativo (Desbloqueado)</>
                    ) : (
                        <><LockClosedIcon className="h-3 w-3" /> Dados Sensíveis (Protegidos)</>
                    )}
                 </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-brand hover:bg-brandHover text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Salvar Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Cores e Modo Dark', icon: PaintBrushIcon, onClick: () => setView('appearance') }
      ]
    },
    {
      title: 'Finanças e Segurança',
      items: [
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
    }
  ];

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-4xl animate-fade-in">
      <div className="flex items-center gap-6 mb-10">
        <button onClick={() => onNavigate('profile')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Ajustes</h2>
      </div>

      <div className="space-y-10">
        {sections.map(section => (
          <div key={section.title}>
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">{section.title}</h3>
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-white/10 overflow-hidden">
              {section.items.map((item, idx) => (
                <div 
                  key={item.label} 
                  onClick={item.onClick}
                  className={`p-6 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-white/5 transition-colors cursor-pointer ${idx !== section.items.length - 1 ? 'border-b border-gray-50 dark:border-white/10' : ''}`}
                >
                  <div className="flex items-center gap-5">
                    <div className="p-3 rounded-2xl bg-brand/10 text-brand">
                      <item.icon className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="font-black text-sm dark:text-white">{item.label}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.desc}</p>
                    </div>
                  </div>
                  <ChevronDownIcon className="h-5 w-5 text-gray-300 -rotate-90" />
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* ÁREA DE DEBUG / DEMO */}
        <div className="mt-12 p-6 bg-red-50 dark:bg-red-900/10 rounded-[2.5rem] border border-red-100 dark:border-red-900/20">
            <h3 className="text-red-600 font-black uppercase text-xs tracking-widest mb-4 flex items-center gap-2">
                <CommandLineIcon className="h-4 w-4" /> Área de Desenvolvimento (Demo)
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <button 
                  onClick={toggleAdminRole} 
                  className={`py-4 rounded-2xl font-black text-xs uppercase transition-all shadow-sm ${currentUser.isAdmin ? 'bg-red-600 text-white shadow-red-500/20' : 'bg-white dark:bg-white/5 text-gray-500 hover:text-red-500'}`}
                >
                   {currentUser.isAdmin ? 'Desativar Admin' : 'Ativar Admin (Root)'}
                </button>
                <button 
                  onClick={toggleCreatorRole} 
                  className={`py-4 rounded-2xl font-black text-xs uppercase transition-all shadow-sm flex items-center justify-center gap-2 ${currentUser.userType === UserType.CREATOR ? 'bg-blue-600 text-white shadow-blue-500/20' : 'bg-white dark:bg-white/5 text-gray-500 hover:text-blue-500'}`}
                >
                   <BuildingStorefrontIcon className="h-4 w-4" />
                   {currentUser.userType === UserType.CREATOR ? 'Voltar para Padrão' : 'Ativar Criador (Loja)'}
                </button>
            </div>
            <p className="text-[9px] text-gray-400 font-medium mt-4 text-center">
                Use estes botões para testar as funcionalidades de loja e administração sem precisar criar novas contas.
            </p>
        </div>

        <div className="mt-10 px-4">
           <button onClick={handleDeletePress} className="flex items-center gap-2 text-red-500 font-black uppercase text-[10px] tracking-widest hover:underline">
              <TrashIcon className="h-4 w-4" /> Remover Cadastro Permanente
           </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsPage;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  saveProducts,
  updateStore,
  getAffiliateSales,
  updateSaleStatus,
  findUserById,
  uploadFile,
  adminDeleteProduct,
  generateUUID,
  fulfillDropshippingOrder,
  updateSaleTracking,
  updateUserBalance,
  updateUser,
  saveStores
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  ArrowDownTrayIcon,
  PaintBrushIcon,
  ShoppingBagIcon,
  PhotoIcon,
  InformationCircleIcon,
  BookOpenIcon,
  VideoCameraIcon,
  AcademicCapIcon,
  TruckIcon,
  ClipboardDocumentListIcon,
  MapPinIcon,
  ClockIcon,
  CheckCircleIcon,
  CurrencyDollarIcon,
  QrCodeIcon
} from '@heroicons/react/24/solid';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [loading, setLoading] = useState(true);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [markup, setMarkup] = useState(2.0);

  const [trackingModal, setTrackingModal] = useState<{saleId: string} | null>(null);
  const [trackingCode, setTrackingCode] = useState('');
  const [supplierOrderId, setSupplierOrderId] = useState('');

  const loadData = async () => {
    setLoading(true);
    const stores = await getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      const allProds = await getProducts();
      setStoreProducts(allProds.filter(p => p.storeId === myStore.id));
      const allSales = await getAffiliateSales();
      setStoreSales(allSales.filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  const handleSaveBranding = async () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    await updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
        const url = await uploadFile(file, 'products');
        setPImg(url);
    } catch (err) {
        alert('Erro ao enviar imagem do produto.');
    } finally {
        setUploading(false);
    }
  };

  const handleCreateProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore || uploading) return;

    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    const currentProds = await getProducts();
    await saveProducts([...currentProds, newProduct]);
    setIsAddingProduct(false);
    setPImg(''); setPName(''); setPDesc(''); setPPrice('');
    loadData();
    alert('Produto criado com sucesso!');
  };

  const handleDeleteProduct = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir este produto?")) {
      await adminDeleteProduct(id);
      loadData();
    }
  };

  const handleFulfillOrder = async (sale: AffiliateSale) => {
    if (!sale.supplierCost) {
      alert("Custo do fornecedor não definido.");
      return;
    }

    if ((currentUser.balance || 0) < sale.supplierCost) {
      alert(`Saldo insuficiente para pagar o fornecedor ($${sale.supplierCost}). Recarregue sua carteira.`);
      return;
    }

    if (confirm(`Confirmar pagamento de $${sale.supplierCost} ao fornecedor para iniciar o despacho?`)) {
       const success = await fulfillDropshippingOrder(sale.id, currentUser.id, sale.supplierCost);
       if (success) {
         refreshUser(); 
         loadData();
         alert("Pedido enviado para processamento no fornecedor!");
       } else {
         alert("Erro ao processar pagamento.");
       }
    }
  };

  const handleAddTracking = async () => {
    if (!trackingModal || !trackingCode) return;
    await updateSaleStatus(trackingModal.saleId, OrderStatus.SHIPPING);
    await updateSaleTracking(trackingModal.saleId, trackingCode, supplierOrderId);
    setTrackingModal(null);
    setTrackingCode('');
    setSupplierOrderId('');
    loadData();
    alert("Código de rastreio atualizado!");
  }

  const handleSource = async () => {
    if (!searchQuery) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(searchQuery);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const handleImport = async (sourceProd: any) => {
    if (!userStore) return;
    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: sourceProd.name,
      description: sourceProd.description,
      price: sourceProd.originalPrice * markup,
      imageUrls: [sourceProd.imageUrl],
      affiliateCommissionRate: 0.1,
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: sourceProd.externalProviderId,
      originalPrice: sourceProd.originalPrice
    };
    const currentProds = await getProducts();
    await saveProducts([...currentProds, newProduct]);
    loadData();
    alert('Item importado para sua loja!');
  };

  const handleInstantUpgrade = async () => {
    setLoading(true);
    const newStoreId = generateUUID();
    const stores = await getStores();

    await saveStores([...stores, {
        id: newStoreId,
        professorId: currentUser.id,
        name: `Loja de ${currentUser.firstName}`,
        description: 'Minha loja oficial no CyBerPhone.',
        productIds: []
    }]);

    await updateUser({ 
        ...currentUser, 
        userType: UserType.CREATOR,
        storeId: newStoreId,
        credentials: 'Empreendedor Digital'
    });

    refreshUser();
    // Re-trigger load to ensure store state updates
    setTimeout(() => loadData(), 500);
  };

  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-32 text-center max-w-2xl animate-fade-in">
         <div className="bg-blue-600 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-8 shadow-2xl">
            <CheckBadgeIcon className="h-12 w-12 text-white" />
         </div>
         <h2 className="text-4xl font-black mb-6 tracking-tighter dark:text-white uppercase leading-none">Torne-se um Profissional <span className="text-blue-600">CyBer.</span></h2>
         <p className="text-gray-500 text-lg mb-10 leading-relaxed font-medium">Ganhe influência e suba de nível para desbloquear sua loja exclusiva e faturar com seu conhecimento ou revenda.</p>
         <button onClick={handleInstantUpgrade} disabled={loading} className="bg-blue-600 text-white px-12 py-5 rounded-2xl font-black uppercase text-sm shadow-xl active:scale-95 transition-all tracking-[0.2em] hover:bg-blue-700">
            {loading ? 'Processando Upgrade...' : 'Ativar Conta Profissional Agora'}
         </button>
      </div>
    );
  }

  if (loading) {
    return <div className="h-screen w-full flex items-center justify-center bg-gray-50 dark:bg-[#0a0c10]"><div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-600"></div></div>;
  }

  return (
    <div className="container mx-auto px-4 pt-24 pb-32 max-6xl animate-fade-in">

       <div className="flex flex-col md:flex-row items-center justify-between mb-12 gap-8">
          <div className="flex items-center gap-5">
            <div className="w-16 h-16 rounded-[1.5rem] shadow-xl flex items-center justify-center text-white" style={{ backgroundColor: brandColor }}>
              <CheckBadgeIcon className="h-10 w-10" />
            </div>
            <div>
              <h2 className="text-3xl font-black dark:text-white tracking-tighter uppercase">{brandName || 'Minha Vitrine'}</h2>
              <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">Painel Profissional <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span></p>
            </div>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] shadow-inner overflow-x-auto no-scrollbar max-w-full">
             {[
               { id: 'inventory', label: 'Produtos', icon: ArchiveBoxIcon },
               { id: 'orders', label: 'Vendas', icon: ClipboardDocumentListIcon },
               { id: 'sourcing', label: 'Revenda', icon: BoltIcon },
               { id: 'branding', label: 'Marca', icon: PaintBrushIcon }
             ].map(t => (
               <button 
                key={t.id} 
                onClick={() => setActiveTab(t.id as any)} 
                className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === t.id ? 'bg-white dark:bg-darkcard text-blue-600 shadow-lg' : 'text-gray-500'}`}
               >
                 <t.icon className="h-4 w-4" /> {t.label}
               </button>
             ))}
          </div>
       </div>

       {activeTab === 'inventory' && (
         <div className="space-y-8 animate-fade-in">
            <div className="flex justify-between items-center px-4">
               <h3 className="font-black text-xl dark:text-white uppercase tracking-tighter">Estoque Ativo</h3>
               <button onClick={() => setIsAddingProduct(true)} className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 active:scale-95 transition-all"><PlusIcon className="h-4 w-4 stroke-[4]" /> Adicionar Item</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
               {storeProducts.map(p => (
                 <div key={p.id} className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-sm group hover:shadow-2xl transition-all">
                    <img src={p.imageUrls[0]} className="h-48 w-full object-cover group-hover:scale-105 transition-transform duration-700" />
                    <div className="p-6">
                       <div className="flex items-center gap-2 mb-2">
                          <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${p.isDropshipping ? 'bg-purple-50 text-purple-600' : 'bg-blue-50 text-blue-600'}`}>
                             {p.isDropshipping ? 'Dropshipping' : p.type.replace('DIGITAL_', '')}
                          </span>
                       </div>
                       <h4 className="font-black text-sm dark:text-white uppercase truncate mb-1">{p.name}</h4>
                       <div className="mb-6">
                          <p className="text-2xl font-black text-blue-600">${p.price.toFixed(2)}</p>
                          {p.isDropshipping && <p className="text-[10px] font-bold text-gray-400">Custo: ${p.originalPrice?.toFixed(2)}</p>}
                       </div>
                       <div className="flex gap-2">
                          <button className="flex-1 bg-gray-50 dark:bg-white/5 text-gray-500 py-3 rounded-xl text-[10px] font-black uppercase">Editar</button>
                          <button onClick={() => handleDeleteProduct(p.id)} className="p-3 bg-red-50 text-red-500 dark:bg-red-900/10 rounded-xl hover:bg-red-600 hover:text-white transition-all"><TrashIcon className="h-4 w-4"/></button>
                       </div>
                    </div>
                 </div>
               ))}
            </div>
         </div>
       )}

       {activeTab === 'orders' && (
         <div className="space-y-6 animate-fade-in">
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] overflow-hidden border border-gray-100 dark:border-white/5 shadow-xl">
               <div className="p-6 border-b dark:border-white/5 bg-gray-50 dark:bg-white/5 flex items-center justify-between">
                  <h3 className="font-black text-sm uppercase tracking-widest text-gray-900 dark:text-white">Gerenciamento de Entregas</h3>
                  <span className="text-[10px] font-black text-blue-600 uppercase bg-blue-50 dark:bg-blue-900/20 px-3 py-1 rounded-full">{storeSales.length} Pedidos</span>
               </div>
               <div className="divide-y divide-gray-50 dark:divide-white/5">
                  {storeSales.length === 0 ? (
                    <div className="p-24 text-center text-gray-400 font-black uppercase text-xs tracking-widest">Aguardando sua primeira venda...</div>
                  ) : (
                    storeSales.map(sale => (
                         <div key={sale.id} className="p-6 md:p-8 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:bg-gray-50/50 dark:hover:bg-white/5 transition-colors">
                            <div className="flex-1 space-y-3 w-full">
                               <div className="flex justify-between">
                                  <p className="font-black text-xl text-gray-900 dark:text-white leading-tight">Venda #{sale.id.slice(-6)}</p>
                                  {sale.isDropshipping && <span className="bg-purple-100 text-purple-700 px-2 py-0.5 rounded text-[8px] font-black uppercase">Dropshipping</span>}
                               </div>
                               <div className="flex items-center gap-4">
                                  <p className="text-2xl font-black text-green-600">+${sale.saleAmount.toFixed(2)}</p>
                                  {sale.isDropshipping && sale.supplierCost && (
                                     <p className="text-sm font-bold text-red-400">- Custo: ${sale.supplierCost.toFixed(2)}</p>
                                  )}
                               </div>
                               <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${
                                   sale.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : 
                                   sale.status === OrderStatus.PROCESSING_SUPPLIER ? 'bg-purple-100 text-purple-600' :
                                   sale.status === OrderStatus.SHIPPING ? 'bg-blue-100 text-blue-600' : 
                                   'bg-orange-100 text-orange-600'
                               }`}>
                                     {sale.status === OrderStatus.WAITLIST ? 'Aguardando Processamento' : 
                                      sale.status === OrderStatus.PROCESSING_SUPPLIER ? 'Processando no Fornecedor' :
                                      sale.status === OrderStatus.SHIPPING ? 'Em Trânsito' : 'Entregue'}
                               </span>
                               {sale.trackingCode && <p className="text-[10px] text-gray-500 font-mono">Rastreio: {sale.trackingCode}</p>}
                            </div>

                            <div className="flex flex-wrap gap-2 shrink-0 justify-center">
                                  {/* Logica para Dropshipping */}
                                  {sale.isDropshipping && sale.status === OrderStatus.WAITLIST && (
                                     <button 
                                      onClick={() => handleFulfillOrder(sale)}
                                      className="bg-purple-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-purple-700 active:scale-95 transition-all"
                                     >
                                        <CurrencyDollarIcon className="h-5 w-5" /> Pagar Fornecedor
                                     </button>
                                  )}

                                  {/* Botão de Rastreio (para dropshipping que já foi pago ou produtos fisicos proprios) */}
                                  {((sale.isDropshipping && sale.status === OrderStatus.PROCESSING_SUPPLIER) || (!sale.isDropshipping && sale.status === OrderStatus.WAITLIST)) && (
                                     <button 
                                      onClick={() => setTrackingModal({saleId: sale.id})}
                                      className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black text-[10px] uppercase shadow-xl flex items-center gap-2 hover:bg-blue-700 active:scale-95 transition-all"
                                     >
                                        <TruckIcon className="h-5 w-5" /> Inserir Rastreio
                                     </button>
                                  )}

                                  {sale.status === OrderStatus.SHIPPING && (
                                     <div className="text-[10px] font-black text-gray-400 uppercase bg-gray-100 dark:bg-white/5 px-4 py-2 rounded-xl">
                                        Em Trânsito
                                     </div>
                                  )}
                            </div>
                         </div>
                    ))
                  )}
               </div>
            </div>
         </div>
       )}

       {activeTab === 'branding' && (
         <div className="max-w-4xl mx-auto space-y-10 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-10 rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-2xl font-black dark:text-white uppercase tracking-tight mb-10">Personalização de Marca</h3>
               <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome Comercial</label>
                        <input type="text" value={brandName} onChange={e => setBrandName(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white font-black outline-none border-2 border-transparent focus:border-blue-600" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Cor da Identidade</label>
                        <div className="flex gap-2">
                           {BRAND_COLORS.map(c => (
                             <button key={c.hex} onClick={() => setBrandColor(c.hex)} className={`w-11 h-11 rounded-full border-4 transition-all ${brandColor === c.hex ? 'border-white shadow-xl scale-110' : 'opacity-40 border-transparent'}`} style={{ backgroundColor: c.hex }}></button>
                           ))}
                        </div>
                     </div>
                  </div>
                  <textarea value={brandDesc} onChange={e => setBrandDesc(e.target.value)} className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white h-32 resize-none outline-none border-2 border-transparent focus:border-blue-600 font-medium" placeholder="Descreva o propósito da sua vitrine profissional..." />
                  <button onClick={handleSaveBranding} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-xl hover:bg-blue-700 transition-all tracking-[0.2em]">Salvar Identidade</button>
               </div>
            </div>
         </div>
       )}

       {activeTab === 'sourcing' && (
         <div className="space-y-8 animate-fade-in">
            <div className="bg-white dark:bg-darkcard p-6 md:p-10 rounded-[2.5rem] md:rounded-[3.5rem] shadow-2xl border border-gray-100 dark:border-white/5">
               <h3 className="text-xl md:text-2xl font-black dark:text-white uppercase tracking-tight mb-6 md:mb-8">Catálogo Global (AliExpress)</h3>
               <div className="flex flex-col sm:flex-row gap-4 mb-6">
                  <div className="flex-1 relative">
                    <MagnifyingGlassIcon className="h-5 w-5 md:h-6 md:w-6 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                    <input type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} placeholder="Pesquisar produtos (ex: Smartwatch, Drone)..." className="w-full pl-11 md:pl-12 pr-6 py-4 md:py-5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-black dark:text-white border-2 border-transparent focus:border-orange-500 text-sm" />
                  </div>
                  <div className="w-full sm:w-40">
                     <div className="relative h-full">
                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-gray-400 uppercase">Markup</span>
                        <input type="number" step="0.1" value={markup} onChange={e => setMarkup(parseFloat(e.target.value))} className="w-full pl-16 pr-4 py-4 md:py-5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-black dark:text-white text-sm text-center" />
                     </div>
                  </div>
                  <button onClick={handleSource} disabled={isSourcing} className="bg-orange-500 text-white px-8 md:px-10 py-4 md:py-5 rounded-2xl font-black uppercase text-[10px] md:text-xs shadow-xl disabled:opacity-50 transition-all active:scale-95">{isSourcing ? 'Buscando...' : 'Buscar'}</button>
               </div>
            </div>
            {sourcingResults.length > 0 && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8">
                {sourcingResults.map((res, i) => (
                  <div key={i} className="bg-white dark:bg-darkcard rounded-[2.5rem] md:rounded-[3rem] p-5 md:p-8 flex flex-col md:flex-row gap-6 md:gap-8 border border-gray-100 dark:border-white/5 shadow-md group transition-all hover:shadow-xl">
                     <div className="w-full md:w-44 h-48 md:h-44 shrink-0 rounded-[1.8rem] md:rounded-[2rem] overflow-hidden shadow-lg">
                        <img src={res.imageUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                     </div>
                     <div className="flex-1 flex flex-col justify-center">
                        <h4 className="font-black text-base md:text-lg dark:text-white mb-2 uppercase line-clamp-1">{res.name}</h4>
                        <div className="mb-4 text-xs text-gray-500 line-clamp-2">{res.description}</div>

                        <div className="grid grid-cols-2 gap-4 mb-4 bg-gray-50 dark:bg-white/5 p-3 rounded-xl">
                           <div>
                              <p className="text-[8px] font-black text-gray-400 uppercase">Custo</p>
                              <p className="font-black text-gray-700 dark:text-gray-300">${res.originalPrice.toFixed(2)}</p>
                           </div>
                           <div>
                              <p className="text-[8px] font-black text-gray-400 uppercase">Venda ({markup}x)</p>
                              <p className="font-black text-orange-600 text-lg">${(res.originalPrice * markup).toFixed(2)}</p>
                           </div>
                        </div>

                        <button onClick={() => handleImport(res)} className="w-full bg-black dark:bg-white dark:text-black text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg active:scale-95 transition-all">Importar para Loja</button>
                     </div>
                  </div>
                ))}
              </div>
            )}
         </div>
       )}

       {isAddingProduct && (
         <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setIsAddingProduct(false)}>
            <div 
              className="bg-white dark:bg-darkcard w-full max-w-2xl rounded-3xl md:rounded-[3rem] p-6 md:p-10 shadow-2xl relative border border-white/10 max-h-[90vh] overflow-y-auto no-scrollbar" 
              onClick={e => e.stopPropagation()}
            >
               <button onClick={() => setIsAddingProduct(false)} className="absolute top-6 right-6 p-2 bg-gray-50 dark:bg-white/5 rounded-full text-gray-400 hover:text-red-500 transition-all">
                    <XMarkIcon className="h-6 w-6" />
               </button>
               <h3 className="text-xl md:text-2xl font-black dark:text-white uppercase tracking-tight mb-10">Novo Item Próprio</h3>
               <form onSubmit={handleCreateProduct} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Nome</label>
                        <input type="text" required value={pName} onChange={e => setPName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold text-sm" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Preço</label>
                        <input type="number" required value={pPrice} onChange={e => setPPrice(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold text-sm" />
                     </div>
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Tipo</label>
                     <select value={pType} onChange={e => setPType(e.target.value as ProductType)} className="w-full p-4 bg-gray-50 dark:bg-white/5 dark:text-white rounded-2xl outline-none font-bold text-sm cursor-pointer">
                        <option value={ProductType.DIGITAL_COURSE}>Curso Digital</option>
                        <option value={ProductType.DIGITAL_EBOOK}>E-book</option>
                        <option value={ProductType.PHYSICAL}>Produto Físico</option>
                     </select>
                  </div>
                  <div className="space-y-2">
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Foto</label>
                     <div onClick={() => fileInputRef.current?.click()} className={`w-full h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center cursor-pointer transition-all ${pImg ? 'border-green-500' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}>
                        {uploading ? <div className="w-6 h-6 border-2 border-blue-600 border-t-transparent animate-spin rounded-full"></div> : pImg ? <div className="text-green-600 font-bold text-xs">Imagem Carregada</div> : <PhotoIcon className="h-8 w-8 text-gray-300" />}
                        <input type="file" ref={fileInputRef} onChange={handleImageUpload} accept="image/*" className="hidden" />
                     </div>
                  </div>
                  {pType !== ProductType.PHYSICAL && (
                    <input type="url" value={pDigitalUrl} onChange={e => setPDigitalUrl(e.target.value)} className="w-full p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl outline-none font-bold text-blue-600 text-sm" placeholder="Link de Download" />
                  )}
                  <button type="submit" disabled={uploading} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-sm uppercase shadow-2xl hover:bg-blue-700 tracking-[0.2em] transition-all active:scale-95 disabled:opacity-50">Publicar Agora</button>
               </form>
            </div>
         </div>
       )}

       {trackingModal && (
         <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[150] flex items-center justify-center p-4 animate-fade-in" onClick={() => setTrackingModal(null)}>
            <div className="bg-white dark:bg-darkcard w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl relative border border-white/10" onClick={e => e.stopPropagation()}>
               <h3 className="text-xl font-black dark:text-white uppercase tracking-tight mb-6">Dados de Envio</h3>
               <div className="space-y-4">
                  <div>
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Código de Rastreio</label>
                     <input type="text" value={trackingCode} onChange={e => setTrackingCode(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl font-bold dark:text-white outline-none" placeholder="Ex: LB123456789HK" />
                  </div>
                  <div>
                     <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">ID do Pedido no Fornecedor</label>
                     <input type="text" value={supplierOrderId} onChange={e => setSupplierOrderId(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl font-bold dark:text-white outline-none" placeholder="Opcional" />
                  </div>
                  <button onClick={handleAddTracking} className="w-full py-4 bg-green-600 text-white rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Confirmar Envio</button>
               </div>
            </div>
         </div>
       )}
    </div>
  );
};

export default StoreManagerPage;

