export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const sales = getLocalList<AffiliateSale>(KEYS.SALES);
    const sale = sales.find(s => s.id === saleId);
    if(sale) {
        sale.isRated = true;
        saveLocalList(KEYS.SALES, sales);

        const products = getLocalList<Product>(KEYS.PRODUCTS);
        const prod = products.find(p => p.id === sale.productId);
        if(prod) {
            prod.ratings.push({ id: generateUUID(), saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() });
            prod.ratingCount = prod.ratings.length;
            prod.averageRating = prod.ratings.reduce((a, b) => a + b.rating, 0) / prod.ratingCount;
            saveLocalList(KEYS.PRODUCTS, products);

            // Sync BD
            try {
                await supabase.from('affiliate_sales').update({ is_rated: true }).eq('id', saleId);
                await supabase.from('products').update({ ratings: prod.ratings, average_rating: prod.averageRating, rating_count: prod.ratingCount }).eq('id', prod.id);
            } catch(e) {}
        }
    }
};

