export const updateCartItemQuantity = (pId: string, q: number) => {
    let cart = getCart();
    if(q <= 0) cart = cart.filter(i => i.productId !== pId);
    else { const i = cart.find(x => x.productId === pId); if(i) i.quantity = q; }
    saveCart(cart);
};
