            link: row.link,
            productName: row.products?.name || 'Item Removido',
            productImage: row.products?.image_urls?.[0] || '',
            commissionRate: row.products?.affiliate_commission_rate || 0,
            timestamp: Number(row.timestamp)
        }));
    } catch(e) {}
    return [];
};

