        chat.messages.push(msg);
        saveLocalList(KEYS.CHATS, chats);

        // Notificações
        chat.participants.forEach(pid => {
            if(pid !== msg.senderId) {
                createNotification({ 
                    type: chat.type === ChatType.GROUP ? NotificationType.GROUP_POST : NotificationType.MESSAGE, 
                    recipientId: pid, 
                    actorId: msg.senderId, 
                    groupName: chat.groupName, 
                    timestamp: Date.now() 
                });
            }
        });

        try {
            await supabase.from('chats').update({ messages: chat.messages }).eq('id', chatId);
        } catch(e) {}
    }
};

