export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme?: string) => {
    const newChat: ChatConversation = {
        id: generateUUID(),
        type: ChatType.GROUP,
        participants: [...members, adminId],
        messages: [],
        groupName: name,
        adminId,
        description,
        theme: theme as GroupTheme,
        isPublic: false
    };

    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    saveLocalList(KEYS.CHATS, [...chats, newChat]);

    if (isSupabaseConfigured) {
      try {
          await supabase.from('chats').insert({
              id: newChat.id,
              type: newChat.type,
              participants: newChat.participants,
              group_name: newChat.groupName,
              admin_id: newChat.adminId,
              description: newChat.description,
              theme: newChat.theme,
              messages: []
          });
      } catch(e) {}
    }

    return newChat;
};

export const sendMessage = async (chatId: string, msg: Message) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages.push(msg);
        saveLocalList(KEYS.CHATS, chats);

        // Notificações
        chat.participants.forEach(pid => {
            if(pid !== msg.senderId) {
                createNotification({ 
                    type: chat.type === ChatType.GROUP ? NotificationType.GROUP_POST : NotificationType.MESSAGE, 
                    recipientId: pid, 
                    actorId: msg.senderId, 
                    groupName: chat.groupName, 
                    timestamp: Date.now() 
                });
            }
        });

        if (isSupabaseConfigured) {
          try {
              await supabase.from('chats').update({ messages: chat.messages }).eq('id', chatId);
          } catch(e) {}
        }
    }
};

export const joinGroup = async (groupId: string, userId: string) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === groupId);
    if(chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        saveLocalList(KEYS.CHATS, chats);
        if (isSupabaseConfigured) {
          try { await supabase.from('chats').update({ participants: chat.participants }).eq('id', groupId); } catch(e) {}
        }
    }
};

export const updateGroupTheme = async (groupId: string, theme: string) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === groupId);
    if(chat) {
        chat.theme = theme as GroupTheme;
        saveLocalList(KEYS.CHATS, chats);
        if (isSupabaseConfigured) {
          try { await supabase.from('chats').update({ theme }).eq('id', groupId); } catch(e) {}
        }
    }
};

