export const createGroup = async (name: string, members: string[], adminId: string, description?: string, theme?: string, imageFile?: File, isPublic: boolean = false) => {
    const newChat: ChatConversation = {
        id: generateUUID(),
        type: ChatType.GROUP,
        participants: [...members, adminId], // Admin is auto-added
        messages: [],
        groupName: name,
        adminId,
        description,
        theme: theme as GroupTheme,
        isPublic: isPublic
    };

    // Upload Image if present
    if (imageFile) {
        try {
            const imageUrl = await uploadFile(imageFile, 'groups');
            newChat.groupImage = imageUrl;
        } catch (e) {
            console.warn("Falha ao fazer upload da imagem do grupo", e);
        }
    }

    // Save to LocalStorage
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    saveLocalList(KEYS.CHATS, [...chats, newChat]);

    // Persist to Supabase
    if (isSupabaseConfigured) {
      try {
          await supabase.from('chats').insert({
              id: newChat.id,
              type: newChat.type,
              participants: newChat.participants,
              group_name: newChat.groupName,
              group_image: newChat.groupImage,
              admin_id: newChat.adminId,
              description: newChat.description,
              theme: newChat.theme,
              is_public: newChat.isPublic,
              messages: []
          });
      } catch(e) {
          console.error("Erro ao criar grupo no Supabase", e);
          throw e;
      }
    }

    return newChat;
};

export const sendMessage = async (chatId: string, msg: Message) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages.push(msg);
        saveLocalList(KEYS.CHATS, chats);

        // Notificações
        chat.participants.forEach(pid => {
            if(pid !== msg.senderId) {
                createNotification({ 
                    type: chat.type === ChatType.GROUP ? NotificationType.GROUP_POST : NotificationType.MESSAGE, 
                    recipientId: pid, 
                    actorId: msg.senderId, 
                    groupName: chat.groupName, 
                    timestamp: Date.now() 
                });
            }
        });

        if (isSupabaseConfigured) {
          try {
              await supabase.from('chats').update({ messages: chat.messages }).eq('id', chatId);
          } catch(e) {}
        }
    }
};

export const joinGroup = async (groupId: string, userId: string) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === groupId);

    // Local Update
    if(chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        saveLocalList(KEYS.CHATS, chats);
    }

    // DB Update
    if (isSupabaseConfigured) {
        // Fetch fresh data first to avoid overwriting
        try {
            const { data: remoteChat } = await supabase.from('chats').select('participants').eq('id', groupId).single();
            if (remoteChat) {
                const currentParticipants = remoteChat.participants || [];
                if (!currentParticipants.includes(userId)) {
                    await supabase.from('chats').update({ 
                        participants: [...currentParticipants, userId] 
                    }).eq('id', groupId);
                }
            }
        } catch(e) {}
    }
};

export const updateGroupTheme = async (groupId: string, theme: string) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === groupId);
    if(chat) {
        chat.theme = theme as GroupTheme;
        saveLocalList(KEYS.CHATS, chats);
        if (isSupabaseConfigured) {
          try { await supabase.from('chats').update({ theme }).eq('id', groupId); } catch(e) {}
        }
    }
};

