    if(story) {
        const newItem = { ...item, id: generateUUID(), timestamp: Date.now() };
        story.items.push(newItem);
        saveLocalList(KEYS.STORIES, stories);

        // Sync BD (Upsert)
        if (isSupabaseConfigured) {
