      const allUsers = await getUsers();
      // Sugere seguidores ou todos os usuários (dependendo da lógica desejada, aqui focamos em seguidores para ser mais "rede social")
      const myFollowers = allUsers.filter(u => u.id !== currentUser.id);
      setFollowers(myFollowers);
    };
    loadFollowers();
  }, [currentUser.id]);

  const filteredFollowers = useMemo(() => {
    return followers.filter(f => 
      `${f.firstName} ${f.lastName}`.toLowerCase().includes(searchTerm.toLowerCase()) ||
      f.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [followers, searchTerm]);

  const toggleMember = (id: string) => {
    if (selectedMembers.includes(id)) {
      setSelectedMembers(selectedMembers.filter(m => m !== id));
    } else {
      setSelectedMembers([...selectedMembers, id]);
    }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setGroupImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setGroupImagePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleCreate = async () => {
    if (!groupName.trim()) {
      alert("Defina um nome para o grupo.");
      return;
