                     value={searchTerm}
                     onChange={e => setSearchTerm(e.target.value)}
                     placeholder="Buscar pessoas..."
                     className="w-full pl-10 pr-4 py-3 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white"
                   />
