import React, { useState, useEffect, useCallback } from 'react';
import { Story } from '../types';
import { XMarkIcon, ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/solid';

interface StoryViewerModalProps {
  stories: Story[];
  initialIndex: number;
  onClose: () => void;
}

const STORY_DURATION = 5000;

const StoryViewerModal: React.FC<StoryViewerModalProps> = ({ stories, initialIndex, onClose }) => {
  const [currentUserIdx, setCurrentUserIdx] = useState(initialIndex);
  const [currentItemIdx, setCurrentItemIdx] = useState(0);
  const [progress, setProgress] = useState(0);

  const currentStory = stories[currentUserIdx];
  const currentItem = currentStory?.items?.[currentItemIdx];

  const handleNext = useCallback(() => {
    if (!currentStory || !currentStory.items) { onClose(); return; }

    if (currentItemIdx < currentStory.items.length - 1) {
      setCurrentItemIdx(prev => prev + 1);
      setProgress(0);
    } else if (currentUserIdx < stories.length - 1) {
      setCurrentUserIdx(prev => prev + 1);
      setCurrentItemIdx(0);
      setProgress(0);
    } else {
      onClose();
    }
  }, [currentItemIdx, currentUserIdx, currentStory, stories.length, onClose]);

  const handlePrev = useCallback(() => {
    if (currentItemIdx > 0) {
      setCurrentItemIdx(prev => prev - 1);
      setProgress(0);
    } else if (currentUserIdx > 0) {
      const prevStory = stories[currentUserIdx - 1];
      setCurrentUserIdx(prev => prev - 1);
      setCurrentItemIdx(prevStory?.items?.length ? prevStory.items.length - 1 : 0);
      setProgress(0);
    }
  }, [currentItemIdx, currentUserIdx, stories]);

  useEffect(() => {
    const timer = setInterval(() => {
      setProgress(prev => {
        if (prev >= 100) {
          handleNext();
          return 0;
        }
        return prev + (100 / (STORY_DURATION / 100));
      });
    }, 100);

    return () => clearInterval(timer);
  }, [handleNext, currentStory]); // Add currentStory dependency to reset if story changes

  if (!currentStory || !currentItem) return null;

  return (
    <div className="fixed inset-0 z-[1000] bg-black flex items-center justify-center animate-fade-in">
      <div className="relative w-full h-full md:max-w-[450px] md:h-[90vh] md:rounded-[2rem] overflow-hidden bg-gray-900 flex flex-col shadow-2xl border border-white/10">

