        <div className="absolute top-4 left-3 right-3 flex gap-1 z-30">
          {currentStory.items?.map((_, idx) => (
            <div key={idx} className="h-0.5 flex-1 bg-white/30 rounded-full overflow-hidden">
               <div 
                 className="h-full bg-white transition-all duration-100 ease-linear"
                 style={{ 
                   width: idx === currentItemIdx ? `${progress}%` : idx < currentItemIdx ? '100%' : '0%' 
                 }}
               />
            </div>
          ))}
        </div>

        {/* Header (User Info) */}
        <div className="absolute top-8 left-4 right-4 flex items-center justify-between z-30">
           <div className="flex items-center gap-3">
              <img src={currentStory.userProfilePic} className="w-9 h-9 rounded-full border border-white/50 object-cover shadow-sm" />
              <div className="flex flex-col">
                 <span className="font-bold text-white text-xs drop-shadow-md">{currentStory.userName}</span>
                 <span className="text-[9px] text-white/80 font-medium">
                    {new Date(currentItem.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                 </span>
              </div>
           </div>
           <button onClick={onClose} className="p-2 text-white/80 hover:text-white transition-colors">
              <XMarkIcon className="h-6 w-6" />
           </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 flex items-center justify-center overflow-hidden bg-black relative">
           {currentItem.imageUrl ? (
              <img src={currentItem.imageUrl} className="w-full h-full object-contain" alt="Story" />
           ) : (
              <div className={`w-full h-full flex flex-col items-center justify-center text-center p-8 transition-colors duration-500 ${currentItem.backgroundColor || 'bg-blue-600'}`}>
                 <p className={`font-black leading-tight break-words max-w-full ${currentItem.textColor || 'text-white'} ${currentItem.fontFamily || 'font-sans'} ${currentItem.text && currentItem.text.length > 60 ? 'text-xl' : 'text-3xl'}`}>
                   {currentItem.text}
                 </p>
              </div>
           )}
        </div>

        {/* Tap Areas for Navigation */}
        <div className="absolute inset-0 z-20 flex">
           <div className="w-1/3 h-full cursor-pointer" onClick={handlePrev}></div>
           <div className="w-2/3 h-full cursor-pointer" onClick={handleNext}></div>
        </div>

        {/* Optional Desktop Arrows (Outside the phone frame) */}
        <button 
          onClick={handlePrev} 
          className="hidden md:flex absolute -left-16 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white z-50 transition-all"
        >
           <ChevronLeftIcon className="h-6 w-6" />
        </button>
        <button 
          onClick={handleNext} 
          className="hidden md:flex absolute -right-16 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/20 rounded-full text-white z-50 transition-all"
        >
           <ChevronRightIcon className="h-6 w-6" />
        </button>
      </div>
    </div>
  );
