  if (isSupabaseConfigured) {
    const { data } = await supabase.from('posts').select('comments').eq('id', postId).single();
    const currentComments = data?.comments || [];
    await supabase.from('posts').update({ comments: [...currentComments, comment] }).eq('id', postId);
  }

  const posts = getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments = post.comments || [];
    post.comments.push(comment);
    saveLocalList(KEYS.POSTS, posts);
  }
};

