  if (isSupabaseConfigured) {
    const { data } = await supabase.from('chats').select('participants').eq('id', groupId).single();
    const parts = data?.participants || [];
    if (!parts.includes(userId)) {
      await supabase.from('chats').update({ participants: [...parts, userId] }).eq('id', groupId);
    }
  }
  const chats = getLocalList<ChatConversation>(KEYS.CHATS);
  const chat = chats.find(c => c.id === groupId);
  if (chat && !chat.participants.includes(userId)) {
    chat.participants.push(userId);
    saveLocalList(KEYS.CHATS, chats);
  }
};

