const ProfilePage: React.FC<ProfilePageProps> = ({ currentUser, onNavigate, refreshUser, userId, onOpenWallet }) => {
  const profileId = userId || currentUser.id;

  // STATE INICIAL INTELIGENTE: Usa o currentUser se for o próprio perfil
  // Isso evita "Usuário não encontrado" em caso de lag de rede ou falha no fetch
  const [profile, setProfile] = useState<User | null>(() => {
    if (!userId || userId === currentUser.id) return currentUser;
    return null;
  });

  const [activeTab, setActiveTab] = useState<'posts' | 'about' | 'store' | 'ads'>('posts');
