    const fetchData = async () => {
      setLoading(true);

      // Tenta buscar dados mais recentes do perfil
      const u = await findUserById(profileId);
      if (u) {
        setProfile(u);
      } else if (!profile && profileId === currentUser.id) {
        // Fallback de segurança: se a busca falhar e for o próprio usuário, garante que não fica null
        setProfile(currentUser);
      }

      const allPosts = await getPosts();
      setUserPosts(allPosts.filter(p => p.userId === profileId).sort((a, b) => b.timestamp - a.timestamp));

      const allAds = await getAds();
      setUserAds(allAds.filter(a => a.professorId === profileId));

      setLoading(false);
    };
