import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { User, UserType, Product, Store, ProductType } from '../types';
import {
  getStores,
  findStoreById,
  findUserById,
  getProducts,
  saveAffiliateLink,
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { ShoppingCartIcon, CheckIcon, PlusIcon, StarIcon, ShoppingBagIcon, MagnifyingGlassIcon, FunnelIcon, Squares2X2Icon, BookOpenIcon, VideoCameraIcon, AcademicCapIcon, TruckIcon, LinkIcon, ChevronDownIcon, BoltIcon, BuildingStorefrontIcon, RocketLaunchIcon } from '@heroicons/react/24/outline';
import { StarIcon as StarIconSolid } from '@heroicons/react/24/solid';
import ProductDetailModal from './ProductDetailModal';

interface StorePageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
  storeId?: string;
  onAddToCart: (productId: string, quantity: number, selectedColor?: string) => void;
  onOpenCart: () => void;
}

const ProductCard: React.FC<{ 
  product: Product; 
  currentUser: User;
  brandColor?: string;
  onSelect: (p: Product) => void; 
  onAddToCart: (productId: string, quantity: number, selectedColor?: string) => void;
  onOpenCart: () => void;
}> = ({ product, currentUser, brandColor = '#2563eb', onSelect, onAddToCart, onOpenCart }) => {
  const [isAdded, setIsAdded] = useState(false);
  const [isLinkGenerated, setIsLinkGenerated] = useState(false);

  const handleAdd = (e: React.MouseEvent) => {
    e.stopPropagation();
    onAddToCart(product.id, 1);
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 2000);
  };

  const handleBuyNow = (e: React.MouseEvent) => {
    e.stopPropagation();
    onAddToCart(product.id, 1);
    onOpenCart();
  };

  const handleGenerateAffiliateLink = (e: React.MouseEvent) => {
    e.stopPropagation();
    const affiliateLink = `${window.location.origin}?page=store&storeId=${product.storeId}&productId=${product.id}&affiliateId=${currentUser.id}`;
    saveAffiliateLink(currentUser.id, product.id, affiliateLink);
    navigator.clipboard.writeText(affiliateLink);
