export const toggleJoinEvent = async (eId: string, uId: string) => {
    if(isSupabaseConfigured) {
       const { data } = await supabase.from('events').select('attendees').eq('id', eId).single();
       let att = data?.attendees || [];
       if(att.includes(uId)) att = att.filter((id: string) => id !== uId);
       else att.push(uId);
       await supabase.from('events').update({ attendees: att }).eq('id', eId);
    } else {
      const evts = getLocalList<CyberEvent>(KEYS.EVENTS);
      const evt = evts.find(e => e.id === eId);
      if(evt) {
          if(evt.attendees.includes(uId)) evt.attendees = evt.attendees.filter(id => id !== uId);
          else evt.attendees.push(uId);
          saveLocalList(KEYS.EVENTS, evts);
      }
    }
};

export const getCart = (): CartItem[] => {
  return getLocalList(KEYS.CART);
};
export const saveCart = (cart: CartItem[]) => {
  saveLocalList(KEYS.CART, cart);
};
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if(existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const updateCartItemQuantity = (pid: string, qty: number) => {
    let cart = getCart();
    if (qty <= 0) cart = cart.filter(i => i.productId !== pid);
    else {
        const item = cart.find(i => i.productId === pid);
        if(item) item.quantity = qty;
    }
    saveCart(cart);
};
export const removeFromCart = (pid: string) => {
    saveCart(getCart().filter(i => i.productId !== pid));
};

export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
    if(isSupabaseConfigured) {
        const { data, error } = await supabase.from('notifications').select('*').eq('recipient_id', userId);
        if (error) return [];
        return data?.map(n => ({
            id: n.id,
            recipientId: n.recipient_id,
            actorId: n.actor_id,
            type: n.type as NotificationType,
            postId: n.post_id,
            isRead: n.is_read,
            timestamp: Number(n.timestamp),
            groupName: n.group_name
        })) || [];
    }
    return getLocalList<Notification>(KEYS.NOTIFICATIONS).filter(n => n.recipientId === userId);
};

export const markNotificationsAsRead = async (userId: string) => {
    if(isSupabaseConfigured) {
        await supabase.from('notifications').update({ is_read: true }).eq('recipient_id', userId);
    } else {
      const notifs = getLocalList<Notification>(KEYS.NOTIFICATIONS);
      notifs.forEach(n => { if(n.recipientId === userId) n.isRead = true; });
      saveLocalList(KEYS.NOTIFICATIONS, notifs);
    }
};

