export const updatePostSaves = async (pid: string, uid: string) => {
    if(isSupabaseConfigured) {
       // Logic to sync saves needed (e.g. specialized RPC or array update)
       // Using simple array update for now
       const { data } = await supabase.from('posts').select('saves').eq('id', pid).single();
       let saves = data?.saves || [];
       if(saves.includes(uid)) saves = saves.filter((x: string) => x !== uid);
       else saves.push(uid);
       await supabase.from('posts').update({ saves }).eq('id', pid);
    } else {
      const posts = getLocalList<Post>(KEYS.POSTS);
      const p = posts.find(x => x.id === pid);
      if(p) {
          if(p.saves.includes(uid)) p.saves = p.saves.filter(x => x !== uid);
          else p.saves.push(uid);
          saveLocalList(KEYS.POSTS, posts);
      }
    }
};

