                               <p className="text-sm dark:text-gray-200 font-medium leading-relaxed">{c.text}</p>
                            </div>
                         </div>
                      </div>
                    ))}
                    <div ref={commentsEndRef} />
                  </div>
                )}
             </div>
          </div>

          <div className="p-6 bg-white dark:bg-[#0a0c10] border-t border-gray-100 dark:border-white/10 z-[105] shadow-[0_-10px_30px_rgba(0,0,0,0.05)] shrink-0">
             <form onSubmit={handleSendComment} className="max-w-4xl mx-auto flex items-end gap-3 bg-gray-50 dark:bg-white/5 p-3 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-inner group focus-within:border-blue-500/50 transition-all">
                <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-xl object-cover hidden sm:block border-2 border-white shadow-sm" />
                <div className="flex-1 flex items-center gap-3">
                   <textarea 
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                    placeholder="Adicionar um comentário..."
                    className="w-full bg-transparent dark:text-white outline-none resize-none text-sm placeholder-gray-400 py-3 font-bold custom-scrollbar max-h-24"
                    rows={1}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${target.scrollHeight}px`;
                    }}
                   />
                   <button 
                     type="submit" 
                     disabled={!commentText.trim()}
                     className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 text-white p-3.5 rounded-2xl shadow-xl shadow-blue-500/20 active:scale-90 transition-all shrink-0"
                   >
                     <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                   </button>
                </div>
             </form>
             <div className="h-2 md:hidden"></div>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

