                       <div className="relative">
                          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 font-bold">$</span>
                          <input 
                            type="number" 
                            value={livePrice}
                            onChange={e => setLivePrice(e.target.value)}
                            className="w-full pl-8 pr-4 py-4 bg-white dark:bg-white/5 rounded-2xl outline-none border-2 border-green-500 font-black text-lg dark:text-white transition-all shadow-sm"
                          />
                       </div>
                    </div>
                 )}
              </div>
           </div>
        )}

        {/* REELS AREA */}
        {postType === PostType.REEL && (
           <div className="space-y-4">
              {!reelUrl ? (
                 <div className="grid grid-cols-2 gap-4 h-64">
                    <button 
                      type="button"
                      onClick={() => setShowRecordModal(true)}
                      className="bg-gray-900 text-white rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-800 transition-all group border-2 border-gray-800 hover:border-blue-500"
                    >
                       <div className="p-4 bg-red-600 rounded-full group-hover:scale-110 transition-transform shadow-lg shadow-red-900/50">
                          <CameraIcon className="h-8 w-8 text-white" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Gravar Agora</span>
                    </button>

                    <button 
                      type="button"
                      onClick={() => videoInputRef.current?.click()}
                      className="bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-300 rounded-[2rem] flex flex-col items-center justify-center gap-3 hover:bg-gray-100 dark:hover:bg-white/10 transition-all border-2 border-dashed border-gray-200 dark:border-white/10 hover:border-blue-500"
                    >
                       <div className="p-4 bg-white dark:bg-white/10 rounded-full group-hover:scale-110 transition-transform">
                          <VideoCameraIcon className="h-8 w-8 text-blue-500" />
                       </div>
                       <span className="font-black text-xs uppercase tracking-widest">Upload Vídeo</span>
                       <input type="file" ref={videoInputRef} onChange={handleVideoFileSelect} accept="video/*" className="hidden" />
                    </button>
                 </div>
              ) : (
                 <div className="relative rounded-[2rem] overflow-hidden bg-black aspect-[9/16] max-h-[500px] mx-auto w-full max-w-xs shadow-2xl">
                    <video src={reelUrl} controls className="w-full h-full object-cover" />
                    <button 
                      type="button" 
                      onClick={() => { setReelUrl(''); setReelFile(null); setReelMeta({}); }}
                      className="absolute top-4 right-4 bg-black/60 text-white p-2 rounded-full hover:bg-red-600 transition-colors backdrop-blur-md"
                    >
                       <XMarkIcon className="h-5 w-5" />
                    </button>
                 </div>
              )}

              <textarea 
               value={content} 
               onChange={e => setContent(e.target.value)} 
               className="w-full p-4 bg-transparent outline-none text-gray-900 dark:text-white font-medium placeholder-gray-400" 
               placeholder="Descreva seu Reel..." 
               rows={2}
             />
           </div>
        )}

        {/* BARRA DE FERRAMENTAS INFERIOR */}
        <div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-white/5">
           <div className="flex gap-2">
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.TEXT); setShowStyleTools(!showStyleTools); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.TEXT && showStyleTools ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Estilo de Texto"
              >
                 <FontIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => { setPostType(PostType.IMAGE); setTimeout(() => imageInputRef.current?.click(), 100); }}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.IMAGE ? 'bg-green-100 dark:bg-green-900/30 text-green-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Adicionar Foto"
              >
                 <PhotoIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => setPostType(PostType.REEL)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.REEL ? 'bg-purple-100 dark:bg-purple-900/30 text-purple-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Reel"
              >
                 <FilmIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                onClick={() => setPostType(PostType.LIVE)}
                className={`p-2.5 rounded-xl transition-all ${postType === PostType.LIVE ? 'bg-red-100 dark:bg-red-900/30 text-red-600' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}
                title="Criar Live"
              >
                 <SignalIcon className="h-6 w-6" />
              </button>
              <button 
                type="button" 
                className="p-2.5 rounded-xl text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-yellow-500 transition-all hidden sm:block"
              >
                 <FaceSmileIcon className="h-6 w-6" />
              </button>
           </div>

           <button 
             type="submit" 
             disabled={loading || (postType !== PostType.LIVE && !content && !imageFile && !reelFile) || (postType === PostType.LIVE && !liveTitle)} 
             className="bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white px-8 py-3 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all flex items-center gap-2 min-w-[140px] justify-center"
           >
             {loading ? <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> {statusText}</> : <><PaperAirplaneIcon className="h-4 w-4 -rotate-45" /> Publicar</>}
           </button>
        </div>
      </form>

      {showRecordModal && (
        <RecordReelModal 
          onClose={() => setShowRecordModal(false)} 
          onSave={handleRecordedReel} 
        />
      )}
    </div>
  );
};

export default CreatePost;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Message } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  XMarkIcon,
  HandRaisedIcon,
  SignalIcon,
  UsersIcon,
  ComputerDesktopIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  PlayIcon,
  HeartIcon,
  FaceSmileIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedIconOutline,
  ChatBubbleLeftRightIcon as ChatIconOutline,
  ComputerDesktopIcon as ScreenIconOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const RANDOM_COMMENTS = [
  "Incrível! 👏👏", "Show de bola!", "Manda um salve!", "Muito bom o conteúdo", 
  "Aula top demais 🚀", "Aprendendo muito", "Isso aí!", "Grande mestre!", "👏👏👏", 
  "Adorei a explicação", "Qual o próximo tema?", "Compartilhei aqui!", "Boa noite galera"
];

const RANDOM_NAMES = ["Carlos", "Ana", "Pedro", "Julia", "Marcos", "Beatriz", "Lucas", "Fernanda"];

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Chat & Reactions States
  const [chatMessages, setChatMessages] = useState<{id: string, name: string, text: string, isMe?: boolean}[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(1200);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
  }, []);

  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // Simulation Effect (Chat, Hearts, Viewers)
  useEffect(() => {
    const interval = setInterval(() => {
      // Random Hearts
      if (Math.random() > 0.6) {
        addFloatingHeart(false);
      }

      // Random Viewer Count Fluctuation
      if (Math.random() > 0.5) {
        setViewerCount(prev => prev + Math.floor(Math.random() * 5) - 2);
      }

      // Random Chat Message
      if (Math.random() > 0.7) {
        const text = RANDOM_COMMENTS[Math.floor(Math.random() * RANDOM_COMMENTS.length)];
        const name = RANDOM_NAMES[Math.floor(Math.random() * RANDOM_NAMES.length)];
        setChatMessages(prev => [...prev.slice(-10), { 
          id: Date.now().toString() + Math.random(), 
          name, 
          text 
        }]);
      }
    }, 800);

    return () => clearInterval(interval);
  }, []);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) { alert("Microfone indisponível."); }
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

      // Donation Special Effect
      for(let i=0; i<10; i++) setTimeout(() => addFloatingHeart(false, 'text-yellow-400'), i * 100);

      setTimeout(() => setDonationAlert(null), 5000);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); // 50% to 90% of container width

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    setChatMessages(prev => [...prev, { id: Date.now().toString(), name: currentUser.firstName, text: newMessage, isMe: true }]);
    setNewMessage('');
    addFloatingHeart(true, 'text-white');
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[60] flex flex-col overflow-hidden text-white font-sans animate-fade-in">

      {/* BACKGROUND VIDEO LAYER */}
      <div className="absolute inset-0 z-0 bg-black">
        {isCamOn ? (
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900">
             <div className="w-32 h-32 md:w-48 md:h-48 rounded-[3rem] bg-white/5 flex items-center justify-center text-4xl md:text-8xl font-black border border-white/10 opacity-30 animate-pulse">
                {creator.firstName[0]}
             </div>
             <p className="mt-8 font-black uppercase tracking-[0.3em] text-xs text-white/20">Aguardando Sinal</p>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE LAYER */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* Header */}
        <nav className="w-full flex items-center justify-between px-4 py-4 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
          <div className="flex items-center gap-3">
             <button onClick={handleExit} className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-all">
               <XMarkIcon className="h-6 w-6" />
             </button>
             <div className="flex items-center gap-2 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 rounded-full border border-white/20" />
                <div className="flex flex-col">
                   <span className="text-[10px] font-black uppercase tracking-wide leading-none">{creator.firstName}</span>
                   <span className="text-[8px] text-white/60 font-bold uppercase tracking-widest">{post.liveStream.title}</span>
                </div>
                <button className="bg-red-600 text-[9px] font-black px-3 py-1 rounded-lg uppercase ml-2 hover:bg-red-700 transition-colors">Seguir</button>
             </div>
          </div>

          <div className="flex items-center gap-2">
             <div className="bg-red-600 px-3 py-1 rounded-lg text-[10px] font-black flex items-center gap-1.5 shadow-lg animate-pulse uppercase tracking-widest">
               <SignalIcon className="h-3 w-3" /> AO VIVO
             </div>
             <div className="bg-black/40 backdrop-blur-md px-3 py-1 rounded-lg border border-white/10 flex items-center gap-1.5">
                <UsersIcon className="h-3 w-3 text-white/70" />
                <span className="text-[10px] font-black">{viewerCount.toLocaleString()}</span>
             </div>
          </div>
        </nav>

        {/* Donation Alert */}
        {donationAlert && (
          <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-shoutout pointer-events-none w-full max-w-sm px-4">
             <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                <div className="bg-black/90 backdrop-blur-xl px-6 py-4 rounded-2xl flex items-center gap-4">
                   <div className="bg-yellow-400 p-2 rounded-full text-black"><SparklesIcon className="h-6 w-6" /></div>
                   <div>
                      <p className="text-xs font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                      <p className="text-sm font-bold text-white">
                         <span className="text-lg">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                      </p>
                   </div>
                </div>
             </div>
          </div>
        )}

        {/* Floating Hearts Container */}
        <div className="absolute bottom-24 right-0 w-24 h-96 pointer-events-none overflow-hidden z-20">
           {floatingHearts.map(heart => (
             <HeartIcon 
               key={heart.id} 
               className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
               style={{ left: `${Math.random() * 60 + 20}%` }} // Random horizontal position within container
             />
           ))}
        </div>

        {/* Footer Area: Chat & Controls */}
        <div className="w-full bg-gradient-to-t from-black via-black/60 to-transparent pt-20 pb-4 px-4 flex flex-col justify-end gap-4 pointer-events-auto">

           {/* Chat Messages */}
           <div className="w-full max-w-md max-h-64 overflow-y-auto no-scrollbar space-y-2 mask-gradient-to-t pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-fade-in">
                   <span className={`text-[11px] font-black ${msg.isMe ? 'text-yellow-400' : 'text-gray-400'} whitespace-nowrap`}>
                      {msg.name}:
                   </span>
                   <span className="text-[11px] text-white font-medium leading-tight shadow-black drop-shadow-md">
                      {msg.text}
                   </span>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           {/* Input & Actions */}
           <div className="flex items-center gap-3">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-md rounded-full px-4 py-2.5 border border-white/10 focus-within:bg-white/20 transition-all">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white hover:text-blue-400 transition-colors disabled:opacity-50">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <button 
                onClick={() => setShowDonationModal(true)}
                className="p-3 bg-yellow-500 hover:bg-yellow-400 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-95 transition-all"
              >
                 <BanknotesIcon className="h-5 w-5" />
              </button>

              <button 
                onClick={() => addFloatingHeart(true)}
                className="p-3 bg-gradient-to-tr from-red-500 to-pink-600 rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-all"
              >
                 <HeartIcon className="h-5 w-5 text-white" />
              </button>

              {isProfessional && (
                 <>
                   <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`}>
                      {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                   </button>
                   <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`}>
                      {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                   </button>
                   <button onClick={() => { if(window.confirm("Encerrar aula?")) { deletePost(post.id); handleExit(); refreshUser(); } }} className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all">
                      <PowerIcon className="h-5 w-5" />
                   </button>
                 </>
              )}
           </div>
        </div>
      </div>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-to-t {
           mask-image: linear-gradient(to top, black 80%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 80%, transparent 100%);
        }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useMemo } from 'react';
import { Post, PostType, User, UserType } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  findUserById, 
  updatePostLikes, 
  updatePostSaves, 
  unpinPost, 
  pinPost,
  createReport,
  updatePostShares,
  deletePost
} from '../services/storageService';
import {
  HeartIcon as HeartIconOutline, 
  ChatBubbleOvalLeftIcon as ChatIconOutline, 
  BookmarkIcon as BookmarkIconOutline, 
  EllipsisHorizontalIcon, 
  CheckBadgeIcon,
  MapPinIcon as PinIconOutline,
  SignalIcon,
  ShareIcon,
  PlayIcon,
  UserGroupIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  MapPinIcon as PinIconSolid,
  BoltIcon
} from '@heroicons/react/24/solid';
import PostDetailModal from './PostDetailModal';
import BoostPostModal from './BoostPostModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import EditPostModal from './EditPostModal';
import PostActionsModal from './PostActionsModal';
import IndicateModal from './IndicateModal';

interface PostCardProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  onPostUpdatedOrDeleted: () => void;
  onPinToggle: (postId: string, isCurrentlyPinned: boolean) => void;
}

const PostCard: React.FC<PostCardProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle,
  refreshUser, 
  onPostUpdatedOrDeleted,
}) => {
  const [postAuthor, setPostAuthor] = useState<User | null>(null);
  const [showActionsModal, setShowActionsModal] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [showBoostModal, setShowBoostModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showIndicateModal, setShowIndicateModal] = useState(false);

  // Optimistic UI states
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);
  const [localSaves, setLocalSaves] = useState<string[]>(post.saves || []);
  const [isSaved, setIsSaved] = useState(post.saves?.includes(currentUser.id) || false);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);

  // Gera um delay aleatório para a animação de flutuação, para que os cards não se movam em uníssono.
  const animationDelay = useMemo(() => `${Math.random() * 5}s`, []);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
    setLocalSaves(post.saves || []);
    setIsSaved(post.saves?.includes(currentUser.id) || false);
  }, [post.likes, post.saves, currentUser.id]);

  useEffect(() => {
    const fetchAuthor = async () => {
      const author = await findUserById(post.userId);
      setPostAuthor(author || null);
    };
    fetchAuthor();
  }, [post.userId]);

  if (!post || !currentUser || !post.id || !postAuthor) return null;

  const isAuthor = currentUser.id === post.userId;
  const isPostBoosted = post.isBoosted && post.boostExpires && post.boostExpires > Date.now();

  const handleLike = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevIsLiked);
    if (prevIsLiked) {
      setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostLikes(post.id, currentUser.id);
    } catch (error) {
      setIsLiked(prevIsLiked);
      setLocalLikes(prevLikes);
      console.error("Falha ao curtir post", error);
    }
  };

  const handleSave = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // Optimistic Update
    const prevIsSaved = isSaved;
    const prevSaves = [...localSaves];

    setIsSaved(!prevIsSaved);
    if (prevIsSaved) {
      setLocalSaves(prev => prev.filter(id => id !== currentUser.id));
    } else {
      setLocalSaves(prev => [...prev, currentUser.id]);
    }

    try {
      await updatePostSaves(post.id, currentUser.id);
    } catch (error) {
      setIsSaved(prevIsSaved);
      setLocalSaves(prevSaves);
    }
  };

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const contentLength = post.content?.length || 0;

  // Lógica Adaptativa de Tamanho (Otimizada para Mobile)
  let containerMinHeight = 'auto';
  let fontSizeClass = 'text-sm md:text-lg text-gray-900 dark:text-white';
  let paddingClass = 'py-2';

  if (hasBg) {
    if (contentLength < 60) {
        // Frase Curta
        containerMinHeight = '180px md:min-h-[200px]'; 
        fontSizeClass = `${post.textColor || 'text-white'} text-2xl md:text-4xl leading-tight`;
        paddingClass = 'p-6 md:p-8';
    } else if (contentLength < 150) {
        // Frase Média
        containerMinHeight = '220px md:min-h-[300px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-lg md:text-2xl leading-snug`;
        paddingClass = 'p-6 md:p-10';
    } else {
        // Texto Longo
        containerMinHeight = '280px md:min-h-[400px]';
        fontSizeClass = `${post.textColor || 'text-white'} text-base md:text-xl leading-relaxed`;
        paddingClass = 'p-8 md:p-12';
    }
  }

  return (
    <>
      <div 
        onClick={() => {
          if (post.type === PostType.LIVE) onNavigate('live', { postId: post.id });
          else if (post.type === PostType.REEL) onNavigate('reels-page', { startPostId: post.id });
          else setShowDetailModal(true);
        }}
        style={{ animationDelay }}
        className="bg-white dark:bg-darkcard rounded-[2rem] md:rounded-[3rem] shadow-sm border border-gray-100 dark:border-white/5 overflow-hidden w-full relative mb-6 cursor-pointer group animate-float hover-pause hover:shadow-2xl hover:-translate-y-2 transition-all duration-300"
      >
        <div className="p-4 md:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3 md:gap-5 min-w-0">
            <div className="relative cursor-pointer shrink-0" onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}>
              <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-10 h-10 md:w-16 md:h-16 rounded-[1.2rem] md:rounded-[1.8rem] object-cover shadow-lg border-2 border-white dark:border-white/10" />
              {postAuthor.userType === UserType.CREATOR && (
                <div className="absolute -bottom-1 -right-1 bg-brand rounded-lg md:rounded-xl p-0.5 md:p-1 border-2 border-white dark:border-darkcard shadow-md">
                  <CheckBadgeIcon className="h-3 w-3 md:h-4 md:w-4 text-white" />
                </div>
              )}
            </div>
            <div className="min-w-0 flex-1">
              <div className="flex flex-col">
                <div className="flex items-center gap-1 md:gap-2">
                  <h4 className="font-black text-gray-900 dark:text-white text-sm md:text-xl truncate tracking-tighter hover:text-brand transition-colors">
                      {postAuthor.firstName}
                  </h4>
                  {post.isPinned && <PinIconSolid className="h-3 w-3 md:h-4 md:w-4 text-brand shrink-0" />}
                  {isPostBoosted && <BoltIcon className="h-3 w-3 md:h-4 md:w-4 text-orange-500 animate-pulse shrink-0" />}
                </div>
                {post.groupId && (
                  <div className="flex items-center gap-1 text-[8px] md:text-[9px] font-black text-brand uppercase tracking-widest mt-0.5 truncate">
                     <UserGroupIcon className="h-3 w-3" /> <span className="truncate">{post.groupName}</span>
                  </div>
                )}
              </div>
              <p className="text-[8px] md:text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-0.5 truncate">
                {new Date(post.timestamp).toLocaleDateString()} 
                {isPostBoosted && <span className="ml-2 text-brand">⚡ Promo</span>}
              </p>
            </div>
          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowActionsModal(true); }} 
            className="p-2 md:p-3 rounded-xl md:rounded-2xl bg-gray-50 dark:bg-white/5 text-gray-400 hover:text-brand transition-all shrink-0"
          >
            <EllipsisHorizontalIcon className="h-6 w-6 md:h-7 md:w-7" />
          </button>
        </div>

        <div className={`px-4 md:px-8 ${hasBg ? 'pb-6 md:pb-8' : 'pb-4'}`}>
          {post.type === PostType.LIVE && post.liveStream ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden bg-gray-900 text-white p-6 md:p-16 relative shadow-2xl border-4 border-white/5">
                <div className="absolute top-4 left-4 md:top-6 md:left-6 z-10 flex gap-3">
                   <div className="bg-red-600 px-3 py-1 md:px-4 md:py-1.5 rounded-full text-[9px] md:text-[10px] font-black flex items-center gap-1.5 shadow-2xl animate-pulse uppercase tracking-widest">
                      <SignalIcon className="h-3 w-3 md:h-3.5 md:w-3.5" /> Ao Vivo
                   </div>
                </div>
                <div className="relative z-10 py-6 md:py-8 flex flex-col items-center text-center">
                   <h3 className="text-xl md:text-4xl font-black mb-6 md:mb-8 tracking-tighter uppercase line-clamp-2">{post.liveStream.title}</h3>
                   <button className="bg-brand text-white px-8 py-4 md:px-10 md:py-5 rounded-[2rem] md:rounded-[2.2rem] font-black text-[10px] md:text-sm uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-3 md:gap-4">
                      <PlayIcon className="h-5 w-5 md:h-6 md:w-6" /> Entrar Agora
                   </button>
                </div>
             </div>
          ) : post.type === PostType.REEL && post.reel ? (
             <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-black relative shadow-xl mt-2 aspect-[9/16] max-h-[500px] md:max-h-[600px] flex items-center justify-center group">
                <video 
                  src={post.reel.videoUrl} 
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity duration-500" 
                  muted 
                  loop 
                  playsInline
                  onMouseOver={(e) => e.currentTarget.play()}
                  onMouseOut={(e) => e.currentTarget.pause()}
                />
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                   <div className="bg-white/20 backdrop-blur-md p-3 md:p-4 rounded-full border border-white/10 group-hover:scale-110 transition-transform">
                      <PlayIcon className="h-8 w-8 md:h-10 md:w-10 text-white fill-white" />
                   </div>
                </div>
                <div className="absolute bottom-0 left-0 w-full p-4 md:p-6 bg-gradient-to-t from-black/80 to-transparent pointer-events-none">
                   <p className="text-white text-xs md:text-sm font-medium line-clamp-2">{post.reel.description}</p>
                </div>
             </div>
          ) : (
            <>
              {post.content && (
                <div 
                  className={`rounded-[2rem] md:rounded-[3rem] transition-all duration-500 w-full flex items-center justify-center
                    ${hasBg ? `${post.backgroundColor} text-center shadow-inner mb-4` : 'text-left bg-transparent'} 
                    ${post.fontFamily || 'font-sans'}`}
                  style={{ 
                    // Use a classe para altura mínima, o style é override se necessário
                  }}
                >
                  <div className={`w-full ${hasBg ? containerMinHeight : ''} flex items-center justify-center ${hasBg ? paddingClass : 'p-0'}`}>
                    <p className={`font-black whitespace-pre-wrap break-words w-full ${fontSizeClass}`}>
                      {post.content}
                    </p>
                  </div>
                </div>
              )}
              {post.imageUrl && (
                <div className="rounded-[2rem] md:rounded-[3.5rem] overflow-hidden border dark:border-white/5 bg-gray-50 dark:bg-darkbg relative shadow-xl mt-2">
                   <img src={post.imageUrl} className="w-full h-auto object-cover max-h-[500px] md:max-h-[700px] transition-transform duration-1000 group-hover:scale-105" alt="Post" />
                </div>
              )}
            </>
          )}
        </div>

        <div className="px-4 md:px-12 py-4 md:py-8 flex items-center justify-between border-t border-gray-50 dark:border-white/5">
          <div className="flex items-center gap-1 md:gap-5">
            <button onClick={handleLike} className={`flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] transition-all active:scale-75 ${isLiked ? 'text-brand bg-brand/10 font-black' : 'text-gray-400 hover:bg-gray-50'}`}>
              {isLiked ? <HeartIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <HeartIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
              <span className="text-xs md:text-base font-black">{localLikes.length}</span>
            </button>
            <button onClick={(e) => { e.stopPropagation(); setShowDetailModal(true); }} className="flex items-center gap-2 md:gap-3 px-4 md:px-7 py-3 md:py-4 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ChatIconOutline className="h-5 w-5 md:h-8 md:w-8" />
              <span className="font-black text-xs md:text-base">{post.comments?.length || 0}</span>
            </button>
            <button className="p-3 md:p-5 rounded-[1.5rem] text-gray-400 hover:bg-gray-50 transition-all active:scale-90">
              <ShareIcon className="h-5 w-5 md:h-8 md:w-8" />
            </button>
          </div>
          <button onClick={handleSave} className={`p-3 md:p-5 rounded-[1.5rem] transition-all active:scale-90 ${isSaved ? 'text-brand bg-brand/10' : 'text-gray-300 hover:bg-gray-50'}`}>
            {isSaved ? <BookmarkIconSolid className="h-5 w-5 md:h-8 md:w-8" /> : <BookmarkIconOutline className="h-5 w-5 md:h-8 md:w-8" />}
          </button>
        </div>
      </div>

      {showActionsModal && (
        <PostActionsModal 
          isAuthor={isAuthor} 
          isPinned={!!post.isPinned}
          isFollowing={isFollowing}
          onClose={() => setShowActionsModal(false)} 
          onEdit={() => { setShowActionsModal(false); setShowEditModal(true); }} 
          onDelete={() => { setShowActionsModal(false); setShowDeleteModal(true); }} 
          onPin={() => { if(post.isPinned) unpinPost(post.id, currentUser.id); else pinPost(post.id, currentUser.id); onPostUpdatedOrDeleted(); setShowActionsModal(false); }} 
          onBoost={() => { setShowActionsModal(false); setShowBoostModal(true); }} 
          onFollow={() => { onFollowToggle(post.userId); setShowActionsModal(false); }} 
          onIndicate={() => { setShowActionsModal(false); setShowIndicateModal(true); }} 
          onReport={() => { 
            if(window.confirm("Deseja realmente denunciar esta publicação?")) {
              createReport({ reporterId: currentUser.id, targetId: post.id, targetType: 'POST', reason: 'DENÚNCIA', details: 'Via PostCard' }); 
              alert("Denúncia enviada com sucesso. Nossa equipe irá analisar.");
              setShowActionsModal(false); 
            }
          }} 
        />
      )}

      {showDetailModal && <PostDetailModal post={post} currentUser={currentUser} onClose={() => setShowDetailModal(false)} onUpdate={onPostUpdatedOrDeleted} onNavigate={onNavigate} refreshUser={refreshUser} />}
      {showBoostModal && <BoostPostModal post={post} currentUser={currentUser} onClose={() => setShowBoostModal(false)} onSuccess={() => { refreshUser(); onPostUpdatedOrDeleted(); }} />}

      {showDeleteModal && (
        <DeleteConfirmModal 
          onClose={() => setShowDeleteModal(false)} 
          onConfirm={async () => { 
            await deletePost(post.id); 
            onPostUpdatedOrDeleted(); 
            setShowDeleteModal(false); 
          }} 
        />
      )}

      {showEditModal && <EditPostModal postId={post.id} currentUser={currentUser} onClose={() => setShowEditModal(false)} onSuccess={onPostUpdatedOrDeleted} />}
      {showIndicateModal && <IndicateModal post={post} currentUser={currentUser} onClose={() => setShowIndicateModal(false)} onPostUpdated={onPostUpdatedOrDeleted} />}
    </>
  );
};

export default PostCard;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { User, Post, AdCampaign, PostType, Story, CyberEvent, ChatConversation } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents, getChats, joinGroup } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import GroupDiscoveryCard from './GroupDiscoveryCard';
import { PlusIcon, ArrowPathIcon, RocketLaunchIcon, ChevronUpIcon, FireIcon, SparklesIcon, CalendarIcon, UserGroupIcon, StarIcon, ArrowTrendingUpIcon, PlayIcon, FilmIcon } from '@heroicons/react/24/outline';
import { TrophyIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

type FeedItem = 
  | Post 
  | AdCampaign 
  | ChatConversation 
  | { type: 'SUGGESTIONS' } 
  | { type: 'REELS_SHELF'; items: Post[] } 
  | { type: 'GROUPS_SHELF'; items: ChatConversation[] };

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<FeedItem[]>([]);
  const [visibleItems, setVisibleItems] = useState<FeedItem[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [stories, setStories] = useState<Story[]>([]);
  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async (isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    const [allPosts, allAds, allUsers, allStories, allChats] = await Promise.all([
      getPosts(),
      getAds(),
      getUsers(),
      getStories(),
      getChats()
    ]);

    // Filtrar Posts Normais e Reels
    const normalPosts = allPosts.filter(p => p.type !== PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);
    const reelsPosts = allPosts.filter(p => p.type === PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);

    const activeAds = allAds.filter(a => a.isActive).sort((a, b) => (b.budget || 0) - (a.budget || 0));

    // Filtrar Grupos Públicos que o usuário NÃO participa
    const publicGroups = allChats.filter(c => 
      c.type === 'GROUP' && 
      c.isPublic && 
      !c.participants.includes(currentUser.id)
    );

    // Filtrar Stories (apenas de quem sigo ou meus)
    // Para simplificar a demo, mostra todos, mas coloca o meu primeiro se existir
    const myStory = allStories.find(s => s.userId === currentUser.id);
    const otherStories = allStories.filter(s => s.userId !== currentUser.id);

    // Se eu tenho story, ele vai pro topo da lista de visualização
    const viewerStories = myStory ? [myStory, ...otherStories] : otherStories;
    setStories(viewerStories);

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);
    setSuggestedUsers(suggestions);

    let combined: FeedItem[] = [];
    let adPointer = 0;

    // Estratégia de Mixagem do Feed
    const firstBatch = normalPosts.slice(0, 3);
    combined.push(...firstBatch);

    if (reelsPosts.length > 0) {
      combined.push({ type: 'REELS_SHELF', items: reelsPosts.slice(0, 10) });
    }

    if (suggestions.length > 0) {
      combined.push({ type: 'SUGGESTIONS' });
    }

    if (publicGroups.length > 0) {
      combined.push({ type: 'GROUPS_SHELF', items: publicGroups.slice(0, 5) });
    }

    const remainingPosts = normalPosts.slice(3);
    remainingPosts.forEach((post, idx) => {
        combined.push(post);
        if ((idx + 1) % 5 === 0 && adPointer < activeAds.length) {
            combined.push(activeAds[adPointer]);
            adPointer++;
        }
    });

    setAllItems(combined);
    // Se for refresh, mantém o limite atual, senão reseta
    if (isRefresh) {
        setVisibleItems(combined.slice(0, displayLimit));
    } else {
        setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
        setDisplayLimit(ITEMS_PER_PAGE);
    }

    setLoading(false);
  }, [currentUser, displayLimit]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  useEffect(() => {
    const handleScroll = () => setShowScrollTop(window.scrollY > 1000);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleJoin = async (groupId: string) => {
    await joinGroup(groupId, currentUser.id);
    loadData(true);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);
  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  // Verifica se o usuário atual tem story postado
  const hasMyStory = stories.some(s => s.userId === currentUser.id);

  // Renderização otimizada dos itens
  const renderedItems = useMemo(() => {
    return visibleItems.map((item: any, idx) => {
        if (item.authorName) { 
          return <PostCard key={item.id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
        }
        if (item.professorId) { 
          return <AdCard key={item.id} ad={item as AdCampaign} rank={idx} />;
        }
        if (item.type === 'SUGGESTIONS') {
          return (
            <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[2.5rem] p-6 md:p-8 text-white shadow-2xl relative overflow-hidden animate-fade-in my-6 border-4 border-white/10">
                <SparklesIcon className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10 rotate-12" />
                <div className="flex items-center justify-between mb-6 relative z-10">
                  <div>
                      <h4 className="font-black text-xl tracking-tighter flex items-center gap-2"><FireIcon className="h-6 w-6 text-yellow-400" /> Networking</h4>
                      <p className="text-blue-100 text-[10px] font-bold uppercase tracking-widest">Sugestões de Conexão</p>
                  </div>
                  <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-2.5 rounded-xl transition-all"><ArrowPathIcon className="h-5 w-5"/></button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar relative z-10 snap-x">
                  {suggestedUsers.map(u => (
                    <div key={u.id} className="bg-white/10 backdrop-blur-md p-4 rounded-[1.8rem] min-w-[140px] flex flex-col items-center text-center border border-white/10 group hover:bg-white/20 transition-all snap-start">
                        <img src={u.profilePicture} className="w-16 h-16 rounded-full object-cover mb-3 border-2 border-white/30 shadow-lg group-hover:scale-110 transition-transform" />
                        <p className="font-black text-xs truncate w-full mb-0.5">{u.firstName}</p>
                        <p className="text-[8px] font-bold text-blue-200 uppercase mb-3 tracking-wide truncate w-full">{u.lastName}</p>
                        <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-700 py-2 rounded-lg font-black text-[9px] uppercase shadow-md active:scale-95 transition-all">Seguir</button>
                    </div>
                  ))}
                </div>
            </div>
          );
        }
        if (item.type === 'REELS_SHELF') {
          return (
            <div key="reels-shelf" className="my-4">
              <div className="flex items-center gap-2 mb-3 px-2">
                  <FilmIcon className="h-5 w-5 text-purple-600" />
                  <h3 className="font-black text-base dark:text-white uppercase tracking-tight">Reels em Alta</h3>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar snap-x px-1">
                  {item.items.map((reel: Post) => (
                    <div 
                      key={reel.id} 
                      onClick={() => onNavigate('reels-page', { startPostId: reel.id })}
                      className="relative min-w-[130px] h-[220px] rounded-[1.2rem] overflow-hidden cursor-pointer group shadow-md snap-start border border-gray-100 dark:border-white/5"
                    >
                      <video src={reel.reel?.videoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" muted />
                      <div className="absolute inset-0 bg-black/10 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                          <PlayIcon className="h-8 w-8 text-white/80 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </div>
                      <div className="absolute bottom-0 left-0 w-full p-3 bg-gradient-to-t from-black/80 to-transparent">
                          <p className="text-white text-[9px] font-bold line-clamp-1 leading-tight mb-0.5">{reel.reel?.description}</p>
                          <p className="text-white/70 text-[7px] font-black uppercase">@{reel.authorName}</p>
                      </div>
                    </div>
                  ))}
              </div>
            </div>
          );
        }
        if (item.type === 'GROUPS_SHELF') {
          return (
            <div key="groups-shelf" className="my-6 bg-gray-50 dark:bg-white/5 p-5 rounded-[2rem] border border-gray-100 dark:border-white/5">
              <div className="flex items-center gap-2 mb-3">
                  <UserGroupIcon className="h-5 w-5 text-blue-600" />
                  <h3 className="font-black text-base dark:text-white uppercase tracking-tight">Comunidades</h3>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar snap-x">
                  {item.items.map((group: ChatConversation) => (
                    <div key={group.id} className="min-w-[240px] snap-start">
                      <GroupDiscoveryCard group={group} onJoin={() => handleJoin(group.id)} />
                    </div>
                  ))}
              </div>
            </div>
          );
        }
        return null;
    });
  }, [visibleItems, currentUser, onNavigate, loadData, refreshUser, suggestedUsers]);

  return (
    <div className="w-full max-w-[1400px] mx-auto px-2 md:px-6 lg:px-8 py-4 md:py-6 relative">
      <div className="fixed bottom-28 md:bottom-12 right-4 md:right-8 z-[100] flex flex-col gap-3">
        {showScrollTop && (
          <button onClick={scrollToTop} className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all">
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button 
          onClick={() => onNavigate('ads')} 
          className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all flex items-center justify-center"
          title="Criar Anúncio"
        >
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      {/* WHATSAPP STYLE STORIES HEADER */}
      <div className="mb-6 overflow-x-auto no-scrollbar py-2 -mx-2 px-2 snap-x">
         <div className="flex items-start gap-4 px-2">

            {/* 1. BOTÃO DE CRIAR (SEMPRE VISÍVEL E FIXO À ESQUERDA) */}
            <div 
              onClick={() => setIsCreatingStory(true)} 
              className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start"
            >
               <div className="relative">
                  <div className="w-16 h-16 rounded-full border-2 border-dashed border-blue-400 p-[2px] flex items-center justify-center hover:bg-blue-50 dark:hover:bg-white/5 transition-all">
                     <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full rounded-full object-cover opacity-70" />
                  </div>
                  <div className="absolute bottom-0 right-0 bg-blue-600 rounded-full p-1.5 border-2 border-white dark:border-darkbg shadow-sm">
                     <PlusIcon className="h-3 w-3 text-white stroke-[3]" />
                  </div>
               </div>
               <span className="text-[10px] font-bold text-gray-900 dark:text-white truncate w-full text-center">
                  Criar
               </span>
            </div>

            {/* 2. MEU STORY (SE EXISTIR) */}
            {hasMyStory && (
              <div 
                onClick={() => setSelectedStoryIndex(stories.findIndex(s => s.userId === currentUser.id))} 
                className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start"
              >
                 <div className="p-[2px] rounded-full bg-gradient-to-tr from-green-400 to-blue-500">
                    <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-16 h-16 rounded-full border-2 border-white dark:border-darkbg object-cover" />
                 </div>
                 <span className="text-[10px] font-medium text-gray-600 dark:text-gray-300 truncate w-[70px] text-center">
                    Você
                 </span>
              </div>
            )}

            {/* 3. STORIES DOS OUTROS */}
            {stories.filter(s => s.userId !== currentUser.id).map((story) => {
               // Encontrar índice real no array completo para abrir o viewer
               const realIndex = stories.findIndex(s => s.userId === story.userId);

               return (
                  <div key={story.userId} onClick={() => setSelectedStoryIndex(realIndex)} className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start">
                     <div className="p-[2px] rounded-full bg-gradient-to-tr from-yellow-400 to-red-500 group-hover:scale-105 transition-transform duration-300">
                        <img src={story.userProfilePic || DEFAULT_PROFILE_PIC} className="w-16 h-16 rounded-full border-2 border-white dark:border-darkbg object-cover" />
                     </div>
                     <span className="text-[10px] font-medium text-gray-600 dark:text-gray-300 truncate w-[70px] text-center">
                        {(story.userName || 'Usuário').split(' ')[0]}
                     </span>
                  </div>
               );
            })}
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Carregando Feed...</p>
              </div>
            ) : (
              <>
                {renderedItems}

                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Carregando...</p>
                    </>
                  )}
                  {isAtEnd && !loadingMore && (
                    <div className="flex flex-col items-center gap-2 opacity-50 py-8">
                       <CheckCircleIcon className="h-8 w-8 text-green-500" />
                       <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em]">Fim do conteúdo</p>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </main>

        <aside className="hidden lg:block lg:col-span-4 space-y-6">
           <div className="sticky top-24 space-y-6">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden group">
                 <RocketLaunchIcon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-4 flex items-center gap-2">
                    <TrophyIcon className="h-6 w-6 text-yellow-400" /> Meta Profissional
                 </h3>
                 <div className="mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2">
                       <span>Progresso</span>
                       <span>{followerCount} / 2.000</span>
                    </div>
                    <div className="w-full h-2.5 bg-white/20 rounded-full overflow-hidden border border-white/10">
                       <div className="h-full bg-white shadow-[0_0_10px_white] transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
                    </div>
                 </div>
                 <button onClick={() => onNavigate('ads')} className="w-full bg-white text-blue-700 py-4 rounded-2xl font-black text-[11px] uppercase shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
                    <RocketLaunchIcon className="h-5 w-5" /> Impulsionar Perfil
                 </button>
              </div>
           </div>
        </aside>
      </div>

      {isCreatingStory && <CreateStoryModal currentUser={currentUser} onClose={() => setIsCreatingStory(false)} onStoryCreated={() => { setIsCreatingStory(false); loadData(true); }} />}

      {selectedStoryIndex !== null && (
        <StoryViewerModal 
          stories={stories} 
          initialIndex={selectedStoryIndex} 
          onClose={() => setSelectedStoryIndex(null)} 
        />
      )}
    </div>
  );
};

export default FeedPage;

import React, { useState, useEffect } from 'react';
import { User } from '../types';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
    MagnifyingGlassIcon, 
    ShoppingCartIcon, 
    BellIcon, 
    ArrowLeftIcon, 
    Bars3Icon 
} from '@heroicons/react/24/outline';
import Logo from './Logo';

interface HeaderProps {
  currentUser: User | null;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  unreadNotificationsCount: number;
  cartItemCount: number;
  onOpenCart: () => void;
  onToggleMenu: () => void;
}

const Header: React.FC<HeaderProps> = ({ currentUser, onNavigate, unreadNotificationsCount, cartItemCount, onOpenCart, onToggleMenu }) => {
