import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User } from '../types';
import { getPosts, findUserById, updateUserBalance, deletePost, getGlobalSettings } from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon,
  SignalIcon,
  UsersIcon,
  PowerIcon,
  BanknotesIcon,
  PaperAirplaneIcon,
  SparklesIcon,
  HeartIcon,
  EllipsisHorizontalIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const RANDOM_COMMENTS = [
  "Incrível! 👏👏", "Show de bola!", "Manda um salve!", "Muito bom o conteúdo", 
  "Aula top demais 🚀", "Aprendendo muito", "Isso aí!", "Grande mestre!", "👏👏👏", 
  "Adorei a explicação", "Qual o próximo tema?", "Compartilhei aqui!", "Boa noite galera"
];

const RANDOM_NAMES = ["Carlos", "Ana", "Pedro", "Julia", "Marcos", "Beatriz", "Lucas", "Fernanda"];

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(false);
  const [isCamOn, setIsCamOn] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); // Mobile toggle for creator controls
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Chat & Reactions States
  const [chatMessages, setChatMessages] = useState<{id: string, name: string, text: string, isMe?: boolean}[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(1200);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
  }, []);

  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // Simulation Effect (Chat, Hearts, Viewers)
  useEffect(() => {
    const interval = setInterval(() => {
      // Random Hearts
      if (Math.random() > 0.6) {
        addFloatingHeart(false);
      }

      // Random Viewer Count Fluctuation
      if (Math.random() > 0.5) {
        setViewerCount(prev => prev + Math.floor(Math.random() * 5) - 2);
      }

      // Random Chat Message
      if (Math.random() > 0.7) {
        const text = RANDOM_COMMENTS[Math.floor(Math.random() * RANDOM_COMMENTS.length)];
        const name = RANDOM_NAMES[Math.floor(Math.random() * RANDOM_NAMES.length)];
        setChatMessages(prev => [...prev.slice(-10), { 
          id: Date.now().toString() + Math.random(), 
          name, 
          text 
        }]);
      }
    }, 800);

    return () => clearInterval(interval);
  }, []);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  const toggleMic = async () => {
    if (isMicOn) {
      if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsMicOn(false);
    } else {
      try {
        const audioStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        const audioTrack = audioStream.getAudioTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        streamRef.current.addTrack(audioTrack);
        setIsMicOn(true);
      } catch (err) { alert("Microfone indisponível."); }
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

      // Donation Special Effect
      for(let i=0; i<10; i++) setTimeout(() => addFloatingHeart(false, 'text-yellow-400'), i * 100);

      setTimeout(() => setDonationAlert(null), 5000);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); // 50% to 90% of container width

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;
    setChatMessages(prev => [...prev, { id: Date.now().toString(), name: currentUser.firstName, text: newMessage, isMe: true }]);
    setNewMessage('');
    addFloatingHeart(true, 'text-white');
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isCamOn ? (
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10 opacity-30 animate-pulse">
                {creator.firstName[0]}
             </div>
             <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white/20">Aguardando Sinal</p>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER - Mobile Optimized */}
        <header className="w-full flex items-center justify-between px-3 pt-3 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           {/* Left: Profile Info */}
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           {/* Right: Controls & Viewers */}
           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button onClick={handleExit} className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90">
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* MIDDLE LAYER - Gift Alerts & Hearts */}
        <div className="flex-1 relative w-full pointer-events-none">
           {/* Donation/Gift Alert Centered Top */}
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {/* Floating Hearts Container - Right Side */}
           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER - Chat & Inputs */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/50 to-transparent pt-12 pb-4 px-3 md:px-6 flex flex-col justify-end gap-3 pointer-events-auto">

           {/* Chat List - Limit Height & Width on Mobile */}
           <div className="w-[85%] md:w-[400px] h-48 md:h-64 overflow-y-auto no-scrollbar space-y-2 mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.isMe ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.name}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           {/* Input Row */}
           <div className="flex items-center gap-2 md:gap-3 pb-safe">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-2.5 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   onFocus={() => { /* logic to handle keyboard overlap if needed */ }}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 {!isProfessional && (
                    <button 
                    onClick={() => setShowDonationModal(true)}
                    className="p-2.5 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                    >
                        <BanknotesIcon className="h-5 w-5" />
                    </button>
                 )}

                 <button 
                   onClick={() => addFloatingHeart(true)}
                   className="p-2.5 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 {isProfessional && (
                    <div className="relative">
                        <button onClick={() => setShowControls(!showControls)} className="p-2.5 bg-gray-800 rounded-full border border-white/20 text-white">
                            <EllipsisHorizontalIcon className="h-5 w-5" />
                        </button>
                        {showControls && (
                            <div className="absolute bottom-full right-0 mb-2 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[50px] items-center">
                                <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`}>
                                    {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                </button>
                                <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`}>
                                    {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                </button>
                                <div className="h-px w-full bg-white/10 my-1"></div>
                                <button onClick={() => { if(window.confirm("Encerrar aula?")) { deletePost(post.id); handleExit(); refreshUser(); } }} className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white">
                                    <PowerIcon className="h-5 w-5" />
                                </button>
                            </div>
                        )}
                    </div>
                 )}
              </div>
           </div>
        </div>
      </div>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: env(safe-area-inset-bottom, 16px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

