                 )}
              </div>
           </div>
        </div>
      </div>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
