export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.toLowerCase().trim();

  // MODO ONLINE ESTRITO: Se Supabase estiver configurado, use-o.
  if (isSupabaseConfigured) {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });

    if (error) throw new Error(error.message);

    if (data.user) {
      const user = await findUserById(data.user.id);
      if (user) return user;

      // Se autenticou mas não tem perfil (inconsistência), tenta recuperar
      console.warn("Perfil não encontrado. Restaurando dados básicos...");
      const meta = data.user.user_metadata || {};
      const restoredUser: User = {
          id: data.user.id,
          email: email,
          firstName: meta.first_name || 'Usuário',
          lastName: meta.last_name || 'Novo',
          userType: UserType.STANDARD,
          phone: '',
          documentId: '',
          birthDate: Date.now(),
          profilePicture: DEFAULT_PROFILE_PIC,
          balance: 0,
          followers: [],
          followedUsers: [],
          isAdmin: false
      };
      // Tenta criar o perfil
      await supabase.from('profiles').upsert({
          id: restoredUser.id,
          email: restoredUser.email,
          first_name: restoredUser.firstName,
          last_name: restoredUser.lastName,
          user_type: restoredUser.userType,
          profile_picture: restoredUser.profilePicture,
          balance: 0
      });
      return restoredUser;
    }
    throw new Error("Erro desconhecido no login.");
  }

  // MODO OFFLINE (Apenas se nenhuma env var estiver configurada)
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
  const user = users.find(u => u.email.toLowerCase() === email);
  if (user) return user;

  throw new Error("Usuário não encontrado (Modo Offline).");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.toLowerCase().trim();
  const newUser: User = {
    id: generateUUID(),
    ...userData,
    email,
    followers: [],
    followedUsers: [],
    balance: 0
  };

  if (isSupabaseConfigured) {
    // Cria Auth
    const { data, error } = await supabase.auth.signUp({
      email,
      password: userData.password,
      options: {
        data: {
          first_name: userData.firstName,
          last_name: userData.lastName
        }
      }
    });

    if (error) throw error;

    if (data.user) {
      newUser.id = data.user.id;
      // Cria Profile
      const { error: profileError } = await supabase.from('profiles').insert({
        id: newUser.id,
        email: newUser.email,
        first_name: newUser.firstName,
        last_name: newUser.lastName,
        user_type: newUser.userType,
        phone: newUser.phone,
        document_id: newUser.documentId,
        birth_date: newUser.birthDate,
        profile_picture: newUser.profilePicture,
        credentials: newUser.credentials,
        bio: newUser.bio,
        verification_file_url: newUser.verificationFileUrl
      });

      if (profileError) {
        console.error("Erro ao criar perfil:", profileError);
        // Não lançamos erro aqui para não travar o cadastro se o Auth funcionou, 
        // o login subsequente tentará corrigir
      }
    }
    return newUser;
  } else {
    // LocalStorage Fallback
    const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    if (users.some(u => u.email.toLowerCase() === email)) {
      throw new Error('Email já cadastrado (Local).');
    }
    users.push(newUser);
    saveLocalList(KEYS.USERS, users);
    return newUser;
  }
};

