export const updateUserBalance = async (userId: string, amount: number) => {
  if (isSupabaseConfigured) {
    const { data } = await supabase.from('profiles').select('balance').eq('id', userId).single();
    const newBal = (data?.balance || 0) + amount;
    await supabase.from('profiles').update({ balance: newBal }).eq('id', userId);
  } else {
    const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    const u = users.find(u => u.id === userId);
    if (u) {
      u.balance = (u.balance || 0) + amount;
      saveLocalList(KEYS.USERS, users);
    }
  }
  return true;
};

