import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType, GroupTheme } from '../types';
import {
  getChats,
  findUserById,
  sendMessage,
  deleteMessage,
  editMessage,
  generateUUID,
  getUsers,
  updateGroupTheme
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  EllipsisVerticalIcon,
  PaintBrushIcon,
  ChevronDownIcon,
  PencilIcon,
  TrashIcon,
  ArrowUturnLeftIcon,
  XMarkIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';

interface ChatPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

const THEME_CONFIG: Record<GroupTheme, { primary: string, secondary: string, bg: string, bubble: string, text: string }> = {
  blue: { primary: 'bg-blue-600', secondary: 'bg-blue-500', bg: 'bg-[#5497d5]', bubble: 'bg-[#effdde]', text: 'text-blue-600' },
  green: { primary: 'bg-emerald-600', secondary: 'bg-emerald-500', bg: 'bg-[#7ebc89]', bubble: 'bg-[#e7fde8]', text: 'text-emerald-600' },
  black: { primary: 'bg-zinc-900', secondary: 'bg-zinc-800', bg: 'bg-[#1a1a1a]', bubble: 'bg-[#2b2b2b]', text: 'text-white' },
  orange: { primary: 'bg-orange-600', secondary: 'bg-orange-500', bg: 'bg-[#edb881]', bubble: 'bg-[#fff5e6]', text: 'text-orange-600' }
};

const ChatPage: React.FC<ChatPageProps> = ({ currentUser, onNavigate }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');
  const [activeCall, setActiveCall] = useState<{partner: User, type: 'voice' | 'video'} | null>(null);

  // New States for Actions
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [openMessageMenuId, setOpenMessageMenuId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = useCallback(async () => {
    const allChats = await getChats();
    const userChats = allChats.filter(c => c.participants.includes(currentUser.id));
    setConversations(userChats);

    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    if (editingMessageId) {
        // Handle Edit
        await editMessage(selectedChat.id, editingMessageId, newMessage.trim());
        setEditingMessageId(null);
    } else {
        // Handle New Message
        const replyContext = replyingTo ? {
            id: replyingTo.id,
            text: replyingTo.text || 'Imagem',
            senderName: replyingTo.senderId === currentUser.id ? 'Você' : 'Usuário' // Ideal seria buscar o nome correto
        } : undefined;

        const msg: Message = {
          id: generateUUID(),
          senderId: currentUser.id,
          timestamp: Date.now(),
          text: newMessage.trim() || undefined,
          imageUrl: attachedImage || undefined,
          groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
          replyTo: replyContext
        };

        await sendMessage(selectedChat.id, msg);
        setReplyingTo(null);
    }

    setNewMessage('');
    setAttachedImage(null);
    loadData();
  };

  const handleDeleteMessage = async (msgId: string) => {
    if (!selectedChat) return;
    if(window.confirm("Apagar esta mensagem?")) {
        await deleteMessage(selectedChat.id, msgId);
        loadData();
    }
    setOpenMessageMenuId(null);
  };

  const handleStartEdit = (msg: Message) => {
    setNewMessage(msg.text || '');
    setEditingMessageId(msg.id);
    setReplyingTo(null);
    setOpenMessageMenuId(null);
    fileInputRef.current?.focus();
  };

  const handleStartReply = (msg: Message) => {
    setReplyingTo(msg);
    setEditingMessageId(null);
    setOpenMessageMenuId(null);
    setNewMessage('');
    fileInputRef.current?.focus();
  };

  const cancelAction = () => {
    setReplyingTo(null);
    setEditingMessageId(null);
    setNewMessage('');
  };

  const handleChangeTheme = async (theme: GroupTheme) => {
    if (!selectedChat || selectedChat.adminId !== currentUser.id) return;
    await updateGroupTheme(selectedChat.id, theme);
    setShowThemeMenu(false);
    loadData();
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat || selectedChat.type === ChatType.GROUP) return;
    const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
    const partner = await findUserById(partnerId!);
    if (partner) setActiveCall({ partner, type });
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab === 'ALL') return true;
    return c.type === filterTab;
  });

  const chatTheme = selectedChat?.theme || 'blue';
  const themeStyles = THEME_CONFIG[chatTheme];

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in">

      {/* Sidebar - Telegram Style */}
      <div className={`w-full md:w-80 lg:w-[360px] flex flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 shrink-0 z-40 transition-all ${selectedChat ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-4 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <button className="p-2 text-gray-400 hover:text-blue-500"><Bars3BottomLeftIcon className="h-6 w-6"/></button>
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">CyBer Chat</h2>
              </div>
              <button 
                onClick={() => onNavigate('create-group')}
                className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-all shadow-lg active:scale-90 flex items-center justify-center"
                title="Criar Novo Grupo"
              >
                <PlusIcon className="h-5 w-5 stroke-[3]" />
              </button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input placeholder="Buscar conversas..." className="w-full pl-11 pr-4 py-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-1 focus:ring-blue-500"/>
           </div>

           <div className="flex gap-2 pb-1 overflow-x-auto no-scrollbar">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
          {filteredConversations.map(chat => {
            const isGroup = chat.type === ChatType.GROUP;
            const lastMsg = chat.messages[chat.messages.length - 1];
            const isActive = selectedChat?.id === chat.id;

            return (
              <button
                key={chat.id}
                onClick={() => setSelectedChat(chat)}
                className={`w-full flex items-center p-3 rounded-2xl transition-all mb-0.5 ${isActive ? 'bg-blue-600 text-white' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
              >
                <div className="relative shrink-0">
                   <img src={chat.groupImage || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-full object-cover border border-black/5 shadow-sm" />
                   {isGroup && <div className="absolute -bottom-0.5 -right-0.5 bg-blue-600 p-0.5 rounded-full border border-white"><UserGroupIcon className="h-2.5 w-2.5 text-white"/></div>}
                </div>
                <div className="ml-3 text-left overflow-hidden flex-1">
                   <div className="flex justify-between items-center mb-0.5">
                      <p className="font-black text-sm truncate uppercase tracking-tighter">{isGroup ? chat.groupName : 'Chat Privado'}</p>
                      {lastMsg && <span className={`text-[8px] font-bold ${isActive ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes()}</span>}
                   </div>
                   <p className={`text-[11px] truncate leading-tight ${isActive ? 'text-blue-100' : 'text-gray-400 font-medium'}`}>
                      {lastMsg ? (lastMsg.isDeleted ? '🚫 Mensagem apagada' : lastMsg.text || '📷 Imagem') : 'Nenhuma mensagem'}
                   </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Chat Area - Telegram UI */}
      <div className={`flex-1 flex flex-col h-full relative ${!selectedChat ? 'hidden md:flex' : 'flex'}`}>
        {selectedChat ? (
          <>
            {/* Header com Tema */}
            <div className={`h-16 flex items-center justify-between px-4 text-white z-30 transition-colors duration-500 ${themeStyles.primary} shadow-lg`}>
               <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-white/80"><ArrowLeftIcon className="h-5 w-5 stroke-[3]"/></button>
                  <div className="flex items-center gap-3">
                     <img src={selectedChat.groupImage || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-full object-cover border-2 border-white/20" />
                     <div className="leading-tight">
                        <h3 className="text-sm font-black uppercase tracking-tight">{selectedChat.groupName || 'Chat Privado'}</h3>
                        <p className="text-[9px] text-white/70 font-bold uppercase">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Online'}</p>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-1">
                  {selectedChat.type === ChatType.PRIVATE && (
                    <button onClick={() => startCall('voice')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PhoneIcon className="h-5 w-5"/></button>
                  )}

                  {/* Seletor de Tema para Admin */}
                  {selectedChat.adminId === currentUser.id && (
                    <div className="relative">
                       <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PaintBrushIcon className="h-5 w-5"/></button>
                       {showThemeMenu && (
                          <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in overflow-hidden">
                             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest p-2 border-b dark:border-white/5">Alterar Tema</p>
                             {(Object.keys(THEME_CONFIG) as GroupTheme[]).map(t => (
                               <button 
                                key={t} 
                                onClick={() => handleChangeTheme(t)}
                                className="w-full flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                               >
                                  <div className={`w-4 h-4 rounded-full ${THEME_CONFIG[t].primary}`} />
                                  <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{t}</span>
                               </button>
                             ))}
                          </div>
                       )}
                    </div>
                  )}
                  <button className="p-2.5 hover:bg-white/10 rounded-full transition-all"><EllipsisVerticalIcon className="h-5 w-5"/></button>
               </div>
            </div>

            {/* Chat Body com Fundo Telegram */}
            <div className={`flex-1 overflow-y-auto p-4 md:p-6 space-y-2 custom-scrollbar relative transition-colors duration-500 ${themeStyles.bg}`}>
               {/* Pattern overlay inspirado no Telegram */}
               <div className="absolute inset-0 opacity-[0.07] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

               <div className="max-w-4xl mx-auto flex flex-col gap-1.5 relative z-10">
                  {selectedChat.messages.map((msg, i) => {
                    const isMine = msg.senderId === currentUser.id;
                    const prevMsg = selectedChat.messages[i-1];
                    const showName = selectedChat.type === ChatType.GROUP && !isMine && (!prevMsg || prevMsg.senderId !== msg.senderId);
                    const isMenuOpen = openMessageMenuId === msg.id;

                    return (
                      <div key={msg.id} className={`flex w-full group relative ${isMine ? 'justify-end' : 'justify-start'}`}>

                         {/* Mensagem Actions (Hover/Menu) */}
                         {!msg.isDeleted && (
                            <div className={`absolute top-0 ${isMine ? 'right-full mr-2' : 'left-full ml-2'} z-20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center`}>
                               <button 
                                 onClick={() => setOpenMessageMenuId(isMenuOpen ? null : msg.id)}
                                 className="p-1 bg-black/20 hover:bg-black/40 rounded-full text-white backdrop-blur-md"
                               >
                                  <ChevronDownIcon className="h-4 w-4" />
                               </button>

                               {/* Dropdown Menu */}
                               {isMenuOpen && (
                                 <div className={`absolute top-full mt-1 ${isMine ? 'right-0 origin-top-right' : 'left-0 origin-top-left'} bg-white dark:bg-[#1a1c23] rounded-xl shadow-xl py-1 w-32 border border-black/5 dark:border-white/10 z-50 animate-scale-in`}>
                                    <button onClick={() => handleStartReply(msg)} className="w-full text-left px-4 py-2 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white">
                                       <ArrowUturnLeftIcon className="h-3 w-3" /> Responder
                                    </button>
                                    {isMine && (
                                       <>
                                          <button onClick={() => handleStartEdit(msg)} className="w-full text-left px-4 py-2 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white">
                                             <PencilIcon className="h-3 w-3" /> Editar
                                          </button>
                                          <button onClick={() => handleDeleteMessage(msg.id)} className="w-full text-left px-4 py-2 hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 flex items-center gap-2 text-xs">
                                             <TrashIcon className="h-3 w-3" /> Apagar
                                          </button>
                                       </>
                                    )}
                                 </div>
                               )}
                            </div>
                         )}

                         <div className={`max-w-[85%] md:max-w-[70%] p-2 rounded-2xl shadow-sm relative ${isMine ? `${themeStyles.bubble} rounded-tr-none text-[#333]` : 'bg-white dark:bg-[#12161f] rounded-tl-none dark:text-white'}`}>

                            {/* Reply Context Bubble */}
                            {msg.replyTo && !msg.isDeleted && (
                               <div className="mb-1 pl-2 border-l-2 border-blue-500 bg-black/5 dark:bg-white/5 rounded-r-md p-1 cursor-pointer opacity-80" onClick={() => {
                                   // Scroll to original message logic could be added here
                               }}>
                                  <p className="text-[9px] font-bold text-blue-600 dark:text-blue-400">{msg.replyTo.senderName}</p>
                                  <p className="text-[10px] truncate max-w-[150px]">{msg.replyTo.text}</p>
                               </div>
                            )}

                            {showName && <p className={`text-[10px] font-black uppercase mb-1 px-1 ${themeStyles.text}`}>Membro #{msg.senderId.slice(-4)}</p>}

                            {msg.isDeleted ? (
                                <div className="italic text-gray-500 text-xs px-2 py-1 flex items-center gap-1">
                                   <XMarkIcon className="h-3 w-3" /> Mensagem apagada
                                </div>
                            ) : (
                                <>
                                    {msg.imageUrl && <img src={msg.imageUrl} className="w-full h-auto rounded-xl mb-1.5" alt="Anexo" />}
                                    <div className="px-1 flex flex-col md:flex-row items-end gap-x-4">
                                       <p className="text-sm font-medium leading-relaxed mb-0.5 break-words min-w-0">
                                          {msg.text} 
                                          {msg.isEdited && <span className="text-[9px] text-gray-400 ml-1 italic">(editado)</span>}
                                       </p>
                                       <div className="flex items-center gap-1 ml-auto shrink-0 mb-[-2px]">
                                          <span className={`text-[9px] font-bold opacity-50 ${isMine ? 'text-[#444]' : 'text-gray-400'}`}>
                                             {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                          </span>
                                          {isMine && <CheckBadgeIcon className={`h-3 w-3 ${themeStyles.text}`} />}
                                       </div>
                                    </div>
                                </>
                            )}
                         </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
               </div>
            </div>

            {/* Input Área */}
            <div className="p-3 md:p-4 bg-white dark:bg-[#12161f] border-t dark:border-white/5 relative">

               {/* Context Banner (Reply/Edit) */}
               {(replyingTo || editingMessageId) && (
                  <div className="absolute bottom-full left-0 w-full bg-gray-50 dark:bg-[#1a1c23] border-t border-black/5 dark:border-white/5 p-3 flex justify-between items-center animate-slide-up">
                     <div className="flex items-center gap-3 px-2 border-l-4 border-blue-500">
                        <div className="text-blue-500">
                           {replyingTo ? <ArrowUturnLeftIcon className="h-5 w-5" /> : <PencilIcon className="h-5 w-5" />}
                        </div>
                        <div>
                           <p className="text-[10px] font-black uppercase text-blue-600 dark:text-blue-400">
                              {replyingTo ? 'Respondendo a' : 'Editando Mensagem'}
                           </p>
                           <p className="text-xs text-gray-600 dark:text-gray-300 truncate max-w-[200px]">
                              {replyingTo ? replyingTo.text : ''}
                           </p>
                        </div>
                     </div>
                     <button onClick={cancelAction} className="p-2 hover:bg-gray-200 dark:hover:bg-white/10 rounded-full text-gray-500"><XMarkIcon className="h-5 w-5" /></button>
                  </div>
               )}

               <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-end gap-2">
                  <div className="flex-1 flex items-center gap-2 bg-gray-50 dark:bg-white/5 p-2 rounded-[1.8rem] border border-black/5 dark:border-white/10 shadow-inner">
                     <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-400 hover:text-blue-500 transition-all shrink-0"><PhotoIcon className="h-6 w-6"/></button>
                     <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) {
                           const r = new FileReader();
                           r.onloadend = () => setAttachedImage(r.result as string);
                           r.readAsDataURL(file);
                        }
                     }} />
                     <textarea 
                       value={newMessage} 
                       onChange={e => setNewMessage(e.target.value)}
                       placeholder="Mensagem..." 
                       rows={1}
                       className="flex-1 bg-transparent border-none outline-none text-sm font-medium dark:text-white py-2 px-1 max-h-32 resize-none no-scrollbar"
                       onInput={(e) => {
                         const target = e.target as HTMLTextAreaElement;
                         target.style.height = 'auto';
                         target.style.height = `${target.scrollHeight}px`;
                       }}
                     />
                  </div>
                  <button 
                    type="submit" 
                    disabled={!newMessage.trim() && !attachedImage} 
                    className={`p-3.5 rounded-full shadow-lg transition-all active:scale-90 disabled:opacity-50 text-white ${themeStyles.primary}`}
                  >
                     {editingMessageId ? <CheckBadgeIcon className="h-6 w-6" /> : <PaperAirplaneIcon className="h-6 w-6 -rotate-45 ml-0.5" />}
                  </button>
               </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-10 bg-white dark:bg-[#0a0c10]">
             <div className="w-40 h-40 bg-gray-50 dark:bg-white/5 rounded-full flex items-center justify-center mb-8">
                <ChatBubbleLeftRightIcon className="h-20 w-20 text-gray-200" />
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter dark:text-white">Central de Mensagens</h3>
             <p className="text-xs text-gray-400 font-black uppercase tracking-widest mt-2 max-w-xs mb-6">Selecione uma conversa ou crie um novo grupo de mentoria.</p>
             <button 
               onClick={() => onNavigate('create-group')}
               className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-3"
             >
               <PlusIcon className="h-5 w-5 stroke-[3]" /> Criar Grupo
             </button>
          </div>
        )}
      </div>

      {activeCall && <CallModal partner={activeCall.partner} type={activeCall.type} onClose={() => setActiveCall(null)} />}
    </div>
  );
};

export default ChatPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType, GroupTheme } from '../types';
import {
  getChats,
  findUserById,
  sendMessage,
  deleteMessage,
  editMessage,
  generateUUID,
  getUsers,
  updateGroupTheme
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  EllipsisVerticalIcon,
  PaintBrushIcon,
  ChevronDownIcon,
  PencilIcon,
  TrashIcon,
  ArrowUturnLeftIcon,
  XMarkIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';

interface ChatPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

const THEME_CONFIG: Record<GroupTheme, { primary: string, secondary: string, bg: string, bubble: string, text: string }> = {
  blue: { primary: 'bg-blue-600', secondary: 'bg-blue-500', bg: 'bg-[#5497d5]', bubble: 'bg-[#effdde]', text: 'text-blue-600' },
  green: { primary: 'bg-emerald-600', secondary: 'bg-emerald-500', bg: 'bg-[#7ebc89]', bubble: 'bg-[#e7fde8]', text: 'text-emerald-600' },
  black: { primary: 'bg-zinc-900', secondary: 'bg-zinc-800', bg: 'bg-[#1a1a1a]', bubble: 'bg-[#2b2b2b]', text: 'text-white' },
  orange: { primary: 'bg-orange-600', secondary: 'bg-orange-500', bg: 'bg-[#edb881]', bubble: 'bg-[#fff5e6]', text: 'text-orange-600' }
};

const ChatPage: React.FC<ChatPageProps> = ({ currentUser, onNavigate }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isCreatingGroup, setIsCreatingGroup] = useState(false);
  const [showThemeMenu, setShowThemeMenu] = useState(false);
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');
  const [activeCall, setActiveCall] = useState<{partner: User, type: 'voice' | 'video'} | null>(null);

  // New States for Actions
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [openMessageMenuId, setOpenMessageMenuId] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadData = useCallback(async () => {
    const allChats = await getChats();
    const userChats = allChats.filter(c => c.participants.includes(currentUser.id));
    setConversations(userChats);

    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    if (editingMessageId) {
        // Handle Edit
        await editMessage(selectedChat.id, editingMessageId, newMessage.trim());
        setEditingMessageId(null);
    } else {
        // Handle New Message
        const replyContext = replyingTo ? {
            id: replyingTo.id,
            text: replyingTo.text || 'Imagem',
            senderName: replyingTo.senderId === currentUser.id ? 'Você' : 'Usuário' // Ideal seria buscar o nome correto
        } : undefined;

        const msg: Message = {
          id: generateUUID(),
          senderId: currentUser.id,
          timestamp: Date.now(),
          text: newMessage.trim() || undefined,
          imageUrl: attachedImage || undefined,
          groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
          replyTo: replyContext
        };

        await sendMessage(selectedChat.id, msg);
        setReplyingTo(null);
    }

    setNewMessage('');
    setAttachedImage(null);
    loadData();
  };

  const handleDeleteMessage = async (msgId: string) => {
    if (!selectedChat) return;
    if(window.confirm("Apagar esta mensagem?")) {
        await deleteMessage(selectedChat.id, msgId);
        loadData();
    }
    setOpenMessageMenuId(null);
  };

  const handleStartEdit = (msg: Message) => {
    setNewMessage(msg.text || '');
    setEditingMessageId(msg.id);
    setReplyingTo(null);
    setOpenMessageMenuId(null);
    fileInputRef.current?.focus();
  };

  const handleStartReply = (msg: Message) => {
    setReplyingTo(msg);
    setEditingMessageId(null);
    setOpenMessageMenuId(null);
    setNewMessage('');
    fileInputRef.current?.focus();
  };

  const cancelAction = () => {
    setReplyingTo(null);
    setEditingMessageId(null);
    setNewMessage('');
  };

  const handleChangeTheme = async (theme: GroupTheme) => {
    if (!selectedChat || selectedChat.adminId !== currentUser.id) return;
    await updateGroupTheme(selectedChat.id, theme);
    setShowThemeMenu(false);
    loadData();
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat || selectedChat.type === ChatType.GROUP) return;
    const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
    const partner = await findUserById(partnerId!);
    if (partner) setActiveCall({ partner, type });
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab === 'ALL') return true;
    return c.type === filterTab;
  });

  const chatTheme = selectedChat?.theme || 'blue';
  const themeStyles = THEME_CONFIG[chatTheme];

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in">

      {/* Sidebar - Telegram Style */}
      <div className={`w-full md:w-80 lg:w-[360px] flex flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 shrink-0 z-40 transition-all ${selectedChat ? 'hidden md:flex' : 'flex'}`}>
        <div className="p-4 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <button className="p-2 text-gray-400 hover:text-blue-500"><Bars3BottomLeftIcon className="h-6 w-6"/></button>
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">CyBer Chat</h2>
              </div>
              <button 
                onClick={() => onNavigate('create-group')}
                className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-all shadow-lg active:scale-90 flex items-center justify-center"
                title="Criar Novo Grupo"
              >
                <PlusIcon className="h-5 w-5 stroke-[3]" />
              </button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input placeholder="Buscar conversas..." className="w-full pl-11 pr-4 py-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-1 focus:ring-blue-500"/>
           </div>

           <div className="flex gap-2 pb-1 overflow-x-auto no-scrollbar">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
          {filteredConversations.map(chat => {
            const isGroup = chat.type === ChatType.GROUP;
            const lastMsg = chat.messages[chat.messages.length - 1];
            const isActive = selectedChat?.id === chat.id;

            return (
              <button
                key={chat.id}
                onClick={() => setSelectedChat(chat)}
                className={`w-full flex items-center p-3 rounded-2xl transition-all mb-0.5 ${isActive ? 'bg-blue-600 text-white' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
              >
                <div className="relative shrink-0">
                   <img src={chat.groupImage || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-full object-cover border border-black/5 shadow-sm" />
                   {isGroup && <div className="absolute -bottom-0.5 -right-0.5 bg-blue-600 p-0.5 rounded-full border border-white"><UserGroupIcon className="h-2.5 w-2.5 text-white"/></div>}
                </div>
                <div className="ml-3 text-left overflow-hidden flex-1">
                   <div className="flex justify-between items-center mb-0.5">
                      <p className="font-black text-sm truncate uppercase tracking-tighter">{isGroup ? chat.groupName : 'Chat Privado'}</p>
                      {lastMsg && <span className={`text-[8px] font-bold ${isActive ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes()}</span>}
                   </div>
                   <p className={`text-[11px] truncate leading-tight ${isActive ? 'text-blue-100' : 'text-gray-400 font-medium'}`}>
                      {lastMsg ? (lastMsg.isDeleted ? '🚫 Mensagem apagada' : lastMsg.text || '📷 Imagem') : 'Nenhuma mensagem'}
                   </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Main Chat Area - Telegram UI */}
      <div className={`flex-1 flex flex-col h-full relative ${!selectedChat ? 'hidden md:flex' : 'flex'}`}>
        {selectedChat ? (
          <>
            {/* Header com Tema */}
            <div className={`h-16 flex items-center justify-between px-4 text-white z-30 transition-colors duration-500 ${themeStyles.primary} shadow-lg`}>
               <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-white/80"><ArrowLeftIcon className="h-5 w-5 stroke-[3]"/></button>
                  <div className="flex items-center gap-3">
                     <img src={selectedChat.groupImage || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-full object-cover border-2 border-white/20" />
                     <div className="leading-tight">
                        <h3 className="text-sm font-black uppercase tracking-tight">{selectedChat.groupName || 'Chat Privado'}</h3>
                        <p className="text-[9px] text-white/70 font-bold uppercase">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Online'}</p>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-1">
                  {selectedChat.type === ChatType.PRIVATE && (
                    <button onClick={() => startCall('voice')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PhoneIcon className="h-5 w-5"/></button>
                  )}

                  {/* Seletor de Tema para Admin */}
                  {selectedChat.adminId === currentUser.id && (
                    <div className="relative">
                       <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PaintBrushIcon className="h-5 w-5"/></button>
                       {showThemeMenu && (
                          <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in overflow-hidden">
                             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest p-2 border-b dark:border-white/5">Alterar Tema</p>
                             {(Object.keys(THEME_CONFIG) as GroupTheme[]).map(t => (
                               <button 
                                key={t} 
                                onClick={() => handleChangeTheme(t)}
                                className="w-full flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                               >
                                  <div className={`w-4 h-4 rounded-full ${THEME_CONFIG[t].primary}`} />
                                  <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{t}</span>
                               </button>
                             ))}
                          </div>
                       )}
                    </div>
                  )}
                  <button className="p-2.5 hover:bg-white/10 rounded-full transition-all"><EllipsisVerticalIcon className="h-5 w-5"/></button>
               </div>
            </div>

            {/* Chat Body com Fundo Telegram */}
            <div className={`flex-1 overflow-y-auto p-4 md:p-6 space-y-2 custom-scrollbar relative transition-colors duration-500 ${themeStyles.bg}`}>
               {/* Pattern overlay inspirado no Telegram */}
               <div className="absolute inset-0 opacity-[0.07] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

               <div className="max-w-4xl mx-auto flex flex-col gap-1.5 relative z-10">
                  {selectedChat.messages.map((msg, i) => {
                    const isMine = msg.senderId === currentUser.id;
                    const prevMsg = selectedChat.messages[i-1];
                    const showName = selectedChat.type === ChatType.GROUP && !isMine && (!prevMsg || prevMsg.senderId !== msg.senderId);
                    const isMenuOpen = openMessageMenuId === msg.id;
                    const isGroupAdmin = selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id;

                    return (
                      <div key={msg.id} className={`flex w-full group relative ${isMine ? 'justify-end' : 'justify-start'}`}>

                         {/* Mensagem Actions (Hover/Menu) */}
                         {!msg.isDeleted && (
                            <div className={`absolute top-0 ${isMine ? 'right-full mr-2' : 'left-full ml-2'} z-20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center`}>
                               <button 
                                 onClick={() => setOpenMessageMenuId(isMenuOpen ? null : msg.id)}
                                 className="p-1 bg-black/20 hover:bg-black/40 rounded-full text-white backdrop-blur-md"
                               >
                                  <ChevronDownIcon className="h-4 w-4" />
                               </button>

                               {/* Dropdown Menu */}
                               {isMenuOpen && (
                                 <div className={`absolute top-full mt-1 ${isMine ? 'right-0 origin-top-right' : 'left-0 origin-top-left'} bg-white dark:bg-[#1a1c23] rounded-xl shadow-xl py-1 w-32 border border-black/5 dark:border-white/10 z-50 animate-scale-in`}>
                                    <button onClick={() => handleStartReply(msg)} className="w-full text-left px-4 py-2 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white">
                                       <ArrowUturnLeftIcon className="h-3 w-3" /> Responder
                                    </button>

                                    {isMine && (
                                       <button onClick={() => handleStartEdit(msg)} className="w-full text-left px-4 py-2 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white">
                                          <PencilIcon className="h-3 w-3" /> Editar
                                       </button>
                                    )}

                                    {/* Excluir: Disponível se for minha mensagem OU se eu for o Admin do Grupo */}
                                    {(isMine || isGroupAdmin) && (
                                      <button onClick={() => handleDeleteMessage(msg.id)} className="w-full text-left px-4 py-2 hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 flex items-center gap-2 text-xs">
                                         <TrashIcon className="h-3 w-3" /> {isGroupAdmin && !isMine ? 'Banir Msg' : 'Apagar'}
                                      </button>
                                    )}
                                 </div>
                               )}
                            </div>
                         )}

                         <div className={`max-w-[85%] md:max-w-[70%] p-2 rounded-2xl shadow-sm relative ${isMine ? `${themeStyles.bubble} rounded-tr-none text-[#333]` : 'bg-white dark:bg-[#12161f] rounded-tl-none dark:text-white'}`}>

                            {/* Reply Context Bubble */}
                            {msg.replyTo && !msg.isDeleted && (
                               <div className="mb-1 pl-2 border-l-2 border-blue-500 bg-black/5 dark:bg-white/5 rounded-r-md p-1 cursor-pointer opacity-80" onClick={() => {
                                   // Scroll to original message logic could be added here
                               }}>
                                  <p className="text-[9px] font-bold text-blue-600 dark:text-blue-400">{msg.replyTo.senderName}</p>
                                  <p className="text-[10px] truncate max-w-[150px]">{msg.replyTo.text}</p>
                               </div>
                            )}

                            {showName && <p className={`text-[10px] font-black uppercase mb-1 px-1 ${themeStyles.text}`}>Membro #{msg.senderId.slice(-4)}</p>}

                            {msg.isDeleted ? (
                                <div className="italic text-gray-500 text-xs px-2 py-1 flex items-center gap-1">
                                   <XMarkIcon className="h-3 w-3" /> Mensagem apagada
                                </div>
                            ) : (
                                <>
                                    {msg.imageUrl && <img src={msg.imageUrl} className="w-full h-auto rounded-xl mb-1.5" alt="Anexo" />}
                                    <div className="px-1 flex flex-col md:flex-row items-end gap-x-4">
                                       <p className="text-sm font-medium leading-relaxed mb-0.5 break-words min-w-0">
                                          {msg.text} 
                                          {msg.isEdited && <span className="text-[9px] text-gray-400 ml-1 italic">(editado)</span>}
                                       </p>
                                       <div className="flex items-center gap-1 ml-auto shrink-0 mb-[-2px]">
                                          <span className={`text-[9px] font-bold opacity-50 ${isMine ? 'text-[#444]' : 'text-gray-400'}`}>
                                             {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                          </span>
                                          {isMine && <CheckBadgeIcon className={`h-3 w-3 ${themeStyles.text}`} />}
                                       </div>
                                    </div>
                                </>
                            )}
                         </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
               </div>
            </div>

            {/* Input Área */}
            <div className="p-3 md:p-4 bg-white dark:bg-[#12161f] border-t dark:border-white/5 relative">

               {/* Context Banner (Reply/Edit) */}
               {(replyingTo || editingMessageId) && (
                  <div className="absolute bottom-full left-0 w-full bg-gray-50 dark:bg-[#1a1c23] border-t border-black/5 dark:border-white/5 p-3 flex justify-between items-center animate-slide-up">
                     <div className="flex items-center gap-3 px-2 border-l-4 border-blue-500">
                        <div className="text-blue-500">
                           {replyingTo ? <ArrowUturnLeftIcon className="h-5 w-5" /> : <PencilIcon className="h-5 w-5" />}
                        </div>
                        <div>
                           <p className="text-[10px] font-black uppercase text-blue-600 dark:text-blue-400">
                              {replyingTo ? 'Respondendo a' : 'Editando Mensagem'}
                           </p>
                           <p className="text-xs text-gray-600 dark:text-gray-300 truncate max-w-[200px]">
                              {replyingTo ? replyingTo.text : ''}
                           </p>
                        </div>
                     </div>
                     <button onClick={cancelAction} className="p-2 hover:bg-gray-200 dark:hover:bg-white/10 rounded-full text-gray-500"><XMarkIcon className="h-5 w-5" /></button>
                  </div>
               )}

               <form onSubmit={handleSend} className="max-w-4xl mx-auto flex items-end gap-2">
                  <div className="flex-1 flex items-center gap-2 bg-gray-50 dark:bg-white/5 p-2 rounded-[1.8rem] border border-black/5 dark:border-white/10 shadow-inner">
                     <button type="button" onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-400 hover:text-blue-500 transition-all shrink-0"><PhotoIcon className="h-6 w-6"/></button>
                     <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) {
                           const r = new FileReader();
                           r.onloadend = () => setAttachedImage(r.result as string);
                           r.readAsDataURL(file);
                        }
                     }} />
                     <textarea 
                       value={newMessage} 
                       onChange={e => setNewMessage(e.target.value)}
                       placeholder="Mensagem..." 
                       rows={1}
                       className="flex-1 bg-transparent border-none outline-none text-sm font-medium dark:text-white py-2 px-1 max-h-32 resize-none no-scrollbar"
                       onInput={(e) => {
                         const target = e.target as HTMLTextAreaElement;
                         target.style.height = 'auto';
                         target.style.height = `${target.scrollHeight}px`;
                       }}
                     />
                  </div>
                  <button 
                    type="submit" 
                    disabled={!newMessage.trim() && !attachedImage} 
                    className={`p-3.5 rounded-full shadow-lg transition-all active:scale-90 disabled:opacity-50 text-white ${themeStyles.primary}`}
                  >
                     {editingMessageId ? <CheckBadgeIcon className="h-6 w-6" /> : <PaperAirplaneIcon className="h-6 w-6 -rotate-45 ml-0.5" />}
                  </button>
               </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-center p-10 bg-white dark:bg-[#0a0c10]">
             <div className="w-40 h-40 bg-gray-50 dark:bg-white/5 rounded-full flex items-center justify-center mb-8">
                <ChatBubbleLeftRightIcon className="h-20 w-20 text-gray-200" />
             </div>
             <h3 className="text-2xl font-black uppercase tracking-tighter dark:text-white">Central de Mensagens</h3>
             <p className="text-xs text-gray-400 font-black uppercase tracking-widest mt-2 max-w-xs mb-6">Selecione uma conversa ou crie um novo grupo de mentoria.</p>
             <button 
               onClick={() => onNavigate('create-group')}
               className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase shadow-xl hover:bg-blue-700 active:scale-95 transition-all flex items-center gap-3"
             >
               <PlusIcon className="h-5 w-5 stroke-[3]" /> Criar Grupo
             </button>
          </div>
        )}
      </div>

      {activeCall && <CallModal partner={activeCall.partner} type={activeCall.type} onClose={() => setActiveCall(null)} />}
    </div>
  );
};

export default ChatPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType, GroupTheme } from '../types';
import {
  getChats,
  findUserById,
  sendMessage,
  deleteMessage,
  editMessage,
  generateUUID,
  getUsers,
  updateGroupTheme
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  EllipsisVerticalIcon,
  PaintBrushIcon,
  ChevronDownIcon,
  PencilIcon,
  TrashIcon,
  ArrowUturnLeftIcon,
  XMarkIcon,
  DocumentDuplicateIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';

interface ChatPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

const THEME_CONFIG: Record<GroupTheme, { primary: string, secondary: string, bg: string, bubble: string, text: string }> = {
  blue: { primary: 'bg-blue-600', secondary: 'bg-blue-500', bg: 'bg-[#73a3c9]', bubble: 'bg-[#effdde]', text: 'text-blue-600' },
  green: { primary: 'bg-emerald-600', secondary: 'bg-emerald-500', bg: 'bg-[#7ebc89]', bubble: 'bg-[#e7fde8]', text: 'text-emerald-600' },
  black: { primary: 'bg-zinc-900', secondary: 'bg-zinc-800', bg: 'bg-[#1a1a1a]', bubble: 'bg-[#2b2b2b]', text: 'text-white' },
  orange: { primary: 'bg-orange-600', secondary: 'bg-orange-500', bg: 'bg-[#edb881]', bubble: 'bg-[#fff5e6]', text: 'text-orange-600' }
};

const ChatPage: React.FC<ChatPageProps> = ({ currentUser, onNavigate }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [showThemeMenu, setShowThemeMenu] = useState(false);
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');
  const [activeCall, setActiveCall] = useState<{partner: User, type: 'voice' | 'video'} | null>(null);

  // States for Actions
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [selectedMessageForAction, setSelectedMessageForAction] = useState<Message | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const loadData = useCallback(async () => {
    const allChats = await getChats();
    const userChats = allChats.filter(c => c.participants.includes(currentUser.id));
    setConversations(userChats);

    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length, selectedChat?.id]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    if (editingMessageId) {
        await editMessage(selectedChat.id, editingMessageId, newMessage.trim());
        setEditingMessageId(null);
    } else {
        const replyContext = replyingTo ? {
            id: replyingTo.id,
            text: replyingTo.text || 'Imagem',
            senderName: replyingTo.senderId === currentUser.id ? 'Você' : 'Usuário'
        } : undefined;

        const msg: Message = {
          id: generateUUID(),
          senderId: currentUser.id,
          timestamp: Date.now(),
          text: newMessage.trim() || undefined,
          imageUrl: attachedImage || undefined,
          groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
          replyTo: replyContext
        };

        await sendMessage(selectedChat.id, msg);
        setReplyingTo(null);
    }

    setNewMessage('');
    setAttachedImage(null);
    loadData();

    // Reset height of textarea
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleAction = (action: 'reply' | 'edit' | 'delete' | 'copy') => {
    if (!selectedMessageForAction || !selectedChat) return;

    const msg = selectedMessageForAction;

    switch (action) {
        case 'reply':
            setReplyingTo(msg);
            setEditingMessageId(null);
            inputRef.current?.focus();
            break;
        case 'edit':
            setNewMessage(msg.text || '');
            setEditingMessageId(msg.id);
            setReplyingTo(null);
            inputRef.current?.focus();
            break;
        case 'delete':
            if(window.confirm("Apagar esta mensagem para todos?")) {
                deleteMessage(selectedChat.id, msg.id).then(loadData);
            }
            break;
        case 'copy':
            if (msg.text) navigator.clipboard.writeText(msg.text);
            break;
    }
    setSelectedMessageForAction(null);
  };

  const cancelAction = () => {
    setReplyingTo(null);
    setEditingMessageId(null);
    setNewMessage('');
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleChangeTheme = async (theme: GroupTheme) => {
    if (!selectedChat || selectedChat.adminId !== currentUser.id) return;
    await updateGroupTheme(selectedChat.id, theme);
    setShowThemeMenu(false);
    loadData();
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat || selectedChat.type === ChatType.GROUP) return;
    const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
    const partner = await findUserById(partnerId!);
    if (partner) setActiveCall({ partner, type });
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab === 'ALL') return true;
    return c.type === filterTab;
  });

  const chatTheme = selectedChat?.theme || 'blue';
  const themeStyles = THEME_CONFIG[chatTheme];

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in">

      {/* 
        SIDEBAR (LISTA DE CHATS)
        - Mobile: Ocupa 100% (w-full) MAS fica 'hidden' se houver um chat selecionado.
        - Desktop: Ocupa largura fixa e sempre visível.
      */}
      <div className={`
        flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 z-40 transition-all
        ${selectedChat ? 'hidden md:flex md:w-80 lg:w-[360px]' : 'flex w-full md:w-80 lg:w-[360px]'}
      `}>
        <div className="p-4 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">Mensagens</h2>
              </div>
              <button 
                onClick={() => onNavigate('create-group')}
                className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-all shadow-lg active:scale-90"
              >
                <PlusIcon className="h-5 w-5 stroke-[3]" />
              </button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input placeholder="Buscar..." className="w-full pl-11 pr-4 py-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-1 focus:ring-blue-500 transition-all"/>
           </div>

           <div className="flex gap-2 pb-1 overflow-x-auto no-scrollbar">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
          {filteredConversations.map(chat => {
            const isGroup = chat.type === ChatType.GROUP;
            const lastMsg = chat.messages[chat.messages.length - 1];
            const isActive = selectedChat?.id === chat.id;

            return (
              <button
                key={chat.id}
                onClick={() => setSelectedChat(chat)}
                className={`w-full flex items-center p-3 rounded-2xl transition-all mb-0.5 ${isActive ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
              >
                <div className="relative shrink-0">
                   <img src={chat.groupImage || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-full object-cover border border-black/5 shadow-sm bg-white" />
                   {isGroup && <div className="absolute -bottom-0.5 -right-0.5 bg-blue-600 p-0.5 rounded-full border border-white"><UserGroupIcon className="h-2.5 w-2.5 text-white"/></div>}
                </div>
                <div className="ml-3 text-left overflow-hidden flex-1">
                   <div className="flex justify-between items-center mb-0.5">
                      <p className={`font-black text-sm truncate uppercase tracking-tighter ${isActive ? 'text-white' : 'dark:text-white'}`}>{isGroup ? chat.groupName : 'Chat Privado'}</p>
                      {lastMsg && <span className={`text-[8px] font-bold ${isActive ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes().toString().padStart(2, '0')}</span>}
                   </div>
                   <p className={`text-[11px] truncate leading-tight ${isActive ? 'text-blue-100' : 'text-gray-400 font-medium'}`}>
                      {lastMsg ? (lastMsg.isDeleted ? '🚫 Mensagem apagada' : lastMsg.text || '📷 Imagem') : 'Nenhuma mensagem'}
                   </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* 
        CHAT AREA (CONVERSA)
        - Mobile: Ocupa 100% se houver chat selecionado.
        - Desktop: Flex-1.
      */}
      <div className={`flex-col h-full relative w-full ${selectedChat ? 'flex' : 'hidden md:flex flex-1'}`}>
        {selectedChat ? (
          <>
            {/* Header com Tema */}
            <div className={`h-16 flex items-center justify-between px-4 text-white z-30 transition-colors duration-500 ${themeStyles.primary} shadow-lg shrink-0`}>
               <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-white/90 hover:bg-white/10 rounded-full"><ArrowLeftIcon className="h-5 w-5 stroke-[3]"/></button>
                  <div className="flex items-center gap-3">
                     <img src={selectedChat.groupImage || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-full object-cover border-2 border-white/20 bg-white" />
                     <div className="leading-tight">
                        <h3 className="text-sm font-black uppercase tracking-tight">{selectedChat.groupName || 'Chat Privado'}</h3>
                        <p className="text-[9px] text-white/80 font-bold uppercase">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Online'}</p>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-1">
                  {selectedChat.type === ChatType.PRIVATE && (
                    <button onClick={() => startCall('voice')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PhoneIcon className="h-5 w-5"/></button>
                  )}

                  {/* Seletor de Tema para Admin */}
                  {selectedChat.adminId === currentUser.id && (
                    <div className="relative">
                       <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PaintBrushIcon className="h-5 w-5"/></button>
                       {showThemeMenu && (
                          <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in overflow-hidden">
                             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest p-2 border-b dark:border-white/5">Alterar Tema</p>
                             {(Object.keys(THEME_CONFIG) as GroupTheme[]).map(t => (
                               <button 
                                key={t} 
                                onClick={() => handleChangeTheme(t)}
                                className="w-full flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                               >
                                  <div className={`w-4 h-4 rounded-full ${THEME_CONFIG[t].primary}`} />
                                  <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{t}</span>
                               </button>
                             ))}
                          </div>
                       )}
                    </div>
                  )}
                  <button className="p-2.5 hover:bg-white/10 rounded-full transition-all"><EllipsisVerticalIcon className="h-5 w-5"/></button>
               </div>
            </div>

            {/* Chat Body com Fundo e Pattern */}
            <div className={`flex-1 overflow-y-auto p-2 md:p-6 custom-scrollbar relative transition-colors duration-500 ${themeStyles.bg}`}>
               <div className="absolute inset-0 opacity-[0.08] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

               <div className="max-w-4xl mx-auto flex flex-col gap-2 relative z-10 pb-4">
                  {selectedChat.messages.map((msg, i) => {
                    const isMine = msg.senderId === currentUser.id;
                    const prevMsg = selectedChat.messages[i-1];
                    const showName = selectedChat.type === ChatType.GROUP && !isMine && (!prevMsg || prevMsg.senderId !== msg.senderId);
                    const isGroupAdmin = selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id;

                    return (
