export const generateUUID = () => crypto.randomUUID();

export const uploadFile = async (file: File, bucketFolder: string): Promise<string> => {
  if (isSupabaseConfigured) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random()}.${fileExt}`;
      const filePath = `${bucketFolder}/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('cyberphone')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('cyberphone').getPublicUrl(filePath);
      return data.publicUrl;
    } catch (e) {
      console.error('Upload falhou:', e);
      throw e; 
    }
  }
  // Fallback Base64 apenas se Supabase NÃO estiver configurado
  return await fileToBase64(file);
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// Generic Local Storage Helpers
const getLocalList = <T>(key: string, defaultData: T[] = []): T[] => {
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultData;
  } catch { return defaultData; }
};

const saveLocalList = <T>(key: string, data: T[]) => {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) { console.warn("Quota LocalStorage excedida"); }
};

