const mapPost = (row: any): Post => ({
  id: row.id,
  userId: row.user_id,
  authorName: 'Carregando...', // Preenchido no join
  type: row.type as PostType,
  timestamp: Number(row.timestamp),
  content: row.content,
  imageUrl: row.image_url,
  likes: row.likes || [],
  comments: row.comments || [],
  shares: row.shares || [],
  saves: row.saves || [],
  isPinned: row.is_pinned,
  isBoosted: row.is_boosted,
  boostExpires: Number(row.boost_expires),
  reel: row.reel_data,
  liveStream: row.live_data,
  backgroundColor: row.background_color,
  textColor: row.text_color,
  fontFamily: row.font_family,
  groupId: row.group_id,
  groupName: row.group_name,
  indicatedUserIds: row.indicated_user_ids || []
});

export const getPosts = async (): Promise<Post[]> => {
  if (isSupabaseConfigured) {
    const { data, error } = await supabase.from('posts').select('*').order('timestamp', { ascending: false }).limit(100);

    if (error) {
        console.error("Erro ao buscar posts:", error);
        return []; 
    }

    if (data && data.length > 0) {
      // Otimização: Buscar autores em lote
      const userIds = [...new Set(data.map(p => p.user_id))];
      const { data: users } = await supabase.from('profiles').select('id, first_name, last_name, profile_picture').in('id', userIds);
      const userMap = new Map((users as any[])?.map(u => [u.id, u]) || []);

      return data.map(row => {
        const p = mapPost(row);
        const u = userMap.get(p.userId);
        if (u) {
          p.authorName = `${u.first_name} ${u.last_name}`;
          p.authorProfilePic = u.profile_picture;
        } else {
          p.authorName = 'Usuário Desconhecido';
        }
        return p;
      });
    }
    return []; // Retorna vazio se não houver posts no banco
  }
  return getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
};

