export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const products = await getProducts();
  const stores = await getStores();

  const newSales: AffiliateSale[] = [];

  for (const item of cartItems) {
    const product = products.find(p => p.id === item.productId);
    if (!product) continue;
    const store = stores.find(s => s.id === product.storeId);
    if (!store) continue;

    const itemTotal = product.price * item.quantity;

    // Create Transaction Record
    const saleId = `sale-${Date.now()}-${item.productId}`;
    const sale: AffiliateSale = {
      id: saleId,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned: affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0,
      saleAmount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      isRated: false,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl,
      isDropshipping: product.isDropshipping,
      supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
    };
    newSales.push(sale);

    // Update Balances
    if (affiliateUserId) {
        await updateUserBalance(affiliateUserId, sale.commissionEarned);
    }
    const net = itemTotal - sale.commissionEarned;
    await updateUserBalance(store.professorId, net);
  }

  if (isSupabaseConfigured) {
    for (const s of newSales) {
        await supabase.from('affiliate_sales').insert({
            id: s.id,
            product_id: s.productId,
            buyer_id: s.buyerId,
            affiliate_user_id: s.affiliateUserId,
            store_id: s.storeId,
            sale_amount: s.saleAmount,
            commission_earned: s.commissionEarned,
            timestamp: s.timestamp,
            status: s.status,
            shipping_address: s.shippingAddress,
            is_dropshipping: s.isDropshipping,
            supplier_cost: s.supplierCost
        });
        await supabase.from('transactions').insert({
            id: generateUUID(),
            user_id: s.buyerId,
            type: TransactionType.PURCHASE,
            amount: -s.saleAmount,
            description: `Compra: ${s.id}`,
            timestamp: Date.now()
        });
    }
  } else {
    const allSales = getLocalList<AffiliateSale>(KEYS.SALES);
    saveLocalList(KEYS.SALES, [...allSales, ...newSales]);
  }
  return true;
};

