export const editMessage = async (chatId: string, messageId: string, newText: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages = chat.messages.map(m => m.id === messageId ? {...m, text: newText, isEdited: true} : m);
        if(isFirebaseConfigured && db) await updateDoc(doc(db, "chats", chatId), { messages: chat.messages });
        else saveLocalList(KEYS.CHATS, chats);
    }
}

export const deleteMessage = async (chatId: string, messageId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages = chat.messages.map(m => m.id === messageId ? {...m, text: '', imageUrl: undefined, isDeleted: true} : m);
        if(isFirebaseConfigured && db) await updateDoc(doc(db, "chats", chatId), { messages: chat.messages });
        else saveLocalList(KEYS.CHATS, chats);
