export const joinGroup = async (groupId: string, userId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === groupId);
    if(chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        if(isFirebaseConfigured && db) await updateDoc(doc(db, "chats", groupId), { participants: chat.participants });
        else saveLocalList(KEYS.CHATS, chats);
    }
}

export const leaveGroup = async (groupId: string, userId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === groupId);
    if(chat) {
        chat.participants = chat.participants.filter(id => id !== userId);
        if(isFirebaseConfigured && db) await updateDoc(doc(db, "chats", groupId), { participants: chat.participants });
        else saveLocalList(KEYS.CHATS, chats);
    }
}

