import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

// Tenta pegar configuração salva no navegador (via tela de Ajustes)
const getStoredConfig = () => {
  if (typeof window === 'undefined') return null;
  try {
    const stored = localStorage.getItem('cyber_firebase_config');
    return stored ? JSON.parse(stored) : null;
  } catch { return null; }
};

const storedConfig = getStoredConfig();

const firebaseConfig = storedConfig || {
  apiKey: process.env.FIREBASE_API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

// Verifica se a configuração mínima existe (API Key e Project ID são essenciais)
export const isFirebaseConfigured = !!(firebaseConfig.apiKey && firebaseConfig.projectId && firebaseConfig.apiKey !== '' && !firebaseConfig.apiKey.includes('undefined'));

let app;
let auth;
let db;
let storage;

if (isFirebaseConfigured) {
  try {
    app = initializeApp(firebaseConfig);
    auth = getAuth(app);
    db = getFirestore(app);
    storage = getStorage(app);
    console.log("Firebase conectado com sucesso via", storedConfig ? "Configuração Manual" : "Variáveis de Ambiente");
  } catch (error) {
    console.error("Erro ao inicializar Firebase. Verifique suas chaves:", error);
  }
} else {
  console.log("Firebase não configurado. Rodando em modo OFFLINE (LocalStorage). Vá em Ajustes > Banco de Dados para configurar.");
}

export { auth, db, storage };

