import { initializeApp } from "firebase/app";
import { getAuth } from "firebase/auth";
import { getFirestore } from "firebase/firestore";
import { getStorage } from "firebase/storage";

// Suas chaves de configuração do Firebase
const firebaseConfig = {
  apiKey: "AIzaSyC5Xc3sjmqtG0HG-poEYvkxEahvYog2lbY",
  authDomain: "studio-3671322177-4a776.firebaseapp.com",
  projectId: "studio-3671322177-4a776",
  storageBucket: "studio-3671322177-4a776.firebasestorage.app",
  messagingSenderId: "988619107363",
  appId: "1:988619107363:web:8e996a806cdcaaad9b9596"
};

// Indica que o Firebase está configurado
export const isFirebaseConfigured = true;

let app;
let auth;
let db;
let storage;

try {
  // Inicializa o Firebase com as suas chaves
  app = initializeApp(firebaseConfig);

  // Inicializa os serviços (Autenticação, Banco de Dados, Arquivos)
  auth = getAuth(app);
  db = getFirestore(app);
  storage = getStorage(app);

  console.log("✅ Firebase conectado com sucesso ao projeto: studio-3671322177-4a776");
} catch (error) {
  console.error("❌ Erro ao conectar no Firebase:", error);
}

export { auth, db, storage };

import { 
  User, Post, ChatConversation, AdCampaign, UserType, Store, Product, 
  AffiliateSale, Comment, ShippingAddress, ProductType, AudioTrack, 
  Notification, NotificationType, CartItem, ProductRating, OrderStatus, 
  CyberEvent, Story, ContentReport, SystemLog, Transaction, GlobalSettings, 
  TransactionType, Message, ChatType, GroupTheme, PostType
} from '../types';
import { auth, db, isFirebaseConfigured, storage } from './firebaseClient';
import { 
  createUserWithEmailAndPassword, 
  signInWithEmailAndPassword, 
  updatePassword,
  signOut 
} from "firebase/auth";
import { 
  doc, 
  setDoc, 
  getDoc, 
  updateDoc, 
  collection, 
  getDocs, 
  query, 
  where 
} from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";

import { 
  DEFAULT_PROFILE_PIC, 
  DEFAULT_USERS, 
  DEFAULT_POSTS, 
  DEFAULT_ADS, 
  DEFAULT_STORES, 
  DEFAULT_PRODUCTS, 
  DEFAULT_AUDIO_TRACKS 
} from '../data/constants';

// --- CONSTANTES DE LOCAL STORAGE (APENAS PARA MODO OFFLINE/FALLBACK) ---
const KEYS = {
  USERS: 'cyberphone_users',
  POSTS: 'cyberphone_posts',
  CHATS: 'cyberphone_chats',
  ADS: 'cyberphone_ads',
  STORES: 'cyberphone_stores',
  PRODUCTS: 'cyberphone_products',
  SALES: 'cyberphone_affiliate_sales',
  NOTIFICATIONS: 'cyberphone_notifications',
  CURRENT_USER: 'cyberphone_current_user_id',
  EVENTS: 'cyberphone_events',
  STORIES: 'cyberphone_stories',
  CART: 'cyberphone_cart',
  TRANSACTIONS: 'cyberphone_transactions',
  THEME: 'cyberphone_theme_color'
};

// --- HELPER FUNCTIONS ---

export const generateUUID = () => crypto.randomUUID();

export const uploadFile = async (file: File, bucketFolder: string): Promise<string> => {
  if (isFirebaseConfigured && storage) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${generateUUID()}.${fileExt}`;
      const storageRef = ref(storage, `${bucketFolder}/${fileName}`);

      await uploadBytes(storageRef, file);
      const url = await getDownloadURL(storageRef);
      return url;
    } catch (e) {
      console.error('Upload Firebase falhou, usando fallback local:', e);
    }
  }
  return await fileToBase64(file);
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// Generic Local Storage Helpers (Fallback)
const getLocalList = <T>(key: string, defaultData: T[] = []): T[] => {
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultData;
  } catch { return defaultData; }
};

const saveLocalList = <T>(key: string, data: T[]) => {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) { console.warn("Quota LocalStorage excedida"); }
};

// --- AUTH & USERS (MIGRADO PARA FIREBASE) ---

export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.trim();

  // MODO ONLINE: Firebase
  if (isFirebaseConfigured && auth && db) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const uid = userCredential.user.uid;

      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data() as User;
        return { ...userData, id: uid };
      } else {
        throw new Error("Perfil de usuário não encontrado no banco de dados.");
      }
    } catch (error: any) {
      console.error("Erro login Firebase:", error);
      let msg = "Erro ao fazer login.";
      if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
        msg = "Email ou senha incorretos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas falhas. Tente novamente mais tarde.";
      }
      throw new Error(msg);
    }
  }

  // MODO OFFLINE (LocalStorage Fallback)
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
  const user = users.find(u => u.email.toLowerCase() === email.toLowerCase());
  if (user) return user; 

  throw new Error("Usuário não encontrado (Modo Offline). Verifique sua conexão ou credenciais.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.trim();

  if (isFirebaseConfigured && auth && db) {
    try {
      console.log("Iniciando registro no Firebase para:", email);

      // 1. Criar Auth no Firebase
      const userCredential = await createUserWithEmailAndPassword(auth, email, userData.password);
      const uid = userCredential.user.uid;
      console.log("Auth criado com sucesso. UID:", uid);

      // 2. Montar objeto do usuário
      const newUser: User = {
        id: uid, 
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
        balance: 0,
        credentials: userData.credentials,
        bio: userData.bio,
        verificationFileUrl: userData.verificationFileUrl,
        isAdmin: false,
        isVerified: false,
        followers: [],
        followedUsers: [],
        storeId: userData.userType === UserType.CREATOR ? generateUUID() : undefined
      };

      // 3. Salvar perfil no Firestore (Com Timeout para detectar se o DB não existe)
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error("TIMEOUT_DB")), 8000)
      );

      const firestorePromise = setDoc(doc(db, "users", uid), newUser);

      console.log("Salvando dados no Firestore...");
      await Promise.race([firestorePromise, timeoutPromise]);
      console.log("Dados salvos no Firestore.");

      return newUser;
    } catch (error: any) {
      console.error("Erro detalhado registro Firebase:", error);
      let msg = "Erro ao criar conta: " + error.message;

      if (error.code === 'auth/operation-not-allowed') {
        msg = "ERRO DE CONFIGURAÇÃO: Você precisa ativar o login por 'Email/Password' no console do Firebase (Menu Authentication).";
      } else if (error.message === "TIMEOUT_DB") {
        msg = "ERRO DE CONFIGURAÇÃO: O Banco de Dados (Firestore Database) não foi criado no console do Firebase ou está inacessível.";
      } else if (error.code === 'auth/email-already-in-use') {
        msg = "Este email já está cadastrado.";
      } else if (error.code === 'auth/weak-password') {
        msg = "A senha deve ter pelo menos 6 caracteres.";
      } else if (error.code === 'permission-denied') {
        msg = "ERRO DE PERMISSÃO: Verifique as regras do Firestore (Rules) no console. Tente iniciar em 'Test Mode'.";
      }

      throw new Error(msg);
    }
  } else {
    // LocalStorage Fallback
    const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    if (users.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      throw new Error('Email já cadastrado (Modo Local).');
    }
    const newUser: User = {
      id: generateUUID(),
      ...userData,
      email,
      followers: [],
      followedUsers: [],
      balance: 0
    };
    users.push(newUser);
    saveLocalList(KEYS.USERS, users);
    return newUser;
  }
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (isFirebaseConfigured && db) {
    try {
      const userDoc = await getDoc(doc(db, "users", userId));
      if (userDoc.exists()) {
        return userDoc.data() as User;
      }
      return undefined;
    } catch (e) {
      console.error("Erro buscar user:", e);
      return undefined;
    }
  }
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (isFirebaseConfigured && db) {
    try {
      const querySnapshot = await getDocs(collection(db, "users"));
      return querySnapshot.docs.map(doc => doc.data() as User);
    } catch (e) { 
        console.error("Erro ao listar usuários:", e);
        return []; 
    }
  }
  return getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
};

export const updateUser = async (user: User) => {
  if (isFirebaseConfigured && db) {
    await updateDoc(doc(db, "users", user.id), { ...user });
  } else {
    let users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    users = users.map(u => u.id === user.id ? { ...u, ...user } : u);
    saveLocalList(KEYS.USERS, users);
  }
};

export const saveCurrentUser = (userId: string | null) => {
  if (userId) localStorage.setItem(KEYS.CURRENT_USER, userId);
  else localStorage.removeItem(KEYS.CURRENT_USER);

  if (!userId && isFirebaseConfigured && auth) {
      signOut(auth).catch(err => console.error("Erro ao deslogar firebase:", err));
  }
};

export const getCurrentUserId = (): string | null => localStorage.getItem(KEYS.CURRENT_USER);

// --- OUTRAS FUNÇÕES (MANTIDAS HÍBRIDAS PARA SIMPLIFICAR A MIGRAÇÃO INICIAL) ---

export const getPosts = async (): Promise<Post[]> => {
    return getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
};

export const addPost = async (post: Post) => {
    const posts = getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
    saveLocalList(KEYS.POSTS, [post, ...posts]);
};

export const updatePost = async (post: Post) => {
    let posts = getLocalList<Post>(KEYS.POSTS, DEFAULT_POSTS);
    posts = posts.map(p => p.id === post.id ? post : p);
    saveLocalList(KEYS.POSTS, posts);
};

export const deletePost = async (pid: string) => {
    saveLocalList(KEYS.POSTS, getLocalList<Post>(KEYS.POSTS).filter(p => p.id !== pid));
};

export const updatePostLikes = async (postId: string, userId: string) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    if (post.likes.includes(userId)) post.likes = post.likes.filter(id => id !== userId);
    else post.likes.push(userId);
    await updatePost(post);
  }
};

export const addPostComment = async (postId: string, comment: Comment) => {
  const posts = await getPosts();
  const post = posts.find(p => p.id === postId);
  if (post) {
    post.comments = post.comments || [];
    post.comments.push(comment);
    await updatePost(post);
  }
};

// --- CHATS (Híbrido) ---
export const getChats = async (): Promise<ChatConversation[]> => getLocalList<ChatConversation>(KEYS.CHATS);

export const createGroup = async (name: string, members: string[], adminId: string, desc: string, theme: GroupTheme, imageFile?: File, isPublic = false) => {
  let imageUrl = '';
  if (imageFile) imageUrl = await uploadFile(imageFile, 'groups');

  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.GROUP,
    participants: [...members, adminId],
    messages: [],
    groupName: name,
    groupImage: imageUrl,
    adminId,
    description: desc,
    theme,
    isPublic
  };
  const chats = getLocalList<ChatConversation>(KEYS.CHATS);
  saveLocalList(KEYS.CHATS, [...chats, newChat]);
  return newChat;
};

export const sendMessage = async (chatId: string, msg: Message) => {
  const chats = await getChats();
  const chat = chats.find(c => c.id === chatId);
  if (chat) {
    chat.messages.push(msg);
    saveLocalList(KEYS.CHATS, chats);
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages = chat.messages.map(m => m.id === messageId ? {...m, text: newText, isEdited: true} : m);
        saveLocalList(KEYS.CHATS, chats);
    }
}

export const deleteMessage = async (chatId: string, messageId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === chatId);
    if(chat) {
        chat.messages = chat.messages.map(m => m.id === messageId ? {...m, text: '', imageUrl: undefined, isDeleted: true} : m);
        saveLocalList(KEYS.CHATS, chats);
    }
}

export const joinGroup = async (groupId: string, userId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === groupId);
    if(chat && !chat.participants.includes(userId)) {
        chat.participants.push(userId);
        saveLocalList(KEYS.CHATS, chats);
    }
}

export const leaveGroup = async (groupId: string, userId: string) => {
    const chats = await getChats();
    const chat = chats.find(c => c.id === groupId);
    if(chat) {
        chat.participants = chat.participants.filter(id => id !== userId);
        saveLocalList(KEYS.CHATS, chats);
    }
}

export const deleteChat = async (chatId: string) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    saveLocalList(KEYS.CHATS, chats.filter(c => c.id !== chatId));
}

export const updateGroupTheme = async (groupId: string, theme: GroupTheme) => {
    const chats = getLocalList<ChatConversation>(KEYS.CHATS);
    const chat = chats.find(c => c.id === groupId);
    if(chat) { chat.theme = theme; saveLocalList(KEYS.CHATS, chats); }
}

// --- OUTROS DADOS ---
export const getAds = async (): Promise<AdCampaign[]> => getLocalList(KEYS.ADS, DEFAULT_ADS);
export const saveAds = async (ads: AdCampaign[]) => saveLocalList(KEYS.ADS, ads);

export const getStores = async (): Promise<Store[]> => getLocalList(KEYS.STORES, DEFAULT_STORES);
export const saveStores = async (stores: Store[]) => saveLocalList(KEYS.STORES, stores);
export const updateStore = async (store: Store) => {
    let stores = await getStores();
    stores = stores.map(s => s.id === store.id ? store : s);
    saveStores(stores);
}

export const getProducts = async (): Promise<Product[]> => getLocalList(KEYS.PRODUCTS, DEFAULT_PRODUCTS);
export const saveProducts = async (products: Product[]) => saveLocalList(KEYS.PRODUCTS, products);
export const adminDeleteProduct = async (id: string) => {
    const products = await getProducts();
    saveProducts(products.filter(p => p.id !== id));
}

export const getAffiliateSales = async (): Promise<AffiliateSale[]> => getLocalList(KEYS.SALES);
export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  const products = await getProducts();
  const stores = await getStores();
  const newSales: AffiliateSale[] = [];

  for (const item of cartItems) {
    const product = products.find(p => p.id === item.productId);
    if (!product) continue;
    const store = stores.find(s => s.id === product.storeId);
    if (!store) continue;

    const itemTotal = product.price * item.quantity;

    const sale: AffiliateSale = {
      id: `sale-${Date.now()}-${item.productId}`,
      productId: item.productId,
      buyerId,
      affiliateUserId: affiliateUserId || '',
      storeId: product.storeId,
      commissionEarned: affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0,
      saleAmount: itemTotal,
      timestamp: Date.now(),
      status: OrderStatus.WAITLIST,
      isRated: false,
      shippingAddress,
      digitalContentUrl: product.digitalContentUrl,
      isDropshipping: product.isDropshipping,
      supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
    };
    newSales.push(sale);

    if (affiliateUserId) await updateUserBalance(affiliateUserId, sale.commissionEarned);
    const net = itemTotal - sale.commissionEarned;
    await updateUserBalance(store.professorId, net);
  }

  const allSales = await getAffiliateSales();
  saveLocalList(KEYS.SALES, [...allSales, ...newSales]);
  return true;
};

// --- UTILS ---
export const getStories = async (): Promise<Story[]> => getLocalList(KEYS.STORIES);
export const addStory = async (uId: string, item: any) => {
    const stories = await getStories();
    const user = await findUserById(uId);
    if (!user) return;
    let userStory = stories.find(s => s.userId === uId);
    if (!userStory) {
      userStory = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
      stories.push(userStory);
    }
    userStory.items.push({ ...item, id: generateUUID(), timestamp: Date.now() });
    saveLocalList(KEYS.STORIES, stories);
}

