export const generateUUID = () => crypto.randomUUID();

export const uploadFile = async (file: File, bucketFolder: string): Promise<string> => {
  if (isFirebaseConfigured && storage) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${generateUUID()}.${fileExt}`;
      const storageRef = ref(storage, `${bucketFolder}/${fileName}`);

      await uploadBytes(storageRef, file);
      const url = await getDownloadURL(storageRef);
      return url;
    } catch (e) {
      console.error('Upload Firebase falhou, usando fallback local:', e);
    }
  }
  return await fileToBase64(file);
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// Generic Local Storage Helpers (Fallback)
const getLocalList = <T>(key: string, defaultData: T[] = []): T[] => {
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultData;
  } catch { return defaultData; }
};

const saveLocalList = <T>(key: string, data: T[]) => {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) { console.warn("Quota LocalStorage excedida"); }
};

// --- AUTH & USERS (MIGRADO PARA FIREBASE) ---

export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.trim();

  // MODO ONLINE: Firebase
  if (isFirebaseConfigured && auth && db) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const uid = userCredential.user.uid;

      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data() as User;
        return { ...userData, id: uid };
      } else {
        throw new Error("Perfil de usuário não encontrado no banco de dados.");
      }
    } catch (error: any) {
      console.error("Erro login Firebase:", error);
      let msg = "Erro ao fazer login.";
      if (error.code === 'auth/invalid-credential' || error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password') {
        msg = "Email ou senha incorretos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas falhas. Tente novamente mais tarde.";
      }
      throw new Error(msg);
    }
  }

  // MODO OFFLINE (LocalStorage Fallback)
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
  const user = users.find(u => u.email.toLowerCase() === email.toLowerCase());
  if (user) return user; 

  throw new Error("Usuário não encontrado (Modo Offline). Verifique sua conexão ou credenciais.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.trim();

  if (isFirebaseConfigured && auth && db) {
    try {
      console.log("Iniciando registro no Firebase para:", email);

      // 1. Criar Auth no Firebase
      const userCredential = await createUserWithEmailAndPassword(auth, email, userData.password);
      const uid = userCredential.user.uid;
      console.log("Auth criado com sucesso. UID:", uid);

      // 2. Montar objeto do usuário (CORREÇÃO: Usar null em vez de undefined)
      // O Firestore rejeita undefined, mas aceita null.
      const newUser: User = {
        id: uid, 
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
        balance: 0,
        // Usar null coalesce operator (??) ou OR (||) para garantir que não vá undefined
        credentials: userData.credentials || null,
        bio: userData.bio || "",
        verificationFileUrl: userData.verificationFileUrl || null,
        isAdmin: false,
        isVerified: false,
        followers: [],
        followedUsers: [],
        storeId: userData.userType === UserType.CREATOR ? generateUUID() : null
      } as any; // Cast as any para permitir nulls em campos opcionais no momento do salvamento

      // 3. Salvar perfil no Firestore (Com Timeout para detectar se o DB não existe)
      const timeoutPromise = new Promise((_, reject) => 
        setTimeout(() => reject(new Error("TIMEOUT_DB")), 8000)
      );

      const firestorePromise = setDoc(doc(db, "users", uid), newUser);

      console.log("Salvando dados no Firestore...");
      await Promise.race([firestorePromise, timeoutPromise]);
      console.log("Dados salvos no Firestore.");

      return newUser;
    } catch (error: any) {
      console.error("Erro detalhado registro Firebase:", error);
      let msg = "Erro ao criar conta: " + error.message;

      if (error.code === 'auth/operation-not-allowed') {
        msg = "ERRO DE CONFIGURAÇÃO: Você precisa ativar o login por 'Email/Password' no console do Firebase (Menu Authentication).";
      } else if (error.message === "TIMEOUT_DB") {
        msg = "ERRO DE CONFIGURAÇÃO: O Banco de Dados (Firestore Database) não foi criado no console do Firebase ou está inacessível.";
      } else if (error.code === 'auth/email-already-in-use') {
        msg = "Este email já está cadastrado.";
      } else if (error.code === 'auth/weak-password') {
        msg = "A senha deve ter pelo menos 6 caracteres.";
      } else if (error.code === 'permission-denied') {
        msg = "ERRO DE PERMISSÃO: Verifique as regras do Firestore (Rules) no console. Tente iniciar em 'Test Mode'.";
      }

      throw new Error(msg);
    }
  } else {
    // LocalStorage Fallback
    const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    if (users.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      throw new Error('Email já cadastrado (Modo Local).');
    }
    const newUser: User = {
      id: generateUUID(),
      ...userData,
      email,
      followers: [],
      followedUsers: [],
      balance: 0
    };
    users.push(newUser);
    saveLocalList(KEYS.USERS, users);
    return newUser;
  }
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (isFirebaseConfigured && db) {
    try {
      const userDoc = await getDoc(doc(db, "users", userId));
      if (userDoc.exists()) {
        return userDoc.data() as User;
      }
      return undefined;
    } catch (e) {
      console.error("Erro buscar user:", e);
      return undefined;
    }
  }
  const users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
  return users.find(u => u.id === userId);
};

export const getUsers = async (): Promise<User[]> => {
  if (isFirebaseConfigured && db) {
    try {
      const querySnapshot = await getDocs(collection(db, "users"));
      return querySnapshot.docs.map(doc => doc.data() as User);
    } catch (e) { 
        console.error("Erro ao listar usuários:", e);
        return []; 
    }
  }
  return getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
};

export const updateUser = async (user: User) => {
  if (isFirebaseConfigured && db) {
    // Garantir que não envie undefined na atualização também
    const safeUser = JSON.parse(JSON.stringify(user)); // Remove undefineds automaticamente ou clones
    await updateDoc(doc(db, "users", user.id), safeUser);
  } else {
    let users = getLocalList<User>(KEYS.USERS, DEFAULT_USERS);
    users = users.map(u => u.id === user.id ? { ...u, ...user } : u);
    saveLocalList(KEYS.USERS, users);
  }
};

