export const generateUUID = () => crypto.randomUUID();

// Helper para SHA-1 (Necessário para assinar upload do Cloudinary no frontend)
async function sha1(str: string) {
  const enc = new TextEncoder();
  const hash = await crypto.subtle.digest('SHA-1', enc.encode(str));
  return Array.from(new Uint8Array(hash))
    .map(v => v.toString(16).padStart(2, '0'))
    .join('');
}

export const uploadFile = async (file: File, bucketFolder: string): Promise<string> => {
  // 1. Tenta Cloudinary (Prioridade definida pelo usuário)
  try {
    const timestamp = Math.round((new Date()).getTime() / 1000);
    // Parâmetros para assinatura (apenas timestamp e public_id se houver, ou outros params ordenados)
    const paramsToSign = `timestamp=${timestamp}${CLOUDINARY_API_SECRET}`;
    const signature = await sha1(paramsToSign);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('api_key', CLOUDINARY_API_KEY);
    formData.append('timestamp', timestamp.toString());
    formData.append('signature', signature);
    // formData.append('folder', bucketFolder); // Pasta opcional no Cloudinary

    const resourceType = file.type.startsWith('video/') ? 'video' : 'image';
    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/${resourceType}/upload`, {
      method: 'POST',
      body: formData
    });

    const data = await response.json();
    if (data.secure_url) {
      return data.secure_url;
    } else {
      console.warn("Erro Cloudinary:", data);
      throw new Error("Falha no upload Cloudinary");
    }
  } catch (cloudinaryError) {
    console.error('Upload Cloudinary falhou, tentando Firebase/Local:', cloudinaryError);
  }

  // 2. Fallback para Firebase Storage
  if (isFirebaseConfigured && storage) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${generateUUID()}.${fileExt}`;
      const storageRef = ref(storage, `${bucketFolder}/${fileName}`);

      await uploadBytes(storageRef, file);
      const url = await getDownloadURL(storageRef);
      return url;
    } catch (e) {
      console.error('Upload Firebase falhou, usando fallback local:', e);
    }
  }

  // 3. Último recurso: Base64
  return await fileToBase64(file);
};

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

// Generic Local Storage Helpers (Fallback)
const getLocalList = <T>(key: string, defaultData: T[] = []): T[] => {
  try {
    const data = localStorage.getItem(key);
    return data ? JSON.parse(data) : defaultData;
  } catch { return defaultData; }
};

const saveLocalList = <T>(key: string, data: T[]) => {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) { console.warn("Quota LocalStorage excedida"); }
};

