Encontrei esse código /**
 * Core Philosophy:
 * This ruleset enforces a strict user-ownership model. All user-generated content,
 * including profiles and posts, is stored in a path structure that ties it directly
 * to the authenticated user's ID (`/users/{userId}`). This ensures that users can only
 * access and modify their own data.
 *
 * Data Structure:
 * - /users/{userId}: Stores a user's public profile. Only the owner can write to it.
 * - /users/{userId}/posts/{postId}: A subcollection for posts, ensuring ownership is
 *   inherited from the path.
 * - /followers/{followerId}_{followedId}: A top-level collection tracks follow
 *   relationships using a composite document ID for efficient lookups. This structure
 *   is designed to be performant and avoids complex queries in security rules.
 *
 * Key Security Decisions:
 * - Strict Ownership: All create, update, and delete operations are restricted to the
 *   data owner, verified via `request.auth.uid`.
 * - No User Listing: Listing the top-level `/users` collection is explicitly disallowed
 *   to protect user privacy and prevent data scraping.
 * - Follower Management: A user can create or delete a "follow" relationship (where
 *   they are the follower), but they cannot modify relationships on behalf of others.
 * - Public Read on Follows: Any signed-in user can check for the existence of a single
 *   follower relationship (`get`), but listing the entire follower graph is disabled.
 *
 * Denormalization for Authorization:
 * This ruleset relies on data denormalization for fast, secure, and cost-effective
 * authorization checks, avoiding slow and expensive `get()` calls.
 * - Post documents (`/users/{userId}/posts/{postId}`) contain a denormalized `authorId`
 *   which is validated against the path's `{userId}` on creation to ensure consistency.
 * - Follower documents (`/followers/...`) contain `followerId` and `followedId`, which
 *   are validated against the composite document ID.
 *
 * Structural Segregation:
 * User-specific data (posts) is segregated into a private subcollection under the
 * user's document (`/users/{userId}/posts`). This is more secure and performant for
 * list operations than using a single global collection with owner-based query filters.
 */
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // -------------------------------------------------------------------------
    // Helper Functions
    // -------------------------------------------------------------------------

    /**
     * Checks if a user is authenticated.
     */
    function isSignedIn() {
      return request.auth != null;
    }

    /**
     * Checks if the currently authenticated user's UID matches the provided userId.
     * This is the primary function for verifying document ownership.
     */
    function isOwner(userId) {
      return isSignedIn() && request.auth.uid == userId;
    }

    /**
     * Checks for ownership on an existing document. Used for update and delete
     * operations to prevent acting on non-existent data.
     */
    function isExistingOwner(userId) {
      return isOwner(userId) && resource != null;
    }

    /**
     * Validates that a UserProfile document being created contains a `uid` field
     * that matches the user's auth UID and the document's path.
     */
    function hasValidUserProfileCreateData(userId) {
      return request.resource.data.uid == userId;
    }

    /**
     * Enforces immutability of the UserProfile's unique identifier upon update.
     */
    function hasValidUserProfileUpdateData() {
      return request.resource.data.uid == resource.data.uid;
    }

    /**
     * Validates that a Post document being created contains an `authorId` field
     * that matches the user's auth UID from the document path.
     */
    function hasValidPostCreateData(userId) {
      return request.resource.data.authorId == userId;
    }

    /**
     * Enforces immutability of the Post's `authorId` upon update.
     */
    function hasValidPostUpdateData() {
      return request.resource.data.authorId == resource.data.authorId;
    }

    /**
     * Checks if the requester is the "follower" based on the composite document ID.
     * e.g., for "userA_userB", this is true if the requester is userA.
     */
    function isFollowerInPath(followerDocId) {
      let parts = followerDocId.split('_');
      return parts.size() == 2 && request.auth.uid == parts[0];
    }

    /**
     * Validates the integrity of a new follower document, ensuring its internal IDs
     * match the composite document ID derived from the path.
     */
    function hasValidFollowerCreateData(followerDocId) {
      let parts = followerDocId.split('_');
      let incomingData = request.resource.data;
      return parts.size() == 2 
          && incomingData.followerId == parts[0]
          && incomingData.followedId == parts[1];
    }

    // -------------------------------------------------------------------------
    // Collection Rules
    // -------------------------------------------------------------------------

    /**
     * @description Manages user profiles. Only the owner can create, update, or
     *              delete their own profile. Reading is also restricted to the owner.
     * @path /users/{userId}
     * @allow (create) A new user `auth.uid: 'user123'` creating their own profile at `/users/user123`.
     * @deny (get) A user `auth.uid: 'user456'` trying to read the profile at `/users/user123`.
     * @deny (list) Any user trying to list the entire `/users` collection.
     * @principle Restricts access to a user's own data tree and prevents enumeration of all users.
     */
    match /users/{userId} {
      allow get: if isOwner(userId);
      allow list: if false; // Critically disallows listing all users
      allow create: if isOwner(userId) && hasValidUserProfileCreateData(userId);
      allow update: if isExistingOwner(userId) && hasValidUserProfileUpdateData();
      allow delete: if isExistingOwner(userId);
    }

    /**
     * @description Manages user posts, which are stored in a subcollection.
     *              Only the user who owns the parent profile can manage these posts.
     * @path /users/{userId}/posts/{postId}
     * @allow (create) User `auth.uid: 'user123'` creating a post at `/users/user123/posts/postABC`.
     * @allow (list) User `auth.uid: 'user123'` listing all their posts at `/users/user123/posts`.
     * @deny (update) User `auth.uid: 'user456'` trying to update a post at `/users/user123/posts/postABC`.
     * @principle Enforces inherited ownership from the parent document path.
     */
    match /users/{userId}/posts/{postId} {
      allow get: if isOwner(userId);
      allow list: if isOwner(userId);
      allow create: if isOwner(userId) && hasValidPostCreateData(userId);
      allow update: if isExistingOwner(userId) && hasValidPostUpdateData();
      allow delete: if isExistingOwner(userId);
    }

    /**
     * @description Manages follower relationships. The document ID is a composite key
     *              of `{followerId}_{followedId}` for direct lookups.
     * @path /followers/{followerDocId}
     * @allow (create) User `auth.uid: 'userA'` creating `/followers/userA_userB` to follow userB.
     * @allow (get) Any signed-in user checking if userA follows userB.
     * @deny (create) User `auth.uid: 'userC'` trying to create `/followers/userA_userB`.
     * @deny (delete) User `auth.uid: 'userB'` trying to delete `/followers/userA_userB` (cannot force an unfollow).
     * @deny (list) Any user trying to list the entire `/followers` collection to scrape the social graph.
     * @principle Allows users to manage their outgoing relationships ("following") but not incoming ones ("followers").
     */
    match /followers/{followerDocId} {
      allow get: if isSignedIn();
      allow list: if false; // Prevents scraping the entire social graph
      allow create: if isFollowerInPath(followerDocId) && hasValidFollowerCreateData(followerDocId);
      allow update: if false; // A follow relationship is binary; it either exists or it doesn't.
      allow delete: if isFollowerInPath(followerDocId) && resource != null;
    }
  }
}

Esse código que você encontrou é um exemplo de **arquitetura de dados aninhada** (Subcollections) com segurança extremamente restrita.

**⚠ POR QUE NÃO USAR ESSE CÓDIGO EXATO NO CYBERPHONE:**
O CyBerPhone é uma **Rede Social com Feed Público**. O código que você enviou bloqueia a listagem de posts (`allow list: if isOwner(userId)`). Se você aplicar essas regras exatas, **o Feed Global vai parar de funcionar**, pois os usuários só conseguiriam ver os *próprios* posts.

Abaixo, criei as **Regras de Segurança Perfeitas para o CyBerPhone**. Elas mantêm a segurança (só você edita seu perfil), mas permitem que a rede social funcione (todos veem os posts públicos).

### Copie e cole isso no seu Firebase Console -> Firestore -> Rules:

```javascript
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {

    // --- FUNÇÕES AUXILIARES ---

    // Verifica se o usuário está logado
    function isSignedIn() {
      return request.auth != null;
    }

    // Verifica se o usuário logado é o dono do documento (pelo ID do doc)
    function isOwner(userId) {
      return isSignedIn() && request.auth.uid == userId;
    }

    // Verifica se o usuário logado é o autor do recurso (pelo campo userId)
    function isResourceAuthor() {
      return isSignedIn() && resource.data.userId == request.auth.uid;
    }

    // --- REGRAS POR COLEÇÃO ---

    // 1. USUÁRIOS (Perfil Público, Edição Privada)
    match /users/{userId} {
      allow read: if true;
      allow create: if isOwner(userId);
      allow update: if isOwner(userId);
      allow delete: if false; // Previne deleção acidental
    }

    // 2. POSTS (Feed Público, Edição apenas pelo Autor)
    match /posts/{postId} {
      allow read: if true;
      allow create: if isSignedIn() && request.resource.data.userId == request.auth.uid;
      allow update, delete: if isResourceAuthor();
    }

    // 3. CHATS (Privacidade Total: Apenas participantes leem/escrevem)
    match /chats/{chatId} {
      allow create: if isSignedIn();
      allow read, update, delete: if isSignedIn() && (
        request.auth.uid in resource.data.participants
      );
    }

    // 4. LOJAS & PRODUTOS (Vitrine Pública)
    match /stores/{storeId} {
      allow read: if true;
      allow write: if isSignedIn(); // Refinar para apenas donos em produção
    }

    match /products/{productId} {
      allow read: if true;
      allow write: if isSignedIn();
    }

    // 5. OUTRAS COLEÇÕES (Ads, Vendas, Notificações)
    match /ads/{adId} {
      allow read: if true;
      allow write: if isSignedIn();
    }

    match /affiliate_sales/{saleId} {
      // Apenas o comprador ou o vendedor podem ver os detalhes da venda
      allow read: if isSignedIn() && (
        resource.data.buyerId == request.auth.uid || 
        resource.data.affiliateUserId == request.auth.uid
      );
      allow create: if isSignedIn();
      allow update: if isSignedIn();
    }

    match /notifications/{notifId} {
      allow read: if isSignedIn() && resource.data.recipientId == request.auth.uid;
      allow create: if isSignedIn(); // Qualquer um pode criar notificação (ex: dar like)
      allow update, delete: if isSignedIn() && resource.data.recipientId == request.auth.uid;
    }

    // Regra Padrão de Segurança (Bloqueia o resto)
    match /{document=**} {
      allow read, write: if isSignedIn(); 
    }
  }
}
```

### O que isso faz:
1.  **Feed Funciona:** Todos podem ler `posts` e `users` (público), mas só podem editar seus próprios dados.
2.  **Chats Seguros:** Se alguém tentar ler um chat onde seu ID não está na lista de `participants`, o banco bloqueia.
3.  **Vendas Privadas:** Um usuário não consegue ver o histórico de compras de outro usuário.

