export const addStory = async (uId: string, item: any) => {
  const newItem = { ...item, id: generateUUID(), timestamp: Date.now() };

  if (isFirebaseConfigured && db) {
    const storyRef = doc(db, "stories", uId);
    const storyDoc = await getDoc(storyRef);

    if (storyDoc.exists()) {
      const currentStory = storyDoc.data() as Story;
      const updatedItems = [...currentStory.items, newItem];
      await updateDoc(storyRef, { items: updatedItems });
    } else {
      const user = await findUserById(uId);
      if (user) {
        const newStory: Story = {
          userId: uId,
          userName: user.firstName,
          userProfilePic: user.profilePicture || '',
          items: [newItem]
        };
        await setDoc(storyRef, JSON.parse(JSON.stringify(newStory)));
      }
    }
  }

  // Local fallback logic (mantido para garantir UI responsiva ou offline)
  const stories = getLocalList<Story>(KEYS.STORIES);
  const user = await findUserById(uId);
  if (!user) return;
  let userStory = stories.find(s => s.userId === uId);
  if (!userStory) {
    userStory = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [] };
    stories.push(userStory);
  }
  userStory.items.push(newItem);
  saveLocalList(KEYS.STORIES, stories);
}

