export const getPosts = async (): Promise<Post[]> => {
  if (isFirebaseConfigured && db) {
    const q = query(collection(db, "posts")); // Order by timestamp handled in client for simplicity or create index
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => d.data() as Post).sort((a, b) => b.timestamp - a.timestamp);
  }
  return [];
};

