export const toggleFollowUser = async (currentId: string, targetId: string) => {
    const meRef = doc(db, "users", currentId);
    const targetRef = doc(db, "users", targetId);

    const [meSnap, targetSnap] = await Promise.all([getDoc(meRef), getDoc(targetRef)]);

    if (meSnap.exists() && targetSnap.exists()) {
        const me = meSnap.data() as User;
        const target = targetSnap.data() as User;

        let newFollowing = me.followedUsers || [];
        let newFollowers = target.followers || [];

        if (newFollowing.includes(targetId)) {
            newFollowing = newFollowing.filter(id => id !== targetId);
            newFollowers = newFollowers.filter(id => id !== currentId);
        } else {
            newFollowing.push(targetId);
            newFollowers.push(currentId);
            await createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetId, actorId: currentId, timestamp: Date.now() });
        }

        await updateDoc(meRef, { followedUsers: newFollowing });
        await updateDoc(targetRef, { followers: newFollowers });
    }
};

