export const toggleJoinEvent = async (eId: string, uId: string) => {
  if (isFirebaseConfigured && db) {
    const evtRef = doc(db, "events", eId);
    const evtSnap = await getDoc(evtRef);
    if (evtSnap.exists()) {
        const evt = evtSnap.data() as CyberEvent;
