export const getNotificationsForUser = async (userId: string): Promise<Notification[]> => {
  if (isFirebaseConfigured && db) {
    const q = query(collection(db, "notifications"), where("recipientId", "==", userId));
    const s = await getDocs(q);
    return s.docs.map(d => d.data() as Notification);
  }
  return [];
};

export const createNotification = async (notifData: Omit<Notification, 'id' | 'isRead'>) => {
  if (!isFirebaseConfigured || !db) return;
  // Evitar notificar a si mesmo
  if (notifData.recipientId === notifData.actorId) return;

  const newNotif: Notification = {
      id: generateUUID(),
      isRead: false,
      ...notifData
  };
  await setDoc(doc(db, "notifications", newNotif.id), JSON.parse(JSON.stringify(newNotif)));
};

export const markNotificationsAsRead = async (userId: string) => {
  if (isFirebaseConfigured && db) {
    const q = query(collection(db, "notifications"), where("recipientId", "==", userId), where("isRead", "==", false));
    const s = await getDocs(q);
    // Batch update seria melhor, mas loop funciona para protótipo
    s.forEach(async (d) => {
        await updateDoc(doc(db, "notifications", d.id), { isRead: true });
    });
  }
};

