import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Post, User, UserType, Comment } from '../types';
import { findUserById, addPostComment, deleteComment, updatePostLikes, updatePostSaves, updatePostShares, toggleFollowUser, generateUUID, getPosts } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  XMarkIcon, 
  ChatBubbleOvalLeftIcon,
  HeartIcon as HeartIconOutline,
  BookmarkIcon as BookmarkIconOutline,
  ShareIcon,
  EllipsisHorizontalIcon,
  ArrowLeftIcon,
  PaperAirplaneIcon,
  ArrowDownTrayIcon,
  TrashIcon
} from '@heroicons/react/24/outline';
import { 
  HeartIcon as HeartIconSolid, 
  BookmarkIcon as BookmarkIconSolid,
  CheckBadgeIcon
} from '@heroicons/react/24/solid';

interface PostDetailModalProps {
  post: Post;
  currentUser: User;
  onClose: () => void;
  onUpdate: () => void;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const PostDetailModal: React.FC<PostDetailModalProps> = ({ post, currentUser, onClose, onUpdate, onNavigate, refreshUser }) => {
  const [commentText, setCommentText] = useState('');
  const [author, setAuthor] = useState<User | null>(null);
  const [comments, setComments] = useState<Comment[]>(post.comments || []);
  const [loadingComments, setLoadingComments] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const commentsEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const user = await findUserById(post.userId);
      setAuthor(user || null);
    };
    fetchAuthor();
  }, [post.userId]);

  // Função para buscar comentários atualizados
  const fetchComments = async () => {
    // setLoadingComments(true); // Opcional: evitar flicker
    const allPosts = await getPosts();
    const currentPost = allPosts.find(p => p.id === post.id);
    if (currentPost) {
      setComments(currentPost.comments || []);
    }
    setLoadingComments(false);
  };

  useEffect(() => {
    fetchComments();
  }, [post.id]);

  const isOwner = currentUser.id === post.userId;
  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasLiked = post.likes?.includes(currentUser.id);
  const hasSaved = post.saves?.includes(currentUser.id);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleLike = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostLikes(post.id, currentUser.id);
    onUpdate();
  };

  const handleSave = (e: React.MouseEvent) => {
    e.stopPropagation();
    updatePostSaves(post.id, currentUser.id);
    onUpdate();
  };

  const handleDownload = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!post.imageUrl) return;

    try {
      const response = await fetch(post.imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `cyberphone-midia-${post.id}.jpg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      window.open(post.imageUrl, '_blank');
    }
  };

  const handleShare = async (e: React.MouseEvent) => {
    e.stopPropagation();
    const shareData = {
      title: `Publicação de ${post.authorName}`,
      text: post.content || 'Confira este conteúdo no CyBerPhone!',
      url: window.location.href + `?post=${post.id}`
    };

    try {
      if (navigator.share) {
        await navigator.share(shareData);
      } else {
        await navigator.clipboard.writeText(shareData.url);
        alert('Link copiado!');
      }
      updatePostShares(post.id, currentUser.id);
      onUpdate();
    } catch (err) {}
  };

  const handleFollow = (e: React.MouseEvent) => {
    e.stopPropagation();
    toggleFollowUser(currentUser.id, post.userId);
    refreshUser();
    onUpdate();
  };

  const handleDeleteComment = async (commentId: string) => {
    if (confirm("Apagar este comentário?")) {
        await deleteComment(post.id, commentId);
        await fetchComments();
        onUpdate();
    }
  };

  const handleSendComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentText.trim()) return;

    const newComment: Comment = {
      id: generateUUID(),
      userId: currentUser.id,
      userName: `${currentUser.firstName} ${currentUser.lastName}`,
      profilePic: currentUser.profilePicture,
      text: commentText,
      timestamp: Date.now()
    };

    // Aguarda a persistência no banco
    await addPostComment(post.id, newComment);

    setCommentText('');

    // Atualiza a lista localmente e notifica o pai
    await fetchComments();
    onUpdate();

    setTimeout(() => {
      if (scrollRef.current) {
        scrollRef.current.scrollTo({
          top: scrollRef.current.scrollHeight,
          behavior: 'smooth'
        });
      }
    }, 100);
  };

  if (!author) return null;

  const hasBg = post.backgroundColor && post.backgroundColor !== 'transparent';
  const contentLength = post.content?.length || 0;

  // Lógica Adaptativa de Tamanho (Consistente com PostCard)
  let containerMinHeight = 'auto';
  let fontSizeClass = 'text-base md:text-lg text-left text-gray-900 dark:text-white';
  let paddingClass = 'p-0'; // Default no padding for plain text in modal

  if (hasBg) {
    if (contentLength < 60) {
        containerMinHeight = '250px'; 
        fontSizeClass = `${post.textColor || 'text-white'} text-3xl md:text-5xl text-center leading-tight`;
        paddingClass = 'p-10';
    } else if (contentLength < 150) {
        containerMinHeight = '350px';
        fontSizeClass = `${post.textColor || 'text-white'} text-2xl md:text-3xl text-center leading-snug`;
        paddingClass = 'p-12';
    } else {
        containerMinHeight = '450px';
        fontSizeClass = `${post.textColor || 'text-white'} text-xl md:text-2xl text-center leading-relaxed`;
        paddingClass = 'p-14';
    }
  }

  return createPortal(
    <div className="fixed inset-0 z-[10000] bg-black/90 flex items-center justify-center animate-fade-in overflow-hidden backdrop-blur-md">

      <div className="w-full h-full md:h-[95vh] md:max-w-6xl md:rounded-[3rem] bg-white dark:bg-[#0a0c10] flex flex-col md:flex-row overflow-hidden relative shadow-2xl">

        {/* Mobile Header */}
        <div className="flex items-center justify-between px-4 md:hidden z-[101] bg-black/40 backdrop-blur-xl border-b border-white/10 h-16 shrink-0">
           <button onClick={onClose} className="p-2 text-white">
             <ArrowLeftIcon className="h-6 w-6" />
           </button>
           <span className="font-black text-[10px] uppercase text-white tracking-[0.3em]">Detalhes</span>
           <div className="w-10"></div>
        </div>

        {/* Desktop Close Button */}
        <button 
          onClick={onClose} 
          className="hidden md:flex absolute top-6 left-6 z-[101] p-4 bg-black/50 hover:bg-black/80 text-white rounded-full transition-all backdrop-blur-lg shadow-2xl border border-white/10 active:scale-90"
        >
          <XMarkIcon className="h-6 w-6" />
        </button>

        {/* Image Container */}
        <div className={`w-full md:flex-1 bg-black flex items-center justify-center relative overflow-hidden shrink-0 ${!post.imageUrl ? 'hidden md:flex' : 'h-[50vh] md:h-full'}`}>
          {post.imageUrl && (
            <img 
              src={post.imageUrl} 
              className="w-full h-full object-contain" 
              alt="Mídia"
            />
          )}

          <div className="absolute bottom-6 right-6 flex flex-col gap-4 md:hidden">
             <button onClick={handleDownload} className="p-4 rounded-full backdrop-blur-xl border border-white/20 shadow-2xl bg-black/40 text-white active:scale-90 transition-all">
