                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] ml-2">Comentários</p>
                </div>

                {comments.length === 0 ? (
                  <div className="py-12 text-center opacity-20">
                     <ChatBubbleOvalLeftIcon className="h-10 w-10 mx-auto mb-2" />
                     <p className="text-[10px] font-black uppercase tracking-widest">Seja o primeiro a comentar</p>
                  </div>
                ) : (
                  <div className="space-y-6">
                    {comments.map((c) => (
                      <div key={c.id} className="flex gap-4 animate-fade-in group relative">
                         <img src={c.profilePic || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-xl object-cover shrink-0 border-2 border-white dark:border-white/5 shadow-sm" />
                         <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                               <span className="font-black text-[11px] dark:text-white uppercase tracking-tighter truncate">{c.userName}</span>
                               <span className="text-gray-400 text-[8px] font-black uppercase">· {new Date(c.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                            </div>
                            <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-white/10 shadow-sm pr-10 relative">
                               <p className="text-sm dark:text-gray-200 font-medium leading-relaxed">{c.text}</p>
                               {/* Delete Comment Button */}
                               {(currentUser.id === c.userId || isOwner) && (
                                   <button 
                                     onClick={() => handleDeleteComment(c.id)}
                                     className="absolute top-2 right-2 p-1.5 text-gray-400 hover:text-red-500 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/10 transition-all opacity-0 group-hover:opacity-100"
                                     title="Apagar comentário"
                                   >
                                       <TrashIcon className="h-4 w-4" />
                                   </button>
                               )}
                            </div>
                         </div>
                      </div>
                    ))}
                    <div ref={commentsEndRef} />
                  </div>
                )}
             </div>
          </div>

          <div className="p-6 bg-white dark:bg-[#0a0c10] border-t border-gray-100 dark:border-white/10 z-[105] shadow-[0_-10px_30px_rgba(0,0,0,0.05)] shrink-0">
             <form onSubmit={handleSendComment} className="max-w-4xl mx-auto flex items-end gap-3 bg-gray-50 dark:bg-white/5 p-3 rounded-[2rem] border border-gray-100 dark:border-white/10 shadow-inner group focus-within:border-blue-500/50 transition-all">
                <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-11 h-11 rounded-xl object-cover hidden sm:block border-2 border-white shadow-sm" />
                <div className="flex-1 flex items-center gap-3">
                   <textarea 
                    value={commentText}
                    onChange={e => setCommentText(e.target.value)}
                    placeholder="Adicionar um comentário..."
                    className="w-full bg-transparent dark:text-white outline-none resize-none text-sm placeholder-gray-400 py-3 font-bold custom-scrollbar max-h-24"
                    rows={1}
                    onInput={(e) => {
                      const target = e.target as HTMLTextAreaElement;
                      target.style.height = 'auto';
                      target.style.height = `${target.scrollHeight}px`;
                    }}
                   />
                   <button 
                     type="submit" 
                     disabled={!commentText.trim()}
                     className="bg-blue-600 hover:bg-blue-700 disabled:opacity-30 text-white p-3.5 rounded-2xl shadow-xl shadow-blue-500/20 active:scale-90 transition-all shrink-0"
                   >
                     <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                   </button>
                </div>
             </form>
             <div className="h-2 md:hidden"></div>
          </div>
        </div>
      </div>
    </div>,
    document.body
  );
};

export default PostDetailModal;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { User, Post, Product, ProductType, UserType } from '../types';
import { getUsers, getPosts, getProducts, toggleFollowUser } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import PostCard from './PostCard';
import { 
  CheckBadgeIcon, 
  ShoppingBagIcon, 
  NewspaperIcon, 
  UsersIcon, 
  Squares2X2Icon, 
  StarIcon,
  FunnelIcon,
  XMarkIcon,
  AdjustmentsHorizontalIcon,
  CurrencyDollarIcon,
  ArrowDownIcon,
  ChevronRightIcon
} from '@heroicons/react/24/solid';

interface SearchResultsPageProps {
  currentUser: User;
  query: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

type SearchTab = 'all' | 'users' | 'posts' | 'products';

const ITEMS_PER_PAGE = 12;

const UserResultCard: React.FC<{ user: User; currentUser: User; onNavigate: Function; onFollowToggle: Function }> = ({ user, currentUser, onNavigate, onFollowToggle }) => {
