                  <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
                    {foundUsers.slice(0, activeTab === 'all' ? 6 : userLimit).map(user => <UserResultCard key={user.id} user={user} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={handleFollowToggle} />)}
                  </div>
                  {activeTab === 'users' && <LoadMoreButton count={foundUsers.length} currentLimit={userLimit} hasMore={userLimit < foundUsers.length} onClick={() => setUserLimit(prev => prev + ITEMS_PER_PAGE)} />}
                </section>
              )}

              {/* Seção Produtos */}
              {(activeTab === 'all' || activeTab === 'products') && foundProducts.length > 0 && (
                <section className="animate-fade-in">
                  <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-3">
                      <div className="w-1.5 h-6 bg-green-500 rounded-full"></div>
                      <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Marketplace</h3>
                      <span className="bg-gray-100 dark:bg-white/5 px-2 py-0.5 rounded text-[10px] font-black text-gray-400">{foundProducts.length}</span>
                    </div>
                    {activeTab === 'all' && foundProducts.length > 4 && (
                      <button onClick={() => setActiveTab('products')} className="text-blue-600 font-black uppercase text-[9px] tracking-widest hover:underline flex items-center gap-2">
                        Ver Loja Completa <ChevronRightIcon className="h-3 w-3" />
                      </button>
                    )}
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6">
                    {foundProducts.slice(0, activeTab === 'all' ? 4 : productLimit).map(product => <ProductResultCard key={product.id} product={product} onNavigate={onNavigate} />)}
                  </div>
                  {activeTab === 'products' && <LoadMoreButton count={foundProducts.length} currentLimit={productLimit} hasMore={productLimit < foundProducts.length} onClick={() => setProductLimit(prev => prev + ITEMS_PER_PAGE)} />}
                </section>
              )}

              {/* Seção Posts */}
              {(activeTab === 'all' || activeTab === 'posts') && foundPosts.length > 0 && (
                <section className="animate-fade-in">
                  <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-3">
                      <div className="w-1.5 h-6 bg-purple-600 rounded-full"></div>
                      <h3 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Conteúdos & Aulas</h3>
                      <span className="bg-gray-100 dark:bg-white/5 px-2 py-0.5 rounded text-[10px] font-black text-gray-400">{foundPosts.length}</span>
                    </div>
                    {activeTab === 'all' && foundPosts.length > 4 && (
                      <button onClick={() => setActiveTab('posts')} className="text-blue-600 font-black uppercase text-[9px] tracking-widest hover:underline flex items-center gap-2">
                        Explorar Postagens <ChevronRightIcon className="h-3 w-3" />
                      </button>
                    )}
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {foundPosts.slice(0, activeTab === 'all' ? 4 : postLimit).map(post => (
                      <div key={post.id} className="w-full">
                        <PostCard
                          post={post} currentUser={currentUser} 
                          onNavigate={onNavigate} onFollowToggle={handleFollowToggle} 
                          refreshUser={refreshUser} onPostUpdatedOrDeleted={performSearch} onPinToggle={() => {}}
                        />
                      </div>
                    ))}
                  </div>
                  {activeTab === 'posts' && <LoadMoreButton count={foundPosts.length} currentLimit={postLimit} hasMore={postLimit < foundPosts.length} onClick={() => setPostLimit(prev => prev + ITEMS_PER_PAGE)} />}
                </section>
              )}
            </div>
          )}
        </main>
      </div>

      {/* Modal de Filtros Mobile */}
      {isFilterMobileOpen && (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-md md:hidden flex flex-col justify-end" onClick={() => setIsFilterMobileOpen(false)}>
           <div 
             className="bg-white dark:bg-darkcard rounded-t-[3rem] p-8 shadow-2xl animate-slide-up" 
             onClick={e => e.stopPropagation()}
           >
              <div className="w-12 h-1.5 bg-gray-100 dark:bg-white/10 rounded-full mx-auto mb-8"></div>

              <div className="flex justify-between items-center mb-10">
                 <h2 className="text-2xl font-black dark:text-white uppercase tracking-tighter">Refinar Busca</h2>
                 <button onClick={() => setIsFilterMobileOpen(false)} className="p-3 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400"><XMarkIcon className="h-6 w-6"/></button>
              </div>

              <div className="max-h-[60vh] overflow-y-auto no-scrollbar pb-10">
                <FilterSidebar />
              </div>

              <button 
                onClick={() => setIsFilterMobileOpen(false)}
                className="w-full py-5 bg-blue-600 text-white rounded-3xl font-black uppercase text-sm shadow-xl shadow-blue-500/20 active:scale-95 transition-all"
              >
                Aplicar Filtros
              </button>
           </div>
        </div>
      )}

      <style>{`
        @keyframes slide-up {
          from { transform: translateY(100%); }
          to { transform: translateY(0); }
        }
        .animate-slide-up { animation: slide-up 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default SearchResultsPage;

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { User, Post, AdCampaign, PostType, Story, CyberEvent, ChatConversation } from '../types';
import { getPosts, getAds, getStories, getUsers, toggleFollowUser, getEvents, getChats, joinGroup } from '../services/storageService';
import { DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import PostCard from './PostCard';
import CreatePost from './CreatePost';
import AdCard from './AdCard';
import StoryViewerModal from './StoryViewerModal';
import CreateStoryModal from './CreateStoryModal';
import GroupDiscoveryCard from './GroupDiscoveryCard';
import { PlusIcon, ArrowPathIcon, RocketLaunchIcon, ChevronUpIcon, FireIcon, SparklesIcon, CalendarIcon, UserGroupIcon, StarIcon, ArrowTrendingUpIcon, PlayIcon, FilmIcon } from '@heroicons/react/24/outline';
import { TrophyIcon, CheckCircleIcon } from '@heroicons/react/24/solid';

interface FeedPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const ITEMS_PER_PAGE = 6;

type FeedItem = 
  | Post 
  | AdCampaign 
  | ChatConversation 
  | { type: 'SUGGESTIONS' } 
  | { type: 'REELS_SHELF'; items: Post[] } 
  | { type: 'GROUPS_SHELF'; items: ChatConversation[] };

const FeedPage: React.FC<FeedPageProps> = ({ currentUser, onNavigate, refreshUser }) => {
  const [allItems, setAllItems] = useState<FeedItem[]>([]);
  const [visibleItems, setVisibleItems] = useState<FeedItem[]>([]);
  const [displayLimit, setDisplayLimit] = useState(ITEMS_PER_PAGE);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [showScrollTop, setShowScrollTop] = useState(false);

  const [stories, setStories] = useState<Story[]>([]);
  const [suggestedUsers, setSuggestedUsers] = useState<User[]>([]);
  const [selectedStoryIndex, setSelectedStoryIndex] = useState<number | null>(null);
  const [isCreatingStory, setIsCreatingStory] = useState(false);

  const observerTarget = useRef<HTMLDivElement>(null);

  const loadData = useCallback(async (isRefresh = false) => {
    if (!isRefresh) setLoading(true);

    const [allPosts, allAds, allUsers, allStories, allChats] = await Promise.all([
      getPosts(),
      getAds(),
      getUsers(),
      getStories(),
      getChats()
    ]);

    // Filtrar Posts Normais e Reels
    const normalPosts = allPosts.filter(p => p.type !== PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);
    const reelsPosts = allPosts.filter(p => p.type === PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);

    const activeAds = allAds.filter(a => a.isActive).sort((a, b) => (b.budget || 0) - (a.budget || 0));

    // Filtrar Grupos Públicos que o usuário NÃO participa
    // Fix: Added optional chaining for participants
    const publicGroups = allChats.filter(c => 
      c.type === 'GROUP' && 
      c.isPublic && 
      !c.participants?.includes(currentUser.id)
    );

    // Filtrar Stories (apenas de quem sigo ou meus)
    // Para simplificar a demo, mostra todos, mas coloca o meu primeiro se existir
    const myStory = allStories.find(s => s.userId === currentUser.id);
    const otherStories = allStories.filter(s => s.userId !== currentUser.id);

    // Se eu tenho story, ele vai pro topo da lista de visualização
    const viewerStories = myStory ? [myStory, ...otherStories] : otherStories;
    setStories(viewerStories);

    const suggestions = allUsers
      .filter(u => u && u.id !== currentUser.id && !currentUser.followedUsers?.includes(u.id))
      .sort(() => 0.5 - Math.random())
      .slice(0, 8);
    setSuggestedUsers(suggestions);

    let combined: FeedItem[] = [];
    let adPointer = 0;

    // Estratégia de Mixagem do Feed
    const firstBatch = normalPosts.slice(0, 3);
    combined.push(...firstBatch);

    if (reelsPosts.length > 0) {
      combined.push({ type: 'REELS_SHELF', items: reelsPosts.slice(0, 10) });
    }

    if (suggestions.length > 0) {
      combined.push({ type: 'SUGGESTIONS' });
    }

    if (publicGroups.length > 0) {
      combined.push({ type: 'GROUPS_SHELF', items: publicGroups.slice(0, 5) });
    }

    const remainingPosts = normalPosts.slice(3);
    remainingPosts.forEach((post, idx) => {
        combined.push(post);
        if ((idx + 1) % 5 === 0 && adPointer < activeAds.length) {
            combined.push(activeAds[adPointer]);
            adPointer++;
        }
    });

    setAllItems(combined);
    // Se for refresh, mantém o limite atual, senão reseta
    if (isRefresh) {
        setVisibleItems(combined.slice(0, displayLimit));
    } else {
        setVisibleItems(combined.slice(0, ITEMS_PER_PAGE));
        setDisplayLimit(ITEMS_PER_PAGE);
    }

    setLoading(false);
  }, [currentUser, displayLimit]);

  useEffect(() => { loadData(); }, [loadData]);

  const loadMoreItems = useCallback(() => {
    if (loadingMore || visibleItems.length >= allItems.length) return;
    setLoadingMore(true);
    setTimeout(() => {
      const nextLimit = displayLimit + ITEMS_PER_PAGE;
      setVisibleItems(allItems.slice(0, nextLimit));
      setDisplayLimit(nextLimit);
      setLoadingMore(false);
    }, 400);
  }, [displayLimit, allItems, loadingMore, visibleItems.length]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting && !loading && !loadingMore && visibleItems.length < allItems.length) {
        loadMoreItems();
      }
    }, { threshold: 0.1, rootMargin: '100px' });

    if (observerTarget.current) observer.observe(observerTarget.current);
    return () => observer.disconnect();
  }, [loading, loadingMore, loadMoreItems, visibleItems.length, allItems.length]);

  useEffect(() => {
    const handleScroll = () => setShowScrollTop(window.scrollY > 1000);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleJoin = async (groupId: string) => {
    await joinGroup(groupId, currentUser.id);
    loadData(true);
  };

  const scrollToTop = () => window.scrollTo({ top: 0, behavior: 'smooth' });

  const followerCount = currentUser.followers?.length || 0;
  const progressPercent = Math.min((followerCount / CREATOR_UPGRADE_FOLLOWERS_GOAL) * 100, 100);
  const isAtEnd = visibleItems.length >= allItems.length && allItems.length > 0;

  // Verifica se o usuário atual tem story postado
  const hasMyStory = stories.some(s => s.userId === currentUser.id);

  // Renderização otimizada dos itens
  const renderedItems = useMemo(() => {
    return visibleItems.map((item: any, idx) => {
        if (item.authorName) { 
          return <PostCard key={item.id} post={item as Post} currentUser={currentUser} onNavigate={onNavigate} onFollowToggle={() => loadData(true)} refreshUser={refreshUser} onPostUpdatedOrDeleted={() => loadData(true)} onPinToggle={() => loadData(true)} />;
        }
        if (item.professorId) { 
          return <AdCard key={item.id} ad={item as AdCampaign} rank={idx} />;
        }
        if (item.type === 'SUGGESTIONS') {
          return (
            <div key="sugg" className="bg-gradient-to-br from-indigo-600 to-blue-800 rounded-[2.5rem] p-6 md:p-8 text-white shadow-2xl relative overflow-hidden animate-fade-in my-6 border-4 border-white/10">
                <SparklesIcon className="absolute -right-10 -bottom-10 w-64 h-64 opacity-10 rotate-12" />
                <div className="flex items-center justify-between mb-6 relative z-10">
                  <div>
                      <h4 className="font-black text-xl tracking-tighter flex items-center gap-2"><FireIcon className="h-6 w-6 text-yellow-400" /> Networking</h4>
                      <p className="text-blue-100 text-[10px] font-bold uppercase tracking-widest">Sugestões de Conexão</p>
                  </div>
                  <button onClick={() => loadData(true)} className="bg-white/10 hover:bg-white/20 p-2.5 rounded-xl transition-all"><ArrowPathIcon className="h-5 w-5"/></button>
                </div>
                <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar relative z-10 snap-x">
                  {suggestedUsers.map(u => (
                    <div key={u.id} className="bg-white/10 backdrop-blur-md p-4 rounded-[1.8rem] min-w-[140px] flex flex-col items-center text-center border border-white/10 group hover:bg-white/20 transition-all snap-start">
                        <img src={u.profilePicture} className="w-16 h-16 rounded-full object-cover mb-3 border-2 border-white/30 shadow-lg group-hover:scale-110 transition-transform" />
                        <p className="font-black text-xs truncate w-full mb-0.5">{u.firstName}</p>
                        <p className="text-[8px] font-bold text-blue-200 uppercase mb-3 tracking-wide truncate w-full">{u.lastName}</p>
                        <button onClick={() => { toggleFollowUser(currentUser.id, u.id); refreshUser(); loadData(true); }} className="w-full bg-white text-blue-700 py-2 rounded-lg font-black text-[9px] uppercase shadow-md active:scale-95 transition-all">Seguir</button>
                    </div>
                  ))}
                </div>
            </div>
          );
        }
        if (item.type === 'REELS_SHELF') {
          return (
            <div key="reels-shelf" className="my-4">
              <div className="flex items-center gap-2 mb-3 px-2">
                  <FilmIcon className="h-5 w-5 text-purple-600" />
                  <h3 className="font-black text-base dark:text-white uppercase tracking-tight">Reels em Alta</h3>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar snap-x px-1">
                  {item.items.map((reel: Post) => (
                    <div 
                      key={reel.id} 
                      onClick={() => onNavigate('reels-page', { startPostId: reel.id })}
                      className="relative min-w-[130px] h-[220px] rounded-[1.2rem] overflow-hidden cursor-pointer group shadow-md snap-start border border-gray-100 dark:border-white/5"
                    >
                      <video src={reel.reel?.videoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" muted />
                      <div className="absolute inset-0 bg-black/10 group-hover:bg-black/30 transition-colors flex items-center justify-center">
                          <PlayIcon className="h-8 w-8 text-white/80 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </div>
                      <div className="absolute bottom-0 left-0 w-full p-3 bg-gradient-to-t from-black/80 to-transparent">
                          <p className="text-white text-[9px] font-bold line-clamp-1 leading-tight mb-0.5">{reel.reel?.description}</p>
                          <p className="text-white/70 text-[7px] font-black uppercase">@{reel.authorName}</p>
                      </div>
                    </div>
                  ))}
              </div>
            </div>
          );
        }
        if (item.type === 'GROUPS_SHELF') {
          return (
            <div key="groups-shelf" className="my-6 bg-gray-50 dark:bg-white/5 p-5 rounded-[2rem] border border-gray-100 dark:border-white/5">
              <div className="flex items-center gap-2 mb-3">
                  <UserGroupIcon className="h-5 w-5 text-blue-600" />
                  <h3 className="font-black text-base dark:text-white uppercase tracking-tight">Comunidades</h3>
              </div>
              <div className="flex gap-3 overflow-x-auto pb-2 no-scrollbar snap-x">
                  {item.items.map((group: ChatConversation) => (
                    <div key={group.id} className="min-w-[240px] snap-start">
                      <GroupDiscoveryCard group={group} onJoin={() => handleJoin(group.id)} />
                    </div>
                  ))}
              </div>
            </div>
          );
        }
        return null;
    });
  }, [visibleItems, currentUser, onNavigate, loadData, refreshUser, suggestedUsers]);

  return (
    <div className="w-full max-w-[1400px] mx-auto px-2 md:px-6 lg:px-8 py-4 md:py-6 relative">
      <div className="fixed bottom-28 md:bottom-12 right-4 md:right-8 z-[100] flex flex-col gap-3">
        {showScrollTop && (
          <button onClick={scrollToTop} className="bg-white dark:bg-darkcard text-blue-600 p-4 rounded-2xl shadow-2xl border border-gray-100 dark:border-white/10 animate-fade-in active:scale-95 transition-all">
            <ChevronUpIcon className="h-6 w-6 stroke-[3]" />
          </button>
        )}
        <button 
          onClick={() => onNavigate('ads')} 
          className="bg-blue-600 text-white p-4 rounded-2xl shadow-[0_15px_30px_rgba(37,99,235,0.4)] hover:scale-105 active:scale-95 transition-all flex items-center justify-center"
          title="Criar Anúncio"
        >
          <RocketLaunchIcon className="h-7 w-7" />
        </button>
      </div>

      {/* WHATSAPP STYLE STORIES HEADER */}
      <div className="mb-6 overflow-x-auto no-scrollbar py-2 -mx-2 px-2 snap-x">
         <div className="flex items-start gap-4 px-2">

            {/* 1. BOTÃO DE CRIAR (SEMPRE VISÍVEL E FIXO À ESQUERDA) */}
            <div 
              onClick={() => setIsCreatingStory(true)} 
              className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start"
            >
               <div className="relative">
                  <div className="w-16 h-16 rounded-full border-2 border-dashed border-blue-400 p-[2px] flex items-center justify-center hover:bg-blue-50 dark:hover:bg-white/5 transition-all">
                     <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full rounded-full object-cover opacity-70" />
                  </div>
                  <div className="absolute bottom-0 right-0 bg-blue-600 rounded-full p-1.5 border-2 border-white dark:border-darkbg shadow-sm">
                     <PlusIcon className="h-3 w-3 text-white stroke-[3]" />
                  </div>
               </div>
               <span className="text-[10px] font-bold text-gray-900 dark:text-white truncate w-full text-center">
                  Criar
               </span>
            </div>

            {/* 2. MEU STORY (SE EXISTIR) */}
            {hasMyStory && (
              <div 
                onClick={() => setSelectedStoryIndex(stories.findIndex(s => s.userId === currentUser.id))} 
                className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start"
              >
                 <div className="p-[2px] rounded-full bg-gradient-to-tr from-green-400 to-blue-500">
                    <img src={currentUser.profilePicture || DEFAULT_PROFILE_PIC} className="w-16 h-16 rounded-full border-2 border-white dark:border-darkbg object-cover" />
                 </div>
                 <span className="text-[10px] font-medium text-gray-600 dark:text-gray-300 truncate w-[70px] text-center">
                    Você
                 </span>
              </div>
            )}

            {/* 3. STORIES DOS OUTROS */}
            {stories.filter(s => s.userId !== currentUser.id).map((story) => {
               // Encontrar índice real no array completo para abrir o viewer
               const realIndex = stories.findIndex(s => s.userId === story.userId);

               return (
                  <div key={story.userId} onClick={() => setSelectedStoryIndex(realIndex)} className="flex flex-col items-center gap-1.5 cursor-pointer group min-w-[70px] flex-shrink-0 snap-start">
                     <div className="p-[2px] rounded-full bg-gradient-to-tr from-yellow-400 to-red-500 group-hover:scale-105 transition-transform duration-300">
                        <img src={story.userProfilePic || DEFAULT_PROFILE_PIC} className="w-16 h-16 rounded-full border-2 border-white dark:border-darkbg object-cover" />
                     </div>
                     <span className="text-[10px] font-medium text-gray-600 dark:text-gray-300 truncate w-[70px] text-center">
                        {(story.userName || 'Usuário').split(' ')[0]}
                     </span>
                  </div>
               );
            })}
         </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <main className="lg:col-span-8 space-y-8">
          <CreatePost currentUser={currentUser} onPostCreated={() => loadData(true)} refreshUser={refreshUser} />

          <div className="space-y-8">
            {loading ? (
              <div className="py-20 text-center">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto"></div>
                <p className="mt-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Carregando Feed...</p>
              </div>
            ) : (
              <>
                {renderedItems}

                <div ref={observerTarget} className="h-24 flex flex-col items-center justify-center">
                  {loadingMore && (
                    <>
                      <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      <p className="mt-3 text-[9px] font-black text-gray-400 uppercase tracking-widest">Carregando...</p>
                    </>
                  )}
                  {isAtEnd && !loadingMore && (
                    <div className="flex flex-col items-center gap-2 opacity-50 py-8">
                       <CheckCircleIcon className="h-8 w-8 text-green-500" />
                       <p className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em]">Fim do conteúdo</p>
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </main>

        <aside className="hidden lg:block lg:col-span-4 space-y-6">
           <div className="sticky top-24 space-y-6">
              <div className="bg-gradient-to-br from-blue-600 to-indigo-700 rounded-[2.5rem] p-8 text-white shadow-xl relative overflow-hidden group">
                 <RocketLaunchIcon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:scale-110 transition-transform duration-700" />
                 <h3 className="text-xl font-black uppercase tracking-tighter mb-4 flex items-center gap-2">
                    <TrophyIcon className="h-6 w-6 text-yellow-400" /> Meta Profissional
                 </h3>
                 <div className="mb-6">
                    <div className="flex justify-between text-[10px] font-black uppercase mb-2">
                       <span>Progresso</span>
                       <span>{followerCount} / 2.000</span>
                    </div>
                    <div className="w-full h-2.5 bg-white/20 rounded-full overflow-hidden border border-white/10">
                       <div className="h-full bg-white shadow-[0_0_10px_white] transition-all duration-1000" style={{ width: `${progressPercent}%` }} />
                    </div>
                 </div>
                 <button onClick={() => onNavigate('ads')} className="w-full bg-white text-blue-700 py-4 rounded-2xl font-black text-[11px] uppercase shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3">
                    <RocketLaunchIcon className="h-5 w-5" /> Impulsionar Perfil
                 </button>
              </div>
           </div>
        </aside>
      </div>

      {isCreatingStory && <CreateStoryModal currentUser={currentUser} onClose={() => setIsCreatingStory(false)} onStoryCreated={() => { setIsCreatingStory(false); loadData(true); }} />}

      {selectedStoryIndex !== null && (
        <StoryViewerModal 
          stories={stories} 
          initialIndex={selectedStoryIndex} 
          onClose={() => setSelectedStoryIndex(null)} 
        />
      )}
    </div>
  );
};

export default FeedPage;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, Message, ChatConversation, ChatType, GroupTheme } from '../types';
import {
  getChats,
  findUserById,
  sendMessage,
  deleteMessage,
  editMessage,
  generateUUID,
  getUsers,
  updateGroupTheme,
  leaveGroup,
  deleteChat
} from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { 
  PhoneIcon, 
  VideoCameraIcon, 
  ChatBubbleLeftRightIcon, 
  PhotoIcon, 
  ArrowLeftIcon, 
  PaperAirplaneIcon, 
  CheckBadgeIcon, 
  MagnifyingGlassIcon, 
  UserGroupIcon,
  PlusIcon,
  Bars3BottomLeftIcon,
  EllipsisVerticalIcon,
  PaintBrushIcon,
  ChevronDownIcon,
  PencilIcon,
  TrashIcon,
  ArrowUturnLeftIcon,
  XMarkIcon,
  DocumentDuplicateIcon,
  ArrowRightOnRectangleIcon,
  InformationCircleIcon
} from '@heroicons/react/24/solid';
import CallModal from './CallModal';

interface ChatPageProps {
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
}

// Configuração expandida de Temas
// Ajuste de cores para garantir visibilidade do texto (text-gray-900 em bubbles claros)
const THEME_CONFIG: Record<GroupTheme, { primary: string, secondary: string, bg: string, bubble: string, text: string }> = {
  blue: { primary: 'bg-blue-600', secondary: 'bg-blue-500', bg: 'bg-[#73a3c9]', bubble: 'bg-[#effdde]', text: 'text-blue-600' },
  green: { primary: 'bg-emerald-600', secondary: 'bg-emerald-500', bg: 'bg-[#7ebc89]', bubble: 'bg-[#e7fde8]', text: 'text-emerald-600' },
  black: { primary: 'bg-zinc-900', secondary: 'bg-zinc-800', bg: 'bg-[#1a1a1a]', bubble: 'bg-[#2b2b2b]', text: 'text-white' }, // Dark theme special case
  orange: { primary: 'bg-orange-600', secondary: 'bg-orange-500', bg: 'bg-[#edb881]', bubble: 'bg-[#fff5e6]', text: 'text-orange-600' },
  purple: { primary: 'bg-purple-600', secondary: 'bg-purple-500', bg: 'bg-[#9d84c4]', bubble: 'bg-[#f3e5f5]', text: 'text-purple-600' },
  red: { primary: 'bg-red-600', secondary: 'bg-red-500', bg: 'bg-[#e57373]', bubble: 'bg-[#ffebee]', text: 'text-red-600' },
  teal: { primary: 'bg-teal-600', secondary: 'bg-teal-500', bg: 'bg-[#4db6ac]', bubble: 'bg-[#e0f2f1]', text: 'text-teal-600' },
  pink: { primary: 'bg-pink-600', secondary: 'bg-pink-500', bg: 'bg-[#f06292]', bubble: 'bg-[#fce4ec]', text: 'text-pink-600' },
  indigo: { primary: 'bg-indigo-600', secondary: 'bg-indigo-500', bg: 'bg-[#7986cb]', bubble: 'bg-[#e8eaf6]', text: 'text-indigo-600' },
  cyan: { primary: 'bg-cyan-600', secondary: 'bg-cyan-500', bg: 'bg-[#4dd0e1]', bubble: 'bg-[#e0f7fa]', text: 'text-cyan-600' }
};

const ChatPage: React.FC<ChatPageProps> = ({ currentUser, onNavigate }) => {
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [selectedChat, setSelectedChat] = useState<ChatConversation | null>(null);
  const [newMessage, setNewMessage] = useState('');
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [showThemeMenu, setShowThemeMenu] = useState(false);
  const [showGroupMenu, setShowGroupMenu] = useState(false); // Menu de 3 pontinhos
  const [filterTab, setFilterTab] = useState<'ALL' | 'PRIVATE' | 'GROUP'>('ALL');
  const [activeCall, setActiveCall] = useState<{partner: User, type: 'voice' | 'video'} | null>(null);

  // States for Actions
  const [replyingTo, setReplyingTo] = useState<Message | null>(null);
  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);
  const [selectedMessageForAction, setSelectedMessageForAction] = useState<Message | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  const loadData = useCallback(async () => {
    const allChats = await getChats();
    // Fix: Added optional chaining for participants
    const userChats = allChats.filter(c => c.participants?.includes(currentUser.id));
    setConversations(userChats);

    if (selectedChat) {
      const updated = userChats.find(c => c.id === selectedChat.id);
      if (updated) setSelectedChat(updated);
      else setSelectedChat(null); // Se foi removido/excluído
    }
  }, [currentUser.id, selectedChat?.id]);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, [loadData]);

  useEffect(() => {
    if (messagesEndRef.current) messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [selectedChat?.messages?.length, selectedChat?.id]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !attachedImage) || !selectedChat) return;

    if (editingMessageId) {
        await editMessage(selectedChat.id, editingMessageId, newMessage.trim());
        setEditingMessageId(null);
    } else {
        const replyContext = replyingTo ? {
            id: replyingTo.id,
            text: replyingTo.text || 'Imagem',
            senderName: replyingTo.senderId === currentUser.id ? 'Você' : 'Usuário'
        } : undefined;

        const msg: Message = {
          id: generateUUID(),
          senderId: currentUser.id,
          timestamp: Date.now(),
          text: newMessage.trim() || undefined,
          imageUrl: attachedImage || undefined,
          groupId: selectedChat.type === ChatType.GROUP ? selectedChat.id : undefined,
          replyTo: replyContext
        };

        await sendMessage(selectedChat.id, msg);
        setReplyingTo(null);
    }

    setNewMessage('');
    setAttachedImage(null);
    loadData();

    // Reset height of textarea
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleAction = (action: 'reply' | 'edit' | 'delete' | 'copy') => {
    if (!selectedMessageForAction || !selectedChat) return;

    const msg = selectedMessageForAction;

    switch (action) {
        case 'reply':
            setReplyingTo(msg);
            setEditingMessageId(null);
            inputRef.current?.focus();
            break;
        case 'edit':
            setNewMessage(msg.text || '');
            setEditingMessageId(msg.id);
            setReplyingTo(null);
            inputRef.current?.focus();
            break;
        case 'delete':
            if(window.confirm("Apagar esta mensagem para todos?")) {
                deleteMessage(selectedChat.id, msg.id).then(loadData);
            }
            break;
        case 'copy':
            if (msg.text) navigator.clipboard.writeText(msg.text);
            break;
    }
    setSelectedMessageForAction(null);
  };

  const cancelAction = () => {
    setReplyingTo(null);
    setEditingMessageId(null);
    setNewMessage('');
    if (inputRef.current) inputRef.current.style.height = 'auto';
  };

  const handleChangeTheme = async (theme: GroupTheme) => {
    if (!selectedChat || selectedChat.adminId !== currentUser.id) return;
    await updateGroupTheme(selectedChat.id, theme);
    setShowThemeMenu(false);
    loadData();
  };

  const handleLeaveGroup = async () => {
    if (!selectedChat) return;
    if (confirm("Tem certeza que deseja sair deste grupo?")) {
      await leaveGroup(selectedChat.id, currentUser.id);
      setSelectedChat(null);
      loadData();
    }
    setShowGroupMenu(false);
  };

  const handleDeleteChat = async () => {
    if (!selectedChat) return;
    const isGroup = selectedChat.type === ChatType.GROUP;
    const msg = isGroup 
        ? "ATENÇÃO: Isso apagará o grupo e todas as mensagens para todos os membros. Continuar?"
        : "Tem certeza que deseja apagar esta conversa? O histórico será perdido.";

    if (confirm(msg)) {
      await deleteChat(selectedChat.id);
      setSelectedChat(null);
      loadData();
    }
    setShowGroupMenu(false);
  };

  const startCall = async (type: 'voice' | 'video') => {
    if (!selectedChat || selectedChat.type === ChatType.GROUP) return;
    const partnerId = selectedChat.participants.find(p => p !== currentUser.id);
    const partner = await findUserById(partnerId!);
    if (partner) setActiveCall({ partner, type });
  };

  const filteredConversations = conversations.filter(c => {
    if (filterTab === 'ALL') return true;
    return c.type === filterTab;
  });

  const chatTheme = selectedChat?.theme || 'blue';
  const themeStyles = THEME_CONFIG[chatTheme];

  // Logic to determine if current user can delete a message
  const canDeleteMessage = (msg: Message) => {
    if (!selectedChat) return false;
    // Own message
    if (msg.senderId === currentUser.id) return true;
    // Group Admin can delete any message
    if (selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id) return true;

    return false;
  };

  return (
    <div className="fixed inset-0 top-[64px] md:top-[72px] bottom-[64px] md:bottom-0 flex bg-[#f0f2f5] dark:bg-[#0a0c10] overflow-hidden animate-fade-in">

      {/* SIDEBAR (LISTA DE CHATS) */}
      <div className={`
        flex-col bg-white dark:bg-[#12161f] border-r dark:border-white/5 z-40 transition-all
        ${selectedChat ? 'hidden md:flex md:w-80 lg:w-[360px]' : 'flex w-full md:w-80 lg:w-[360px]'}
      `}>
        <div className="p-4 space-y-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                 <h2 className="text-xl font-black dark:text-white uppercase tracking-tighter">Mensagens</h2>
              </div>
              <button 
                onClick={() => onNavigate('create-group')}
                className="p-2 bg-blue-600 text-white rounded-full hover:bg-blue-700 transition-all shadow-lg active:scale-90"
              >
                <PlusIcon className="h-5 w-5 stroke-[3]" />
              </button>
           </div>

           <div className="relative">
              <MagnifyingGlassIcon className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input placeholder="Buscar..." className="w-full pl-11 pr-4 py-2.5 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-xs dark:text-white focus:ring-1 focus:ring-blue-500 transition-all"/>
           </div>

           <div className="flex gap-2 pb-1 overflow-x-auto no-scrollbar">
              {['ALL', 'PRIVATE', 'GROUP'].map(tab => (
                 <button key={tab} onClick={() => setFilterTab(tab as any)} className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${filterTab === tab ? 'bg-blue-600 text-white shadow-md' : 'text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'}`}>
                    {tab === 'ALL' ? 'Todos' : tab === 'PRIVATE' ? 'Privados' : 'Grupos'}
                 </button>
              ))}
           </div>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar px-1">
          {filteredConversations.map(chat => {
            const isGroup = chat.type === ChatType.GROUP;
            const lastMsg = chat.messages[chat.messages.length - 1];
            const isActive = selectedChat?.id === chat.id;

            return (
              <button
                key={chat.id}
                onClick={() => setSelectedChat(chat)}
                className={`w-full flex items-center p-3 rounded-2xl transition-all mb-0.5 ${isActive ? 'bg-blue-600 text-white shadow-md' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
              >
                <div className="relative shrink-0">
                   <img src={chat.groupImage || DEFAULT_PROFILE_PIC} className="w-12 h-12 rounded-full object-cover border border-black/5 shadow-sm bg-white" />
                   {isGroup && <div className="absolute -bottom-0.5 -right-0.5 bg-blue-600 p-0.5 rounded-full border border-white"><UserGroupIcon className="h-2.5 w-2.5 text-white"/></div>}
                </div>
                <div className="ml-3 text-left overflow-hidden flex-1">
                   <div className="flex justify-between items-center mb-0.5">
                      <p className={`font-black text-sm truncate uppercase tracking-tighter ${isActive ? 'text-white' : 'dark:text-white'}`}>{isGroup ? chat.groupName : 'Chat Privado'}</p>
                      {lastMsg && <span className={`text-[8px] font-bold ${isActive ? 'text-blue-100' : 'text-gray-400'}`}>{new Date(lastMsg.timestamp).getHours()}:{new Date(lastMsg.timestamp).getMinutes().toString().padStart(2, '0')}</span>}
                   </div>
                   <p className={`text-[11px] truncate leading-tight ${isActive ? 'text-blue-100' : 'text-gray-400 font-medium'}`}>
                      {lastMsg ? (lastMsg.isDeleted ? '🚫 Mensagem apagada' : lastMsg.text || '📷 Imagem') : 'Nenhuma mensagem'}
                   </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* CHAT AREA (CONVERSA) */}
      <div className={`flex-col h-full relative w-full ${selectedChat ? 'flex' : 'hidden md:flex flex-1'}`}>
        {selectedChat ? (
          <>
            {/* Header com Tema */}
            <div className={`h-16 flex items-center justify-between px-4 text-white z-30 transition-colors duration-500 ${themeStyles.primary} shadow-lg shrink-0`}>
               <div className="flex items-center gap-3">
                  <button onClick={() => setSelectedChat(null)} className="md:hidden p-2 text-white/90 hover:bg-white/10 rounded-full"><ArrowLeftIcon className="h-5 w-5 stroke-[3]"/></button>
                  <div className="flex items-center gap-3 cursor-pointer" onClick={() => setShowGroupMenu(!showGroupMenu)}>
                     <img src={selectedChat.groupImage || DEFAULT_PROFILE_PIC} className="w-10 h-10 rounded-full object-cover border-2 border-white/20 bg-white" />
                     <div className="leading-tight">
                        <h3 className="text-sm font-black uppercase tracking-tight">{selectedChat.groupName || 'Chat Privado'}</h3>
                        <p className="text-[9px] text-white/80 font-bold uppercase">{selectedChat.type === ChatType.GROUP ? `${selectedChat.participants.length} membros` : 'Online'}</p>
                     </div>
                  </div>
               </div>

               <div className="flex items-center gap-1">
                  {selectedChat.type === ChatType.PRIVATE && (
                    <button onClick={() => startCall('voice')} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PhoneIcon className="h-5 w-5"/></button>
                  )}

                  {/* Seletor de Tema para Admin */}
                  {selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id && (
                    <div className="relative">
                       <button onClick={() => setShowThemeMenu(!showThemeMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><PaintBrushIcon className="h-5 w-5"/></button>
                       {showThemeMenu && (
                          <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in overflow-hidden max-h-60 overflow-y-auto custom-scrollbar">
                             <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest p-2 border-b dark:border-white/5">Alterar Tema</p>
                             {(Object.keys(THEME_CONFIG) as GroupTheme[]).map(t => (
                               <button 
                                key={t} 
                                onClick={() => handleChangeTheme(t)}
                                className="w-full flex items-center gap-3 p-3 hover:bg-gray-50 dark:hover:bg-white/5 rounded-xl transition-all"
                               >
                                  <div className={`w-4 h-4 rounded-full ${THEME_CONFIG[t].primary}`} />
                                  <span className="text-[10px] font-black uppercase text-gray-600 dark:text-gray-300">{t}</span>
                               </button>
                             ))}
                          </div>
                       )}
                    </div>
                  )}

                  {/* Menu do Grupo / Chat (Três Pontinhos) */}
                  <div className="relative">
                    <button onClick={() => setShowGroupMenu(!showGroupMenu)} className="p-2.5 hover:bg-white/10 rounded-full transition-all"><EllipsisVerticalIcon className="h-5 w-5"/></button>
                    {showGroupMenu && (
                        <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-[#1a1c23] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 z-[100] p-2 animate-fade-in">
                            <button className="w-full text-left px-4 py-3 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-2 text-xs dark:text-white rounded-xl transition-all" onClick={() => { alert(`Chat: ${selectedChat.groupName || 'Privado'}`); setShowGroupMenu(false); }}>
                                <InformationCircleIcon className="h-4 w-4 text-blue-500" /> Detalhes
                            </button>

                            {selectedChat.type === ChatType.GROUP && (
                                <button onClick={handleLeaveGroup} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all">
                                    <ArrowRightOnRectangleIcon className="h-4 w-4" /> Sair do Grupo
                                </button>
                            )}

                            {selectedChat.type === ChatType.PRIVATE && (
                                <button onClick={handleDeleteChat} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all border-t border-gray-100 dark:border-white/5 mt-1">
                                    <TrashIcon className="h-4 w-4" /> Excluir Conversa
                                </button>
                            )}

                            {selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id && (
                                <button onClick={handleDeleteChat} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-600 font-bold rounded-xl transition-all border-t border-gray-100 dark:border-white/5 mt-1">
                                    <TrashIcon className="h-4 w-4" /> Excluir Grupo
                                </button>
                            )}
                        </div>
                    )}
                  </div>
               </div>
            </div>

            {/* Chat Body com Fundo e Pattern */}
            <div className={`flex-1 overflow-y-auto p-2 md:p-6 custom-scrollbar relative transition-colors duration-500 ${themeStyles.bg}`}>
               <div className="absolute inset-0 opacity-[0.08] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

               <div className="max-w-4xl mx-auto flex flex-col gap-2 relative z-10 pb-4">
                  {selectedChat.messages.map((msg, i) => {
                    const isMine = msg.senderId === currentUser.id;
                    const prevMsg = selectedChat.messages[i-1];
                    const showName = selectedChat.type === ChatType.GROUP && !isMine && (!prevMsg || prevMsg.senderId !== msg.senderId);

                    // Lógica para visibilidade do texto:
                    // Se for minha mensagem: usa bubble do tema. Se o tema for escuro (Black), texto é branco. Caso contrário, escuro.
                    // Se NÃO for minha mensagem: usa fundo branco/darkcard padrão.

                    // Bubble Styles for sender
                    const senderBubbleStyle = isMine 
                        ? `${themeStyles.bubble} rounded-tr-none ${chatTheme === 'black' ? 'text-white' : 'text-[#1f2937]'}` 
                        : 'bg-white dark:bg-[#12161f] rounded-tl-none dark:text-white';

                    return (
                      <div key={msg.id} className={`flex w-full ${isMine ? 'justify-end' : 'justify-start'}`}>

                         {/* Bubble Container: Click to open options */}
                         <div 
                           onClick={() => !msg.isDeleted && setSelectedMessageForAction(msg)}
                           className={`
                             relative max-w-[85%] md:max-w-[65%] p-2 rounded-2xl shadow-sm cursor-pointer active:scale-[0.98] transition-transform
                             ${senderBubbleStyle}
                           `}
                         >

                            {/* Reply Context */}
                            {msg.replyTo && !msg.isDeleted && (
                               <div className="mb-1 pl-2 border-l-2 border-blue-500 bg-black/5 dark:bg-white/5 rounded-r-md p-1 opacity-80">
                                  <p className="text-[9px] font-bold text-blue-600 dark:text-blue-400">{msg.replyTo.senderName}</p>
                                  <p className="text-[10px] truncate max-w-[150px]">{msg.replyTo.text}</p>
                               </div>
                            )}

                            {showName && <p className={`text-[10px] font-black uppercase mb-1 px-1 ${themeStyles.text}`}>Membro #{msg.senderId.slice(-4)}</p>}

                            {msg.isDeleted ? (
                                <div className="italic text-gray-500 text-xs px-2 py-1 flex items-center gap-1">
                                   <XMarkIcon className="h-3 w-3" /> <span className="opacity-70">Mensagem apagada</span>
                                </div>
                            ) : (
                                <>
                                    {msg.imageUrl && <img src={msg.imageUrl} className="w-full h-auto rounded-xl mb-1.5" alt="Anexo" />}
                                    <div className="px-1 flex flex-col items-end gap-x-2">
                                       <p className="text-sm font-medium leading-relaxed whitespace-pre-wrap break-words min-w-0 w-full text-left">
                                          {msg.text} 
                                          {msg.isEdited && <span className="text-[9px] opacity-60 ml-1 italic">(editado)</span>}
                                       </p>
                                       <div className="flex items-center gap-1 mt-1 opacity-60">
                                          <span className="text-[9px] font-bold">
                                             {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                          </span>
                                          {isMine && <CheckBadgeIcon className={`h-3 w-3 ${chatTheme === 'black' ? 'text-white' : themeStyles.text}`} />}
                                       </div>
                                    </div>
                                </>
                            )}
                         </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
               </div>
            </div>

            {/* Input Área */}
            <div className="p-2 md:p-4 bg-white dark:bg-[#12161f] border-t dark:border-white/5 relative z-40 shrink-0">

               {/* Context Banner (Reply/Edit) */}
               {(replyingTo || editingMessageId) && (
                  <div className="absolute bottom-full left-0 w-full bg-gray-50 dark:bg-[#1a1c23] border-t border-black/5 dark:border-white/5 p-3 flex justify-between items-center animate-slide-up shadow-lg z-50">
                     <div className="flex items-center gap-3 px-2 border-l-4 border-blue-500 overflow-hidden">
                        <div className="text-blue-500 shrink-0">
                           {replyingTo ? <ArrowUturnLeftIcon className="h-5 w-5" /> : <PencilIcon className="h-5 w-5" />}
                        </div>
                        <div className="min-w-0">
                           <p className="text-[10px] font-black uppercase text-blue-600 dark:text-blue-400">
                              {replyingTo ? 'Respondendo' : 'Editando'}
                           </p>
                           <p className="text-xs text-gray-600 dark:text-gray-300 truncate">
                              {replyingTo ? replyingTo.text : ''}
                           </p>
