};

const saveChat = async (chat: ChatConversation) => {
  if (isFirebaseConfigured && db) {
    await setDoc(doc(db, "chats", chat.id), JSON.parse(JSON.stringify(chat)));
  }
};

export const createGroup = async (name: string, members: string[], adminId: string, desc: string, theme: GroupTheme, imageFile?: File, isPublic = false) => {
  let imageUrl = '';
  if (imageFile) imageUrl = await uploadFile(imageFile, 'groups');

  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.GROUP,
    participants: [...members, adminId],
    messages: [],
    groupName: name,
    groupImage: imageUrl,
    adminId,
    description: desc,
    theme,
    isPublic
  };
  await saveChat(newChat);
  return newChat;
};

export const sendMessage = async (chatId: string, msg: Message) => {
  const chatRef = doc(db, "chats", chatId);
  const chatSnap = await getDoc(chatRef);
  if (chatSnap.exists()) {
      const chat = chatSnap.data() as ChatConversation;
      const msgs = [...chat.messages, msg];
      await updateDoc(chatRef, { messages: msgs });

      // Notificar membros do grupo (exceto remetente)
      if (chat.type === ChatType.GROUP) {
          if (chat.participants.length < 20) {
              chat.participants.forEach(pid => {
                  if (pid !== msg.senderId) {
                      createNotification({ 
                          type: NotificationType.GROUP_POST, recipientId: pid, actorId: msg.senderId, groupName: chat.groupName, timestamp: Date.now() 
                      });
                  }
              });
          }
      } else {
          // Chat Privado
          const recipient = chat.participants.find(p => p !== msg.senderId);
          if (recipient) {
              createNotification({
                  type: NotificationType.MESSAGE, recipientId: recipient, actorId: msg.senderId, timestamp: Date.now()
              });
          }
      }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
