export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const saleRef = doc(db, "affiliate_sales", saleId);
    const saleSnap = await getDoc(saleRef);
    if(saleSnap.exists()) {
        const sale = saleSnap.data() as AffiliateSale;
        if(sale.isRated) return;

        await updateDoc(saleRef, { isRated: true });

        const prodRef = doc(db, "products", sale.productId);
        const prodSnap = await getDoc(prodRef);
        if(prodSnap.exists()) {
            const p = prodSnap.data() as Product;
            const newRating = { id: generateUUID(), saleId, userId: sale.buyerId, rating, comment, timestamp: Date.now() };
            const ratings = [...(p.ratings || []), newRating];
            const avg = ratings.reduce((acc, r) => acc + r.rating, 0) / ratings.length;
            await updateDoc(prodRef, { ratings, averageRating: avg, ratingCount: ratings.length });
        }
    }
};

