export const generateUUID = () => crypto.randomUUID();

async function sha1(str: string) {
  // Verifica se crypto.subtle está disponível (requer HTTPS ou localhost)
  if (!crypto || !crypto.subtle) {
      throw new Error("Crypto API indisponível");
  }
  const enc = new TextEncoder();
  const hash = await crypto.subtle.digest('SHA-1', enc.encode(str));
  return Array.from(new Uint8Array(hash))
    .map(v => v.toString(16).padStart(2, '0'))
    .join('');
}

const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

export const uploadFile = async (file: File, bucketFolder: string): Promise<string> => {
  // 1. Tentar Cloudinary
  try {
    const timestamp = Math.round((new Date()).getTime() / 1000);
    const paramsToSign = `timestamp=${timestamp}${CLOUDINARY_API_SECRET}`;

    // Tenta gerar assinatura. Se falhar (ex: http inseguro), pula para o catch
    const signature = await sha1(paramsToSign);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('api_key', CLOUDINARY_API_KEY);
    formData.append('timestamp', timestamp.toString());
    formData.append('signature', signature);

    const resourceType = file.type.startsWith('video/') ? 'video' : 'image';
    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/${resourceType}/upload`, {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
        throw new Error(`Cloudinary error: ${response.statusText}`);
    }

    const data = await response.json();
    if (data.secure_url) {
      return data.secure_url;
    }
  } catch (cloudinaryError) {
    console.warn('Upload Cloudinary falhou, tentando Firebase...', cloudinaryError);
  }

  // 2. Tentar Firebase Storage
  if (isFirebaseConfigured && storage) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${generateUUID()}.${fileExt}`;
      const storageRef = ref(storage, `${bucketFolder}/${fileName}`);
      await uploadBytes(storageRef, file);
      const downloadUrl = await getDownloadURL(storageRef);
      return downloadUrl;
    } catch (e) {
      console.warn('Upload Firebase falhou, tentando Base64 local...', e);
    }
  }

  // 3. Fallback Final: Base64 (Local)
  // Se tudo falhar, converte a imagem para string e salva direto no documento
  try {
      console.log('Usando fallback local (Base64) para garantir funcionamento.');
      return await fileToBase64(file);
  } catch (e) {
      console.error('Falha crítica no upload (todos os métodos):', e);
      return '';
  }
};

// --- AUTH & USERS ---

export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.trim();
  if (isFirebaseConfigured && auth && db) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const uid = userCredential.user.uid;
      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data() as User;
        // Garantir que arrays existam para evitar crash
        return { 
            ...userData, 
            id: uid,
            followers: userData.followers || [],
            followedUsers: userData.followedUsers || []
        };
      } else {
        throw new Error("Perfil não encontrado. Tente 'Criar nova conta' para corrigir.");
      }
    } catch (error: any) {
      let msg = error.message;
      if (error.code === 'auth/invalid-credential') msg = "Email ou senha incorretos.";
      throw new Error(msg);
    }
  }
  throw new Error("Modo offline não suportado para login.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.trim();
  if (isFirebaseConfigured && auth && db) {
    let uid = '';

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      if (error.code === 'auth/email-already-in-use') {
         const credential = await signInWithEmailAndPassword(auth, email, userData.password);
         uid = credential.user.uid;
         const userDoc = await getDoc(doc(db, "users", uid));
         if (userDoc.exists()) throw new Error("Este email já está cadastrado.");
      } else {
          throw new Error(error.message);
      }
    }

    const newUser: User = {
        id: uid, 
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
        balance: 0,
        credentials: userData.credentials || null,
        bio: userData.bio || null,
        verificationFileUrl: userData.verificationFileUrl || null,
        isAdmin: false,
        isVerified: false,
        followers: [],
        followedUsers: [],
        storeId: userData.userType === UserType.CREATOR ? generateUUID() : undefined
    };

    await setDoc(doc(db, "users", uid), JSON.parse(JSON.stringify(newUser)));

    if (newUser.userType === UserType.CREATOR && newUser.storeId) {
       const newStore: Store = {
         id: newUser.storeId,
         professorId: newUser.id,
         name: `Loja de ${newUser.firstName}`,
         description: 'Bem-vindo à minha loja oficial.',
         productIds: [],
         brandColor: '#2563eb'
       };
       await setDoc(doc(db, "stores", newStore.id), newStore);
    }

    return newUser;
  }
  throw new Error("Erro de configuração do Firebase.");
};

