export const sendMessage = async (chatId: string, msg: Message) => {
  const chatRef = doc(db, "chats", chatId);
  const chatSnap = await getDoc(chatRef);
  if (chatSnap.exists()) {
      const chat = chatSnap.data() as ChatConversation;
      const msgs = [...chat.messages, msg];
      await updateDoc(chatRef, { messages: msgs });

      if (chat.type === ChatType.GROUP) {
          if (chat.participants.length < 20) {
              chat.participants.forEach(pid => {
                  if (pid !== msg.senderId) {
                      createNotification({ 
                          type: NotificationType.GROUP_POST, recipientId: pid, actorId: msg.senderId, groupName: chat.groupName, timestamp: Date.now() 
                      });
                  }
              });
          }
      } else {
          const recipient = chat.participants.find(p => p !== msg.senderId);
          if (recipient) {
              createNotification({
                  type: NotificationType.MESSAGE, recipientId: recipient, actorId: msg.senderId, timestamp: Date.now()
              });
          }
      }
  }
};

