export const getCart = (): CartItem[] => {
  try { return JSON.parse(localStorage.getItem(KEYS.CART) || '[]'); } catch { return []; }
};
export const saveCart = (cart: CartItem[]) => localStorage.setItem(KEYS.CART, JSON.stringify(cart));
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if(existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const updateCartItemQuantity = (pid: string, qty: number) => {
    let cart = getCart();
    if (qty <= 0) cart = cart.filter(i => i.productId !== pid);
    else { const item = cart.find(i => i.productId === pid); if(item) item.quantity = qty; }
    saveCart(cart);
};
export const removeFromCart = (pid: string) => saveCart(getCart().filter(i => i.productId !== pid));

export const getAppTheme = (): GroupTheme => (localStorage.getItem(KEYS.THEME) as GroupTheme) || 'blue';
