export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  if (!isFirebaseConfigured || !db) return false;

  try {
    for (const item of cartItems) {
      const product = await findProductById(item.productId);
      if (!product) continue;
      const store = await findStoreById(product.storeId);
      if (!store) continue;

      const itemTotal = product.price * item.quantity;
      const commission = affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0;
      const netRevenue = itemTotal - commission;

      if (affiliateUserId) await updateUserBalance(affiliateUserId, commission);
      await updateUserBalance(store.professorId, netRevenue);

      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${generateUUID().slice(0,4)}`,
        productId: item.productId,
        buyerId,
        affiliateUserId: affiliateUserId || '',
        storeId: product.storeId,
        commissionEarned: commission,
        saleAmount: itemTotal,
        timestamp: Date.now(),
        status: OrderStatus.WAITLIST,
        isRated: false,
        shippingAddress,
        digitalContentUrl: product.digitalContentUrl,
        isDropshipping: product.isDropshipping,
        supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
      };

      await setDoc(doc(db, "affiliate_sales", sale.id), cleanData(sale));

      if (affiliateUserId) {
          await createNotification({
              type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, saleId: sale.id, timestamp: Date.now()
          });
      }
    }
    return true;
  } catch (e) {
    console.error("Erro na compra:", e);
    return false;
  }
};

