  if (isFirebaseConfigured && db) {
    const s = await getDocs(collection(db, "chats"));
    return s.docs.map(d => d.data() as ChatConversation);
  }
  return [];
};

const saveChat = async (chat: ChatConversation) => {
  if (isFirebaseConfigured && db) {
    await setDoc(doc(db, "chats", chat.id), cleanData(chat));
  }
};

export const createGroup = async (name: string, members: string[], adminId: string, desc: string, theme: GroupTheme, imageFile?: File, isPublic = false) => {
  let imageUrl = '';
  if (imageFile) imageUrl = await uploadFile(imageFile, 'groups');

  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.GROUP,
    participants: [...members, adminId],
    messages: [],
    groupName: name,
    groupImage: imageUrl,
    adminId,
    description: desc,
    theme,
    isPublic
  };
  await saveChat(newChat);
  return newChat;
};

// NOVA FUNÇÃO PARA INICIAR CONVERSA PRIVADA
export const startPrivateChat = async (currentUserId: string, targetUserId: string): Promise<string> => {
  if (!isFirebaseConfigured || !db) throw new Error("Offline");

  // 1. Verificar se já existe chat
  const allChats = await getChats();
  const existingChat = allChats.find(c => 
    c.type === ChatType.PRIVATE && 
    c.participants.includes(currentUserId) && 
    c.participants.includes(targetUserId)
  );

  if (existingChat) {
    return existingChat.id;
  }

  // 2. Se não existe, criar um novo
  const newChat: ChatConversation = {
    id: generateUUID(),
    type: ChatType.PRIVATE,
    participants: [currentUserId, targetUserId],
    messages: [],
    theme: 'blue'
  };

  await saveChat(newChat);
  return newChat.id;
};

export const sendMessage = async (chatId: string, msg: Message) => {
  const chatRef = doc(db, "chats", chatId);
  const chatSnap = await getDoc(chatRef);
  if (chatSnap.exists()) {
      const chat = chatSnap.data() as ChatConversation;
      // Sanitize message using the helper
      const cleanMsg = cleanData(msg);
      const msgs = [...chat.messages, cleanMsg];

      // Update with sanitized data
      await updateDoc(chatRef, { messages: msgs });

      if (chat.type === ChatType.GROUP) {
          if (chat.participants.length < 20) {
              chat.participants.forEach(pid => {
                  if (pid !== msg.senderId) {
                      createNotification({ 
                          type: NotificationType.GROUP_POST, recipientId: pid, actorId: msg.senderId, groupName: chat.groupName, timestamp: Date.now() 
                      });
                  }
              });
          }
      } else {
          const recipient = chat.participants.find(p => p !== msg.senderId);
          if (recipient) {
              createNotification({
                  type: NotificationType.MESSAGE, recipientId: recipient, actorId: msg.senderId, timestamp: Date.now()
              });
          }
      }
  }
};

export const editMessage = async (chatId: string, messageId: string, newText: string) => {
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        const msgs = chat.messages.map(m => m.id === messageId ? {...m, text: newText, isEdited: true} : m);
        // Sanitize the entire array to be safe
        await updateDoc(chatRef, { messages: cleanData(msgs) });
    }
}

export const deleteMessage = async (chatId: string, messageId: string) => {
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        // Ensure we handle undefined explicitly by setting to null or just relying on cleanData
        const msgs = chat.messages.map(m => m.id === messageId ? {...m, text: '', imageUrl: undefined, isDeleted: true} : m);
        await updateDoc(chatRef, { messages: cleanData(msgs) });
    }
}

export const joinGroup = async (groupId: string, userId: string) => {
    const chatRef = doc(db, "chats", groupId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        await updateDoc(chatRef, { participants: arrayUnion(userId) });
    }
}

export const leaveGroup = async (groupId: string, userId: string) => {
    const chatRef = doc(db, "chats", groupId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        await updateDoc(chatRef, { participants: arrayRemove(userId) });
    }
}

export const deleteChat = async (chatId: string) => {
    await deleteDoc(doc(db, "chats", chatId));
}

export const updateGroupTheme = async (groupId: string, theme: GroupTheme) => {
    await updateDoc(doc(db, "chats", groupId), { theme });
}

