export const addStory = async (uId: string, item: any) => {
    const newItem = { ...item, id: generateUUID(), timestamp: Date.now() };
    if (isFirebaseConfigured && db) {
        const storyRef = doc(db, "stories", uId);
        const storyDoc = await getDoc(storyRef);
        if (storyDoc.exists()) {
            await updateDoc(storyRef, { items: arrayUnion(cleanData(newItem)) });
        } else {
            const user = await findUserById(uId);
            if(user) {
                const newStory: Story = { userId: uId, userName: user.firstName, userProfilePic: user.profilePicture || '', items: [newItem] };
                await setDoc(storyRef, cleanData(newStory));
            }
        }
    }
};

