export const getAffiliateLinks = async (uid: string) => {
    if (isFirebaseConfigured && db) {
        const q = query(collection(db, "affiliate_links"), where("userId", "==", uid));
        const s = await getDocs(q);
        const links = s.docs.map(d => d.data());
        const enriched = [];
        for (const link of links) {
            const prod = await findProductById(link.productId);
            if (prod) {
                enriched.push({ ...link, productName: prod.name, productImage: prod.imageUrls[0], commissionRate: prod.affiliateCommissionRate });
            }
        }
        return enriched;
    }
    return [];
};

