// Modificado para garantir a privacidade: Retorna APENAS chats onde o usuário é participante
export const getChats = async (userId?: string): Promise<ChatConversation[]> => {
  if (isFirebaseConfigured && db) {
    try {
        let q;
        if (userId) {
            // SEGURANÇA E PRIVACIDADE: Filtra no banco apenas chats onde o usuário está incluso
            q = query(collection(db, "chats"), where("participants", "array-contains", userId));
        } else {
            // Fallback (não recomendado para produção real sem regras de segurança, mas mantido para admin ou debug)
            q = collection(db, "chats");
        }
        const s = await getDocs(q);
        return s.docs.map(d => d.data() as ChatConversation);
    } catch (e) {
        console.error("Erro ao buscar chats:", e);
        return [];
    }
  }
  return [];
};

