                                <InformationCircleIcon className="h-4 w-4 text-blue-500" /> Detalhes
                            </button>

                            {selectedChat.type === ChatType.GROUP && (
                                <button onClick={handleLeaveGroup} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all">
                                    <ArrowRightOnRectangleIcon className="h-4 w-4" /> Sair do Grupo
                                </button>
                            )}

                            {selectedChat.type === ChatType.PRIVATE && (
                                <button onClick={handleDeleteChat} className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-2 text-xs text-red-500 rounded-xl transition-all border-t border-gray-100 dark:border-white/5 mt-1">
                                    <TrashIcon className="h-4 w-4" /> Excluir Conversa
                                </button>
                            )}

                            {selectedChat.type === ChatType.GROUP && selectedChat.adminId === currentUser.id && (
