export const saveCart = (cart: CartItem[]) => localStorage.setItem(KEYS.CART, JSON.stringify(cart));
export const addToCart = (productId: string, quantity: number = 1, selectedColor?: string) => {
  const cart = getCart();
  const existing = cart.find(i => i.productId === productId && i.selectedColor === selectedColor);
  if(existing) existing.quantity += quantity;
  else cart.push({ productId, quantity, selectedColor });
  saveCart(cart);
};
export const updateCartItemQuantity = (pid: string, qty: number) => {
    let cart = getCart();
    if (qty <= 0) cart = cart.filter(i => i.productId !== pid);
    else { const item = cart.find(i => i.productId === pid); if(item) item.quantity = qty; }
    saveCart(cart);
};
export const removeFromCart = (pid: string) => saveCart(getCart().filter(i => i.productId !== pid));

export const getAppTheme = (): GroupTheme => (localStorage.getItem(KEYS.THEME) as GroupTheme) || 'blue';
export const saveAppTheme = (theme: GroupTheme) => localStorage.setItem(KEYS.THEME, theme);

export const updatePostSaves = async (pid: string, uid: string) => {
    const postRef = doc(db, "posts", pid);
    const snap = await getDoc(postRef);
    if(snap.exists()) {
        const p = snap.data() as Post;
        // CORREÇÃO CRÍTICA: Garante que p.saves seja um array
        const saves = p.saves || [];
        if (saves.includes(uid)) {
            await updateDoc(postRef, { saves: arrayRemove(uid) });
        } else {
            await updateDoc(postRef, { saves: arrayUnion(uid) });
        }
    }
};

export const updatePostShares = async (pid: string, uid: string) => { 
    const postRef = doc(db, "posts", pid);
    await updateDoc(postRef, { shares: arrayUnion(uid) });
};

export const toggleFollowUser = async (currentId: string, targetId: string) => {
    if (!isFirebaseConfigured || !db) return;

    const meRef = doc(db, "users", currentId);
    const targetRef = doc(db, "users", targetId);

    const meSnap = await getDoc(meRef);
    if (!meSnap.exists()) return;

    const meData = meSnap.data() as User;
    // CORREÇÃO CRÍTICA: Garante que seguidoUsers seja tratado como array mesmo se undefined
    const followedUsers = meData.followedUsers || [];
    const isFollowing = followedUsers.includes(targetId);

    if (isFollowing) {
        await updateDoc(meRef, { followedUsers: arrayRemove(targetId) });
        await updateDoc(targetRef, { followers: arrayRemove(currentId) });
    } else {
        await updateDoc(meRef, { followedUsers: arrayUnion(targetId) });
        await updateDoc(targetRef, { followers: arrayUnion(currentId) });
        await createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetId, actorId: currentId, timestamp: Date.now() });
    }
};

export const boostPost = async (pid: string, uid: string, budget: number, days: number) => {
    const postRef = doc(db, "posts", pid);
    if (await updateUserBalance(uid, -budget)) {
        await updateDoc(postRef, { isBoosted: true, boostExpires: Date.now() + (days * 86400000) });
        return true;
    }
    return false;
};

export const indicatePostToUser = async (pid: string, from: string, to: string) => {
    const postRef = doc(db, "posts", pid);
    const snap = await getDoc(postRef);
    if(snap.exists()) {
        const p = snap.data() as Post;
        // CORREÇÃO: Garante array
        const indicated = p.indicatedUserIds || [];
        if(indicated.includes(to)) return false;

        await updateDoc(postRef, { indicatedUserIds: arrayUnion(to) });
        await createNotification({ type: NotificationType.INDICATION, recipientId: to, actorId: from, postId: pid, timestamp: Date.now() });
        return true;
    }
    return false;
};

