// --- OTIMIZAÇÃO DE VÍDEO CLOUDINARY ---
export const getOptimizedVideoUrl = (url: string) => {
  if (!url || !url.includes('cloudinary.com')) return url;

  // Insere transformações para melhor desempenho de streaming
  // f_auto: Escolhe o melhor formato (webm, mp4, av1) suportado pelo navegador
  // q_auto: Ajusta a qualidade visual vs tamanho do arquivo automaticamente
  // vc_auto: Otimiza codec de vídeo
  // w_720: Limita largura a 720p para mobile (economiza banda), ajustar conforme necessidade
  const transformation = 'f_auto,q_auto,vc_auto';

  // Inserir a transformação logo após /upload/
  return url.replace('/upload/', `/upload/${transformation}/`);
};

async function sha1(str: string) {
  // Verifica se crypto.subtle está disponível (requer HTTPS ou localhost)
  if (!crypto || !crypto.subtle) {
      // Retorna nulo ou throw para fallback
      throw new Error("Crypto API indisponível (requer HTTPS ou localhost)");
  }
  const enc = new TextEncoder();
  const hash = await crypto.subtle.digest('SHA-1', enc.encode(str));
  return Array.from(new Uint8Array(hash))
    .map(v => v.toString(16).padStart(2, '0'))
    .join('');
}

const fileToBase64 = (file: File | Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

export const uploadFile = async (file: File | Blob, bucketFolder: string): Promise<string> => {
  // 1. Tentar Cloudinary (Prioridade para arquivos grandes como Stories/PDFs)
  try {
    const timestamp = Math.round((new Date()).getTime() / 1000);
    const paramsToSign = `timestamp=${timestamp}${CLOUDINARY_API_SECRET}`;

    // Tenta gerar assinatura. Se falhar (ex: http inseguro), pula para o catch
    const signature = await sha1(paramsToSign);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('api_key', CLOUDINARY_API_KEY);
    formData.append('timestamp', timestamp.toString());
    formData.append('signature', signature);

    // Detecção correta do tipo de recurso
    const resourceType = file.type.startsWith('video/') ? 'video' : 'image';

    // Upload para Cloudinary
    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/${resourceType}/upload`, {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
        throw new Error(`Cloudinary error: ${response.statusText}`);
    }

    const data = await response.json();
    if (data.secure_url) {
      return data.secure_url;
    }
  } catch (cloudinaryError) {
    console.warn('Upload Cloudinary falhou, tentando Firebase...', cloudinaryError);
  }

  // 2. Tentar Firebase Storage
  if (isFirebaseConfigured && storage && file instanceof File) {
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${generateUUID()}.${fileExt}`;
      const storageRef = ref(storage, `${bucketFolder}/${fileName}`);
      await uploadBytes(storageRef, file);
      const downloadUrl = await getDownloadURL(storageRef);
      return downloadUrl;
    } catch (e) {
      console.warn('Upload Firebase falhou, tentando Base64 local...', e);
    }
  }

  // 3. Fallback Final: Base64 (Local)
  try {
      console.log('Usando fallback local (Base64) para garantir funcionamento.');
      return await fileToBase64(file);
  } catch (e) {
      console.error('Falha crítica no upload (todos os métodos):', e);
      return '';
  }
};

