export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.trim();
  if (isFirebaseConfigured && auth && db) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const uid = userCredential.user.uid;
      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data() as User;
        const user = { 
            ...userData, 
            id: uid,
            followers: userData.followers || [],
            followedUsers: userData.followedUsers || [],
            isOnline: true // Optimistic update
        };

        // Atualiza status no banco
        updateUserStatus(uid, true);

        return user;
      } else {
        throw new Error("Perfil não encontrado. Tente 'Criar nova conta' para corrigir.");
      }
    } catch (error: any) {
      let msg = error.message;
      if (error.code === 'auth/invalid-credential') msg = "Email ou senha incorretos.";
      throw new Error(msg);
    }
  }
  throw new Error("Modo offline não suportado para login.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.trim();
  if (isFirebaseConfigured && auth && db) {
    let uid = '';

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      if (error.code === 'auth/email-already-in-use') {
         const credential = await signInWithEmailAndPassword(auth, email, userData.password);
         uid = credential.user.uid;
         const userDoc = await getDoc(doc(db, "users", uid));
         if (userDoc.exists()) throw new Error("Este email já está cadastrado.");
      } else {
          throw new Error(error.message);
      }
    }

    const newUser: User = {
        id: uid, 
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
        balance: 0,
        credentials: userData.credentials || null,
        bio: userData.bio || null,
        verificationFileUrl: userData.verificationFileUrl || null,
        isAdmin: false,
        isVerified: false,
        followers: [],
        followedUsers: [],
        storeId: userData.userType === UserType.CREATOR ? generateUUID() : undefined,
        isOnline: true,
        lastSeen: Date.now()
    };

    await setDoc(doc(db, "users", uid), cleanData(newUser));

    if (newUser.userType === UserType.CREATOR && newUser.storeId) {
       const newStore: Store = {
         id: newUser.storeId,
         professorId: newUser.id,
         name: `Loja de ${newUser.firstName}`,
         description: 'Bem-vindo à minha loja oficial.',
         productIds: [],
         brandColor: '#2563eb'
       };
       await setDoc(doc(db, "stores", newStore.id), newStore);
    }

    return newUser;
  }
  throw new Error("Erro de configuração do Firebase.");
};

