  if (postSnap.exists()) {
    const post = postSnap.data() as Post;
    // Garante que o comentário não tenha undefined
    const cleanComment = cleanData(comment);
    const newComments = [...(post.comments || []), cleanComment];
    await updateDoc(postRef, { comments: newComments });

    if (post.userId !== comment.userId) {
        await createNotification({ 
            type: NotificationType.COMMENT, recipientId: post.userId, actorId: comment.userId, postId: post.id, timestamp: Date.now() 
        });
    }
  }
};

export const deleteComment = async (postId: string, commentId: string) => {
    if (isFirebaseConfigured && db) {
        const postRef = doc(db, "posts", postId);
        const postSnap = await getDoc(postRef);
        if (postSnap.exists()) {
            const post = postSnap.data() as Post;
            const updatedComments = (post.comments || []).filter(c => c.id !== commentId);
            await updateDoc(postRef, { comments: updatedComments });
        }
    }
};

