}

interface ReelVideoProps {
  post: Post;
  currentUser: User;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  onFollowToggle: (userIdToFollow: string) => void;
  refreshUser: () => void;
  isIntersecting: boolean;
  onPostUpdate: () => void;
  // New props for global state and auto-scroll
  isMuted: boolean;
  onToggleMute: () => void;
  onVideoEnd: () => void;
}

const ReelVideo: React.FC<ReelVideoProps> = ({ 
  post, 
  currentUser, 
  onNavigate, 
  onFollowToggle, 
  refreshUser, 
  isIntersecting, 
  onPostUpdate,
  isMuted,
  onToggleMute,
  onVideoEnd
}) => {
  if (!post || !currentUser) return null;

  const videoRef = useRef<HTMLVideoElement>(null);
  const [showPlayIcon, setShowPlayIcon] = useState(false);
  const [isCommentsModalOpen, setIsCommentsModalOpen] = useState(false);
  const [isIndicateModalOpen, setIsIndicateModalOpen] = useState(false);
  const [likeHearts, setLikeHearts] = useState<{ id: number; x: number; y: number }[]>([]);
  const [videoProgress, setVideoProgress] = useState(0);
  const [postAuthor, setPostAuthor] = useState<User | null>(null);

  // Optimistic Likes state
  const [localLikes, setLocalLikes] = useState<string[]>(post.likes || []);
  const [isLiked, setIsLiked] = useState(post.likes?.includes(currentUser.id) || false);

  const clickTimeout = useRef<number | null>(null);

  useEffect(() => {
    const fetchAuthor = async () => {
      const u = await findUserById(post.userId);
      setPostAuthor(u || null);
    };
    fetchAuthor();
  }, [post.userId]);

  useEffect(() => {
    setLocalLikes(post.likes || []);
    setIsLiked(post.likes?.includes(currentUser.id) || false);
  }, [post.likes, currentUser.id]);

  const isFollowing = currentUser.followedUsers?.includes(post.userId);
  const hasSaved = post.saves?.includes(currentUser.id);
  const [audioTrack, setAudioTrack] = useState<AudioTrack | null>(null);

  useEffect(() => {
    if (post.reel?.audioTrackId) {
      findAudioTrackById(post.reel.audioTrackId).then(track => {
        setAudioTrack(track || null);
      });
    }
  }, [post.reel?.audioTrackId]);

  // Sync mute state whenever prop changes
  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.muted = isMuted;
    }
  }, [isMuted]);

  const syncPlay = useCallback(async () => {
    const video = videoRef.current;
    if (!video) return;
    try {
      video.muted = isMuted; // Ensure muted state is applied before playing
      if (video.paused) await video.play();
    } catch (e) {
      // Auto-play policy might block unmuted playback
      if (!isMuted) {
         // console.warn("Autoplay blocked, falling back to muted");
         // video.muted = true;
         // await video.play();
      }
    }
  }, [isMuted]);

  const syncPause = useCallback(() => {
    const video = videoRef.current;
    if (video && !video.paused) video.pause();
  }, []);

  useEffect(() => {
    if (isIntersecting) {
        // Reset progress when scrolling back to a video
        if (videoRef.current) {
            // Optional: reset to 0 if coming back? usually user prefers resume
            // videoRef.current.currentTime = 0; 
        }
        syncPlay();
    } else {
        syncPause();
    }
  }, [isIntersecting, syncPlay, syncPause]);

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      const progress = (videoRef.current.currentTime / videoRef.current.duration) * 100;
      setVideoProgress(progress);
    }
  };

  const togglePlayPause = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      syncPlay();
      setShowPlayIcon(false);
    } else {
      syncPause();
      setShowPlayIcon(true);
    }
  };

  const handleLike = async (e?: any) => {
    if (e) e.stopPropagation();

    // Optimistic
    const prevLiked = isLiked;
    const prevLikes = [...localLikes];

    setIsLiked(!prevLiked);
    if (prevLiked) {
        setLocalLikes(prev => prev.filter(id => id !== currentUser.id));
    } else {
        setLocalLikes(prev => [...prev, currentUser.id]);
    }

    try {
        await updatePostLikes(post.id, currentUser.id);
        refreshUser();
    } catch (err) {
        setIsLiked(prevLiked);
        setLocalLikes(prevLikes);
    }
  };

  const handleDoubleClick = (e: any) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX || (e.touches && e.touches[0].clientX)) - rect.left;
    const y = (e.clientY || (e.touches && e.touches[0].clientY)) - rect.top;

    const newHeart = { id: Date.now(), x, y };
    setLikeHearts(prev => [...prev, newHeart]);
    if (!isLiked) handleLike();
    setTimeout(() => setLikeHearts(prev => prev.filter(h => h.id !== newHeart.id)), 800);
  };

  const handleMainContainerClick = (e: React.MouseEvent) => {
    if (clickTimeout.current) {
      window.clearTimeout(clickTimeout.current);
      clickTimeout.current = null;
      handleDoubleClick(e);
    } else {
      clickTimeout.current = window.setTimeout(() => {
        togglePlayPause();
        clickTimeout.current = null;
      }, 250);
    }
  };

  if (!postAuthor || !post.reel) return null;

  // Use Cloudinary Optimized URL
  const optimizedVideoUrl = getOptimizedVideoUrl(post.reel.videoUrl);

  return (
    <div 
      className="relative w-full h-full snap-start snap-always overflow-hidden bg-black flex items-center justify-center"
      onClick={handleMainContainerClick}
    >
      {/* 1. LAYER: VIDEO */}
      <video
        ref={videoRef}
        src={optimizedVideoUrl}
        playsInline
        webkit-playsinline="true"
        onTimeUpdate={handleTimeUpdate}
        onEnded={onVideoEnd} // Trigger scroll to next
        className="w-full h-full object-cover md:max-w-lg md:mx-auto"
        style={{ filter: post.reel.filter || 'none' }}
      />

      {/* 2. LAYER: OVERLAYS */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/80 pointer-events-none z-10"></div>

      {/* 3. LAYER: INTERACTIVE ELEMENTS */}

      {/* Play Icon Feedback */}
      {showPlayIcon && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-30">
          <div className="bg-black/20 p-8 rounded-full backdrop-blur-md animate-scale-in">
            <PlayIcon className="h-16 w-16 text-white/80" />
          </div>
        </div>
      )}

      {/* Double Tap Hearts */}
      {likeHearts.map(heart => (
        <div key={heart.id} className="absolute z-50 pointer-events-none animate-like-heart" style={{ left: heart.x - 40, top: heart.y - 40 }}>
          <HeartIconSolid className="w-24 h-24 text-red-500 drop-shadow-[0_0_20px_rgba(239,68,68,0.8)]" />
        </div>
      ))}

      {/* ACTIONS SIDEBAR (Right) - Otimizado para caber em telas menores */}
      <div 
        className="absolute bottom-20 right-1 flex flex-col items-center gap-1.5 z-40 px-2"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Seguir */}
        {!isFollowing && currentUser.id !== post.userId && (
          <button 
            onClick={(e) => { e.stopPropagation(); onFollowToggle(post.userId); }} 
            className="flex flex-col items-center group p-1"
          >
            <div className="bg-blue-600 p-2 rounded-full shadow-2xl border border-white/20 group-active:scale-125 transition-transform">
              <UserPlusIcon className="h-6 w-6 text-white" />
            </div>
            <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Seguir</span>
          </button>
        )}

        {/* Volume */}
        <button 
          onClick={(e) => { e.stopPropagation(); onToggleMute(); }} 
          className="flex flex-col items-center group p-1"
        >
          <div className="bg-black/40 backdrop-blur-md p-2 rounded-full shadow-2xl border border-white/10 group-active:scale-125 transition-transform">
            {isMuted ? (
              <SpeakerXMarkIcon className="h-6 w-6 text-white" />
            ) : (
              <SpeakerWaveIcon className="h-6 w-6 text-white" />
            )}
          </div>
          <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Som</span>
        </button>

        {/* Like */}
        <button onClick={handleLike} className="flex flex-col items-center group p-1">
          <div className="transition-transform duration-200 group-active:scale-150">
            <HeartIconSolid className={`h-8 w-8 drop-shadow-xl ${isLiked ? 'text-red-500' : 'text-white'}`} />
          </div>
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{localLikes.length}</span>
        </button>

        {/* Comments */}
        <button onClick={(e) => { e.stopPropagation(); setIsCommentsModalOpen(true); }} className="flex flex-col items-center group p-1">
          <ChatIconOutline className="h-8 w-8 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{post.comments?.length || 0}</span>
        </button>

        {/* Save */}
        <button onClick={(e) => { e.stopPropagation(); updatePostSaves(post.id, currentUser.id); onPostUpdate(); }} className="flex flex-col items-center group p-1">
          <BookmarkIconSolid className={`h-8 w-8 drop-shadow-xl transition-all duration-300 group-active:scale-125 ${hasSaved ? 'text-yellow-400' : 'text-white'}`} />
          <span className="text-[10px] font-black text-white mt-0.5 drop-shadow-md">{post.saves?.length || 0}</span>
        </button>

        {/* Indicate */}
        <button onClick={(e) => { e.stopPropagation(); setIsIndicateModalOpen(true); }} className="flex flex-col items-center group p-1">
          <ShareIconOutline className="h-8 w-8 text-white drop-shadow-xl group-active:scale-125 transition-transform" />
          <span className="text-[8px] font-black text-white uppercase mt-0.5 drop-shadow-md">Indicar</span>
        </button>

        {/* Spinning Audio Icon */}
        <div className="mt-1">
          <div className="w-9 h-9 rounded-full bg-gradient-to-r from-gray-800 to-black border border-white/20 flex items-center justify-center overflow-hidden shadow-2xl animate-spin-slow">
            <img src={postAuthor.profilePicture || DEFAULT_PROFILE_PIC} className="w-full h-full object-cover opacity-60" />
          </div>
        </div>
      </div>

      {/* INFO AREA (Bottom Left) */}
      <div 
        className="absolute bottom-4 left-0 right-20 z-30 px-5 pb-4 pointer-events-none flex flex-col gap-1.5"
      >
        <div 
          className="flex items-center gap-2 pointer-events-auto cursor-pointer w-fit"
          onClick={(e) => { e.stopPropagation(); onNavigate('profile', { userId: post.userId }); }}
        >
          <span className="font-black text-base text-white hover:underline drop-shadow-lg">@{post.authorName}</span>
          <span className="bg-blue-600/90 backdrop-blur-md px-2 py-0.5 rounded-lg text-[8px] font-black text-white uppercase border border-white/10">Mestre</span>
        </div>

        <div className="pointer-events-auto max-w-full">
           <p className="text-xs text-white/95 font-medium leading-snug drop-shadow-md line-clamp-2">
            {post.reel.description}
           </p>
        </div>

        <div className="flex items-center gap-2 mt-1 pointer-events-auto w-fit bg-black/30 backdrop-blur-md px-3 py-1 rounded-full border border-white/5">
          <MusicalNoteIcon className="h-3 w-3 text-white animate-pulse" />
          <div className="overflow-hidden max-w-[120px]">
            <div className="whitespace-nowrap text-[9px] font-black text-white uppercase tracking-wider animate-marquee">
              {audioTrack ? `${audioTrack.title} - ${audioTrack.artist}` : `Áudio Original • ${post.authorName}`}
            </div>
          </div>
        </div>
      </div>

      {/* Progress Bar (Bottom) */}
      <div className="absolute bottom-0 left-0 w-full h-1 bg-white/10 z-50 pointer-events-none">
        <div 
          className="h-full bg-blue-600 transition-all duration-100 ease-linear shadow-[0_0_10px_#2563eb]" 
          style={{ width: `${videoProgress}%` }}
        />
      </div>

      {/* MODALS */}
      {isCommentsModalOpen && (
        <CommentsModal postId={post.id} currentUser={currentUser} onClose={() => setIsCommentsModalOpen(false)} onCommentsUpdated={onPostUpdate} />
      )}

      {isIndicateModalOpen && (
        <IndicateModal post={post} currentUser={currentUser} onClose={() => setIsIndicateModalOpen(false)} onPostUpdated={onPostUpdate} />
      )}

      <style>{`
        .animate-spin-slow { animation: spin 5s linear infinite; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        @keyframes marquee {
          0% { transform: translateX(100%); }
          100% { transform: translateX(-100%); }
        }
        .animate-marquee {
          display: inline-block;
          animation: marquee 8s linear infinite;
        }

        @keyframes like-heart {
          0% { transform: scale(0); opacity: 0; }
          20% { transform: scale(1.2) rotate(15deg); opacity: 1; }
          80% { transform: scale(1) rotate(-10deg); opacity: 1; }
          100% { transform: scale(2.5); opacity: 0; }
        }
        .animate-like-heart { animation: like-heart 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

const ReelsPage: React.FC<ReelsPageProps> = ({ currentUser, onNavigate, refreshUser, startPostId }) => {
  const [reels, setReels] = useState<Post[]>([]);
  const containerRef = useRef<HTMLDivElement>(null);
  const [visibleIdx, setVisibleIdx] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isMuted, setIsMuted] = useState(true); // Global mute state

  const fetchReels = useCallback(async () => {
    const allPosts = await getPosts();
    const posts = allPosts.filter(p => p.type === PostType.REEL).sort((a, b) => b.timestamp - a.timestamp);
    setReels(posts);

    // Se houver um post inicial, encontrar o índice
    if (startPostId) {
      const idx = posts.findIndex(p => p.id === startPostId);
      if (idx !== -1) {
        setVisibleIdx(idx);
        // Pequeno delay para garantir que o DOM renderizou
        setTimeout(() => {
          if (containerRef.current?.children[idx]) {
            containerRef.current.children[idx].scrollIntoView();
          }
        }, 100);
      }
    }
    setLoading(false);
  }, [startPostId]);

  useEffect(() => {
    fetchReels();
  }, [fetchReels]);

  useEffect(() => {
    const observer = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          const idx = Number((e.target as HTMLElement).dataset.idx);
          setVisibleIdx(idx);
        }
      });
    }, { threshold: 0.65 });

    const items = containerRef.current?.children;
    if (items) {
      Array.from(items).forEach(item => {
        if ((item as HTMLElement).dataset.idx !== undefined) {
          observer.observe(item as Element);
        }
      });
    }
    return () => observer.disconnect();
  }, [reels]);

  const handleFollowToggle = useCallback(
    (userIdToFollow: string) => {
      toggleFollowUser(currentUser.id, userIdToFollow);
      refreshUser();
      fetchReels();
    },
    [currentUser.id, refreshUser, fetchReels],
  );

  const handleNextReel = (currentIndex: number) => {
    if (containerRef.current) {
        const nextIndex = currentIndex + 1;
        if (nextIndex < reels.length) {
            // Scroll to next
            const nextElement = containerRef.current.children[nextIndex];
            nextElement?.scrollIntoView({ behavior: 'smooth' });
        } else {
            // Optional: Loop back to start or do nothing
            // containerRef.current.children[0].scrollIntoView({ behavior: 'smooth' });
        }
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center w-full h-screen bg-black text-white text-xl">
        <div className="w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mr-3"></div>
        Carregando Reels...
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 md:top-[72px] md:ml-64 bottom-[64px] md:bottom-0 bg-black z-10"
    >
      <div 
        ref={containerRef} 
        className="w-full h-full overflow-y-scroll snap-y snap-mandatory no-scrollbar scroll-smooth"
        style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
      >
        {reels.length > 0 ? (
          reels.map((r, i) => (
            <div 
              key={r.id} 
              data-idx={i} 
              className="h-full w-full snap-start snap-always"
            >
              <ReelVideo 
                post={r} 
                currentUser={currentUser} 
                onNavigate={onNavigate} 
                onFollowToggle={handleFollowToggle} 
                refreshUser={refreshUser} 
                isIntersecting={i === visibleIdx}
                onPostUpdate={fetchReels}
                isMuted={isMuted}
                onToggleMute={() => setIsMuted(!isMuted)}
                onVideoEnd={() => handleNextReel(i)}
              />
            </div>
          ))
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-white p-10 text-center">
            <MusicalNoteIcon className="h-20 w-20 text-gray-800 mb-6" />
            <h3 className="text-2xl font-black uppercase tracking-tighter">Nenhum Reel ainda</h3>
            <p className="text-gray-500 mt-2 font-medium">Seja o primeiro mestre a publicar conteúdo vertical!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ReelsPage;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  updateUserBalance, 
  deletePost, 
  getGlobalSettings,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  addPost,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon,
  HandRaisedIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // GRAVAÇÃO DA LIVE
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const [isSavingReplay, setIsSavingReplay] = useState(false);

  const settings = getGlobalSettings();
  const platformTax = settings.platformTax;

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription to Live Data
  useEffect(() => {
    if (!postId) return;

    // Entrar na Live (Incrementar Viewer)
    manageLiveViewers(postId, 'join');

    // Inscrever para atualizações
    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        // Atualizar Chat
        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        // Atualizar Viewers
        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        // Detectar novos corações para animação
        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            // Spawn hearts based on difference (limit to avoid crash)
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    // Cleanup: Sair da Live (Decrementar Viewer)
    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount]);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    recordedChunksRef.current = [];
    // Tenta codecs comuns
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';

    try {
        const recorder = new MediaRecorder(stream, { mimeType });
        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) recordedChunksRef.current.push(event.data);
        };
        recorder.start(1000); // chunk a cada segundo
        mediaRecorderRef.current = recorder;
    } catch (e) {
        console.error("Erro ao iniciar gravação da live:", e);
    }
  };

  const handleEndLive = async () => {
    if (!window.confirm("Encerrar aula? O vídeo será salvo como Replay.")) return;

    setIsSavingReplay(true);

    // Parar gravação
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
    }

    // Aguardar buffer final
    await new Promise(resolve => setTimeout(resolve, 500));

    try {
        if (recordedChunksRef.current.length > 0) {
            const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });

            // Upload para Cloudinary
            const videoUrl = await uploadFile(blob, 'replays');

            // Criar Post de Replay
            if (videoUrl && post) {
                const replayPost: Post = {
                    id: generateUUID(),
                    userId: currentUser.id,
                    authorName: `${currentUser.firstName} ${currentUser.lastName}`,
                    type: PostType.REEL, // Replay aparece como Reel
                    timestamp: Date.now(),
                    content: `Replay: ${post.liveStream?.title || 'Live'}`,
                    reel: {
                        videoUrl: videoUrl,
                        description: `Gravação da live: ${post.liveStream?.description || ''}`,
                    },
                    likes: [],
                    comments: [],
                    shares: [],
                    saves: []
                };
                await addPost(replayPost);
                alert("Replay salvo com sucesso! Estará disponível no seu perfil em instantes.");
            }
        }
    } catch (e) {
        console.error("Erro ao salvar replay:", e);
        alert("Erro ao salvar replay da live.");
    }

    // Limpeza
    await deletePost(post!.id);
    handleExit();
    refreshUser();
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        // Remove tracks antigos
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);

        // Reiniciar gravação se necessário ou atualizar stream
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  // Inicialização da Câmera para o Criador
  useEffect(() => {
      if (creator && currentUser.id === creator.id) {
          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }
                  // Iniciar gravação automática para o host
                  startRecording(stream);
              } catch (e) {
                  console.error("Erro camera:", e);
              }
          };
          initCam();
      }
  }, [creator, currentUser.id]);

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      // Visual feedback local e remoto
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = () => {
    if (!pendingAmount || !creator) return;
    if ((currentUser.balance || 0) < pendingAmount) { alert("Saldo insuficiente."); return; }
    setIsProcessingDonation(true);
    setTimeout(() => {
      updateUserBalance(currentUser.id, -pendingAmount);
      updateUserBalance(creator.id, pendingAmount * (1 - platformTax));
      refreshUser();
      setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

      // Enviar mensagem de sistema no chat
      const sysMsg: Comment = {
          id: generateUUID(),
          userId: 'system',
          userName: 'Sistema',
          text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
          timestamp: Date.now()
      };
      sendLiveMessage(postId, sysMsg);
      pulseLiveHeart(postId);

      setTimeout(() => setDonationAlert(null), 5000);
      setIsProcessingDonation(false);
      setPendingAmount(null);
      setShowDonationModal(false);
    }, 1000);
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); // 50% to 90% of container width

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); // Feedback local imediato
      pulseLiveHeart(postId); // Persistir
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  if (isSavingReplay) {
      return (
          <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center text-white">
              <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-black uppercase tracking-widest">Salvando Replay...</h2>
              <p className="text-gray-400 text-xs mt-2">Otimizando vídeo no Cloudinary</p>
          </div>
      );
  }

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          // Visão do Criador (Local Video Mirror)
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          // Visão do Espectador (Simulado com imagem, já que não temos WebRTC server real aqui)
          // Em um app real, aqui entraria o Cloudinary Video Player (HLS) se fosse live via RTMP
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             {/* Simulação de Player */}
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER - Mobile Optimized */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           {/* Left: Profile Info */}
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           {/* Right: Controls & Viewers */}
           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button onClick={isProfessional ? handleEndLive : handleExit} className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90">
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* MIDDLE LAYER - Gift Alerts & Hearts */}
        <div className="flex-1 relative w-full pointer-events-none">
           {/* Donation/Gift Alert Centered Top */}
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {/* Hand Raised Indicator (if self) */}
           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           {/* Floating Hearts Container - Right Side */}
           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER - Chat & Inputs */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">

           {/* Chat List - Limit Height & Width on Mobile */}
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           {/* Input Row */}
           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
              <form onSubmit={handleSendMessage} className="flex-1 flex items-center gap-2 bg-white/10 backdrop-blur-lg rounded-full px-4 py-3 border border-white/10 focus-within:bg-white/20 transition-all shadow-lg min-w-0">
                 <input 
                   type="text" 
                   value={newMessage}
                   onChange={e => setNewMessage(e.target.value)}
                   onFocus={() => { /* logic to handle keyboard overlap if needed */ }}
                   placeholder="Comente algo..." 
                   className="bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/50 w-full min-w-0"
                 />
                 <button type="submit" disabled={!newMessage.trim()} className="text-white/80 hover:text-blue-400 transition-colors disabled:opacity-30 shrink-0">
                    <PaperAirplaneIcon className="h-5 w-5 -rotate-45" />
                 </button>
              </form>

              <div className="flex items-center gap-2 shrink-0">
                 <button 
                   onClick={handleSendHeart}
                   className="p-3 bg-gradient-to-tr from-pink-500 to-red-600 text-white rounded-full shadow-lg shadow-red-500/30 active:scale-75 transition-transform"
                 >
                    <HeartIcon className="h-5 w-5" />
                 </button>

                 <div className="relative">
                    <button 
                      onClick={() => setShowControls(!showControls)} 
                      className="p-3 bg-gray-800 rounded-full border border-white/20 text-white hover:bg-gray-700 transition-all shadow-lg"
                    >
                        <EllipsisHorizontalIcon className="h-5 w-5" />
                    </button>

                    {/* DROPDOWN MENU */}
                    {showControls && (
                        <div className="absolute bottom-full right-0 mb-4 bg-black/90 border border-white/10 rounded-2xl p-2 flex flex-col gap-2 shadow-2xl backdrop-blur-xl animate-scale-in origin-bottom-right min-w-[60px] items-center z-50">
                            {isProfessional ? (
                                <>
                                    <button onClick={toggleMic} className={`p-3 rounded-full transition-all ${isMicOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Microfone">
                                        {isMicOn ? <MicrophoneIcon className="h-5 w-5" /> : <MicrophoneIconOutline className="h-5 w-5" />}
                                    </button>
                                    <button onClick={toggleCamera} className={`p-3 rounded-full transition-all ${isCamOn ? 'bg-white text-black' : 'bg-white/10 text-white'}`} title="Câmera">
                                        {isCamOn ? <VideoCameraIcon className="h-5 w-5" /> : <VideoCameraIconOutline className="h-5 w-5" />}
                                    </button>
                                    <div className="h-px w-full bg-white/10 my-1"></div>
                                    <button onClick={handleEndLive} className="p-3 bg-red-600 rounded-full hover:bg-red-700 transition-all text-white" title="Encerrar">
                                        <PowerIcon className="h-5 w-5" />
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={() => { setShowDonationModal(true); setShowControls(false); }}
                                        className="p-3 bg-yellow-500 text-black rounded-full shadow-lg shadow-yellow-500/20 active:scale-90 transition-transform"
                                        title="Apoiar"
                                    >
                                        <BanknotesIcon className="h-5 w-5" />
                                    </button>
                                    <button 
                                        onClick={toggleHandRaise}
                                        className={`p-3 rounded-full transition-all active:scale-90 ${isHandRaised ? 'bg-orange-500 text-white' : 'bg-white/10 text-white'}`}
                                        title="Levantar Mão"
                                    >
                                        {isHandRaised ? <HandRaisedIcon className="h-5 w-5" /> : <HandRaisedOutline className="h-5 w-5" />}
                                    </button>
                                </>
                            )}
                        </div>
                    )}
                 </div>
              </div>
           </div>
        </div>
      </div>

      {/* MODAL APOIO */}
      {showDonationModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-2xl z-[100] flex items-center justify-center p-4 animate-fade-in" onClick={() => setShowDonationModal(false)}>
           <div className="bg-white dark:bg-[#12141c] w-full max-w-sm rounded-[3rem] p-10 shadow-2xl relative border border-white/5" onClick={e => e.stopPropagation()}>
              <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter text-center mb-8">Apoiar Mestre</h3>
              <div className="grid grid-cols-3 gap-3 mb-8">
                 {[1, 5, 10, 20, 50, 100].map(val => (
                   <button key={val} onClick={() => setPendingAmount(val)} className={`py-4 rounded-2xl font-black text-sm transition-all ${pendingAmount === val ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-500'}`}>${val}</button>
                 ))}
              </div>
              <button onClick={executeDonation} disabled={!pendingAmount || isProcessingDonation} className="w-full bg-blue-600 text-white py-5 rounded-[2rem] font-black text-xs uppercase shadow-xl transition-all active:scale-95">
                {isProcessingDonation ? 'Processando...' : 'Confirmar Envio'}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .mask-gradient-chat {
           mask-image: linear-gradient(to top, black 85%, transparent 100%);
           -webkit-mask-image: linear-gradient(to top, black 85%, transparent 100%);
        }
        .pb-safe {
           padding-bottom: max(env(safe-area-inset-bottom), 20px);
        }
        @keyframes slide-right-fade {
           from { opacity: 0; transform: translateX(-10px); }
           to { opacity: 1; transform: translateX(0); }
        }
        .animate-slide-right-fade { animation: slide-right-fade 0.2s ease-out forwards; }
        @keyframes shoutout { 0% { transform: translate(-50%, -100%); opacity: 0; } 15% { transform: translate(-50%, 0); opacity: 1; } 85% { transform: translate(-50%, 0); opacity: 1; } 100% { transform: translate(-50%, -100%); opacity: 0; } }
        .animate-shoutout { animation: shoutout 5s cubic-bezier(0.23, 1, 0.32, 1) forwards; }
      `}</style>
    </div>
  );
};

export default LiveStreamViewer;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { User, UserType, Store, Product, ProductType, OrderStatus, AffiliateSale } from '../types';
import { 
  getStores, 
  getProducts, 
  createProduct,
  updateStore,
  getAffiliateSales,
  updateSaleStatus,
  uploadFile,
  adminDeleteProduct,
  generateUUID,
  fulfillDropshippingOrder,
  updateSaleTracking,
  createStore,
  updateUser
} from '../services/storageService';
import { sourceDropshippingProducts } from '../services/geminiService';
import { 
  PlusIcon, 
  ArchiveBoxIcon,
  TrashIcon,
  CheckBadgeIcon,
  BoltIcon,
  XMarkIcon,
  MagnifyingGlassIcon,
  PaintBrushIcon,
  ClipboardDocumentListIcon,
  CurrencyDollarIcon,
  TruckIcon,
  GlobeAmericasIcon,
  CalculatorIcon,
  ArrowPathIcon,
  TagIcon,
  PhotoIcon
} from '@heroicons/react/24/solid';

interface StoreManagerPageProps {
  currentUser: User;
  refreshUser: () => void;
  onNavigate: (page: any, params?: any) => void;
}

type ManagerTab = 'inventory' | 'orders' | 'sourcing' | 'branding';

const BRAND_COLORS = [
  { name: 'Azul CyBer', hex: '#2563eb' },
  { name: 'Roxo Royal', hex: '#7c3aed' },
  { name: 'Verde Mint', hex: '#10b981' },
  { name: 'Preto Carbono', hex: '#0f172a' },
  { name: 'Laranja Solar', hex: '#f59e0b' },
  { name: 'Rosa Shock', hex: '#db2777' }
];

const CATEGORIES_SOURCING = [
    'Tech & Gadgets', 'Moda Masculina', 'Moda Feminina', 'Casa Inteligente', 'Fitness', 'Beleza'
];

const StoreManagerPage: React.FC<StoreManagerPageProps> = ({ currentUser, refreshUser, onNavigate }) => {
  const [userStore, setUserStore] = useState<Store | null>(null);
  const [storeProducts, setStoreProducts] = useState<Product[]>([]);
  const [storeSales, setStoreSales] = useState<AffiliateSale[]>([]);
  const [activeTab, setActiveTab] = useState<ManagerTab>('inventory');
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [loading, setLoading] = useState(true);

  const [brandName, setBrandName] = useState('');
  const [brandDesc, setBrandDesc] = useState('');
  const [brandColor, setBrandColor] = useState(BRAND_COLORS[0].hex);

  // Product Form
  const [pName, setPName] = useState('');
  const [pDesc, setPDesc] = useState('');
  const [pPrice, setPPrice] = useState('');
  const [pType, setPType] = useState<ProductType>(ProductType.DIGITAL_COURSE);
  const [pImg, setPImg] = useState('');
  const [pDigitalUrl, setPDigitalUrl] = useState('');
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sourcing & Import Logic
  const [searchQuery, setSearchQuery] = useState('');
  const [sourcingResults, setSourcingResults] = useState<any[]>([]);
  const [isSourcing, setIsSourcing] = useState(false);
  const [importModal, setImportModal] = useState<any | null>(null); // Produto sendo importado
  const [importPrice, setImportPrice] = useState<string>(''); // Preço final definido pelo usuário

  const [trackingModal, setTrackingModal] = useState<{saleId: string} | null>(null);
  const [trackingCode, setTrackingCode] = useState('');
  const [supplierOrderId, setSupplierOrderId] = useState('');

  const loadData = async () => {
    setLoading(true);
    const stores = await getStores();
    const myStore = stores.find(s => s.professorId === currentUser.id);
    if (myStore) {
      setUserStore(myStore);
      setBrandName(myStore.name);
      setBrandDesc(myStore.description);
      setBrandColor(myStore.brandColor || BRAND_COLORS[0].hex);
      const allProds = await getProducts();
      setStoreProducts(allProds.filter(p => p.storeId === myStore.id));
      const allSales = await getAffiliateSales();
      setStoreSales(allSales.filter(s => s.storeId === myStore.id).sort((a, b) => b.timestamp - a.timestamp));
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, [currentUser.id]);

  // Trigger sourcing on mount for generic categories
  useEffect(() => {
      if (activeTab === 'sourcing' && sourcingResults.length === 0) {
          handleSource("Tendências de Tecnologia");
      }
  }, [activeTab]);

  const handleSaveBranding = async () => {
    if (!userStore) return;
    const updated = { ...userStore, name: brandName, description: brandDesc, brandColor };
    await updateStore(updated);
    setUserStore(updated);
    alert('Identidade visual da loja atualizada!');
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
        const url = await uploadFile(file, 'products');
        setPImg(url);
    } catch (err) {
        alert('Erro ao enviar imagem do produto.');
    } finally {
        setUploading(false);
    }
  };

  const handleCreateProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userStore || uploading) return;

    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: pName,
      description: pDesc,
      price: parseFloat(pPrice),
      imageUrls: [pImg || 'https://picsum.photos/400/400?random=prod'],
      affiliateCommissionRate: 0.15,
      type: pType,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      digitalContentUrl: pType !== ProductType.PHYSICAL ? pDigitalUrl : undefined
    };

    await createProduct(newProduct);
    setIsAddingProduct(false);
    setPImg(''); setPName(''); setPDesc(''); setPPrice('');
    loadData();
    alert('Produto criado com sucesso!');
  };

  const handleDeleteProduct = async (id: string) => {
    if (confirm("Tem certeza que deseja excluir este produto?")) {
      await adminDeleteProduct(id);
      loadData();
    }
  };

  const handleFulfillOrder = async (sale: AffiliateSale) => {
    if (!sale.supplierCost) {
      alert("Custo do fornecedor não definido.");
      return;
    }

    if ((currentUser.balance || 0) < sale.supplierCost) {
      alert(`Saldo insuficiente para pagar o fornecedor ($${sale.supplierCost}). Recarregue sua carteira.`);
      return;
    }

    if (confirm(`Confirmar pagamento de $${sale.supplierCost} ao fornecedor para iniciar o despacho?`)) {
       const success = await fulfillDropshippingOrder(sale.id, currentUser.id, sale.supplierCost);
       if (success) {
         refreshUser(); 
         loadData();
         alert("Pedido enviado para processamento no fornecedor!");
       } else {
         alert("Erro ao processar pagamento.");
       }
    }
  };

  const handleAddTracking = async () => {
    if (!trackingModal || !trackingCode) return;
    await updateSaleStatus(trackingModal.saleId, OrderStatus.SHIPPING);
    await updateSaleTracking(trackingModal.saleId, trackingCode, supplierOrderId);
    setTrackingModal(null);
    setTrackingCode('');
    setSupplierOrderId('');
    loadData();
    alert("Código de rastreio atualizado!");
  }

  const handleSource = async (queryOverride?: string) => {
    const q = queryOverride || searchQuery;
    if (!q) return;
    setIsSourcing(true);
    const results = await sourceDropshippingProducts(q);
    setSourcingResults(results);
    setIsSourcing(false);
  };

  const openImportModal = (product: any) => {
      setImportModal(product);
      setImportPrice((product.originalPrice * 2).toFixed(2)); // Sugestão 2x markup
  };

  const confirmImport = async () => {
    if (!userStore || !importModal) return;

    const finalPrice = parseFloat(importPrice);
    if (isNaN(finalPrice) || finalPrice <= importModal.originalPrice) {
        alert("O preço de venda deve ser maior que o custo.");
        return;
    }

    const newProduct: Product = {
      id: generateUUID(),
      storeId: userStore.id,
      name: importModal.name,
      description: importModal.description,
      price: finalPrice,
      imageUrls: [importModal.imageUrl],
      affiliateCommissionRate: 0.1, // 10% padrão para afiliados
      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: importModal.externalProviderId,
      originalPrice: importModal.originalPrice
    };

    await createProduct(newProduct);
    setImportModal(null);
    loadData();
    alert('Item importado para sua vitrine com sucesso!');
  };

  const handleInstantUpgrade = async () => {
    setLoading(true);
    const newStoreId = generateUUID();

    await createStore({
        id: newStoreId,
        professorId: currentUser.id,
        name: `Loja de ${currentUser.firstName}`,
        description: 'Minha loja oficial no CyBerPhone.',
        productIds: []
    });

    await updateUser({ 
        ...currentUser, 
        userType: UserType.CREATOR,
        storeId: newStoreId,
