export const toggleFollowUser = async (currentId: string, targetId: string) => {
    if (!isFirebaseConfigured || !db) return;

    const meRef = doc(db, "users", currentId);
    const targetRef = doc(db, "users", targetId);

    const meSnap = await getDoc(meRef);
    if (!meSnap.exists()) return;

    const meData = meSnap.data() as User;
    // CORREÇÃO CRÍTICA: Garante que seguidoUsers seja tratado como array mesmo se undefined
    const followedUsers = meData.followedUsers || [];
    const isFollowing = followedUsers.includes(targetId);

    if (isFollowing) {
        await updateDoc(meRef, { followedUsers: arrayRemove(targetId) });
        await updateDoc(targetRef, { followers: arrayRemove(currentId) });
    } else {
        await updateDoc(meRef, { followedUsers: arrayUnion(targetId) });
        await updateDoc(targetRef, { followers: arrayUnion(currentId) });
        await createNotification({ type: NotificationType.NEW_FOLLOWER, recipientId: targetId, actorId: currentId, timestamp: Date.now() });
    }
};

