            type: amount > 0 ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL,
            amount: Math.abs(amount),
            description: amount > 0 ? 'Crédito em conta' : 'Débito em conta',
            timestamp: Date.now(),
            status: 'COMPLETED'
        };
        await setDoc(doc(db, "transactions", transaction.id), transaction);

        return true;
    }
    return false;
};

