export const fulfillDropshippingOrder = async (saleId: string, userId: string, cost: number) => {
    if (await updateUserBalance(userId, -cost)) {
        await updateSaleStatus(saleId, OrderStatus.PROCESSING_SUPPLIER);

        // Registrar especificamente a transação de dropshipping
        const transaction: Transaction = {
            id: generateUUID(),
            userId: userId,
            type: TransactionType.DROPSHIPPING_COST,
            amount: cost,
            description: `Pagamento Fornecedor (Pedido #${saleId.slice(-6)})`,
            timestamp: Date.now(),
            status: 'COMPLETED'
        };
        await setDoc(doc(db, "transactions", transaction.id), transaction);

        return true;
    }
    return false;
};

