// Helper para gravar transação. NUNCA chame updateUserBalance diretamente para finanças sem isso.
export const recordTransaction = async (
  userId: string, 
  type: TransactionType, 
  amount: number, 
  description: string
) => {
  if (isFirebaseConfigured && db) {
    const transaction: Transaction = {
      id: generateUUID(),
      userId,
      type,
      amount,
      description,
      timestamp: Date.now(),
      status: 'COMPLETED'
    };
    await setDoc(doc(db, "transactions", transaction.id), cleanData(transaction));
    return transaction.id;
  }
  return null;
};

// Função ATÔMICA (lógica) para atualizar saldo COM registro de transação
export const performFinancialOperation = async (
  userId: string, 
  amount: number, 
  type: TransactionType, 
  description: string
): Promise<boolean> => {
  if (!isFirebaseConfigured || !db) return false;

  const userRef = doc(db, "users", userId);

  try {
    // 1. Atualizar Saldo
    await updateDoc(userRef, {
      balance: increment(amount)
    });

    // 2. Registrar Transação (Auditoria)
    await recordTransaction(userId, type, Math.abs(amount), description);

    return true;
  } catch (e) {
    console.error(`Falha na operação financeira para ${userId}:`, e);
    // Em produção real, usaríamos Firestore Batches ou Transactions para garantir rollback
    return false;
  }
};

