export const getPosts = async (): Promise<Post[]> => {
  if (isFirebaseConfigured && db) {
    const q = query(collection(db, "posts"));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(d => {
        const p = d.data() as Post;
        // Sanitizar arrays para evitar crash no UI
        return {
            ...p,
            likes: p.likes || [],
            saves: p.saves || [],
            shares: p.shares || [],
            comments: p.comments || []
        };
    }).sort((a, b) => b.timestamp - a.timestamp);
  }
  return [];
};

// NOVA FUNCIONALIDADE: Subscrição em Tempo Real para Lives
export const subscribeToLivePost = (postId: string, callback: (post: Post) => void) => {
  if (!isFirebaseConfigured || !db) return () => {};

  return onSnapshot(doc(db, "posts", postId), (docSnap) => {
    if (docSnap.exists()) {
      const data = docSnap.data() as Post;
      // Garante que arrays existam
      const cleanPost = {
        ...data,
        likes: data.likes || [],
        comments: data.comments || [],
        liveChat: data.liveChat || [],
        liveViewerCount: data.liveViewerCount || 0,
        liveHeartCount: data.liveHeartCount || 0
      };
      callback(cleanPost);
    }
  });
};

