import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Post, User, Comment, PostType } from '../types';
import { 
  getPosts, 
  findUserById, 
  processDonation, 
  deletePost, 
  getGlobalSettings,
  subscribeToLivePost,
  sendLiveMessage,
  manageLiveViewers,
  pulseLiveHeart,
  generateUUID,
  addPost,
  uploadFile
} from '../services/storageService';
import { 
  MicrophoneIcon, 
  VideoCameraIcon, 
  XMarkIcon, 
  SignalIcon, 
  UsersIcon, 
  PowerIcon, 
  BanknotesIcon, 
  PaperAirplaneIcon, 
  SparklesIcon, 
  HeartIcon, 
  EllipsisHorizontalIcon, 
  HandRaisedIcon
} from '@heroicons/react/24/solid';
import { 
  MicrophoneIcon as MicrophoneIconOutline, 
  VideoCameraIcon as VideoCameraIconOutline,
  HandRaisedIcon as HandRaisedOutline
} from '@heroicons/react/24/outline';
import { DEFAULT_PROFILE_PIC } from '../data/constants';

interface LiveStreamViewerProps {
  currentUser: User;
  postId: string;
  onNavigate: (page: string, params?: Record<string, string>) => void;
  refreshUser: () => void;
}

const LiveStreamViewer: React.FC<LiveStreamViewerProps> = ({ currentUser, postId, onNavigate, refreshUser }) => {
  const [post, setPost] = useState<Post | null>(null);
  const [creator, setCreator] = useState<User | null>(null);
  const [isMicOn, setIsMicOn] = useState(true);
  const [isCamOn, setIsCamOn] = useState(true);
  const [isHandRaised, setIsHandRaised] = useState(false);

  const [showDonationModal, setShowDonationModal] = useState(false);
  const [showControls, setShowControls] = useState(false); 
  const [pendingAmount, setPendingAmount] = useState<number | null>(null);
  const [isProcessingDonation, setIsProcessingDonation] = useState(false);
  const [donationAlert, setDonationAlert] = useState<{name: string, amount: number} | null>(null);

  // Real-time Data
  const [chatMessages, setChatMessages] = useState<Comment[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [floatingHearts, setFloatingHearts] = useState<{id: number, left: number, color: string}[]>([]);
  const [viewerCount, setViewerCount] = useState(0);
  const [lastHeartCount, setLastHeartCount] = useState(0);

  const streamRef = useRef<MediaStream | null>(null);
  const videoElementRef = useRef<HTMLVideoElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // GRAVAÇÃO DA LIVE
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const recordedChunksRef = useRef<Blob[]>([]);
  const [isSavingReplay, setIsSavingReplay] = useState(false);

  const stopStreams = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
        streamRef.current?.removeTrack(track);
      });
      streamRef.current = null;
    }
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
      mediaRecorderRef.current.stop();
    }
  }, []);

  // 1. Initial Load & Creator Info
  useEffect(() => {
    const fetchData = async () => {
        const posts = await getPosts();
        const foundPost = posts.find(p => p.id === postId);
        if (foundPost && foundPost.liveStream) {
            setPost(foundPost);
            const author = await findUserById(foundPost.userId);
            setCreator(author || null);
        } else {
            onNavigate('feed');
        }
    };
    fetchData();

    return () => {
      stopStreams();
    };
  }, [postId, onNavigate, stopStreams]);

  // 2. Real-time Subscription to Live Data
  useEffect(() => {
    if (!postId) return;

    // Entrar na Live (Incrementar Viewer)
    manageLiveViewers(postId, 'join');

    // Inscrever para atualizações
    const unsubscribe = subscribeToLivePost(postId, (updatedPost) => {
        if (!updatedPost) return;

        // Atualizar Chat
        if (updatedPost.liveChat) {
            setChatMessages(updatedPost.liveChat);
        }

        // Atualizar Viewers
        if (updatedPost.liveViewerCount !== undefined) {
            setViewerCount(updatedPost.liveViewerCount);
        }

        // Detectar novos corações para animação
        if (updatedPost.liveHeartCount && updatedPost.liveHeartCount > lastHeartCount) {
            const diff = updatedPost.liveHeartCount - lastHeartCount;
            // Spawn hearts based on difference (limit to avoid crash)
            for(let i=0; i<Math.min(diff, 5); i++) {
                setTimeout(() => addFloatingHeart(false), i * 150);
            }
            setLastHeartCount(updatedPost.liveHeartCount);
        }
    });

    // Cleanup: Sair da Live (Decrementar Viewer)
    return () => {
        unsubscribe();
        manageLiveViewers(postId, 'leave');
    };
  }, [postId, lastHeartCount]);

  // Scroll to bottom of chat
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  const startRecording = (stream: MediaStream) => {
    recordedChunksRef.current = [];
    // Tenta codecs comuns
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9') ? 'video/webm;codecs=vp9' : 'video/webm';

    try {
        const recorder = new MediaRecorder(stream, { mimeType });
        recorder.ondataavailable = (event) => {
            if (event.data.size > 0) recordedChunksRef.current.push(event.data);
        };
        recorder.start(1000); // chunk a cada segundo
        mediaRecorderRef.current = recorder;
    } catch (e) {
        console.error("Erro ao iniciar gravação da live:", e);
    }
  };

  const handleEndLive = async () => {
    if (!window.confirm("Encerrar aula? O vídeo será salvo como Replay.")) return;

    setIsSavingReplay(true);

    // Parar gravação
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
    }

    // Aguardar buffer final
    await new Promise(resolve => setTimeout(resolve, 500));

    try {
        if (recordedChunksRef.current.length > 0) {
            const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });

            // Upload para Cloudinary
            const videoUrl = await uploadFile(blob, 'replays');

            // Criar Post de Replay
            if (videoUrl && post) {
                const replayPost: Post = {
                    id: generateUUID(),
                    userId: currentUser.id,
                    authorName: `${currentUser.firstName} ${currentUser.lastName}`,
                    type: PostType.REEL, // Replay aparece como Reel
                    timestamp: Date.now(),
                    content: `Replay: ${post.liveStream?.title || 'Live'}`,
                    reel: {
                        videoUrl: videoUrl,
                        description: `Gravação da live: ${post.liveStream?.description || ''}`,
                    },
                    likes: [],
                    comments: [],
                    shares: [],
                    saves: []
                };
                await addPost(replayPost);
                alert("Replay salvo com sucesso! Estará disponível no seu perfil em instantes.");
            }
        }
    } catch (e) {
        console.error("Erro ao salvar replay:", e);
        alert("Erro ao salvar replay da live.");
    }

    // Limpeza
    await deletePost(post!.id);
    handleExit();
    refreshUser();
  };

  const setVideoRef = useCallback((node: HTMLVideoElement | null) => {
    if (node) {
      videoElementRef.current = node;
      if (isCamOn && streamRef.current) {
        node.srcObject = streamRef.current;
      }
    } else {
      videoElementRef.current = null;
    }
  }, [isCamOn]);

  const toggleCamera = async () => {
    if (isCamOn) {
      if (streamRef.current) {
        streamRef.current.getVideoTracks().forEach(track => {
          track.stop();
          streamRef.current?.removeTrack(track);
        });
      }
      setIsCamOn(false);
    } else {
      try {
        const videoStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } } 
        });
        const videoTrack = videoStream.getVideoTracks()[0];
        if (!streamRef.current) streamRef.current = new MediaStream();
        // Remove tracks antigos
        streamRef.current.getVideoTracks().forEach(t => { t.stop(); streamRef.current?.removeTrack(t); });
        streamRef.current.addTrack(videoTrack);
        setIsCamOn(true);

        // Reiniciar gravação se necessário ou atualizar stream
      } catch (err) { alert("Câmera indisponível."); }
    }
  };

  // Inicialização da Câmera para o Criador
  useEffect(() => {
      if (creator && currentUser.id === creator.id) {
          const initCam = async () => {
              try {
                  const stream = await navigator.mediaDevices.getUserMedia({ 
                      video: { facingMode: 'user' }, 
                      audio: true 
                  });
                  streamRef.current = stream;
                  if (videoElementRef.current) {
                      videoElementRef.current.srcObject = stream;
                  }
                  // Iniciar gravação automática para o host
                  startRecording(stream);
              } catch (e) {
                  console.error("Erro camera:", e);
              }
          };
          initCam();
      }
  }, [creator, currentUser.id]);

  const toggleMic = async () => {
    if (streamRef.current) {
        streamRef.current.getAudioTracks().forEach(track => track.enabled = !isMicOn);
        setIsMicOn(!isMicOn);
    }
  };

  const toggleHandRaise = () => {
    setIsHandRaised(!isHandRaised);
    setShowControls(false);
    if (!isHandRaised) {
      alert("✋ Você levantou a mão! O professor foi notificado.");
      // Visual feedback local e remoto
      pulseLiveHeart(postId);
    }
  };

  const handleExit = () => {
    stopStreams();
    onNavigate('feed');
  };

  const executeDonation = async () => {
    if (!pendingAmount || !creator || !post) return;

    if ((currentUser.balance || 0) < pendingAmount) { 
        alert("Saldo insuficiente."); 
        return; 
    }

    setIsProcessingDonation(true);

    // Processamento seguro da transação
    const success = await processDonation(currentUser.id, creator.id, pendingAmount, `Live: ${post.liveStream?.title || 'Aula'}`);

    if (success) {
        refreshUser();
        setDonationAlert({ name: currentUser.firstName, amount: pendingAmount });

        // Enviar mensagem de sistema no chat
        const sysMsg: Comment = {
            id: generateUUID(),
            userId: 'system',
            userName: 'Sistema',
            text: `🎉 ${currentUser.firstName} doou $${pendingAmount}!`,
            timestamp: Date.now()
        };
        sendLiveMessage(postId, sysMsg);
        pulseLiveHeart(postId);

        setTimeout(() => setDonationAlert(null), 5000);
        setIsProcessingDonation(false);
        setPendingAmount(null);
        setShowDonationModal(false);
    } else {
        alert("Erro ao processar doação.");
        setIsProcessingDonation(false);
    }
  };

  const addFloatingHeart = (isMe = true, customColor = '') => {
    const id = Date.now() + Math.random();
    const colors = ['text-red-500', 'text-pink-500', 'text-purple-500', 'text-blue-500'];
    const color = customColor || (isMe ? 'text-red-500' : colors[Math.floor(Math.random() * colors.length)]);
    const left = 50 + (Math.random() * 40); // 50% to 90% of container width

    setFloatingHearts(prev => [...prev, { id, left, color }]);
    setTimeout(() => {
      setFloatingHearts(prev => prev.filter(h => h.id !== id));
    }, 2000);
  };

  const handleSendHeart = () => {
      addFloatingHeart(true, 'text-red-600'); // Feedback local imediato
      pulseLiveHeart(postId); // Persistir
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    const msg: Comment = {
        id: generateUUID(),
        userId: currentUser.id,
        userName: currentUser.firstName,
        text: newMessage,
        timestamp: Date.now(),
        profilePic: currentUser.profilePicture
    };

    setNewMessage('');
    await sendLiveMessage(postId, msg);
  };

  if (!post || !post.liveStream || !creator) return null;
  const isProfessional = currentUser.id === creator.id;

  if (isSavingReplay) {
      return (
          <div className="fixed inset-0 bg-black z-[2000] flex flex-col items-center justify-center text-white">
              <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-black uppercase tracking-widest">Salvando Replay...</h2>
              <p className="text-gray-400 text-xs mt-2">Otimizando vídeo no Cloudinary</p>
          </div>
      );
  }

  return (
    <div className="fixed inset-0 bg-[#020408] z-[2000] flex flex-col h-[100dvh] w-full overflow-hidden text-white font-sans animate-fade-in">

      {/* VIDEO LAYER - Fullscreen */}
      <div className="absolute inset-0 z-0 bg-gray-900">
        {isProfessional ? (
          // Visão do Criador (Local Video Mirror)
          <video ref={setVideoRef} autoPlay playsInline muted className="w-full h-full object-cover scale-x-[-1]" />
        ) : (
          // Visão do Espectador
          <div className="w-full h-full flex flex-col items-center justify-center bg-gray-900 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-gray-800 via-gray-900 to-black">
             {/* Simulação de Player */}
             <div className="w-full h-full absolute inset-0">
                <img src={creator.profilePicture} className="w-full h-full object-cover opacity-50 blur-sm" />
             </div>
             <div className="z-10 flex flex-col items-center animate-pulse">
                 <div className="w-24 h-24 md:w-32 md:h-32 rounded-[2rem] bg-white/5 flex items-center justify-center text-4xl md:text-6xl font-black border border-white/10">
                    {creator.firstName[0]}
                 </div>
                 <p className="mt-6 font-black uppercase tracking-[0.3em] text-[10px] text-white">Transmissão Ao Vivo</p>
             </div>
          </div>
        )}
      </div>

      {/* OVERLAY INTERFACE */}
      <div className="absolute inset-0 z-10 flex flex-col justify-between pointer-events-none">

        {/* HEADER - Mobile Optimized */}
        <header className="w-full flex items-center justify-between px-4 pt-4 pb-12 bg-gradient-to-b from-black/80 to-transparent pointer-events-auto">
           {/* Left: Profile Info */}
           <div className="flex items-center gap-2 bg-black/30 backdrop-blur-md rounded-full p-1 pr-3 border border-white/10 shadow-lg max-w-[65%]">
                <img src={creator.profilePicture || DEFAULT_PROFILE_PIC} className="w-8 h-8 md:w-10 md:h-10 rounded-full border border-white/20 object-cover shrink-0" />
                <div className="flex flex-col min-w-0">
                    <span className="text-[10px] md:text-xs font-black uppercase tracking-wide leading-none text-white truncate">{creator.firstName}</span>
                    <span className="text-[8px] md:text-[10px] text-white/70 font-bold uppercase truncate">{post.liveStream.title}</span>
                </div>
                {!isProfessional && (
                    <button className="bg-red-600 text-[8px] md:text-[9px] font-black px-2 py-1 rounded-lg uppercase ml-1 hover:bg-red-700 transition-colors shadow-md shrink-0">
                        + Seguir
                    </button>
                )}
           </div>

           {/* Right: Controls & Viewers */}
           <div className="flex items-center gap-2 shrink-0">
              <div className="flex flex-col items-end">
                 <div className="bg-red-600 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-wider mb-1 shadow-sm flex items-center gap-1 animate-pulse">
                    <SignalIcon className="h-2 w-2" /> Ao Vivo
                 </div>
                 <div className="flex items-center gap-1 bg-black/30 backdrop-blur-md px-2 py-1 rounded-lg border border-white/10">
                    <UsersIcon className="h-3 w-3 text-white/80" />
                    <span className="text-[9px] font-black">{viewerCount.toLocaleString()}</span>
                 </div>
              </div>
              <button onClick={isProfessional ? handleEndLive : handleExit} className="p-2 bg-black/20 hover:bg-white/10 rounded-full backdrop-blur-md border border-white/5 transition-all active:scale-90">
                 <XMarkIcon className="h-5 w-5 md:h-6 md:w-6 text-white" />
              </button>
           </div>
        </header>

        {/* MIDDLE LAYER - Gift Alerts & Hearts */}
        <div className="flex-1 relative w-full pointer-events-none">
           {/* Donation/Gift Alert Centered Top */}
           {donationAlert && (
             <div className="absolute top-4 left-1/2 -translate-x-1/2 z-50 animate-shoutout w-[90%] max-w-sm px-2">
                <div className="bg-gradient-to-r from-yellow-400 to-orange-500 p-[2px] rounded-2xl shadow-[0_0_50px_rgba(234,179,8,0.6)]">
                    <div className="bg-black/90 backdrop-blur-xl px-4 py-3 rounded-2xl flex items-center gap-3">
                    <div className="bg-yellow-400 p-1.5 rounded-full text-black"><SparklesIcon className="h-4 w-4" /></div>
                    <div>
                        <p className="text-[10px] font-black text-yellow-400 uppercase tracking-widest">Nova Doação</p>
                        <p className="text-xs font-bold text-white">
                            <span className="text-sm">{donationAlert.name}</span> enviou <span className="text-green-400 font-black">${donationAlert.amount}</span>
                        </p>
                    </div>
                    </div>
                </div>
             </div>
           )}

           {/* Hand Raised Indicator (if self) */}
           {isHandRaised && (
             <div className="absolute top-20 right-4 animate-bounce">
                <div className="bg-yellow-500 text-black p-2 rounded-full shadow-lg border-2 border-white">
                   <HandRaisedIcon className="h-6 w-6" />
                </div>
             </div>
           )}

           {/* Floating Hearts Container - Right Side */}
           <div className="absolute bottom-0 right-2 w-16 h-[60%] overflow-hidden z-20">
              {floatingHearts.map(heart => (
                <HeartIcon 
                  key={heart.id} 
                  className={`absolute bottom-0 w-8 h-8 ${heart.color} animate-float-up drop-shadow-lg`}
                  style={{ left: `${Math.random() * 50}%` }} 
                />
              ))}
           </div>
        </div>

        {/* BOTTOM LAYER - Chat & Inputs */}
        <div className="w-full bg-gradient-to-t from-black/90 via-black/60 to-transparent pt-24 pb-8 md:pb-6 px-4 flex flex-col justify-end gap-3 pointer-events-auto">

           {/* Chat List - Limit Height & Width on Mobile */}
           <div className="w-[85%] md:w-[400px] h-40 md:h-64 overflow-y-auto no-scrollbar mask-gradient-chat pb-2">
              {chatMessages.map(msg => (
                <div key={msg.id} className="flex items-start gap-2 animate-slide-right-fade mb-2">
                   <div className={`px-3 py-1.5 rounded-2xl rounded-tl-none bg-black/40 backdrop-blur-sm border border-white/5 shadow-sm text-xs max-w-full break-words ${msg.userId === currentUser.id ? 'bg-blue-600/40 border-blue-500/30' : ''}`}>
                      <span className="font-black text-gray-300 mr-2 text-[10px] uppercase tracking-wide">{msg.userName}</span>
                      <span className="text-white font-medium text-[11px] leading-snug">{msg.text}</span>
                   </div>
                </div>
              ))}
              <div ref={chatEndRef} />
           </div>

           {/* Input Row */}
           <div className="flex items-center gap-2 md:gap-3 pb-safe mb-2 md:mb-0">
