import { MIN_DAILY_AD_BUDGET_USD, DEFAULT_PROFILE_PIC, CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import { 
  RocketLaunchIcon, 
  MegaphoneIcon, 
  CursorArrowRaysIcon, 
  PhotoIcon, 
  ChevronRightIcon, 
  ChevronLeftIcon, 
  SparklesIcon, 
  CheckCircleIcon, 
  MapPinIcon, 
  GlobeAltIcon, 
  XMarkIcon, 
  PlusIcon, 
  InformationCircleIcon, 
  UserGroupIcon, 
  ExclamationTriangleIcon, 
  ShieldCheckIcon, 
  PresentationChartLineIcon, 
  ArrowTrendingUpIcon, 
  CheckBadgeIcon, 
