  currentUser: User;
  refreshUser: () => void;
}

const WalletModal: React.FC<WalletModalProps> = ({ isOpen, mode, onClose, currentUser, refreshUser }) => {
  const settings = getGlobalSettings();
  const taxPercentage = settings.platformTax; // Ex: 0.1 para 10%

  if (!isOpen) return null;

  const handleTransaction = async (data: any) => {
    const requestedAmount = data.amount;

    if (data.mode === 'withdraw') {
      if ((currentUser.balance || 0) < requestedAmount) {
          alert("Saldo insuficiente para realizar este saque.");
          return;
      }

      const taxAmount = requestedAmount * taxPercentage;
      const netAmount = requestedAmount - taxAmount;

      if (window.confirm(`Confirmação de Saque:\n\nValor Solicitado: $${requestedAmount.toFixed(2)}\nTaxa CyBer (${(taxPercentage * 100).toFixed(0)}%): -$${taxAmount.toFixed(2)}\nValor Líquido a Receber: $${netAmount.toFixed(2)}`)) {
        // Usa a função segura de transação
        const success = await handleWalletTransaction(currentUser.id, requestedAmount, 'withdraw');

        if (success) {
            refreshUser();
            alert("Pedido de saque enviado! Os fundos líquidos serão processados para sua conta externa.");
            onClose();
        } else {
            alert("Erro ao processar saque.");
        }
      }
    } else {
      // Depósito simples
      const success = await handleWalletTransaction(currentUser.id, requestedAmount, 'deposit');

