export const performFinancialOperation = async (
  userId: string, 
  amount: number, 
  type: TransactionType, 
  description: string
): Promise<boolean> => {
  if (!isFirebaseConfigured || !db) return false;

  const userRef = doc(db, "users", userId);

  try {
    await updateDoc(userRef, {
      balance: increment(amount)
    });
    await recordTransaction(userId, type, Math.abs(amount), description);
    return true;
  } catch (e) {
    console.error(`Falha na operação financeira para ${userId}:`, e);
    return false;
  }
