// Processamento de Compra com Split de Pagamento e Logs Rigorosos
export const processProductPurchase = async (cartItems: CartItem[], buyerId: string, affiliateUserId: string | null, shippingAddress?: ShippingAddress) => {
  if (!isFirebaseConfigured || !db) return false;

  try {
    let totalSpent = 0;

    for (const item of cartItems) {
      const product = await findProductById(item.productId);
      if (!product) continue;
      const store = await findStoreById(product.storeId);
      if (!store) continue;

      const itemTotal = product.price * item.quantity;
      const commission = affiliateUserId ? itemTotal * product.affiliateCommissionRate : 0;
      const netRevenue = itemTotal - commission;

      // 1. Registrar Venda (Cria o objeto da venda)
      const sale: AffiliateSale = {
        id: `sale-${Date.now()}-${generateUUID().slice(0,4)}`,
        productId: item.productId,
        buyerId,
        affiliateUserId: affiliateUserId || '',
        storeId: product.storeId,
        commissionEarned: commission,
        saleAmount: itemTotal,
        timestamp: Date.now(),
        status: OrderStatus.WAITLIST,
        isRated: false,
        shippingAddress,
        digitalContentUrl: product.digitalContentUrl,
        isDropshipping: product.isDropshipping,
        supplierCost: product.originalPrice ? product.originalPrice * item.quantity : undefined
      };
      await setDoc(doc(db, "affiliate_sales", sale.id), cleanData(sale));

      // 2. Transação: Crédito ao Vendedor (Loja)
      await performFinancialOperation(
        store.professorId, 
        netRevenue, 
        TransactionType.SALE, 
        `Venda: ${product.name} (Qtd: ${item.quantity})`
      );

      // 3. Transação: Crédito ao Afiliado (se houver)
      if (affiliateUserId && commission > 0) {
        await performFinancialOperation(
          affiliateUserId,
          commission,
          TransactionType.SALE, // Consideramos venda afiliada como SALE ou comissão
          `Comissão: ${product.name} (Ref: ${buyerId.slice(0,4)})`
        );

        await createNotification({
            type: NotificationType.AFFILIATE_SALE, recipientId: affiliateUserId, actorId: buyerId, saleId: sale.id, timestamp: Date.now()
        });
      }

      totalSpent += itemTotal;
    }

    // 4. Transação: Débito do Comprador (Total)
    await performFinancialOperation(
        buyerId,
        -totalSpent,
        TransactionType.PURCHASE,
        `Compra de ${cartItems.length} itens`
    );

    return true;
  } catch (e) {
    console.error("Erro processamento compra:", e);
    return false;
  }
};

// Processamento de Doação em Live
export const processDonation = async (fromUserId: string, toUserId: string, amount: number, context: string) => {
    // 1. Débito do Doador
    const debitSuccess = await performFinancialOperation(
        fromUserId,
        -amount,
        TransactionType.DONATION,
        `Doação enviada: ${context}`
    );

    if (!debitSuccess) return false;

    // 2. Crédito ao Recebedor
    const settings = getGlobalSettings();
    const netAmount = amount * (1 - settings.platformTax);

    await performFinancialOperation(
        toUserId,
        netAmount,
        TransactionType.DONATION,
        `Doação recebida: ${context}`
    );

    return true;
};

