    if(snap.exists()) {
        const p = snap.data() as Post;
        // CORREÇÃO CRÍTICA: Garante que p.saves seja um array
        const saves = p.saves || [];
        if (saves.includes(uid)) {
            await updateDoc(postRef, { saves: arrayRemove(uid) });
        } else {
