      type: ProductType.PHYSICAL,
      ratings: [],
      averageRating: 5,
      ratingCount: 0,
      isDropshipping: true,
      externalProviderId: importModal.externalProviderId,
      originalPrice: importModal.originalPrice
    };

    await createProduct(newProduct);
    setImportModal(null);
    loadData();
    alert('Item importado para sua vitrine com sucesso!');
  };

