  const handleUpgradeProcess = async () => {
    if (!docFile) {
        alert("Obrigatório: Envie o documento de identificação profissional (PDF).");
        return;
    }
    if (!credentials.trim()) {
        alert("Obrigatório: Preencha sua especialidade.");
        return;
