  if (currentUser.userType === UserType.STANDARD) {
    return (
      <div className="container mx-auto px-4 pt-24 pb-32 max-w-4xl animate-fade-in">
         <div className="bg-white dark:bg-darkcard rounded-[3rem] p-10 md:p-16 shadow-2xl border dark:border-white/5 relative overflow-hidden">

            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>

            <div className="text-center mb-12">
                <div className="bg-blue-50 dark:bg-blue-900/10 w-24 h-24 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-xl">
                    <CheckBadgeIcon className="h-12 w-12 text-blue-600" />
                </div>
                <h2 className="text-3xl md:text-5xl font-black mb-4 tracking-tighter dark:text-white uppercase">Torne-se um Profissional</h2>
                <p className="text-gray-500 text-sm md:text-base font-medium max-w-xl mx-auto leading-relaxed">
                    Desbloqueie ferramentas de venda, crie sua loja oficial, transmita lives pagas e ganhe destaque no feed.
                </p>
            </div>

