export const updateUserStatus = async (userId: string, isOnline: boolean) => {
  if (isFirebaseConfigured && db) {
    try {
      const updateData = {
        isOnline: isOnline,
        lastSeen: Date.now()
      };
      await updateDoc(doc(db, "users", userId), updateData);
    } catch (e) {
      console.error("Erro ao atualizar status:", e);
    }
  }
};

export const loginUser = async (emailRaw: string, password: string): Promise<User> => {
  const email = emailRaw.trim();
  if (isFirebaseConfigured && auth && db) {
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const uid = userCredential.user.uid;
      const userDocRef = doc(db, "users", uid);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data() as User;
        const user = { 
            ...userData, 
            id: uid,
            followers: userData.followers || [],
            followedUsers: userData.followedUsers || [],
            isOnline: true 
        };
        updateUserStatus(uid, true);
        return user;
      } else {
        throw new Error("Perfil não encontrado. Tente 'Criar nova conta' para corrigir.");
      }
    } catch (error: any) {
      let msg = error.message;
      if (error.code === 'auth/invalid-credential') msg = "Email ou senha incorretos.";
      throw new Error(msg);
    }
  }
  throw new Error("Modo offline não suportado para login.");
};

export const registerUser = async (userData: any): Promise<User> => {
  const email = userData.email.trim();

  if (isFirebaseConfigured && auth && db) {
    // 1. Verificação Rigorosa de Unicidade (Firestore) antes de criar Auth
    // Firebase Auth checa email, mas queremos checar telefone e documento também.
    const usersRef = collection(db, "users");

    // Checar Email (redundância de segurança)
    const emailQuery = query(usersRef, where("email", "==", email));
    const emailSnapshot = await getDocs(emailQuery);
    if (!emailSnapshot.empty) {
        throw new Error("Este endereço de email já está em uso por outra conta.");
    }

    // Checar Telefone
    const phoneQuery = query(usersRef, where("phone", "==", userData.phone));
    const phoneSnapshot = await getDocs(phoneQuery);
    if (!phoneSnapshot.empty) {
        throw new Error("Este número de telefone já está cadastrado.");
    }

    // Checar Documento (CPF/NIF/BI)
    const docQuery = query(usersRef, where("documentId", "==", userData.documentId));
    const docSnapshot = await getDocs(docQuery);
    if (!docSnapshot.empty) {
        throw new Error("Este documento de identidade (CPF/NIF/BI) já está registrado.");
    }

    let uid = '';

    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, userData.password);
      uid = userCredential.user.uid;
    } catch (error: any) {
      if (error.code === 'auth/email-already-in-use') {
         // Fallback caso a verificação anterior falhe por latência (raro)
         throw new Error("Este email já está cadastrado no sistema de autenticação.");
      } else {
          throw new Error(error.message);
      }
    }

    const newUser: User = {
        id: uid, 
        userType: userData.userType,
        firstName: userData.firstName,
        lastName: userData.lastName,
        email: email,
        phone: userData.phone,
        documentId: userData.documentId,
        birthDate: userData.birthDate,
        profilePicture: userData.profilePicture || DEFAULT_PROFILE_PIC,
        balance: 0,
        credentials: userData.credentials || null,
        bio: userData.bio || null,
        verificationFileUrl: userData.verificationFileUrl || null,
        isAdmin: false,
        isVerified: false,
        followers: [],
        followedUsers: [],
        storeId: userData.userType === UserType.CREATOR ? generateUUID() : undefined,
        isOnline: true,
        lastSeen: Date.now()
    };

    await setDoc(doc(db, "users", uid), cleanData(newUser));

    if (newUser.userType === UserType.CREATOR && newUser.storeId) {
       const newStore: Store = {
         id: newUser.storeId,
         professorId: newUser.id,
         name: `Loja de ${newUser.firstName}`,
         description: 'Bem-vindo à minha loja oficial.',
         productIds: [],
         brandColor: '#2563eb'
       };
       await setDoc(doc(db, "stores", newStore.id), newStore);
    }

    return newUser;
  }
  throw new Error("Erro de configuração do Firebase.");
};

export const findUserById = async (userId: string): Promise<User | undefined> => {
  if (isFirebaseConfigured && db) {
    try {
      const userDoc = await getDoc(doc(db, "users", userId));
      if (userDoc.exists()) {
          const u = userDoc.data() as User;
          return {
              ...u,
              followers: u.followers || [],
              followedUsers: u.followedUsers || []
          };
      }
      return undefined;
    } catch (e) { return undefined; }
  }
  return undefined;
};

