export const saveCurrentUser = (userId: string | null) => {
  if (userId) {
    localStorage.setItem('cyberphone_current_user_id', userId);
  } else {
    const currentId = localStorage.getItem('cyberphone_current_user_id');
    if (currentId) {
      updateUserStatus(currentId, false).finally(() => {
        localStorage.removeItem('cyberphone_current_user_id');
        signOut(auth).catch(() => {});
      });
    } else {
      localStorage.removeItem('cyberphone_current_user_id');
      signOut(auth).catch(() => {});
    }
