// NOVA FUNÇÃO: Processamento Rigoroso de Upgrade para Creator
export const processUserUpgrade = async (userId: string, user: User, docFile: File, credentials: string) => {
    // 1. Upload do Documento (Obrigatório)
    let docUrl = '';
