// Processamento de Wallet (Depósito/Saque Externo)
export const handleWalletTransaction = async (userId: string, amount: number, type: 'deposit' | 'withdraw') => {
    // Se for saque, o valor é negativo
    const finalAmount = type === 'deposit' ? amount : -amount;
    const txType = type === 'deposit' ? TransactionType.DEPOSIT : TransactionType.WITHDRAWAL;
    const desc = type === 'deposit' ? 'Depósito via Gateway' : 'Solicitação de Saque';

    return await performFinancialOperation(userId, finalAmount, txType, desc);
};

