import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser, uploadFile } from '../services/storageService';
import { COUNTRIES } from '../data/countries';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import Logo from './Logo';
import { 
  UserIcon, 
  EnvelopeIcon, 
  LockClosedIcon, 
  IdentificationIcon, 
  PhoneIcon, 
  BriefcaseIcon,
  CheckBadgeIcon,
  CameraIcon,
  DocumentArrowUpIcon,
  CalendarDaysIcon,
  CheckCircleIcon,
  ArrowPathIcon,
  ShieldCheckIcon,
  XMarkIcon
} from '@heroicons/react/24/outline';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  // Form States
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [birthDate, setBirthDate] = useState('');

  // Phone Logic
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES.find(c => c.code === 'BR') || COUNTRIES[0]);
  const [phoneNumber, setPhoneNumber] = useState('');

  const [documentId, setDocumentId] = useState('');
  const [bio, setBio] = useState('');

  // Media States
  const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
  const [profilePreview, setProfilePreview] = useState<string | null>(null);
  const profileInputRef = useRef<HTMLInputElement>(null);

  // Creator/Professional specific
  const [isCreator, setIsCreator] = useState(false);
  const [credentials, setCredentials] = useState('');
  const [docFile, setDocFile] = useState<File | null>(null);
  const docInputRef = useRef<HTMLInputElement>(null);

  // Identity Verification Modal States
  const [showVerificationModal, setShowVerificationModal] = useState(false);
  const [idFrontFile, setIdFrontFile] = useState<File | null>(null);
  const [idBackFile, setIdBackFile] = useState<File | null>(null);
  const [selfieFile, setSelfieFile] = useState<File | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);

  // Refs for verification inputs
  const idFrontRef = useRef<HTMLInputElement>(null);
  const idBackRef = useRef<HTMLInputElement>(null);
  const selfieRef = useRef<HTMLInputElement>(null);

  const handleProfileImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProfileImageFile(file);
      const reader = new FileReader();
      reader.onloadend = () => setProfilePreview(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleDocChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Por favor, envie apenas arquivos PDF.');
        return;
      }
      setDocFile(file);
    }
  };

  const formatDocumentId = (value: string) => {
    // Remove tudo que não é número
    const v = value.replace(/\D/g, '');

    // CPF (Brasil) - Máscara 000.000.000-00
    if (v.length <= 11) {
        return v
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d{1,2})/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1');
    } 
    // CNPJ ou Formatos Maiores (NIF/BI genéricos)
    else {
        return v
            .replace(/^(\d{2})(\d)/, '$1.$2')
            .replace(/^(\d{2})\.(\d{3})(\d)/, '$1.$2.$3')
            .replace(/\.(\d{3})(\d)/, '.$1/$2')
            .replace(/(\d{4})(\d)/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1');
    }
  };

  const handleDocumentInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      setDocumentId(formatDocumentId(e.target.value));
  };

  const handleInitialRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validação Básica
    if (!firstName || !lastName || !email || !password || !phoneNumber || !documentId || !bio || !birthDate) {
        setError("Preencha todos os campos obrigatórios.");
        return;
    }

    // Validação Idade (18+)
    const birthTimestamp = new Date(birthDate).getTime();
    const age = (Date.now() - birthTimestamp) / (365.25 * 24 * 60 * 60 * 1000);

    if (age < 18) {
        setError("É estritamente proibido o cadastro de menores de 18 anos nesta plataforma.");
        return;
    }

    if (isCreator) {
        if (!credentials) { setError("Profissionais precisam informar a área de atuação."); return; }
        if (!docFile) { setError("É obrigatório enviar o documento comprovante (PDF) para contas profissionais."); return; }
    }

    // Se passou na validação, abre o modal de verificação
    setShowVerificationModal(true);
  };

  const handleFinalRegistration = async () => {
    if (!idFrontFile || !idBackFile || !selfieFile) {
        alert("Envie todos os documentos de verificação para continuar.");
        return;
    }

    setIsVerifying(true);
    setLoading(true);

    try {
        // Simulação de delay de envio dos documentos de verificação
        await new Promise(resolve => setTimeout(resolve, 2000));

        let finalProfilePic = DEFAULT_PROFILE_PIC;
        if (profileImageFile) {
            finalProfilePic = await uploadFile(profileImageFile, 'profiles');
        }

        let verificationDocUrl = undefined;
        if (isCreator && docFile) {
            verificationDocUrl = await uploadFile(docFile, 'documents');
        }

        const fullPhone = `${selectedCountry.ddi} ${phoneNumber}`;
        const birthTimestamp = new Date(birthDate).getTime();

        const newUser = await registerUser({
          userType: isCreator ? UserType.CREATOR : UserType.STANDARD,
          firstName,
          lastName,
          email,
          phone: fullPhone,
          documentId,
          birthDate: birthTimestamp,
          password,
          profilePicture: finalProfilePic,
          bio,
          credentials: isCreator ? credentials : undefined,
          verificationFileUrl: verificationDocUrl,
        });

        saveCurrentUser(newUser.id);
        onLoginSuccess(newUser);
    } catch (err: any) {
        setError(err.message || 'Falha no cadastro.');
        setShowVerificationModal(false); // Fecha modal para mostrar erro
    } finally {
        setLoading(false);
        setIsVerifying(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
        const user = await loginUser(email, password);
        saveCurrentUser(user.id);
        onLoginSuccess(user);
    } catch (err: any) {
        const msg = err.message || 'Falha na autenticação.';
        setError(msg);
    } finally {
        setLoading(false);
    }
  };

  const inputClass = "w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-blue-600 dark:text-white font-bold text-sm transition-all shadow-inner placeholder-gray-400";
  const iconClass = "absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400";

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-[#0a0c10] p-4 font-sans transition-colors duration-300 relative">

      {/* Modal de Verificação de Identidade */}
      {showVerificationModal && (
          <div className="fixed inset-0 z-[200] bg-black/90 backdrop-blur-xl flex items-center justify-center p-4 animate-fade-in">
              <div className="bg-white dark:bg-[#12161f] w-full max-w-md rounded-[3rem] p-8 shadow-2xl relative border border-white/10 overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 to-green-500"></div>

                  <div className="text-center mb-8">
                      <div className="bg-blue-50 dark:bg-blue-900/20 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white dark:border-[#12161f] shadow-lg">
                          <ShieldCheckIcon className="h-10 w-10 text-blue-600" />
                      </div>
                      <h3 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tighter">Verificação de Identidade</h3>
                      <p className="text-gray-500 text-xs font-bold mt-2 uppercase tracking-wide">Para segurança da comunidade, precisamos validar sua identidade.</p>
                  </div>

                  <div className="space-y-4 mb-8">
                      <div onClick={() => idFrontRef.current?.click()} className={`p-4 rounded-2xl border-2 border-dashed flex items-center justify-center gap-3 cursor-pointer transition-all ${idFrontFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10 text-green-600' : 'border-gray-300 dark:border-white/10 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 text-gray-400'}`}>
                          <DocumentArrowUpIcon className="h-6 w-6" />
                          <span className="font-black text-[10px] uppercase">{idFrontFile ? 'Frente Recebida' : 'Frente do Documento'}</span>
                          <input type="file" ref={idFrontRef} className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && setIdFrontFile(e.target.files[0])} />
                      </div>

                      <div onClick={() => idBackRef.current?.click()} className={`p-4 rounded-2xl border-2 border-dashed flex items-center justify-center gap-3 cursor-pointer transition-all ${idBackFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10 text-green-600' : 'border-gray-300 dark:border-white/10 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 text-gray-400'}`}>
                          <DocumentArrowUpIcon className="h-6 w-6" />
                          <span className="font-black text-[10px] uppercase">{idBackFile ? 'Verso Recebido' : 'Verso do Documento'}</span>
                          <input type="file" ref={idBackRef} className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && setIdBackFile(e.target.files[0])} />
                      </div>

                      <div onClick={() => selfieRef.current?.click()} className={`p-4 rounded-2xl border-2 border-dashed flex items-center justify-center gap-3 cursor-pointer transition-all ${selfieFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10 text-green-600' : 'border-gray-300 dark:border-white/10 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10 text-gray-400'}`}>
                          <CameraIcon className="h-6 w-6" />
                          <span className="font-black text-[10px] uppercase">{selfieFile ? 'Selfie Recebida' : 'Selfie com Documento'}</span>
                          <input type="file" ref={selfieRef} className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && setSelfieFile(e.target.files[0])} />
                      </div>
                  </div>

                  <div className="flex gap-3">
                      <button onClick={() => setShowVerificationModal(false)} className="flex-1 py-4 bg-gray-100 dark:bg-white/5 text-gray-500 rounded-2xl font-black text-xs uppercase hover:bg-gray-200 dark:hover:bg-white/10 transition-all">Cancelar</button>
                      <button 
                        onClick={handleFinalRegistration} 
                        disabled={isVerifying || !idFrontFile || !idBackFile || !selfieFile}
                        className="flex-[2] py-4 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-xs uppercase shadow-xl disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                      >
                          {isVerifying ? <><div className="w-4 h-4 border-2 border-white border-t-transparent animate-spin rounded-full"></div> Validando...</> : 'Enviar e Finalizar'}
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="bg-white dark:bg-[#12161f] p-8 md:p-12 rounded-[3rem] shadow-2xl w-full max-w-lg border border-gray-100 dark:border-white/5 animate-fade-in relative overflow-hidden">

        <div className="absolute -top-20 -right-20 w-64 h-64 bg-blue-600/10 rounded-full blur-3xl pointer-events-none"></div>

        <div className="mb-8 flex flex-col items-center relative z-10">
          <Logo size="xl" />
          <p className="text-gray-400 text-[10px] font-black uppercase tracking-[0.3em] mt-4">
            {isRegister ? 'Crie sua Identidade' : 'Acesse sua Conta'}
          </p>
        </div>

        {successMessage && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/10 text-green-600 dark:text-green-400 rounded-2xl text-xs font-black uppercase text-center border border-green-100 dark:border-green-900/20 animate-fade-in flex items-center justify-center gap-2">
            <CheckCircleIcon className="h-5 w-5" />
            {successMessage}
          </div>
        )}

        {error && (
          <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 text-red-600 dark:text-red-400 rounded-2xl text-xs font-black uppercase text-center border border-red-100 dark:border-red-900/20 animate-pulse">
            {error}
            {error.includes("Criar nova conta") && (
                <button 
                  type="button"
                  onClick={() => { setIsRegister(true); setError(''); }}
                  className="block w-full mt-2 bg-red-100 dark:bg-red-900/30 py-2 rounded-lg text-red-700 dark:text-red-300 font-bold hover:bg-red-200 transition-colors flex items-center justify-center gap-2"
                >
                   <ArrowPathIcon className="h-4 w-4" /> Ir para Cadastro (Correção)
                </button>
            )}
          </div>
        )}

        <form onSubmit={isRegister ? handleInitialRegisterSubmit : handleAuth} className="space-y-4 relative z-10">

          {isRegister && (
            <div className="flex justify-center mb-6">
                <div 
                  onClick={() => profileInputRef.current?.click()}
                  className="w-28 h-28 rounded-full bg-gray-100 dark:bg-white/5 border-4 border-white dark:border-[#12161f] shadow-xl flex items-center justify-center cursor-pointer relative group overflow-hidden"
                >
                    {profilePreview ? (
                        <img src={profilePreview} className="w-full h-full object-cover" alt="Preview" />
                    ) : (
                        <UserIcon className="h-10 w-10 text-gray-300 group-hover:text-blue-500 transition-colors" />
                    )}
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <CameraIcon className="h-8 w-8 text-white" />
                    </div>
                    <input type="file" ref={profileInputRef} onChange={handleProfileImageChange} accept="image/*" className="hidden" />
                </div>
            </div>
          )}

          {isRegister && (
            <div className="space-y-4 animate-fade-in">
              <div className="grid grid-cols-2 gap-3">
                <div className="relative">
                   <UserIcon className={iconClass} />
                   <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className={inputClass} required />
                </div>
                <div className="relative">
                   <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-blue-600 dark:text-white font-bold text-sm transition-all shadow-inner" required />
                </div>
              </div>

              <div className="flex gap-2">
                <div className="relative w-24 shrink-0">
                    <select 
                        className="w-full h-full p-0 pl-3 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-blue-600 dark:text-white font-bold text-lg appearance-none cursor-pointer text-center"
                        value={selectedCountry.code}
                        onChange={e => setSelectedCountry(COUNTRIES.find(c => c.code === e.target.value) || COUNTRIES[0])}
                    >
                        {COUNTRIES.map(c => (
                            <option key={c.code} value={c.code}>{c.flag} {c.ddi}</option>
                        ))}
                    </select>
                </div>
                <div className="relative flex-1">
                    <input type="tel" placeholder="Telefone" value={phoneNumber} onChange={e => setPhoneNumber(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none border-2 border-transparent focus:border-blue-600 dark:text-white font-bold text-sm transition-all shadow-inner" required />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                 <div className="relative">
                    <IdentificationIcon className={iconClass} />
                    <input 
                      type="text" 
                      placeholder="CPF / NIF / BI" 
