          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/10 text-green-600 dark:text-green-400 rounded-2xl text-xs font-black uppercase text-center border border-green-100 dark:border-green-900/20 animate-fade-in flex items-center justify-center gap-2">
            <CheckCircleIcon className="h-5 w-5" />
            {successMessage}
