        )}

        {error && (
          <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 text-red-600 dark:text-red-400 rounded-2xl text-xs font-black uppercase text-center border border-red-100 dark:border-red-900/20 animate-pulse flex flex-col items-center">
