                        onChange={e => setCredentials(e.target.value)} 
                        className={inputClass} 
                        required={isCreator}
                    />

                    <div className="relative group">
                        <div 
                            onClick={() => docInputRef.current?.click()}
                            className={`w-full p-4 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center cursor-pointer transition-all ${docFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10' : 'border-gray-300 dark:border-white/10 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/10'}`}
                        >
                            <DocumentArrowUpIcon className={`h-8 w-8 mb-2 ${docFile ? 'text-green-600' : 'text-gray-400'}`} />
                            <p className={`text-xs font-black uppercase ${docFile ? 'text-green-600' : 'text-gray-500'}`}>
                                {docFile ? docFile.name : 'Upload Habilitação (PDF)'}
                            </p>
                            <p className="text-[9px] text-gray-400 font-bold mt-1">Comprovante Profissional</p>
                        </div>
                        <input 
