                            onChange={handleDocChange} 
                            accept="application/pdf" 
                            className="hidden" 
                        />
                    </div>
                 </div>
               )}
            </div>
          )}

          <button 
            type="submit" 
            disabled={loading}
            className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black uppercase text-xs shadow-xl shadow-blue-500/20 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed mt-6 tracking-widest flex items-center justify-center gap-3"
          >
            {loading ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
            ) : (
               isRegister ? 'Continuar para Verificação' : 'Entrar na Rede'
            )}
          </button>
        </form>

        <button 
          onClick={() => { setIsRegister(!isRegister); setError(''); setSuccessMessage(''); }} 
          className="w-full mt-8 text-center text-gray-400 hover:text-blue-600 font-black uppercase text-[10px] tracking-widest transition-colors relative z-10"
        >
          {isRegister ? 'Já tenho uma conta' : 'Criar nova conta'}
        </button>
      </div>
    </div>
  );
};

