import React, { useState, useEffect, useMemo } from 'react';
import { User, UserType, Post, AdCampaign, Product } from '../types';
import { 
  findUserById, 
  updateUser,
  getPosts,
  getAds,
  getProducts
} from '../services/storageService';
import { CREATOR_UPGRADE_FOLLOWERS_GOAL } from '../data/constants';
import { 
  CheckBadgeIcon, 
  TrophyIcon,
  WalletIcon,
  ArrowDownCircleIcon,
  ArrowUpCircleIcon,
  UserIcon,
  Squares2X2Icon,
  ShoppingBagIcon,
  MegaphoneIcon,
  SparklesIcon,
  RocketLaunchIcon,
  ClockIcon,
  ShieldCheckIcon,
  UserGroupIcon,
  PlusIcon,
  ArrowPathIcon,
  BuildingStorefrontIcon,
  CalendarDaysIcon,
  BriefcaseIcon,
  EnvelopeIcon,
  LinkIcon,
  MapPinIcon
} from '@heroicons/react/24/solid';
import PostCard from './PostCard';
import AdCard from './AdCard';

interface ProfilePageProps {
  currentUser: User;
  onNavigate: (page: string, params?: any) => void;
  refreshUser: () => void;
  userId?: string;
  onOpenWallet: (mode: 'deposit' | 'withdraw') => void;
}

const ProfilePage: React.FC<ProfilePageProps> = ({ currentUser, onNavigate, refreshUser, userId, onOpenWallet }) => {
  const profileId = userId || currentUser.id;

  const [profile, setProfile] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<'posts' | 'about' | 'store' | 'ads'>('posts');
  const [userPosts, setUserPosts] = useState<Post[]>([]);
  const [userAds, setUserAds] = useState<AdCampaign[]>([]);
  const [userProducts, setUserProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);

      // 1. Carregar Perfil Alvo
      let targetUser = await findUserById(profileId);

      // Se não achar (ex: delay de criação), tenta usar o currentUser se o ID bater
      if (!targetUser && profileId === currentUser.id) {
        targetUser = currentUser;
      }

      setProfile(targetUser || null);

      if (targetUser) {
          // 2. Carregar Posts
          const allPosts = await getPosts();
          setUserPosts(allPosts.filter(p => p.userId === profileId).sort((a, b) => b.timestamp - a.timestamp));

          // 3. Carregar Anúncios
          const allAds = await getAds();
          setUserAds(allAds.filter(a => a.professorId === profileId));

          // 4. Carregar Produtos (Se tiver loja)
          if (targetUser.storeId) {
              const allProducts = await getProducts();
              setUserProducts(allProducts.filter(p => p.storeId === targetUser.storeId));
          }
      }

      setLoading(false);
    };
    fetchData();
  }, [profileId, currentUser]); // Recarrega se o ID mudar ou o currentUser atualizar

  if (!profile) {
    return (
