import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { 
  UserIcon, 
