  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  CommandLineIcon,
  CloudIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'database'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // Configuração Firebase
  const [fbApiKey, setFbApiKey] = useState('');
  const [fbProjectId, setFbProjectId] = useState('');
  const [fbAuthDomain, setFbAuthDomain] = useState('');
  const [fbStorageBucket, setFbStorageBucket] = useState('');
  const [fbAppId, setFbAppId] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  useEffect(() => {
    // Carregar configs salvas ao abrir
    const savedConfig = localStorage.getItem('cyber_firebase_config');
    if (savedConfig) {
      const parsed = JSON.parse(savedConfig);
      setFbApiKey(parsed.apiKey || '');
      setFbProjectId(parsed.projectId || '');
      setFbAuthDomain(parsed.authDomain || '');
      setFbStorageBucket(parsed.storageBucket || '');
      setFbAppId(parsed.appId || '');
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
