const handleDocChange = (e: React.ChangeEvent<HTMLInputElement>) => {
  const file = e.target.files?.[0];
  if (file) {
    if (file.type !== 'application/pdf') {
      alert('Por favor, envie apenas arquivos PDF.');
      return;
    }
    setDocFile(file);
  }
};

const formatDocumentId = (value: string) => {
  // Lógica específica por país
  if (selectedCountry.code === 'AO') {
      // BI Angolano: Permite números e letras, remove outros caracteres, caixa alta
      // Formato Exato: 007904433HA040 (14 caracteres)
      return value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 14);
  } 

  if (selectedCountry.code === 'PT') {
      // NIF: Apenas 9 números
      return value.replace(/\D/g, '').slice(0, 9);
  }

  // Padrão (Brasil CPF / Outros) - Mantém lógica numérica
  const v = value.replace(/\D/g, '');

  // CPF (Brasil) - Máscara 000.000.000-00
  if (selectedCountry.code === 'BR' || v.length <= 11) {
      return v
          .replace(/(\d{3})(\d)/, '$1.$2')
          .replace(/(\d{3})(\d)/, '$1.$2')
          .replace(/(\d{3})(\d{1,2})/, '$1-$2')
          .replace(/(-\d{2})\d+?$/, '$1');
  } 

  return v.slice(0, 20); // Limite genérico para outros
};

const validateDocumentFormat = (doc: string, countryCode: string): boolean => {
    if (countryCode === 'AO') {
        // Validação rigorosa BI Angolano: 9 dígitos + 2 letras + 3 dígitos
        return /^\d{9}[A-Z]{2}\d{3}$/.test(doc);
    }
    if (countryCode === 'BR') {
        // Validação rigorosa CPF formatado
        return /^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(doc);
    }
    if (countryCode === 'PT') {
        // Validação rigorosa NIF (9 dígitos)
        return /^\d{9}$/.test(doc);
    }
    return doc.length > 5; // Fallback para outros países
};

const handleDocumentInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    setDocumentId(formatDocumentId(e.target.value));
};

const handleInitialRegisterSubmit = async (e: React.FormEvent) => {
  e.preventDefault();
  setError('');

  // Validação Básica
  if (!firstName || !lastName || !email || !password || !phoneNumber || !documentId || !bio || !birthDate) {
      setError("Preencha todos os campos obrigatórios.");
      return;
  }

  // Validação Rigorosa de Documento
  if (!validateDocumentFormat(documentId, selectedCountry.code)) {
      let msg = "Formato de documento inválido.";
      if (selectedCountry.code === 'AO') msg = "BI Angolano inválido. O formato deve ser rigorosamente: 9 dígitos, 2 letras, 3 dígitos (Ex: 007904433HA040).";
      if (selectedCountry.code === 'BR') msg = "CPF inválido. O formato deve ser: 000.000.000-00.";
      if (selectedCountry.code === 'PT') msg = "NIF inválido. Deve conter exatamente 9 dígitos.";
      setError(msg);
      return;
  }

  // Validação Idade (18+) Simples (A IA fará a checagem rigorosa depois)
  const birthTimestamp = new Date(birthDate).getTime();
  const age = (Date.now() - birthTimestamp) / (365.25 * 24 * 60 * 60 * 1000);

  if (age < 18) {
      setError("É estritamente proibido o cadastro de menores de 18 anos nesta plataforma.");
      return;
  }

  if (isCreator) {
      if (!credentials) { setError("Profissionais precisam informar a área de atuação."); return; }
      if (!docFile) { setError("É obrigatório enviar o documento comprovante (PDF) para contas profissionais."); return; }
  }

  // Se passou na validação básica, abre o modal de verificação rigorosa
  setShowVerificationModal(true);
};

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser, uploadFile } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { COUNTRIES } from '../data/countries';
import { EyeIcon, EyeSlashIcon, CloudArrowUpIcon, DocumentCheckIcon, CheckBadgeIcon, ArrowPathIcon } from '@heroicons/react/24/solid';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);

  // Form Data
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');

  // Advanced
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES.find(c => c.code === 'BR') || COUNTRIES[0]);
  const [docFile, setDocFile] = useState<File | null>(null);

  // UI State
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showVerificationModal, setShowVerificationModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDocChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Por favor, envie apenas arquivos PDF.');
        return;
      }
      setDocFile(file);
    }
  };

  const formatDocumentId = (value: string) => {
    if (selectedCountry.code === 'AO') {
        return value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 14);
    } 
    if (selectedCountry.code === 'PT') {
        return value.replace(/\D/g, '').slice(0, 9);
    }
    const v = value.replace(/\D/g, '');
    if (selectedCountry.code === 'BR' || v.length <= 11) {
        return v
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d{1,2})/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1');
    } 
    return v.slice(0, 20);
  };

  const validateDocumentFormat = (doc: string, countryCode: string): boolean => {
      if (countryCode === 'AO') {
          return /^\d{9}[A-Z]{2}\d{3}$/.test(doc);
      }
      if (countryCode === 'BR') {
          return /^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(doc);
      }
      if (countryCode === 'PT') {
          return /^\d{9}$/.test(doc);
      }
      return doc.length > 5;
  };

  const handleDocumentInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      setDocumentId(formatDocumentId(e.target.value));
  };

  const handleInitialRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !password || !phone || !documentId || !birthDate) {
        setError("Preencha todos os campos obrigatórios.");
        return;
    }

    if (!validateDocumentFormat(documentId, selectedCountry.code)) {
        let msg = "Formato de documento inválido.";
        if (selectedCountry.code === 'AO') msg = "BI Angolano inválido. (Ex: 007904433HA040).";
        if (selectedCountry.code === 'BR') msg = "CPF inválido. (Ex: 000.000.000-00).";
        if (selectedCountry.code === 'PT') msg = "NIF inválido. (9 dígitos).";
        setError(msg);
        return;
    }

    const birthTimestamp = new Date(birthDate).getTime();
    const age = (Date.now() - birthTimestamp) / (365.25 * 24 * 60 * 60 * 1000);

    if (age < 18) {
        setError("É estritamente proibido o cadastro de menores de 18 anos nesta plataforma.");
        return;
    }

    if (userType === UserType.CREATOR) {
        if (!credentials) { setError("Profissionais precisam informar a área de atuação."); return; }
        if (!bio) { setError("Biografia é obrigatória para criadores."); return; }
        if (!docFile) { setError("É obrigatório enviar o documento comprovante (PDF) para contas profissionais."); return; }
    }

    setShowVerificationModal(true);
  };

  const handleFinalRegister = async () => {
      setLoading(true);
      setError('');
      try {
          let docUrl = undefined;
          if (docFile) {
              docUrl = await uploadFile(docFile, 'verification_docs');
          }

          const newUser = await registerUser({
            userType,
            firstName,
            lastName,
            email,
            phone,
            documentId,
            birthDate: new Date(birthDate).getTime(),
            password,
            profilePicture: DEFAULT_PROFILE_PIC,
            credentials: userType === UserType.CREATOR ? credentials : undefined,
            bio: userType === UserType.CREATOR ? bio : undefined,
            verificationFileUrl: docUrl
          });

          saveCurrentUser(newUser.id);
          onLoginSuccess(newUser);
      } catch (err: any) {
          setError(err.message || 'Erro no registro.');
          setShowVerificationModal(false);
      } finally {
          setLoading(false);
      }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError(err.message || 'Erro no login.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-900 via-gray-900 to-black p-4 font-sans animate-fade-in">

      {showVerificationModal && (
        <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl flex items-center justify-center p-4">
           <div className="bg-white dark:bg-[#1a1c23] w-full max-w-md rounded-[2.5rem] p-8 text-center shadow-2xl border border-white/10 animate-scale-in">
              <div className="w-20 h-20 bg-green-100 dark:bg-green-900/20 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                 <DocumentCheckIcon className="h-10 w-10 text-green-600" />
              </div>
              <h3 className="text-2xl font-black dark:text-white uppercase tracking-tighter mb-2">Validação Final</h3>
              <p className="text-sm text-gray-500 font-medium mb-8">
                 Seus dados serão auditados por nossa IA de conformidade. Ao confirmar, você aceita nossos termos de uso e política de privacidade rigorosa.
              </p>
              <div className="space-y-3">
                 <button 
                   onClick={handleFinalRegister} 
                   disabled={loading}
                   className="w-full py-4 bg-green-600 hover:bg-green-700 text-white rounded-2xl font-black text-sm uppercase shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2"
                 >
                    {loading ? (
                        <>
                           <ArrowPathIcon className="h-5 w-5 animate-spin" /> Processando...
                        </>
                    ) : (
                        <>Confirmar Cadastro</>
                    )}
                 </button>
                 <button onClick={() => setShowVerificationModal(false)} className="text-xs text-gray-400 font-bold uppercase hover:text-white transition-colors">Voltar e Revisar</button>
              </div>
           </div>
        </div>
      )}

      <div className="bg-white dark:bg-[#0f1115] w-full max-w-lg rounded-[3rem] shadow-2xl overflow-hidden relative border border-white/10">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>

        <div className="p-8 md:p-12">
           <div className="text-center mb-10">
              <h1 className="text-4xl font-black dark:text-white tracking-tighter mb-2">CyBerPhone <span className="text-blue-500">ID</span></h1>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.3em]">Acesso Seguro Global</p>
           </div>

           {error && (
             <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-500/20 rounded-2xl text-center animate-shake">
                <p className="text-xs font-black text-red-600 dark:text-red-400 uppercase">{error}</p>
             </div>
           )}

           <form onSubmit={isRegister ? handleInitialRegisterSubmit : handleLogin} className="space-y-5">

              {isRegister && (
                <div className="grid grid-cols-2 gap-3 mb-6">
                   <button 
                     type="button" 
                     onClick={() => setUserType(UserType.STANDARD)} 
                     className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.STANDARD ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/10 text-blue-600' : 'border-transparent bg-gray-50 dark:bg-white/5 text-gray-400'}`}
                   >
                      <CheckBadgeIcon className="h-5 w-5" />
                      <span className="text-[9px] font-black uppercase">Membro</span>
                   </button>
                   <button 
                     type="button" 
                     onClick={() => setUserType(UserType.CREATOR)} 
                     className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.CREATOR ? 'border-purple-600 bg-purple-50 dark:bg-purple-900/10 text-purple-600' : 'border-transparent bg-gray-50 dark:bg-white/5 text-gray-400'}`}
                   >
                      <CloudArrowUpIcon className="h-5 w-5" />
                      <span className="text-[9px] font-black uppercase">Creator</span>
                   </button>
                </div>
              )}

              {isRegister && (
                <>
                   <div className="flex gap-3">
                      <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                      <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   </div>

                   <div className="flex gap-3">
                      <select 
                        value={selectedCountry.code} 
                        onChange={e => setSelectedCountry(COUNTRIES.find(c => c.code === e.target.value) || COUNTRIES[0])}
                        className="w-1/3 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all cursor-pointer"
                      >
                         {COUNTRIES.map(c => <option key={c.code} value={c.code}>{c.flag} {c.code}</option>)}
                      </select>
                      <input type="text" placeholder="Documento ID" value={documentId} onChange={handleDocumentInput} className="flex-1 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   </div>

                   <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />

                   {userType === UserType.CREATOR && (
                      <div className="space-y-3 animate-fade-in">
                         <input type="text" placeholder="Especialidade / Profissão" value={credentials} onChange={e => setCredentials(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-purple-600 transition-all" />
                         <textarea placeholder="Biografia Profissional" value={bio} onChange={e => setBio(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-purple-600 transition-all resize-none h-24" />

                         <div onClick={() => fileInputRef.current?.click()} className={`w-full p-4 border-2 border-dashed rounded-2xl flex items-center justify-center gap-2 cursor-pointer transition-all ${docFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10 text-green-600' : 'border-gray-200 dark:border-white/10 text-gray-400 hover:border-purple-500'}`}>
                            <CloudArrowUpIcon className="h-5 w-5" />
                            <span className="text-xs font-black uppercase">{docFile ? docFile.name : 'Upload PDF Comprovante'}</span>
                            <input type="file" ref={fileInputRef} onChange={handleDocChange} accept="application/pdf" className="hidden" />
                         </div>
                      </div>
                   )}
                </>
              )}

              <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />

              <div className="relative">
                 <input type={showPassword ? "text" : "password"} placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                 <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-600">
                    {showPassword ? <EyeSlashIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}
                 </button>
              </div>

              <button 
                type="submit" 
                disabled={loading}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-sm uppercase shadow-xl shadow-blue-500/30 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                 {loading ? <ArrowPathIcon className="h-5 w-5 animate-spin" /> : (isRegister ? 'Avançar' : 'Entrar')}
              </button>
           </form>

           <div className="mt-8 text-center">
              <button onClick={() => setIsRegister(!isRegister)} className="text-xs font-bold text-gray-500 dark:text-gray-400 hover:text-blue-600 dark:hover:text-white transition-colors">
                 {isRegister ? 'Já possui conta? Faça login.' : 'Não tem conta? Cadastre-se grátis.'}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

export enum UserType {
  STANDARD = 'STANDARD',
