export const getSupportTickets = (userId?: string): SupportTicket[] => {
    const json = localStorage.getItem(SUPPORT_TICKETS_KEY);
    const allTickets: SupportTicket[] = json ? JSON.parse(json) : [];
    if (userId) {
        return allTickets.filter(t => t.userId === userId).sort((a,b) => b.updatedAt - a.updatedAt);
    }
    return allTickets.sort((a,b) => b.updatedAt - a.updatedAt);
};

export const createSupportTicket = (ticket: Omit<SupportTicket, 'id' | 'createdAt' | 'updatedAt' | 'messages' | 'status'>, initialMessage: string, attachmentUrl?: string, attachmentType?: 'image' | 'video') => {
    const tickets = getSupportTickets();
    const newTicket: SupportTicket = {
        ...ticket,
        id: generateUUID(),
        status: 'OPEN',
        createdAt: Date.now(),
        updatedAt: Date.now(),
        messages: [{
            id: generateUUID(),
            senderId: ticket.userId,
            text: initialMessage,
            attachmentUrl,
            attachmentType,
            timestamp: Date.now()
        }]
    };
    localStorage.setItem(SUPPORT_TICKETS_KEY, JSON.stringify([newTicket, ...tickets]));
    return newTicket;
};

export const addSupportMessage = (ticketId: string, message: Omit<SupportMessage, 'id' | 'timestamp'>) => {
    const tickets = getSupportTickets();
    const ticket = tickets.find(t => t.id === ticketId);
    if (ticket) {
        ticket.messages.push({
            ...message,
            id: generateUUID(),
            timestamp: Date.now()
        });
        ticket.updatedAt = Date.now();
        // If user sends message, reopen ticket if closed (optional logic, keeping simple)
        localStorage.setItem(SUPPORT_TICKETS_KEY, JSON.stringify(tickets));

        // Simular resposta do suporte se for mensagem do usuário
        if (message.senderId !== 'SUPPORT') {
            setTimeout(() => {
                const updatedTickets = getSupportTickets();
                const t = updatedTickets.find(x => x.id === ticketId);
                if (t) {
                    t.messages.push({
                        id: generateUUID(),
                        senderId: 'SUPPORT',
                        text: "Recebemos sua mensagem. Um agente analisará seu caso em breve.",
                        timestamp: Date.now()
                    });
                    t.updatedAt = Date.now();
                    localStorage.setItem(SUPPORT_TICKETS_KEY, JSON.stringify(updatedTickets));
                }
            }, 5000);
        }
    }
};

