import React, { useState, useEffect, useCallback, useRef } from 'react';
import { User, CartItem, GlobalSettings, GroupTheme } from './types';
import {
    getCurrentUserId,
    findUserById,
    saveCurrentUser,
    getNotificationsForUser,
    markNotificationsAsRead,
    getCart,
    getGlobalSettings,
    getAppTheme,
    saveAppTheme,
    updateUserStatus
} from './services/storageService';
import { showNotification, requestNotificationPermission, getNotificationContent } from './services/notificationService';
import Header from './components/Header';
import Footer from './components/Footer';
import AuthPage from './components/AuthPage';
import FeedPage from './components/FeedPage';
import ProfilePage from './components/ProfilePage';
import ChatPage from './components/ChatPage';
import AdCampaignPage from './components/AdCampaignPage';
import LiveStreamViewer from './components/LiveStreamViewer';
import { StorePage } from './components/StorePage';
import StoreManagerPage from './components/StoreManagerPage';
import ReelsPage from './components/ReelsPage';
import SearchResultsPage from './components/SearchResultsPage';
import NotificationsPage from './components/NotificationsPage';
import CartModal from './components/CartModal';
import WalletModal from './components/WalletModal';
import SettingsPage from './components/SettingsPage';
import AdminDashboard from './components/AdminDashboard';
import EventsPage from './components/EventsPage';
import PurchasesPage from './components/PurchasesPage';
import AffiliatesPage from './components/AffiliatesPage';
import CreateGroupPage from './components/CreateGroupPage';
import SupportPage from './components/SupportPage'; // NEW IMPORT
import { ExclamationTriangleIcon, ArrowPathIcon } from '@heroicons/react/24/solid';

type Page = 'auth' | 'feed' | 'profile' | 'chat' | 'ads' | 'live' | 'store' | 'manage-store' | 'reels-page' | 'search-results' | 'notifications' | 'settings' | 'admin' | 'events' | 'purchases' | 'affiliates' | 'create-group' | 'support';

const THEME_MAP: Record<GroupTheme, { primary: string, hover: string, light: string }> = {
  blue: { primary: '#2563eb', hover: '#1d4ed8', light: '#eff6ff' },
  green: { primary: '#10b981', hover: '#059669', light: '#ecfdf5' },
  black: { primary: '#18181b', hover: '#09090b', light: '#27272a' },
  orange: { primary: '#f97316', hover: '#ea580c', light: '#fff7ed' },
  purple: { primary: '#9333ea', hover: '#7e22ce', light: '#f3e8ff' },
  red: { primary: '#dc2626', hover: '#b91c1c', light: '#fef2f2' },
  teal: { primary: '#0d9488', hover: '#0f766e', light: '#f0fdfa' },
  pink: { primary: '#db2777', hover: '#be185d', light: '#fce7f3' },
  indigo: { primary: '#4f46e5', hover: '#4338ca', light: '#eef2ff' },
  cyan: { primary: '#0891b2', hover: '#0e7490', light: '#ecfeff' }
};

const App: React.FC = () => {
    const [darkMode, setDarkMode] = useState(() => localStorage.getItem('cyberphone_theme') === 'dark');
    const [appTheme, setAppTheme] = useState<GroupTheme>(() => getAppTheme());
    const [isMenuOpen, setIsMenuOpen] = useState(false);
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [currentPage, setCurrentPage] = useState<Page>('auth');
    const [pageParams, setPageParams] = useState<Record<string, string>>({});
    const [unreadNotificationsCount, setUnreadNotificationsCount] = useState(0);
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [isCartModalOpen, setIsCartModalOpen] = useState(false);
    const [walletConfig, setWalletConfig] = useState<{ isOpen: boolean, mode: 'deposit' | 'withdraw' }>({ isOpen: false, mode: 'deposit' });
    const [isLoading, setIsLoading] = useState(true);
    const [initError, setInitError] = useState<string | null>(null);

    const lastNotificationIdRef = useRef<string | null>(null);

    useEffect(() => {
        const params = new URLSearchParams(window.location.search);
        const affiliateId = params.get('affiliateId');
        if (affiliateId) {
            localStorage.setItem('cyber_referrer_id', affiliateId);
            const newUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
            window.history.replaceState({ path: newUrl }, '', newUrl);
        }

        const page = params.get('page') as Page;
        if (page) {
            const newParams: Record<string, string> = {};
            params.forEach((value, key) => {
                if (key !== 'page' && key !== 'affiliateId') newParams[key] = value;
            });
            setCurrentPage(page);
            setPageParams(newParams);
        }
    }, []);

    useEffect(() => {
      const handleTabClose = () => {
        if (currentUser) {
          updateUserStatus(currentUser.id, false);
        }
      };

      window.addEventListener('beforeunload', handleTabClose);
      return () => {
        window.removeEventListener('beforeunload', handleTabClose);
      };
    }, [currentUser]);

    const toggleTheme = useCallback(() => {
        setDarkMode(prev => {
            const newVal = !prev;
            localStorage.setItem('cyberphone_theme', newVal ? 'dark' : 'light');
            return newVal;
        });
    }, []);

    const changeAppTheme = useCallback((newTheme: GroupTheme) => {
        setAppTheme(newTheme);
        saveAppTheme(newTheme);
    }, []);

    useEffect(() => {
        if (darkMode) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    }, [darkMode]);

    useEffect(() => {
        const theme = THEME_MAP[appTheme];
        document.documentElement.style.setProperty('--brand-color', theme.primary);
        document.documentElement.style.setProperty('--brand-hover', theme.hover);
        document.documentElement.style.setProperty('--brand-light', theme.light);
    }, [appTheme]);

    useEffect(() => {
        if (!currentUser) return;

        const pollInterval = setInterval(async () => {
            try {
                const notifications = await getNotificationsForUser(currentUser.id);
                const sorted = notifications.sort((a, b) => b.timestamp - a.timestamp);

                if (sorted.length > 0) {
                    const latest = sorted[0];
                    setUnreadNotificationsCount(sorted.filter(n => !n.isRead).length);

                    if (lastNotificationIdRef.current && latest.id !== lastNotificationIdRef.current && !latest.isRead) {
                        const actor = await findUserById(latest.actorId);
                        if (actor) {
                            const content = getNotificationContent(latest.type, actor.firstName, latest.groupName);
                            showNotification(content.title, { 
                                body: content.body,
                                icon: actor.profilePicture,
                                url: window.location.origin
                            });
                        }
                    }
                    lastNotificationIdRef.current = latest.id;
                }
            } catch (err) {
            }
        }, 5000);

        return () => clearInterval(pollInterval);
    }, [currentUser]);

    const refreshCurrentUser = useCallback(async () => {
        try {
            const userId = getCurrentUserId();
            setCartItems(getCart());

            if (userId) {
                const user = await findUserById(userId);
                if (user) {
                    setCurrentUser(user);
                    updateUserStatus(user.id, true);

                    const notifications = await getNotificationsForUser(user.id);
                    const sorted = notifications.sort((a, b) => b.timestamp - a.timestamp);
                    if (sorted.length > 0) lastNotificationIdRef.current = sorted[0].id;

                    setUnreadNotificationsCount(notifications.filter(n => !n.isRead).length);
                    if (currentPage === 'auth') setCurrentPage('feed');

                    requestNotificationPermission();
                } else {
                    setCurrentPage('auth');
                }
            } else {
                setCurrentPage('auth');
            }
        } catch (error) {
            console.error("Erro na inicialização:", error);
            setInitError("Falha na sincronização local. Tente recarregar.");
        } finally {
            setIsLoading(false);
        }
    }, [currentPage]);

    useEffect(() => {
        refreshCurrentUser();
    }, []);

    const handleLoginSuccess = useCallback((user: User) => {
        setCurrentUser(user);
        saveCurrentUser(user.id);
        setCurrentPage('feed');
        requestNotificationPermission();
    }, []);

    const handleLogout = useCallback(() => {
        saveCurrentUser(null);
        setCurrentUser(null);
        setCurrentPage('auth');
        lastNotificationIdRef.current = null;
    }, []);

    const handleNavigate = useCallback((page: Page, params: Record<string, string> = {}) => {
        if (page === 'notifications' && currentUser) {
            markNotificationsAsRead(currentUser.id);
            refreshCurrentUser();
        }
        setCurrentPage(page);
        setPageParams(params);
        setIsMenuOpen(false);
        window.scrollTo(0, 0);
    }, [currentUser, refreshCurrentUser]);

    if (isLoading) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-gray-50 dark:bg-[#0a0c10]">
                <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-brand mb-6 shadow-[0_0_15px_rgba(37,99,235,0.3)]"></div>
                <div className="flex flex-col items-center gap-2">
                   <h1 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">CyBerPhone <span className="text-brand">Pro</span></h1>
                   <p className="text-[9px] font-bold uppercase text-gray-400 tracking-[0.3em] animate-pulse">Carregando Ecossistema v1.3.1</p>
                </div>
            </div>
        );
    }

    if (initError) {
        return (
            <div className="h-screen w-full flex flex-col items-center justify-center bg-white dark:bg-darkbg p-6 text-center">
                <ExclamationTriangleIcon className="h-16 w-16 text-red-500 mb-6" />
                <h2 className="text-2xl font-black uppercase mb-2 text-gray-900 dark:text-white">Erro de Inicialização</h2>
                <p className="text-gray-500 text-sm mb-8 font-medium">{initError}</p>
                <button onClick={() => window.location.reload()} className="bg-brand text-white px-10 py-4 rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">Recarregar App</button>
            </div>
        );
    }

    const renderPage = () => {
        if (!currentUser) return <AuthPage onLoginSuccess={handleLoginSuccess} />;
        switch (currentPage) {
            case 'feed': return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'profile': return <ProfilePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} userId={pageParams.userId} onOpenWallet={(mode) => setWalletConfig({ isOpen: true, mode })} />;
            case 'chat': return <ChatPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'create-group': return <CreateGroupPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'reels-page': return <ReelsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} startPostId={pageParams.startPostId} />;
            case 'search-results': return <SearchResultsPage currentUser={currentUser} query={pageParams.query} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'notifications': return <NotificationsPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'live': return <LiveStreamViewer currentUser={currentUser} postId={pageParams.postId} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
            case 'settings': return <SettingsPage currentUser={currentUser} onNavigate={handleNavigate} darkMode={darkMode} toggleTheme={toggleTheme} refreshUser={refreshCurrentUser} onLogout={handleLogout} onDeleteAccount={handleLogout} appTheme={appTheme} onThemeChange={changeAppTheme} />;
            case 'store': return <StorePage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} storeId={pageParams.storeId} onAddToCart={() => setCartItems(getCart())} onOpenCart={() => setIsCartModalOpen(true)} />;
            case 'manage-store': return <StoreManagerPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'admin': return <AdminDashboard currentUser={currentUser} onNavigate={handleNavigate} onRefreshUser={refreshCurrentUser} />;
            case 'events': return <EventsPage currentUser={currentUser} />;
            case 'purchases': return <PurchasesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'affiliates': return <AffiliatesPage currentUser={currentUser} onNavigate={handleNavigate} />;
            case 'ads': return <AdCampaignPage currentUser={currentUser} refreshUser={refreshCurrentUser} onNavigate={handleNavigate} />;
            case 'support': return <SupportPage currentUser={currentUser} onNavigate={handleNavigate} />;
            default: return <FeedPage currentUser={currentUser} onNavigate={handleNavigate} refreshUser={refreshCurrentUser} />;
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-[#0a0c10] text-gray-900 dark:text-gray-100 transition-colors duration-300">
            <Header 
              currentUser={currentUser} 
              onNavigate={handleNavigate} 
              unreadNotificationsCount={unreadNotificationsCount} 
              cartItemCount={cartItems.length} 
              onOpenCart={() => setIsCartModalOpen(true)} 
              onToggleMenu={() => setIsMenuOpen(!isMenuOpen)}
            />
            <div className="flex flex-1 relative">
                {currentUser && (
                  <Footer 
                    currentUser={currentUser} 
                    onNavigate={handleNavigate} 
                    activePage={currentPage} 
                    onLogout={handleLogout} 
                    isMenuOpen={isMenuOpen}
                    onCloseMenu={() => setIsMenuOpen(false)}
                  />
                )}
                <main className={`flex-grow pt-[64px] md:pt-[72px] pb-[80px] md:pb-8 transition-all ${currentUser ? 'md:ml-64 px-0 md:px-8' : ''} overflow-x-hidden`}>
                    <div className="max-w-7xl mx-auto min-h-[calc(100vh-140px)] animate-fade-in">
                        {renderPage()}
                    </div>
                </main>
            </div>
            {currentUser && (
              <>
                <CartModal isOpen={isCartModalOpen} onClose={() => setIsCartModalOpen(false)} currentUser={currentUser} onCartUpdate={() => setCartItems(getCart())} refreshUser={refreshCurrentUser} />
                <WalletModal isOpen={walletConfig.isOpen} mode={walletConfig.mode} onClose={() => setWalletConfig({ ...walletConfig, isOpen: false })} currentUser={currentUser} refreshUser={refreshCurrentUser} />
              </>
            )}
        </div>
    );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  CommandLineIcon,
  CloudIcon,
  ExclamationTriangleIcon,
  LifebuoyIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'database'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // Configuração Firebase
  const [fbApiKey, setFbApiKey] = useState('');
  const [fbProjectId, setFbProjectId] = useState('');
  const [fbAuthDomain, setFbAuthDomain] = useState('');
  const [fbStorageBucket, setFbStorageBucket] = useState('');
  const [fbAppId, setFbAppId] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  useEffect(() => {
    // Carregar configs salvas ao abrir
    const savedConfig = localStorage.getItem('cyber_firebase_config');
    if (savedConfig) {
      const parsed = JSON.parse(savedConfig);
      setFbApiKey(parsed.apiKey || '');
      setFbProjectId(parsed.projectId || '');
      setFbAuthDomain(parsed.authDomain || '');
      setFbStorageBucket(parsed.storageBucket || '');
      setFbAppId(parsed.appId || '');
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveFirebase = (e: React.FormEvent) => {
    e.preventDefault();
    const config = {
      apiKey: fbApiKey.trim(),
      projectId: fbProjectId.trim(),
      authDomain: fbAuthDomain.trim(),
      storageBucket: fbStorageBucket.trim(),
      appId: fbAppId.trim()
    };

    localStorage.setItem('cyber_firebase_config', JSON.stringify(config));
    alert('Configuração salva! O aplicativo será recarregado para aplicar as mudanças.');
    window.location.reload();
  };

  const handleClearFirebase = () => {
    if(confirm("Deseja remover as configurações do Firebase e voltar ao modo Offline?")) {
      localStorage.removeItem('cyber_firebase_config');
      window.location.reload();
    }
  };

  const handleDeletePress = async () => {
    if (window.confirm('ALERTA DE SEGURANÇA: Esta ação excluirá permanentemente sua conta, dados, posts e carteira. Esta ação é irreversível. Deseja continuar?')) {
        try {
            setIsSaving(true); // Bloqueia UI
            await deleteUser(currentUser.id);
            // Limpa sessão local explicitamente
            saveCurrentUser(null);
            onDeleteAccount(); // Chama o logout/reset do pai
        } catch (error) {
            console.error("Erro ao deletar conta:", error);
            alert("Não foi possível excluir a conta no momento. Tente novamente.");
            setIsSaving(false);
        }
    }
  };

  const handleVersionClick = async () => {
    const newCount = devClicks + 1;
    setDevClicks(newCount);

    if (newCount === 7) {
        if (currentUser.email.toLowerCase() === ADMIN_EMAIL) {
            const newStatus = !currentUser.isAdmin;
            await updateUser({ ...currentUser, isAdmin: newStatus });
            refreshUser();
            alert(`SISTEMA ROOT: Privilégios de Superusuário ${newStatus ? 'ATIVADOS' : 'DESATIVADOS'}.`);
        } else {
            alert(`⛔ ACESSO NEGADO\n\nConta não autorizada para Root.`);
        }
        setDevClicks(0);
    }
  };

  if (view === 'database') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
        <div className="flex items-center gap-6 mb-8">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-3xl font-black dark:text-white tracking-tighter">Conexão Firebase</h2>
        </div>

        <div className="bg-orange-50 dark:bg-orange-900/10 border border-orange-200 dark:border-orange-500/20 p-6 rounded-3xl mb-8">
           <p className="text-orange-800 dark:text-orange-400 text-xs font-bold leading-relaxed">
             Insira as chaves do seu projeto Firebase aqui para ativar Login Real, Chat em Tempo Real e Banco de Dados na Nuvem. Deixe em branco para usar o modo Demonstração (Offline).
           </p>
        </div>

        <form onSubmit={handleSaveFirebase} className="space-y-6 bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">API Key (obrigatório)</label>
              <input type="text" value={fbApiKey} onChange={e => setFbApiKey(e.target.value)} placeholder="AIzaSy..." className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Project ID (obrigatório)</label>
              <input type="text" value={fbProjectId} onChange={e => setFbProjectId(e.target.value)} placeholder="meu-projeto-id" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Auth Domain</label>
              <input type="text" value={fbAuthDomain} onChange={e => setFbAuthDomain(e.target.value)} placeholder="meu-projeto.firebaseapp.com" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Storage Bucket</label>
              <input type="text" value={fbStorageBucket} onChange={e => setFbStorageBucket(e.target.value)} placeholder="meu-projeto.appspot.com" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">App ID</label>
              <input type="text" value={fbAppId} onChange={e => setFbAppId(e.target.value)} placeholder="1:123456789:web:..." className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="pt-4 flex flex-col gap-3">
              <button type="submit" className="w-full py-5 bg-green-600 hover:bg-green-700 text-white rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">
                 Salvar e Conectar
              </button>
              <button type="button" onClick={handleClearFirebase} className="w-full py-5 bg-gray-100 dark:bg-white/5 text-gray-500 hover:text-red-500 rounded-2xl font-black uppercase text-xs transition-all">
                 Resetar para Modo Offline
              </button>
           </div>
        </form>
      </div>
    );
  }

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-4xl font-black dark:text-white tracking-tighter">Dados de Inscrição</h2>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-500/30 rounded-2xl flex items-center gap-3 animate-fade-in">
             <CheckIcon className="h-5 w-5 text-green-600" />
             <p className="text-xs font-black text-green-700 dark:text-green-400 uppercase tracking-widest">Perfil atualizado!</p>
          </div>
        )}

        <form onSubmit={handleSaveProfile} className="space-y-8">
           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Identidade Visual</p>
              <div className="flex flex-col items-center gap-6">
                 <div 
                   onClick={() => fileInputRef.current?.click()} 
                   className="relative group cursor-pointer"
                 >
                    <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-white dark:border-darkcard shadow-2xl transition-transform group-hover:scale-105 relative">
                       <img src={profilePicture || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" alt="Profile" />
                       {isUploading && (
                         <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                           <div className="w-8 h-8 border-4 border-white border-t-transparent animate-spin rounded-full"></div>
                         </div>
                       )}
                       <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                          <CameraIcon className="h-10 w-10 text-white" />
                       </div>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-brand text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                       <PaintBrushIcon className="h-4 w-4" />
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
                      onChange={handleFileChange} 
                    />
                 </div>
                 <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Clique na foto para alterar</p>
              </div>
           </div>

           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Dados Pessoais</p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Nome</label>
                    <input type="text" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Sobrenome</label>
                    <input type="text" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-black" />
                 </div>
              </div>

              <div className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Data de Nascimento</label>
                    <div className="relative">
                       <CalendarDaysIcon className="h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                       <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 pl-12 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                    </div>
                 </div>

                 {currentUser.userType === UserType.CREATOR && (
                   <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Cargo ou Especialidade</label>
                      <input type="text" value={credentials} onChange={e => setCredentials(e.target.value)} placeholder="Ex: Professor" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-bold" />
                   </div>
                 )}

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Biografia</label>
                    <textarea value={bio} onChange={e => setBio(e.target.value)} placeholder="Conte um pouco sobre você..." className="w-full p-5 bg-gray-50 dark:bg-white/5 rounded-[2rem] dark:text-white outline-none border-2 border-transparent focus:border-brand font-medium h-32 resize-none" />
                 </div>
              </div>
           </div>

           <div className={`bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border transition-all ${currentUser.isAdmin ? 'border-green-500/20 shadow-green-500/10' : 'border-gray-200 dark:border-white/10 opacity-90'}`}>
              <div className="flex items-center justify-between mb-6">
                 <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                    {currentUser.isAdmin ? (
                        <><LockOpenIcon className="h-3 w-3 text-green-500" /> Acesso Administrativo (Desbloqueado)</>
                    ) : (
                        <><LockClosedIcon className="h-3 w-3" /> Dados Sensíveis (Protegidos)</>
                    )}
                 </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Endereço de E-mail</label>
                    <div className="relative">
                       <EnvelopeIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={email} 
                        onChange={e => setEmail(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>

                 <div className="space-y-2">
                    <label className="text-[9px] font-black text-gray-400 uppercase ml-2">Telefone</label>
                    <div className="relative">
                       <PhoneIcon className={`h-5 w-5 absolute left-4 top-1/2 -translate-y-1/2 ${currentUser.isAdmin ? 'text-brand' : 'text-gray-300'}`} />
                       <input 
                        type="text" 
                        disabled={!currentUser.isAdmin} 
                        value={phone} 
                        onChange={e => setPhone(e.target.value)}
                        className={`w-full p-4 pl-12 rounded-2xl font-bold border ${currentUser.isAdmin ? 'bg-white dark:bg-white/5 dark:text-white border-transparent focus:border-brand' : 'bg-gray-50 dark:bg-white/5 text-gray-400 dark:text-gray-500 cursor-not-allowed border-gray-100 dark:border-white/5'}`} 
                       />
                    </div>
                 </div>
              </div>
           </div>

           <button 
             type="submit" 
             disabled={isSaving || isUploading} 
             className="w-full py-6 bg-brand hover:bg-brandHover text-white rounded-[2.2rem] font-black uppercase text-sm tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
           >
             {isSaving ? (
               <div className="w-5 h-5 border-3 border-white border-t-transparent animate-spin rounded-full"></div>
             ) : (
               <><CheckIcon className="h-6 w-6 stroke-[3]" /> Salvar Alterações</>
             )}
           </button>
        </form>
      </div>
    );
  }

  const sections = [
    {
      title: 'Identidade Digital',
      items: [
        { label: 'Editar Perfil & Senha', desc: 'Nome, bio, foto e segurança', icon: UserIcon, onClick: () => setView('edit-profile') },
        { label: 'Visual e Estilo', desc: 'Cores e Modo Dark', icon: PaintBrushIcon, onClick: () => setView('appearance') }
      ]
    },
    {
      title: 'Sistema & Segurança',
      items: [
        { label: 'CyBer Card Pro', desc: 'Conta virtual (Beta)', icon: CreditCardIcon, onClick: () => setView('payments') },
        { label: 'Banco de Dados', desc: 'Configurar Firebase', icon: CloudIcon, onClick: () => setView('database') },
        { label: 'Ajuda e Suporte', desc: 'Abrir tickets e resolver problemas', icon: LifebuoyIcon, onClick: () => onNavigate('support') }, // NEW LINK
        { label: 'Sair da Conta', desc: 'Desconectar dispositivo', icon: ArrowRightOnRectangleIcon, onClick: onLogout }
      ]
    }
  ];

  return (
    <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-4xl animate-fade-in">
      <div className="flex items-center gap-6 mb-10">
        <button onClick={() => onNavigate('profile')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
        <h2 className="text-4xl font-black text-gray-900 dark:text-white tracking-tighter">Ajustes</h2>
      </div>

      <div className="space-y-10">
        {sections.map(section => (
          <div key={section.title}>
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.2em] mb-4 ml-4">{section.title}</h3>
            <div className="bg-white dark:bg-darkcard rounded-[2.5rem] shadow-xl border border-gray-100 dark:border-white/10 overflow-hidden">
              {section.items.map((item, idx) => (
                <div 
                  key={item.label} 
                  onClick={item.onClick}
                  className={`p-6 flex items-center justify-between hover:bg-gray-50 dark:hover:bg-white/5 transition-colors cursor-pointer ${idx !== section.items.length - 1 ? 'border-b border-gray-50 dark:border-white/10' : ''}`}
                >
                  <div className="flex items-center gap-5">
                    <div className="p-3 rounded-2xl bg-brand/10 text-brand">
                      <item.icon className="h-6 w-6" />
                    </div>
                    <div>
                      <p className="font-black text-sm dark:text-white">{item.label}</p>
                      <p className="text-xs text-gray-400 font-bold">{item.desc}</p>
                    </div>
                  </div>
                  <ChevronDownIcon className="h-5 w-5 text-gray-300 -rotate-90" />
                </div>
              ))}
            </div>
          </div>
        ))}

        {/* ÁREA DE PERIGO PERSISTENTE */}
        <div className="mt-10 px-4 bg-red-50 dark:bg-red-900/10 p-8 rounded-[3rem] border border-red-100 dark:border-red-900/20">
           <div className="flex items-center gap-3 mb-4">
              <ExclamationTriangleIcon className="h-6 w-6 text-red-600" />
              <h3 className="text-sm font-black text-red-700 dark:text-red-400 uppercase tracking-widest">Área de Perigo</h3>
           </div>
           <p className="text-xs text-red-600/80 dark:text-red-400/80 font-medium mb-6 leading-relaxed">
              A exclusão da conta é permanente. Todos os seus dados, postagens, loja e saldo serão removidos dos nossos servidores.
           </p>

           <div className="flex flex-col gap-6">
               <button 
                 onClick={handleDeletePress} 
                 disabled={isSaving}
                 className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-black text-xs uppercase shadow-lg shadow-red-200 dark:shadow-none active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                  {isSaving ? (
                      <>Processando Exclusão...</>
                  ) : (
                      <><TrashIcon className="h-4 w-4" /> Excluir Minha Conta</>
                  )}
               </button>

               <div 
                 onClick={handleVersionClick}
                 className="text-center opacity-30 hover:opacity-100 transition-opacity cursor-pointer select-none"
               >
                  <p className="text-[9px] font-black uppercase tracking-[0.3em] text-gray-400">
                     CyBerPhone Pro v1.3.2
                     {currentUser.isAdmin && <span className="text-red-500 ml-2">ROOT ACCESS</span>}
                  </p>
               </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsPage;

import React, { useState, useRef } from 'react';
import { User, UserType } from '../types';
import { loginUser, registerUser, saveCurrentUser, uploadFile } from '../services/storageService';
import { DEFAULT_PROFILE_PIC } from '../data/constants';
import { COUNTRIES } from '../data/countries';
import { EyeIcon, EyeSlashIcon, CloudArrowUpIcon, DocumentCheckIcon, CheckBadgeIcon, ArrowPathIcon, CameraIcon, UserCircleIcon } from '@heroicons/react/24/solid';

interface AuthPageProps {
  onLoginSuccess: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ onLoginSuccess }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [userType, setUserType] = useState<UserType>(UserType.STANDARD);

  // Form Data
  const [firstName, setFirstName] = useState('');
  const [lastName, setLastName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [documentId, setDocumentId] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [credentials, setCredentials] = useState('');
  const [bio, setBio] = useState('');

  // Profile Image State
  const [profileImageFile, setProfileImageFile] = useState<File | null>(null);
  const [profileImagePreview, setProfileImagePreview] = useState<string | null>(null);

  // Advanced
  const [selectedCountry, setSelectedCountry] = useState(COUNTRIES.find(c => c.code === 'BR') || COUNTRIES[0]);
  const [docFile, setDocFile] = useState<File | null>(null);

  // UI State
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showVerificationModal, setShowVerificationModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const profileImageInputRef = useRef<HTMLInputElement>(null);

  const handleDocChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.type !== 'application/pdf') {
        alert('Por favor, envie apenas arquivos PDF.');
        return;
      }
      setDocFile(file);
    }
  };

  const handleProfileImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setProfileImageFile(file);
      setProfileImagePreview(URL.createObjectURL(file));
    }
  };

  const formatDocumentId = (value: string) => {
    if (selectedCountry.code === 'AO') {
        return value.toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 14);
    } 
    if (selectedCountry.code === 'PT') {
        return value.replace(/\D/g, '').slice(0, 9);
    }
    const v = value.replace(/\D/g, '');
    if (selectedCountry.code === 'BR' || v.length <= 11) {
        return v
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d)/, '$1.$2')
            .replace(/(\d{3})(\d{1,2})/, '$1-$2')
            .replace(/(-\d{2})\d+?$/, '$1');
    } 
    return v.slice(0, 20);
  };

  const validateDocumentFormat = (doc: string, countryCode: string): boolean => {
      if (countryCode === 'AO') {
          return /^\d{9}[A-Z]{2}\d{3}$/.test(doc);
      }
      if (countryCode === 'BR') {
          return /^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(doc);
      }
      if (countryCode === 'PT') {
          return /^\d{9}$/.test(doc);
      }
      return doc.length > 5;
  };

  const handleDocumentInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      setDocumentId(formatDocumentId(e.target.value));
  };

  const handleInitialRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!firstName || !lastName || !email || !password || !phone || !documentId || !birthDate) {
        setError("Preencha todos os campos obrigatórios.");
        return;
    }

    if (!validateDocumentFormat(documentId, selectedCountry.code)) {
        let msg = "Formato de documento inválido.";
        if (selectedCountry.code === 'AO') msg = "BI Angolano inválido. (Ex: 007904433HA040).";
        if (selectedCountry.code === 'BR') msg = "CPF inválido. (Ex: 000.000.000-00).";
        if (selectedCountry.code === 'PT') msg = "NIF inválido. (9 dígitos).";
        setError(msg);
        return;
    }

    const birthTimestamp = new Date(birthDate).getTime();
    const age = (Date.now() - birthTimestamp) / (365.25 * 24 * 60 * 60 * 1000);

    if (age < 18) {
        setError("É estritamente proibido o cadastro de menores de 18 anos nesta plataforma.");
        return;
    }

    if (userType === UserType.CREATOR) {
        if (!credentials) { setError("Profissionais precisam informar a área de atuação."); return; }
        if (!bio) { setError("Biografia é obrigatória para criadores."); return; }
        if (!docFile) { setError("É obrigatório enviar o documento comprovante (PDF) para contas profissionais."); return; }
    }

    setShowVerificationModal(true);
  };

  const handleFinalRegister = async () => {
      setLoading(true);
      setError('');
      try {
          let docUrl = undefined;
          if (docFile) {
              docUrl = await uploadFile(docFile, 'verification_docs');
          }

          let profilePicUrl = DEFAULT_PROFILE_PIC;
          if (profileImageFile) {
              profilePicUrl = await uploadFile(profileImageFile, 'profiles');
          }

          const newUser = await registerUser({
            userType,
            firstName,
            lastName,
            email,
            phone,
            documentId,
            birthDate: new Date(birthDate).getTime(),
            password,
            profilePicture: profilePicUrl,
            credentials: userType === UserType.CREATOR ? credentials : undefined,
            bio: userType === UserType.CREATOR ? bio : undefined,
            verificationFileUrl: docUrl
          });

          saveCurrentUser(newUser.id);
          onLoginSuccess(newUser);
      } catch (err: any) {
          setError(err.message || 'Erro no registro.');
          setShowVerificationModal(false);
      } finally {
          setLoading(false);
      }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const user = await loginUser(email, password);
      saveCurrentUser(user.id);
      onLoginSuccess(user);
    } catch (err: any) {
      setError(err.message || 'Erro no login.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-900 via-gray-900 to-black p-4 font-sans animate-fade-in">

      {showVerificationModal && (
        <div className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl flex items-center justify-center p-4">
           <div className="bg-white dark:bg-[#1a1c23] w-full max-w-md rounded-[2.5rem] p-8 text-center shadow-2xl border border-white/10 animate-scale-in">
              <div className="w-20 h-20 bg-green-100 dark:bg-green-900/20 rounded-full flex items-center justify-center mx-auto mb-6 animate-bounce">
                 <DocumentCheckIcon className="h-10 w-10 text-green-600" />
              </div>
              <h3 className="text-2xl font-black dark:text-white uppercase tracking-tighter mb-2">Validação Final</h3>
              <p className="text-sm text-gray-500 font-medium mb-8">
                 Seus dados serão auditados por nossa IA de conformidade. Ao confirmar, você aceita nossos termos de uso e política de privacidade rigorosa.
              </p>
              <div className="space-y-3">
                 <button 
                   onClick={handleFinalRegister} 
                   disabled={loading}
                   className="w-full py-4 bg-green-600 hover:bg-green-700 text-white rounded-2xl font-black text-sm uppercase shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2"
                 >
                    {loading ? (
                        <>
                           <ArrowPathIcon className="h-5 w-5 animate-spin" /> Processando...
                        </>
                    ) : (
                        <>Confirmar Cadastro</>
                    )}
                 </button>
                 <button onClick={() => setShowVerificationModal(false)} className="text-xs text-gray-400 font-bold uppercase hover:text-white transition-colors">Voltar e Revisar</button>
              </div>
           </div>
        </div>
      )}

      <div className="bg-white dark:bg-[#0f1115] w-full max-w-lg rounded-[3rem] shadow-2xl overflow-hidden relative border border-white/10">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500"></div>

        <div className="p-8 md:p-12">
           <div className="text-center mb-10">
              <h1 className="text-4xl font-black dark:text-white tracking-tighter mb-2">CyBerPhone <span className="text-blue-500">ID</span></h1>
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.3em]">Acesso Seguro Global</p>
           </div>

           {error && (
             <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-500/20 rounded-2xl text-center animate-shake">
                <p className="text-xs font-black text-red-600 dark:text-red-400 uppercase">{error}</p>
             </div>
           )}

           <form onSubmit={isRegister ? handleInitialRegisterSubmit : handleLogin} className="space-y-5">

              {isRegister && (
                <>
                    <div className="grid grid-cols-2 gap-3 mb-6">
                        <button 
                            type="button" 
                            onClick={() => setUserType(UserType.STANDARD)} 
                            className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.STANDARD ? 'border-blue-600 bg-blue-50 dark:bg-blue-900/10 text-blue-600' : 'border-transparent bg-gray-50 dark:bg-white/5 text-gray-400'}`}
                        >
                            <CheckBadgeIcon className="h-5 w-5" />
                            <span className="text-[9px] font-black uppercase">Membro</span>
                        </button>
                        <button 
                            type="button" 
                            onClick={() => setUserType(UserType.CREATOR)} 
                            className={`p-3 rounded-2xl border-2 transition-all flex flex-col items-center gap-1 ${userType === UserType.CREATOR ? 'border-purple-600 bg-purple-50 dark:bg-purple-900/10 text-purple-600' : 'border-transparent bg-gray-50 dark:bg-white/5 text-gray-400'}`}
                        >
                            <CloudArrowUpIcon className="h-5 w-5" />
                            <span className="text-[9px] font-black uppercase">Creator</span>
                        </button>
                    </div>

                    {/* PROFILE IMAGE UPLOAD */}
                    <div className="flex justify-center mb-6">
                        <div 
                            onClick={() => profileImageInputRef.current?.click()}
                            className="relative w-24 h-24 rounded-full border-4 border-gray-100 dark:border-white/10 cursor-pointer overflow-hidden group shadow-lg bg-gray-50 dark:bg-white/5"
                        >
                            {profileImagePreview ? (
                                <img src={profileImagePreview} className="w-full h-full object-cover" alt="Profile Preview" />
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-gray-300 dark:text-white/20">
                                    <UserCircleIcon className="h-16 w-16" />
                                </div>
                            )}
                            <div className="absolute inset-0 bg-black/40 hidden group-hover:flex items-center justify-center transition-all">
                                <CameraIcon className="h-8 w-8 text-white" />
                            </div>
                            <input 
                                type="file" 
                                ref={profileImageInputRef} 
                                onChange={handleProfileImageChange} 
                                accept="image/*" 
                                className="hidden" 
                            />
                        </div>
                    </div>
                    <p className="text-center text-[10px] text-gray-400 uppercase font-bold tracking-widest -mt-4 mb-6">Foto de Perfil</p>
                </>
              )}

              {isRegister && (
                <>
                   <div className="flex gap-3">
                      <input type="text" placeholder="Nome" value={firstName} onChange={e => setFirstName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                      <input type="text" placeholder="Sobrenome" value={lastName} onChange={e => setLastName(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   </div>

                   <div className="flex gap-3">
                      <select 
                        value={selectedCountry.code} 
                        onChange={e => setSelectedCountry(COUNTRIES.find(c => c.code === e.target.value) || COUNTRIES[0])}
                        className="w-1/3 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all cursor-pointer"
                      >
                         {COUNTRIES.map(c => <option key={c.code} value={c.code}>{c.flag} {c.code}</option>)}
                      </select>
                      <input type="text" placeholder="Documento ID" value={documentId} onChange={handleDocumentInput} className="flex-1 p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   </div>

                   <input type="tel" placeholder="Telefone" value={phone} onChange={e => setPhone(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                   <input type="date" value={birthDate} onChange={e => setBirthDate(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />

                   {userType === UserType.CREATOR && (
                      <div className="space-y-3 animate-fade-in">
                         <input type="text" placeholder="Especialidade / Profissão" value={credentials} onChange={e => setCredentials(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-purple-600 transition-all" />
                         <textarea placeholder="Biografia Profissional" value={bio} onChange={e => setBio(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-purple-600 transition-all resize-none h-24" />

                         <div onClick={() => fileInputRef.current?.click()} className={`w-full p-4 border-2 border-dashed rounded-2xl flex items-center justify-center gap-2 cursor-pointer transition-all ${docFile ? 'border-green-500 bg-green-50 dark:bg-green-900/10 text-green-600' : 'border-gray-200 dark:border-white/10 text-gray-400 hover:border-purple-500'}`}>
                            <CloudArrowUpIcon className="h-5 w-5" />
                            <span className="text-xs font-black uppercase">{docFile ? docFile.name : 'Upload PDF Comprovante'}</span>
                            <input type="file" ref={fileInputRef} onChange={handleDocChange} accept="application/pdf" className="hidden" />
                         </div>
                      </div>
                   )}
                </>
              )}

              <input type="email" placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />

              <div className="relative">
                 <input type={showPassword ? "text" : "password"} placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none font-bold text-sm border-2 border-transparent focus:border-blue-600 transition-all" />
                 <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-blue-600">
                    {showPassword ? <EyeSlashIcon className="h-5 w-5"/> : <EyeIcon className="h-5 w-5"/>}
                 </button>
              </div>

              <button 
                type="submit" 
                disabled={loading}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-sm uppercase shadow-xl shadow-blue-500/30 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                 {loading ? <ArrowPathIcon className="h-5 w-5 animate-spin" /> : (isRegister ? 'Avançar' : 'Entrar')}
              </button>
           </form>

           <div className="mt-8 text-center">
              <button onClick={() => setIsRegister(!isRegister)} className="text-xs font-bold text-gray-500 dark:text-gray-400 hover:text-blue-600 dark:hover:text-white transition-colors">
                 {isRegister ? 'Já possui conta? Faça login.' : 'Não tem conta? Cadastre-se grátis.'}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

export default AuthPage;

export enum UserType {
  STANDARD = 'STANDARD',
  CREATOR = 'CREATOR', 
}

export enum ChatType {
  PRIVATE = 'PRIVATE',
  GROUP = 'GROUP'
}

export type GroupTheme = 
  | 'blue' 
  | 'green' 
  | 'black' 
  | 'orange' 
  | 'purple' 
  | 'red' 
  | 'teal' 
  | 'pink' 
  | 'indigo' 
  | 'cyan';

export interface ChatConversation {
  id: string;
  type: ChatType;
  participants: string[]; // IDs dos usuários
  messages: Message[];
  groupName?: string;
  groupImage?: string;
  adminId?: string;
  isPublic?: boolean; 
  description?: string;
  theme?: GroupTheme; // NOVO: Tema visual do grupo
}

export interface Message {
  id: string;
  senderId: string;
  receiverId?: string; 
  groupId?: string;    
  timestamp: number;
  text?: string;
  imageUrl?: string;
  // Novos campos
  isDeleted?: boolean;
  isEdited?: boolean;
  replyTo?: {
    id: string;
    text: string;
    senderName: string;
  };
}

export enum TransactionType {
  DEPOSIT = 'DEPOSIT',
  WITHDRAWAL = 'WITHDRAWAL',
  PURCHASE = 'PURCHASE',
  SALE = 'SALE',
  UPGRADE = 'UPGRADE',
  SUBSCRIPTION = 'SUBSCRIPTION',
  CHAT_FEE = 'CHAT_FEE',
  BOOST = 'BOOST',
  DROPSHIPPING_COST = 'DROPSHIPPING_COST',
  DONATION = 'DONATION'
}

export interface Transaction {
  id: string;
  userId: string;
  type: TransactionType;
  amount: number;
  description: string;
  timestamp: number;
  status: 'COMPLETED' | 'PENDING' | 'FAILED';
}

export interface SystemLog {
  id: string;
  adminId: string;
  action: string;
  targetId?: string;
  details: string;
  timestamp: number;
}

export interface ContentReport {
  id: string;
  reporterId: string;
  targetId: string; 
  targetType: 'POST' | 'COMMENT' | 'USER';
  reason: string;
  details: string;
  status: 'OPEN' | 'RESOLVED' | 'DISMISSED';
  timestamp: number;
}

export interface User {
  id: string;
  userType: UserType;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  documentId: string;
