import React, { useState, useEffect, useRef } from 'react';
import { User, SupportTicket, SupportMessage } from '../types';
import { getSupportTickets, createSupportTicket, addSupportMessage, uploadFile } from '../services/storageService';
import { 
  ArrowLeftIcon, 
  LifebuoyIcon, 
  PlusIcon, 
  ChatBubbleLeftRightIcon, 
  PaperClipIcon, 
  PaperAirplaneIcon, 
  CheckCircleIcon,
  ClockIcon,
  DocumentIcon,
  VideoCameraIcon,
  PhotoIcon,
  XMarkIcon
} from '@heroicons/react/24/solid';

interface SupportPageProps {
  currentUser: User;
  onNavigate: (page: string) => void;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

const SupportPage: React.FC<SupportPageProps> = ({ currentUser, onNavigate }) => {
  const [tickets, setTickets] = useState<SupportTicket[]>([]);
  const [view, setView] = useState<'dashboard' | 'create' | 'chat'>('dashboard');
  const [currentTicket, setCurrentTicket] = useState<SupportTicket | null>(null);

  // Create Form State
  const [subject, setSubject] = useState('');
  const [category, setCategory] = useState<'TECHNICAL' | 'BILLING' | 'ABUSE' | 'OTHER'>('TECHNICAL');
  const [description, setDescription] = useState('');
  const [initialFile, setInitialFile] = useState<File | null>(null);

  // Chat State
  const [newMessage, setNewMessage] = useState('');
  const [chatFile, setChatFile] = useState<File | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const createFileInputRef = useRef<HTMLInputElement>(null);

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadTickets();
  }, [currentUser.id]);

  useEffect(() => {
    if (view === 'chat' && currentTicket) {
        // Auto scroll to bottom
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [currentTicket?.messages, view]);

  const loadTickets = () => {
    const data = getSupportTickets(currentUser.id);
    setTickets(data);
    if (currentTicket) {
        // Refresh current ticket if open
        const updated = data.find(t => t.id === currentTicket.id);
        if (updated) setCurrentTicket(updated);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>, isChat: boolean) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // RIGOROUS SIZE CHECK
    if (file.size > MAX_FILE_SIZE_BYTES) {
        alert(`Arquivo muito grande! O limite máximo é estritamente ${MAX_FILE_SIZE_MB}MB.`);
        e.target.value = ''; // Reset input
        return;
    }

    if (isChat) setChatFile(file);
    else setInitialFile(file);
  };

  const handleCreateTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!subject.trim() || !description.trim()) return;

    setLoading(true);
    try {
        let attachmentUrl = undefined;
        let attachmentType: 'image' | 'video' | undefined = undefined;

        if (initialFile) {
            attachmentUrl = await uploadFile(initialFile, 'support');
            attachmentType = initialFile.type.startsWith('video/') ? 'video' : 'image';
        }

        const newTicket = createSupportTicket({
            userId: currentUser.id,
            subject,
            category
        }, description, attachmentUrl, attachmentType);

        loadTickets();
        setView('dashboard');
        setSubject(''); setDescription(''); setInitialFile(null);
        alert("Ticket criado com sucesso! Nossa equipe responderá em breve.");
    } catch (err) {
        alert("Erro ao criar ticket.");
    } finally {
        setLoading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if ((!newMessage.trim() && !chatFile) || !currentTicket) return;

    setLoading(true);
    try {
        let attachmentUrl = undefined;
        let attachmentType: 'image' | 'video' | undefined = undefined;

        if (chatFile) {
            attachmentUrl = await uploadFile(chatFile, 'support');
            attachmentType = chatFile.type.startsWith('video/') ? 'video' : 'image';
        }

        addSupportMessage(currentTicket.id, {
            senderId: currentUser.id,
            text: newMessage,
            attachmentUrl,
            attachmentType
        });

        setNewMessage('');
        setChatFile(null);
        loadTickets();
    } catch (err) {
        alert("Erro ao enviar mensagem.");
    } finally {
        setLoading(false);
    }
  };

  const openTicket = (ticket: SupportTicket) => {
      setCurrentTicket(ticket);
      setView('chat');
  };

  const formatDate = (ts: number) => new Date(ts).toLocaleString();

  return (
    <div className="container mx-auto px-4 pt-24 pb-20 max-w-4xl animate-fade-in min-h-screen">

      {/* Header Navigation */}
      <div className="flex items-center gap-4 mb-8">
         <button onClick={() => {
             if (view === 'dashboard') onNavigate('settings');
             else setView('dashboard');
         }} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-sm text-gray-500 hover:text-blue-600 transition-all">
            <ArrowLeftIcon className="h-6 w-6" />
         </button>
         <div>
            <h2 className="text-3xl font-black dark:text-white uppercase tracking-tighter">Central de Suporte</h2>
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Resolva problemas e tire dúvidas</p>
         </div>
      </div>

      {view === 'dashboard' && (
        <div className="space-y-8">
           <div className="bg-blue-600 p-8 rounded-[2.5rem] shadow-xl text-white relative overflow-hidden flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="relative z-10">
                 <h3 className="text-2xl font-black uppercase tracking-tight mb-2">Precisa de Ajuda?</h3>
                 <p className="text-xs font-medium opacity-90 max-w-md">Nossa equipe de especialistas está pronta para resolver qualquer questão técnica, financeira ou de conteúdo.</p>
              </div>
              <button 
                onClick={() => setView('create')}
                className="bg-white text-blue-600 px-8 py-4 rounded-2xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all flex items-center gap-2 relative z-10"
              >
                 <PlusIcon className="h-5 w-5 stroke-[3]" /> Abrir Novo Chamado
              </button>
              <LifebuoyIcon className="absolute -right-6 -bottom-6 h-48 w-48 text-white opacity-10 rotate-12" />
           </div>

           <div>
              <h3 className="text-sm font-black text-gray-500 uppercase tracking-widest mb-4 ml-2">Meus Tickets</h3>
              <div className="space-y-4">
                 {tickets.length === 0 ? (
                    <div className="text-center py-20 bg-gray-50 dark:bg-white/5 rounded-[2.5rem] border-2 border-dashed border-gray-200 dark:border-white/10">
                       <LifebuoyIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
                       <p className="text-gray-400 font-bold text-xs uppercase">Nenhum ticket encontrado</p>
                    </div>
                 ) : (
                    tickets.map(ticket => (
                       <div 
                         key={ticket.id} 
                         onClick={() => openTicket(ticket)}
                         className="bg-white dark:bg-darkcard p-6 rounded-[2rem] shadow-sm border border-gray-100 dark:border-white/5 flex items-center justify-between cursor-pointer hover:shadow-lg transition-all group"
                       >
                          <div className="flex items-center gap-4">
                             <div className={`p-4 rounded-2xl ${ticket.status === 'OPEN' ? 'bg-green-100 text-green-600' : 'bg-gray-100 text-gray-400'}`}>
                                {ticket.status === 'OPEN' ? <ClockIcon className="h-6 w-6" /> : <CheckCircleIcon className="h-6 w-6" />}
                             </div>
                             <div>
                                <h4 className="font-black text-sm dark:text-white uppercase tracking-tight mb-1 group-hover:text-blue-600 transition-colors">{ticket.subject}</h4>
                                <div className="flex items-center gap-3">
                                   <span className="text-[9px] font-bold text-gray-400 bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded uppercase">{ticket.category}</span>
                                   <span className="text-[9px] text-gray-400 font-medium">Atualizado em: {formatDate(ticket.updatedAt)}</span>
                                </div>
                             </div>
                          </div>
                          <div className="hidden md:block">
                             <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${ticket.status === 'OPEN' ? 'bg-blue-50 text-blue-600' : 'bg-gray-100 text-gray-500'}`}>
                                {ticket.status === 'OPEN' ? 'Em Aberto' : 'Resolvido'}
                             </span>
                          </div>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>
      )}

      {view === 'create' && (
         <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border border-gray-100 dark:border-white/5 max-w-2xl mx-auto">
            <h3 className="text-xl font-black dark:text-white uppercase tracking-tighter mb-8">Novo Ticket</h3>
            <form onSubmit={handleCreateTicket} className="space-y-6">
               <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-2">Assunto</label>
                  <input 
                    type="text" 
                    value={subject} 
                    onChange={e => setSubject(e.target.value)} 
                    className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-bold text-sm dark:text-white focus:ring-2 focus:ring-blue-600 transition-all"
                    placeholder="Resumo do problema..."
                    required
                  />
               </div>

               <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-2">Categoria</label>
                  <div className="grid grid-cols-2 gap-3">
                     {['TECHNICAL', 'BILLING', 'ABUSE', 'OTHER'].map(cat => (
                        <button 
                          key={cat}
                          type="button"
                          onClick={() => setCategory(cat as any)}
                          className={`p-3 rounded-xl text-[10px] font-black uppercase border-2 transition-all ${category === cat ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-transparent bg-gray-50 dark:bg-white/5 text-gray-500'}`}
                        >
                           {cat}
                        </button>
                     ))}
                  </div>
               </div>

               <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-2">Descrição Detalhada</label>
                  <textarea 
                    value={description} 
                    onChange={e => setDescription(e.target.value)} 
                    className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl outline-none font-medium text-sm dark:text-white focus:ring-2 focus:ring-blue-600 transition-all h-40 resize-none"
                    placeholder="Descreva o que aconteceu..."
                    required
                  />
               </div>

               <div>
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-2 block mb-2">Anexo (Opcional - Máx 5MB)</label>
                  <div 
                    onClick={() => createFileInputRef.current?.click()}
                    className={`w-full p-6 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-2 cursor-pointer transition-all ${initialFile ? 'border-green-500 bg-green-50' : 'border-gray-200 dark:border-white/10 hover:border-blue-500'}`}
                  >
                     <PaperClipIcon className={`h-6 w-6 ${initialFile ? 'text-green-600' : 'text-gray-400'}`} />
                     <p className="text-[10px] font-black uppercase text-gray-500">{initialFile ? initialFile.name : 'Clique para adicionar Print/Vídeo'}</p>
                     <input type="file" ref={createFileInputRef} className="hidden" onChange={e => handleFileSelect(e, false)} accept="image/*,video/*" />
                  </div>
               </div>

               <button 
                 type="submit" 
                 disabled={loading}
                 className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black text-xs uppercase shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2"
               >
                  {loading ? 'Enviando...' : 'Criar Ticket'}
               </button>
            </form>
         </div>
      )}

      {view === 'chat' && currentTicket && (
         <div className="flex flex-col h-[75vh] bg-white dark:bg-darkcard rounded-[3rem] shadow-2xl border border-gray-100 dark:border-white/5 overflow-hidden">
            {/* Chat Header */}
            <div className="p-6 border-b border-gray-100 dark:border-white/5 bg-gray-50 dark:bg-white/5 flex items-center justify-between">
               <div>
                  <h3 className="font-black text-sm dark:text-white uppercase tracking-tight">{currentTicket.subject}</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">Ticket #{currentTicket.id.slice(0,8)} • {currentTicket.category}</p>
               </div>
               <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${currentTicket.status === 'OPEN' ? 'bg-green-100 text-green-600' : 'bg-gray-200 text-gray-500'}`}>
                  {currentTicket.status === 'OPEN' ? 'Aberto' : 'Fechado'}
               </span>
            </div>

            {/* Messages Area */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-gray-50/50 dark:bg-[#0a0c10]">
               {currentTicket.messages.map(msg => {
                  const isMe = msg.senderId === currentUser.id;
                  return (
                     <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[80%] p-4 rounded-2xl shadow-sm ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white dark:bg-white/10 dark:text-white rounded-tl-none'}`}>
                           {msg.attachmentUrl && (
                              <div className="mb-3 rounded-xl overflow-hidden border border-white/20">
                                 {msg.attachmentType === 'video' ? (
                                    <video src={msg.attachmentUrl} controls className="max-h-48 w-full object-cover" />
                                 ) : (
                                    <img src={msg.attachmentUrl} className="max-h-48 w-full object-cover" alt="attachment" />
                                 )}
                              </div>
                           )}
                           <p className="text-sm font-medium leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                           <p className={`text-[8px] font-bold mt-2 opacity-60 uppercase text-right`}>
                              {isMe ? 'Você' : 'Suporte'} • {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                           </p>
                        </div>
                     </div>
                  );
               })}
               <div ref={chatEndRef} />
            </div>

            {/* Input Area */}
            {currentTicket.status === 'OPEN' && (
                <div className="p-4 bg-white dark:bg-darkcard border-t border-gray-100 dark:border-white/5">
                   {chatFile && (
                      <div className="flex items-center gap-2 mb-3 bg-blue-50 dark:bg-blue-900/10 p-2 rounded-xl w-fit">
                         <DocumentIcon className="h-4 w-4 text-blue-600" />
                         <span className="text-[10px] font-bold text-blue-600 truncate max-w-[200px]">{chatFile.name}</span>
                         <button onClick={() => setChatFile(null)}><XMarkIcon className="h-4 w-4 text-gray-400 hover:text-red-500"/></button>
                      </div>
                   )}
                   <form onSubmit={handleSendMessage} className="flex items-center gap-3">
                      <button 
                        type="button" 
                        onClick={() => fileInputRef.current?.click()}
                        className="p-3 bg-gray-100 dark:bg-white/5 rounded-full text-gray-500 hover:text-blue-600 transition-colors"
                      >
                         <PaperClipIcon className="h-5 w-5" />
                      </button>
                      <input type="file" ref={fileInputRef} className="hidden" onChange={e => handleFileSelect(e, true)} accept="image/*,video/*" />

                      <input 
                        type="text" 
                        value={newMessage}
                        onChange={e => setNewMessage(e.target.value)}
                        placeholder="Digite sua mensagem..."
                        className="flex-1 bg-gray-100 dark:bg-white/5 rounded-2xl px-4 py-3 outline-none text-sm font-medium dark:text-white"
                      />

                      <button 
                        type="submit" 
                        disabled={loading || (!newMessage.trim() && !chatFile)}
                        className="p-3 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 disabled:opacity-50 transition-all active:scale-90"
                      >
                         <PaperAirplaneIcon className="h-5 w-5" />
                      </button>
                   </form>
                   <p className="text-[8px] text-gray-400 font-bold uppercase mt-2 text-center">Máximo de 5MB por arquivo de mídia.</p>
                </div>
            )}
         </div>
      )}

    </div>
  );
};

export default SupportPage;

import React, { useState, useRef, useEffect } from 'react';
import { User, UserType, GroupTheme } from '../types';
import { updateUser, uploadFile, deleteUser, updateUserPassword, saveCurrentUser } from '../services/storageService';
import { 
  UserIcon, 
  PaintBrushIcon, 
  ArrowLeftIcon, 
  CreditCardIcon, 
  CheckIcon,
  ArrowRightOnRectangleIcon,
  TrashIcon,
  CameraIcon,
  CalendarDaysIcon,
  EnvelopeIcon,
  PhoneIcon,
  LockClosedIcon,
  LockOpenIcon,
  ChevronDownIcon,
  CommandLineIcon,
  CloudIcon,
  ExclamationTriangleIcon,
  LifebuoyIcon
} from '@heroicons/react/24/outline';

interface SettingsPageProps {
  currentUser: User;
  onNavigate: (page: any) => void;
  darkMode: boolean;
  toggleTheme: () => void;
  refreshUser: () => void;
  onLogout: () => void;
  onDeleteAccount: () => void;
  appTheme: GroupTheme;
  onThemeChange: (theme: GroupTheme) => void;
}

const THEMES: { id: GroupTheme; label: string; color: string }[] = [
    { id: 'blue', label: 'Azul Clássico', color: 'bg-blue-500' },
    { id: 'green', label: 'Verde Natureza', color: 'bg-emerald-500' },
    { id: 'black', label: 'Dark OLED', color: 'bg-zinc-900' },
    { id: 'orange', label: 'Laranja Solar', color: 'bg-orange-500' }
];

const SettingsPage: React.FC<SettingsPageProps> = ({ currentUser, onNavigate, darkMode, toggleTheme, refreshUser, onLogout, onDeleteAccount, appTheme, onThemeChange }) => {
  const [view, setView] = useState<'main' | 'edit-profile' | 'payments' | 'appearance' | 'database'>('main');

  // States para edição de perfil
  const [firstName, setFirstName] = useState(currentUser.firstName);
  const [lastName, setLastName] = useState(currentUser.lastName);
  const [bio, setBio] = useState(currentUser.bio || '');
  const [credentials, setCredentials] = useState(currentUser.credentials || '');
  const [profilePicture, setProfilePicture] = useState(currentUser.profilePicture || '');
  const [email, setEmail] = useState(currentUser.email || '');
  const [phone, setPhone] = useState(currentUser.phone || '');

  const [birthDate, setBirthDate] = useState(() => {
    const d = new Date(currentUser.birthDate);
    return isNaN(d.getTime()) ? '' : d.toISOString().split('T')[0];
  });

  // Senha
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // Configuração Firebase
  const [fbApiKey, setFbApiKey] = useState('');
  const [fbProjectId, setFbProjectId] = useState('');
  const [fbAuthDomain, setFbAuthDomain] = useState('');
  const [fbStorageBucket, setFbStorageBucket] = useState('');
  const [fbAppId, setFbAppId] = useState('');

  const [isSaving, setIsSaving] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Hidden Admin Access
  const [devClicks, setDevClicks] = useState(0);
  const ADMIN_EMAIL = 'admin@cyber.com';

  useEffect(() => {
    // Carregar configs salvas ao abrir
    const savedConfig = localStorage.getItem('cyber_firebase_config');
    if (savedConfig) {
      const parsed = JSON.parse(savedConfig);
      setFbApiKey(parsed.apiKey || '');
      setFbProjectId(parsed.projectId || '');
      setFbAuthDomain(parsed.authDomain || '');
      setFbStorageBucket(parsed.storageBucket || '');
      setFbAppId(parsed.appId || '');
    }
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        alert('Por favor, selecione um arquivo de imagem.');
        return;
      }
      setIsUploading(true);
      try {
        const url = await uploadFile(file, 'profiles');
        setProfilePicture(url);
      } catch (err) {
        alert('Erro no upload da imagem.');
      } finally {
        setIsUploading(false);
      }
    }
  };

  const handleSaveProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isUploading) return;
    setIsSaving(true);

    try {
      if (newPassword) {
        if (newPassword.length < 6) {
          alert('A senha deve ter pelo menos 6 caracteres.');
          setIsSaving(false);
          return;
        }
        if (newPassword !== confirmPassword) {
          alert('As senhas não conferem.');
          setIsSaving(false);
          return;
        }
        await updateUserPassword(newPassword);
        setNewPassword('');
        setConfirmPassword('');
      }

      const updatedUser: User = { 
          ...currentUser, 
          firstName, 
          lastName, 
          email,
          phone,
          bio, 
          credentials, 
          profilePicture,
          birthDate: new Date(birthDate).getTime()
      };

      // Persistência Imediata
      await updateUser(updatedUser);
      await refreshUser(); // Atualiza o estado global no App.tsx

      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar perfil.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveFirebase = (e: React.FormEvent) => {
    e.preventDefault();
    const config = {
      apiKey: fbApiKey.trim(),
      projectId: fbProjectId.trim(),
      authDomain: fbAuthDomain.trim(),
      storageBucket: fbStorageBucket.trim(),
      appId: fbAppId.trim()
    };

    localStorage.setItem('cyber_firebase_config', JSON.stringify(config));
    alert('Configuração salva! O aplicativo será recarregado para aplicar as mudanças.');
    window.location.reload();
  };

  const handleClearFirebase = () => {
    if(confirm("Deseja remover as configurações do Firebase e voltar ao modo Offline?")) {
      localStorage.removeItem('cyber_firebase_config');
      window.location.reload();
    }
  };

  const handleDeletePress = async () => {
    if (window.confirm('ALERTA DE SEGURANÇA: Esta ação excluirá permanentemente sua conta, dados, posts e carteira. Esta ação é irreversível. Deseja continuar?')) {
        try {
            setIsSaving(true); // Bloqueia UI
            await deleteUser(currentUser.id);
            // Limpa sessão local explicitamente
            saveCurrentUser(null);
            onDeleteAccount(); // Chama o logout/reset do pai
        } catch (error) {
            console.error("Erro ao deletar conta:", error);
            alert("Não foi possível excluir a conta no momento. Tente novamente.");
            setIsSaving(false);
        }
    }
  };

  const handleVersionClick = async () => {
    const newCount = devClicks + 1;
    setDevClicks(newCount);

    if (newCount === 7) {
        if (currentUser.email.toLowerCase() === ADMIN_EMAIL) {
            const newStatus = !currentUser.isAdmin;
            await updateUser({ ...currentUser, isAdmin: newStatus });
            refreshUser();
            alert(`SISTEMA ROOT: Privilégios de Superusuário ${newStatus ? 'ATIVADOS' : 'DESATIVADOS'}.`);
        } else {
            alert(`⛔ ACESSO NEGADO\n\nConta não autorizada para Root.`);
        }
        setDevClicks(0);
    }
  };

  if (view === 'database') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
        <div className="flex items-center gap-6 mb-8">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-3xl font-black dark:text-white tracking-tighter">Conexão Firebase</h2>
        </div>

        <div className="bg-orange-50 dark:bg-orange-900/10 border border-orange-200 dark:border-orange-500/20 p-6 rounded-3xl mb-8">
           <p className="text-orange-800 dark:text-orange-400 text-xs font-bold leading-relaxed">
             Insira as chaves do seu projeto Firebase aqui para ativar Login Real, Chat em Tempo Real e Banco de Dados na Nuvem. Deixe em branco para usar o modo Demonstração (Offline).
           </p>
        </div>

        <form onSubmit={handleSaveFirebase} className="space-y-6 bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">API Key (obrigatório)</label>
              <input type="text" value={fbApiKey} onChange={e => setFbApiKey(e.target.value)} placeholder="AIzaSy..." className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Project ID (obrigatório)</label>
              <input type="text" value={fbProjectId} onChange={e => setFbProjectId(e.target.value)} placeholder="meu-projeto-id" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Auth Domain</label>
              <input type="text" value={fbAuthDomain} onChange={e => setFbAuthDomain(e.target.value)} placeholder="meu-projeto.firebaseapp.com" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">Storage Bucket</label>
              <input type="text" value={fbStorageBucket} onChange={e => setFbStorageBucket(e.target.value)} placeholder="meu-projeto.appspot.com" className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="space-y-2">
              <label className="text-[10px] font-black text-gray-400 uppercase ml-2">App ID</label>
              <input type="text" value={fbAppId} onChange={e => setFbAppId(e.target.value)} placeholder="1:123456789:web:..." className="w-full p-4 bg-gray-50 dark:bg-white/5 rounded-2xl dark:text-white outline-none border-2 border-transparent focus:border-brand font-mono text-xs" />
           </div>

           <div className="pt-4 flex flex-col gap-3">
              <button type="submit" className="w-full py-5 bg-green-600 hover:bg-green-700 text-white rounded-2xl font-black uppercase text-xs shadow-xl active:scale-95 transition-all">
                 Salvar e Conectar
              </button>
              <button type="button" onClick={handleClearFirebase} className="w-full py-5 bg-gray-100 dark:bg-white/5 text-gray-500 hover:text-red-500 rounded-2xl font-black uppercase text-xs transition-all">
                 Resetar para Modo Offline
              </button>
           </div>
        </form>
      </div>
    );
  }

  if (view === 'appearance') {
    return (
        <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-2xl animate-fade-in">
          <div className="flex items-center gap-6 mb-10">
            <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
            <h2 className="text-4xl font-black dark:text-white tracking-tighter">Estilo</h2>
          </div>

          <div className="space-y-10">
            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6">Tema de Cores</p>
                <div className="grid grid-cols-2 gap-4">
                    {THEMES.map(theme => (
                        <button 
                          key={theme.id}
                          onClick={() => onThemeChange(theme.id)}
                          className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-4 ${appTheme === theme.id ? 'border-brand bg-brand/5 shadow-xl' : 'border-gray-50 dark:border-white/5 hover:border-gray-200'}`}
                        >
                           <div className={`w-14 h-14 rounded-2xl ${theme.color} shadow-lg flex items-center justify-center`}>
                              {appTheme === theme.id && <CheckIcon className="h-7 w-7 text-white" />}
                           </div>
                           <span className={`text-xs font-black uppercase ${appTheme === theme.id ? 'text-brand' : 'text-gray-400'}`}>{theme.label}</span>
                        </button>
                    ))}
                </div>
            </div>

            <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10 flex items-center justify-between">
                <div>
                    <p className="font-black text-sm dark:text-white uppercase tracking-tighter">Modo Escuro</p>
                    <p className="text-xs text-gray-400 font-bold">Inverter cores do sistema</p>
                </div>
                <button onClick={toggleTheme} className={`w-14 h-7 rounded-full transition-all relative ${darkMode ? 'bg-brand' : 'bg-gray-200'}`}>
                    <div className={`absolute top-1 w-5 h-5 bg-white rounded-full transition-all ${darkMode ? 'right-1' : 'left-1'}`}></div>
                </button>
            </div>
          </div>
        </div>
    );
  }

  if (view === 'edit-profile') {
    return (
      <div className="container mx-auto p-4 md:p-8 pt-24 pb-20 max-w-3xl animate-fade-in">
        <div className="flex items-center gap-6 mb-10">
          <button onClick={() => setView('main')} className="p-3 bg-white dark:bg-darkcard rounded-2xl shadow-md text-gray-400 hover:text-brand transition-all"><ArrowLeftIcon className="h-6 w-6" /></button>
          <h2 className="text-4xl font-black dark:text-white tracking-tighter">Dados de Inscrição</h2>
        </div>

        {saveSuccess && (
          <div className="mb-6 p-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-500/30 rounded-2xl flex items-center gap-3 animate-fade-in">
             <CheckIcon className="h-5 w-5 text-green-600" />
             <p className="text-xs font-black text-green-700 dark:text-green-400 uppercase tracking-widest">Perfil atualizado!</p>
          </div>
        )}

        <form onSubmit={handleSaveProfile} className="space-y-8">
           <div className="bg-white dark:bg-darkcard p-8 rounded-[3rem] shadow-xl border dark:border-white/10">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-6 ml-1">Identidade Visual</p>
              <div className="flex flex-col items-center gap-6">
                 <div 
                   onClick={() => fileInputRef.current?.click()} 
                   className="relative group cursor-pointer"
                 >
                    <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden border-4 border-white dark:border-darkcard shadow-2xl transition-transform group-hover:scale-105 relative">
                       <img src={profilePicture || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" alt="Profile" />
                       {isUploading && (
                         <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                           <div className="w-8 h-8 border-4 border-white border-t-transparent animate-spin rounded-full"></div>
                         </div>
                       )}
                       <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                          <CameraIcon className="h-10 w-10 text-white" />
                       </div>
                    </div>
                    <div className="absolute -bottom-2 -right-2 bg-brand text-white p-2 rounded-xl shadow-lg border-2 border-white dark:border-darkcard">
                       <PaintBrushIcon className="h-4 w-4" />
                    </div>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      className="hidden" 
                      accept="image/*" 
