export const toggleFollowUser = async (currentUserId: string, targetId: string) => {
    const currentUser = await findUserById(currentUserId);
    const targetUser = await findUserById(targetId);

    if(currentUser && targetUser) {
        let following = currentUser.followedUsers || [];
        let followers = targetUser.followers || [];

        if(following.includes(targetId)) {
            following = following.filter(id => id !== targetId);
            followers = followers.filter(id => id !== currentUserId);
        } else {
            following.push(targetId);
            followers.push(currentUserId);
        }

        await updateDoc(doc(db, "users", currentUserId), { followedUsers: following });
        await updateDoc(doc(db, "users", targetId), { followers: followers });
    }
};

export const addProductRating = async (saleId: string, rating: number, comment: string) => {
    const saleRef = doc(db, "affiliate_sales", saleId);
    const saleSnap = await getDoc(saleRef);
    if(saleSnap.exists()) {
        const sale = saleSnap.data() as AffiliateSale;
        if(sale.isRated) return;

        const productRef = doc(db, "products", sale.productId);
        const productSnap = await getDoc(productRef);
        if(productSnap.exists()) {
            const product = productSnap.data() as Product;
            const newRating: ProductRating = {
                id: generateUUID(),
                saleId,
                userId: sale.buyerId,
                rating,
                comment,
                timestamp: Date.now()
            };
            const ratings = product.ratings || [];
            ratings.push(sanitizePayload(newRating));
            const avg = ratings.reduce((acc: number, r: ProductRating) => acc + r.rating, 0) / ratings.length;

            await updateDoc(productRef, { ratings: sanitizePayload(ratings), ratingCount: ratings.length, averageRating: avg });
            await updateDoc(saleRef, { isRated: true });
        }
    }
};

