        const chat = chatSnap.data() as ChatConversation;
        const newMessages = chat.messages.map(m => m.id === messageId ? { ...m, text: newText, isEdited: true } : m);
        await updateDoc(chatRef, { messages: sanitizePayload(newMessages) });
