export const leaveGroup = async (chatId: string, userId: string) => { 
    const chatRef = doc(db, "chats", chatId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        const newParticipants = chat.participants.filter(p => p !== userId);
        await updateDoc(chatRef, { participants: newParticipants });
    }
};
