export const joinGroup = async (groupId: string, userId: string) => { 
    const chatRef = doc(db, "chats", groupId);
    const chatSnap = await getDoc(chatRef);
    if(chatSnap.exists()) {
        const chat = chatSnap.data() as ChatConversation;
        if(!chat.participants.includes(userId)) {
            await updateDoc(chatRef, { participants: [...chat.participants, userId] });
        }
    }
};
export const startPrivateChat = async (userId1: string, userId2: string) => { 
    // Check if exists
    const chats = await getChats();
    const existing = chats.find(c => c.type === ChatType.PRIVATE && c.participants.includes(userId1) && c.participants.includes(userId2));
    if(existing) return existing.id;

    const newChat: ChatConversation = {
        id: generateUUID(),
        type: ChatType.PRIVATE,
        participants: [userId1, userId2],
        messages: []
    };
    await setDoc(doc(db, "chats", newChat.id), sanitizePayload(newChat));
    return newChat.id;
};
