export const processUserUpgrade = async (userId: string, user: User, docFile: File, credentials: string) => {
    // 1. Upload Doc
    const docUrl = await uploadFile(docFile, 'docs');

    // 2. Update User
    const updatedUser = { 
        ...user, 
        userType: UserType.CREATOR, 
        credentials, 
        verificationFileUrl: docUrl 
    };
    await updateUser(updatedUser);

    // 3. Create Store
    const storeId = generateUUID();
    await setDoc(doc(db, "stores", storeId), sanitizePayload({
        id: storeId,
        professorId: userId,
        name: `Loja de ${user.firstName}`,
        description: 'Bem-vindo',
        productIds: []
    }));

    await updateDoc(doc(db, "users", userId), { storeId });
};
